window.CY = {"meta":{"city":"金門縣","slug":"kinmen-county","updated":"2026-11-01","designer":"Allan Lo","designerSite":"https://www.123hi.org","designed":"2026年11月","ai":"Claude Opus 5.5"},"config":{"slug":"kinmen-county","name":"金門縣","short":"金門","center":[24.44,118.34],"zoom":12,"minZoom":8,"detailZoom":16,"timeZoom":12,"categories":["國定古蹟","縣定古蹟","歷史建築","紀念建築","聚落建築群","文化景觀"],"towns":["金城鎮","金寧鄉","金湖鎮","金沙鎮","烈嶼鄉","烏坵鄉"],"ubikeAreas":[],"wiki":{"title":"維基百科「金門縣文化資產」","url":"https://zh.wikipedia.org/zh-tw/%E9%87%91%E9%96%80%E7%B8%A3%E6%96%87%E5%8C%96%E8%B3%87%E7%94%A2"},"introTitle":"歡迎來到金門","quizTitle":"浯島文資通","eraLabels":{"dutch":"明代以前","zheng":"明鄭時期","qing":"清代（–1911）","japan":"民國初年與日軍占領（1912–1945）","postwar":"戰後（1945–1980）","modern":"1981 年以後"},"board":{"name":"浯島擲骰大冒險","start":"出發：金城車站","train":"金門大橋","trainText":"開上金門大橋，前進 3 格！","food":"廣東粥補給站"},"planner":{"speeds":{"car":30,"scooter":28,"bike":13,"walk":4.5,"ubike":13},"hints":{"car":"金門景點分散在各村落，但島不大，從金城開到金沙約 30 分鐘；有金門大橋可以直接開車到烈嶼（小金門）。村落巷弄窄，車停在聚落外圍再步行。每站已預留約 8 分鐘停車時間。","scooter":"金門最常見的玩法是租機車，聚落之間騎 10 到 20 分鐘就到；也可以騎上金門大橋到烈嶼。冬天東北季風強，騎車要注意保暖與側風。","bike":"金門地勢平緩，金城、水頭、珠山、古寧頭一帶適合騎單車；單段超過 12 公里（例如金城到金沙）會建議改開車或搭公車。","walk":"金城的後浦老街、模範街、總兵署、邱良功母節孝坊彼此很近，水頭、珠山、瓊林聚落裡也適合步行；單段超過 3 公里會建議改搭公車或計程車。","ubike":"金門縣目前沒有 YouBike 2.0 站點，建議租機車、開車，或搭金門縣公車。"},"defaultMode":"scooter","lunchNote":"金門在地小吃：廣東粥、蚵仔麵線、石蚵料理、燒餅、炒泡麵，伴手禮可帶貢糖與麵線","eveningNote":"晚上可以逛金城的後浦老街與模範街，或到山外市區吃宵夜；部分店家較早打烊，請以現場為準","walkMaxKm":3,"bikeMaxKm":12,"ubikeStationMaxKm":1.2,"farKm":60,"islands":[{"name":"大膽島","bbox":[24.355,118.12,24.4,118.185],"port":[24.38946,118.16331],"portName":"大膽島","mainPort":[24.42679,118.26524],"back":"烈嶼九宮碼頭","seaMin":60,"note":"大膽島要事先向金門縣政府預約登島，從烈嶼九宮碼頭搭船、團進團出，登島時段配合潮汐，島上部分區域仍屬軍事管制。開放日、申請期限與船班請以金門縣政府公告為準。","lunchNote":"大膽島上沒有一般餐廳，請在烈嶼或金門本島用餐"}],"noVisit":{"jinhu-dongdingdaodengta":"東椗島位在金門南方外海，屬軍事管制區，一般民眾無法登島，只能從網站認識這座燈塔。","jinhu-beidingdaodengta":"北椗島位在金門東方外海，沒有一般交通船，一般民眾無法自由登島。","wuqiu-dengta":"烏坵在金門東北方約 130 公里的海上，仍屬軍事管制區，燈塔不對外開放，一般民眾無法前往。","jinhu-caipanlongmu":"蔡攀龍墓位在軍事管制範圍內，一般民眾無法自由進入。","jinhu-jinfangbuganxunban":"原金防部幹訓班暨士校營區仍由國軍使用，一般民眾無法進入，請勿靠近或拍攝。"}},"eras":{"dutch":{"layers":[],"paper":true,"end":1645,"note":"中研院臺灣百年歷史地圖的老地圖都沒有涵蓋金門，這個時期改用古紙風格底圖，標示的是推定位置。"},"zheng":{"layers":[],"paper":true,"end":1683,"note":"明鄭時期沒有實測地圖，底圖改成古紙風格，標示的是推定位置。"},"qing":{"layers":[],"paper":true,"end":1911,"note":"清代沒有金門的實測地圖可以疊圖，1904 年的臺灣堡圖也不包含金門，這裡改用古紙風格底圖。"},"japan":{"layers":[],"paper":true,"end":1945,"note":"金門在 1895 到 1945 年間不屬日本統治，當時臺灣總督府繪製的地形圖都沒有畫到金門，這裡改用古紙風格底圖。"},"early-roc":{"layers":[],"paper":true,"end":1958,"note":"戰地前線時期的金門地圖多屬軍事機密，中研院的老地圖沒有收錄，這裡改用古紙風格底圖。"},"roc60":{"layers":[],"paper":true,"end":1992,"note":"戰地政務時期的金門地圖同樣沒有公開的實測圖層，這裡改用古紙風格底圖。"},"now":{"layers":["photo"],"end":2026,"opacity":0,"note":"今天的金門縣。可疊上國土測繪中心的正射影像，看看聚落、坑道口與海岸。"}}},"categories":["國定古蹟","縣定古蹟","歷史建築","紀念建築","聚落建築群","文化景觀"],"sites":[{"id":"jincheng-wentaibaota","name":"文臺寶塔","short":"文臺寶塔","category":"國定古蹟","level":"國定古蹟","town":"金城鎮","types":["其他設施"],"lat":24.39877,"lng":118.306013,"address":"金門縣金城鎮古城里金門城南磐山南端","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000093","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-15/454408d2-2ba2-4716-a15f-a37022ddc8fd/文台寶塔.jpg","year":1388,"yearText":"1388年（明洪武21年）","era":"dutch","themes":["海防燈塔","城池衛所","摩崖石刻"],"yearUnknown":false,"summary":"臺澎金馬僅存、保有明代原貌的石塔","intro":"文臺寶塔位於金城鎮古城里舊金門城南磐山南端。明洪武20年（1387）江夏侯周德興奉命至福建督建衛所，在金門設守禦千戶所、築金門城，取「固若金湯，雄鎮海門」之意，這就是「金門」地名的由來。次年他以在地花崗石興建三座石塔作為航運指引，另兩座分別在民國27年與50年毀損，文臺寶塔是唯一保有明代初建原貌的一座，也是臺澎金馬僅存的明代石塔。塔身六角五層，以一丁一順方式砌築，北側第三層刻有「奎星聳照」與魁星踢斗浮雕。","highlights":["北側第三層「奎星聳照」四字與魁星踢斗浮雕","基石上明代百戶陳煇題的「文臺寶塔」「湖海清平」","六角五層、逐層縮小的花崗石塔身與葫蘆寶頂"],"funFact":"三座明代石塔中，只有文臺寶塔撐過天災、地震、戰火與民國50年的爆破拆除，至今仍是初建原貌。","photoSpot":"在塔下低角度仰拍，帶入基石題刻","visitMin":20,"openNote":"位於金城鎮古城里南磐山，開放空間、全天可參觀；鄰近虛江嘯臥石刻群，可一併走訪。可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"A","text":"站在南磐山上吹海風，阿拉蕾，你眼前這座六角石塔，已經在這裡站了600多年囉。"},{"who":"R","text":"600多年？Allan，它比你家巷口那間老雜貨店還要老嗎？"},{"who":"A","text":"老太多了！明洪武20年周德興來金門築城，隔年用在地花崗石蓋了三座塔，給船隻當指引。"},{"who":"R","text":"三座塔？那另外兩座跑去哪裡了？"},{"who":"A","text":"一座在民國27年、一座在民國50年毀損，後來雖然重建，只有文臺寶塔還是明代原裝的。"},{"who":"R","text":"原裝耶，那它根本是金門的骨董級導航系統！"},{"who":"A","text":"說得好，而且它還兼差保佑考試。北側第三層刻著「奎星聳照」，還有魁星踢斗的浮雕。"},{"who":"R","text":"考生快來拜！那下面大石頭上的字又是誰寫的？"},{"who":"A","text":"「文臺寶塔」和「湖海清平」是明萬曆年間百戶陳煇題的。等一下繞到北側，找找那位踢斗的魁星吧！"}],"clues":["我和兩位兄弟同年誕生，如今只剩我保有原貌","我身上刻著「奎星聳照」，還有魁星踢斗的浮雕","我是金門城南磐山上的六角五層明代石塔"],"quiz":[{"q":"文臺寶塔最初興建的主要用途是？","options":["祭祀媽祖","航運指引","儲存軍糧","瞭望烽火"],"answer":1,"explain":"周德興建三座石塔，作為船隻的航運指引。"},{"q":"塔身北側第三層刻的是哪四個字？","options":["湖海清平","國之金湯","奎星聳照","碧海丹心"],"answer":2,"explain":"北側第三層刻「奎星聳照」，並有魁星踢斗浮雕。"}],"images":[{"file":"文臺寶塔(3).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/03/%E6%96%87%E8%87%BA%E5%AF%B6%E5%A1%94%283%29.jpg/960px-%E6%96%87%E8%87%BA%E5%AF%B6%E5%A1%94%283%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%96%87%E8%87%BA%E5%AF%B6%E5%A1%94(3).jpg","artist":"寺人孟子","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-wentaibaota-0.webp","small":"img/jincheng-wentaibaota-0-s.webp"}]},{"id":"jinsha-chenzhenmu","name":"陳禎墓","short":"陳禎墓","category":"國定古蹟","level":"國定古蹟","town":"金沙鎮","types":["墓葬"],"lat":24.481466,"lng":118.392856,"address":"金門縣金沙鎮埔山村黃龍山上","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000087","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1020/photo/陳禎墓1.JPG","year":1526,"yearText":"1526年（明嘉靖5年）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"臺澎金馬規制最完整的明代五品官墓","intro":"陳禎墓位於金沙鎮浦山村黃龍山上，是國定古蹟。陳禎為浯陽陳氏第十八世，明正德10年（1515）歲貢，曾任廣東長樂縣訓導；次子陳健於嘉靖5年（1526）登進士，陳禎同年去世，因子而貴獲贈刑部員外郎。墓坐落於被稱為「仙人覆掌」的風水吉地，居高臨下、視野遼闊。墓以花崗石為主，前有四柱廡殿頂石墓亭，墓碑立於亭中；墓埕有石羊、石馬、望柱各一對，符合明代五品官的造墳規制，是臺澎金馬規制最完整的明代五品官墓，與陳健墓並稱金門明代墓式的代表。","highlights":["墓埕成對的石羊與側首的石馬","廡殿頂四柱石墓亭與起翹的翼角","三伸手脊端的回眸石獅，一張口一閉口"],"funFact":"陳禎的兒子陳健考上進士那年，陳禎就去世了，朝廷仍「父以子貴」追贈他官銜。","photoSpot":"在墓埕拍石馬、石羊與墓亭同框","visitMin":20,"openNote":"位於金沙鎮浦山村黃龍山上，開放空間、全時段可參觀；墓塋仍有祭祀，請保持肅靜，勿攀爬石像與墓體。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這座墓前面怎麼有石羊和石馬？是古代的寵物園嗎？"},{"who":"A","text":"哈，這可不是寵物，是身分證明。石羊、石馬、望柱各一對，正好符合明代五品官墓的規格。"},{"who":"R","text":"原來是官階配件！那墓主是幾品官？"},{"who":"A","text":"墓主陳禎當過廣東長樂縣訓導，因為兒子陳健考上進士，朝廷追贈他刑部員外郎，是從五品。"},{"who":"R","text":"兒子考得好，爸爸也跟著升官，這是最強的孝順吧！"},{"who":"A","text":"可惜陳健中進士那年陳禎就過世了。墓前還有一座四根石柱撐起的石墓亭，跟陳健墓是父子款。"},{"who":"R","text":"父子款古墓，好特別！那還有什麼小細節？"},{"who":"A","text":"護牆外側最外面那組伸手石牆，末端各有一隻回頭的石獅，一隻張嘴一隻閉嘴。到現場仔細比對看看吧！"}],"clues":["我的墓埕有石羊、石馬和望柱各一對","我兒子中進士那年我過世，朝廷追贈刑部員外郎","我在黃龍山上，是陳健父親的明代墓"],"quiz":[{"q":"陳禎墓的墓埕有哪些成對的石像？","options":["石獅與石象","石虎與石龜","石羊與石馬","石麒麟與石鶴"],"answer":2,"explain":"墓埕有石羊、石馬、望柱各一對，符合五品官規制。"},{"q":"陳禎墓所在的風水吉地稱為？","options":["仙人覆掌","猛虎下山","金龜出海","雙龍搶珠"],"answer":0,"explain":"陳禎墓坐落於金門風水吉地「仙人覆掌」穴。"}],"images":[]},{"id":"jincheng-xujiangxiaowoshike","name":"虛江嘯臥石刻群","short":"虛江嘯臥石刻","category":"國定古蹟","level":"國定古蹟","town":"金城鎮","types":["碑碣"],"lat":24.398418,"lng":118.305675,"address":"金門縣金城鎮古城里金門城南磐山南端","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-06-23/037935bb-9982-4981-80fc-ec21d0c720c5/虛江嘯臥碣群1.jpg","year":1535,"yearText":"約1535–1539年（明嘉靖14至18年）首刻","era":"dutch","themes":["摩崖石刻","城池衛所"],"yearUnknown":false,"summary":"俞大猷題字起頭，明清民國題刻群聚","intro":"虛江嘯臥石刻群位於金城鎮古城里南磐山頂，鄰近文臺寶塔。明嘉靖14年（1535）抗倭名將俞大猷（號虛江）派守金門千戶所，閒暇常登臨此地，在海濱摩崖自題「虛江嘯臥」；他後來與戚繼光並稱「俞龍戚虎」。嘉靖42年（1563）門人楊弘舉任金門所副千戶，在旁築嘯臥亭並作記，原亭已毀，今亭為民國89年重建。這裡是昔日金門八景之一「嘯臥棲雲」，歷代文人留下12方石刻，分布在5處山壁巨石上，從明代一路到民國19年，官方評為臺澎金馬碑碣數量與密度最高之處。","highlights":["俞大猷親題的「虛江嘯臥」摩崖","楊弘舉題「汪洋滄海，波浪怒來」的豪邁贊語","民國89年重建的嘯臥亭"],"funFact":"12方石刻中，「名賢翫跡」和何喬遠等人的遊嘯臥亭詩兩方，位在金門舊酒廠的範圍內。","photoSpot":"在嘯臥亭旁拍石刻與遠方海面","visitMin":30,"openNote":"位於金城鎮古城里南磐山。除「名賢翫跡」與何喬遠等人遊嘯臥亭詩位在金門舊酒廠內，其餘石刻在開放空間，全天可參觀。可與文臺寶塔一起走訪，開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，想像一下，將近500年前，有位將軍一有空就跑來這塊大石頭上吹海風、放聲長嘯。"},{"who":"R","text":"長嘯？是像山上的猴子那樣大叫嗎？"},{"who":"A","text":"文雅一點啦！他是抗倭名將俞大猷，號虛江，守金門時在這裡刻下「虛江嘯臥」四個字。"},{"who":"R","text":"原來是將軍的簽名打卡點！後來還有別人跟著刻嗎？"},{"who":"A","text":"有喔，他的門人楊弘舉在旁邊蓋了嘯臥亭，還刻下「汪洋滄海，波浪怒來，我有片物，揮之使迴」。"},{"who":"R","text":"哇，一揮手就把海浪趕回去，好像在拍武俠片！"},{"who":"A","text":"這裡是金門八景之一，明、清到民國總共留下12方石刻，是臺澎金馬碑碣密度最高的地方。"},{"who":"R","text":"12方？那我們要像尋寶一樣一塊一塊找了！"},{"who":"A","text":"沒錯，今天的任務就是找到俞大猷親筆的「虛江嘯臥」，再拍一張你自己的嘯臥姿勢！"}],"clues":["我和「俞龍戚虎」裡的那條龍有關","我是昔日金門八景「嘯臥棲雲」的所在","南磐山頂12方摩崖題刻，起頭的是一位守金門的千戶"],"quiz":[{"q":"俞大猷與哪位將領並稱「俞龍戚虎」？","options":["鄭成功","戚繼光","施琅","邱良功"],"answer":1,"explain":"俞大猷與戚繼光同為抗倭名將，並稱俞龍戚虎。"},{"q":"嘯臥亭最早由誰興建？","options":["俞大猷","周德興","楊弘舉","陳煇"],"answer":2,"explain":"俞大猷門人楊弘舉於明嘉靖42年築嘯臥亭。"}],"images":[]},{"id":"jinsha-chenjianmu","name":"陳健墓","short":"陳健墓","category":"國定古蹟","level":"國定古蹟","town":"金沙鎮","types":["墓葬"],"lat":24.484838,"lng":118.433044,"address":"金門縣金沙鎮東珩村外南郊","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000001","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/1019/photo/陳健墓1.JPG","year":1561,"yearText":"1561年（明嘉靖40年）陳健辭世後興建","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"明世宗特准興建的進士衣冠塚","intro":"陳健墓位於金沙鎮東珩聚落外南郊，是國定古蹟。陳健（1491–1561）為陽翟陳氏第十九世，明嘉靖5年（1526）登進士，歷任刑部主事及南安、南寧等地知府，進階正四品中憲大夫，為官剛直。辭官後修築同安滄江壩與石道，並重建陳氏宗祠、續修族譜。他逝世後葬在同安，東珩這座是衣冠塚，傳為明世宗特頒聖旨准許興建。墓塋呈ㄇ字形配置，墓碑與歇山重檐石墓亭獨立於護牆前，是全墓制高點；臺澎金馬現存明墓中，這種形式只見於金門三座浯陽陳氏墓。","highlights":["四根石柱撐起的歇山重檐石墓亭","墓亭中央無字無飾的狹長花崗石碑","墓塋左側展示的舊聖旨碑與墓坊構件"],"funFact":"2016年莫蘭蒂颱風吹落新建墓坊頂端的聖旨碑，2018年換上新碑，舊構件改放墓旁展示。","photoSpot":"從墓埕門柱處拍墓亭與層層曲手","visitMin":20,"openNote":"位於金沙鎮東珩聚落外南郊，開放空間、全天可參觀，宗親會定期祭掃；請保持肅靜，勿攀爬墓體。鄰近陽翟聚落，開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，你知道什麼叫衣冠塚嗎？就是墓裡放的不是本人，而是他的衣服和帽子。"},{"who":"R","text":"只放衣服？Allan，那陳健本人葬在哪裡呀？"},{"who":"A","text":"他晚年住在同安，過世後葬在那裡。傳說他的進士衣冠留在金門，明世宗特別下聖旨，准許在家鄉建衣冠塚。"},{"who":"R","text":"皇帝親自批准，這套衣服的待遇也太好了！陳健是什麼大人物？"},{"who":"A","text":"他是嘉靖5年的進士，當過三地知府，升到正四品，還在同安修水壩、鋪石道，造福鄉里。"},{"who":"R","text":"文官兼工程師，好斜槓！那這座墓有什麼特別？"},{"who":"A","text":"墓碑和石墓亭獨立站在護牆前面，墓亭是歇山重檐屋頂。臺澎金馬的明墓裡，這種形式只在金門找得到三座。"},{"who":"R","text":"限量款古墓！那旁邊那堆石頭零件是什麼？"},{"who":"A","text":"那是颱風吹落的舊聖旨碑和老墓坊構件。到現場繞到墓的左側找找它們，記得輕聲慢步、別攀爬喔。"}],"clues":["我裡面放的是衣冠，主人其實葬在同安","颱風吹落我的聖旨碑，舊構件就放在我身旁展示","我在東珩村外，主人是嘉靖5年進士、南寧知府"],"quiz":[{"q":"東珩這座墓為什麼稱為衣冠塚？","options":["墓主遺體葬在同安","墓主沒有後代","墓主遺體佚失","墓主出家為僧"],"answer":0,"explain":"陳健葬於同安，金門東珩所存為其衣冠塚。"},{"q":"2016年哪個颱風吹落了墓坊上的聖旨碑？","options":["尼伯特颱風","丹恩颱風","莫蘭蒂颱風","梅姬颱風"],"answer":2,"explain":"105年9月莫蘭蒂颱風期間，墓坊聖旨碑斷裂掉落。"}],"images":[]},{"id":"jincheng-shuitouhuangshiyou","name":"水頭黃氏酉堂別業","short":"黃氏酉堂別業","category":"國定古蹟","level":"國定古蹟","town":"金城鎮","types":["宅第"],"lat":24.410643,"lng":118.298142,"address":"金門縣金城鎮金水村前水頭55號","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000008","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/843/photo/水頭黃氏酉堂別業1.JPG","year":1765,"yearText":"1765年（清乾隆30年）","era":"qing","themes":["閩南古厝","教育書院"],"yearUnknown":false,"summary":"金門唯一有日月池與曲橋的書院宅第","intro":"水頭黃氏酉堂別業位於金城鎮金水村前水頭聚落，由水頭富商黃俊（字伯癸，人稱「酉堂百萬祖」）於清乾隆30年（1765）興建。這年是乙酉年，他的妻子蔡氏也在這年過世，因此取名「酉堂」。黃俊晚年把這裡作為頤養與督促子弟讀書的地方，禮聘外地教席設帳講課。宅院主軸為雙落大厝，前落帶四柱亭，左側另有書院空間與花廳；牆外池塘分為一圓一弦的日月池，上架三塊石板並排的曲橋。官方說明它是金門唯一曾具池沼曲橋的書院宅第，目前由黃氏後裔居住。","highlights":["一圓一弦的日月池，取讀書人「泮水」之意","三塊花崗石板並排鋪成的斜向曲橋","入口牆門上方的「酉堂」橫匾"],"funFact":"有人傳說黃俊發跡和海盜蔡牽有關，但黃俊卒於乾隆年間，蔡牽活躍於嘉慶年間，時間根本對不上。","photoSpot":"在池畔拍曲橋與「酉堂」門額","visitMin":15,"openNote":"位於金城鎮金水村前水頭聚落，屬金門國家公園範圍。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至水頭一帶，或開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝前面怎麼有兩個池塘，還一個圓圓、一個彎彎的？"},{"who":"A","text":"好眼力！這叫日月池，一圓像太陽、一弦像月亮，取的是讀書人「泮水」的意思。"},{"who":"R","text":"讀書人？這裡不是黃家人住的地方嗎？"},{"who":"A","text":"是住家也是學堂。清乾隆30年富商黃俊蓋了這裡，一邊養老，一邊請外地老師來教黃家子弟。"},{"who":"R","text":"為什麼要請外地老師？自己家族的人不能教嗎？"},{"who":"A","text":"他怕族人教書礙於親情不好嚴格，乾脆外聘。跟我小時候一樣，老爸教我寫功課，最後都變成吵架大會。"},{"who":"R","text":"哈哈，難怪！那名字為什麼叫酉堂？"},{"who":"A","text":"那年是乙酉年，他的老伴蔡氏也在這年過世，算是雙重紀念。現在還有後代住在裡面，我們在外面看就好。"},{"who":"R","text":"收到！那我去池邊數數看，那座曲橋是用幾塊石板並排鋪成的！"}],"clues":["我的主人被後人稱為「百萬祖」","我的名字同時紀念興建那年與老伴離世那年","前水頭的書院宅第，門前有日月池和石板曲橋"],"quiz":[{"q":"酉堂門前的池塘被稱為什麼？","options":["鴛鴦池","蓮花池","半月池","日月池"],"answer":3,"explain":"池塘分為一圓一弦，稱為日月池。"},{"q":"黃俊為什麼從外地聘請教席？","options":["外地老師比較便宜","怕族人執教礙於親情","金門沒有讀書人","官府規定必須外聘"],"answer":1,"explain":"怕族人執教囿於親情不便，教席都從外地請來。"}],"images":[]},{"id":"jincheng-zhuzici","name":"金門朱子祠","short":"金門朱子祠","category":"國定古蹟","level":"國定古蹟","town":"金城鎮","types":["書院"],"lat":24.434501,"lng":118.317379,"address":"金門縣金城鎮珠埔北路35號","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20210526000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-15/c41ac6e2-0d98-4e56-983b-492776f17e92/金門朱子祠.png","year":1780,"yearText":"1780年（清乾隆45年）創設浯江書院","era":"qing","themes":["教育書院","宗教信仰"],"yearUnknown":false,"summary":"金門四大書院唯一留存，祭祀朱熹","intro":"金門朱子祠位於金城鎮珠浦北路的浯江書院內，紀念南宋理學家朱熹。相傳朱子任同安縣主簿時曾過化金門，創設燕南書院，鄉人感念而設祠奉祀。金門舊有燕南、浯洲、金山、浯江四大書院，浯江書院是碩果僅存的一座。清乾隆45年（1780）原縣丞署改為浯江書院，次年因再設縣丞，士紳另就義學基址興建新書院，並把朱子像移入。現存朱子祠為三開間歇山重簷建築，四周有簷廊、前有月臺；書院內有清道光18年（1838）的「浯江書院膏火碑記」，大門上方懸有錢穆所題「朱子祠」匾額。","highlights":["三開間歇山重簷的朱子祠與前方月臺","錢穆題寫的「朱子祠」三字匾額","清道光18年的「浯江書院膏火碑記」"],"funFact":"祠內兩側設有供遊客拓印的石碑，可以親手拓一張朱子文辭留作紀念。","photoSpot":"從月臺前方拍重簷屋頂與匾額","visitMin":25,"openNote":"位於金城鎮珠浦北路浯江書院內，官方資料記載每日08:00至21:00開放。可從金城車站步行前往，鄰近清金門鎮總兵署與模範街。","dialogue":[{"who":"A","text":"考試前要拜誰？今天帶阿拉蕾來金城市區，拜見一位超級大咖的老師。"},{"who":"R","text":"我知道！是不是朱熹？就是寫四書章句集注的那位？"},{"who":"A","text":"答對加十分！相傳朱子當同安縣主簿時來過金門，還創設了燕南書院。"},{"who":"A","text":"不過我們站的是浯江書院喔。金門以前有四大書院，現在只剩浯江書院還在，朱子祠就在最後面。"},{"who":"R","text":"只剩一間，那它根本是書院界的最後倖存者！"},{"who":"A","text":"朱子祠是三開間歇山重簷建築，前面有月臺，以前是祭祀行禮的地方，旁邊還有石碑讓遊客拓印。"},{"who":"R","text":"可以拓印？那我要拓一張貼在書桌前面，保佑我考試順利！"},{"who":"A","text":"清乾隆45年創設，後來改成學校，民國15年還叫縣立浯江小學。看完我請你吃廣東粥補補腦。"},{"who":"R","text":"好耶！那我先去祠前的月臺，找找錢穆題的那塊匾額掛在哪裡！"}],"clues":["相傳我紀念的人曾在金門創設第一座書院","我在金門四大書院中唯一留存的那一座裡面","金城珠浦北路，歇山重簷的祠堂供奉南宋理學家"],"quiz":[{"q":"金門舊有四大書院，哪一座留存至今？","options":["燕南書院","浯洲書院","金山書院","浯江書院"],"answer":3,"explain":"四大書院中只有浯江書院碩果僅存。"},{"q":"書院大門上方的「朱子祠」匾額是誰題的？","options":["胡適","錢穆","于右任","張大千"],"answer":1,"explain":"匾額由漢學大師錢穆所題，是珍貴文物。"}],"images":[{"file":"Kinmen - Zhu Zi Ci - DSCF9441 (cropped).JPG","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Kinmen_-_Zhu_Zi_Ci_-_DSCF9441_%28cropped%29.JPG/960px-Kinmen_-_Zhu_Zi_Ci_-_DSCF9441_%28cropped%29.JPG","page":"https://commons.wikimedia.org/wiki/File:Kinmen_-_Zhu_Zi_Ci_-_DSCF9441_(cropped).JPG","artist":"User:Vmenkov","license":"CC BY-SA 3.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/3.0","local":"img/jincheng-zhuzici-0.webp","small":"img/jincheng-zhuzici-0-s.webp"}]},{"id":"jincheng-qiulianggongmujie","name":"邱良功母節孝坊","short":"邱良功母節孝坊","category":"國定古蹟","level":"國定古蹟","town":"金城鎮","types":["牌坊"],"lat":24.431385,"lng":118.318537,"address":"金門縣金城鎮東門里莒光路1段觀音亭邊","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000092","officialImg":"https://data.boch.gov.tw/old_upload/_upload/Assets_new/building/844/photo/邱良功母節孝坊1.jpg","year":1812,"yearText":"1812年（清嘉慶17年）","era":"qing","themes":["牌坊碑碣"],"yearUnknown":false,"summary":"臺澎金馬規模最大的明清石牌坊","intro":"邱良功母節孝坊位於金城鎮東門里莒光路一段觀音亭旁，清嘉慶17年（1812）建立，旌表浙江水師提督邱良功的母親許氏。許氏28歲喪夫，當時良功出生僅35日，她守節撫孤28年。邱良功因剿滅海盜蔡牽有功受封三等男爵，為金門清代官階最高的武將，事母至孝，為母奏請旌表建坊。牌坊為「四柱三間三層五檐樓」形制，總高9.48公尺，以泉州白石與青斗石雕成，官方稱為臺澎金馬明清牌坊之最。坊柱四幅楹聯由王得祿、阮元等人題贈，南側另有清光緒13年（1887）的示禁碑。","highlights":["五座出挑檐樓，頂層以鴟尾與火燄珠收頭","王得祿、阮元等名臣題贈的四幅楹聯","被地方供奉為「石獅仙姑」的彩繪石獅"],"funFact":"民國33年盟軍轟炸後浦東門，震落雀替和一隻石獅，石獅後來由匠師陳南山仿作補回。","photoSpot":"站在莒光路旁安全處拍牌坊全景","visitMin":15,"openNote":"位於金城鎮東門里莒光路一段、後浦東門市場旁的開放空間，全天可參觀。牌坊下常有汽機車通行，拍照請注意安全。可從金城車站步行前往。","dialogue":[{"who":"R","text":"Allan，這座石頭牌樓好高喔，下面還有機車鑽來鑽去！"},{"who":"A","text":"這是邱良功母節孝坊，高度將近9公尺半，官方說是臺澎金馬明清牌坊裡規模最大的一座。"},{"who":"R","text":"為什麼要幫媽媽蓋這麼大一座牌坊？"},{"who":"A","text":"邱良功出生才35天，爸爸就過世了，媽媽許氏28歲守寡，一個人把他拉拔長大。"},{"who":"R","text":"好辛苦喔，那邱良功後來有成材嗎？"},{"who":"A","text":"超成材！他當上浙江水師提督，剿滅海盜蔡牽，是金門清代官階最高的武將，就奏請朝廷為母親建坊。"},{"who":"R","text":"這根本是最強的母親節禮物，比康乃馨重了好幾噸吧！"},{"who":"A","text":"哈哈，而且其中一隻石獅被當地人供奉成「石獅仙姑」，臉上有彩繪，前面還擺了香案。"},{"who":"R","text":"那我來找找是哪一隻石獅有彩繪，順便數一數總共有幾座屋簷！"}],"clues":["我的柱子上有王得祿、阮元等名臣的題聯","我紀念一位28歲守寡、撫孤成名的母親","後浦東門的四柱三間五檐石牌坊，主角是提督的母親"],"quiz":[{"q":"邱良功因為剿滅哪一位海盜而立功？","options":["林道乾","李旦","張保仔","蔡牽"],"answer":3,"explain":"邱良功剿滅海盜蔡牽，受封三等男爵。"},{"q":"節孝坊屬於哪一種牌坊形制？","options":["四柱三間三層五檐樓","二柱單間單層一檐樓","四柱三間二層三檐樓","六柱五間三層七檐樓"],"answer":0,"explain":"四根方柱、三層檐樓共五個出挑，是清代最雄偉格局。"}],"images":[{"file":"金門邱良功母節孝坊.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/%E9%87%91%E9%96%80%E9%82%B1%E8%89%AF%E5%8A%9F%E6%AF%8D%E7%AF%80%E5%AD%9D%E5%9D%8A.jpg/960px-%E9%87%91%E9%96%80%E9%82%B1%E8%89%AF%E5%8A%9F%E6%AF%8D%E7%AF%80%E5%AD%9D%E5%9D%8A.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E9%82%B1%E8%89%AF%E5%8A%9F%E6%AF%8D%E7%AF%80%E5%AD%9D%E5%9D%8A.jpg","artist":"Jennifer25172466","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-qiulianggongmujie-0.webp","small":"img/jincheng-qiulianggongmujie-0-s.webp"}]},{"id":"jinhu-qionglincaishici","name":"瓊林蔡氏祠堂","short":"瓊林蔡氏祠堂","category":"國定古蹟","level":"國定古蹟","town":"金湖鎮","types":["祠堂"],"lat":24.454114,"lng":118.373313,"address":"金門縣金湖鎮瓊林村測段377地號（大厝房十世宗祠）","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000089","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-15/7060f2ea-aecf-4c28-806e-175f41b205be/瓊林蔡氏祠堂.jpg","year":1840,"yearText":"明清兩代陸續興建，最晚一座建於1840年（清道光20年）","era":"qing","themes":["宗祠家廟","教育書院"],"yearUnknown":false,"summary":"七座八祠加書齋，臺澎金馬少見的單姓宗祠群","intro":"瓊林蔡氏祠堂位於金湖鎮瓊林村聚落核心，包括俗稱「七座八祠」的蔡氏家廟、竹溪六世、樂圃六世與新倉二房十世、前庭房六世、大厝房十世、新倉上二房十一世、藩伯等宗祠，以及作為學塾的怡穀堂，是臺澎金馬少見的大型單姓宗祠群。族譜記載南宋初年蔡氏十七郎入贅平林陳家，此後枝葉繁盛。祠堂形制各異，外牆依「紅宮黑祖厝」傳統塗黑，屋脊端的龍隱龍首朝外，寓意子孫向外發展。蔡氏家廟每年農曆二月初七、十月初六舉行春秋二祭，族人仍輪值晨昏上香。祠堂於1994至2002年陸續修復，今為國定古蹟。","highlights":["外牆塗黑的「紅宮黑祖厝」作法與屋脊朝外的龍隱","以書卷、文字為裝飾題材的學塾怡穀堂","最晚落成、屋脊最高的新倉上二房十一世宗祠"],"funFact":"新倉上二房十一世宗祠1840年最晚落成，村人叫它「新祖厝」，堂聯請來書法名家呂世宜題寫。","photoSpot":"在蔡氏家廟前埕拍黑牆與屋脊龍隱","visitMin":40,"openNote":"位於金湖鎮瓊林村。官方資料記載為瓊林蔡氏宗親祭祀之用，平時開放參觀；竹溪六世宗祠開放時間為每日7點至12點、14點至16點30分。參觀請保持肅靜，遇祭祀時勿干擾。可搭金門縣公車或騎機車前往瓊林。","dialogue":[{"who":"R","text":"Allan，這個村子怎麼到處都是黑色牆壁的房子？好像在拍武俠片！"},{"who":"A","text":"妳看到的是瓊林蔡氏祠堂。金門有句話叫「紅宮黑祖厝」，廟宇用紅色，宗祠就塗黑，一看就知道身分。"},{"who":"R","text":"那這裡總共有幾間祠堂？我數到眼睛都花了。"},{"who":"A","text":"俗稱「七座八祠」，再加上一間學塾怡穀堂。同一個姓氏蓋這麼多祠堂，在臺澎金馬非常少見。"},{"who":"R","text":"七座卻有八祠，是有一座買一送一嗎？"},{"who":"A","text":"哈，可以這樣記！其中一座同時供奉樂圃六世與新倉二房十世，一座房子兩個祠，比我一碗廣東粥加兩顆蛋還划算。"},{"who":"R","text":"那蔡家的人現在還會回來這裡拜拜嗎？"},{"who":"A","text":"會喔，蔡氏家廟每年農曆二月初七和十月初六舉行春秋二祭，族人平常還輪流早晚來上香。"},{"who":"R","text":"好用心！那我在現場要注意看什麼？"},{"who":"A","text":"請抬頭找屋脊兩端的龍隱，數數看龍頭是朝裡面還是朝外面，答案藏著蔡家對子孫的期望喔。"}],"clues":["我的外牆塗成黑色，屋脊龍首朝外","我有七座建築卻供奉八個祠，還附設一間學塾","我是瓊林蔡家的國定古蹟宗祠群"],"quiz":[{"q":"金門俗語「紅宮黑祖厝」中，塗黑色的是哪一類建築？","options":["廟宇","書院","洋樓","宗祠"],"answer":3,"explain":"宗祠外牆塗黑，廟宇用紅色，瓊林蔡氏祠堂即依此傳統。"},{"q":"瓊林蔡氏祠堂群中，作為學塾的是哪一座？","options":["怡穀堂","藩伯宗祠","蔡氏家廟","竹溪六世宗祠"],"answer":0,"explain":"怡穀堂是蔡家學塾，多用書卷與文字作裝飾。"}],"images":[{"file":"瓊林蔡氏祠堂.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2b/%E7%93%8A%E6%9E%97%E8%94%A1%E6%B0%8F%E7%A5%A0%E5%A0%82.jpg/960px-%E7%93%8A%E6%9E%97%E8%94%A1%E6%B0%8F%E7%A5%A0%E5%A0%82.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%93%8A%E6%9E%97%E8%94%A1%E6%B0%8F%E7%A5%A0%E5%A0%82.jpg","artist":"張雅倫","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinhu-qionglincaishici-0.webp","small":"img/jinhu-qionglincaishici-0-s.webp"}]},{"id":"jinhu-dongdingdaodengta","name":"東椗島燈塔","short":"東椗島燈塔","category":"國定古蹟","level":"國定古蹟","town":"金湖鎮","types":["燈塔"],"lat":24.16186,"lng":118.23369,"address":"金門縣金湖鎮東碇段7、8、9地號","announced":"2024-03-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20240315000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-15/6bbb7af1-aa59-4897-b839-07720c603130/unnamed.jpg","year":1871,"yearText":"1871年（清同治10年）","era":"qing","themes":["海防燈塔"],"yearUnknown":false,"summary":"金門極南端的黑色燈塔，閩粵臺最早的近代燈塔","intro":"東椗島燈塔位於金湖鎮轄下的東椗島（今稱東碇島），距水頭港約28.8公里，島面積約0.016平方公里，是金門縣的極南點。廈門開港後，清海關總稅務司赫德規劃東南沿海燈塔時最早確定興建此塔，1871年（清同治10年）竣工，是閩粵臺最早完成的近代燈塔。圓形磚造塔身外塗黑漆，為東南沿海燈塔首例；門額上方嵌有監造工程師與廈門關稅務司的姓名及建造年代，是清代燈塔首見的紀念性勒石。宿舍、庫房、儲水池與霧砲仍保存，展現西式技術與閩南紅磚的折衷特色。戰後國軍進駐，塔身留有當時的標語，2024年指定為國定古蹟。","highlights":["罕見的黑色圓形磚造塔身，船隻遠遠就能辨識","門額上方刻有監造者姓名與1871年的勒石","停用的兩門霧砲與紅磚儲水池井口"],"funFact":"「椗」是船錨。廈門人把廈門島想像成大船，東、北、南三座小島像固定船身的錨，東椗之名由此而來。","photoSpot":"無法到現場拍攝，可欣賞官方照片中的黑色塔身","visitMin":10,"openNote":"位於金門南方海域的東碇島，屬軍事管制區，一般民眾無法登島，只能透過網站或展覽認識。","dialogue":[{"who":"A","text":"阿拉蕾，今天我們搭網路快艇，去金門最南端的東椗島，看一座黑色的燈塔。"},{"who":"R","text":"黑色？燈塔不是都白白的嗎？它是不是走酷酷的叛逆路線？"},{"who":"A","text":"官方推測塗黑是為了讓船更好辨認，這在中國東南沿海的近代燈塔是第一座。"},{"who":"R","text":"那它幾歲了？應該比你爺爺還老吧！"},{"who":"A","text":"它在1871年，也就是清同治10年完工，是閩粵臺三地最早蓋好的近代燈塔，比我爺爺的爺爺還資深。"},{"who":"R","text":"為什麼要在這麼小的島上蓋燈塔？"},{"who":"A","text":"廈門開港後船越來越多，這片海暗礁多、海象亂，海關就先在東椗點亮第一盞燈。門口還刻著監造者的名字，等於燈塔的出生證明。"},{"who":"R","text":"好想去摸摸看喔，我們可以搭船登島嗎？"},{"who":"A","text":"這裡是軍事管制區，一般民眾不能登島。請你在網站照片裡找找門額上方那塊刻字的石頭吧。"}],"clues":["我站在只有約0.016平方公里的小島上，是金門的極南點","我的名字跟船錨有關，西方海圖叫我禮拜堂島","我是1871年完工的黑色磚造燈塔"],"quiz":[{"q":"東椗島燈塔塔身是什麼顏色？","options":["白色","紅白相間","黑色","黃色"],"answer":2,"explain":"塔身外塗黑漆，推測是為了增加航行辨識度。"},{"q":"東椗島燈塔在哪一年竣工？","options":["1842年","1871年","1883年","1895年"],"answer":1,"explain":"1871年（清同治10年）竣工，為閩粵臺最早的近代燈塔。"}],"images":[]},{"id":"wuqiu-dengta","name":"烏坵燈塔","short":"烏坵燈塔","category":"國定古蹟","level":"國定古蹟","town":"烏坵鄉","types":["燈塔"],"lat":24.993296,"lng":119.452137,"address":"金門縣烏坵鄉24.991973, 119.452990","announced":"2018-02-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20180726000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2018-07-26/293b50a1-bc57-4992-ac6e-089f654b53a7/IMG_2722.jpg","year":1874,"yearText":"1874年（清同治13年）興建，1875年（清光緒元年）點燈","era":"qing","themes":["海防燈塔"],"yearUnknown":false,"summary":"清代海關興建、矗立前哨島嶼的花崗石燈塔","intro":"烏坵燈塔位於烏坵鄉，距金門約130公里。燈塔建於清同治13年（1874），光緒元年（1875）12月3日點燈，由清政府海關總營造司、英籍的韓德善設計監造。塔身以紅灰色花崗石以石榫相啣砌成圓柱狀，形式尺寸與東莒燈塔相同，塔身並刻有興建年代與營造司姓名等石刻。1949年後烏坵成為前哨，燈塔轉為監視沿海的軍事建築，長期熄燈，塔高也由原本的19.5公尺變為17.3公尺；官方資料記載交通部航港局於2017年完成復燈工程。挪威籍守塔人雅格森1899年葬於燈塔旁。2018年由縣定古蹟升格為國定古蹟。","highlights":["以石榫相啣組砌的花崗石圓柱塔身","塔身記載興建年代與海關營造司的石刻","與東莒燈塔形式、尺寸相同的同代工法"],"funFact":"挪威人雅格森曾在鵝鑾鼻、漁翁島、東椗島與烏坵守塔，1899年葬在烏坵燈塔旁。","photoSpot":"無法到現場拍攝，可欣賞官方照片","visitMin":10,"openNote":"位於烏坵鄉，屬軍事管制區，距金門約130公里，一般民眾無法登島，只能透過網站或展覽認識。","dialogue":[{"who":"A","text":"阿拉蕾，今天這座燈塔我們只能在網路上看，因為烏坵是軍事管制區，一般民眾不能登島。"},{"who":"R","text":"連Allan都去不了？那它到底在哪裡呀？"},{"who":"A","text":"在湄洲灣和興化灣一帶的烏坵嶼，距離金門大約130公里，比金門到廈門遠多了。"},{"who":"R","text":"這麼遠！那燈塔是什麼時候蓋的？"},{"who":"A","text":"清同治13年，也就是1874年興建，隔年點燈，是清朝海關的英籍工程師韓德善設計的花崗石燈塔。"},{"who":"R","text":"英國工程師在清朝蓋燈塔，好國際化！"},{"who":"A","text":"還有更國際的，挪威人雅格森在這裡守過塔，1899年就葬在燈塔旁。"},{"who":"R","text":"後來燈塔怎麼了？聽說它好像變矮了？"},{"who":"A","text":"1949年後改作軍事用途、長期熄燈，塔高從19點5公尺變成17點3公尺。請到網站看官方照片，找找塔身的石刻。"}],"clues":["一位挪威守塔人長眠在我的身旁","我由清朝海關的英籍工程師設計，1875年點燈","我是金門縣最遠的離島上，一座花崗石燈塔"],"quiz":[{"q":"烏坵燈塔是由誰設計監造的？","options":["韓德善","雅格森","周德興","馬偕"],"answer":0,"explain":"清政府海關總營造司、英籍韓德善設計監造。"},{"q":"烏坵燈塔和哪一座燈塔形式尺寸相同？","options":["鵝鑾鼻燈塔","東椗島燈塔","東莒燈塔","漁翁島燈塔"],"answer":2,"explain":"烏坵燈塔與東莒燈塔形式尺寸相同。"}],"images":[{"file":"烏坵百年燈塔1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/%E7%83%8F%E5%9D%B5%E7%99%BE%E5%B9%B4%E7%87%88%E5%A1%941.jpg/960px-%E7%83%8F%E5%9D%B5%E7%99%BE%E5%B9%B4%E7%87%88%E5%A1%941.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%83%8F%E5%9D%B5%E7%99%BE%E5%B9%B4%E7%87%88%E5%A1%941.jpg","artist":"Kechinyuan","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/wuqiu-dengta-0.webp","small":"img/wuqiu-dengta-0-s.webp"}]},{"id":"lieyu-donglinsongdaidong","name":"烈嶼東林宋代東井","short":"東林宋代東井","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["其他設施"],"lat":24.427501,"lng":118.249457,"address":"金門縣烈嶼鄉東林聚落","announced":"2007-09-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20070926000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/292bda99-6e90-4156-a76a-aae00c31d483/烈嶼東林宋代東井.jpg","year":1204,"yearText":"1204年（南宋嘉泰4年）","era":"dutch","themes":["聚落地景"],"yearUnknown":false,"summary":"刻有南宋紀年、金門尺度最大的石砌古井","intro":"烈嶼東林宋代東井位於烈嶼鄉東林聚落，以花崗石板砌成。井欄北面刻「嘉泰甲子春林彥智捨」九字楷書，南面刻「大德乙巳重修」，可知此井於南宋嘉泰4年（1204）由林彥智捐建，元大德9年（1305）重修。井體以長石板「凸」字型相接組砌成正方形，內徑邊長130公分、深4.5公尺，是金門同類石砌井中尺度最大者。井四周加砌高60公分、邊長420公分的方形臺基，由井欄向四面鋪排24塊放射狀石板，中心高、四周低，水可流入臺基四周的導溝，再由四角開口排出，設計周到。","highlights":["井欄北面「嘉泰甲子春林彥智捨」楷書刻字","24塊放射狀石板鋪成的方形臺基","中心高四周低、四角開口排水的導溝設計"],"funFact":"南宋捐建、元代重修，兩個紀年都刻在井欄上，就像一張800多年前的施工銘牌。","photoSpot":"蹲低拍井欄刻字與放射狀石板","visitMin":15,"openNote":"位於烈嶼鄉東林聚落，戶外空間、全天候開放；井欄刻字請勿觸摸或拓印。可經金門大橋開車或騎車前往。鄰近烈嶼東林佛祖廟。","dialogue":[{"who":"A","text":"阿拉蕾，猜猜看，小金門東林這口井和我比起來，誰的年紀比較大？"},{"who":"R","text":"Allan雖然看起來很有歷史感，但我猜還是井贏。"},{"who":"A","text":"你這是安慰還是吐槽？這口井在南宋嘉泰4年，也就是1204年由林彥智捐建，已經800多歲了。"},{"who":"R","text":"800多歲！它怎麼證明自己的年紀？有身分證嗎？"},{"who":"A","text":"有喔，就刻在井欄上！北面刻「嘉泰甲子」捐建，南面刻「大德乙巳重修」，是元朝1305年修過。"},{"who":"R","text":"把出生證明和保養紀錄一起刻上去，好聰明！"},{"who":"A","text":"而且它很大，內徑邊長130公分、深4公尺半，是金門同類石砌井裡最大的一口。"},{"who":"R","text":"井旁邊那一圈石板排成放射狀，是裝飾嗎？"},{"who":"A","text":"那是排水設計，中間高四周低，水會流到導溝再從四角流出。到現場數數看，是不是剛好24塊？"}],"clues":["我身上刻著「嘉泰甲子」與「大德乙巳」兩個紀年","我四周鋪著24塊放射狀石板，四角還有排水口","我是小金門東林聚落一口800多歲的石砌古井"],"quiz":[{"q":"依井欄刻字，這口井由誰捐建？","options":["林天助","林信屏","林天來","林彥智"],"answer":3,"explain":"北面刻「嘉泰甲子春林彥智捨」，由林彥智捐建。"},{"q":"井臺由井欄向外鋪了幾塊放射狀石板？","options":["12塊","24塊","18塊","36塊"],"answer":1,"explain":"井欄向四面鋪排24塊放射狀石板，並有導溝排水。"}],"images":[{"file":"Lia̍t-sū Tong-lîm Sòng-tāi Tang-chíⁿ 20220802 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Lia%CC%8Dt-s%C5%AB_Tong-l%C3%AEm_S%C3%B2ng-t%C4%81i_Tang-ch%C3%AD%E2%81%BF_20220802_%28cropped%29.jpg/960px-Lia%CC%8Dt-s%C5%AB_Tong-l%C3%AEm_S%C3%B2ng-t%C4%81i_Tang-ch%C3%AD%E2%81%BF_20220802_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Lia%CC%8Dt-s%C5%AB_Tong-l%C3%AEm_S%C3%B2ng-t%C4%81i_Tang-ch%C3%AD%E2%81%BF_20220802_(cropped).jpg","artist":"Viy4092","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/lieyu-donglinsongdaidong-0.webp","small":"img/lieyu-donglinsongdaidong-0-s.webp"}]},{"id":"jinsha-haiyinsishimenguan","name":"海印寺、石門關","short":"海印寺石門關","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["其他設施"],"lat":24.462666,"lng":118.418393,"address":"金門縣金沙鎮太武山頂峰（梅園）後方","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-27/9c880829-d4ed-4aea-a5c4-5c152144149c/封面.png","year":1270,"yearText":"宋咸淳年間（1265–1274）創建","era":"dutch","themes":["宗教信仰"],"yearUnknown":false,"summary":"太武山頂的古剎與「海山第一」山門","intro":"海印寺位於金沙鎮太武山頂峰梅園後方，又稱太武巖寺，宋咸淳年間（1265–1274）創建，原祀通遠仙翁。明萬曆8年（1580）同安知縣金枝捐資修建，萬曆28年（1600）再修。相傳廟眾夜見觀音現身而改奉觀音，依寺方說法至遲在永曆15年（1661）重修時已成佛寺並更名海印寺。石門關是它的山門，石楣石柱帶半圓拱，門額「海山第一」為明人盧若騰所題，名列太武山十二奇。寺院順山谷縱向配置鐘鼓樓、蘸月池、拜亭、正殿與大雄寶殿，後方巨岩下的「古石室」是最古老的遺址。每年農曆正月初九有齋天大法會。","highlights":["石門關門額上盧若騰題的「海山第一」","泉水自岩縫流出的蘸月池","正殿後巨岩下的「古石室」與八角形石柱"],"funFact":"據《同安縣志》，知縣金枝夢見登太武山、神明指出逃犯藏身處，果然抓到人，便捐錢修祠。","photoSpot":"在石門關前拍「海山第一」門額","visitMin":40,"openNote":"位於金沙鎮太武山頂峰梅園後方，官方資料記載每日08:00至17:00開放。需沿太武山步道步行上山，請穿好走的鞋、帶水，並依現場告示通行。每年農曆正月初九有齋天大法會，人潮較多。","dialogue":[{"who":"A","text":"爬到這裡，汗都流下來了吧？歡迎來到太武山頂的海印寺。"},{"who":"R","text":"Allan，你才是滿頭大汗，光頭都在反光了！"},{"who":"A","text":"哈哈，這叫自帶照明。海印寺在宋咸淳年間創建，一開始拜的是通遠仙翁，不是觀音。"},{"who":"R","text":"咦？那後來怎麼會變成供奉觀音的佛寺？"},{"who":"A","text":"相傳廟裡的人在夜裡看見觀音菩薩現身，就改奉觀音，最晚在永曆15年重修時已是佛寺。"},{"who":"R","text":"剛剛進來穿過的那個石頭拱門，也很有味道耶。"},{"who":"A","text":"那是山門石門關，門額「海山第一」是明代盧若騰題的，名列太武山十二奇。"},{"who":"R","text":"站在山頂看海，海山第一果然名不虛傳！"},{"who":"A","text":"等一下繞到正殿後面，找找巨岩下的「古石室」，看看石柱是不是八角形的！"}],"clues":["我原本供奉通遠仙翁，後來改奉觀音","我的山門門額寫著「海山第一」","我在太武山頂梅園後方，正月初九有人登山拜天公"],"quiz":[{"q":"海印寺創建時最早供奉的是哪一位神祇？","options":["通遠仙翁","觀音菩薩","保生大帝","關聖帝君"],"answer":0,"explain":"宋咸淳年間建巖宇祀通遠仙翁，後改奉觀音。"},{"q":"石門關門額上題的是哪四個字？","options":["奎星聳照","海山第一","湖海清平","虛江嘯臥"],"answer":1,"explain":"門額「海山第一」為明人盧若騰所題。"}],"images":[]},{"id":"jincheng-fenglianshanmuma","name":"豐蓮山牧馬侯祠","short":"牧馬侯祠","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["寺廟"],"lat":24.42061,"lng":118.32238,"address":"金門縣金城鎮莒光樓段803-4地號","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/82b87562-893a-43bb-91c7-183494695201/01封面.jpg","year":1336,"yearText":"約1336年（元至元年間）敕建，唐代已有祭祀","era":"dutch","themes":["宗教信仰"],"yearUnknown":false,"summary":"供奉開浯恩主陳淵，金門最早的恩主公廟","intro":"牧馬侯祠位於金城鎮庵前聚落東北隅、豐蓮山東南側，主祀唐代牧馬監陳淵。據《金門志》，唐貞元19年（803）金門被奏置為萬安牧馬監地，陳淵率部屬與蔡、許、翁等十二姓來島屯居牧馬，鄉人尊他為「開浯恩主」。元代相傳他顯靈助退倭寇，朝廷賜廟額「孚濟」、敕封「福佑聖侯」；明永樂年間〈孚濟廟記〉記載當時廟有七座。現為三落廟宇，保留清末建築特色，左側有清道光23年（1843）與宣統元年（1909）兩方石碑。恩主公信仰遍布金門，更隨落番鄉親傳到新加坡與越南。","highlights":["三川殿與正殿燕尾翹脊、八字規混合的屋脊","捲棚拜亭兩側的龍虎井與交趾陶","左側道光23年與宣統元年兩方捐題碑"],"funFact":"傳說陳淵擊鼓豎旗，馬匹就會認旗子顏色自動集合，所以也有人稱他「馬祖」。","photoSpot":"前埕正面拍三落廟宇的燕尾翹脊","visitMin":25,"openNote":"位於金城鎮庵前聚落東北側的豐蓮山麓，官方資料記載全天候開放，參拜請保持肅靜、遵守廟方規定。可從金城市區騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，考妳一題，金門人口中的恩主公是誰？答案就在豐蓮山這間牧馬侯祠。"},{"who":"R","text":"恩主公？聽起來像請大家吃飯的大恩人，Allan你是不是又想到吃的了？"},{"who":"A","text":"這次真的不是。恩主公是唐代的牧馬監陳淵，803年金門被設為牧馬區，他帶著十二姓鄉親來這裡養馬。"},{"who":"R","text":"十二姓？原來金門早期的開發，跟養馬有關喔！"},{"who":"A","text":"沒錯，所以大家尊稱他開浯恩主。傳說他擊鼓豎旗，馬就會認旗子的顏色，自己跑到旗下集合。"},{"who":"R","text":"馬會認旗子排隊？比我們班上朝會還整齊耶！"},{"who":"A","text":"元代還傳說他顯靈幫忙擊退倭寇，朝廷因此賜廟額孚濟，封他福佑聖侯。"},{"who":"R","text":"那恩主公的信仰只有在金門才有嗎？"},{"who":"A","text":"還跟著落番鄉親傳到新加坡呢。到現場請找左邊那兩塊清代捐題石碑，看看刻的是哪兩個年號！"}],"clues":["我的主神在唐代帶著十二姓來島上屯居牧馬","元代朝廷賜我廟額「孚濟」","我在庵前豐蓮山下，供奉金門的恩主公陳淵"],"quiz":[{"q":"金門恩主公陳淵在唐代擔任什麼職務？","options":["水師提督","牧馬監","縣丞","書院山長"],"answer":1,"explain":"陳淵是唐代牧馬監，率眾到金門屯居牧馬。"},{"q":"元代朝廷賜給這座廟的廟額是？","options":["昭應","慈濟","孚濟","威靈"],"answer":2,"explain":"元代朝廷賜廟額「孚濟」，並封福佑聖侯。"}],"images":[{"file":"牧马侯祠 - Marquis of Horse Pasturage Shrine - 2014.09 - panoramio (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/%E7%89%A7%E9%A9%AC%E4%BE%AF%E7%A5%A0_-_Marquis_of_Horse_Pasturage_Shrine_-_2014.09_-_panoramio_%28cropped%29.jpg/960px-%E7%89%A7%E9%A9%AC%E4%BE%AF%E7%A5%A0_-_Marquis_of_Horse_Pasturage_Shrine_-_2014.09_-_panoramio_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%89%A7%E9%A9%AC%E4%BE%AF%E7%A5%A0_-_Marquis_of_Horse_Pasturage_Shrine_-_2014.09_-_panoramio_(cropped).jpg","artist":"rheins","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/jincheng-fenglianshanmuma-0.webp","small":"img/jincheng-fenglianshanmuma-0-s.webp"}]},{"id":"jinsha-yuantaiwushanzhu","name":"元太武山築寨砌路摩崖石刻","short":"元代太武山石刻","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["碑碣"],"lat":24.465725,"lng":118.418288,"address":"金門縣金沙鎮大山段370-8地號","announced":"2019-08-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190929000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/468fa5a5-3678-4c5e-8149-44b32929d661/元太武山築寨砌路摩崖石刻.jpg","year":1363,"yearText":"1363年（元至正23年）","era":"dutch","themes":["摩崖石刻"],"yearUnknown":false,"summary":"金門島上僅見的元代石刻","intro":"元太武山築寨砌路摩崖石刻位於金沙鎮太武山的蔡厝古道上，鄰近海印寺與石門關。巨巖東南側平滑面刻有五行楷書，記載元代忠翊校尉、浯洲場鹽司令陳元澤募款修築山寨、鋪砌登山石路，並列出司令謝忠南、司丞王國禮、管勾呂務能、耆儒陳志霖、僧王岩、司吏李榮等人，落款「至正癸卯二十三年春三月」，即1363年。金門自元大德元年起建場徵鹽，石刻上的司令、司丞、管勾官名與《元史》《金門志》記載相符，是目前金門島上僅見的元代石刻。","highlights":["巨巖上的五行楷書與「至正癸卯」落款","刻文中司令、司丞、管勾三種鹽場官名","沿蔡厝古道登山，可順遊海印寺與石門關"],"funFact":"金門鹽場在元代稱「浯洲場」，石刻上的鹽司令是從七品官，負責管理島上鹽務。","photoSpot":"側光下拍巨巖刻字，較易看清字跡","visitMin":30,"openNote":"位於金沙鎮太武山蔡厝古道旁，鄰近海印寺與石門關，官方資料記載全天開放。需步行登山，請穿好走的鞋並留意天候。可開車或騎機車到太武山一帶再步行前往。","dialogue":[{"who":"R","text":"Allan，爬山爬得好喘，這塊大石頭上刻的是什麼字？"},{"who":"A","text":"這可是金門島上僅見的元代石刻，落款是至正23年，也就是1363年，比明朝建國還早5年。"},{"who":"R","text":"比明朝還早耶！那到底是誰刻的呀？"},{"who":"A","text":"一位叫陳元澤的浯洲場鹽司令，他募款在太武山修山寨、鋪石路，完工後刻石留念。"},{"who":"R","text":"鹽司令？管鹽的官也要管修路喔？"},{"who":"A","text":"那時金門是重要鹽場，官員找來地方耆儒和僧人一起出力，石頭上連司丞、管勾的名字都刻上去了。"},{"who":"R","text":"好像工程完工的感謝名單，大家都有掛名！"},{"who":"A","text":"而且這些官名跟元史的記載對得上，證明金門在元代就設有鹽場，價值很高。"},{"who":"R","text":"那我來出任務：到現場找找「至正癸卯」四個字，找到再下山吃碗蚵仔麵線！"}],"clues":["我比明朝建國還早五年就被刻好了","我記下一位鹽司令募款修山寨、鋪石路的事","我是太武山蔡厝古道旁一塊有題刻的巨巖"],"quiz":[{"q":"石刻上的陳元澤擔任什麼官職？","options":["浯洲場鹽司令","金門守禦千戶","同安縣知縣","泉州府通判"],"answer":0,"explain":"刻文記載忠翊校尉浯洲場鹽司令陳元澤募緣築寨。"},{"q":"石刻落款的至正23年是西元哪一年？","options":["1287年","1388年","1363年","1403年"],"answer":2,"explain":"落款至正癸卯二十三年，即1363年。"}],"images":[]},{"id":"jinsha-xiyuanxizhaihuang","name":"西園西宅黃氏開基祖墓","short":"西宅黃氏祖墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["墓葬"],"lat":24.51129,"lng":118.40271,"address":"金門縣金沙鎮西園段1285-1地號","announced":"2020-03-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20200409000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/d0c9ea79-2574-4143-add7-3e87107e4e48/西園西宅黃氏開基祖墓封面.jpg","year":1370,"yearText":"約元末明初（14世紀）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"逾600年仍有子孫祭掃的開基祖墓","intro":"西園西宅黃氏開基祖墓位於金沙鎮西園聚落。西園是以黃氏為主的單姓聚落，墓主黃時守與妻王氏在元末明初自南安下店遷來，定居西甲「西宅」，是西宅黃氏開基祖；三子黃均彰遷居北甲，成為北甲始祖。約民國50年代後祭掃中斷，墓地被雜木覆蓋，民國105年（2016）北甲宗親從廈門取得家譜，依記載尋回此墓並購回墓地，恢復祭掃。墓碑為無碑文的牛軛狀花崗石，以淺浮雕刻瑞日、祥雲；墓岸、墓龜與墓手以夯土混石塊、蚵殼築成，反映西園自古為「蠔鹽之鄉」、就地取材的智慧。","highlights":["無碑文、刻有瑞日祥雲的牛軛狀墓碑","混入石塊與蚵殼的夯土墓龜與墓手","順著山坡層層升高的墓體配置"],"funFact":"這座墓曾被雜木掩沒，直到宗親從廈門取得家譜，才依記載把開基祖的墓找回來。","photoSpot":"在墓前低角度拍牛軛狀墓碑","visitMin":10,"openNote":"位於金沙鎮西園聚落郊外，官方資料記載全天候開放。墓地仍有宗親祭掃，請保持肅靜、勿踩踏或攀爬墓體，周邊植被茂密請注意腳下。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這個墓碑上怎麼一個字都沒有？"},{"who":"A","text":"好問題！明初古墓常見無碑文的牛軛狀墓碑，這塊只刻了瑞日和祥雲。"},{"who":"R","text":"沒有名字，那大家怎麼知道是誰的墓？"},{"who":"A","text":"這就是精彩的地方。民國105年，北甲黃氏宗親從廈門取得家譜，照著記載找回這座墓。"},{"who":"R","text":"拿著家譜找祖先，好像拿藏寶圖尋寶喔！"},{"who":"A","text":"很像吧。墓主黃時守在元末明初從南安遷來西園，是西宅黃氏的開基祖，至今已600多年。"},{"who":"R","text":"那墓旁邊這些土堆，怎麼好像混著一片一片白白的碎片？"},{"who":"A","text":"那是蚵殼！西園自古是蠔鹽之鄉，墓龜和墓手用夯土混石塊、蚵殼築成。"},{"who":"R","text":"那我要蹲下來仔細看，找找墓碑上的太陽和雲朵浮雕！"}],"clues":["我的墓碑沒有刻字，只有太陽和雲朵","我被雜木掩蓋多年，子孫靠一本家譜把我找回來","西園聚落元末明初遷來的黃氏祖先長眠之地"],"quiz":[{"q":"這座祖墓的墓碑是什麼外形？","options":["圓拱形","屋形","牛軛狀","方尖碑"],"answer":2,"explain":"墓碑為無碑文的牛軛狀花崗石，屬明初形制。"},{"q":"墓龜與墓手的夯土裡混了什麼材料？","options":["稻草與竹片","瓦片與陶片","糯米與紅糖","石塊與蚵殼"],"answer":3,"explain":"西園為蠔鹽之鄉，夯土就地混入石塊與蚵殼。"}],"images":[]},{"id":"jinhu-chenxianmu","name":"陳顯墓","short":"陳顯墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["墓葬"],"lat":24.43635,"lng":118.40416,"address":"金門縣金湖鎮漁村段178-1、189、190、242-1、320、321、329-1地號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/455f2c1f-0fe7-42aa-aa35-675aeb9e84c1/封面.png","year":1403,"yearText":"約1403年（明永樂元年）","era":"dutch","themes":["墓葬","摩崖石刻"],"yearUnknown":false,"summary":"背倚巨石的「南海夜臺」，金門開科第一人之墓","intro":"陳顯墓位於金湖鎮後園南側濱海處，面向料羅灣。陳顯號南海，金門下坑（今夏興）人，1371年（明洪武4年）首科以經魁中試，被稱為金門「開科第一」，歷任三地知州，為官清廉而家貧。燕王曾延攬他掌書記，他察覺燕王有異志，諷諫未果便稱病返鄉；1403年明成祖遣使召他入京，他不願出仕，具衣冠再拜而自盡。墓背倚巨石，泉州白石墓碑刻「南海夜臺」篆文，「夜臺」即墓穴。墓後百餘公尺的巨石上鐫刻1726年（清雍正4年）裔孫所立的墓道碑，為金門孤例。此地被稱為「螃蟹穴」，流傳燈籠飛落擇地的傳說。","highlights":["泉州白石墓碑上的「南海夜臺」篆文","墓後百餘公尺巨石上鐫刻的墓道碑，金門孤例","曲手前端起翹如屋簷的罕見墓制"],"funFact":"相傳運送陳顯的船頭燈籠被風吹到巨石坡上，堪輿師一看驚呼是「蟹窩吉地」，就葬在這裡。","photoSpot":"從墓前拍墓碑與後方巨石","visitMin":15,"openNote":"位於金湖鎮後園南側濱海處的戶外墓地，官方資料未載開放資訊。參觀請尊重墓主、勿攀爬墓體與巨石。","dialogue":[{"who":"R","text":"Allan，這座墓後面靠著一顆超大的石頭，好像有個巨人在背後撐腰！"},{"who":"A","text":"這是陳顯墓。陳顯是明代洪武年間第一屆科舉就上榜的金門人，所以被稱為金門「開科第一」。"},{"who":"R","text":"第一屆就考上，學霸中的學霸耶！"},{"who":"A","text":"他當了三任知州，為官清廉，家裡卻窮到三餐不繼。後來燕王起兵當了皇帝，召他進京，他不願意，選擇以死明志。"},{"who":"R","text":"好有骨氣，聽了心裡覺得很沉重。"},{"who":"A","text":"是啊。墓碑刻著「南海夜臺」，南海是他的號，夜臺是墓穴的意思。墓後百多公尺的巨石上，還刻著清代子孫立的墓道碑。"},{"who":"R","text":"那為什麼會選在這顆大石頭前面？"},{"who":"A","text":"傳說船頭的燈籠被風吹到這塊巨石上，風水師說這裡是螃蟹穴。請你看看巨石和前方海灣，像不像螃蟹的殼和兩隻大螯。"}],"clues":["我的風水被稱為螃蟹穴，傳說是燈籠替我選的","我的墓碑刻著南海夜臺四個字","我的主人是明代洪武首科中試的金門開科第一人"],"quiz":[{"q":"陳顯被稱為金門的什麼？","options":["開科第一","首任知縣","第一位進士","海防名將"],"answer":0,"explain":"陳顯於明洪武首科以經魁中試，為一邑科名之始。"},{"q":"陳顯墓碑上「夜臺」二字指的是什麼？","options":["夜晚的燈塔","觀星平臺","墓穴的別稱","海邊的瞭望臺"],"answer":2,"explain":"南海是陳顯的號，夜臺是墓穴的別稱。"}],"images":[]},{"id":"jinsha-yongchangtangjiwu","name":"永昌堂暨浯陽小學校","short":"永昌堂","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["祠堂","學校"],"lat":24.479,"lng":118.42799,"address":"金門縣金沙鎮陽翟37號","announced":"2015-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150211000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-04-07/e29aa48d-1e0b-491b-9945-5d9c0e99f1f0/代表圖像.jpg","year":1435,"yearText":"約1435年（明宣德年間）始建，1935年改建","era":"dutch","themes":["宗祠家廟","教育書院","僑鄉洋樓"],"yearUnknown":false,"summary":"洋樓式宗祠加小學校，金門罕見組合","intro":"永昌堂暨浯陽小學校位於金沙鎮光前里陽翟聚落。永昌堂是陽翟陳氏信房前房的小宗祠堂，始建於明宣德年間（約1435）。1930年代印尼邦加檳港胡椒園主陳仲厚（1869–1949）獨資重建，帶回融合西方元素的設計圖，民國24年（1935）完工，隔年右側的五腳基護龍「浯陽小學校」也落成，總工程費一萬二千銀圓。宗祠前落為傳統閩式，後落為二層五腳基洋樓，是宗祠採洋樓形式的少見案例。民國38年（1949）後兩棟皆為國軍使用，1994年國軍撤離後閒置，2024年10月開工修復。","highlights":["後落洋樓山頭上金門唯一的飛馬泥塑","護龍牆上「浯陽小學校1936」泥塑題字","二樓正廳鋼筋混凝土仿木的三通五瓜棟架"],"funFact":"出資重建的陳仲厚在印尼邦加檳港經營胡椒園，被譽為「檳港第一」。","photoSpot":"在前方拍閩式前落與後方洋樓山頭","visitMin":15,"openNote":"位於金沙鎮陽翟聚落，為陳氏宗族祠堂，2024年10月起進行修復工程，目前僅能外觀參觀；施工期間請注意安全，勿擅入。可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間祠堂前面是閩南屋頂，後面卻冒出一棟洋樓，是兩棟房子黏在一起嗎？"},{"who":"A","text":"很像吧！永昌堂明代就有了，民國24年印尼胡椒園主陳仲厚出錢重建，還帶回有西方元素的設計圖。"},{"who":"R","text":"胡椒園主！所以這間祠堂吃起來會有點辣嗎？"},{"who":"A","text":"哈，是看起來很嗆眼。隔年他又在右邊蓋了浯陽小學校，祠堂加學校，在金門非常罕見。"},{"who":"R","text":"拜完祖先就去上課，讀書應該會特別認真吧！"},{"who":"A","text":"可惜戰後這裡成了國軍的師部指揮所，學校後來也併校了，直到1994年部隊撤離後就閒置下來。"},{"who":"R","text":"好可惜，那它現在的狀況怎麼樣呢？"},{"who":"A","text":"2024年開始修復了。後落洋樓的山頭上有一匹飛馬泥塑，是金門唯一的一匹喔。"},{"who":"R","text":"金門唯一的飛馬！大家到現場抬頭找找它，再看看護龍牆上「浯陽小學校1936」的字樣吧！"}],"clues":["我前面是閩南屋頂，後面卻是一棟洋樓","我山頭上有一匹金門唯一的飛馬泥塑","我是陽翟陳氏宗祠，右邊還附設一所小學校"],"quiz":[{"q":"出資重建永昌堂的陳仲厚在印尼經營什麼？","options":["胡椒園","橡膠園","錫礦場","糖廠"],"answer":0,"explain":"陳仲厚在印尼邦加檳港經營胡椒園，人稱檳港第一。"},{"q":"永昌堂後落洋樓山頭上有什麼金門唯一的泥塑？","options":["雄鷹","天使","飛馬","麒麟"],"answer":2,"explain":"永昌堂後落山頭的飛馬泥塑為金門唯一。"}],"images":[]},{"id":"jinsha-caicuocaishijia","name":"蔡厝蔡氏家廟","short":"蔡厝蔡氏家廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["祠堂"],"lat":24.473034,"lng":118.417013,"address":"金門縣金沙鎮蔡厝3號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-09-12/1c680494-8c2e-4118-8499-c3b4a0f3326e/蔡厝蔡氏家廟-代表圖片.jpg","year":1466,"yearText":"宋代創建，1466年（明成化2年）修建","era":"dutch","themes":["宗祠家廟"],"yearUnknown":false,"summary":"宋代創建、奉祀明代名臣蔡復一的家廟","intro":"蔡厝蔡氏家廟位於金沙鎮蔡厝聚落。開浯始祖蔡一郎在五代後期由泉州萬安遷居「山兜」，即今蔡厝。家廟創建於宋代，今日外觀與格局是明成化2年（1466）修建留下，屬金門傳統單進式家廟，由門樓、過水廊與正殿組成，木棟架雕刻不施彩繪，質樸大方。廟內奉祀出生於蔡厝的明代名臣蔡復一，他於萬曆23年（1595）登進士，後官至總督，為金門與同安共同景仰；原藏家廟的「蔡復一畫像」已登錄為重要古物。民國38年（1949）國軍進駐後側廳曾作倉庫，正殿右側大規壁留有「反共抗俄」標語。家廟於民國113年（2024）6月修復竣工。","highlights":["不施彩繪、呈現原木質樸的木棟架雕刻","正殿右側大規壁上的軍事標語","屋脊上的龍隱與兩端翹脊"],"funFact":"「蔡復一畫像」原本收藏在家廟內，民國109年登錄為重要古物，後來由博物館典藏展示。","photoSpot":"在廟埕拍門樓與兩側人字砌石牆","visitMin":15,"openNote":"位於金沙鎮蔡厝聚落，官方資料記載週一至週日08:00至17:00開放。這裡是宗族祭祀空間，參觀請保持安靜、尊重祖龕。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"歡迎來到蔡厝。阿拉蕾，你知道這個村子以前叫什麼嗎？"},{"who":"R","text":"該不會叫蔡家莊吧？聽起來好像武俠小說。"},{"who":"A","text":"差一點，以前叫山兜。五代後期蔡一郎從泉州萬安搬來，就在這裡落地生根。"},{"who":"R","text":"五代那麼早？那這座家廟應該也很老囉？"},{"who":"A","text":"家廟創建於宋代，現在的樣子是明成化2年修建留下來的，已經超過550年了。"},{"who":"R","text":"裡面供奉的祖先裡，有沒有特別有名的？"},{"who":"A","text":"有，明代名臣蔡復一就在蔡厝出生，萬曆23年考上進士，金門和同安都很敬重他。"},{"who":"R","text":"我發現這裡的木頭雕刻都沒有上色耶，是還沒畫完嗎？"},{"who":"A","text":"對，原木不上彩正是它的特色。離開前看看正殿右邊的牆，找找當年的軍事標語。"}],"clues":["我在宋代創建，明成化年間修建成今天的樣子","我奉祀一位明萬曆年間登進士的名臣","舊稱山兜的聚落裡，木雕不施彩繪的單進式家廟"],"quiz":[{"q":"蔡厝聚落的舊稱是什麼？","options":["山后","山前","山西","山兜"],"answer":3,"explain":"蔡一郎遷居的山兜，就是今天的蔡厝。"},{"q":"家廟今天的外觀格局，主要是哪一年修建留下的？","options":["明成化2年","明萬曆23年","清康熙3年","清道光9年"],"answer":0,"explain":"家廟創建於宋代，今貌為明成化2年修建所致。"}],"images":[{"file":"Kingmentsai (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/aa/Kingmentsai_%28cropped%29.jpg/960px-Kingmentsai_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Kingmentsai_(cropped).jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-caicuocaishijia-0.webp","small":"img/jinsha-caicuocaishijia-0-s.webp"}]},{"id":"jinsha-zhangminyiguan","name":"張敏衣冠塚","short":"張敏衣冠塚","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["墓葬"],"lat":24.51989,"lng":118.41828,"address":"金門縣金沙鎮青嶼測段480-1、483-5、488-1地號","announced":"2025-04-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20250429000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-04-28/6fb9a102-f552-45e0-9d3a-9de495518409/代表圖像.jpg","year":1485,"yearText":"1485年（明成化21年）張敏逝世後敕建","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"為浯洲爭取減輕鹽稅的明代人物衣冠塚","intro":"張敏衣冠塚位於金沙鎮青嶼一帶的古官道旁。張敏（1434–1485），字太德，金門青嶼人，幼年雙親俱逝，與兄長被送往京師侍奉內廷，明憲宗時受到重用，曾任御馬監太監、監督五軍大營等職。他進言減輕浯洲灶戶的鹽稅與徭役，使島民得以安居，也為金門子弟開啟科舉之路。成化21年（1485）逝世後，皇帝賜葬通州，並遣欽差到青嶼宣旨，建下馬碑、褒忠祠與這座衣冠塚，後代祭祀至今。墓塋通體花崗岩，牛軛形墓碑中央浮雕瑞日祥雲，墓龜為一整塊刻有龜背紋的巨石，墓桌兩側石獅轉首相望。","highlights":["碑心象徵「大明」的瑞日祥雲浮雕","整塊巨石雕成、刻六角龜背紋的墓龜","墓桌兩側轉頭相望、模樣樸拙的石獅"],"funFact":"衣冠塚就在古官道上，順著官道還能走到同樣與張敏有關的褒忠坊與宗祠。","photoSpot":"在墓埕外側拍兩隻轉頭相望的石獅","visitMin":15,"openNote":"位於金沙鎮青嶼一帶的古官道旁，官方資料記載全天候開放；墓塋仍由後代祭祀，請保持肅靜，勿攀爬墓體與石獅。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這兩隻石獅子頭小小的，還轉頭互看，好像在偷講悄悄話！"},{"who":"A","text":"觀察得好，這是閩南同安一帶常見的石獅造型，樸拙又可愛。牠們守護的是明代人物張敏的衣冠塚。"},{"who":"R","text":"張敏是誰呀？他在金門很有名嗎？"},{"who":"A","text":"他是青嶼人，從小父母雙亡，被送進京城內廷，後來受到明憲宗重用。"},{"who":"R","text":"從孤兒變成皇帝身邊的紅人，好像宮廷劇的主角！"},{"who":"A","text":"更重要的是他沒忘記家鄉，進言減輕浯洲灶戶的鹽稅和徭役，讓島民的日子好過許多。"},{"who":"R","text":"幫家鄉爭取減稅！金門人一定很感謝他吧？"},{"who":"A","text":"是啊，他過世後皇帝派欽差來青嶼宣旨，建了下馬碑、褒忠祠和這座衣冠塚，後代祭祀到今天。"},{"who":"R","text":"那大家到現場，先找找墓碑中央的瑞日祥雲，再看看兩隻石獅各自轉向哪一邊吧！"}],"clues":["我守護著一位為浯洲爭取減稅的明代人物","我墓桌兩側的石獅頭小小的，轉頭互相對望","我在青嶼古官道旁，是明成化年間敕建的墓"],"quiz":[{"q":"張敏對家鄉浯洲最大的貢獻是？","options":["進言減輕鹽稅與徭役","捐資興建書院","督造金門城牆","開闢料羅港口"],"answer":0,"explain":"張敏進言減輕浯洲灶戶鹽稅、徭役，使島民安居。"},{"q":"張敏衣冠塚墓碑中央的浮雕圖案是？","options":["雙龍搶珠","麒麟送子","瑞日祥雲","八卦太極"],"answer":2,"explain":"牛軛狀墓碑碑心刻有「瑞日祥雲」圖樣。"}],"images":[]},{"id":"jinsha-chenzhenenrongfang","name":"陳禎恩榮坊","short":"陳禎恩榮坊","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["牌坊"],"lat":24.48109,"lng":118.43028,"address":"金門縣金沙鎮東珩段707、708地號（會山寺右前方）","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/65a10677-de71-429e-bed5-7db031febd4e/01封面.jpg","year":1530,"yearText":"明嘉靖年間（1526年以後）","era":"dutch","themes":["牌坊碑碣"],"yearUnknown":false,"summary":"金門保存最完整的明代石牌坊","intro":"陳禎恩榮坊位於金沙鎮陽翟聚落東郊、會山寺右前方。陳禎是明代浯洲陽翟人，正德10年（1515）為貢生，曾任廣東長樂縣訓導。次子陳健於嘉靖5年（1526）登進士，因「父以子貴」，陳禎去世後獲朝廷誥贈並賜建此坊。牌坊坐西朝東，正面朝向陽翟聚落，用以榮宗耀祖。它是典型明代沖天式牌坊，四柱三間三樓，花崗石造，總高約5.07公尺；明間小額枋陰刻「誥贈刑部員外郎陳禎」，插角雕成魚龍，頂部牌樓下的匾額刻紅漆「恩榮」二字，柱頂石獅為後來居民捐資安上。官方稱它是金門保存最完整的明代石造牌坊。","highlights":["小額枋上橫刻的「誥贈刑部員外郎陳禎」","牌樓匾額上塗紅漆的「恩榮」二字","插角上龍首魚身的魚龍雕刻"],"funFact":"柱頂那對青斗石獅不是明代原物，而是後來的居民捐錢安上去的。","photoSpot":"從陽翟聚落方向拍牌坊正面","visitMin":15,"openNote":"位於金沙鎮陽翟聚落東郊、會山寺右前方的戶外空間，官方資料記載全天開放。請勿攀爬牌坊與夾杆石。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，站在這座石牌坊前，你覺得它在跟誰打招呼？"},{"who":"R","text":"當然是跟我打招呼啊！我這麼可愛。"},{"who":"A","text":"差一點點。它坐西朝東，正面朝著陽翟聚落，要讓全村都看見陳家的榮耀。"},{"who":"R","text":"什麼榮耀這麼重要，要做成石頭給大家看？"},{"who":"A","text":"陳禎的兒子陳健在嘉靖5年考上進士，父以子貴，陳禎過世後朝廷誥贈官銜，還賜建這座坊。"},{"who":"R","text":"兒子考得好，爸爸得牌坊，這是最強的家長獎勵吧！"},{"who":"A","text":"哈哈，可以這麼說。它是四柱三間的明代沖天式牌坊，也是金門保存最完整的明代石牌坊。"},{"who":"R","text":"柱子頂上那兩隻石獅子，也是明代的嗎？"},{"who":"A","text":"那對青斗石獅是後來居民捐的。你去找找頂端的匾額，看看那兩個紅字寫什麼！"}],"clues":["我因為一位兒子考上進士，才在父親身後被賜建","我是四柱三間的沖天式石造建築，頂上刻著紅字","陽翟東郊、會山寺附近的明代石牌坊"],"quiz":[{"q":"牌坊頂部匾額刻的是哪兩個字？","options":["聖旨","節孝","恩榮","旌表"],"answer":2,"explain":"牌樓下的匾額陰刻「恩榮」二字，並上紅漆。"},{"q":"陳禎因為誰的功名而獲朝廷誥贈？","options":["長子陳偉","次子陳健","孫子陳榮祖","同鄉黃偉"],"answer":1,"explain":"次子陳健嘉靖5年登進士，父以子貴。"}],"images":[]},{"id":"jinsha-huangweimu","name":"黃偉墓","short":"黃偉墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["墓葬"],"lat":24.476254,"lng":118.409156,"address":"金門縣金沙鎮斗門劃測段600、601、621、444地號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/a469fb3d-8209-400b-bba0-bba40120589a/封面.png","year":1538,"yearText":"1538年（明嘉靖17年）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"「品德完人」黃偉的完整明代墓園","intro":"黃偉墓位於金沙鎮太武山北麓坡地，風水上稱「飛鴉落田」穴，曾列金門四大風水吉地之一。黃偉號逸叟，汶水頭（今後水頭）人，明正德9年（1514）進士，歷任南京刑部主事、南雄知府、松江知府，因直言不附和當道而返鄉講學。俗諺「文章許鍾斗，品德黃逸叟」，尊他為「品德完人」。嘉靖16年（1537）泉州大饑，他協助賑災，積勞成疾，次年去世，墓建於明嘉靖17年（1538）。墓園規制與《大明會典》相符，有石虎、石馬、墓筆各一對，墓龜為官印式，未設墓碑，另有贔屭馱負的「大明」墓道碑。民國98年（2009）修復完成。","highlights":["墓埕上蹲踞的石虎與低首的石馬","官印式墓龜與青斗石欄板","贔屭馱著的「大明」墓道碑"],"funFact":"黃偉後來被神格化，汶源宮、慈德宮、壽溪宮都有供奉，朱子祠內也掛著「品德完人」匾。","photoSpot":"從墓埕下方仰拍層層升高的墓園","visitMin":25,"openNote":"位於金沙鎮太武山北麓斗門一帶的戶外墓園，官方未公布開放時間；民國98年（2009）修復時增設墓前廣場與解說設施。請保持肅靜，勿攀爬墓體與石獸；墓道碑周邊雜木較多，請注意腳下。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"金門有句俗諺：「文章許鍾斗，品德黃逸叟」，阿拉蕾聽過嗎？"},{"who":"R","text":"聽起來像在選模範生！黃逸叟是誰？"},{"who":"A","text":"就是黃偉，明正德9年的進士，當過南雄和松江知府。他當官清廉又敢直言，被稱為品德完人。"},{"who":"R","text":"這麼好的官，那他後來怎麼了呢？"},{"who":"A","text":"嘉靖16年泉州大饑荒，他出面協助賑災，積勞成疾，隔年就過世了。"},{"who":"R","text":"原來他是為了救災而倒下的，真令人敬佩。"},{"who":"A","text":"是啊。他的墓在太武山北麓，風水上叫飛鴉落田，墓埕還有石虎、石馬和墓筆。"},{"who":"R","text":"這裡有墓碑嗎？我繞了一圈，怎麼都沒看到名字？"},{"who":"A","text":"觀察得好，它跟一般明墓一樣沒設墓碑。去找找那匹石馬，看看牠是不是在低頭沉思！"}],"clues":["民間俗諺稱讚我的主人品德第一","我的墓埕有石虎、石馬，路旁還有贔屭馱碑","太武山北麓的飛鴉落田穴，明嘉靖年間建成"],"quiz":[{"q":"俗諺「品德○○○」說的是誰？","options":["許鍾斗","蔡復一","盧若騰","黃逸叟"],"answer":3,"explain":"「文章許鍾斗，品德黃逸叟」，黃逸叟即黃偉。"},{"q":"黃偉墓所在的風水穴位叫什麼？","options":["飛鴉落田","猛虎下山","金龜浮海","覆掌形"],"answer":0,"explain":"地形似鳥張翼，故稱飛鴉落田穴。"}],"images":[]},{"id":"jinsha-huangbianmu","name":"黃汴墓","short":"黃汴墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["墓葬"],"lat":24.49486,"lng":118.42076,"address":"金門縣金沙鎮英坑石鼓山腳","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-06-05/25640044-22ec-494e-ab4f-8bd2b5c22a9b/IMG_8215.jpg","year":1540,"yearText":"明嘉靖年間（確切年份不詳）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"俗稱馬仔墓、有石馬石羊的明代墓塋","intro":"黃汴墓位於金沙鎮英坑石鼓山腳，建於明嘉靖年間，俗稱「馬仔墓」。黃汴字梁輔，號東郊，明代浯洲汶水人，妻呂氏，長子就是有「品德完人」美稱的黃偉。官方說明指出，黃偉官至從四品的松江知府，黃汴應有相應品秩，依明代墓制可設石羊、石馬、石望柱各一對，現場又留有墓坊立柱構件，可知原應是有墓坊的明墓。墓塋由外而內為外埕、前埕、內埕、供桌、墓碑與墓龜，外埕兩側有石馬與石羊，內埕有石獅曲手，護牆兩端作龍首；墓碑中央浮雕重檐牌樓，內刻「文水黃公呂氏墓」。民國114年（2025）4月完成修復。","highlights":["外埕兩側的石馬與石羊","墓碑上浮雕的重檐牌樓與「文水黃公呂氏墓」","曲手上的石獅與護牆兩端的龍首"],"funFact":"黃汴墓俗稱「馬仔墓」，墓主正是「品德完人」黃偉的父親。","photoSpot":"在外埕拍石馬、石羊與墓碑同框","visitMin":15,"openNote":"位於金沙鎮英坑石鼓山腳的戶外墓園，官方未公布開放時間；附近有蘇寅賓墓。請保持肅靜，勿攀爬墓體與石獸。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，為什麼這座墓被叫作馬仔墓？"},{"who":"A","text":"這是地方上的俗稱，由來沒有明確記載。不過你看外埕兩側，有石馬也有石羊，很好認吧。"},{"who":"R","text":"原來如此，那這座墓的主人是誰呀？"},{"who":"A","text":"他叫黃汴，就是品德完人黃偉的爸爸。黃偉當到松江知府，他的墓也在金沙喔。"},{"who":"R","text":"兒子這麼有名，爸爸的墓也跟著升級了嗎？"},{"who":"A","text":"官方說明推測，黃汴依兒子品秩，可設石羊、石馬和望柱，現場還留著墓坊的柱子構件。"},{"who":"R","text":"原來墓前本來還有一座墓坊，好氣派！"},{"who":"A","text":"沒錯。墓碑中間還雕了一座重檐小牌樓，裡面刻著文水黃公呂氏墓。"},{"who":"R","text":"那我要到墓碑前面，仔細數數那座小牌樓到底有幾層屋簷！"}],"clues":["我的主人教出一位被稱為品德完人的兒子","我的墓碑上浮雕重檐牌樓，外埕有石馬石羊","英坑石鼓山腳、俗稱馬仔墓的明代墓塋"],"quiz":[{"q":"黃汴和黃偉是什麼關係？","options":["兄弟","祖孫","師生","父子"],"answer":3,"explain":"黃汴生三子，長子即品德完人黃偉。"},{"q":"黃汴墓的墓碑內刻什麼字？","options":["文水黃公呂氏墓","汶水黃氏祖墓","黃公暨安人陳氏墓","浯陽陳公之墓"],"answer":0,"explain":"墓碑中央浮雕牌樓內刻「文水黃公呂氏墓」。"}],"images":[]},{"id":"jincheng-xuxiemuyuwenzhang","name":"許獬墓與文章垂世孝友傳家坊","short":"許獬墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["牌坊","碑碣","墓葬"],"lat":24.41583,"lng":118.31524,"address":"金門縣金城鎮前山前測段65、65-1、66、69、70地號","announced":"2020-04-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20200502000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/282de3b6-5579-47fc-af20-38612ee60831/許獬墓與文章垂世孝友傳家坊封面.jpg","year":1606,"yearText":"1606年（明萬曆34年）","era":"dutch","themes":["墓葬","牌坊碑碣"],"yearUnknown":false,"summary":"金門唯一會元許獬的墓園與牌坊","intro":"許獬墓與文章垂世孝友傳家坊位於金城鎮前山前一帶。許獬（1570–1606）字子遜、號鍾斗，九歲能文，明萬曆29年（1601）會試第一，是金門也是同安唯一的會元，人稱「許會元」「許同安」，民間傳有「文章許鍾斗，品德黃逸叟」。他官至翰林院編修，後因思親成病請假返鄉，不久過世，年僅37歲。許獬與繼室蔡氏的合葬墓長年位於駐軍營區內，現存墓碑、墓桌、墓耳與墓手；文章垂世孝友傳家坊立在明代金門官道南線，曾只剩一根文筆柱單立。範圍還包括孺人顏氏墓、界石與墓道碑，是保存部分明末原物的系列遺產。","highlights":["立於明代官道上的文章垂世孝友傳家坊","高285公分、刻有24字的許獬墓道碑","疑為明代原物的墓桌與墓手"],"funFact":"許獬曾說：「取天下第一等名位，不若幹天下第一等事業，更不若做天下第一等人品。」","photoSpot":"在賢庵國小旁古官道拍牌坊與墓道碑","visitMin":20,"openNote":"位於金城鎮前山前一帶，官方資料記載戶外空間全天候開放；牌坊與墓道碑在賢庵國小旁的古官道上。顏氏墓與界石前方常有車輛停放，請注意勿碰撞古蹟。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，會元是什麼？跟狀元一樣厲害嗎？"},{"who":"A","text":"會元是會試第一名喔！明萬曆29年許獬在會試奪下第一，是金門、也是同安唯一的會元。"},{"who":"R","text":"哇，學霸中的學霸！他是不是從小就很會讀書？"},{"who":"A","text":"九歲就能寫文章，十三歲已經讀通經史。民間還有一句話：「文章許鍾斗，品德黃逸叟」。"},{"who":"R","text":"那他考上之後，有沒有當上大官呢？"},{"who":"A","text":"當到翰林院編修，可是他太想念父母，生病請假回鄉，不久就過世了，才37歲。"},{"who":"R","text":"好可惜，這麼有才華，卻這麼早就離開了。"},{"who":"A","text":"他說過，名位第一不如人品第一。這句話我常拿來勉勵自己少吃一塊貢糖，可惜每次都失敗。"},{"who":"R","text":"哈哈，人品要第一，貢糖也第一！那我去古官道找墓道碑，數數上面刻了幾個字！"}],"clues":["我的主人是金門、也是同安唯一的會試第一名","我的主人說，第一等人品勝過第一等名位","前山前的明代墓園，古官道上還立著一座傳家坊"],"quiz":[{"q":"許獬被稱為「許會元」，是因為他在哪一場考試奪魁？","options":["鄉試","會試","殿試","院試"],"answer":1,"explain":"萬曆29年辛丑科會試第一，稱為會元。"},{"q":"許獬過世時年僅幾歲？","options":["47歲","57歲","37歲","27歲"],"answer":2,"explain":"他思親成病請假歸鄉，不久過世，年僅37歲。"}],"images":[]},{"id":"jinsha-guanaolongfenggong","name":"官澳龍鳳宮","short":"官澳龍鳳宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["寺廟"],"lat":24.51828,"lng":118.41267,"address":"金門縣金沙鎮官澳16號","announced":"2007-09-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20070926000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-15/cd2221f4-dfeb-4897-baf9-8b4212fefca5/01封面.jpg","year":1611,"yearText":"1611年（明萬曆39年）","era":"dutch","themes":["宗教信仰"],"yearUnknown":false,"summary":"金門規模最大的媽祖廟，留有林天助壁畫","intro":"官澳龍鳳宮位於金沙鎮北岸的官澳聚落，面海坐落在花崗石平臺上。廟址原為清代《金門志》所載的天妃廟，創建於明萬曆39年（1611），是金門規模最大的媽祖廟。民國38年（1949）原供奉於西宮的廣澤尊王因西宮被拆而移駕至此，廟內主祀廣澤尊王與媽祖，因而得名「龍鳳宮」。每年農曆3月23日與8月22日設醮，由官澳與塘頭共八個甲頭供奉。民國67年（1978）重修，2012年完成整體修復。正殿與拜殿兩側的黑白水墨壁畫出自匠師林天助，目前部分保留原作。","highlights":["正殿與拜殿兩側林天助的黑白水墨壁畫","正門中堵螭虎鏤雕與門前一對抱鼓石","前、正殿屋脊上的火焰珠、寶塔與龍吻"],"funFact":"龍鳳宮的名字和婚姻無關，而是來自廟裡同時主祀廣澤尊王與媽祖兩位神明。","photoSpot":"在廟埕水池邊拍廟宇與澳口","visitMin":20,"openNote":"位於金沙鎮官澳聚落面海的澳口旁，依廟方時間開放參觀；參觀請保持安靜、尊重祭祀。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，龍鳳宮這個名字好喜氣，是專門保佑結婚的廟嗎？"},{"who":"A","text":"很多人都這樣猜！其實是因為廟裡同時主祀廣澤尊王和媽祖，兩位神明一起住，才叫龍鳳宮。"},{"who":"R","text":"原來是神明合租！他們一開始就住在一起嗎？"},{"who":"A","text":"不是喔。這裡原本是明萬曆39年建的天妃廟，民國38年廣澤尊王原本住的西宮被拆，才移駕過來。"},{"who":"R","text":"搬家搬到媽祖家，媽祖人真好。那廟裡有什麼必看的？"},{"who":"A","text":"正殿和拜殿兩側有黑白水墨壁畫，是匠師林天助的作品，只是保存不易，現在只有部分是原作。"},{"who":"R","text":"黑白水墨畫在廟裡，好像古代的連環漫畫！"},{"who":"A","text":"每年農曆3月23日和8月22日都會設醮。進廟後找找壁畫裡你最喜歡的人物，再看看門前那對抱鼓石吧！"}],"clues":["我的名字來自兩位主神，但我不是月老廟","我殿內有林天助的黑白水墨壁畫","我在金沙北岸澳口，原是明萬曆年間的天妃廟"],"quiz":[{"q":"「龍鳳宮」的名稱由來是？","options":["廟前有龍鳳石雕","建廟時龍鳳顯靈","主祀廣澤尊王與媽祖","捐建者名字有龍鳳"],"answer":2,"explain":"廟內主祀廣澤尊王與媽祖，因而得名龍鳳宮。"},{"q":"廟內黑白水墨壁畫出自哪位匠師？","options":["林天助","王益順","潘麗水","陳應彬"],"answer":0,"explain":"正殿與拜殿兩側水墨壁畫為林天助匠師所繪。"}],"images":[]},{"id":"jincheng-huangminggaozengyi","name":"皇明誥贈一品夫人曾氏墓","short":"曾氏墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["墓葬"],"lat":24.41797,"lng":118.3209,"address":"金門縣金城鎮庵前劃測段399地號（賢庵國小附近）","announced":"2017-02-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170207000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/e9b765c4-a8d5-4b35-8245-222f4434d8a8/(1)封面.jpg","year":1640,"yearText":"明末（確切年代不詳）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"洪旭祖母與伯父母同葬的明代墓","intro":"皇明誥贈一品夫人曾氏墓位於金城鎮庵前、賢庵國小附近。墓中共葬三人：洪旭的祖母曾氏，以及祔葬的洪旭伯父洪渭文（本名洪廷載）與伯母李氏。洪旭的父親洪公掄於明萬曆42年（1614）征戰海南島時陣亡，洪旭幼年喪父，由伯父撫育成人，視之如父。洪旭後來成為輔佐鄭氏的重要將領，祖母曾氏因而誥贈一品夫人。墓碑形式極簡，陰刻紅字「皇明」「誥贈一品夫人曾氏祔冢」「男渭文洪公暨婦李氏墓」，子與媳併葬母塚的例子少見。此墓原以「洪渭文墓」公告，2025年8月變更為現名。","highlights":["陰刻紅字、形式極簡的墓碑","碑首「皇明」與「誥贈一品夫人」字樣","外墓埕、內墓埕到墓龜的完整配置"],"funFact":"這座墓原本以伯父「洪渭文墓」公告，2025年改以輩分較高的祖母曾氏為名。","photoSpot":"在墓埕前拍極簡墓碑與紅字","visitMin":10,"openNote":"位於金城鎮庵前、賢庵國小附近，官方資料記載全天候開放。墓地仍有家族祭掃，請保持肅靜、勿踩踏墓體。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，這座墓碑看起來很簡單吧？但它背後有一段很溫暖的家族故事。"},{"who":"R","text":"墓碑上寫著「皇明」，所以是明朝的墓囉？裡面葬的是誰？"},{"who":"A","text":"葬了三個人，主角是洪旭的祖母曾氏，旁邊祔葬的是洪旭的伯父洪渭文和伯母李氏。"},{"who":"R","text":"為什麼伯父伯母會和祖母葬在一起呢？"},{"who":"A","text":"洪旭的父親在明萬曆42年征戰海南島時犧牲，洪旭是伯父帶大的，他把伯父當成親生父親一樣敬重。"},{"who":"R","text":"原來如此，難怪他這麼尊敬伯父。"},{"who":"A","text":"洪旭後來成為鄭氏重臣，祖母也因此誥贈一品夫人。這座墓原本叫洪渭文墓，2025年才改用祖母的名號。"},{"who":"R","text":"改名之後更符合輩分了！那我仔細看看墓碑上那三行紅字，各寫了些什麼！"}],"clues":["我原本以一位伯父的名字公告，後來改用祖母之名","我收葬一位撫育姪兒成人的伯父，姪兒後來成為鄭氏重臣","賢庵國小附近的明代墓，碑首刻著「皇明」二字"],"quiz":[{"q":"墓中的主角曾氏是洪旭的什麼人？","options":["母親","祖母","伯母","妻子"],"answer":1,"explain":"曾氏是洪旭的祖母，因孫而貴，誥贈一品夫人。"},{"q":"洪旭幼年喪父後，由誰撫育成人？","options":["鄭芝龍","外祖父","伯父洪渭文","老師盧若騰"],"answer":2,"explain":"洪旭年幼喪父，幸賴伯父洪渭文撫育成人。"}],"images":[]},{"id":"jincheng-houfengganghongxu","name":"後豐港洪旭古厝","short":"洪旭古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.41841,"lng":118.30146,"address":"金門縣金城鎮後豐港8、9號","announced":"2003-12-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170207000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-30/49b19332-9b27-44a0-b563-bbb6167d4451/01封面.jpg","year":1645,"yearText":"約1645年（明隆武元年，推論）","era":"dutch","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"輔佐鄭氏三代的洪旭明末大厝","intro":"後豐港洪旭古厝位於金城鎮後豐港聚落。洪旭（字弘藎）是南明武將，初為鄭芝龍部將，明隆武元年（1645）受封忠振伯，後輔佐鄭成功、鄭經，鄭成功東征臺灣時受命駐守廈門。他也曾倡議修建太武巖寺（今海印寺）與孚濟廟（今牧馬侯祠）。古厝落成年代無史料記載，推論是受封後興建，當時共建三座三落大厝，洪氏宗祠居中，南側這座由自家子嗣居住。建築為二落大厝與後座一落併列的類三落大厝，屋頂翹脊外加圓規以避免與宗祠對沖，官方稱金門民宅僅此與兄弟古厝兩例。主要木構估計至少是清中葉以前原物。","highlights":["翹脊外加圓規的屋頂，金門民宅僅見兩例","左右大規壁大量出磚入石的砌法","三開間退縮成檐廊的「直榻受」正立面"],"funFact":"後豐港洪氏以洪旭後裔人數最多，並以他的出仕燈號「滄江義門」作為支派燈號。","photoSpot":"退到埕前拍翹脊與圓規並存的屋頂","visitMin":15,"openNote":"位於金城鎮後豐港聚落，目前作祖厝祭祀使用，部分空間為私人工作室。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這間古厝的屋頂好像戴了兩頂帽子，中間翹翹的，兩邊又圓圓的？"},{"who":"A","text":"觀察力滿分！中間是翹脊，兩旁再加圓脊規壁，官方說金門民宅只有這裡和隔壁兄弟古厝兩例。"},{"who":"R","text":"為什麼要把屋頂弄得這麼複雜呢？"},{"who":"A","text":"因為旁邊就是洪氏宗祠，這樣做可以避免屋脊和宗祠對沖，算是建築界的禮讓三先。"},{"who":"R","text":"那屋主洪旭是什麼來頭的大人物？"},{"who":"A","text":"他是明末武將，輔佐鄭芝龍、鄭成功、鄭經三代，鄭成功東征臺灣時，他受命留守廈門。"},{"who":"R","text":"三代老臣耶！那這間房子有幾歲了？"},{"who":"A","text":"年代沒有文字紀錄，推論是他明隆武元年受封忠振伯之後興建，主要木構估計至少是清中葉以前的原物。"},{"who":"R","text":"那我站遠一點，數數看屋頂兩側各有幾壟筒瓦！"}],"clues":["我的主人輔佐過鄭氏三代，曾受封忠振伯","我的屋頂翹脊外加圓規，是為了避開隔壁宗祠","後豐港洪氏宗祠南側、由自家子嗣居住的明末大厝"],"quiz":[{"q":"古厝屋頂翹脊外加圓規，是為了什麼？","options":["增加排水","避免與宗祠對沖","防颱防風","顯示官階"],"answer":1,"explain":"以翹脊加圓規的做法，避免與鄰棟宗祠對沖。"},{"q":"鄭成功東征臺灣時，洪旭受命做什麼？","options":["駐守廈門輔佐鄭經","率兵先攻澎湖","出使日本通商","鎮守廣東南澳"],"answer":0,"explain":"洪旭受命駐守廈門，輔佐世子鄭經。"}],"images":[]},{"id":"jincheng-houfengganghongyun","name":"後豐港洪韻洪扆兄弟古厝","short":"洪韻洪扆古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.418661,"lng":118.301498,"address":"金門縣金城鎮後豐港11、12號","announced":"2017-02-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170207000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/08fdd4af-84b4-43d3-947b-7088a5d38ed3/後豐港洪韻洪扆兄弟古厝.jpg","year":1650,"yearText":"約17世紀中葉（明末）","era":"dutch","themes":["閩南古厝"],"yearUnknown":false,"summary":"洪旭贈給兄弟、樸拙的類三落大厝","intro":"後豐港洪韻洪扆兄弟古厝位於金城鎮後豐港聚落、洪氏宗祠右側，是洪旭贈給兄弟洪曦（字弘扆）、洪暄（字弘韻）居住的宅第，約落成於17世紀中葉。洪曦官至副將、都督同知，洪暄官至游擊將軍。古厝格局與洪旭古厝相仿，由雙落大厝與後一落二櫸頭併列成「類三落大厝」，雙落大厝由洪曦子孫居住，後落分給洪暄一脈。正立面與大規壁大量以出磚入石砌成，第一落正脊在圓脊內另收成翹脊，與洪旭古厝同為金門孤例。室內以菅蓁壁隔間、幾乎沒有裝飾，呈現早期樸拙的民宅風格。","highlights":["圓脊內再收翹脊、翹圓共存的屋面","正立面與大規壁的出磚入石牆","斗砌牆與亂石混砌的樸拙外牆"],"funFact":"依洪旭古厝的命名方式，這裡其實應稱「洪曦、洪暄兄弟古厝」，韻與扆都是兩人的字。","photoSpot":"在外埕拍出磚入石的正立面","visitMin":10,"openNote":"位於金城鎮後豐港聚落、洪氏宗祠右側，後落仍有人居住。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"來到後豐港，先考考你：洪韻、洪扆，是兩個人，還是同一個人的名字？"},{"who":"R","text":"聽起來像兩兄弟？Allan不要一來就出腦筋急轉彎啦！"},{"who":"A","text":"答對了！他們是洪旭的兄弟洪暄和洪曦，韻和扆其實是兩人的字，所以官方說這裡本該叫洪曦洪暄兄弟古厝。"},{"who":"R","text":"原來是用字來取名，有點像現在的網路暱稱耶！"},{"who":"A","text":"差不多啦。這間是洪旭送給兄弟住的，格局和隔壁洪旭古厝很像，前面雙落、後面一落並排。"},{"who":"R","text":"那牆壁怎麼紅紅灰灰的，磚頭和石頭混在一起？"},{"who":"A","text":"這叫出磚入石，用不同尺寸的石塊、磚和瓦一起砌，牆面又穩又好看，是金門老房子的拿手絕活。"},{"who":"R","text":"就像拼布一樣！那我來找找，牆上哪一塊石頭最大、哪一塊磚頭最小！"}],"clues":["我的名字用的是兩位主人的字，不是本名","一位忠振伯把我送給兩個弟弟居住","後豐港洪氏宗祠右側，出磚入石、翹脊與圓脊共存的明末大厝"],"quiz":[{"q":"這座古厝原本是洪旭送給誰居住？","options":["他的兒子們","他的部將們","他的老師們","他的兄弟們"],"answer":3,"explain":"洪旭將此宅贈與兄弟洪曦、洪暄居住。"},{"q":"以石塊、磚、瓦混砌成牆的做法稱為？","options":["斗子砌","一丁一順","出磚入石","人字砌"],"answer":2,"explain":"古厝外牆大量使用出磚入石，是金門營造特色。"}],"images":[]},{"id":"jinsha-caidiansuyinbingu","name":"蔡店蘇寅賓古厝與古墓","short":"蘇寅賓古厝與墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第","墓葬"],"lat":24.48555,"lng":118.42067,"address":"金門縣金沙鎮蔡店1號","announced":"2017-01-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170104000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-14/ef50b5d1-7701-48bb-a158-924a849ccfc5/蔡店蘇寅賓古厝與古墓.jpg","year":1650,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝","墓葬","名人故居"],"yearUnknown":true,"summary":"明末清官進士蘇寅賓的故居與明式古墓","intro":"蔡店蘇寅賓古厝與古墓位於金沙鎮蔡店聚落。蘇寅賓號日門，明萬曆40年（1612）中舉、47年（1619）登進士。《金門志》記載他任崑山知縣時守正不阿，因執法得罪權貴被貶，後累遷海南兵備道兼提學、湖廣糧儲道參議，辭官回鄉時「家無擔石」，享壽八十一。古厝興建年代不詳，為燕尾翹脊的雙落大厝，正面以磚砌出銅錢形花磚，大門掛「蘆山衍派」匾；正廳步口屋架外移一步擱在牆上，金門稱「大展步」。民國38年（1949）曾借國軍使用，民國78年（1989）後閒置。古墓在聚落東側石鼓山腳，為明墓形制，墓碑無明顯字跡。","highlights":["正面銅錢形花磚組砌與「蘆山衍派」匾額","燕尾翹脊的雙落大厝輪廓","古墓墓桌下緣正面的三組浮雕"],"funFact":"《金門志》記載他在崑山時螃蟹爬滿田埂吃稻禾，他向天祈禱為民請命，螃蟹離去，當年大豐收。","photoSpot":"在巷口拍燕尾翹脊與正面花磚","visitMin":20,"openNote":"古厝位於金沙鎮蔡店聚落，官方資料記載不開放參觀。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。古墓在聚落東側石鼓山腳，官方資料記載全天候開放，請保持肅靜、勿踩踏墓體。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，聽說這裡住過一位會「趕螃蟹」的官？"},{"who":"A","text":"哈哈，你說的是蘇寅賓。他是明萬曆年間的進士，當過崑山知縣，金門志有記載他的故事。"},{"who":"R","text":"趕螃蟹？螃蟹到底做了什麼壞事？"},{"who":"A","text":"那年螃蟹爬滿田埂吃稻子，他向天祈禱為百姓請命，螃蟹就離開了，當年還大豐收。"},{"who":"R","text":"早知道我也來祈禱，讓螃蟹自己跳進火鍋裡！"},{"who":"A","text":"你這是許願不是請命啦！他為官清廉，辭官回鄉時家無擔石，活到81歲。"},{"who":"R","text":"清官住的房子，看起來也很樸實嗎？有沒有什麼特別的？"},{"who":"A","text":"樸實中有細節，正面紅磚砌成銅錢形，屋脊是燕尾，大門上掛著「蘆山衍派」。"},{"who":"R","text":"那我要在外面找找銅錢形的花磚，數數一排有幾個銅錢！"}],"clues":["我家主人向天祈禱，讓爬滿田埂的螃蟹離開","我家大門掛著「蘆山衍派」，正面有銅錢形花磚","蔡店聚落裡明末進士的故居，聚落東側還有他的古墓"],"quiz":[{"q":"蘇寅賓在哪裡當知縣時遇上螃蟹食禾？","options":["崑山","同安","瓊州","寧波"],"answer":0,"explain":"金門志記載他任崑山令時禱天使螃蟹離去。"},{"q":"正廳步口屋架外移一步擱在牆上，金門稱為什麼？","options":["燕尾脊","大展步","出磚入石","半廳紅"],"answer":1,"explain":"這種步口屋架做法在金門特稱為大展步。"}],"images":[]},{"id":"jincheng-hanyingyungenmoya","name":"漢影雲根摩崖石刻群","short":"漢影雲根","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["碑碣"],"lat":24.393855,"lng":118.312654,"address":"金門縣金城鎮古崗東紅山麓","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000091","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/3ba01cdb-ceda-4989-8004-df95bfc0e9fb/(1)封面.png","year":1654,"yearText":"約1653–1654年（明永曆7至8年）","era":"zheng","themes":["摩崖石刻"],"yearUnknown":false,"summary":"南明魯王寄寓金門時留下的題字石刻","intro":"漢影雲根摩崖石刻群位於金城鎮古崗東紅山麓。南明監國魯王朱以海約1651年寄寓金門，常與遺臣遊歷古崗湖畔，約在明永曆7至8年間（1653–1654）於巨石題「漢影雲根」四字。遺臣諸葛倬、吳兆煒、鄭纘祖、鄭纘緒各賦七言律詩一首，刻於下方巨石，落款「永曆甲午仲秋朔日」（1654），同一巨石後方還有董颺先草書「湖海釣狂」。民國4年（1915）一場雷擊使原刻巨石崩落，僅存「漢影雲」三字倒臥於地；民國59年（1970）金門社教館在對面石壁描摹重鐫，並由書法家薛祖森補書「根」字，就是今天常見的版本。","highlights":["雷擊崩落後倒臥於地的原刻「漢影雲」三字","民國59年描摹重鐫、補書「根」字的版本","四位南明遺臣的「漢影雲根詠詩并序」"],"funFact":"民國4年雷擊後巨石被燻黑，當天古崗村恰有男嬰出生，家人因此替他取名「董烏石」。","photoSpot":"同框拍原刻倒石與對面重鐫版","visitMin":30,"openNote":"位於金城鎮古崗東紅山麓，官方資料記載全天候開放，與董颺先墓及周邊石刻同在步道範圍內。可開車或騎機車到古崗湖一帶再步行。","dialogue":[{"who":"A","text":"阿拉蕾，今天要帶你看一場真假石刻的推理劇，地點就在古崗湖旁的東紅山。"},{"who":"R","text":"真假石刻？難道有人偷偷做了山寨版？"},{"who":"A","text":"不是山寨，是重鐫版！南明魯王寄居金門時，在巨石上題了「漢影雲根」四個字。"},{"who":"R","text":"那原本魯王題字的那塊大石頭呢？"},{"who":"A","text":"民國4年被雷打中，巨石崩落，「根」字不見了，只剩「漢影雲」三個字倒在地上。"},{"who":"R","text":"被雷劈到！這比連續劇還要戲劇化耶！"},{"who":"A","text":"所以民國59年金門社教館在對面石壁描摹重刻，再請書法家薛祖森補上一個「根」字。"},{"who":"R","text":"原來大家平常合照的是二號版本！那原版也還看得到嗎？"},{"who":"A","text":"看得到，就倒在附近。今天的任務是把倒臥的原刻和重鐫版都找出來，比比看字有什麼不同！"}],"clues":["一位自去監國號的明朝宗室，在我身上留下四個字","民國4年的一道雷，讓我只剩三個字倒臥在地","古崗東紅山的南明題字，常見的是民國59年重鐫版"],"quiz":[{"q":"這四個大字原本是誰題的？","options":["鄭成功","董颺先","寧靖王","魯王朱以海"],"answer":3,"explain":"南明監國魯王寄寓金門時，於東紅山巨石題字。"},{"q":"原刻巨石在民國4年因為什麼崩落？","options":["雷擊","地震","砲擊","颱風"],"answer":0,"explain":"民國4年4月17日一陣雷擊，使巨石崩落。"}],"images":[]},{"id":"jincheng-mingdongyangxianmu","name":"明董颺先墓及周邊摩崖石刻群","short":"董颺先墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["墓葬","碑碣"],"lat":24.39245,"lng":118.31315,"address":"金門縣金城鎮古崗段864地號（部分）","announced":"2022-01-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20220131000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/69d82ed3-187e-4db9-a37d-4efacb6677c7/(1)封面.png","year":1656,"yearText":"約1646–1656年（明末南明時期）","era":"zheng","themes":["墓葬","摩崖石刻"],"yearUnknown":false,"summary":"鄭成功岳父董颺先的明代墓與石刻","intro":"明董颺先墓及周邊摩崖石刻群位於金城鎮古崗東紅山一帶。董颺先是泉州晉江人，明崇禎10年（1637）進士，隆武朝任禮部右侍郎。明隆武2年（1646）福州被清軍攻克後，他避居浯洲，因與古坑董氏同宗而定居今古崗。據他自撰的世次記載，長女董友是鄭成功的正室、鄭經之母，兩人是父女關係。他以裝瘋表明不仕清廷，魯王曾贈匾「風高五柳」。墓碑題「明沙河子歸真」，屬明代墓塋規制；周邊13處石刻有6處落款董颺先，如「高一層」「明臣董子」，見證明末遺臣避世隱居的心境。","highlights":["墓碑中心隸書「明沙河子歸真」","東紅山路口相傳通往桃林的「古桃源」石刻","頭巾山上的「第一峯」與峰下岩洞"],"funFact":"「第一峯」下的天然岩洞，八二三砲戰期間曾作為古崗村公所的民防指揮部。","photoSpot":"在觀止步道拍巨巖上的題刻","visitMin":40,"openNote":"位於金城鎮古崗東紅山一帶，官方資料記載全天候開放；石刻多分布在觀止步道沿線，部分在頭巾山與古崗湖畔。墓塋仍有祭祀，請保持尊重。可開車或騎機車到古崗湖一帶再步行。","dialogue":[{"who":"R","text":"Allan，這塊大石頭上刻著「且向上看」，是在叫我抬頭嗎？"},{"who":"A","text":"哈，算是一種人生建議吧！這附近的石頭刻了13處字，很多出自明末進士董颺先之手。"},{"who":"R","text":"董颺先？名字好難念，他到底是誰啊？"},{"who":"A","text":"他是鄭成功的岳父！依他自己寫的世次記載，長女董友就是鄭成功的正室、鄭經的媽媽。"},{"who":"R","text":"哇，原來是國姓爺的丈人！那他怎麼會跑來金門？"},{"who":"A","text":"清軍攻下福州後，他避居金門古崗，還故意裝瘋，表示不願意替清朝做官。"},{"who":"R","text":"裝瘋是為了守住氣節，好有個性的老先生！"},{"who":"A","text":"他過世後葬在東紅山，墓碑寫「明沙河子歸真」。我們沿著觀止步道散步，順便找石刻。"},{"who":"R","text":"那我的任務就是找到落款「明臣董子」的那一塊，拍下來給大家看！"}],"clues":["我的主人是鄭成功正室的父親","我的主人以裝瘋表明不仕清廷，魯王贈他「風高五柳」","古崗東紅山的明代墓塋，墓碑題「明沙河子歸真」"],"quiz":[{"q":"董颺先和鄭成功是什麼關係？","options":["翁婿","叔姪","師生","同窗"],"answer":0,"explain":"董颺先長女董友是鄭成功正室，兩人為翁婿。"},{"q":"董颺先墓碑中心題刻的文字是？","options":["明臣董子","風高五柳","古桃源","明沙河子歸真"],"answer":3,"explain":"墓碑中心以隸書題刻「明沙河子歸真」。"}],"images":[]},{"id":"jincheng-qingjinmenzhenzong","name":"清金門鎮總兵署","short":"金門鎮總兵署","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["衙署"],"lat":24.43225,"lng":118.31836,"address":"金門縣金城鎮浯江街53號","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/46747672-9f80-455d-a141-7d1d1d85c15e/01封面.jpg","year":1682,"yearText":"1682年（清康熙21年）改建","era":"qing","themes":["公共建築","城池衛所"],"yearUnknown":false,"summary":"明代會元故宅改建的清代軍政中心","intro":"清金門鎮總兵署位於金城鎮浯江街，清康熙21年（1682）總兵陳龍以明末會元許獬的故宅「叢青軒」改建而成。總兵署原設在金門所城，清初遷界毀城、港口淤淺，加上後浦形勢較佳，於康熙19年（1680）移駐後浦；族譜另記與陳龍盼求子嗣、相信後浦風水有關，並於農曆四月十二日將城隍分火到後浦，衍生出今日的迎城隍。同治7年（1868）改為協鎮署，民國後陸續作為縣公署、警察局等。建築以中軸四進配置，頭門、大堂仍具閩南衙署風格，內署保留清同光年間形貌，2004年開放為史料館。","highlights":["中軸線上頭門、大堂、內署相連的衙署格局","以蠟像重現的總兵審案與生活情境","水師提督與海盜蔡牽主題的互動展示"],"funFact":"後浦每年農曆四月十二迎城隍，相傳源自總兵署移駐後浦時，把城隍爺分火過來奉祀。","photoSpot":"在頭門外拍三川脊與中軸甬道","visitMin":40,"openNote":"位於金城鎮浯江街，現為清金門鎮總兵署史料館，官方資料記載每日09:00至22:00開放。可從金城車站步行前往，鄰近模範街與朱子祠。","dialogue":[{"who":"A","text":"阿拉蕾，歡迎來到清代金門的最高軍政中心，金門鎮總兵署。"},{"who":"R","text":"總兵署？是金門最大的官上班的地方嗎？"},{"who":"A","text":"對，清代金門鎮總兵就在這裡辦公。有趣的是，它原本是明朝會元許獬的書齋叢青軒。"},{"who":"R","text":"書房變衙門？讀書人知道了會不會氣到跳腳？"},{"who":"A","text":"哈哈，清康熙年間總兵署從金門城搬到後浦，原因之一是舊城港口淤淺，後浦形勢比較好。"},{"who":"R","text":"那除了港口，還有其他搬家的原因嗎？"},{"who":"A","text":"族譜說總兵陳龍盼望生兒子，聽說後浦人丁旺、地氣佳就搬來了，還把城隍分火過來，才有四月十二迎城隍。"},{"who":"R","text":"原來迎城隍是這樣來的！那裡面可以看什麼？"},{"who":"A","text":"有蠟像重現總兵審案和生活，還有蔡牽主題的互動遊戲。請你找找地牢在哪裡，體驗一下當犯人的感覺！"}],"clues":["我原本是一位明代會元的書齋","我搬家後城隍爺也跟著分火，衍生出一場熱鬧的迎神","後浦浯江街的清代衙署，現為史料館"],"quiz":[{"q":"總兵署是由誰的故宅改建而成？","options":["許獬","盧若騰","林斐章","邱良功"],"answer":0,"explain":"總兵陳龍以許獬故宅叢青軒改建為總兵署。"},{"q":"後浦迎城隍是在農曆哪一天？","options":["正月十五","三月二十三","四月十二","七月十五"],"answer":2,"explain":"城隍分火到後浦那天，成為後浦城隍爺生日。"}],"images":[{"file":"清金門鎮總兵署1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bc/%E6%B8%85%E9%87%91%E9%96%80%E9%8E%AE%E7%B8%BD%E5%85%B5%E7%BD%B21.jpg/960px-%E6%B8%85%E9%87%91%E9%96%80%E9%8E%AE%E7%B8%BD%E5%85%B5%E7%BD%B21.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B8%85%E9%87%91%E9%96%80%E9%8E%AE%E7%B8%BD%E5%85%B5%E7%BD%B21.jpg","artist":"Jennifer25172466","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-qingjinmenzhenzong-0.webp","small":"img/jincheng-qingjinmenzhenzong-0-s.webp"}]},{"id":"jincheng-luruotengguzhaiji","name":"盧若騰故宅及墓園","short":"盧若騰故宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第","墓葬"],"lat":24.41671,"lng":118.31052,"address":"金門縣金城鎮賢庵村賢聚9號","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-31/5d13858b-3a88-485e-860b-a5a0183e7bf7/盧若騰故宅及故居 (1).jpg","year":1684,"yearText":"清康熙年間（1683年後遷葬）","era":"qing","themes":["名人故居","墓葬"],"yearUnknown":false,"summary":"明末孤臣「盧菩薩」的故居與墓園","intro":"盧若騰故宅及墓園位於金城鎮賢庵村賢聚。盧若騰（1600–1664）號牧洲、留庵，明崇禎13年（1640）41歲才中進士，為官耿直敢言，在浙江寧紹一帶任官時剔奸抑豪，被譽為「盧菩薩」。南明時任浙東巡撫，溫州城破時身受箭傷，退隱金門。1664年隨寧靖王等人東渡，途經澎湖時病逝。清康熙22年（1683）海禁解除後，其子赴澎湖負骨歸葬賢庵村北，孫輩才立碑，題「奉 有明自許先生 牧洲盧公之墓 遺命勒石」，不書名而稱「自許先生」。故宅為一落四櫸頭加牆規樓，門楣題「留庵故居」，2013年修復時將正身屋脊復原為翹脊。","highlights":["門楣「留庵故居」額題與門埕旗桿石座","墓碑「奉 有明自許先生 牧洲盧公之墓」","墓手三曲半的石蓮與石印柱頭"],"funFact":"墓碑刻意不寫本名，只稱「自許先生」；民國59年蔣中正巡視時囑咐整修，並立解說牌。","photoSpot":"在故宅外拍「留庵故居」門楣","visitMin":20,"openNote":"位於金城鎮賢庵村賢聚。故宅仍由盧氏後裔居住、未開放，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；墓園為開放空間，請保持肅靜。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這裡的墓碑怎麼寫「自許先生」？自許是他的名字嗎？"},{"who":"A","text":"不是喔，墓主是明末的盧若騰。墓碑故意不寫本名，只稱自許先生，表現他一生的傲骨。"},{"who":"R","text":"好神秘！他做了什麼事，這麼有骨氣？"},{"who":"A","text":"他41歲才中進士，大器晚成。在浙江當官時打擊豪強、減輕賦稅，老百姓叫他「盧菩薩」，還幫他蓋祠堂。"},{"who":"R","text":"被叫菩薩，那一定是超級好官！後來呢？"},{"who":"A","text":"南明時溫州城破，他中箭受傷，退回金門隱居。1664年東渡時，在澎湖病逝。"},{"who":"R","text":"那他最後怎麼又回到家鄉金門了呢？"},{"who":"A","text":"清康熙22年海禁解除後，他兒子到澎湖把遺骨帶回來，葬在賢庵村北，所以這裡同時有故居和墓園。"},{"who":"R","text":"原來是兒子接爸爸回家！那我去故居外面，找找門楣上的「留庵故居」四個字！"}],"clues":["我的墓碑不寫本名，只稱「自許先生」","我的主人在浙江為官，被百姓譽為「盧菩薩」","賢聚村的「留庵故居」與牧洲公墓園"],"quiz":[{"q":"盧若騰在浙江為官時，被百姓譽為什麼？","options":["盧菩薩","盧青天","盧聖人","盧大俠"],"answer":0,"explain":"他剔奸抑豪、輕賦贖鍰，被譽為盧菩薩。"},{"q":"盧若騰東渡時在哪裡病逝？","options":["金門","廈門","臺南","澎湖"],"answer":3,"explain":"他隨寧靖王等人東渡，在澎湖停留時病發而卒。"}],"images":[{"file":"盧若騰故宅 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/%E7%9B%A7%E8%8B%A5%E9%A8%B0%E6%95%85%E5%AE%85_%28cropped%29.jpg/960px-%E7%9B%A7%E8%8B%A5%E9%A8%B0%E6%95%85%E5%AE%85_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%9B%A7%E8%8B%A5%E9%A8%B0%E6%95%85%E5%AE%85_(cropped).jpg","artist":"Koala0090","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-luruotengguzhaiji-0.webp","small":"img/jincheng-luruotengguzhaiji-0-s.webp"}]},{"id":"jinsha-wangshijiegucuoyu","name":"王世傑古厝與古墓","short":"王世傑古厝與墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["其他設施"],"lat":24.47955,"lng":118.38894,"address":"金門縣金沙鎮浦邊39、40號","announced":"2007-09-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20070926000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-15/6ac09d06-a96e-47cf-b9dc-7a65f9714a4a/01封面.jpg","year":1700,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝","墓葬","名人故居"],"yearUnknown":true,"summary":"新竹開墾先驅王世傑的金門祖厝","intro":"王世傑古厝與古墓位於金沙鎮浦邊聚落與太武山北麓一帶。王世傑生於明末，明永曆36年（1682）隨鄭克塽部隊北上征戰，運糧有功，獲准「跑馬定界」墾荒，看中竹塹（今新竹）附近的沖積地。清康熙50年（1711）他帶領100多位族親到竹塹開墾，墾田數千甲，並設公田把收益寄回家鄉，供照顧親族、祭祖與修祖厝之用。官方認為祖厝保留明末清初的建築形式與構法，為二落大厝加雙突歸，右突歸大規壁採出磚入石砌法；左突歸清末曾作鴉片館，失火燒毀。古墓有龜殼狀墓龜與半月形墓池。古厝於民國101年（2012）修復完成。","highlights":["右突歸大規壁的出磚入石砌法","前埕牆上以煙炙磚砌成的花窗","古墓的半月形墓池與左右曲手"],"funFact":"「跑馬定界」是以騎馬奔馳的起止路線當作墾地界線，王世傑因運糧有功獲准這樣劃地。","photoSpot":"在屋外拍右突歸的出磚入石牆面","visitMin":20,"openNote":"古厝位於金沙鎮浦邊聚落，仍作居住使用，官方開放資訊為「依屋主作息時間」。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。古墓位於太武山北麓一帶，官方資料記載全天開放，周邊為放牧區，請保持肅靜、勿踩踏墓體。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，新竹的人為什麼會來金門找祖先？"},{"who":"A","text":"因為開墾新竹的重要人物王世傑，老家就在金沙浦邊，這棟就是他的祖厝。"},{"who":"R","text":"他怎麼會跑去新竹？那時候又沒有飛機。"},{"who":"A","text":"明永曆36年，他隨鄭克塽部隊運糧有功，獲准跑馬定界，用騎馬跑的路線圈地開墾。"},{"who":"R","text":"騎馬圈地？那他一定很希望馬可以跑久一點！"},{"who":"A","text":"哈哈，那匹馬壓力應該很大。清康熙50年，他帶100多位族親到竹塹開墾，墾田數千甲。"},{"who":"R","text":"他在新竹發財以後，還會記得金門的家鄉嗎？"},{"who":"A","text":"會喔，他設了公田，把收入寄回金門，拿來照顧親族、冬至祭祖和修祖厝。"},{"who":"R","text":"那我要去看右邊突歸的牆，找找石頭和紅磚混著砌的出磚入石！"}],"clues":["我家主人靠著騎馬劃界，換來一大片墾地","我家主人在竹塹墾田數千甲，還設公田照顧家鄉","浦邊的二落大厝加雙突歸，是新竹開墾者的祖厝"],"quiz":[{"q":"王世傑帶族親開墾的竹塹是今天哪裡？","options":["桃園","苗栗","新竹","臺中"],"answer":2,"explain":"王世傑在竹塹，也就是今天的新竹開墾。"},{"q":"王世傑用什麼方式照顧家鄉親族？","options":["興建書院","設立公田","開設當鋪","捐建碼頭"],"answer":1,"explain":"他設公田，把收益寄回家鄉祭祖、修祖厝。"}],"images":[]},{"id":"jinhu-liaoluowushiliulu","name":"料羅吳氏六路大厝","short":"料羅六路大厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.41718,"lng":118.43565,"address":"金門縣金湖鎮料羅100、101號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-14/dc43aa9f-d671-4ba8-96d1-eeb11117e6cd/料羅吳氏六路大厝.jpg","year":1750,"yearText":"約18世紀中葉（清乾隆年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"六道木構牆撐起的海商祖公厝，金門唯一","intro":"料羅吳氏六路大厝位於金湖鎮料羅聚落，吳氏先祖源自閩北蓁嶼，清初以航運起家。料羅地處閩北往臺灣水路的中點，吳家自清乾隆初年在此購地建屋，大厝成為經營臺海貿易的中軸要站，族人稱它「祖公厝」，鼎盛時有五、六十人同住。建築為五開間雙落帶雙陟歸與雙護龍，因有六道縱向牆體而得名，是當地最大民宅；六路牆體全為穿斗式木構造，在金門僅此一例。戰後曾作國軍住所、派出所與村辦公處，單打雙不打時期屋頂曾被宣傳彈擊中。現為家族祭祀與儲物空間，2026年8月完成修復。","highlights":["六道縱向牆體全為穿斗式木構造，金門唯一","後落與櫸頭間跨距超過2公尺的大展步巷頭","榻受對看堵「松鶴延年」與「福祿長壽」泥塑"],"funFact":"民國30年以前吳氏還沒有宗祠，祖先牌位都供在這座大厝的廳堂裡，所以叫它「祖公厝」。","photoSpot":"在前埕拍五開間雙落的寬闊正面","visitMin":20,"openNote":"位於金湖鎮料羅聚落，為吳氏家族祭祀與儲物空間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶與族人祭祀。","dialogue":[{"who":"A","text":"阿拉蕾，我們到料羅了。猜猜看，眼前這座大厝為什麼叫「六路大厝」？"},{"who":"R","text":"因為門口有六條路？還是可以同時開六條公車路線？"},{"who":"A","text":"都不是啦！是屋子裡有六道縱向牆，而且六道全是木頭做的穿斗式構造，在金門只有這一座。"},{"who":"R","text":"全木頭的牆，那蓋房子的人一定很有錢吧？"},{"who":"A","text":"吳家清初就跑船做生意，料羅剛好在閩北到臺灣航線的中點，清乾隆年間蓋好這裡，當成臺海貿易的大本營。"},{"who":"R","text":"原來是海上貿易公司的總部！裡面住了多少人？"},{"who":"A","text":"最熱鬧時有五、六十人，比我家吃年夜飯還擠。後來還當過派出所和村辦公處，屋頂也被宣傳彈打中過。"},{"who":"R","text":"這房子的履歷表也太精采了！現在還有人住嗎？"},{"who":"A","text":"現在是家族祭祀和放東西的地方，2026年8月才修復完成。請在屋外數數看，正面一共有幾開間吧。"}],"clues":["我曾是航運家族經營臺海貿易的中軸要站","我的六道縱向牆全是穿斗式木構造，金門唯一","我在料羅，吳氏宗親叫我祖公厝"],"quiz":[{"q":"「六路大厝」的名稱是怎麼來的？","options":["門前有六條道路","家族有六個房派","屋內有六道縱向牆體","興建花了六年"],"answer":2,"explain":"因有六道縱向牆體與左右護龍，稱為六路大厝。"},{"q":"料羅吳氏先祖清初靠什麼行業起家？","options":["航運","農耕","製鹽","釀酒"],"answer":0,"explain":"吳氏先祖清初以航運為業，家業因而大興。"}],"images":[]},{"id":"jinning-gulongtoushuiweita","name":"古龍頭水尾塔","short":"古龍頭水尾塔","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["其他設施"],"lat":24.476513,"lng":118.312014,"address":"金門縣金寧鄉古寧國民小學南側","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-16/f3e525fe-0f7d-4b7d-9705-41ade7b5974f/01封面.jpg","year":1765,"yearText":"清乾隆年間（1735～1796）","era":"qing","themes":["宗教信仰","聚落地景"],"yearUnknown":false,"summary":"刻著佛法僧寶的花崗石風水塔，古寧頭入口地標","intro":"古龍頭水尾塔位於金寧鄉古寧村，在雙鯉古地關帝廟右側，是進入南山、北山聚落的地標。依《金門縣志》記載，塔建於清乾隆年間。1953年以前雙鯉湖尚未築堤成湖，這裡原是港灣，水尾塔就位在港灣入口，退潮時村民可沿塔旁石板路前往關帝廟。塔為花崗石砌的四邊形實心方塔，頂層塔身四面刻「佛」「法」「僧」「寶」，屬於具厭勝作用的風水塔，早年也可作為潮汐水位觀測與航海指標。每年農曆六月二十四日關聖帝君誕辰醮慶，也有祭祀水尾塔的習俗。1983年由李敏捷匠師修繕，抬高基座並設階梯步道。","highlights":["頂層整塊花崗石四面刻佛、法、僧、寶","葫蘆形塔尖與梟混線腳的塔簷、塔座","1983年修繕後加設的兩層臺基與九階石梯"],"funFact":"雙鯉湖築堤以前，這裡是港灣入口，水尾塔還能幫村民看潮汐、指引船隻。","photoSpot":"從關帝廟旁斜角拍石塔與葫蘆塔尖","visitMin":15,"openNote":"位於金寧鄉古寧村、古寧國小南側，官方資料記載全天候開放。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"R","text":"Allan，這座小石塔好可愛，看起來像一支插在地上的大毛筆！"},{"who":"A","text":"這個比喻很有創意。它是古龍頭水尾塔，清乾隆年間就在這裡，是進南山、北山聚落的地標。"},{"who":"R","text":"塔上面刻了四個字耶，佛、法、僧、寶，是佛教的意思嗎？"},{"who":"A","text":"對，佛法僧就是三寶。它是一座風水塔，有厭勝鎮煞的作用，守護村子。"},{"who":"R","text":"可是旁邊是湖，為什麼要在水邊蓋塔？"},{"who":"A","text":"1953年以前雙鯉湖還沒築堤，這裡是港灣入口。塔可以看潮汐、當航海指標，是古早的導航系統。"},{"who":"R","text":"古代版導航！那現在還有人拜它嗎？"},{"who":"A","text":"有喔，每年農曆六月二十四關帝誕辰醮慶，也會祭祀水尾塔。請你繞塔一圈，確認四個字各在哪一面。"}],"clues":["雙鯉湖築堤以前，我站在港灣入口看潮汐","每年農曆六月二十四，關帝廟醮慶時也會祭祀我","我是花崗石方塔，頂層四面刻佛法僧寶"],"quiz":[{"q":"水尾塔頂層塔身四面刻的是哪四個字？","options":["福、祿、壽、喜","佛、法、僧、寶","東、南、西、北","風、調、雨、順"],"answer":1,"explain":"頂層四面刻佛、法、僧、寶，即佛教三寶。"},{"q":"除了風水作用，水尾塔早年還有什麼功能？","options":["存放糧食","點火傳遞烽火","觀測潮汐與航海指標","收藏族譜"],"answer":2,"explain":"塔位於港灣入口，可供村民觀測潮汐水位並作航海指標。"}],"images":[{"file":"古龍頭水尾塔..DSC 1928.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/%E5%8F%A4%E9%BE%8D%E9%A0%AD%E6%B0%B4%E5%B0%BE%E5%A1%94..DSC_1928.jpg/960px-%E5%8F%A4%E9%BE%8D%E9%A0%AD%E6%B0%B4%E5%B0%BE%E5%A1%94..DSC_1928.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%A4%E9%BE%8D%E9%A0%AD%E6%B0%B4%E5%B0%BE%E5%A1%94..DSC_1928.jpg","artist":"顏錫沂2","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinning-gulongtoushuiweita-0.webp","small":"img/jinning-gulongtoushuiweita-0-s.webp"}]},{"id":"jinning-panshanwengshijia","name":"盤山翁氏家廟","short":"盤山翁氏家廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["祠堂"],"lat":24.447397,"lng":118.338608,"address":"金門縣金寧鄉頂堡101號","announced":"2020-03-05","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20200409000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-10/cd71318d-1543-4583-8e0c-6b64889c2b23/1.盤山翁氏家廟-代表圖像.jpg","year":1772,"yearText":"1772年（清乾隆37年）遷建現址","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"保有1930年代原貌木雕的罕見宗祠","intro":"盤山翁氏家廟位於金寧鄉盤山村頂堡，清雍正8年（1731）初建於今廣濟廟旁，清乾隆37年（1772）遷至現址，道光14年（1834）眾議重修，到同治元年（1862）才完竣。1920至1930年代修繕時留下立面馬約利卡彩瓷與木質彩繪，1981年再修屋頂。在許多宗祠大幅翻修的風潮下，它的主要構造與裝飾仍屬1930年代或更早的原物，是金門罕見的孤例。正廳前四點金柱採「披麻捉灰」工法，廟中保存四方清代中晚期古匾。祖龕奉祀翁氏開浯始祖康叟公，每年農曆九月初九忌辰舉行祭祖、頒發獎學金，晚上還有「食頭」宴。","highlights":["正廳前四點金柱的「披麻捉灰」工法","四方清代中晚期古匾與「六桂堂」祖龕擂金木雕","翹脊上面朝外的龍隱，寓意子孫向外發展"],"funFact":"翹脊上的龍隱刻意面朝外，寓意子孫向外蓬勃發展；照壁上還留著軍管時期的泥塑標語。","photoSpot":"在前埕拍前亭翹脊龍隱與彩瓷立面","visitMin":20,"openNote":"位於金寧鄉盤山村頂堡，由翁氏宗親會管理使用，平日未必開門，請在外觀參觀；每年農曆九月初九祭祖期間請勿打擾儀式。可騎機車或開車前往。","dialogue":[{"who":"A","text":"盤山頂堡這座翁氏家廟，最厲害的不是新，而是它很「捨不得換」，留住了將近百年前的原貌。"},{"who":"R","text":"捨不得換？Allan，你是說它跟你一樣，衣服穿到變古董嗎？"},{"who":"A","text":"哈，差不多。金門很多宗祠後來都大翻修，這裡的木雕彩繪卻還是1930年代或更早的原物。"},{"who":"R","text":"那這座家廟最早是什麼時候蓋的？"},{"who":"A","text":"清雍正8年初建，乾隆37年，也就是1772年遷到這裡，後來重修還花了將近30年。"},{"who":"R","text":"修30年！那工人師傅都從年輕修到變爺爺了吧。"},{"who":"A","text":"正廳前的四點金柱用「披麻捉灰」的工法做成，是金門早期宗祠的特色，還有四方清代古匾。"},{"who":"R","text":"那翁家人什麼時候會回來這裡團聚？"},{"who":"A","text":"每年農曆九月初九祭祖，還發獎學金、辦食頭宴。請你抬頭找找，翹脊上的龍隱臉朝哪個方向？"}],"clues":["我在1772年遷到現址，重修前後花了將近30年","我的四點金柱用披麻捉灰工法，翹脊龍隱面朝外","我在盤山頂堡，每年農曆九月初九祭康叟公"],"quiz":[{"q":"盤山翁氏家廟每年祭祖是在哪一天？","options":["農曆正月十五","農曆三月初三","農曆七月十五","農曆九月初九"],"answer":3,"explain":"每年農曆九月初九康叟公忌辰於家廟舉行祭祖典禮。"},{"q":"家廟正廳前四點金柱採用什麼傳統工法？","options":["剪黏貼瓷","披麻捉灰","洗石子","交趾燒"],"answer":1,"explain":"正廳前四點金柱以披麻捉灰工法製作，是金門早期宗祠特色。"}],"images":[]},{"id":"jinsha-xiaoputouhuangyun","name":"小浦頭黃允棋古厝","short":"黃允棋古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.48955,"lng":118.412,"address":"金門縣金沙鎮成功路3號","announced":"2015-09-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150922000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/a44398fd-5aa4-4499-99d4-f219f93feced/01封面.jpg","year":1773,"yearText":"約1773年（清乾隆38年）竣工，後裔推估","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"救人一命換來一座六路大厝的傳說","intro":"小浦頭黃允棋古厝位於金沙鎮沙美小浦頭聚落。黃允棋（1720–1787）為開浦第九世，家境清寒。據後裔口述，某年寒流時妻子楊氏在池邊發現一名病倒的福州人，黃家救回照料數月，又典當女兒嫁妝資助他返鄉；多年後此人再訪，運來建材與匠師為黃家蓋屋，傳為地方美談。後裔推估古厝約於清乾隆38年（1773）竣工。建築為雙落六路大厝帶左右突歸，原為三落，第三落在八二三砲戰中全毀，二落背面仍留有三道通往第三落的門。正廳次間房比明間廳更深，為金門少見格局。","highlights":["二落背面三道通往已毀第三落的門","前後廳中堵上方少見的「菅蓁牆」做法","榻受水車堵與山牆脊墜的精美泥塑"],"funFact":"1937年後浦頭黃氏家廟被日軍占用，開浯始祖守恭公曾暫奉祀在這座古厝廳堂達三年。","photoSpot":"在屋外拍榻受泥塑與山牆脊墜","visitMin":15,"openNote":"位於金沙鎮沙美小浦頭聚落。私人住宅，目前無人居住、由屋主定期祭祀，2024年5月起進行修復工程；請在外觀參觀，勿擅入，施工期間請注意安全。可搭金門縣公車到沙美一帶，或開車、騎機車前往。","dialogue":[{"who":"A","text":"今天講個好人有好報的故事。據黃家後代口述，清乾隆年間某個寒流早上，黃允棋的太太在池邊發現一個病倒的外地人。"},{"who":"R","text":"天那麼冷，好危險！Allan，他們有救他嗎？"},{"who":"A","text":"有，全家把他抬回家照顧了好幾個月。那人想回福州，黃家沒錢，還把女兒的嫁妝拿去典當給他當旅費。"},{"who":"R","text":"自己都吃不飽還幫別人，太善良了吧！"},{"who":"A","text":"過了幾年那人回來了，看黃家十幾個孩子擠一間小屋，就運來建材和師傅，幫他們蓋了這座大厝。"},{"who":"R","text":"這是古代版的報恩神劇！那房子蓋得怎麼樣？"},{"who":"A","text":"是雙落六路大厝，原本還有第三落，可惜在八二三砲戰時全毀，第二落背面那三道門就是當年通往第三落的。"},{"who":"R","text":"原來門後面曾經還有一整落房子，好令人感慨。"},{"who":"A","text":"古厝正在修復，請在屋外欣賞就好。找找榻受上的精美泥塑，再回味一次這段報恩故事吧。"}],"clues":["據說有人為了報答救命之恩，替我的主人運來建材和師傅","我原有三落，第三落毀於八二三砲戰","我是小浦頭聚落清乾隆年間的六路大厝"],"quiz":[{"q":"據口述，黃家為了資助落難者返鄉典當了什麼？","options":["祖傳田產","家中耕牛","祖先牌位","女兒的嫁妝"],"answer":3,"explain":"黃允棋夫婦典當女兒嫁妝，資助落難者返鄉。"},{"q":"古厝原本的第三落是怎麼消失的？","options":["被颱風吹垮","毀於八二三砲戰","拆除改建馬路","白蟻蛀蝕倒塌"],"answer":1,"explain":"此屋初建為三落，第三落因八二三砲戰全毀。"}],"images":[]},{"id":"jinhu-dongcunlvshiyigu","name":"東村呂世宜古厝","short":"呂世宜古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.42711,"lng":118.44554,"address":"金門縣金湖鎮東村16號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/c0ad5124-4246-43b9-8aa9-a23b1607806d/1.jpg","year":1780,"yearText":"約18世紀（清乾隆年間或更早）","era":"qing","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"臺灣書法宗師呂世宜的東村故里","intro":"東村呂世宜古厝位於金湖鎮東村聚落，是清代書法家呂世宜的故里宅邸，也有一說是他的出生宅。呂世宜（1784－1855）號西村，自幼移居廈門，1822年（清道光2年）中舉，精通金石之學，尤工篆隸。他應板橋林家之邀任西席，寓居臺灣十多年，把畢生收藏的古書與金石拓本留在臺灣，帶動隸書與金石學風氣，被奉為金石書法宗師。古厝為金門典型的一落四櫸頭，外牆花崗石人字砌，形式儉樸。大門上方原懸1822年的「文魁」匾，2016年莫蘭蒂颱風時被吹落，僅存殘蹟。古厝目前受損嚴重，已加設鋼棚架保護。","highlights":["大門上方1822年「文魁」匾的殘蹟與精美花座木雕","四面外牆的花崗石人字砌與轉角水平砌","正廳穿斗式木棟架與菅蓁壁的早期民居作法"],"funFact":"呂世宜的隸書影響臺灣深遠，有人稱他的字體為「呂體」，瓊林新倉上二房宗祠的堂聯也出自他手。","photoSpot":"在屋前拍文魁匾位置與人字砌石牆","visitMin":15,"openNote":"位於金湖鎮東村聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築受損嚴重並設有鋼棚架，請勿靠近。","dialogue":[{"who":"R","text":"Allan，這間古厝看起來好樸素，沒什麼雕花耶，為什麼會是古蹟？"},{"who":"A","text":"別看它低調，這是清代書法家呂世宜的老家。他的字在臺灣書法界可是宗師等級。"},{"who":"R","text":"金門人怎麼會變成臺灣的書法宗師？"},{"who":"A","text":"他受板橋林家邀請去當老師，在臺灣住了十多年，還把一輩子收藏的金石拓本留在臺灣，帶動了研究隸書的風氣。"},{"who":"R","text":"哇，等於把整座圖書館打包送給臺灣！"},{"who":"A","text":"形容得好。大門上原本掛著他1822年中舉的「文魁」匾，可惜2016年莫蘭蒂颱風把它吹落，只剩一點殘蹟。"},{"who":"R","text":"颱風太過分了！那現在古厝還好嗎？"},{"who":"A","text":"受損蠻嚴重，已經加了鋼棚架保護。請在屋外看看石牆，找出排成人字形的花崗石，像不像一排排的魚骨頭？"}],"clues":["我門上原本的文魁匾被2016年的颱風吹落","我是一落四櫸頭的樸素古厝，石牆用人字砌","主人在東村出身，後來成為臺灣金石書法宗師"],"quiz":[{"q":"呂世宜受哪個家族邀請到臺灣任教？","options":["霧峰林家","鹿港辜家","基隆顏家","板橋林家"],"answer":3,"explain":"呂世宜應板橋林家之邀任西席，寓居臺灣十多年。"},{"q":"古厝的「文魁」匾在哪一年被颱風吹落？","options":["2016年","2010年","2019年","2023年"],"answer":0,"explain":"2016年莫蘭蒂颱風將文魁匾吹落，僅留局部殘蹟。"}],"images":[]},{"id":"jinning-liguangxiangujuji","name":"李光顯故居及墓園","short":"李光顯故居","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["宅第","墓葬"],"lat":24.4785,"lng":118.31204,"address":"金門縣金寧鄉古寧村北山25-1號","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2018-01-15/f4c7f5e3-4c86-469e-8a90-bfe18708b65b/李光顯故居.jpg","year":1790,"yearText":"約1789～1794年（清乾隆54～59年）","era":"qing","themes":["名人故居","墓葬","閩南古厝"],"yearUnknown":false,"summary":"清代廣東水師提督李光顯的振威第與墓園","intro":"李光顯故居及墓園位於金寧鄉古寧村北山。李光顯（1757～1819），清乾隆42年（1777）從軍，熟悉潮汐海象，常自請駕艇出海巡哨。林爽文事件時駐守打鼓汛，嘉慶年間追剿縱橫閩浙粵的海盜蔡牽一黨，與姨表兄弟、浙江提督邱良功一同搜捕餘黨，清嘉慶21年（1816）升任廣東水師提督。他為官廉潔，卒於任所時兩袖清風，由粵商代為收殮歸葬，誥贈振威將軍，故居因此稱「振威第」。故居約建於1789至1794年間，為三落大厝，1950年代初曾充作國民學校校舍，後來軍隊進駐、改作理髮部，1995年完成整體修復，與墓葬一同指定為縣定古蹟。","highlights":["榻受正中書卷式門匾「振威第」","背立面兩根角柱刻有「石敢當」三字","屏門上方橫批窗的柿蒂與錢紋「雙只折交」"],"funFact":"李光顯清廉到去世時兩袖清風，是感念他的廣東商人出錢替他收殮、送回金門安葬。","photoSpot":"在前埕正面拍書卷式門匾「振威第」","visitMin":20,"openNote":"位於金寧鄉古寧村北山聚落。官方資料未載明開放時間，內部是否開放請以現場公告為準；請在外觀參觀，勿打擾周邊住戶。參觀墓園請保持肅靜。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"A","text":"這棟三落大厝門上寫著「振威第」，主人李光顯是從小兵一路升到廣東水師提督的古寧頭人。"},{"who":"R","text":"從小兵變提督？這根本是古代版的勵志升級遊戲！"},{"who":"A","text":"他從小在海邊長大，懂潮汐和航海，常自己駕船出海巡邏，後來還追剿海盜蔡牽一黨。"},{"who":"R","text":"那他一定賺很多錢，才能蓋這麼大的房子吧？"},{"who":"A","text":"剛好相反，他很清廉。清嘉慶24年他死在任上，兩袖清風，是廣東商人感念他，出錢送他回鄉安葬。"},{"who":"R","text":"哇，好感人。那振威第這個名字是怎麼來的？"},{"who":"A","text":"他死後被追贈振威將軍。後來這裡還當過學校教室和理髮部，比我的履歷還精彩。"},{"who":"R","text":"在提督家剪頭髮，Allan 你應該很想去，可是你已經光頭了。"},{"who":"A","text":"被你發現了。請你繞到房子背面，找找兩根角柱上刻的三個字是什麼？"}],"clues":["我的主人從小兵做起，追剿過海盜蔡牽","主人死後被追贈將軍，我也有了「振威第」之稱","我在古寧頭北山，主人官至廣東水師提督"],"quiz":[{"q":"李光顯最後升到什麼官職？","options":["福建陸路提督","廣東水師提督","金門鎮總兵","臺灣府知府"],"answer":1,"explain":"清嘉慶21年李光顯擢升廣東水師提督。"},{"q":"李光顯過世後，是誰出資替他收殮歸葬？","options":["朝廷特別撥款","金門宗親集資","感念他的粵商","邱良功獨力負擔"],"answer":2,"explain":"他為官廉潔、兩袖清風，由感念恩德的粵商代為收殮歸葬。"}],"images":[]},{"id":"jinsha-cangxinggucuo","name":"藏興古厝","short":"藏興古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.51874,"lng":118.41406,"address":"金門縣金沙鎮官澳73號","announced":"2015-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150211000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-04-11/823bd50a-ce6e-42bf-846e-b58006005100/藏興古厝.jpg","year":1790,"yearText":"約1785–1795年（清乾隆50至60年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"俗諺「官澳富，藏興厝」的雙落雙護龍大宅","intro":"藏興古厝位於金沙鎮官澳聚落，由官澳楊氏十七世楊廣理約於清乾隆50至60年（1785–1795）間開始興建，歷經後代接手、費時十年才完成這座雙落雙護龍大宅。「藏興」之名與先人楊亮節隱居官澳後改名「允藏」有關，也寓含「藏富待興」。楊廣理經商成為官澳首富，曾捐資在楊氏祠堂設私塾，為今述美國小前身；家族後來經營鹽場、當鋪、榨油與釀酒等產業，俗諺稱「官澳富，藏興厝」。古厝面寬約25公尺，前落三開間退縮作展步，以斗栱出簷，後落束隨雕有暗八仙法器。民國112年（2023）11月完成整體修復。","highlights":["雙落雙護龍、面寬約25公尺的完整格局","前落三開間退縮的展步與斗栱出簷","護龍外牆的花崗石人字砌與煙炙磚斗砌"],"funFact":"地方還有俗諺「上藏興，下當舖」，說的就是官澳楊氏家族當年的興盛。","photoSpot":"站在前埕外拍雙護龍環抱的全景","visitMin":15,"openNote":"位於金沙鎮官澳聚落，民國112年（2023）修復完成，官方未公布開放時間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，金門老一輩有句話：「官澳富，藏興厝」，你猜是什麼意思？"},{"who":"R","text":"官澳很有錢，所以大家都去藏興厝借錢？"},{"who":"A","text":"哈哈，方向對了一半！意思是說官澳的富，就要看藏興厝，屋主楊廣理經商成為官澳首富。"},{"who":"R","text":"首富住的房子，一定大得不得了吧？"},{"who":"A","text":"雙落雙護龍，面寬約25公尺，從清乾隆年間開工，經過兩代人、花了十年才完成。"},{"who":"R","text":"十年！落成那天大家應該是感動到哭著放鞭炮。"},{"who":"A","text":"楊廣理也很重視教育，在楊氏祠堂設私塾，就是今天述美國小的前身。"},{"who":"R","text":"有錢又出錢讓鄉親的孩子讀書，這才是真正的富！"},{"who":"A","text":"說得好！到現場找找前落屋簷下的斗栱，看它們怎麼把屋簷撐出來。"}],"clues":["老俗諺說「官澳富」，後面接的就是我","我的主人楊廣理是官澳首富，也捐資辦私塾","官澳聚落裡清乾隆年間興建的雙落雙護龍大宅"],"quiz":[{"q":"這座古厝屬於哪一種格局？","options":["一落四櫸頭","二落大厝","雙落雙護龍","六路大厝"],"answer":2,"explain":"藏興古厝為雙落雙護龍，在地區少見。"},{"q":"楊廣理捐資設立的私塾是今天哪所學校的前身？","options":["述美國小","安瀾國小","金沙國中","多年國小"],"answer":0,"explain":"他在楊氏祠堂設私塾，為今述美國小前身。"}],"images":[]},{"id":"jinsha-huangxuanxianliulu","name":"黃宣顯六路大厝","short":"黃宣顯六路大厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.487098,"lng":118.414641,"address":"金門縣金沙鎮后浦頭3號","announced":"2006-06-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060613000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-06-06/f57d70fb-d8ae-423d-9d31-7ae8c136ad98/代表圖片.jpg","year":1790,"yearText":"1792年以前（清乾隆年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"清乾隆年間的六路大厝，如今是中醫診所","intro":"黃宣顯六路大厝位於金沙鎮后浦頭聚落，由黃宣顯在清乾隆57年（1792）以前興建，原為五開間的「六路大厝」帶雙護龍。黃宣顯在家中排行第七，父親曾官拜「翰外郎」，家族為地方望族；曾孫黃熙懷在五口通商後不久即前往印尼發展，後代分在印尼、新加坡打拚。約民國30年（1941）左護龍毀損，民國81年（1992）因鄉村改建改為水溝，現為六路大厝帶右護龍。大厝紅瓦翹脊，脊肚飾剪黏花鳥，水車堵頭塑有「福、祿、禎、祥」四字，呈現清乾隆年間民居構材壯碩、裝飾樸實的特色。民國103年（2014）修復後作為中醫診所。","highlights":["水車堵堵頭的「福、祿、禎、祥」泥塑","脊肚剪黏花鳥與紅瓦翹脊","五開間大厝與右護龍並列的格局"],"funFact":"「六路大厝」指的就是五開間的大厝，這座兩百多年的老屋如今是看診中的中醫診所。","photoSpot":"在前埕外拍五開間大厝正面","visitMin":15,"openNote":"位於金沙鎮后浦頭聚落，修復後作為中醫診所使用，官方資料記載依診所看診時間參訪，參訪時請勿影響醫師與看診民眾；非看診需求請在外觀參觀，勿擅入其他空間。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，聽說這棟古厝裡面可以看醫生，是真的嗎？"},{"who":"A","text":"真的，它現在是中醫診所！這是清乾隆年間黃宣顯蓋的六路大厝，修復後再利用。"},{"who":"R","text":"在兩百多年的老房子裡把脈，會不會特別準？"},{"who":"A","text":"哈哈，這我可不敢保證。六路大厝就是五開間的大厝，原本左右還各有一條護龍。"},{"who":"R","text":"你說原本？那現在是少了一邊護龍嗎？"},{"who":"A","text":"左護龍大約民國30年就因年久失修毀損，民國81年又改成水溝，現在只剩右護龍。"},{"who":"R","text":"那黃家的後代，後來都去了哪裡發展？"},{"who":"A","text":"曾孫黃熙懷在五口通商後不久就到印尼發展，後代在印尼和新加坡打拚。"},{"who":"R","text":"我不吵醫生，只在外面找找「福、祿、禎、祥」四個泥塑字！"}],"clues":["我已經兩百多歲，現在每天還有人來看診","我是五開間的大厝，左護龍已毀，只剩右護龍","后浦頭聚落清乾隆年間興建的五開間大厝"],"quiz":[{"q":"這座大厝今天作為什麼用途？","options":["中醫診所","文學館","民俗館","村公所"],"answer":0,"explain":"民國103年修復後再利用為中醫診所。"},{"q":"「六路大厝」指的是哪一種建築？","options":["六落深的大厝","五開間的大厝","六座相連的厝","六條巷子的厝"],"answer":1,"explain":"官方說明六路大厝即五開間之大厝。"}],"images":[]},{"id":"jincheng-qiulianggonggucuo","name":"邱良功古厝","short":"邱良功古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.43263,"lng":118.31792,"address":"金門縣金城鎮浯江街23、25、27、29號","announced":"2006-06-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20110906000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-05-07/95c5828b-01b4-4454-8f59-6b7df726319f/代表圖片-邱良功古厝.jpg","year":1797,"yearText":"約1797年（清嘉慶2年）或更早","era":"qing","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"浙江水師提督邱良功當小官時的簡樸舊宅","intro":"邱良功古厝位於金城鎮後浦城區浯江街，在清金門鎮總兵署西側。邱良功（1769–1817）是後浦人，出生35天即喪父，由母親許氏撫養長大，從金門鎮標補伍做起，後任浙江水師提督，1809年與福建水師聯手剿滅海盜蔡牽，受封三等男爵。古厝推測建於清嘉慶2年（1797）或更早，是他官位還小時的房舍，構造簡樸。相傳他受封後想擴建爵府，因一戶鄰居不肯賣地而作罷，朝廷所賜兩塊雕龍聖旨石後來嵌在井邊牆角。古厝由左右兩棟大厝組成，2014年修復完成，右大厝現為金門傳統音樂館。","highlights":["左大厝公媽廳、右大厝神明廳，兩棟並列夾一條巷道","嵌在古井旁牆角的雙龍青斗石聖旨石","花崗石門框的牆規樓與煙炙磚框窗"],"funFact":"邱良功受封後想把舊宅擴建成男爵府，卻因一戶鄰居不肯賣地，計畫只好擱置。","photoSpot":"浯江街上拍兩座牆規樓並列的入口","visitMin":20,"openNote":"位於金城鎮後浦城區浯江街，總兵署西側。目前仍有人居住，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；右大厝作為金門傳統音樂館，官方資料記載週三、週五晚上18:30–20:30開放參觀。從金城車站步行可達。","dialogue":[{"who":"R","text":"Allan，總兵署旁邊這兩棟房子好樸素喔，真的是大將軍的家嗎？"},{"who":"A","text":"問得好！這是邱良功古厝，推測1797年或更早就蓋好了，那時他還只是個小官。"},{"who":"R","text":"小官住小房子，很合理。那他後來當到多大的官？"},{"who":"A","text":"他當到浙江水師提督，1809年和福建水師聯手剿滅海盜蔡牽，受封三等男爵。"},{"who":"R","text":"男爵耶！那一定把房子改建成超大豪宅了吧？"},{"who":"A","text":"他本來想擴建爵府，結果有一戶鄰居就是不肯賣地，計畫只好擱著。官再大，也拗不過一個堅持的鄰居。"},{"who":"R","text":"哈哈，這位鄰居也太有個性了！那朝廷送的東西還在嗎？"},{"who":"A","text":"朝廷賜的兩塊雕龍聖旨石，後代把它嵌在古井旁的牆角保存。右邊那棟現在是金門傳統音樂館。"},{"who":"A","text":"平常請在外面欣賞就好。任務來了，找找兩棟大厝中間那條小巷道，從巷口拍一張照吧！"}],"clues":["我的主人出生35天就失去父親，由母親撫養長大","主人後來剿滅海盜蔡牽，受封三等男爵","我在總兵署西側，兩棟大厝之間夾著一條巷道"],"quiz":[{"q":"邱良功想擴建爵府，為什麼作罷？","options":["經費不足","颱風毀損","朝廷不准","一戶鄰居拒絕賣地"],"answer":3,"explain":"因一戶鄰居不肯讓售，擴建府第之事只好擱置。"},{"q":"古厝的右大厝現在作為什麼使用？","options":["金門傳統音樂館","金門民俗文物館","後浦僑鄉展示館","金城鎮里辦公處"],"answer":0,"explain":"右大厝作為金門傳統音樂館，週三、週五晚上開放。"}],"images":[{"file":"邱良功古厝.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/%E9%82%B1%E8%89%AF%E5%8A%9F%E5%8F%A4%E5%8E%9D.jpg/960px-%E9%82%B1%E8%89%AF%E5%8A%9F%E5%8F%A4%E5%8E%9D.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%82%B1%E8%89%AF%E5%8A%9F%E5%8F%A4%E5%8E%9D.jpg","artist":"寺人孟子","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-qiulianggonggucuo-0.webp","small":"img/jincheng-qiulianggonggucuo-0-s.webp"}]},{"id":"jinhu-caipanlongmu","name":"蔡攀龍墓","short":"蔡攀龍墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["墓葬"],"lat":24.451874,"lng":118.410915,"address":"金門縣金湖鎮太武山武揚道旁","announced":"1991-11-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19911123000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/fccdfb98-7a43-480b-b300-8073b978090c/01封面.jpg","year":1799,"yearText":"1799年（清嘉慶4年）","era":"qing","themes":["墓葬"],"yearUnknown":false,"summary":"漁夫出身的「蔡老虎」提督長眠於太武山下","intro":"蔡攀龍墓位於金湖鎮北太武山下的翠谷，鄰近明德公園。蔡攀龍（1738－1798）號躍州，瓊林人，少年家貧以捕魚為業，受岳父鼓勵從軍，因勇武一路升遷。1786年林爽文事件爆發，時任澎湖右營遊擊的他奉命率軍七百渡臺，作戰身先士卒，有「蔡老虎」之稱，獲賜「健勇巴圖魯」名號並列名紫光閣功臣像。後降調江南狼山鎮總兵，1798年卒於任內，翌年歸葬。墓為清代三合碑形制，由墓碑、墓桌、二道曲手與一對石獅立柱組成，墓桌雕雙龍交尾。2016年颱風吹倒右側立柱，墓園位於軍事管制範圍。","highlights":["三塊花崗石拼成、山峰形的三合碑","墓桌正面海棠紋框中的雙龍交尾浮雕","八角柱身頂端立著石獅的一對立柱"],"funFact":"蔡攀龍年輕時挑擔進城叫賣，岳父看中他的相貌，才鼓勵他去從軍，從此改寫人生。","photoSpot":"無法進入時可欣賞官方照片中的石獅立柱","visitMin":10,"openNote":"位於金湖鎮太武山武揚道旁，墓園在軍事管制範圍內，平時無法自由進入，請遵守軍方管制規定，勿擅闖。","dialogue":[{"who":"A","text":"阿拉蕾，妳覺得一個以捕魚為生的窮少年，有可能變成一品大官嗎？"},{"who":"R","text":"聽起來像逆襲小說！難道金門真的有這個人？"},{"who":"A","text":"有，他叫蔡攀龍，瓊林人。年輕時挑擔子進城做小生意，岳父看他長得威武，鼓勵他去從軍。"},{"who":"R","text":"岳父的眼光也太準了吧！那後來呢？"},{"who":"A","text":"他作戰勇猛，大家叫他「蔡老虎」。1786年林爽文事件時，他奉命帶兵渡海來臺灣，後來畫像還被掛進紫光閣。"},{"who":"R","text":"蔡老虎，聽起來比你的綽號光頭大叔威風多了。"},{"who":"A","text":"我認輸。他1798年在江南任上過世，隔年歸葬太武山下。墓前有一對頂著石獅的立柱，可惜右邊那根在2016年被颱風吹倒。"},{"who":"R","text":"那我們現在可以走過去看看他的墓嗎？"},{"who":"A","text":"墓園在軍事管制區，平時不能自由進入。請你在官方照片裡找找，石獅蹲在柱子的哪個位置。"}],"clues":["我年輕時以捕魚為業，後來畫像進了紫光閣","我有個威風的綽號，跟一種猛獸有關","我是瓊林出身的清代提督，長眠在太武山下的軍事管制區"],"quiz":[{"q":"蔡攀龍因作戰勇猛而得到什麼綽號？","options":["海上蛟龍","金門雄獅","鐵面將軍","蔡老虎"],"answer":3,"explain":"他每戰身先士卒，贏得「虎將」與「蔡老虎」之名。"},{"q":"蔡攀龍從軍前以什麼維生？","options":["捕魚","種田","讀書","打鐵"],"answer":0,"explain":"蔡攀龍少時家貧，以捕魚為業。"}],"images":[]},{"id":"jincheng-houpulinfeizhangda","name":"後浦林斐章大宅","short":"林斐章大宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.433354,"lng":118.318753,"address":"金門縣金城鎮珠浦北路12巷2號","announced":"2023-05-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20230611000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-06-12/7a8873aa-a536-49ca-bf15-91e891a7ca45/DSC_8318.jpg","year":1800,"yearText":"約清代中葉（推測18世紀末至19世紀初）","era":"qing","themes":["閩南古厝","宗祠家廟","名人故居"],"yearUnknown":false,"summary":"捐建奎閣的鄉賢林斐章家宅與家祠","intro":"後浦林斐章大宅位於金城鎮珠浦北路巷內。林斐章（1760–1838）的先祖於清初自福建永春遷居後浦，傳到他以經商起家，曾捐得例貢生，地方稱其家族為「後浦三林」。《金門志》記他「富而好義，年施棺木無算」，清道光16年（1836）更獨資捐銀千圓創建奎閣，大廳門額「振起斯文」木匾即為紀念。宅第興建年代無史料記載，若建於他在世期間則為清代中葉，大致維持清代風貌。因前埕侷促，另設非中軸的牆規樓為主入口，牆身以玄武石採龜殼六角形砌法，形制少見。這裡也曾是林氏族人祭祖之處。","highlights":["玄武石龜殼六角形砌法的牆規樓","泉州白石裙堵與幾何形磚組砌的對看堵","水車堵與拱仔頭的精美泥塑"],"funFact":"民國38年後，宅第左前房曾借給正氣中華報記者居住，門樓上還掛過報社招牌。","photoSpot":"在巷內拍龜殼紋牆規樓","visitMin":10,"openNote":"位於金城鎮珠浦北路巷內，後浦市區。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可從金城車站步行前往。","dialogue":[{"who":"R","text":"Allan，這面牆的石頭好特別，一格一格的，好像烏龜殼耶！"},{"who":"A","text":"眼睛真利！這是牆規樓，用玄武石砌成龜殼六角形，是林斐章大宅的大門。"},{"who":"R","text":"咦，大門為什麼不開在房子的正中間呢？"},{"who":"A","text":"因為前埕太窄了，只好在旁邊另開一座門樓當主入口，官方說這種格局在金門很少見。"},{"who":"R","text":"原來是空間不夠，只好變通一下。那林斐章是誰呀？"},{"who":"A","text":"清代後浦的商人，很樂善好施，金門志記載他每年施捨棺木多到數不清，還獨資捐銀千圓蓋了奎閣。"},{"who":"R","text":"奎閣就是拜魁星爺的地方吧？那他是金門讀書人的大恩人耶！"},{"who":"A","text":"沒錯，所以大廳掛了「振起斯文」匾。這裡現在還是私人住宅，我們在巷子裡安靜欣賞就好。"},{"who":"R","text":"好，那我來數一數，這面龜殼牆上大概有幾格六角形！"}],"clues":["我的主人每年施捨棺木，還獨資捐建奎閣","我的大門不在中軸線上，牆面像烏龜殼","後浦三林家族的清代宅第，大廳掛著「振起斯文」"],"quiz":[{"q":"林斐章獨資捐建了哪座建築？","options":["朱子祠","奎閣","浯江書院","觀音亭"],"answer":1,"explain":"清道光16年他獨資捐銀千圓，在後浦創建奎閣。"},{"q":"大宅牆規樓的玄武石採用什麼砌法？","options":["人字形砌法","出磚入石","龜殼六角形砌法","一丁一順"],"answer":2,"explain":"牆規樓牆身由玄武石採龜殼六角形砌法。"}],"images":[]},{"id":"jinsha-pubianzhouzhai","name":"浦邊周宅","short":"浦邊周宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.48061,"lng":118.39009,"address":"金門縣金沙鎮浦邊95號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-16/82e01a0e-d9bb-4dfe-9995-4e455441e03f/01封面.jpg","year":1809,"yearText":"約1805–1813年（清嘉慶10至18年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"典當富商家族一路加蓋的三落大厝","intro":"浦邊周宅位於金沙鎮浦邊聚落。浦邊周氏堂號「濂溪」，族人周全斌曾輔佐鄭成功父子，清康熙3年（1664）率部歸清並受封。周宅興建人推測是經營典當業的富商周文與長子周弁，周弁並擁有田園與鹽埕，推測此宅原是他為長子周高堂結婚準備的新居。最早的二落大厝約建於清嘉慶10至18年（1805–1813），清道光9年（1829）增建第三落與「五間」，右突歸年代不可考。今為三落大厝加右突歸，前埕有圍牆環繞，前落門頭堵中央是「五獅漫步山林」泥塑，脊肚飾有花鳥、蝙蝠泥塑與剪黏。民國93年（2004）完成修復。","highlights":["前落門頭堵中央「五獅漫步山林」泥塑","脊肚的花鳥、蝙蝠、果供泥塑與剪黏","前埕圍牆下段的人字形石砌"],"funFact":"周宅推測是周弁為長子周高堂結婚準備的新居，後來又陸續加蓋，成了三落大厝。","photoSpot":"在前埕圍牆外拍三落大厝翹脊","visitMin":15,"openNote":"位於金沙鎮浦邊聚落，官方未公布開放時間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，如果有人送你一棟大房子當結婚禮物，你會怎麼想？"},{"who":"R","text":"我會想，Allan你是不是又在作白日夢了？"},{"who":"A","text":"哈哈，在浦邊還真有。周宅推測就是周弁為長子周高堂結婚準備的新居。"},{"who":"R","text":"哇，這個爸爸也太大手筆了吧！周家是做什麼的？"},{"who":"A","text":"周文、周弁父子經營典當業，還有田園和鹽埕，那時是周家最輝煌的時候。"},{"who":"R","text":"難怪房子這麼大，從前埕看進去，前前後後好像有好幾進耶。"},{"who":"A","text":"最早的二落大厝約在清嘉慶年間蓋好，清道光9年又加了第三落和旁邊的五間。"},{"who":"R","text":"一路加蓋，簡直是一棟會長大的房子！"},{"who":"A","text":"等一下看看前落門頭，中央泥塑是五隻獅子漫步山林，數數看是不是真的五隻！"}],"clues":["我原本可能是一份新婚禮物，後來一路加蓋","我的主人家族以典當業致富，堂號是濂溪","浦邊聚落的三落大厝，門頭有五獅漫步山林泥塑"],"quiz":[{"q":"興建周宅的周文、周弁父子以什麼行業致富？","options":["航運業","橡膠業","釀酒業","典當業"],"answer":3,"explain":"周文是經營典當業的富商，周弁繼承家業。"},{"q":"周宅前落門頭堵中央的泥塑主題是什麼？","options":["五獅漫步山林","雙龍搶珠","八仙過海","麒麟獻瑞"],"answer":0,"explain":"門頭堵中央以泥塑表現五獅漫步山林。"}],"images":[]},{"id":"jinning-yanghuaguju","name":"楊華故居","short":"楊華故居","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["宅第"],"lat":24.45692,"lng":118.30618,"address":"金門縣金寧鄉湖浦村湖下114號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-05-25/d7317daa-0345-456c-82c3-646c2ac0b13e/楊華故居.jpg","year":1811,"yearText":"約1811年（清嘉慶16年）","era":"qing","themes":["名人故居","閩南古厝"],"yearUnknown":false,"summary":"清代江南提督楊華退休後興建的三落大厝","intro":"楊華故居位於金寧鄉湖浦村湖下聚落。楊華（1745～1826），字良淵，號鳳山，從基層汛兵做起，三十多歲仍是從九品外委，乾隆末年參與平定林爽文事件後升任千總；嘉慶年間沿海海盜猖獗，他身經百戰，五十歲後一路升遷，清嘉慶10年（1805）授蘇松總兵，奉命署江南提督。墓誌銘稱他不建豪宅遺子孫，故居推測是致仕後約1811年所建。建築面寬約18公尺、縱深約38公尺，為三落大厝左側增單邊護龍，護龍後方設八卦廳。前方原有圍牆與龍虎門，已遭拆毀，只留門臼痕跡。2001年起由縣府委託調查研究並進行修復。","highlights":["第二落脊墜的泥塑「獬豸啣鏡」，象徵公正清廉","門廳螭虎團爐透雕木窗、鰲魚插角與垂花吊筒","護龍最後方與第三落平行的八卦廳"],"funFact":"第二落脊墜上的獬豸啣鏡，獬豸與明鏡高懸都象徵公正清廉，很符合主人的形象。","photoSpot":"在大埕拍三落大厝正面與翹脊","visitMin":20,"openNote":"位於金寧鄉湖浦村湖下聚落。官方資料記載需事先預約聯絡參觀；未預約請在外觀參觀，勿擅入、勿打擾後方住戶。可騎機車或開車前往，湖下也是金門大橋的金門端起點一帶。","dialogue":[{"who":"R","text":"Allan，湖下這棟大厝好長喔，一眼望不到底耶！"},{"who":"A","text":"它縱深大約38公尺，是三落大厝，主人楊華是清代從小兵做起，最後署理江南提督的將領。"},{"who":"R","text":"又是小兵逆襲的故事！金門是不是專門出產將軍？"},{"who":"A","text":"可以這麼說。楊華三十多歲還只是從九品的外委，五十歲以後才官運大開，算是大器晚成。"},{"who":"R","text":"五十歲才發達，Allan 你還有希望喔！加油加油！"},{"who":"A","text":"謝謝鼓勵。他的墓誌銘說他不建豪宅留給子孫，所以這棟房子推測是退休後養老才蓋的。"},{"who":"R","text":"那房子上有什麼可以代表他的裝飾嗎？"},{"who":"A","text":"第二落的脊墜有「獬豸啣鏡」，象徵公正清廉。請你抬頭找找，那隻神獸嘴裡是不是咬著一面鏡子？"}],"clues":["我的主人三十多歲還是外委，五十歲後才一路高升","我的脊墜上有獬豸啣鏡，還藏著一間八卦廳","我在湖下，主人曾任蘇松總兵、署江南提督"],"quiz":[{"q":"楊華故居第二落脊墜的「獬豸啣鏡」象徵什麼？","options":["多子多孫","公正清廉","招財進寶","驅風避邪"],"answer":1,"explain":"獬豸與明鏡高懸都有公正、清廉的象徵。"},{"q":"楊華故居護龍最後方設有什麼特殊空間？","options":["八卦廳","藏書樓","練武場","銃樓"],"answer":0,"explain":"護龍最後方與第三落平行處設有八卦廳。"}],"images":[]},{"id":"jinhu-qiulianggongmuyuan","name":"邱良功墓園","short":"邱良功墓園","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["墓葬"],"lat":24.44983,"lng":118.38607,"address":"金門縣金湖鎮太武山麓小徑村旁","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000088","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/41d39ca4-ee2a-4c84-9e59-c91e430a904e/01封面.jpg","year":1819,"yearText":"1819年（清嘉慶24年）","era":"qing","themes":["墓葬"],"yearUnknown":false,"summary":"金門清代墳塋形制最完整的墓園","intro":"邱良功墓園位於金湖鎮太武山麓的小徑村旁。邱良功（1769－1817）號琢齋，金門後浦人，27歲起隨軍出海緝捕海盜，嘉慶年間隨浙江水師提督李長庚追剿橫行臺海的蔡牽集團；李長庚戰歿後，他與王得祿接手，1809年平定蔡牽集團，獲封三等男爵。1817年病逝於江蘇，朝廷追贈建威將軍、諡剛勇，並賜神道碑兩通，1819年歸葬金門。墓園背山面水，墓前排列文官、武官、石馬、石虎、石羊與石柱，正前方立四柱三間二層石坊，兩側石造碑亭內立神道碑，是金門保存清代墳塋形制最完整的墓園。","highlights":["左右對稱排列的文官、武官、石馬、石虎、石羊","墓前四柱三間二層石坊與泉州白石褒狀","仿木亭造型、屋簷起翹的石造碑亭與神道碑"],"funFact":"金城的邱良功母節孝坊是為他母親而立，母子兩人一坊一墓都在金門。","photoSpot":"從石像生步道往墓塚方向拍對稱構圖","visitMin":20,"openNote":"位於金湖鎮太武山麓小徑村旁的戶外墓園，官方資料未載開放時間。參觀請保持肅靜、尊重墓主，勿攀爬石像與牌坊。可騎機車或開車前往。","dialogue":[{"who":"R","text":"哇，這條路兩邊站著好多石頭人和石頭動物，好像在列隊歡迎我們！"},{"who":"A","text":"這叫石像生，有文官、武官、石馬、石虎、石羊。這裡是清代男爵邱良功的墓園，是金門清代墓園裡形制最完整的。"},{"who":"R","text":"男爵？金門也有貴族喔？他做了什麼大事？"},{"who":"A","text":"清嘉慶年間，海盜蔡牽集團在臺灣海峽一帶橫行，邱良功跟著水師追剿多年，1809年終於平定，因此封為三等男爵。"},{"who":"R","text":"海上追海盜，根本是古代的動作大片！"},{"who":"A","text":"他1817年病逝，皇帝還賜了兩通神道碑，就放在兩邊的石亭裡。對了，金城那座邱良功母節孝坊，是為他媽媽立的。"},{"who":"R","text":"一個在金城、一個在太武山腳，母子都留名金門耶。"},{"who":"A","text":"所以參觀時要安靜、別攀爬。請你仔細看石亭的屋頂，數數看屋簷四個角有沒有往上翹。"}],"clues":["我的主人曾參與平定海盜蔡牽集團","我的墓前有文官、武官與石馬、石虎、石羊列隊","我是金門清代墓園形制最完整的男爵墓"],"quiz":[{"q":"邱良功因平定哪個集團而封為男爵？","options":["林爽文集團","天地會","蔡牽集團","鄭成功部隊"],"answer":2,"explain":"1809年邱良功平定蔡牽海盜集團，以功授三等男爵。"},{"q":"邱良功墓園兩側碑亭內立的是什麼？","options":["族譜碑","神道碑","節孝碑","修墓碑"],"answer":1,"explain":"朝廷諭賜神道碑兩通，立於墓園兩側碑亭。"}],"images":[]},{"id":"jincheng-wenyingjumu","name":"文應舉墓","short":"文應舉墓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["墓葬"],"lat":24.39956,"lng":118.31796,"address":"金門縣金城鎮小古崗北郊","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-16/e5ddab8c-89ab-48db-a46e-cca991ea7ed3/01封面.jpg","year":1830,"yearText":"1830年（清道光10年）安葬","era":"qing","themes":["墓葬"],"yearUnknown":false,"summary":"四代從戎的總兵文應舉清代品官墓","intro":"文應舉墓位於金城鎮小古崗北郊，是清代品官古墓。文應舉（1770–1829）號茅山，武職出身，清嘉慶元年（1796）追隨金門總兵在深滬擒獲海賊，因功敘獎；後受浙江提督李長庚賞識，赴浙江洋面追緝海盜蔡牽、朱濆一黨。他歷任金門、廈門遊擊，補天津大沽參將、廣東海口副將，道光年間升任廣東陽江鎮、瓊州鎮總兵，誥授武顯將軍。他於道光9年元旦過世，次年安葬，《金門志》記「總兵文應舉墓，在古坑」。墓為一身二翼的三合碑形式，碑翼刻「四代衣冠皆宿將，兩朝劍笏舊勳臣」。","highlights":["碑翼對聯「四代衣冠皆宿將，兩朝劍笏舊勳臣」","墓桌浮雕：樹下雙鸛與草叢雙鹿","曲手轉角的坐獅與蓮花柱頭"],"funFact":"對聯上句說文家從渡金祖起四代都是武將，下句指文應舉歷經嘉慶、道光兩朝為將。","photoSpot":"從墓埕正面拍三合碑與曲手","visitMin":15,"openNote":"位於金城鎮小古崗北郊，為戶外墓園，可在外部參觀；請保持肅靜，勿攀爬墓體。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，到墓園參觀要放輕腳步喔。這裡是清代總兵文應舉的墓，墓主可是追海盜的高手。"},{"who":"R","text":"追海盜？像電影裡那樣在海上開船追來追去嗎？"},{"who":"A","text":"差不多！他年輕時就在深滬抓到海賊，後來被浙江提督李長庚看中，派去追緝蔡牽、朱濆一黨。"},{"who":"R","text":"蔡牽！就是邱良功剿滅的那個大海盜嘛！"},{"who":"A","text":"記性真好，同一時代很多金門將領都跟他交手過。文應舉後來還當到廣東瓊州鎮總兵。"},{"who":"R","text":"那墓碑兩旁的對聯，到底寫了些什麼呢？"},{"who":"A","text":"「四代衣冠皆宿將，兩朝劍笏舊勳臣」，意思是文家連續四代都是武將，他自己也歷經兩朝。"},{"who":"R","text":"四代都是將軍，這根本是家族事業吧！"},{"who":"A","text":"可以這麼說。請你看看墓桌正面的浮雕，左右兩邊分別刻了哪兩種成對的動物！"}],"clues":["我的主人曾奉命赴浙江洋面追緝蔡牽一黨","我的碑翼寫著「四代衣冠皆宿將」","小古崗北郊的清代總兵墓，墓桌刻有雙鸛與雙鹿"],"quiz":[{"q":"墓主文應舉最後擔任過哪一鎮的總兵？","options":["金門鎮","溫州鎮","臺灣鎮","瓊州鎮"],"answer":3,"explain":"道光年間擢陽江鎮總兵，再調瓊州鎮。"},{"q":"墓桌正面浮雕刻的是哪兩組動物？","options":["雙鸛與雙鹿","雙龍與雙鳳","雙獅與雙象","雙鶴與雙魚"],"answer":0,"explain":"左側雕樹下雙鸛，右側雕草叢雙鹿。"}],"images":[]},{"id":"jinhu-qionglinyimensan","name":"瓊林一門三節坊","short":"一門三節坊","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["寺廟"],"lat":24.45392,"lng":118.37042,"address":"金門縣金湖鎮瓊林村外（雙瓊路上）","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/ca3d43c4-7d59-4087-abd8-c30ac8cf3cff/01封面.jpg","year":1831,"yearText":"1831年（清道光11年）","era":"qing","themes":["牌坊碑碣"],"yearUnknown":false,"summary":"旌表一姑兩媳守節的古官道石牌坊","intro":"瓊林一門三節坊位於金湖鎮瓊林村西郊的雙瓊路旁，是清代旌表平林（瓊林舊稱）蔡仲環之妻陳氏與兩位媳婦陳氏、黃氏守節而立。陳氏29歲喪夫，撫養三子成人；兩位媳婦分別在21歲與29歲守寡，婆媳勤儉持家，晚年五世同堂。1831年（清道光11年）呈請旌表後，立坊於金門城通往官澳的古官道上。牌坊為四柱三間二層石坊，以花崗石與青斗石雕成，大額枋正面浮雕雙龍戲珠、背面浮刻雙鳳朝陽；最上層與原有橫額已佚失，今嵌青斗石「一門三節」橫額，柱上留有郭揚聲等人的題聯。","highlights":["青斗石雕刻的「一門三節」四字橫額","大額枋正面雙龍戲珠、背面雙鳳朝陽浮雕","背面柱上郭揚聲題寫的「一姑兩媳冰霜節」楹聯"],"funFact":"牌坊立在金門城往官澳的古官道上，是過去進出瓊林的必經之路。","photoSpot":"從雙瓊路旁正面拍四柱三間全景","visitMin":10,"openNote":"位於金湖鎮瓊林村外雙瓊路旁，官方資料記載全天候開放，可就近參觀瓊林聚落。請勿攀爬牌坊。","dialogue":[{"who":"R","text":"Allan，瓊林村外這座石牌坊上寫著「一門三節」，是三個節日的意思嗎？"},{"who":"A","text":"不是節日，是節操的節。清代官府用牌坊表揚守節的婦女，這座表揚的是同一家的婆婆和兩個媳婦。"},{"who":"R","text":"一家三個人？她們發生了什麼事？"},{"who":"A","text":"婆婆陳氏29歲失去丈夫，獨自養大三個兒子，後來兩個媳婦也分別在21歲和29歲守寡。"},{"who":"R","text":"好辛苦喔，三個人都要撐起整個家。"},{"who":"A","text":"她們勤儉持家，到晚年已經五代同堂。1831年清道光11年族人申請旌表，就把牌坊立在古官道上。"},{"who":"R","text":"那這座牌坊上的雕刻有什麼看頭？"},{"who":"A","text":"正面是雙龍戲珠，繞到背面變成雙鳳朝陽。請你走到背面，找找看那對鳳凰藏在哪一根石樑上。"}],"clues":["我站在金門城通往官澳的古官道旁","我的正面雕雙龍戲珠，背面雕雙鳳朝陽","我表揚的是一位婆婆和兩位媳婦"],"quiz":[{"q":"一門三節坊表揚的是哪三位女性？","options":["三位姊妹","母親與兩個女兒","婆婆與兩位媳婦","祖孫三代"],"answer":2,"explain":"表揚蔡仲環妻陳氏及兩位媳婦陳氏、黃氏守節。"},{"q":"一門三節坊大額枋背面浮刻什麼圖案？","options":["雙龍戲珠","雙鳳朝陽","麒麟送子","八仙過海"],"answer":1,"explain":"大額枋正面浮雕雙龍戲珠，背面浮刻雙鳳朝陽。"}],"images":[{"file":"瓊林一門三節坊..DSC 1248.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4b/%E7%93%8A%E6%9E%97%E4%B8%80%E9%96%80%E4%B8%89%E7%AF%80%E5%9D%8A..DSC_1248.jpg/960px-%E7%93%8A%E6%9E%97%E4%B8%80%E9%96%80%E4%B8%89%E7%AF%80%E5%9D%8A..DSC_1248.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%93%8A%E6%9E%97%E4%B8%80%E9%96%80%E4%B8%89%E7%AF%80%E5%9D%8A..DSC_1248.jpg","artist":"顏錫沂2","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinhu-qionglinyimensan-0.webp","small":"img/jinhu-qionglinyimensan-0-s.webp"}]},{"id":"jincheng-kuixinglou","name":"魁星樓(奎閣)","short":"奎閣","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["寺廟"],"lat":24.43131,"lng":118.31781,"address":"金門縣金城鎮珠浦東路43號前","announced":"1985-08-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000090","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-28/f9e12b6a-ae3b-45f0-9885-5fb2573dfd05/01封面.jpg","year":1836,"yearText":"1836年（清道光16年）動工，1838年完成","era":"qing","themes":["宗教信仰","教育書院"],"yearUnknown":false,"summary":"後浦林斐章獨資捐建的六角形二層奎閣","intro":"奎閣又稱魁星樓，位於金城鎮珠浦東路，由後浦富商林斐章捐銀千圓，於清道光16至18年（1836–1838）興建，供讀書人祈求功名。「魁」與「奎」同音互通，所以有奎閣、魁閣等稱呼。《金門志》說林斐章富而好義，年年施捨棺木，孫子林可遠也承續家風熱心公益。奎閣在1955、1963年兩度重修，1963年由旅居菲律賓的林斐章玄孫林克凱出資，換上部分綠釉琉璃瓦；1986年由建築師漢寶德主持整修，2002年再修復完成。建築為正六角形二層樓，重檐屋頂中央有葫蘆泥塑，二樓有層層出挑的六角藻井。","highlights":["正六角形重檐屋頂與頂端葫蘆泥塑","牆面上的八角形竹節花窗","二樓四層出挑、以夔龍收頭的六角藻井"],"funFact":"1963年重修時出錢的，是興建者林斐章旅居菲律賓的玄孫林克凱。","photoSpot":"珠浦東路上拍六角重檐與陳詩吟洋樓同框","visitMin":15,"openNote":"位於金城鎮珠浦東路，官方資料記載每日08:00–12:00、13:30–17:30開放。從金城車站步行可達，可與旁邊的陳詩吟洋樓一起參觀。","dialogue":[{"who":"R","text":"Allan，這座六角形的小樓好可愛，像一顆巨大的粽子！"},{"who":"A","text":"粽子哪有六個角啦。這是奎閣，又叫魁星樓，1836年動工，讓讀書人來拜魁星、求功名。"},{"who":"R","text":"所以考試前來拜一拜，就會考一百分嗎？"},{"who":"A","text":"拜完還是要讀書喔。它是後浦商人林斐章一個人捐銀千圓蓋的，金門志說他富而好義，年年施捨棺木。"},{"who":"R","text":"一個人出錢蓋一座樓，真的好大方！"},{"who":"A","text":"更厲害的是，1963年重修時出錢的，是他旅居菲律賓的玄孫林克凱，隔了好幾代還在守護它。"},{"who":"R","text":"原來是家族接力賽！那裡面有什麼好看的？"},{"who":"A","text":"二樓屋頂有六角藻井，一層一層往內縮，最後收在彩繪的夔龍，像萬花筒一樣。"},{"who":"A","text":"現在請你繞奎閣走一圈，數數看牆上的八角形竹節花窗總共有幾扇！"}],"clues":["我由後浦一位富商獨資捐銀千圓興建","我是六角形的二層樓，屋頂中央有葫蘆","讀書人來這裡祭拜魁星，祈求金榜題名"],"quiz":[{"q":"奎閣的平面是什麼形狀？","options":["正方形","正六角形","正八角形","圓形"],"answer":1,"explain":"奎閣是正六角形的二層建築，屋頂採重檐。"},{"q":"1986年主持奎閣整修的建築師是誰？","options":["漢寶德","李祖原","陳南山","王益順"],"answer":0,"explain":"1986年由建築師漢寶德主持整修，成為今日面貌。"}],"images":[{"file":"金門奎閣.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/36/%E9%87%91%E9%96%80%E5%A5%8E%E9%96%A3.jpg/960px-%E9%87%91%E9%96%80%E5%A5%8E%E9%96%A3.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E5%A5%8E%E9%96%A3.jpg","artist":"riNux from Taipei, Taiwan","license":"CC BY-SA 2.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/2.0","local":"img/jincheng-kuixinglou-0.webp","small":"img/jincheng-kuixinglou-0-s.webp"}]},{"id":"lieyu-wuxiucaicuo","name":"烈嶼吳秀才厝","short":"吳秀才厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["宅第"],"lat":24.42234,"lng":118.22968,"address":"金門縣烈嶼鄉上庫25號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000011","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-16/f6c58785-c807-4f68-a2ea-0f371b03b0ec/封面01.png","year":1840,"yearText":"約1840年代（清道光年間）","era":"qing","themes":["閩南古厝","名人故居","教育書院"],"yearUnknown":false,"summary":"秀才義務辦學、鄉親贈地的雙落大厝","intro":"烈嶼吳秀才厝位於烈嶼鄉上庫聚落。清末上庫以「走北船」航運與鹽田為主要產業，吳景山（1804–1845）經營航運與鹽場致富後，於清道光年間興建此宅。其孫吳煜善（1867–1923）於光緒末年考中秀才，在屋前設書齋學堂，義務教導鄉里子弟，鄉親感念而將屋前原屬公產的前埕贈與吳家，「秀才厝」之名從此流傳。建築為雙落大厝加左右護龍，門口埕以牆規樓環護；大門有「其儀不忒」泥塑匾額，大廳四座格扇門以春牡丹、夏荷、秋菊、冬梅為主題，木雕精細。民國92年（2003）完成整體修復後開放參觀，宅內仍留有後代行醫時的中藥櫃。","highlights":["大門上方勉勵子孫的「其儀不忒」泥塑匾額","大廳格扇門上春夏秋冬四季花卉木雕","宅內保留的中藥櫃，見證後代在此行醫"],"funFact":"吳秀才在屋前免費教書，鄉親為了感謝，乾脆把原本公有的前埕送給吳家。","photoSpot":"在前埕拍雙落大厝的翹脊與交趾陶","visitMin":30,"openNote":"位於烈嶼鄉上庫聚落，依官方資料每週一、三、五、六、日09:00–17:00開放參觀。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，這裡明明是吳家的房子，為什麼大家都叫它秀才厝？"},{"who":"A","text":"因為吳家出了秀才吳煜善，他在清光緒末年考中後，就在屋前開學堂，免費教村裡的孩子。"},{"who":"R","text":"免費補習班！那鄉親一定超感謝他。"},{"who":"A","text":"太感謝了，乾脆把屋前原本公有的前埕送給吳家，秀才厝這個名字就叫到今天。"},{"who":"R","text":"送一整片廣場當謝禮，比送水果禮盒豪氣多了！那房子是秀才自己蓋的嗎？"},{"who":"A","text":"不是，是他的祖父吳景山，清道光年間靠走北船航運和鹽場致富後蓋的。來，邊喝廣東粥邊聽我說。"},{"who":"R","text":"Allan你又偷帶早餐！那屋子裡有什麼必看的寶貝？"},{"who":"A","text":"大廳四座格扇門雕著春牡丹、夏荷、秋菊、冬梅。進大廳後找找看，代表冬天的梅花藏在哪一扇門上？"}],"clues":["鄉親為了感謝我家主人義務教書，把前埕送給我們","我大門上方有「其儀不忒」泥塑匾額","我是小金門上庫聚落，因一位秀才而得名的大厝"],"quiz":[{"q":"鄉親送給吳家什麼來表達感謝？","options":["一艘北船","一塊鹽田","屋前的前埕","一面匾額"],"answer":2,"explain":"吳秀才義務辦學，鄉親把原屬公產的前埕贈與吳家。"},{"q":"大廳格扇門頂堵的雕刻主題是？","options":["四季花卉","八仙過海","二十四孝","三國故事"],"answer":0,"explain":"以春牡丹、夏荷、秋菊、冬梅四季花卉為主題。"}],"images":[{"file":"金門色.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/%E9%87%91%E9%96%80%E8%89%B2.jpg/960px-%E9%87%91%E9%96%80%E8%89%B2.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E8%89%B2.jpg","artist":"Deepblue5042","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/lieyu-wuxiucaicuo-0.webp","small":"img/lieyu-wuxiucaicuo-0-s.webp"}]},{"id":"jinsha-dongxizhengshijia","name":"東溪鄭氏家廟","short":"東溪鄭氏家廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["祠堂"],"lat":24.46251,"lng":118.45252,"address":"金門縣金沙鎮東溪14號","announced":"1999-06-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990616000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-15/beabe868-48b8-4b1e-a344-e63b29cdd3a2/01封面.jpg","year":1848,"yearText":"1848年（清道光28年）","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"開台進士鄭用錫回原鄉興建的家廟","intro":"東溪鄭氏家廟位於金沙鎮大洋里東溪聚落（古稱裡洋）。內洋鄭氏開基祖鄭懷仁於清康熙年間自漳浦遷居墾拓，乾隆年間部分族人赴臺，定居竹塹的鄭崇和之子鄭用錫於清道光3年（1823）中進士，有「開台進士」之稱。鄭用錫於道光28年（1848）在金門故里興建家廟，5年後才在新竹建另一座鄭氏家廟。家廟為二進帶廂格局，外觀簡樸、用料精良，大木棟架採疊斗做法，展現同安系木匠風格。1930年代曾作私塾，戰後辦「內洋學校」；八二三砲戰時屋瓦與石材被彈片擊傷，2009年修復完成。","highlights":["正殿四點金柱的三通五瓜疊斗棟架","大通下雕刻精緻的人物插角","平緩屋面讓正立面顯得格外寬闊"],"funFact":"鄭用錫先在金門原鄉蓋家廟，5年後才在新竹蓋鄭氏家廟，金門這座反而是「大哥」。","photoSpot":"在外埕拍寬闊低簷的正立面","visitMin":15,"openNote":"位於金沙鎮東溪聚落，為鄭氏宗族祭祀場所，平日請在外觀參觀，祭祀期間請勿打擾。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，新竹也有一座鄭氏家廟，跟金門這座有關係嗎？"},{"who":"A","text":"關係可深了！兩座都和開台進士鄭用錫有關。他的祖先從金門內洋出發，到臺灣竹塹落腳。"},{"who":"R","text":"開台進士？是臺灣第一個考上進士的人嗎？"},{"who":"A","text":"對，道光3年考上的。他沒忘記根在金門，道光28年先回原鄉蓋了這座家廟，5年後才在新竹蓋另一座。"},{"who":"R","text":"所以金門這座是哥哥，新竹那座是弟弟！"},{"who":"A","text":"可以這麼記。這座家廟外觀樸素，可是木棟架用疊斗做法，雕工很細，屬於同安系木匠的風格。"},{"who":"R","text":"低調奢華型的家廟耶。它後來一直都當祠堂嗎？"},{"who":"A","text":"1930年代當過私塾，戰後辦過內洋學校，八二三砲戰時，屋瓦和石材還被砲彈碎片打傷，後來才修復。"},{"who":"R","text":"當過教室又挺過砲火，好堅強！大家到現場站在外埕，看看它的屋簷多低、正面多寬吧！"}],"clues":["我的主人是臺灣第一位進士，卻先在金門蓋了我","我比新竹那座同姓家廟早5年落成","我在東溪聚落，是與開台進士有關的祠堂"],"quiz":[{"q":"鄭用錫有什麼美譽？","options":["開台進士","開台國聖","開澎進士","金門狀元"],"answer":0,"explain":"鄭用錫為臺灣登進士第第一人，有開台進士之譽。"},{"q":"東溪鄭氏家廟比新竹鄭氏家廟早幾年興建？","options":["2年","10年","5年","20年"],"answer":2,"explain":"金門家廟建於1848年，新竹家廟建於1853年。"}],"images":[]},{"id":"jinsha-hecuochenshigucuo","name":"何厝陳氏古厝","short":"何厝陳氏古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.473975,"lng":118.399787,"address":"金門縣金沙鎮何厝20號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-04-02/b6ef8196-643e-43ff-8d9e-834553062bb4/(3).jpg","year":1850,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝"],"yearUnknown":true,"summary":"深井大到能擺六張圓桌的古厝","intro":"何厝陳氏古厝位於金沙鎮何厝聚落，是何厝陳氏開基祖房之一，興建年代與起造人官方資料未載。建築為一落四櫸頭，帶左右突歸與右護龍，屋脊為翹脊，外牆多以花崗石塊砌成，樸實少裝飾；入口大門內凹，留有防盜門的石作插栓孔。最特別的是深井，寬7.3公尺、深6.73公尺，在地俗稱可擺六張大圓桌，為地區少見；外櫸頭朝深井設出檐與四組出挑斗拱，在承重牆擱檁造中也很少見。目前建築損壞嚴重，屋頂與牆體多處坍塌，木構架也曾遭白蟻嚴重蛀蝕。","highlights":["在地俗稱可擺六張大圓桌的大深井","樸素少裝飾的花崗石塊外牆","大門內凹處的防盜門石作插栓孔"],"funFact":"這座古厝的深井寬7.3公尺、深6.73公尺，在地人說可以擺上六張大圓桌。","photoSpot":"在屋外安全距離拍花崗石外牆","visitMin":10,"openNote":"位於金沙鎮何厝聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築屋頂與牆體多處坍塌，請保持安全距離。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"金門人辦桌最講究場地，今天這間古厝的深井，據說可以擺下六張大圓桌！"},{"who":"R","text":"六張？Allan，那不就能在自己家裡辦喜宴了？"},{"who":"A","text":"差不多喔，它寬超過7公尺、深將近7公尺，比一般閩南古厝的天井大很多，在金門很少見。"},{"who":"R","text":"那主人一定很有錢吧，是誰蓋的？"},{"who":"A","text":"這個嘛，官方資料只知道它是何厝陳氏開基祖房之一，誰蓋的、哪一年蓋的都不清楚。"},{"who":"R","text":"身世成謎的大宅，好像推理小說的開場！"},{"who":"A","text":"外觀倒是很樸素，牆面多是花崗石塊，大門內凹還有防盜門的插栓孔。可惜現在屋頂和牆都塌了不少。"},{"who":"R","text":"好可惜，希望能早點修好。那我們能做什麼？"},{"who":"A","text":"請在屋外保持安全距離，看看那片樸素的花崗石外牆，想像門後那座能擺六桌的大深井吧。"}],"clues":["我的深井據說能擺下六張大圓桌","我身世不詳，只知道是開基祖房之一","我在金沙鎮何厝，是一落四櫸頭帶護龍的古厝"],"quiz":[{"q":"在地人形容這座古厝的深井有多大？","options":["可停兩輛牛車","可種十棵果樹","可容百人看戲","可擺六張大圓桌"],"answer":3,"explain":"深井寬7.3公尺、深6.73公尺，俗稱可放六張大圓桌。"},{"q":"古厝外牆主要以什麼材料砌成？","options":["紅磚斗砌","花崗石塊","咾咕石","土埆磚"],"answer":1,"explain":"外側立面除山牆抹灰外，牆體皆由花崗石塊砌成。"}],"images":[]},{"id":"jinsha-guandeqiao","name":"觀德橋","short":"觀德橋","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["橋樑"],"lat":24.468374,"lng":118.391382,"address":"金門縣金沙鎮高坑劃測段629地號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-31/171638d5-17bd-4862-9344-99958103895b/觀德橋 (1).jpg","year":1850,"yearText":"1850年（清道光30年）","era":"qing","themes":["公共建築","牌坊碑碣"],"yearUnknown":false,"summary":"金門古官道上保存最完整的清代石橋","intro":"觀德橋位於金沙鎮高坑聚落村郊，橫跨太武山腳的「大路宮溝」，清道光30年（1850）由瓊林鄉紳蔡行猷興建。明代以來，從金門千戶所城到東北官澳渡口有一條「官道」，公文傳遞與官民往來多經此路。古官道今已不存，只能從沿途牌坊、石碑與橋樑推知路線，觀德橋是其中保存較完整的清代古橋。橋為單跨梁橋，全以花崗石築成，橋面由四塊長石條組成，兩側鑽孔痕跡顯示原應設有護欄，兩端各有石獅與仙桃望柱一對。橋旁約六公尺處立有石碑，刻「觀德橋」與「道光庚戌年桐月新建築造」等字。","highlights":["橋兩端的石獅與仙桃望柱","橋面兩側推測原有護欄的鑽孔痕跡","橋旁刻有「道光庚戌年」的觀德橋石碑"],"funFact":"碑上刻的官名是「武德尉騎」，官方說明特別加註，正確應為「武德騎尉」。","photoSpot":"在溝旁側拍單跨石橋與望柱","visitMin":10,"openNote":"位於金沙鎮高坑聚落村郊的戶外空間，官方未公布開放時間。古橋石材老舊，請勿攀爬石獅與望柱。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這座橋好短喔，幾步就走完了，有什麼特別的？"},{"who":"A","text":"別小看它！觀德橋是清道光30年蓋的，是金門古官道保存較完整的見證。"},{"who":"R","text":"古官道？聽起來像是古代的高速公路耶！"},{"who":"A","text":"可以這樣比喻，明代以來從金門城到官澳渡口，公文傳遞和官民往來都走這條路。"},{"who":"R","text":"那這條古代高速公路，現在跑去哪裡了？"},{"who":"A","text":"官道已經不在了，只能靠沿路的牌坊、石碑和這座橋，拼出它大概的路線。"},{"who":"R","text":"原來它是拼圖裡的一塊！那是誰出錢蓋的呀？"},{"who":"A","text":"是瓊林鄉紳蔡行猷，旁邊還立了石碑記下年份。橋兩端的石獅和仙桃望柱，也守在這裡一百多年了。"},{"who":"R","text":"那我先跟石獅打招呼，再去石碑上找「道光庚戌年」那幾個字！"}],"clues":["我是一條消失道路留下來的拼圖碎片","我兩端有石獅和仙桃望柱，旁邊立著一塊石碑","高坑村郊跨越大路宮溝的清代花崗石橋"],"quiz":[{"q":"這座橋是由誰興建的？","options":["瓊林鄉紳蔡行猷","浦邊富商周文","官澳首富楊廣理","西山前僑商李撻"],"answer":0,"explain":"清道光30年由瓊林鄉紳蔡行猷所建。"},{"q":"觀德橋屬於哪一種橋樑構造？","options":["三孔拱橋","單跨梁橋","木造吊橋","石砌廊橋"],"answer":1,"explain":"兩端橋墩支撐四塊石條橋面，屬單跨梁橋。"}],"images":[]},{"id":"jinning-xupijiangucuo","name":"許丕簡古厝","short":"許丕簡古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["宅第"],"lat":24.459161,"lng":118.36406,"address":"金門縣金寧鄉后沙20號","announced":"2010-01-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20100112000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/86d5cb98-1158-4c01-a7fb-b601005268f6/01封面.png","year":1867,"yearText":"1867年（清同治6年）","era":"qing","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"金門少見的小六路大厝，雕飾與彩繪精美","intro":"許丕簡古厝位於金寧鄉后沙聚落，竣工於清同治6年（1867），原由后沙許氏五房的許丕騰從新加坡經商返鄉興建。後來許丕騰商號中落，打算以一千二百銀元賣給外鄉僑商，同房的許丕簡認為賣給外人有損村譽，以一千五百銀元買下。許丕簡（1869～1945）遠赴菲律賓衣里岸，投資友人創設的聯芳公司經營椰乾與雜貨，致富後曾在宗祠開辦私塾。古厝為一落四櫸頭兩側增突規的「小六路」厝加左護龍，屬少見格局。日軍占領期間曾被當作伙房，正立面左裙堵留有槍孔；1949年後多支國軍部隊進駐，1990年代才歸還，2019至2020年完成整體修復。","highlights":["牆規樓中央的「太和翔洽」匾堵與青斗石門印","燈樑全支彩繪「丹鳳朝陽」，修復後重現","正立面八角配四方磚、卍字紋等多種磚組砌"],"funFact":"許丕簡寧可多付三百銀元，也不讓古厝賣給外鄉人，因為他覺得那樣有損村子的名聲。","photoSpot":"在牆規樓前拍「太和翔洽」匾堵與磚雕","visitMin":20,"openNote":"位於金寧鄉后沙聚落。官方資料記載需電話預約安排時日參觀；未預約請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這棟古厝的故事我聽說了，有人搶著用比較貴的價錢買下它，是真的嗎？"},{"who":"A","text":"是真的。原屋主許丕騰生意失利，想用一千二百銀元賣給外鄉人，同宗的許丕簡硬是出一千五百銀元買下。"},{"who":"R","text":"多付三百塊！他是不是不會殺價啊？"},{"who":"A","text":"他是覺得賣給外鄉人有損村子名聲。這叫愛鄉愛到願意加價，比我買燒餅還阿莎力。"},{"who":"R","text":"那他到底是怎麼賺到這麼多錢的呢？"},{"who":"A","text":"他到菲律賓衣里岸，先當帳房，再投資聯芳公司做椰乾和雜貨，還自己買電船跑島際貿易。"},{"who":"R","text":"這棟房子的形狀好像特別寬，是什麼格局？"},{"who":"A","text":"它叫小六路，是一落四櫸頭兩邊再加突規，金門很少見。請你在門口找找匾堵上寫的四個字！"}],"clues":["有人願意多付三百銀元，只為了不讓我賣給外鄉人","我是小六路格局，燈樑上畫著丹鳳朝陽","我在后沙，牆規樓匾堵寫著「太和翔洽」"],"quiz":[{"q":"許丕簡最後用多少銀元買下這棟古厝？","options":["一千銀元","一千二百銀元","一千五百銀元","兩千銀元"],"answer":2,"explain":"他以一千五百銀元購入，避免古厝轉賣給外鄉人。"},{"q":"許丕簡古厝屬於哪一種少見的格局？","options":["小六路厝","三蓋廊厝","五腳基洋樓","三落大厝"],"answer":0,"explain":"古厝為一落四櫸頭兩側增突規的六路厝，俗稱小六路。"}],"images":[]},{"id":"jinsha-xishanqianlizhai","name":"西山前李宅","short":"西山前李宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.49364,"lng":118.4274,"address":"金門縣金沙鎮三山村西山前17、17-1、18號","announced":"1988-11-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19881111000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/5eb63d8f-03a1-4858-b464-f77b0a5df853/01封面.jpg","year":1880,"yearText":"1880年（清光緒6年）、1884年（清光緒10年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"新加坡批發商回鄉蓋的兩座六路大厝","intro":"西山前李宅位於金沙鎮三山村西山前聚落，共兩座，都是在新加坡經商致富的族人回鄉興建。一座由經營「金裕美號」批發行的李撻興建，他曾在新加坡牛車水捐建浯江孚濟廟，並捐得五品同知奉政大夫銜，清光緒6年（1880）建造五開間兩落的「大六路」大厝，迎接次年頒給父母的誥命。另一座由經營「金振美號」的李冊騫出資，清光緒10年（1884）引進泉州、晉江建材與師傅，建成三落五開間的六路大厝，有十六間房可分戶居住，人稱「十六間厝」。兩座正面皆採雙榻受，民國86年（1997）完成整體修護。","highlights":["李冊騫大厝三落、十六間房的「十六間厝」","李冊騫大厝門額「山門水秀」與李撻大厝門額「福星高照」","兩座大厝正面的雙榻受作法"],"funFact":"李冊騫大厝每一落兩側山牆都開有小門，以巷頭相連，三落就有三道巷頭，方便各房分戶出入。","photoSpot":"在巷道拍兩座大厝相連的翹脊","visitMin":15,"openNote":"位於金沙鎮三山村西山前聚落，官方未公布開放時間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。鄰近西山前李氏家廟，可一併走訪；開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，十六間厝是什麼意思？是有十六棟房子嗎？"},{"who":"A","text":"不是喔，是一棟大厝裡有十六間房，就是李冊騫出資的那座大厝，三落五開間的六路大厝。"},{"who":"R","text":"十六間房！過年親戚再多也睡得下了。"},{"who":"A","text":"沒錯，而且每一落兩側都開小門，三道巷頭串起來，各房可以自己進出。"},{"who":"R","text":"那後面那一棟呢？也是十六間嗎？"},{"who":"A","text":"那是李撻大厝，清光緒6年李撻蓋的五開間兩落大厝，用來迎接朝廷頒給父母的誥命。"},{"who":"R","text":"兩棟都這麼氣派，他們是做什麼生意的？"},{"who":"A","text":"都在新加坡開批發行，一家叫金裕美號，一家叫金振美號，名字聽起來就很有財氣吧。"},{"who":"R","text":"那我要去比對兩棟的門額，一個寫山門水秀，另一個寫什麼呢？"}],"clues":["我們是兩座相鄰的大厝，主人都在新加坡開批發行","其中一座有十六間房，被叫作十六間厝","西山前聚落兩座清光緒年間的六路大厝"],"quiz":[{"q":"「十六間厝」這個名稱是怎麼來的？","options":["有十六根柱子","有十六間房可分戶住","有十六扇窗","花了十六年蓋好"],"answer":1,"explain":"李冊騫大厝有十六間房間可分戶居住，故稱十六間厝。"},{"q":"李撻大厝的門額題字是什麼？","options":["山門水秀","科第流芳","福星高照","忠勤世第"],"answer":2,"explain":"李撻大厝門額題「福星高照」，李冊騫大厝為「山門水秀」。"}],"images":[]},{"id":"jinhu-beidingdaodengta","name":"北椗島燈塔","short":"北椗島燈塔","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["燈塔"],"lat":24.42715,"lng":118.50453,"address":"金門縣金湖鎮北碇段9、10、11、12、16地號","announced":"2020-10-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20201115000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-28/3c6cba3b-ede8-4031-aa6a-269177415083/北椗島燈塔.jpg","year":1883,"yearText":"1882年（清光緒8年）動工，1883年（清光緒9年）點燈","era":"qing","themes":["海防燈塔"],"yearUnknown":false,"summary":"金湖鎮極東點，唯一花崗石嵌框的白色燈塔","intro":"北椗島燈塔位於金湖鎮料羅東南方海上的北椗島（今稱北碇島），是金湖鎮的極東點。廈門開港後由中國海關英籍總營造司韓得善設計，1882年（清光緒8年）動工，1883年10月18日點燈，指引從北方駛入廈門港的船隻，是廈門港外四座燈塔中最晚完成的，與東椗島燈塔合稱「金門雙椗」。白色圓形磚造塔身中段以3道花崗石嵌框加強結構，是唯一的例子。二戰期間塔頂燈器室遭炸毀，曾以三角鐵架懸燈維持運作，1986年燈器移回塔頂。戰後國軍進駐，塔身留有當時的標語，宿舍屋角還嵌著一尊風獅爺。","highlights":["塔身中段3道花崗石嵌框，是唯一的特殊作法","二戰炸落的塔頂頂蓋，改設為基地中的紀念座","宿舍屋角鑲入牆身的金門風獅爺"],"funFact":"清《金門志》以金門為中心，把這座島叫「東椗」；西方海圖以廈門為中心，才叫它「北椗」。","photoSpot":"無法到現場拍攝，可欣賞官方照片中的花崗石嵌框","visitMin":10,"openNote":"位於金湖鎮料羅東南方海域的北碇島，沒有一般交通船，由航港局與守備部隊使用管理，一般民眾無法登島，只能透過網站或展覽認識。","dialogue":[{"who":"R","text":"Allan，東椗的黑燈塔我記住了，那北椗的燈塔也是黑色的嗎？"},{"who":"A","text":"這次換成白色！北椗島在料羅東南方海上，是金湖鎮的最東端，燈塔在1883年，也就是清光緒9年點燈。"},{"who":"R","text":"一黑一白，好像金門的海上雙胞胎！"},{"who":"A","text":"說得好，大家就叫它們「金門雙椗」。北椗的塔身中段有三圈花崗石嵌框，是唯一這樣做的燈塔，像穿了三條腰帶。"},{"who":"R","text":"三條腰帶，難怪身材這麼挺！它有沒有受過傷？"},{"who":"A","text":"第二次世界大戰時塔頂的燈器室被炸毀，後來只能把燈掛在三角鐵架上撐著，直到1986年燈才搬回塔頂。"},{"who":"R","text":"好堅強！聽說島上還藏著一個金門特產？"},{"who":"A","text":"宿舍屋角嵌著一尊風獅爺，連燈塔都要它鎮風。島上不開放登島，請你在官方照片裡找找那三圈嵌框吧。"}],"clues":["我被叫過東椗，後來才改成現在的名字","我的塔頂在二戰時被炸毀，燈曾掛在三角鐵架上","我是金湖鎮最東端的白色燈塔，和另一座燈塔合稱金門雙椗"],"quiz":[{"q":"北椗島燈塔塔身有什麼獨一無二的作法？","options":["塔身全塗黑漆","三道花崗石嵌框","以鋼骨搭建塔身","塔頂裝設銅鐘"],"answer":1,"explain":"塔身中段設3條花崗石嵌框加強結構，是唯一的例子。"},{"q":"北椗島燈塔宿舍屋角嵌著什麼？","options":["石敢當","八卦鏡","門神彩繪","風獅爺"],"answer":3,"explain":"宿舍屋角鑲入一座風獅爺，作為鎮風避邪之物。"}],"images":[]},{"id":"jincheng-jiangjundi","name":"將軍第","short":"將軍第","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.43307,"lng":118.31813,"address":"金門縣金城鎮珠浦北路24號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-15/27053795-b396-47c1-bf68-0b87637acf7f/01封面.jpg","year":1885,"yearText":"約1880年代（清光緒年間，1891年以前落成）","era":"qing","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"從小兵升到溫州總兵的盧成金宅第","intro":"將軍第位於金城鎮珠浦北路，是清代溫州總兵盧成金的宅第。盧成金（1822–1895）幼年家貧，棄學投入金門鎮標從軍，由最基層一路升至署理溫州總兵（正二品），並受封「正二品武顯將軍」。他發達後在後浦北門大井腳購地建宅，據清光緒17年（1891）的析產鬮書記載，土地購自邱良功之孫邱炳忠，起蓋三進住屋與一列護厝，買地連同起蓋共花英銀二千八百元。建築為三落大厝帶右護龍，正廳懸有透雕蟠龍、存放聖旨的「皇恩誥命」牌匾，第一落還保存皇宮專用的京磚。","highlights":["門額「將軍第」與窗楣「文章華國」「家傳禮詩」","正立面煙炙磚牆上的雙囍磚雕","右護龍大門上方的綠釉花磚女兒牆"],"funFact":"宅內保存一塊京磚，原是專為皇宮燒製的細料方磚，敲擊有金石之聲，所以又叫「金磚」。","photoSpot":"在宅前拍「將軍第」門額與雙囍磚雕","visitMin":15,"openNote":"位於金城鎮珠浦北路，後浦市區內。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可從金城車站步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，你知道從小兵當到將軍要多久嗎？這間厝的主人盧成金，花了大半輩子。"},{"who":"R","text":"小兵變將軍？聽起來好像勵志電影的劇情耶！"},{"who":"A","text":"真的很勵志。他小時候家裡窮沒辦法讀書，就去金門鎮標當兵，一路打仗升到署理溫州總兵。"},{"who":"R","text":"總兵是多大的官啊？比班長大嗎？"},{"who":"A","text":"大很多啦！總兵是正二品，在清代綠營裡僅次於提督。朝廷還封他武顯將軍，所以門額寫「將軍第」。"},{"who":"R","text":"那蓋這麼大的房子，一定花了很多錢吧？"},{"who":"A","text":"鬮書記載買地加蓋房共花英銀二千八百元，土地還是向邱良功的孫子買的，金門真像將軍養成班。"},{"who":"R","text":"哈哈，將軍買了提督家的地！這間現在還有人住嗎？"},{"who":"A","text":"有，所以我們只在外面欣賞。請你找找正面牆上的雙囍磚雕，還有窗楣上寫的四個字！"}],"clues":["我的主人從金門鎮標小兵一路升到溫州總兵","我的土地是向一位提督的孫子買來的","後浦珠浦北路的三落大厝，門額寫著主人的身分"],"quiz":[{"q":"盧成金最高官至哪個職位？","options":["金門鎮總兵","浙江水師提督","署理溫州總兵","福建巡撫"],"answer":2,"explain":"他由行伍出身，最後署理溫州總兵，官秩正二品。"},{"q":"將軍第的土地是向誰購買的？","options":["邱良功之孫","許獬的後人","黃俊的後人","洪旭之孫"],"answer":0,"explain":"析產鬮書記載土地購自邱良功之孫邱炳忠。"}],"images":[]},{"id":"jincheng-zhushanxiasanluo","name":"珠山下三落","short":"珠山下三落","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.40208,"lng":118.32133,"address":"金門縣金城鎮珠山61、63號","announced":"2018-03-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20180428000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-08/60733e20-4aef-44d9-8aa5-ed86e7cdcaec/1.png","year":1885,"yearText":"約1880年代（清光緒年間）","era":"qing","themes":["閩南古厝","聚落地景"],"yearUnknown":false,"summary":"呂宋僑匯大宅，前廳當過戲臺與冰果室","intro":"珠山下三落位於金城鎮珠山聚落核心大埕旁，約於清光緒年間由在菲律賓經商致富的僑商薛紹德返鄉興建三落大厝。後因其子吸食鴉片而家道中落，轉賣給同在菲律賓經商的薛如阜；薛如阜在宿霧經營麻索公司、擁有電船，民國初年返鄉增建右側二層疊樓護龍。因前落與大潭間腹地狹窄，前落採迴向配置、入口設在龍邊，前廳還曾作戲臺使用，在金門傳統建築中少見。民國38年後國軍進駐後落與護龍；1954年起前落改成和記商店與冰果室，一度是珠山的商業中心，見證華僑家族的興衰與戰地生活。","highlights":["前落迴向、入口設在龍邊的少見格局","三落與護龍各不相同的山牆泥塑脊墜","右護龍疊樓的磨石子牆面與彩繪磁磚"],"funFact":"薛家女眷會請戲班來演出，前落門扉可以完全打開，前廳就變成戲臺。","photoSpot":"在大埕旁拍迴向入口與護龍疊樓","visitMin":15,"openNote":"位於金城鎮珠山聚落大埕旁，官方開放資訊為「屋主在家時間」。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這間古厝的大門怎麼開在側邊，不是正對前面？"},{"who":"A","text":"這叫迴向，因為前落和大潭之間太窄，乾脆把入口轉到龍邊，金門很少見喔。"},{"who":"R","text":"那正面空出來的前廳，要拿來做什麼？"},{"who":"A","text":"以前薛家女眷會請戲班來，前落門扉整個打開，前廳就變成戲臺，在家就能看戲。"},{"who":"R","text":"哇，在家就有私人劇院，也太奢華了吧！"},{"who":"A","text":"因為屋主是菲律賓回來的僑商。最早的主人薛紹德蓋了三落大厝，後來兒子抽鴉片敗家，只好賣給同樣在菲律賓打拚的薛如阜。"},{"who":"R","text":"一間房子，就看得到一個家族的起起落落。"},{"who":"A","text":"後來國軍駐守，前落還開過商店和冰果室，很多阿兵哥都來消費。我要是當年在這裡，一定天天點刨冰。"},{"who":"R","text":"你現在也天天想吃好不好！我去看看山牆上的脊墜，三落和護龍的圖案是不是真的都不一樣！"}],"clues":["我的前廳曾經是戲臺，後來又變成冰果室","最早的主人因兒子吸食鴉片家道中落，把我賣給同鄉","珠山聚落大埕旁，前落迴向的三落大厝"],"quiz":[{"q":"這座大厝的前落為什麼採迴向配置？","options":["前方腹地狹窄","避開風水煞氣","方便軍隊進出","面向祖先墳墓"],"answer":0,"explain":"前落與大潭間腹地狹窄，主出入口改設龍邊。"},{"q":"民國43年起，前落曾改作什麼用途？","options":["私塾教室","軍隊指揮所","鄉公所辦公室","商店與冰果室"],"answer":3,"explain":"薛承立夫婦開設和記商店與冰果室。"}],"images":[]},{"id":"jinhu-xiaxingchenhongzuo","name":"夏興陳鴻佐古厝","short":"夏興陳鴻佐古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.44049,"lng":118.39568,"address":"金門縣金湖鎮夏興27號","announced":"2024-08-21","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20240902000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-09-02/2c5bbf4a-b589-4725-904f-0a26c4690e86/image073.jpg","year":1885,"yearText":"約1880年代（清光緒年間）始建，1906年（清光緒32年）擴建","era":"qing","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"僑匯擴建的三落大厝，彩繪木雕金門少見","intro":"夏興陳鴻佐古厝位於金湖鎮夏興聚落，夏興舊稱下坑，是以陳姓為主的單姓村，明初忠臣陳顯即出身於此。古厝相傳由陳顯裔孫陳鴻佐（1827－1890）起造，1906年（清光緒32年）由其六子陳侯老以南洋經商所得的僑匯擴建，成為三落大厝加右突規帶牆規的格局，規模在金門少見。裝飾尤其出色：前落水車堵以金門特有的「子婿燈」為彩繪題材，內部楣枋有少見的描金畫，正廳祖龕楣枋雕有「郭子儀拜壽」連環故事，另有罕見的「大象銜花」木雕。古厝歷經日軍與國軍進駐，整體結構仍保存良好，1993年整修後轉作民宿使用，2024年公告為縣定古蹟。","highlights":["水車堵以金門特有「子婿燈」為題材的彩繪","正廳祖龕楣枋的「郭子儀拜壽」連環木雕","金門民居少見的「大象銜花」木雕"],"funFact":"古厝原本是二落大厝，1906年才靠南洋僑匯加蓋第三落與右側突規，變成金門少見的大格局。","photoSpot":"在前埕拍三落大厝正面與水車堵彩繪","visitMin":20,"openNote":"位於金湖鎮夏興聚落。官方資料記載為預約開放參觀；古厝1993年整修後作為民宿使用，參觀請事先預約，未預約時請在外觀參觀，勿擅入、勿打擾住客。","dialogue":[{"who":"A","text":"來到夏興，舊名叫下坑，這裡的陳家很有來頭，明初忠臣陳顯就是這個村子的人。"},{"who":"R","text":"那這間大厝是陳顯蓋的嗎？看起來好氣派！"},{"who":"A","text":"是他的後代陳鴻佐起造的。1906年他的六子陳侯老在南洋賺了錢，寄僑匯回來，把二落大厝擴建成三落加突規。"},{"who":"R","text":"兒子賺錢幫老家升級，根本是金門版的房屋大改造！"},{"who":"A","text":"而且裝潢超講究。水車堵畫的是金門特有的「子婿燈」，屋裡還有少見的描金畫。"},{"who":"R","text":"子婿燈？聽起來跟女婿有關，畫在牆上是金門獨有的嗎？"},{"who":"A","text":"官方說這是金門特有的題材，很有地方味。祖龕上還雕著郭子儀拜壽，連大象都叼著花來祝賀。"},{"who":"R","text":"大象也來湊熱鬧，太可愛了！那我們可以進去看嗎？"},{"who":"A","text":"官方資料說要預約才能入內。沒預約的話，請在屋外仔細看前落水車堵，找找那幅子婿燈彩繪。"}],"clues":["我原本是二落大厝，1906年靠南洋僑匯擴建成三落","我的水車堵畫著子婿燈，祖龕雕著郭子儀拜壽","我在舊稱下坑的村子，起造人是明初忠臣的後代"],"quiz":[{"q":"夏興陳鴻佐古厝1906年靠什麼資金擴建？","options":["科舉獎賞","南洋僑匯","官府補助","宗族募捐"],"answer":1,"explain":"陳鴻佐六子陳侯老以南洋經商所得僑匯擴建。"},{"q":"古厝水車堵彩繪的金門特有題材是什麼？","options":["風獅爺","八仙過海","子婿燈","二十四孝"],"answer":2,"explain":"前落水車堵以金門特有的「子婿燈」為彩繪題材。"}],"images":[]},{"id":"jinsha-qingyuqianjiazhang","name":"青嶼前甲張氏宗祠","short":"青嶼前甲張氏宗祠","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["祠堂"],"lat":24.52056,"lng":118.422971,"address":"金門縣金沙鎮青嶼16號","announced":"2016-12-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20161226000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/0a6a4636-6645-49e2-b09f-64464440ad84/(1)封面.jpg","year":1890,"yearText":"清末（確切年份不詳）","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"木構不上色、雕工精美的清末宗祠","intro":"青嶼前甲張氏宗祠位於金沙鎮青嶼聚落。青嶼張氏以均正公為大宗始祖，清末時第四世張復保的後人感念先祖創業艱辛，集資在前甲擇地興建，是青嶼兩座張氏宗祠之一。宗祠民國40多年間曾作為小學，民國47年（1958）八二三砲戰時遭砲擊，民國66年（1977）修繕屋頂與正立面，整體仍大致保留清末樣貌。建築為典型兩進式，前落採三川脊與雙榻受，次間有泥塑竹節圓窗；正廳「三通五瓜」棟架的瓜筒、獅形座斗與鰲魚插角雕工細膩，點金柱與木屏堵刻意不上色。官方指出青嶼張氏在明清兩代人才輩出。","highlights":["不上色的點金柱與木屏堵","正廳三通五瓜棟架與獅形座斗","前落次間的泥塑竹節圓窗"],"funFact":"宗祠建成後一直作祭祀使用，民國40多年間還曾兼作小學。","photoSpot":"在廟埕拍三川脊與竹節圓窗","visitMin":15,"openNote":"位於金沙鎮青嶼聚落，官方未公布開放時間，請在外觀參觀並尊重宗族祭祀空間。鄰近青嶼張氏兄弟洋樓，開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"青嶼這個名字很美吧？今天我們來看前甲的張氏宗祠。"},{"who":"R","text":"Allan，為什麼要特別說前甲？難道還有別的？"},{"who":"A","text":"前甲是聚落裡的地名。青嶼有兩座張氏宗祠，這座是清末第四世張復保的後人集資蓋的。"},{"who":"R","text":"那它蓋好之後的一百多年，過得平順嗎？"},{"who":"A","text":"經歷不少喔！民國40多年當過小學，民國47年八二三砲戰時也遭到砲擊，後來才修繕。"},{"who":"R","text":"還好它撐下來了。裡面最值得看的是什麼？"},{"who":"A","text":"木雕！正廳的瓜筒、獅形座斗和鰲魚插角都很細，而且點金柱和木屏堵刻意不上色。"},{"who":"R","text":"不上色？是不是油漆預算花光了？"},{"who":"A","text":"哈哈，那是刻意呈現木頭本色。先從外面找找前落兩側的竹節圓窗吧！"}],"clues":["我的木柱和屏堵刻意不上色，展現原木本色","我當過小學，也在八二三砲戰時遭到砲擊","青嶼聚落兩座張氏宗祠之一，蓋在前甲"],"quiz":[{"q":"宗祠在民國40多年間曾作為什麼用途？","options":["醫院","小學","村公所","市場"],"answer":1,"explain":"宗祠在民國40多年間曾作為小學使用。"},{"q":"宗祠內木構最大的特色是什麼？","options":["全部貼上金箔","通體漆成黑色","以鐵件包覆補強","點金柱與屏堵不上色"],"answer":3,"explain":"內部木屏堵與點金柱採不上色處理。"}],"images":[]},{"id":"jinsha-pubianhededuogucuo","name":"浦邊何德奪古厝","short":"何德奪古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.479151,"lng":118.388537,"address":"金門縣金沙鎮浦邊43、44號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-10-25/f7bce0b9-eeb5-4679-a590-043eab4f26de/浦邊何德奪古厝_代表圖像.jpg","year":1893,"yearText":"約1884–1902年間（清光緒10至28年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"菲律賓僑匯蓋起的晚清二落大厝","intro":"浦邊何德奪古厝位於金沙鎮浦邊聚落。興建人何德奪曾旅居菲律賓，返鄉後經營借放款生意，依古地契推測約在清光緒10至28年（1884–1902）間興建。他娶了三位太太，第二位是菲律賓人，兒子何敬麟也到菲律賓發展，官方視此宅為菲律賓僑匯的見證。古厝是三開間二落大厝，外牆下堵為七層花崗石，上堵紅磚抹蚵殼灰；入口榻受的鏡面牆有「螭虎圍爐」彩繪，但不少裝飾在戰地政務時期被油漆或水泥遮蓋，泥塑也多遭竊。民國42至47年（1953–1958）曾由何家與國軍共住，民國94年（2005）後無人居住，目前正進行修復規劃。","highlights":["入口榻受的「螭虎圍爐」彩繪與泥塑","外牆七層花崗石下堵與蚵殼灰粉刷","晚清閩南僑匯建築典型的二落大厝格局"],"funFact":"興建人何德奪娶了三位太太，其中第二位是菲律賓人，這棟古厝也成了菲律賓僑匯的見證。","photoSpot":"在屋外拍二落大厝的翹脊正面","visitMin":10,"openNote":"位於金沙鎮浦邊聚落，目前無人居住、尚待修復，未對外開放。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，浦邊這條路上的老房子好多喔，我們今天先看哪一棟？"},{"who":"A","text":"先看何德奪古厝。主人何德奪年輕時到菲律賓打拚，回來以後做借放款生意。"},{"who":"R","text":"借放款？那他是不是金門版的銀行行長？"},{"who":"A","text":"可以這麼想像啦！依古地契推測，這棟二落大厝大約蓋在清光緒10年到28年之間。"},{"who":"R","text":"我聽說他們家的故事很國際化，是真的嗎？"},{"who":"A","text":"沒錯，他娶了三位太太，第二位是菲律賓人，兒子何敬麟後來也到菲律賓發展。"},{"who":"R","text":"一個家族跨兩個國家，難怪官方說它是菲律賓僑匯的見證。"},{"who":"A","text":"可惜入口的泥塑不少在戰地政務時期被油漆、水泥遮蓋，有的還被偷走了。"},{"who":"R","text":"那我到現場就數數看，外牆下面的花崗石是不是剛好七層！"}],"clues":["我的主人娶了三位太太，其中一位來自菲律賓","我的外牆下堵是七層花崗石，入口有螭虎圍爐彩繪","浦邊聚落裡一棟清光緒年間的二落大厝，主人姓何"],"quiz":[{"q":"何德奪是從哪裡經商回鄉的？","options":["印尼","菲律賓","新加坡","越南"],"answer":1,"explain":"何德奪曾旅居菲律賓，返鄉後經營借放款生意。"},{"q":"古厝外牆下堵用了幾層花崗石？","options":["三層","五層","七層","九層"],"answer":2,"explain":"外牆下堵為七層花崗石，上堵紅磚抹蚵殼灰。"}],"images":[{"file":"Kingmenho (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Kingmenho_%28cropped%29.jpg/960px-Kingmenho_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Kingmenho_(cropped).jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-pubianhededuogucuo-0.webp","small":"img/jinsha-pubianhededuogucuo-0-s.webp"}]},{"id":"jinsha-dadiwushoupenggu","name":"大地吳守椪古厝","short":"吳守椪古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.4748,"lng":118.4591,"address":"金門縣金沙鎮大地23號","announced":"2019-01-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190410000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/edff6d6b-1d6c-42e6-8b7d-a51e90bb72a1/大地吳守椪古厝封面.jpg","year":1894,"yearText":"1894年（清光緒20年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"大地聚落規模最大的傳統民宅","intro":"大地吳守椪古厝位於金沙鎮大洋里大地聚落。吳守椪於19世紀中葉下南洋，在新加坡從事枋廊行業致富，清光緒20年（1894）返鄉興建自宅，花費7000多兩白銀，木料、紅料、石材都從閩南購置，並聘閩南匠師施工，光石材就耗費石匠三年工時。建築為二落大厝加左護龍、護龍後側起疊樓，是大地聚落規模最大的傳統民宅；聚落房屋多坐東北朝西南，這座卻坐東南朝西北。前落與護龍牆面有萬字紋、八角配十字的磚組砌，門廊牆面的花鳥泥塑在金門少見。目前長年閒置，屋頂嚴重破損。","highlights":["前落牆面萬字紋與八角配十字的磚組砌","門廊牆面在金門少見的花鳥泥塑","與聚落方向不同的坐東南朝西北座向"],"funFact":"光是這間古厝要用的石材，就讓石匠足足做了三年。","photoSpot":"在屋外拍前落牆面的磚組砌花紋","visitMin":10,"openNote":"位於金沙鎮大地聚落。私人產業，長年閒置，屋頂與護龍嚴重損壞，請在外觀參觀並保持安全距離，勿擅入。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，大地聚落的房子都朝同一邊，怎麼只有這一間轉了個方向？"},{"who":"A","text":"被你發現了！聚落大多坐東北朝西南，吳守椪古厝卻坐東南朝西北，而且是大地規模最大的傳統民宅。"},{"who":"R","text":"最大又最有個性，這房子的主人是誰呀？"},{"who":"A","text":"吳守椪19世紀中葉下南洋，在新加坡做枋廊生意致富，清光緒20年回鄉蓋了這座二落大厝加護龍。"},{"who":"R","text":"那他一定很講究吧，到底花了多少錢？"},{"who":"A","text":"7000多兩白銀，木料、石材全從閩南買，光是石材就讓石匠做了三年。"},{"who":"R","text":"三年！我寫一份暑假作業都要拖到最後一天了。"},{"who":"A","text":"所以細節特別精緻，牆面用磚拼出萬字紋和八角配十字。可惜現在長年閒置，屋頂破損得很嚴重。"},{"who":"R","text":"好心疼！大家請在屋外安全距離，找找牆上用磚拼出的萬字紋吧！"}],"clues":["整個聚落大多朝西南，只有我坐東南朝西北","我的石材讓石匠足足做了三年","我是大地聚落規模最大的傳統民宅，光緒20年落成"],"quiz":[{"q":"吳守椪在新加坡從事什麼行業致富？","options":["橡膠園","枋廊行業","胡椒園","航運業"],"answer":1,"explain":"吳守椪下南洋後在新加坡從事枋廊行業致富。"},{"q":"古厝所需石材耗費石匠多少工時？","options":["半年","一年","十年","三年"],"answer":3,"explain":"屋宅所需石材即耗費石匠三年工時。"}],"images":[]},{"id":"jinsha-cidegong","name":"慈德宮","short":"慈德宮","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["寺廟"],"lat":24.48621,"lng":118.4123,"address":"金門縣金沙鎮後浦頭99號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-04-25/aa289a90-f4d0-4dfa-ac1d-30e1e665eb80/慈德宮.jpg","year":1894,"yearText":"約1894年（清光緒20年鼠疫後興建）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"為祈求遏止鼠疫而建，奉祀明代進士黃偉","intro":"慈德宮位於金沙鎮後浦頭聚落，面臨榮湖，主祀黃府大王爺黃偉。黃偉（1488–1538）為汶水黃氏第五世，明正德9年（1514）進士，是金門明代第二位進士，曾任刑部郎中及南雄、松江知府，為官剛正，被尊為「品德完人」。廟址在明末原為一座小廟。清光緒20年（1894）金門鼠疫流行，在印尼經營航運的黃卓科母親與妻小皆因鼠疫過世，他向南洋僑民募款興建慈德宮，另祀名醫先生與蔡先生，祈求遏止疫病。相傳由名匠王益順設計監造，石雕由兩批惠安石匠對場施作。","highlights":["前落雙榻受與三川門的石雕、交趾陶","川亭兩側龍虎井牆面的龍、虎交趾陶","正殿神龕仍保留原始樣貌的彩繪"],"funFact":"廟裡除了黃府大王爺，還祀奉名醫先生與蔡先生，都是為了祈求遏止傳染病蔓延。","photoSpot":"在廟埕拍三川脊與榮湖水岸","visitMin":20,"openNote":"位於金沙鎮後浦頭聚落、榮湖畔，依廟方時間開放參觀；參觀請保持安靜、尊重祭祀。鄰近黃卓彬洋樓，可搭金門縣公車到沙美一帶，或開車、騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你知道金門也曾被瘟疫嚇壞過嗎？清光緒20年，鼠疫在金門到處流行。"},{"who":"R","text":"鼠疫！Allan，那後浦頭的人怎麼辦？"},{"who":"A","text":"在印尼做航運的黃卓科，母親和妻小都因鼠疫過世。他很傷心，就向南洋僑民募款，蓋了這座慈德宮。"},{"who":"R","text":"好令人難過的起因。那廟裡拜的是哪位神明？"},{"who":"A","text":"主祀黃府大王爺，也就是明代進士黃偉。他做官剛正不阿，被尊稱為品德完人，另外還祀名醫先生和蔡先生。"},{"who":"R","text":"有名醫先生坐鎮，真的是全方位守護健康！"},{"who":"A","text":"而且相傳這座廟是名匠王益順設計的，石雕由兩批惠安石匠對場施作，左右各做一邊，互相較勁。"},{"who":"R","text":"一間廟兩隊比賽，難怪雕得這麼精緻！"},{"who":"A","text":"進廟後走到川亭兩側，看看龍井和虎井牆上的交趾陶，比比看哪一邊你比較喜歡。"}],"clues":["我因一場鼠疫而誕生，由南洋僑民募款興建","我主祀被尊為「品德完人」的明代進士","我在後浦頭榮湖畔，供奉黃府大王爺"],"quiz":[{"q":"慈德宮的興建起因與什麼事件有關？","options":["海盜侵擾","鼠疫流行","大旱缺水","颱風災害"],"answer":1,"explain":"光緒20年鼠疫流行，黃卓科募款興建慈德宮。"},{"q":"慈德宮主祀的黃府大王爺是哪位人物？","options":["僑商黃卓科","開浯始祖黃守恭","船商黃奕本","明代進士黃偉"],"answer":3,"explain":"慈德宮主祀黃偉，為金門明代進士第二人。"}],"images":[]},{"id":"jinhu-huqianchenshigucuo","name":"湖前陳氏古厝群","short":"湖前陳氏古厝群","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.4361,"lng":118.41097,"address":"金門縣金湖鎮湖前46、47、48、49、56、57號","announced":"2016-02-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20160201000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-08-15/ff5480e8-be48-41f1-b001-1022fbcc8b41/1.湖前陳氏古厝群-代表圖像.jpg","year":1900,"yearText":"清末至民國初年（約1900至1930年代）","era":"qing","themes":["閩南古厝","宗祠家廟","聚落地景"],"yearUnknown":false,"summary":"五兄弟闖蕩新加坡後回鄉蓋的古厝群","intro":"湖前陳氏古厝群位於金湖鎮湖前聚落，湖前原名「碧湖」，因村旁有兩座湖泊得名。古厝群由陳聯丕的五個兒子興建：長子陳芳坑18歲時曾遭海盜綁架勒贖，獲釋後赴新加坡發展，與兄弟合力經營洋行與木材業，致富後陸續返鄉建屋，並委派泉州工匠來金施工。登錄範圍共6棟，包括陳氏宗祠（1734年落成，1989年改建為鋼筋混凝土）與5棟清末至民初的二落大厝。陳芳窗古厝正面的銅錢形磚砌、交趾陶與石雕最為精美，陳芳猷古厝的內嵌式祖龕在金門罕見。部分古厝仍有族人居住，其他則閒置。","highlights":["陳芳窗古厝正面銅錢形磚砌與交趾陶裝飾","陳芳猷古厝金門罕見的內嵌式祖龕","陳芳窗古厝正廳木柱上方的天使與民間故事木楣"],"funFact":"1936年陳芳猷的五子陳慶豹從事賽馬，還把馬養在古厝左側的陟歸裡。","photoSpot":"在陳芳窗古厝前拍銅錢紋磚牆","visitMin":25,"openNote":"位於金湖鎮湖前聚落，含宗祠與多棟古厝，部分仍有人居住。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；宗祠為祭祀空間，請保持肅靜。","dialogue":[{"who":"A","text":"湖前以前叫「碧湖」，因為村邊有兩座湖。這一排古厝，背後是五兄弟一起打拚的故事。"},{"who":"R","text":"五兄弟？聽起來像熱血漫畫的開頭！"},{"who":"A","text":"還真的很熱血。大哥陳芳坑18歲被海盜綁架勒贖，平安回來後決定去新加坡闖天下，後來把弟弟們也找去。"},{"who":"R","text":"被綁架還能逆轉人生，太勵志了！"},{"who":"A","text":"他們在新加坡經營洋行和木材生意，賺了錢就回來蓋房子，還請新加坡的泉州師傅專程來金門施工。"},{"who":"R","text":"跨國工程團隊耶！那哪一棟最漂亮？"},{"who":"A","text":"陳芳窗古厝的正面最精采，磚頭排成銅錢形狀，還有交趾陶。屋裡木柱上竟然站著小天使，中西合璧。"},{"who":"R","text":"閩南古厝裡有天使，好特別！還有什麼趣事？"},{"who":"A","text":"1936年有位子孫玩賽馬，把馬養在古厝側邊。請你在屋外找找，哪面牆的磚排成了銅錢的樣子。"}],"clues":["我的村子舊名碧湖，因為有兩座湖","我由五兄弟在新加坡致富後陸續回鄉興建，有一棟還養過賽馬","我是湖前的陳家宗祠與古厝群"],"quiz":[{"q":"湖前聚落的舊名是什麼？","options":["碧湖","下坑","平林","陳坑"],"answer":0,"explain":"湖前原名碧湖，因擁有兩座湖泊而得名。"},{"q":"興建古厝群的陳氏兄弟在哪裡發展事業？","options":["緬甸","菲律賓","新加坡","日本"],"answer":2,"explain":"陳芳坑等兄弟在新加坡經營洋行與木材業致富。"}],"images":[]},{"id":"jinsha-houshuitouhuangyi","name":"后水頭黃奕本古厝","short":"黃奕本古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.48412,"lng":118.41563,"address":"金門縣金沙鎮后水頭12號","announced":"2018-10-23","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20181024000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/8e13fed0-2230-4f64-ae72-faf64a04954e/后水頭黃奕本古厝封面.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝","僑鄉洋樓","宗教信仰"],"yearUnknown":true,"summary":"金門信奉基督教先驅家族的古厝","intro":"后水頭黃奕本古厝位於金沙鎮后水頭聚落，由一落四櫸頭與前迴向五腳基疊樓組成，前方洋樓是聚落唯一的洋樓。黃奕本從事往來廈門的船隊貿易與鹽場投資，接觸西方文化較早，家族成為金門信奉基督教的先驅，正廳對聯「信主居仁永膺多福，蒙神成聖丕錫遐齡」即可見其信仰。古厝由一落大厝逐步增建為一落四櫸頭，牆上仍看得到增建接縫；前方疊樓為了尊重祖厝簷高，將外深井地坪降低約50公分。日軍占領時期與戰後國軍都曾使用，外牆至今留有「軍民合作」等當時的標語。","highlights":["正廳融入信仰的對聯「信主居仁永膺多福」","外牆上歷次增建銜接的痕跡","疊樓柱上「知廉恥辨生死」等當時標語"],"funFact":"黃奕本的大女兒黃鴛鴦曾到鼓浪嶼念神學院，嫁給牧師後回鄉在西園興建佈道所。","photoSpot":"在屋外拍五腳基疊樓與牆上標語","visitMin":15,"openNote":"位於金沙鎮后水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車到沙美一帶，或開車、騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，逛了這麼多閩南古厝，你應該很少看到對聯寫著信主兩個字吧？"},{"who":"R","text":"信主？Allan，那不是教會常說的話嗎？怎麼會出現在古厝？"},{"who":"A","text":"因為主人黃奕本常跑廈門做船隊貿易，很早接觸西方文化，他們家是金門信奉基督教的先驅。"},{"who":"R","text":"好前衛！那他們家還有誰也信教？"},{"who":"A","text":"他的大女兒黃鴛鴦去鼓浪嶼念神學院，嫁給牧師，後來回鄉在西園蓋了佈道所和牧師館。"},{"who":"R","text":"一家人都很有行動力耶。那前面這棟洋樓是後來加的嗎？"},{"who":"A","text":"對，古厝是一次次增建出來的，牆上還看得到接縫。前面疊樓為了不壓過祖厝屋簷，還把地坪降低約50公分。"},{"who":"R","text":"為了尊重長輩自動蹲低，這棟樓好有禮貌！"},{"who":"A","text":"這裡是私人住宅，請在屋外看就好。找找疊樓柱子上的當年標語，還有外牆增建留下的接縫吧！"}],"clues":["我的正廳對聯寫著「信主居仁」","我前方的洋樓為了禮讓祖厝，把地坪降低約50公分","我在后水頭聚落，前方有聚落唯一的洋樓"],"quiz":[{"q":"黃奕本家族在金門的宗教信仰有何特別？","options":["創建金門第一座佛寺","金門信奉基督教的先驅","世代主持王爺廟","出了多位天主教神父"],"answer":1,"explain":"黃奕本常往來廈門，家族成為金門信奉基督教先驅。"},{"q":"前方疊樓為什麼把外深井地坪降低？","options":["避免雨季淹水","方便停放牛車","躲避砲彈攻擊","尊重祖厝的簷高"],"answer":3,"explain":"為尊重屋後祖厝簷高，將地坪降低約50公分。"}],"images":[]},{"id":"jincheng-houpudongmenjing","name":"後浦東門境洪氏古厝","short":"東門境洪氏古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.43106,"lng":118.31908,"address":"金門縣金城鎮珠浦東路19號","announced":"2019-01-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190410000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/899fc85c-e3e5-4d07-a730-332c06355052/(0)封面.jpg","year":1905,"yearText":"約1900年代（清光緒末年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"後浦東門境洪家僅存的二落大厝","intro":"後浦東門境洪氏古厝位於金城鎮珠浦東路，是後浦東門境洪家僅存的古厝。洪氏先祖由晉江遷居金門，原住後浦北門境，後來長房遷往東門境，在代天府西側發展。清光緒末年，七世祖洪中來以屠宰販肉起家、經商有成，相傳與兄弟合建這座二落大厝，木料、紅料與石材都從泉州一帶購置，並聘閩南匠師營造。洪中來熱心東門境公共事務，地方稱他為「東門三王爺」之一。古厝前落匾額「奎璧聯輝」，正立面磚雕多樣，水車堵與鏡面堵為手繪彩繪，兩落屋頂皆為硬山馬背，脊墜有雲紋、磬牌、燈籠框、蝙蝠等泥塑。","highlights":["前落匾額「奎璧聯輝」","正立面多樣磚雕與手繪螭龍團爐彩繪","馬背脊墜的雲紋、磬牌、燈籠框、蝙蝠泥塑"],"funFact":"古厝前原是後浦主要道路，民國55年政府填平水池、新建市場後，古厝就隱身在鬧市後方。","photoSpot":"在宅前拍「奎璧聯輝」匾額與磚雕","visitMin":10,"openNote":"位於金城鎮珠浦東路，後浦東門市場後方。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可從金城車站步行前往。","dialogue":[{"who":"A","text":"後浦東門市場熱鬧滾滾，可是阿拉蕾，市場後面藏著一間百年古厝，你有發現嗎？"},{"who":"R","text":"藏在市場後面？它是在跟我們玩捉迷藏嗎？"},{"who":"A","text":"可以這麼說。以前它前面是主要道路，民國55年填平水池蓋了市場，它就躲到鬧市後面去了。"},{"who":"R","text":"那這間古厝的主人是做什麼的呢？"},{"who":"A","text":"七世祖洪中來原本殺豬賣肉，後來經商有成，清光緒末年相傳和兄弟一起蓋了這座二落大厝。"},{"who":"R","text":"賣豬肉也能蓋出這麼漂亮的房子，好厲害！"},{"who":"A","text":"他很熱心地方事務，大家稱他「東門三王爺」之一。我逛完市場，也想去吃碗蚵仔麵線當一下王爺。"},{"who":"R","text":"你只是想吃吧！我先去門口找那塊寫著「奎璧聯輝」的匾額，再看看屋脊下的蝙蝠泥塑！"}],"clues":["我的主人以屠宰販肉起家，被稱為「東門三王爺」之一","政府填平水池建市場後，我就隱身在鬧市後方","後浦東門境洪家唯一留下的二落大厝，匾額寫「奎璧聯輝」"],"quiz":[{"q":"洪中來在地方上被稱為什麼？","options":["後浦大總理","北門三林","東門三王爺","酉堂百萬祖"],"answer":2,"explain":"洪中來熱心東門境事務，人稱東門三王爺之一。"},{"q":"古厝前落的匾額寫的是？","options":["奎璧聯輝","振起斯文","文章華國","紫雲衍派"],"answer":0,"explain":"前落匾額為「奎璧聯輝」。"}],"images":[]},{"id":"jinsha-xishanqianlishijia","name":"西山前李氏家廟","short":"西山前李氏家廟","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["祠堂"],"lat":24.49399,"lng":118.42769,"address":"金門縣金沙鎮西山前22號","announced":"1999-06-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19990615000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-26/e56c7674-0fbe-4d53-8409-71d6944d08e3/封面.png","year":1906,"yearText":"約1906年（清光緒32年）","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"牆上留著「忠義廉節」壁字的單姓家廟","intro":"西山前李氏家廟位於金沙鎮西山前聚落，居民全姓李，堂號「桂林」。官方記載二世祖李孫助在明洪武年間任守禦百戶，鎮守小嶝島抵禦倭寇而陣亡，遺孀攜子到金門避難，繁衍成族。清嘉慶至光緒年間，族人在新加坡開設「九八行」批發行多達十八家，匯款返鄉興建宅第與家廟。依牆上落款推測，家廟約建於清光緒32年（1906）。建築為三開間兩落兩廊，燕尾翹脊，門前有抱鼓石，正廳大規壁內牆留有創建時的「忠義廉節」四字，祖龕上懸「進士」「總戎」「奉政大夫」等匾。右側牆面留有軍事標語「安全第一」。","highlights":["大規壁內牆創建時留下的「忠義廉節」四字","祖龕上的「進士」「總戎」「奉政大夫」匾","右側立面牆上的「安全第一」標語"],"funFact":"九八行就是批發行，因抽取二分利潤而得名，西山前李氏在新加坡開了十八家。","photoSpot":"在廟埕拍燕尾翹脊與門前抱鼓石","visitMin":15,"openNote":"位於金沙鎮西山前聚落，官方未公布開放時間，門扇關閉時請在外觀參觀，並尊重宗族祭祀空間。鄰近西山前李宅，開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，考考你：九八行是什麼？提示一下，跟九十八元沒關係喔。"},{"who":"R","text":"那是九點開到八點的店？還是賣九八折的店？"},{"who":"A","text":"都不對！九八行是批發行，抽二分利潤所以叫九八。西山前李氏在新加坡就開了十八家。"},{"who":"R","text":"十八家！那他們賺了錢都拿回來做什麼？"},{"who":"A","text":"蓋宅第、蓋家廟。這座李氏家廟依牆上落款推測，大約在清光緒32年建成。"},{"who":"R","text":"那家廟裡面有什麼必看的寶貝嗎？"},{"who":"A","text":"正廳兩側牆上留著創建時寫的「忠義廉節」四個大字，祖龕上還有進士和總戎的匾額。"},{"who":"R","text":"門口那兩顆圓圓的石頭又是什麼？"},{"who":"A","text":"那是抱鼓石。最後繞到右側牆面，找找「安全第一」四個字，那是駐軍留下的標語。"}],"clues":["我的子孫在新加坡開了十八家九八行","我的牆上寫著「忠義廉節」，側牆還有「安全第一」","桂林李氏聚落中心的兩落燕尾家廟"],"quiz":[{"q":"「九八行」指的是哪一種商行？","options":["當鋪","錢莊","船行","批發行"],"answer":3,"explain":"九八行即批發行，因獲取二分利潤而得名。"},{"q":"正廳大規壁內牆留有哪四個字？","options":["忠孝傳家","忠義廉節","禮義廉恥","文章華國"],"answer":1,"explain":"「忠義廉節」為創建時留下的壁字。"}],"images":[{"file":"Kingmenlee.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Kingmenlee.jpg/960px-Kingmenlee.jpg","page":"https://commons.wikimedia.org/wiki/File:Kingmenlee.jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-xishanqianlishijia-0.webp","small":"img/jinsha-xishanqianlishijia-0-s.webp"}]},{"id":"jinsha-yangdichendumie","name":"陽翟陳篤篾、陳篤浪古厝","short":"陳篤篾陳篤浪古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.4796,"lng":118.4284,"address":"金門縣金沙鎮陽翟18號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/ef4bce23-7b71-474d-b03e-653fcf73903c/(1)封面.png","year":1910,"yearText":"1910年（清宣統2年）興建，1917年（民國6年）竣工","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"越南僑商出資、堂弟監造的雙落大厝","intro":"陽翟陳篤篾、陳篤浪古厝位於金沙鎮陽翟聚落。陳篤篾清光緒22年（1896）前往安南（今越南）經營米糧、雜貨，後來種植橡膠致富，並帶堂弟陳篤浪的弟弟到新加坡謀生。清宣統2年（1910）陳篤篾寄回僑匯建屋，留鄉務農的陳篤浪感念此情，挺身監造，民國6年（1917）完工。建築為二落大厝帶左突歸，前突歸上起疊樓，正門匾題「科第流芳」，官方視為民國初年中西混合閩式建築的案例。民國37年（1948）起國軍進駐，屋主遷住鄰房，此宅先後作為師部、衛生連與戰車連駐所，前廳房內仍有防空洞；屋主事先藏起的門板與祖龕則保持原貌。","highlights":["正門上方的「科第流芳」匾額","前突歸上起的疊樓與圓脊脊墜泥塑","鏡面牆底石的卍字與捲草雕刻"],"funFact":"駐軍進駐前，屋主先把木門窗板和祖龕藏到鄰房，所以門板和祖龕至今仍是原貌。","photoSpot":"在前埕院牆外拍疊樓與二落屋脊","visitMin":15,"openNote":"位於金沙鎮陽翟聚落，後裔仍居住於此，建築損壞嚴重、尚待修復。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。也請與老屋保持距離。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，為什麼這棟古厝的名字裡有兩個人？"},{"who":"A","text":"因為一個出錢、一個出力。陳篤篾在越南做米和橡膠生意，清宣統2年寄錢回來蓋房子。"},{"who":"R","text":"那名字裡的另一位陳篤浪，負責做什麼？"},{"who":"A","text":"他留在陽翟務農，感謝篤篾帶自己的弟弟出洋謀生，就扛下監工，一路蓋到民國6年完工。"},{"who":"R","text":"一個寄錢一個顧工地，這是最強堂兄弟組合！"},{"who":"A","text":"後來國軍進駐，這裡先後當過師部、衛生連和戰車連駐所，前廳的房間裡還有防空洞。"},{"who":"R","text":"那原本的門窗是不是都被拆走了？"},{"who":"A","text":"屋主很機警，事先把木門窗和祖龕藏到隔壁，所以門板到現在還是原貌。"},{"who":"R","text":"那我要在外面找找大門上的匾額，看看「科第流芳」四個字！"}],"clues":["我的名字裡有兩位堂兄弟，一位出錢、一位監工","我當過師部和衛生連，房間裡還有防空洞","陽翟聚落清宣統年間動工、門匾題科第流芳的大厝"],"quiz":[{"q":"陳篤篾是在哪裡經商致富的？","options":["菲律賓","印尼","安南，也就是越南","緬甸"],"answer":2,"explain":"陳篤篾前往安南經營米糧、雜貨並種植橡膠。"},{"q":"古厝的門板與祖龕為何能保持原貌？","options":["屋主事先藏到鄰房","駐軍特別保護","後來仿作補回","一直封存在廟裡"],"answer":0,"explain":"屋主事先將木門窗板與祖龕藏於鄰房。"}],"images":[{"file":"Kingmenchen (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Kingmenchen_%28cropped%29.jpg/960px-Kingmenchen_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Kingmenchen_(cropped).jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-yangdichendumie-0.webp","small":"img/jinsha-yangdichendumie-0-s.webp"}]},{"id":"jinning-banglinwangtianqi","name":"榜林王天乞古厝","short":"王天乞古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["宅第"],"lat":24.42838,"lng":118.340351,"address":"金門縣金寧鄉榜林村榜林33號","announced":"2019-01-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190409000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-05-29/6cfa2f48-f5e6-4468-9532-5b4fbedef58d/榜林王天乞古厝.jpg","year":1912,"yearText":"1912年（民國元年）","era":"japan","themes":["閩南古厝"],"yearUnknown":false,"summary":"落成時被譽為榜林最美民居的民國元年大厝","intro":"榜林王天乞古厝位於金寧鄉榜林村榜林聚落。王天乞清末下南洋從事土產貿易，致富後返鄉興建自宅，大廳書法落款為民國元年；他從閩南購置木料、紅料與石材，特聘閩南匠師並親自督造，落成後被鄰里譽為全榜林最美的傳統民居，晚年也在此辭世。古厝為雙落大厝加左護龍，榻受門扇、門印、插角與櫃檯腳雕刻細緻，櫸頭以綠釉花磚搭配紅磚女兒牆。戰地政務時期曾作為學校使用，前埕仍留一小段當年的水泥圍牆；1986年家族在護龍裝設設備自製貢糖，1999年搬離後閒置。目前多處屋頂坍塌、植生深入牆體，亟待修復。","highlights":["大廳中檔壁落款民國元年的書法字畫","雙落脊墜精美泥塑與獅、魚脊塞","櫸頭綠釉花磚搭配紅磚女兒牆"],"funFact":"這棟古厝的護龍在1986年曾裝設設備自製貢糖，古蹟裡飄過貢糖香。","photoSpot":"在前埕外拍雙落翹脊與脊墜泥塑","visitMin":10,"openNote":"位於金寧鄉榜林村榜林聚落。私人古厝目前閒置，多處屋頂坍塌，請在外觀參觀，勿擅入，也勿打擾周邊住戶。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你知道一百多年前，榜林村公認最美的房子是哪一棟嗎？就是眼前這棟王天乞古厝。"},{"who":"R","text":"選美冠軍古厝！它到底是怎麼贏的啊？"},{"who":"A","text":"王天乞清末下南洋做土產貿易，賺了錢回來，從閩南買木料石材，還請閩南匠師、自己回來監工。"},{"who":"R","text":"親自監工，難怪雕刻那麼細，連櫃檯腳都雕得好漂亮。"},{"who":"A","text":"大廳書法還落款民國元年喔。後來戰地政務時期它當過學校，1986年家族還在護龍自製貢糖。"},{"who":"R","text":"貢糖！Allan，你的眼睛突然在發光。"},{"who":"A","text":"古蹟加貢糖，我當然有感。可惜家族搬走後閒置，現在屋頂坍塌、樹根鑽進牆裡，很需要修復。"},{"who":"R","text":"選美冠軍生病了，要趕快幫它看醫生才行。"},{"who":"A","text":"說得好。請你在外面找找脊墜旁邊的脊塞，看看是獅子還是魚的造型？"}],"clues":["我的主人清末下南洋做土產貿易，親自回鄉督造我","我當過學校，後來護龍還做過貢糖","我在榜林，大廳書法落款民國元年"],"quiz":[{"q":"王天乞古厝落成後被鄰里譽為什麼？","options":["金門第一洋樓","最多燕尾的大厝","全榜林最美的傳統民居","最古老的宅第"],"answer":2,"explain":"落成後被鄰里譽為全榜林村落最美的傳統民居。"},{"q":"1986年王家曾在古厝護龍做什麼？","options":["開設雜貨店","釀造高粱酒","經營理髮部","自製貢糖"],"answer":3,"explain":"民國75年在護龍安裝貢糖設備自製貢糖。"}],"images":[]},{"id":"jincheng-houpuxuyunxuanyang","name":"後浦許允選洋樓","short":"許允選洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.430562,"lng":118.316206,"address":"金門縣金城鎮民族路214號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-07-14/4ed6695f-4c0e-45b2-ad7a-3c7d5fce9ec2/後浦許允選洋樓.jpg","year":1915,"yearText":"1911–1915年（清宣統3年至民國4年）","era":"japan","themes":["僑鄉洋樓","名人故居"],"yearUnknown":false,"summary":"為讓祖先「見白」而中間降低的洋樓","intro":"後浦許允選洋樓位於金城鎮民族路，建於1911年至1915年，前落為二層五腳基外廊洋樓，後落為閩南式二坡七架廳堂，是閩南僑鄉受南洋影響的折衷建築。最特別的是二樓外廊只在左右前房疊樓，正面呈凹字形，讓大廳祖先牌位得以「見白」；二樓高度也只有224公分，以免高過後方許氏宗祠，展現傳統倫理對洋樓的制約。興造者許允選（1889–1952）開設「復和行」經營建材與石灰買賣，民國4年（1915）與父親參與爭取金門設縣，後任金門縣商會會長。洋樓於2025年1月修復竣工。","highlights":["正面凹字形五腳基，中間降低讓祖先「見白」","一樓大弧拱、大圓拱與拱尖的拱心石","陽臺綠釉瓶與泥塑瓶並用的欄杆"],"funFact":"洋樓二樓的高度只有224公分，就是為了不高過後方的許氏宗祠。","photoSpot":"在民族路對面拍凹字形正立面","visitMin":15,"openNote":"位於金城鎮民族路，後浦南門一帶，2025年1月修復竣工；內部開放情形請以金門縣文化局公告為準。未開放時請在外觀參觀，勿擅入、勿打擾住戶。可從金城車站步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，你看這棟洋樓，二樓是不是有點怪怪的？"},{"who":"R","text":"嗯，左右兩邊有二樓，中間卻凹下去，好像缺了一顆門牙！"},{"who":"A","text":"形容得太傳神了！這叫凹字形五腳基，中間故意空出來，讓大廳的祖先牌位可以「見白」，看得到天。"},{"who":"R","text":"原來是體貼祖先！那二樓看起來也比較矮？"},{"who":"A","text":"對，二樓只有224公分高，因為後面是許氏宗祠，洋樓不能比宗祠還高。"},{"who":"R","text":"還好Allan是光頭，撞到也不怕弄亂髮型！那主人許允選是做什麼的？"},{"who":"A","text":"他開復和行賣建材和石灰，民國4年還和父親一起參與爭取金門設縣，後來當過縣商會會長。"},{"who":"R","text":"又會做生意又關心地方，難怪洋樓蓋得這麼講究！"},{"who":"A","text":"請你站在對街，找找一樓拱圈頂端的拱心石，再數數看二樓左右各有幾個小圓拱！"}],"clues":["我的二樓只有224公分高，因為不能高過後方宗祠","我的主人曾參與爭取金門設縣","後浦民族路上，正面呈凹字形的五腳基洋樓"],"quiz":[{"q":"洋樓正面做成凹字形，是為了什麼？","options":["節省建材","方便通風","防禦盜匪","讓祖先牌位見白"],"answer":3,"explain":"二樓只在左右疊樓，讓大廳祖先牌位得以見白。"},{"q":"許允選開設的「復和行」主要做什麼生意？","options":["建材與石灰","南洋土產","茶葉批發","遠洋船運"],"answer":0,"explain":"復和行從漳州等地進口建材及石灰加工買賣。"}],"images":[]},{"id":"jincheng-xiaoximenmofance","name":"小西門模範廁","short":"小西門模範廁","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["其他設施"],"lat":24.413135,"lng":118.327064,"address":"金門縣金城鎮小西門聚落(金城鎮小西門劃測段150、147、148、149、168地號)","announced":"2007-09-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20070926000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-07/85f8ada5-d7b9-419c-998e-4c85a32a03fc/小西門模範廁.jpg","year":1917,"yearText":"1917年（民國6年）","era":"japan","themes":["公共建築"],"yearUnknown":false,"summary":"僑商出資興建、22口編號的公共廁所","intro":"小西門模範廁位於金城鎮小西門聚落，民國6年（1917）由僑商吳朝枰出資興建。吳朝枰（1854–1936）清同治13年（1874）赴印尼蘇門答臘經商，後至新加坡發展，熱心南洋公益。他返鄉在小西門興建三幢二落大厝，而聚落原本的舊茅坑就在大厝前，為了環境衛生，他與村民協議把廁所遷到村郊西南處，並購地重建「模範廁」。廁所依原有戶數設22口廁池，牆面嵌有磚雕編號；除前段兩間有屋頂外，其餘露天廁池以抽籤分配並立約訂定權屬，各戶自行收集水肥。正面還有洋樓式的曲線山頭。","highlights":["正面洋樓式曲線山頭與「模範廁」門額","嵌在每口廁池牆面上的磚雕編號","兩側煙炙磚與空心花磚組砌的通氣孔"],"funFact":"22口廁池中，吳家使用的1號與2號有屋頂遮蔽，其餘20口露天廁池靠抽籤決定歸屬。","photoSpot":"從正面拍曲線山頭與長條形廁池","visitMin":10,"openNote":"位於金城鎮小西門聚落，官方資料記載全天候開放，為戶外古蹟，請勿攀爬矮牆。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，今天的景點竟然是廁所？你確定沒有帶錯路嗎？"},{"who":"A","text":"沒帶錯，而且它是縣定古蹟！小西門模範廁，民國6年由南洋僑商吳朝枰出錢蓋的。"},{"who":"R","text":"華僑賺了錢回鄉，不是都蓋大房子嗎？怎麼會蓋廁所？"},{"who":"A","text":"大房子他也蓋了，可是舊茅坑就在大厝前面。他跟村民商量，把廁所搬到村外，再重新蓋一座模範廁。"},{"who":"R","text":"原來是為了環境衛生，好有遠見喔！"},{"who":"A","text":"裡面有22口廁池，牆上都嵌了磚雕編號，一戶分配一口，管理得清清楚楚。"},{"who":"R","text":"那誰用哪一間怎麼決定？猜拳嗎？"},{"who":"A","text":"吳家用1號和2號，有屋頂，其他20口露天的靠抽籤，還立契約。水肥自己收去種田，一點都不浪費。"},{"who":"R","text":"連水肥都有產權，太專業了！我要去看看牆上的編號是不是真的排到22號！"}],"clues":["我的每個位置都有編號，還靠抽籤分配","一位南洋僑商為了家門口的衛生，把我搬到村郊","小西門聚落裡，22口池子排成一列的百年公共設施"],"quiz":[{"q":"模範廁共設有幾口廁池？","options":["12口","18口","22口","30口"],"answer":2,"explain":"依原有戶數設置22口廁池，並予以編號。"},{"q":"露天廁池的歸屬是怎麼決定的？","options":["依年齡排序","以抽籤決定","由官府指派","價高者得標"],"answer":1,"explain":"20口露天廁池以抽籤決定位置，並立契約。"}],"images":[]},{"id":"jinhu-dongcunlvchaoyi","name":"東村呂朝怡洋樓(別名:東村雙喜樓 )","short":"東村雙喜樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.42814,"lng":118.44535,"address":"金門縣金湖鎮東村33號","announced":"2015-10-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151027000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-08-25/bcb694dc-f1c0-4158-a7a9-acc5f380ec14/倒塌前建築全景.jpg","year":1920,"yearText":"民國初年（約1910至1920年代）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"二樓紅磚砌雙囍窗的小洋樓","intro":"東村呂朝怡洋樓又名「東村雙喜樓」，位於金湖鎮東村聚落。呂朝怡出生於新加坡，從事船運與貨運，中年返金於民國初年興建此樓；1937年因戰亂與南洋事業返回新加坡，未再回金。1949年起曾借國軍使用，1985年前後因屋頂漏水嚴重而閒置。洋樓以護龍為基地興建，面寬約10.4公尺，格局小巧但仍維持漢式三開間；最大特色是二樓中央拱門兩旁以紅磚砌成「雙囍」字的漏窗。2023年9月海葵颱風帶來大雨，洋樓倒塌，2024年11月完成緊急搶修，坍塌磚瓦已保存，作為日後復建材料。","highlights":["二樓拱門兩旁紅磚砌成的「雙囍」漏窗","以護龍為基地、仍維持三開間的小格局洋樓","保存坍塌磚瓦準備復建的搶修現場"],"funFact":"颱風造成倒塌後，搶修時特別把坍塌的磚瓦收好保存，未來復建要盡量用回原本的材料。","photoSpot":"在屋外遠拍二樓雙囍窗殘存立面","visitMin":10,"openNote":"位於金湖鎮東村聚落。私人住宅，請在外觀參觀，勿擅入；建築於2023年颱風後倒塌，雖已完成緊急搶修，仍請勿靠近。","dialogue":[{"who":"A","text":"東村這棟小洋樓有個喜氣的別名，叫「雙喜樓」，妳猜得到原因嗎？"},{"who":"R","text":"因為主人娶了兩個老婆？還是生了雙胞胎？"},{"who":"A","text":"想太多啦！是二樓拱門兩邊的窗戶，用紅磚砌成「雙囍」字，整面牆就靠它當主角。"},{"who":"R","text":"用磚頭寫字，這比我寫書法還厲害！主人是誰呀？"},{"who":"A","text":"呂朝怡，在新加坡出生，做船運生意，民國初年回來蓋了這棟樓。1937年戰亂，他回新加坡後就沒再回來。"},{"who":"R","text":"那房子後來怎麼了？看起來好像少了一塊。"},{"who":"A","text":"2023年9月海葵颱風的大雨讓它倒塌，2024年11月完成緊急搶修，掉下來的磚瓦都收好，等著以後復建。"},{"who":"R","text":"好像把拼圖碎片收進盒子，總有一天要拼回來！"},{"who":"A","text":"正是這個精神。請在屋外遠遠找一找，殘存的牆面上還看不看得到紅磚砌的囍字。"}],"clues":["我在2023年的颱風中倒塌，磚瓦被收好等待復建","我的主人生於新加坡，做船運生意","我二樓的窗戶用紅磚砌成雙囍字"],"quiz":[{"q":"雙喜樓的名稱來自哪個特色？","options":["門口兩對石獅","屋頂雙燕尾","紅磚砌雙囍字的窗","主人辦了兩場婚禮"],"answer":2,"explain":"二樓拱門兩旁窗戶以紅磚砌成雙囍字。"},{"q":"雙喜樓在2023年因哪個颱風倒塌？","options":["莫蘭蒂颱風","海葵颱風","杜蘇芮颱風","尼伯特颱風"],"answer":1,"explain":"2023年9月海葵颱風大雨衝擊，洋樓倒塌。"}],"images":[]},{"id":"jinsha-houputouhuangzhuo","name":"後浦頭黃卓彬洋樓","short":"黃卓彬洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.4863,"lng":118.41488,"address":"金門縣金沙鎮后浦頭7號","announced":"2019-07-30","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190928000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-07-14/363e0e3c-adaa-4630-a911-d58cffa94539/後浦頭黃卓彬洋樓.jpg","year":1923,"yearText":"1923年（民國12年）竣工","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"只求「堅固」的榮湖畔水岸洋樓","intro":"後浦頭黃卓彬洋樓位於金沙鎮後浦頭聚落，面臨榮湖畔的汶浦水岸。黃卓彬（1870–1939）婚後下南洋，在印尼峇眼亞比從賣豆腐起家，後經營橡膠園致富。民國9年（1920）他返鄉將原有的一落四櫸頭改建為洋樓，只要求「堅固」、不求華美，1923年竣工。建築為二層五腳基洋樓加前迴向，門戶設有銃眼，山牆有西方天使泥塑，脊頭有雄鷹泥塑。1937年家族避禍離金後未再返回；洋樓曾被日軍占用為士官宿舍，戰後作為野戰醫院等用途，外牆留有「雪恥復國」等當時的標語泥塑。2026年1月修復竣工。","highlights":["二樓「紫雲衍派」堂號與兩側天使泥塑","山牆脊頭展翅的雄鷹泥塑","東西兩側牆面的軍管時期標語泥塑"],"funFact":"黃卓彬在印尼是從賣豆腐起家，存錢買地，後來才擁有一整片橡膠園。","photoSpot":"在榮湖畔拍洋樓與水岸倒影","visitMin":15,"openNote":"位於金沙鎮後浦頭聚落、榮湖畔，私人產業，2026年1月修復竣工；內部開放情形請以主管機關公告為準，未開放時請在外觀參觀，勿擅入。鄰近慈德宮，可搭金門縣公車到沙美一帶，或開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，這棟洋樓倒映在湖面上好漂亮，主人一定是大富翁吧？"},{"who":"A","text":"後來是，一開始可不是。黃卓彬到印尼峇眼亞比打拚，是從賣豆腐開始的。"},{"who":"R","text":"賣豆腐！那後來是怎麼變有錢的？"},{"who":"A","text":"他把賺來的錢存下來買地，最後經營橡膠園致富，民國9年回鄉蓋洋樓，只交代一個要求：要堅固。"},{"who":"R","text":"不要華麗只要堅固，好像我挑手機殼的標準！"},{"who":"A","text":"哈，不過門口還是有天使和雄鷹泥塑。可惜1937年日軍侵犯金門，家族避難到印尼，從此再也沒回來住。"},{"who":"R","text":"蓋得這麼用心卻沒能回來，好讓人難過。"},{"who":"A","text":"之後洋樓當過日軍宿舍和國軍野戰醫院。到湖邊找找山牆上的雄鷹泥塑，還有西側牆上的當年標語吧！"}],"clues":["我的主人從賣豆腐做到橡膠園主","我的主人只交代一件事：一定要蓋得堅固","我在榮湖畔的後浦頭，山牆上有天使和雄鷹泥塑"],"quiz":[{"q":"黃卓彬在印尼最後靠什麼生意致富？","options":["開採錫礦","經營橡膠園","經營糖廠","種植胡椒"],"answer":1,"explain":"黃卓彬從賣豆腐起家，最後以經營橡膠園致富。"},{"q":"黃卓彬對這棟洋樓的主要要求是？","options":["華麗氣派","高聳醒目","通風涼爽","堅固耐用"],"answer":3,"explain":"他只希望興建堅固的洋樓，無需過多華美裝飾。"}],"images":[]},{"id":"jinsha-dongxiaoxiaoxian","name":"東蕭蕭顯傳洋樓","short":"蕭顯傳洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.48827,"lng":118.42331,"address":"金門縣金沙鎮東蕭14號","announced":"2019-01-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190411000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-09-12/82c20e33-4ced-4d10-a343-51d6afce39b3/東蕭蕭顯傳洋樓.jpg","year":1925,"yearText":"1925年（民國14年）竣工","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"裝飾華麗的東蕭僑匯洋樓","intro":"東蕭蕭顯傳洋樓位於金沙鎮東蕭聚落。蕭顯傳（1883–1952）18歲赴新加坡，從事船務與海事相關行業。民國13年（1924）他透過陳景蘭創辦的成源商行匯回近萬元龍銀，託堂兄蕭顯回督造，1925年竣工。建築為雙層五腳基洋樓加前落，正面有龍、麒麟、蝙蝠、花草泥塑，二樓窗楣有象徵多子多孫的南瓜泥塑與螭虎泥塑，山牆脊墜飾以老鷹與雙旗；屋內各房設有槍口以防盜。民國38年（1949）後曾作為野戰醫院，之後被徵作軍中特約茶室沙美分室。目前屋頂與樓板多處崩塌，加設鋼棚架保護。","highlights":["正面龍、麒麟、蝙蝠與花草泥塑","二樓窗楣象徵多子多孫的南瓜泥塑","山牆脊墜的老鷹與雙旗泥塑"],"funFact":"蕭顯傳蓋洋樓的近萬元龍銀，是透過陳景蘭創辦的成源商行從新加坡匯回金門的。","photoSpot":"在屋外安全距離拍正面泥塑","visitMin":10,"openNote":"位於金沙鎮東蕭聚落，與蕭顯紀洋樓相鄰。私人產業，屋頂與樓板多處崩塌，加設鋼棚架保護，請在外觀參觀並保持安全距離，勿擅入。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，一百年前沒有網路銀行，南洋的華僑要怎麼把錢寄回金門？"},{"who":"R","text":"我猜是飛鴿傳書？Allan，鴿子背得動錢嗎？"},{"who":"A","text":"哈哈，背不動啦。蕭顯傳在新加坡做船務，民國13年就是透過陳景蘭開的成源商行，匯回近萬元龍銀。"},{"who":"R","text":"原來是僑商幫僑商！那錢匯回來以後，誰負責蓋房子？"},{"who":"A","text":"他請堂兄蕭顯回幫忙督造，隔年洋樓就完工了，是雙層五腳基洋樓加前落。"},{"who":"R","text":"那這棟洋樓最漂亮的地方在哪裡？"},{"who":"A","text":"正面有龍、麒麟、蝙蝠的泥塑，二樓窗楣還有南瓜泥塑。南瓜籽多，代表多子多孫。"},{"who":"R","text":"南瓜也能當祝福，我晚餐要多喝一碗南瓜湯！"},{"who":"A","text":"洋樓現在損壞嚴重，請在外面保持安全距離。找找二樓窗楣上的南瓜泥塑吧！"}],"clues":["我的建屋經費透過另一位僑商的商行匯回金門","我二樓窗楣有象徵多子多孫的南瓜泥塑","我在東蕭聚落，隔壁就是堂弟蓋的洋樓"],"quiz":[{"q":"蕭顯傳的建屋款項是透過哪家商行匯回？","options":["恆美貿易商行","南金號","成源商行","裕發號"],"answer":2,"explain":"蕭顯傳透過陳景蘭創辦的成源商行匯款回鄉。"},{"q":"洋樓窗楣的南瓜泥塑象徵什麼？","options":["多子多孫","五穀豐收","財源廣進","健康長壽"],"answer":0,"explain":"二樓側面窗楣的南瓜泥塑象徵多子多孫。"}],"images":[{"file":"人去樓空.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/%E4%BA%BA%E5%8E%BB%E6%A8%93%E7%A9%BA.jpg/960px-%E4%BA%BA%E5%8E%BB%E6%A8%93%E7%A9%BA.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%BA%BA%E5%8E%BB%E6%A8%93%E7%A9%BA.jpg","artist":"Deepblue5042","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-dongxiaoxiaoxian-0.webp","small":"img/jinsha-dongxiaoxiaoxian-0-s.webp"}]},{"id":"lieyu-xifanglintianlai","name":"西方林天來洋樓","short":"林天來洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["宅第"],"lat":24.435251,"lng":118.238407,"address":"金門縣烈嶼鄉西方13號","announced":"2017-01-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170126000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/904bf3aa-9bba-4beb-83ff-c5023f28466a/西方林天來洋樓.jpg","year":1925,"yearText":"1920年代（民國10年代）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"汶萊僑商洋樓，留有彩繪匠師林天助的筆墨","intro":"西方林天來洋樓位於烈嶼鄉西方聚落。林天來年少時赴汶萊經營雜貨批發致富，匯款返鄉，委託父親林馬與親族協助，自廈門延聘匠司負責設計、施工與採購建材；民國21年（1932）其妻偕養女返鄉入住，林天來本人則於1930年代後期病逝汶萊。建築為五腳基洋樓帶前落及二櫸頭，正立面採粉刷畫磚作法，山頭以蠣殼灰洗石子裝飾盾牌與捲草紋，二樓磚拱高低有別，略異於同類洋樓。女婿林天助是烈嶼知名彩繪匠師，以廟宇連環畫式壁畫聞名，屋內一樓大廳壽屏題字即出自他手。這裡也曾作為私塾、商店與地方事務辦公場所。","highlights":["正立面用灰泥畫出磚紋的粉刷畫磚作法","山頭中央盾牌與兩側捲草紋泥塑","二樓高低有別的磚拱外廊"],"funFact":"女婿林天助當過烈嶼首任保長與官派鄉長，後來辭官專心為廟宇彩繪題字，作品遍布大小金門。","photoSpot":"正面拍二樓高低磚拱與山頭盾牌","visitMin":15,"openNote":"位於烈嶼鄉西方聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可經金門大橋開車或騎車前往。附近還有林氏六路大厝與方宅。","dialogue":[{"who":"A","text":"來到西方聚落，阿拉蕾，你仔細看這棟洋樓的正面，那些紅磚紋路有什麼古怪？"},{"who":"R","text":"看起來像磚，可是又太平整了，是在玩大家來找碴嗎？"},{"who":"A","text":"眼力好！這叫粉刷畫磚，用灰泥畫出磚的樣子，在金門洋樓裡很少見。"},{"who":"R","text":"原來是幫牆壁化妝，畫上磚頭眼線，太會了吧！"},{"who":"A","text":"屋主林天來年少時去汶萊做雜貨批發，賺了錢匯回家鄉，請廈門的匠司來蓋這棟樓。"},{"who":"R","text":"那他有沒有住進這棟漂亮的新房子？"},{"who":"A","text":"民國21年太太帶著養女先回來住，他自己則在1930年代後期病逝汶萊，令人感慨。"},{"who":"R","text":"好可惜。那後來是誰在照顧這棟樓呢？"},{"who":"A","text":"女婿林天助，他是烈嶼有名的彩繪匠師。到外面抬頭看，二樓的磚拱是不是一高一低？"}],"clues":["我的女婿是烈嶼有名的廟宇壁畫匠師","我的正面用灰泥畫出磚紋，二樓磚拱高低不同","我是小金門西方聚落一位汶萊僑商的洋樓"],"quiz":[{"q":"林天來在哪裡經商致富？","options":["新加坡","汶萊","印尼","菲律賓"],"answer":1,"explain":"林天來年少時赴汶萊從事雜貨批發致富。"},{"q":"洋樓正立面的特殊作法是？","options":["馬賽克拼貼","清水紅磚","洗石子浮雕","粉刷畫磚"],"answer":3,"explain":"正立面以灰泥畫出磚紋，稱為粉刷畫磚。"}],"images":[{"file":"烈嶼春日 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/%E7%83%88%E5%B6%BC%E6%98%A5%E6%97%A5_%28cropped%29.jpg/960px-%E7%83%88%E5%B6%BC%E6%98%A5%E6%97%A5_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%83%88%E5%B6%BC%E6%98%A5%E6%97%A5_(cropped).jpg","artist":"Deepblue5042","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/lieyu-xifanglintianlai-0.webp","small":"img/lieyu-xifanglintianlai-0-s.webp"}]},{"id":"lieyu-huangcuohongshigu","name":"黃厝洪氏古厝","short":"黃厝洪氏古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["宅第"],"lat":24.447758,"lng":118.252723,"address":"金門縣烈嶼鄉黃厝37號","announced":"2016-12-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20161226000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/64b049e3-b386-48ab-b54e-0ecde0aa3740/(1)封面.jpg","year":1925,"yearText":"約1920年代（民國10年代）增建護龍疊樓","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"疊樓掛著拉丁字母商號匾的印尼僑商古厝","intro":"黃厝洪氏古厝位於烈嶼鄉黃厝聚落西南隅。洪艾年輕時與兄長洪水矸到印尼北馬魯古的依武經商，創立「金聯發」商號，從事雜貨買賣。事業有成後，約於民國10年代（1920年代）返鄉，在一落四櫸頭祖厝旁增建右護龍疊樓，疊樓規尾以多曲線火焰造型處理，搭配拱圈外廊與花瓶欄杆，是傳統建築過渡到洋樓的案例。一落四櫸頭正面裙堵以烈嶼在地玄武岩亂石砌。最特別的是二樓廳門額以泥塑做出「KIEM DJIAN HOAT」，即「金聯發」的閩南語拼音。九三砲戰後民間自建的防空洞、疊樓外牆的彈痕與軍管時期開設的撞球間、雜貨店，都反映戰地生活。","highlights":["二樓門額以拉丁字母泥塑的商號「金聯發」","疊樓規尾的多曲線火焰造型","烈嶼在地玄武岩亂石砌的裙堵"],"funFact":"民國47年八二三砲戰期間，大厝曾被一顆宣傳彈擊中，所幸沒有爆炸。","photoSpot":"拍疊樓火焰形規尾與拱圈外廊","visitMin":15,"openNote":"位於烈嶼鄉黃埔村黃厝聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；護龍疊樓目前以鋼棚架防護。可經金門大橋開車或騎車前往。鄰近勇士堡、鐵漢堡。","dialogue":[{"who":"A","text":"阿拉蕾，考考你，在金門古厝上看到一排拉丁字母，你會想到什麼？"},{"who":"R","text":"難道是古人留下的無線網路密碼？"},{"who":"A","text":"哈，差一點！黃厝洪氏古厝的疊樓門額，用泥塑拼出拉丁字母，念起來就是閩南語的「金聯發」。"},{"who":"R","text":"金聯發是什麼？聽起來很會賺錢！"},{"who":"A","text":"是屋主洪艾在印尼依武開的商號，賣椰乾、衣料、日用品，生意做得很好。"},{"who":"R","text":"所以他把店名掛回老家，提醒子孫不要忘本？"},{"who":"A","text":"正是飲水思源。他約在民國10年代回鄉，在祖厝旁加蓋疊樓，屋頂側邊還做成火焰般的曲線。"},{"who":"R","text":"那疊樓牆上一點一點的痕跡是什麼？"},{"who":"A","text":"那是八二三砲戰留下的彈片痕跡。請在屋外仰望疊樓，找找那排特別的拉丁字母。"}],"clues":["我的疊樓門額用拉丁字母拼出閩南語商號名","我的主人在印尼依武經商，開了「金聯發」","我是小金門黃厝聚落西南角的古厝，旁邊加了疊樓"],"quiz":[{"q":"疊樓門額上的拉丁字母代表什麼？","options":["家族堂號","建造年份","商號名稱","匠師名字"],"answer":2,"explain":"拉丁字母是商號「金聯發」的閩南語拼音。"},{"q":"洪艾在哪裡經商致富？","options":["印尼依武","新加坡","汶萊","菲律賓"],"answer":0,"explain":"洪艾在印尼北馬魯古的依武創立「金聯發」。"}],"images":[]},{"id":"jinning-huxiayangyunpaoji","name":"湖下楊允泡及楊盤讀古厝","short":"楊允泡古厝","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["宅第"],"lat":24.456496,"lng":118.306661,"address":"金門縣金寧鄉湖埔村湖下91號","announced":"2019-01-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20220428000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/3c988ebb-738f-473f-9bc6-660d8da60742/湖下楊允泡及楊盤讀古厝封面_審查後更新.png","year":1926,"yearText":"1926年（民國15年）竣工","era":"japan","themes":["閩南古厝","戰地史蹟"],"yearUnknown":false,"summary":"前後不相通的罕見三落大厝，滿牆馬約利卡彩磁","intro":"湖下楊允泡及楊盤讀古厝位於金寧鄉湖浦村湖下聚落。楊盤讀、楊允泡兄弟家中原有十位兄弟，後來兩人相依為命，清末民初到新加坡經商致富，返鄉修建舊厝，約1922年動工，依大門匾額「四知世冑」落款，1926年竣工。石料來自惠安、木料來自福州。前二落由楊允泡興建，第三落由楊盤讀興建，第三落由右側外埕進出、不與前方二落相通，是金門罕見的特殊三落大厝。前落榻受牆與對看堵滿貼馬約利卡彩磁，是湖下少見的新加坡僑匯建築。1949年後國軍進駐，第三落牆體留有開射口，大門左右還有衛兵站哨矮座。","highlights":["前落榻受牆與對看堵的馬約利卡彩磁","大門匾額「四知世冑」與民國十五年落款","大門兩側的衛兵站哨矮座與第三落開射口"],"funFact":"這棟三落大厝的第三落要從右側外埕進出，跟前面兩落不相通，像同一棟樓的兩戶人家。","photoSpot":"在前埕拍彩磁榻受牆與「四知世冑」門額","visitMin":15,"openNote":"位於金寧鄉湖浦村湖下聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築多處屋頂坍塌，請勿靠近。可騎機車或開車前往。","dialogue":[{"who":"R","text":"哇，這面牆貼滿花花綠綠的磁磚，好像一本立體的花布圖鑑！"},{"who":"A","text":"那是馬約利卡彩磁，1920年代很流行。這棟是楊允泡和楊盤讀兄弟從新加坡賺錢回來蓋的。"},{"who":"R","text":"兄弟一起蓋，那是不是兩個人各住一半？"},{"who":"A","text":"很接近喔。前面二落是楊允泡蓋的，第三落是楊盤讀蓋的，第三落要從右邊外埕進出，前後不相通。"},{"who":"R","text":"同一棟房子卻有兩個入口，就像住在同一層樓的鄰居！"},{"who":"A","text":"這種三落大厝在金門很少見。石料從惠安運來，木料來自福州，1926年才完工。"},{"who":"R","text":"門口兩邊那兩個矮矮的石座是做什麼用的？"},{"who":"A","text":"1949年後國軍進駐，那是衛兵站哨的矮座。請你在門額找找「四知世冑」旁邊落款的是民國幾年？"}],"clues":["起造我的兄弟原有十位兄弟，後來兩人相依為命","我的第三落要從側邊外埕進出，不和前面相通","我在湖下，門額寫「四知世冑」，滿牆彩磁"],"quiz":[{"q":"楊允泡、楊盤讀兄弟是到哪裡經商致富？","options":["新加坡","菲律賓","印尼","越南"],"answer":0,"explain":"兄弟清末民初前往新加坡經商，累積財富後返鄉。"},{"q":"這棟三落大厝特別的地方是？","options":["屋頂全是圓脊","第三落與前二落不相通","只有單邊護龍","門前有半月池"],"answer":1,"explain":"第三落由右側外埕進出，不與前側二落大厝相通。"}],"images":[]},{"id":"jinsha-dongxiaoxiaoxianji","name":"東蕭蕭顯紀洋樓","short":"蕭顯紀洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.48824,"lng":118.42322,"address":"金門縣金沙鎮東蕭13號","announced":"2019-01-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190410000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-02/e49f6642-0206-4791-b7b6-53d589d05e2a/1.東蕭蕭顯紀洋樓-已加上鋼棚架防護.jpg","year":1927,"yearText":"約1925–1928年（民國14至17年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"與堂兄洋樓並肩、外觀較樸實的洋樓","intro":"東蕭蕭顯紀洋樓位於金沙鎮東蕭聚落，緊鄰蕭顯傳洋樓。蕭顯紀清末赴菲律賓開設九八行，收購五穀雜糧、椰子、橡膠等土產並經營批發零售，事業有成。他見堂兄蕭顯傳返鄉建樓，約於民國14至17年（1925–1928）也在隔壁興建洋樓。兩棟並立，蕭顯傳洋樓裝飾華麗，這棟則相對樸實。建築為五腳基洋樓加前落，正面一、二樓各有五座拱，中央橫批堂號「古榮衍派」；一樓大門為雙層，內門是金門俗稱的「輪錢門」，屋內各房設槍口，神桌、鑄鐵吊燈與防盜鑄鐵窗都是興建時的原物。","highlights":["女兒牆中央的「古榮衍派」橫批堂號","二樓拱廊窗台的防盜鑄鐵欄杆","中央較寬、兩側較窄的五座拱立面"],"funFact":"洋樓落成後蕭顯紀曾返鄉居住，1928年到廈門就醫時病逝，後來葬在金門。","photoSpot":"與隔壁蕭顯傳洋樓同框比較立面","visitMin":10,"openNote":"位於金沙鎮東蕭聚落，與蕭顯傳洋樓相鄰。私人產業，建築損壞、屋頂滲水，請在外觀參觀並保持安全距離，勿擅入。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這兩棟洋樓並排站在一起，好像雙胞胎喔！"},{"who":"A","text":"它們其實是堂兄弟蓋的。哥哥蕭顯傳先蓋，弟弟蕭顯紀看了，也在隔壁蓋了一棟。"},{"who":"R","text":"哥哥有，我也要有！這根本是小孩子比玩具嘛。"},{"who":"A","text":"哈，不過兩兄弟風格不同。蕭顯傳那棟裝飾華麗，蕭顯紀這棟比較樸實，但氣度一點也不輸。"},{"who":"R","text":"那蕭顯紀是在南洋做什麼生意的？"},{"who":"A","text":"他清末到菲律賓開九八行，收購五穀雜糧、椰子、橡膠，再批發零售，事業很成功。"},{"who":"R","text":"九八行聽起來好像在打折！那這棟樓有什麼特別的設計？"},{"who":"A","text":"一樓大門是雙層的，內門叫輪錢門，房間還有槍口，二樓拱廊也裝了鑄鐵欄杆，都是為了防盜。"},{"who":"R","text":"樸實外表下藏著保全系統！大家站在路邊，把兩棟洋樓拍在一起，比比看哪裡不一樣吧！"}],"clues":["我的主人看到堂兄蓋洋樓，也在隔壁蓋了我","我的大門有兩層，內門是金門俗稱的輪錢門","我在東蕭聚落，主人在菲律賓開九八行"],"quiz":[{"q":"蕭顯紀在菲律賓經營什麼生意？","options":["橡膠園","銀器買賣","船務公司","九八行"],"answer":3,"explain":"蕭顯紀清末赴菲律賓開設九八行，收購土產批發零售。"},{"q":"和隔壁蕭顯傳洋樓相比，這棟洋樓外觀如何？","options":["更加華麗","相對樸實","樓層更高","全為木造"],"answer":1,"explain":"蕭顯傳洋樓裝飾較華麗，蕭顯紀洋樓相對樸實。"}],"images":[]},{"id":"jinsha-wukengzhengguhuai","name":"浯坑鄭古懷洋樓","short":"鄭古懷洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.50367,"lng":118.41157,"address":"金門縣金沙鎮浯坑1號","announced":"2016-12-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20161226000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/93e9c17a-b621-4d35-80ce-d9567efffbb0/浯坑鄭古懷洋樓封面.jpg","year":1927,"yearText":"1927年（民國16年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"印尼胡椒商家族的早期五腳基洋樓","intro":"浯坑鄭古懷洋樓位於金沙鎮浯坑聚落。鄭古懷年輕時當船員，後來帶家人到印尼勿里洞發展，兒子們合開九八行經營胡椒、橡膠、丁香，五子鄭樹桐有「胡椒大王」之稱。民國10多年間鄭家商議回鄉建宅，由二子鄭樹擺主持，民國16年（1927）落成。當時金門洋樓尚未盛行，這是較早的純洋樓，仍採承重牆擱檁構造；主樓為五腳基洋樓，二樓女兒牆有泥塑天使，線腳貼日本花磚，另有護龍、後棟洋樓與防空洞遺址。民國26年（1937）日軍占領金門，屋主因反抗，部分房舍遭焚燒；國軍駐金後曾作軍方住所至民國60年（1971）。","highlights":["二樓女兒牆上的泥塑天使","線腳上的日本花磚與弧形窗眉","圍牆基的花崗岩人字砌與平砌"],"funFact":"鄭家在印尼的生意從胡椒一路做到電影院、汽水廠與醬油廠，五子鄭樹桐還有「胡椒大王」稱號。","photoSpot":"在洋樓正前方拍五腳基外廊與女兒牆","visitMin":15,"openNote":"位於金沙鎮浯坑聚落，鄭氏後代偶爾返鄉居住，官方未公布開放時間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這棟洋樓二樓的牆上，是不是站著小天使？"},{"who":"A","text":"眼力很好！那是女兒牆上的泥塑天使，這是鄭古懷家族在民國16年蓋好的洋樓。"},{"who":"R","text":"鄭古懷是誰？名字聽起來很有學問耶。"},{"who":"A","text":"他年輕時當船員，後來帶家人到印尼勿里洞打拚，兒子們開九八行，賣胡椒、橡膠和丁香。"},{"who":"R","text":"賣胡椒能蓋洋樓？那胡椒餅老闆不就都是富翁了！"},{"who":"A","text":"哈哈，規模不一樣啦！五兒子鄭樹桐被叫作「胡椒大王」，生意後來還做到電影院和船運。"},{"who":"R","text":"那這棟洋樓蓋好以後，一直都很平靜嗎？"},{"who":"A","text":"並沒有。民國26年日軍占領金門，屋主反抗，部分房舍被焚燒，後來國軍也曾借住到民國60年。"},{"who":"R","text":"原來漂亮的外牆後面有這麼多故事，我要去找線腳上的日本花磚，看看有幾種花色！"}],"clues":["我的主人家族在印尼以胡椒生意起家","我的女兒牆上站著泥塑天使，線腳貼著日本花磚","浯坑聚落民國16年落成的五腳基洋樓"],"quiz":[{"q":"鄭古懷一家到印尼哪裡發展？","options":["爪哇泗水","勿里洞","蘇門答臘棉蘭","婆羅洲坤甸"],"answer":1,"explain":"鄭古懷帶家人前往印尼勿里洞發展。"},{"q":"五子鄭樹桐在當地有什麼稱號？","options":["橡膠大王","米糧大王","胡椒大王","航運大王"],"answer":2,"explain":"鄭家九八行經營胡椒等生意，鄭樹桐有胡椒大王之稱。"}],"images":[]},{"id":"jinning-guningtoubeishangu","name":"古寧頭北山古洋樓","short":"北山古洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["宅第"],"lat":24.47911,"lng":118.31263,"address":"金門縣金寧鄉古寧村46-5號","announced":"2015-02-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20191002000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/06f055f6-5d84-4eb6-b1f7-851c2bab32df/00封面.jpg","year":1928,"yearText":"約1920年代末期起建（民國10年代末），1937年完成洋樓彩繪","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"牆上彈孔見證古寧頭戰役的僑匯洋樓","intro":"古寧頭北山古洋樓位於金寧鄉古寧村北山聚落，由二落大厝加左護龍二層疊樓組成。李金魚、李炎芽、李天祝三兄弟在菲律賓馬尼拉經營椰子貿易，返鄉建二落大厝，約1932至1933年集資增建護龍洋樓，室內彩繪完成於1937年，是僑匯影響下由傳統大厝轉向洋樓的經典案例。日軍占領金門期間兄弟避居菲律賓，洋樓曾被日本警察作為駐在所。1949年10月古寧頭戰役，這裡成為兩軍交戰的重點建築，也是目前確知戰役中曾被共軍占領的建築，後寮牆與洋樓外牆至今留有巷戰彈孔，採原貌保存。戰後長年由國軍使用，2006年修復，2019年指定為縣定古蹟。","highlights":["二落大厝後寮牆與洋樓外牆原貌保存的彈孔","洋樓二樓彩繪中的輪船、汽車、長堤等時代圖案","洋樓側面的窗楣造形、花瓶欄杆與薔薇泥塑"],"funFact":"洋樓二樓的彩繪裡畫了輪船和汽車，是1930年代僑鄉人家眼中的新潮題材。","photoSpot":"在洋樓外側拍保留彈孔的外牆與窗楣","visitMin":20,"openNote":"位於金寧鄉古寧村北山聚落，由金門國家公園管理處管理。二落大厝修復後作為民宿使用，左護龍洋樓尚未整修、未對外開放；請在外觀參觀彈孔牆面，勿擅入、勿打擾住宿旅客。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"A","text":"阿拉蕾，北山這棟洋樓是古寧頭最有名的建築之一，你先看看牆上那些密密麻麻的小洞。"},{"who":"R","text":"是蟲蛀嗎？還是有人在牆上練習射飛鏢？"},{"who":"A","text":"都不是。1949年10月古寧頭戰役，這裡發生激烈巷戰，那些是當年留下的彈孔。"},{"who":"R","text":"原來是真的子彈，突然覺得好沉重。"},{"who":"A","text":"這是目前確知戰役中曾被共軍占領的建築，很多人在這場戰役中失去生命，所以彈孔照原貌保存，提醒大家珍惜和平。"},{"who":"R","text":"那這棟洋樓一開始是誰出錢蓋的呢？"},{"who":"A","text":"李金魚三兄弟在菲律賓馬尼拉做椰子貿易，先蓋二落大厝，1930年代再加蓋兩層的護龍洋樓。"},{"who":"R","text":"做椰子生意蓋洋樓，這就是傳說中的椰子豪宅吧！"},{"who":"A","text":"哈，可以這樣記。請你在洋樓側面找一找，花瓶欄杆旁邊有沒有薔薇花的泥塑？"}],"clues":["我的主人三兄弟在馬尼拉經營椰子貿易","日軍占領期間，我曾被當作警察駐在所","我的外牆留著1949年巷戰的彈孔，位在古寧頭"],"quiz":[{"q":"起造北山古洋樓的李家三兄弟在菲律賓經營什麼生意？","options":["橡膠種植","椰子貿易","錫礦開採","茶葉批發"],"answer":1,"explain":"李金魚等三兄弟在馬尼拉經營椰子貿易後返鄉興建。"},{"q":"北山古洋樓外牆的彈孔，主要來自哪一場戰事？","options":["九三砲戰","八二三砲戰","日軍攻占金門","古寧頭戰役"],"answer":3,"explain":"1949年10月古寧頭戰役的巷戰在此留下彈孔遺痕。"}],"images":[{"file":"古寧頭北山古洋樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bd/%E5%8F%A4%E5%AF%A7%E9%A0%AD%E5%8C%97%E5%B1%B1%E5%8F%A4%E6%B4%8B%E6%A8%93.jpg/960px-%E5%8F%A4%E5%AF%A7%E9%A0%AD%E5%8C%97%E5%B1%B1%E5%8F%A4%E6%B4%8B%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%8F%A4%E5%AF%A7%E9%A0%AD%E5%8C%97%E5%B1%B1%E5%8F%A4%E6%B4%8B%E6%A8%93.jpg","artist":"張雅倫","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinning-guningtoubeishangu-0.webp","small":"img/jinning-guningtoubeishangu-0-s.webp"}]},{"id":"jinsha-dadiwuxinquanzhai","name":"大地吳心泉宅","short":"吳心泉宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.47491,"lng":118.45941,"address":"金門縣金沙鎮大地12號","announced":"2012-12-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20121207000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-24/8381017a-ac85-42cc-ba11-3e610fd1fb88/01.jpg","year":1929,"yearText":"1929年（民國18年）動工，1933年完成","era":"japan","themes":["閩南古厝","僑鄉洋樓","名人故居"],"yearUnknown":false,"summary":"麻六甲「山王」後代捐出的僑鄉大宅","intro":"大地吳心泉宅位於金沙鎮大洋里大地聚落。吳心泉（1887–1950）早年與兄弟下南洋，從泰國碼頭苦力做起，後在馬來西亞麻六甲創立金泉成、金泉發商號，承攬國泰大橋等地標工程，與經營船運的弟弟吳仲坦並稱「山王」「海王」。他在民國18至20年（1929–1931）興建二落大厝，1931至1933年再增建右護龍與洋式疊樓。宅第中西合璧，榻受有泉州白石與馬約利卡彩磁，龍虎門上設玻璃刀山與槍口。2016年後代將祖宅捐給金門縣政府，2020年修復完成，是金門首件旅外金僑捐贈祖厝並修復的案例。","highlights":["榻受的泉州白石與馬約利卡彩磁貼面","龍虎門上的玻璃刀山與槍口防禦設施","右護龍五彎曲形脊頭與洋式拱廊疊樓"],"funFact":"1937年日軍登陸金門前夕，吳心泉派專船把親族接到麻六甲居住。","photoSpot":"在前埕拍榻受彩磁與右側洋式疊樓","visitMin":30,"openNote":"位於金沙鎮大地聚落，已由後代捐贈金門縣政府並於2020年修復完成，活化為駐縣藝術家創作展示據點；開放時間請以金門縣文化局公告為準，未開放時請在外觀參觀。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，你聽過山王和海王嗎？這可不是武俠小說，是麻六甲華人對一對兄弟的稱呼。"},{"who":"R","text":"好帥的外號！Allan，他們是誰呀？"},{"who":"A","text":"哥哥吳心泉做營造業，蓋橋、填海造路，弟弟吳仲坦做船運，一個管山、一個管海。"},{"who":"R","text":"那他們是一開始就這麼厲害的嗎？"},{"who":"A","text":"才不是，他們先在泰國碼頭當苦力，後來到麻六甲開店創業，一步一步打拚出來的。"},{"who":"R","text":"從苦力變山王，太勵志了！那這棟房子就是他蓋的？"},{"who":"A","text":"對，民國18年起建，先蓋二落大厝，再加洋式疊樓。門口有泉州白石和彩色磁磚，牆上還有玻璃刀山防小偷。"},{"who":"R","text":"又漂亮又能防盜，好像有保全的豪宅！"},{"who":"A","text":"2016年他的後代把祖厝捐給縣政府，修好後成了藝術家創作展示的據點。到現場找找龍虎門上那排玻璃刀山吧！"}],"clues":["我的主人被稱為「山王」，弟弟則是「海王」","我的後代在2016年把我捐給縣政府","我在大地聚落，是麻六甲僑領回鄉蓋的大宅"],"quiz":[{"q":"吳心泉在麻六甲被稱為什麼？","options":["山王","海王","橋王","糖王"],"answer":0,"explain":"吳心泉做營造業稱山王，弟弟吳仲坦做船運稱海王。"},{"q":"吳心泉宅修復後活化為什麼用途？","options":["縣史館","民俗文物館","藝術家創作展示據點","遊客服務中心"],"answer":2,"explain":"修復後活化為駐縣藝術家創作展示據點。"}],"images":[]},{"id":"jinhu-chenqizaiyanglou","name":"陳期宰洋樓","short":"陳期宰洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.44451,"lng":118.41511,"address":"金門縣金湖鎮山外段269地號","announced":"2015-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150211000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/ed69abdf-034f-4d32-8fc4-f29308113cde/01封面.jpg","year":1930,"yearText":"1930年（民國19年）興建，翌年完工","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"四面迴廊的山外洋樓，僑匯建築巔峰之作","intro":"陳期宰洋樓位於金湖鎮山外聚落，由新加坡僑商陳期宰於1930年（民國19年）返鄉興建，翌年完工。他約20歲下南洋，從幫工做起，後經營航運，創辦「金興利」號，以木材廠與橡膠園致富。洋樓完工後他舉家遷入，隔年病逝。日軍占領時期洋樓被作為排部，1949年起成為國軍軍團司令部，之後改為招待所、迎賓館，1991年交還屋主，1998年起閒置。四面迴廊的配置在金門獨一無二，五邊形出龜有26幅石雕，一樓橫楣有「番仔樓」泥塑字樣，被譽為金門僑匯洋樓巔峰之作。目前屋頂崩塌，損壞嚴重。","highlights":["金門唯一四面迴廊配置與五邊形出龜","出龜石柱上花鳥、民間故事等26幅石雕","一樓橫楣上的「番仔樓」泥塑字樣"],"funFact":"洋樓一樓橫楣直接塑上「番仔樓」三個字，等於自己幫自己掛上名牌。","photoSpot":"在洋樓正前方拍五邊形出龜與拱圈","visitMin":15,"openNote":"位於金湖鎮山外聚落，可搭金門縣公車至山外車站一帶。私人住宅，請在外觀參觀，勿擅入；建築損壞嚴重，請勿靠近或攀爬。","dialogue":[{"who":"A","text":"阿拉蕾，山外這棟洋樓，在金門洋樓界可是天花板等級，妳看出它哪裡特別了嗎？"},{"who":"R","text":"它四邊都有走廊耶！好像穿了一件圍裙在身上。"},{"who":"A","text":"對，四面迴廊在金門只有這一棟。1930年新加坡僑商陳期宰回鄉蓋的，他做航運、開木材廠和橡膠園。"},{"who":"R","text":"那他蓋好以後一定住得很開心吧？"},{"who":"A","text":"可惜他搬進來隔年就過世了。後來日軍占領時被當排部，1949年起又當過國軍司令部、招待所和迎賓館。"},{"who":"R","text":"這棟樓換過的身分比我換過的髮型還多！"},{"who":"A","text":"1991年還給屋主後，又當過唱歌的餐廳和藝品店，1998年起就空著沒人用了。"},{"who":"R","text":"好可惜，這麼漂亮的房子，那它現在狀況怎樣？"},{"who":"A","text":"屋頂崩塌，請在外面看。仔細找一樓的橫楣，上面用泥塑寫了三個字，念念看是什麼。"}],"clues":["我曾當過軍團司令部、招待所，還當過唱歌的餐廳","我的四面都有迴廊，出龜石柱上有26幅石雕","我的一樓橫楣寫著番仔樓，主人是新加坡僑商"],"quiz":[{"q":"陳期宰洋樓在金門獨一無二的配置是什麼？","options":["三層塔樓","四面迴廊","雙落大厝","地下室"],"answer":1,"explain":"四面迴廊的配置方式為金門唯一。"},{"q":"洋樓一樓橫楣上的泥塑字樣是什麼？","options":["金興利","陳氏洋樓","光前裕後","番仔樓"],"answer":3,"explain":"一樓橫眉提有「番仔樓」泥塑字樣。"}],"images":[]},{"id":"jincheng-qianshuitoudeyue","name":"前水頭得月樓及黃輝煌洋樓","short":"得月樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.40975,"lng":118.29851,"address":"金門縣金城鎮前水頭45號","announced":"2019-01-15","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20190410000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2019-04-10/0ff68c68-fbab-49de-95a0-13c19c73e903/image003.jpg","year":1931,"yearText":"1931年（民國20年）洋樓落成","era":"japan","themes":["僑鄉洋樓","聚落地景"],"yearUnknown":false,"summary":"防盜銃樓配華麗洋樓的水頭僑鄉代表","intro":"前水頭得月樓及黃輝煌洋樓位於金城鎮金水村水頭聚落。黃輝煌早年隨鄉人赴印尼謀生，經商致富後匯款回鄉，民國20年（1931）建成洋樓，由南安籍名師陳南山等人設計施作，精緻程度為金門洋樓數一數二。民國22年（1933）水頭僑眷遭劫的「黑面宙事件」後，他再請古崗師傅興建高11.26公尺、外牆厚40公分的得月樓，作為全村銃樓，並以三開間「番仔厝」式假樓連接，用來欺敵。日軍占領時期洋樓曾被占為營房，戰後國軍進駐；2005年起由金門國家公園管理處代管修復，2009年開放為展示館。","highlights":["高11.26公尺的得月樓與牆上的銃眼、觀測口","洋樓山頭泥塑時鐘，指針指向12時40分","假樓門額「紫雲衍派」與馬約利卡彩磁"],"funFact":"得月樓沒有固定樓梯，只靠移動式木梯上下，盜匪來襲時，防禦者可以爬上去再把梯子收起來。","photoSpot":"在前埕拍得月樓與洋樓同框","visitMin":40,"openNote":"位於金城鎮金水村水頭聚落，官方資料記載每日8:30至17:00開放，除夕休館。鄰近水頭碼頭，可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，那座細細高高、牆上都是小洞洞的樓，是燈塔嗎？"},{"who":"A","text":"不是燈塔，是銃樓！它叫得月樓，高11公尺多，那些小洞是銃眼和觀測口。"},{"who":"R","text":"住在村子裡，為什麼需要射擊孔啊？"},{"who":"A","text":"民國22年水頭發生僑眷遭劫的「黑面宙事件」，大家很緊張，黃輝煌就蓋了這座樓保護全村。"},{"who":"R","text":"那旁邊那棟漂亮的洋樓也是他的嗎？"},{"who":"A","text":"對，民國20年落成，請名師陳南山設計。中間還有一棟假樓，故意做得很華麗，讓盜匪誤以為那是主屋。"},{"who":"R","text":"假樓騙盜匪，這根本是建築版的空城計嘛！"},{"who":"A","text":"而且銃樓只用移動式木梯，壞人來了就把梯子收起來，比我躲家事的功夫還厲害。"},{"who":"R","text":"我來抬頭找洋樓山頭上的時鐘，看看指針停在幾點幾分！"}],"clues":["我的誕生起因於一樁震驚全金門的劫案","我和一棟華麗洋樓之間，隔著一棟專門騙人的假樓","水頭聚落裡高11.26公尺的四層銃樓"],"quiz":[{"q":"得月樓興建的主要目的是什麼？","options":["收藏南洋書畫","防禦盜匪的銃樓","觀測天象星辰","供奉家族神明"],"answer":1,"explain":"黑面宙事件後興建，作為全村防禦的銃樓。"},{"q":"連接得月樓與洋樓的假樓，主要功能是？","options":["欺騙盜匪","儲存糧食","祭祀祖先","教授私塾"],"answer":0,"explain":"假樓裝飾華麗，讓盜匪誤判為宅第主體。"}],"images":[{"file":"前水頭黃輝煌洋樓及得月樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/%E5%89%8D%E6%B0%B4%E9%A0%AD%E9%BB%83%E8%BC%9D%E7%85%8C%E6%B4%8B%E6%A8%93%E5%8F%8A%E5%BE%97%E6%9C%88%E6%A8%93.jpg/960px-%E5%89%8D%E6%B0%B4%E9%A0%AD%E9%BB%83%E8%BC%9D%E7%85%8C%E6%B4%8B%E6%A8%93%E5%8F%8A%E5%BE%97%E6%9C%88%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%89%8D%E6%B0%B4%E9%A0%AD%E9%BB%83%E8%BC%9D%E7%85%8C%E6%B4%8B%E6%A8%93%E5%8F%8A%E5%BE%97%E6%9C%88%E6%A8%93.jpg","artist":"張雅倫","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-qianshuitoudeyue-0.webp","small":"img/jincheng-qianshuitoudeyue-0-s.webp"}]},{"id":"jinsha-wangjinchengyang","name":"王金城洋樓","short":"王金城洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.48148,"lng":118.39472,"address":"金門縣金沙鎮浦山里后宅2號","announced":"2015-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150211000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-04-23/28b172ad-3487-4438-8d7c-5fa105dea28d/王金城洋樓_代表圖像.jpg","year":1932,"yearText":"1932年（民國21年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"鼓浪嶼師傅設計、雙獅環球山頭的洋樓","intro":"王金城洋樓位於金沙鎮浦山里后宅聚落。王仁都字金城，早年隨父親到印尼茂物，從麵包店起家，後獲當地政府特許經營賭場而致富。民國17年（1928）起他以僑匯委託弟弟王金鎖主持建造，聘廈門鼓浪嶼師傅設計，石匠在現場鑿雕石柱與窗框，耗資三萬多大洋，民國21年（1932）竣工。洋樓為出龜式兩層樓，紅瓦歇山頂，山頭有「雙獅環球」與「廿一年」字樣，柱頭泥塑有槍兵、管家與天使，並設鑄鐵窗、防盜門與銃眼防範盜賊。民國38年（1949）後曾作駐軍團部，留有戰地標語，民國112年（2023）9月修復完成。","highlights":["山頭「雙獅環球」泥塑與「廿一年」字樣","一樓柱頭的槍兵、管家與天使泥塑","防盜用的鑄鐵窗與銃眼"],"funFact":"一樓橫樑的泥塑風景裡，有騎腳踏車的人、拄著拐杖過橋的人，還有騎馬奔馳的圖案。","photoSpot":"在圍牆外拍出龜立面與雙獅環球山頭","visitMin":30,"openNote":"位於金沙鎮浦山里后宅聚落，民國112年（2023）修復完成後由所有權人活化經營，官方資料記載須提前一個月預約參觀。未預約時請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看山頭中間，兩隻獅子抱著一顆球，這叫「雙獅環球」。"},{"who":"R","text":"獅子在打籃球嗎？Allan，牠們的球技好像不錯喔。"},{"who":"A","text":"哈哈，旁邊還寫著「中華民國」「廿一年」，就是民國21年，這棟洋樓完工的年份。"},{"who":"R","text":"屋主到底是誰？可以蓋得這麼氣派！"},{"who":"A","text":"屋主王金城早年到印尼茂物，從麵包店做起，發達後委託弟弟王金鎖回鄉蓋房子。"},{"who":"R","text":"從麵包店到洋樓，這是最成功的發麵故事吧！"},{"who":"A","text":"很會接梗！他請鼓浪嶼師傅設計，石匠在現場鑿石柱和窗框，花了三萬多大洋，蓋了四年多。"},{"who":"R","text":"那這些窗戶怎麼看起來那麼厚重？"},{"who":"A","text":"那時金門常有盜賊，所以有鑄鐵窗、防盜門和銃眼。到現場找找一樓柱頭上的槍兵泥塑吧！"}],"clues":["我的主人在印尼茂物從麵包店起家","我的山頭有雙獅環球，還寫著廿一年","后宅聚落裡由鼓浪嶼師傅設計的出龜洋樓"],"quiz":[{"q":"這棟洋樓聘請哪裡的師傅設計？","options":["泉州晉江","廈門鼓浪嶼","福州馬尾","汕頭潮州"],"answer":1,"explain":"王金城聘請廈門鼓浪嶼師傅設計洋樓。"},{"q":"洋樓山頭中央的主題泥塑是什麼？","options":["雙龍搶珠","鳳凰牡丹","雙獅環球","老鷹展翅"],"answer":2,"explain":"山頭中央兩旁有獅獸，形成雙獅環球圖騰。"}],"images":[{"file":"中華民國的山牆.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/%E4%B8%AD%E8%8F%AF%E6%B0%91%E5%9C%8B%E7%9A%84%E5%B1%B1%E7%89%86.jpg/960px-%E4%B8%AD%E8%8F%AF%E6%B0%91%E5%9C%8B%E7%9A%84%E5%B1%B1%E7%89%86.jpg","page":"https://commons.wikimedia.org/wiki/File:%E4%B8%AD%E8%8F%AF%E6%B0%91%E5%9C%8B%E7%9A%84%E5%B1%B1%E7%89%86.jpg","artist":"鐘堡","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-wangjinchengyang-0.webp","small":"img/jinsha-wangjinchengyang-0-s.webp"}]},{"id":"jincheng-dongyunyaoyanglou","name":"董允耀洋樓","short":"董允耀洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.39978,"lng":118.31371,"address":"金門縣金城鎮大古崗84號","announced":"2015-02-11","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20150211000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-09-15/59848657-fdf3-4ff5-a46f-98d2dbbc0338/董允耀洋樓_代表圖像.jpg","year":1933,"yearText":"1933年（民國22年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"山頭泥塑拼出主人姓名的古崗洋樓","intro":"董允耀洋樓位於金城鎮大古崗。董允耀（1880–1945）幼時家貧，曾在家鄉賣豆腐，十餘歲隨鄉人赴印尼謀生，從幫工做起，後與鄭古悅合創「同成棧」販售海產乾貨，再經營胡椒買賣與船運致富。民國22年（1933）他返鄉聘古崗匠師董天乞興建洋樓，工期七個月，木料、洋灰自廈門採購。山頭泥塑有他姓名的金門話羅馬拼音，配上大象、椰子樹等南洋紋樣，門額「玉筍流芳」「豢龍」由後浦文人許維舟題寫。1937年日軍占領金門後他無法返回南洋，在洋樓度過晚年。2020年產權人捐給縣府，2025年修復完成。","highlights":["山頭泥塑的主人姓名拼音與大象、椰子樹","門樓「玉筍流芳」與二樓「豢龍」堂號","一樓大門兩側留存的海龍部隊字樣"],"funFact":"洋樓曾進駐陸軍成功隊海龍部隊，正立面和二樓至今仍看得到當年海龍字樣的油漆痕跡。","photoSpot":"在庭院前拍洋樓山頭泥塑","visitMin":20,"openNote":"位於金城鎮大古崗，已捐贈金門縣政府並於2025年修復完成，曾配合藝術展覽開放參觀；開放時間請以主管機關公告為準，未開放時請在外觀參觀。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看洋樓山頭，那一排拼音字母，你念得出來嗎？"},{"who":"R","text":"咦，這是外國名字嗎？蓋洋樓還要在上面簽名喔？"},{"who":"A","text":"猜對一半！這是屋主董允耀名字的金門話羅馬拼音，旁邊還有大象和椰子樹，滿滿南洋風。"},{"who":"R","text":"所以他是去南洋打拚，發了大財才回來的嗎？"},{"who":"A","text":"對，他小時候在家鄉賣豆腐，十幾歲去印尼從幫工做起，後來賣海產乾貨、胡椒，還做船運，才存夠錢回來蓋樓。"},{"who":"R","text":"從豆腐小販變成船運老闆，好勵志！"},{"who":"A","text":"可惜民國26年日軍占領金門，他回不了南洋，就在這棟洋樓住到過世。"},{"who":"R","text":"好可惜喔。那現在洋樓還有人住嗎？"},{"who":"A","text":"產權人在2020年把它捐給縣政府，2025年修復完成。請你找找一樓大門兩側，國軍海龍部隊留下的字樣！"}],"clues":["我的山頭泥塑拼出了主人名字的羅馬拼音","我的主人因日軍占領金門回不了南洋，在我這裡度過晚年","大古崗的僑鄉洋樓，門樓題著「玉筍流芳」"],"quiz":[{"q":"山頭泥塑上除了主人姓名拼音，還有什麼紋樣？","options":["龍鳳與牡丹","大象與椰子樹","天使與時鐘","獅子與葡萄"],"answer":1,"explain":"姓名拼音下方有椰子樹與兩側大象泥塑。"},{"q":"董允耀在印尼與人合創的商號是？","options":["承順福","復和行","同成棧","和記商店"],"answer":2,"explain":"他與鄭古悅共同創設同成棧，販售海鮮乾貨。"}],"images":[]},{"id":"jincheng-chenshiyinyanglou","name":"陳詩吟洋樓","short":"陳詩吟洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["宅第"],"lat":24.431525,"lng":118.317734,"address":"金門縣金城鎮珠浦東路44 號","announced":"2006-06-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060613000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-30/35422c60-b0e2-4102-831c-1c9771cca729/(1)封面.jpg","year":1933,"yearText":"1933年（民國22年）落成","era":"japan","themes":["僑鄉洋樓","名人故居"],"yearUnknown":false,"summary":"山頭立著聖母像與印度人偶的華麗僑匯洋樓","intro":"陳詩吟洋樓位於金城鎮珠浦東路，緊鄰奎閣。陳詩吟（1873–1933）是金門高坑人，原本教私塾，1903年赴南洋，在新加坡經營土產貿易，第一次世界大戰期間致富。1932年他與夫人薛賢珍回鄉，在後浦塗山頭購地，聘大陸工匠興建洋樓，工料花費銀三萬元，但他在1933年過世，洋樓由夫人主持於同年落成。1937年日軍登陸金門，家族避往鼓浪嶼與新加坡，此後未再返鄉；洋樓在日軍占領時期被占作官舍，1949年後由國軍使用。後來長期閒置、屋頂塌陷，2016年起以鋼棚架保護。它是出龜式洋樓，山頭與檐下泥塑極為豐富。","highlights":["山頭鏤空處的聖母像泥塑與「1933」落款","頭頂壽桃的印度人偶與南洋苦力造型托架","側牆花草、燭臺、火焰形等各式窗楣"],"funFact":"檐下托架做成肩扛、倒立腳扛、手扛等南洋苦力造型，像在合力撐起屋簷。","photoSpot":"奎閣旁仰拍山頭的雙龍與人偶泥塑","visitMin":15,"openNote":"位於金城鎮珠浦東路，奎閣旁。屋頂坍塌，目前閒置並以鋼棚架保護，僅能外觀參觀，請勿擅入。從金城車站步行可達，可與奎閣一起參觀。","dialogue":[{"who":"A","text":"站在奎閣旁邊抬頭看，這棟罩著鋼棚架的，就是1933年落成的陳詩吟洋樓。"},{"who":"R","text":"怎麼被鐵架包起來了？它是在戴安全帽嗎？"},{"who":"A","text":"差不多啦。它閒置多年，屋頂塌陷，2016年起用鋼棚架保護，免得山頭泥塑被風雨打壞。"},{"who":"R","text":"那陳詩吟是誰？聽名字好像是個詩人。"},{"who":"A","text":"他原本是私塾老師，1903年去新加坡做土產貿易，第一次世界大戰期間發了財，回鄉花銀三萬元蓋樓。"},{"who":"R","text":"三萬元！那他住得一定很開心吧？"},{"who":"A","text":"可惜洋樓還沒完工他就過世了，由夫人薛賢珍主持完工。1937年日軍登陸金門，家族離開後就沒再回來。"},{"who":"R","text":"好令人感傷。那洋樓上還留著什麼特別的裝飾？"},{"who":"A","text":"山頭有聖母像，兩側是頭頂壽桃的印度人偶，檐下還有倒立撐屋簷的苦力。找找看，哪一個托架是用腳扛的？"}],"clues":["我的主人原是私塾老師，在新加坡做土產貿易致富","我還沒完工，主人就過世了，由夫人主持落成","我在奎閣旁，山頭有聖母像和頭頂壽桃的人偶"],"quiz":[{"q":"陳詩吟洋樓在哪一年落成？","options":["1923年","1928年","1933年","1937年"],"answer":2,"explain":"洋樓於1933年在夫人薛賢珍主持下落成。"},{"q":"陳詩吟在哪裡建立事業、經商致富？","options":["菲律賓","新加坡","日本","越南"],"answer":1,"explain":"他1903年赴南洋，在新加坡經營土產貿易致富。"}],"images":[{"file":"100024Golden Gate National Park+ID2411215+007+DSC00085A (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/96/100024Golden_Gate_National_Park%2BID2411215%2B007%2BDSC00085A_%28cropped%29.jpg/960px-100024Golden_Gate_National_Park%2BID2411215%2B007%2BDSC00085A_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:100024Golden_Gate_National_Park%2BID2411215%2B007%2BDSC00085A_(cropped).jpg","artist":"林高志","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-chenshiyinyanglou-0.webp","small":"img/jincheng-chenshiyinyanglou-0-s.webp"}]},{"id":"jinhu-anbianlvchaoxuan","name":"庵邊呂朝選宅","short":"庵邊呂朝選宅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.42557,"lng":118.442979,"address":"金門縣金湖鎮庵邊6號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-15/0fa1730f-60c7-42cb-ae10-2d81aa2d930b/庵邊呂朝選宅-代表圖像.jpg","year":1933,"yearText":"1933年（民國22年）","era":"japan","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"新加坡僑商為母親蓋的花磚大厝","intro":"庵邊呂朝選宅位於金湖鎮庵邊聚落，由旅居新加坡經商有成的呂朝選於1933年（民國22年）返鄉興建，完工後他回到新加坡，宅邸留給母親居住，此後未再返鄉，後代多定居新加坡。建築為雙落大厝帶右護龍，屬僑匯興建的閩南式大厝，卻在水車堵、壁堵、墀頭與屋脊內貼滿日本製的馬約利卡彩瓷花磚，融合不同文化的裝飾風格。大門石匾題「奎璧聯輝」，前廳設有防盜用的輪錢門，向寮樑托雕成兔子，寓意多子多孫；壽堂後設半樓通往兩側房，是「走馬樓」形式。古厝曾遭國軍占用，後長期無人使用，目前屋頂與櫸頭多處崩塌，受損相當嚴重。","highlights":["水車堵與墀頭上的日本製馬約利卡彩瓷花磚","大門上方「奎璧聯輝」石匾","向寮雕成兔子造型的樑托，寓意多子多孫"],"funFact":"向寮的樑托雕成兔子，因為兔子很會生，象徵子孫滿堂，是匠師藏在屋裡的祝福。","photoSpot":"在屋前拍正面花磚水車堵與石匾","visitMin":15,"openNote":"位於金湖鎮庵邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築嚴重損壞，請勿靠近或攀爬。","dialogue":[{"who":"R","text":"Allan，這間古厝牆上貼著好多彩色小磁磚，閃閃發亮的！"},{"who":"A","text":"那叫馬約利卡彩瓷，是日本製的花磚。1933年呂朝選在新加坡做生意有成，回到庵邊蓋了這座大厝。"},{"who":"R","text":"蓋好之後他自己有住進來享福嗎？"},{"who":"A","text":"沒有喔，他蓋好就回新加坡，把房子留給母親住，之後再也沒回來，算是用一棟房子表達孝心。"},{"who":"R","text":"好感人！那屋子裡還藏什麼小祕密？"},{"who":"A","text":"向寮的樑托雕成兔子，祝福多子多孫，前廳還有防小偷的輪錢門，比我家鐵窗還有學問。"},{"who":"R","text":"兔子守門，小偷應該會被萌到不敢進來吧！"},{"who":"A","text":"可惜現在屋頂和櫸頭都崩塌得很嚴重，請在外面看就好。找找大門上的石匾，念念看「奎璧聯輝」四個字。"}],"clues":["我身上貼滿日本製的彩瓷花磚","我的向寮樑托雕成兔子，前廳有輪錢門","我是新加坡僑商1933年在庵邊為母親蓋的大厝"],"quiz":[{"q":"呂朝選宅的向寮樑托雕成什麼動物？","options":["獅子","兔子","麒麟","蝙蝠"],"answer":1,"explain":"樑托雕成兔形，寓意多子多孫。"},{"q":"呂朝選宅大門上的石匾題什麼字？","options":["奎璧聯輝","文魁","副魁","祖德流芳"],"answer":0,"explain":"大門入口上方石匾字樣為「奎璧聯輝」。"}],"images":[]},{"id":"jinsha-qingyuzhangshi","name":"青嶼張氏兄弟洋樓","short":"張氏兄弟洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.519822,"lng":118.420676,"address":"金門縣金沙鎮青嶼23號、24號","announced":"2017-01-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170126000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-07-14/89ff856c-5e91-4b38-9cb9-dc6b50e9e9f1/青嶼張氏兄弟洋樓_壓縮.jpg","year":1934,"yearText":"1934年（民國23年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"菲律賓四兄弟合建、防盜機關滿滿的洋樓","intro":"青嶼張氏兄弟洋樓位於金沙鎮青嶼聚落，由張自然、張自吉、張自來、張自忠四兄弟在菲律賓經營雜貨有成後合資興建。民國19年（1930）開始規劃，由父親主導，民國23年（1934）完工，因四兄弟都在菲律賓，宅邸以長房媳婦為戶長。建築為五腳基洋樓加右護龍與前迴向，紅瓦歇山屋頂，正面圓柱以四分之一圓特製紅磚交丁疊砌，山頭有泥塑獅踩球，並設銃眼、地板窺孔與樓梯蓋板等防盜設施。民國26年（1937）日軍占領金門，僑匯一度斷絕；民國38年（1949）後成為營部，八二三砲戰時閣樓嚴重受損，民國114年（2025）9月修復竣工。","highlights":["四分之一圓紅磚交丁疊砌的圓形磚柱","一樓火型、二樓水型的不同窗楣","山頭獅踩球泥塑與「忠勤世第」匾額"],"funFact":"磚柱頭和上層樓板黏著碎玻璃，原本用來防盜，後來也成了柱頭裝飾的一部分。","photoSpot":"在洋樓前方拍圓形磚柱與山頭","visitMin":15,"openNote":"位於金沙鎮青嶼聚落，民國114年（2025）修復竣工，官方未公布開放時間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。鄰近青嶼前甲張氏宗祠，開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的柱子是圓的耶，紅磚也能砌成圓柱嗎？"},{"who":"A","text":"可以，而且很講究。每一層用四塊四分之一圓的特製紅磚拼成一圈，再交錯往上疊。"},{"who":"R","text":"聽起來就像一層一層在疊年輪蛋糕！"},{"who":"A","text":"好比喻！這是張家四兄弟在菲律賓做雜貨生意，一起出錢蓋的，民國23年完工。"},{"who":"R","text":"四兄弟合蓋一棟，裡面一定很寬敞吧？"},{"who":"A","text":"一二樓都是六房二廳，而且防盜機關很多，有銃眼、地板窺孔和樓梯蓋板。"},{"who":"R","text":"簡直是密室逃脫屋！那後來它過得平靜嗎？"},{"who":"A","text":"民國38年後這裡成了營部，八二三砲戰時閣樓嚴重受損，直到民國114年才修復完成。"},{"who":"R","text":"那我要到現場比比看，一樓和二樓的窗楣形狀有什麼不一樣！"}],"clues":["我是四兄弟在菲律賓打拚後合蓋的家","我的圓柱用四分之一圓紅磚拼成，還藏著銃眼與窺孔","青嶼聚落民國23年完工的歇山頂五腳基洋樓"],"quiz":[{"q":"張家四兄弟在哪裡經商有成？","options":["印尼","菲律賓","新加坡","越南"],"answer":1,"explain":"四兄弟在菲律賓經營雜貨，共同出資建樓。"},{"q":"洋樓一樓的窗楣是什麼造型？","options":["曲形水型","圓拱形","三角形","尖型火型"],"answer":3,"explain":"一樓為尖型火型窗楣，二樓為曲形水型。"}],"images":[]},{"id":"jinhu-huqianchenzong","name":"湖前陳宗炯洋樓","short":"陳宗炯洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金湖鎮","types":["宅第"],"lat":24.436591,"lng":118.413064,"address":"金門縣金湖鎮湖前24號","announced":"2015-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20151029000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-03-27/6c8e1b67-25f7-44da-85ab-1a1819ce5fe2/湖前陳宗炯洋樓.jpg","year":1935,"yearText":"1935年（民國24年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"緬甸僑商所建，樑上嵌著民國24年的洋樓","intro":"湖前陳宗炯洋樓位於金湖鎮湖前聚落。陳宗炯生於1904年，旅居緬甸四十多年，創辦「宗記商行」經營土產，1935年（民國24年）返鄉興建此樓，1941年又在左側加蓋簡易洋樓作診所，免費看診並贈藥給貧困病患。他後來定居臺北，曾捐建湖前學校校舍，並任臺北金門同鄉會首屆理事長。洋樓為五腳基洋樓帶二櫸頭起疊樓，外廊採簡易鋼筋混凝土，屬較晚期的洋樓，平面卻偏漢式。二樓樑上以馬賽克拼出「中華民國二十四年」，山頭有花草與獸類浮雕，窗楣有三種樣式，樓板還設有防盜窗。","highlights":["二樓樑上馬賽克拼貼的「中華民國二十四年」字樣","正面山頭的花草與獸類浮雕","三種不同樣式的窗楣與二樓外廊花形窗"],"funFact":"陳宗炯在洋樓旁加蓋簡易洋樓當診所，免費替鄉親看病，貧困的人還能免費拿藥。","photoSpot":"在院牆外拍二樓馬賽克年代字樣","visitMin":15,"openNote":"位於金湖鎮湖前聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。","dialogue":[{"who":"R","text":"Allan，你看二樓樑上有一排小磁磚拼的字，寫著「中華民國二十四年」！"},{"who":"A","text":"眼力真好！那就是這棟樓的生日，民國24年，也就是1935年，屋主把年代直接拼在牆上。"},{"who":"R","text":"好聰明，這樣就不會忘記房子幾歲了。屋主是誰呢？"},{"who":"A","text":"陳宗炯，在緬甸做土產生意四十多年，開了宗記商行，賺了錢不忘家鄉。"},{"who":"R","text":"他除了蓋洋樓，還做了什麼好事？"},{"who":"A","text":"1941年他在旁邊加蓋一間診所，免費替鄉親看病，窮苦的人還送藥，比我請客吃燒餅還大方多了。"},{"who":"R","text":"好暖心的屋主！這棟洋樓跟別的洋樓有什麼不一樣？"},{"who":"A","text":"外觀很洋派，平面卻偏漢式，樓板還開了防盜窗。請你在院牆外數數看，窗楣一共有幾種花樣。"}],"clues":["我的屋主在緬甸開商行，還開過免費診所","我的二樓樑上用馬賽克拼出建造年代","我是湖前1935年完工的五腳基洋樓"],"quiz":[{"q":"陳宗炯在哪個國家經商？","options":["新加坡","印尼","菲律賓","緬甸"],"answer":3,"explain":"陳宗炯旅居緬甸四十多年，創辦宗記商行。"},{"q":"洋樓二樓樑上的馬賽克拼貼寫了什麼？","options":["中華民國二十四年","福祿壽全","宗記商行","湖前陳氏"],"answer":0,"explain":"二樓正立面樑上貼有「中華民國二十四年」字樣。"}],"images":[]},{"id":"jinsha-ruiyouxuexiao","name":"睿友學校","short":"睿友學校","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金沙鎮","types":["宅第"],"lat":24.485656,"lng":118.441122,"address":"金門縣金沙鎮碧山1號","announced":"2006-06-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060613000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-30/21bde33a-ef7e-4454-a2c1-6dc447a1cb11/01封面.jpg","year":1936,"yearText":"1936年（民國25年）","era":"japan","themes":["教育書院","僑鄉洋樓"],"yearUnknown":false,"summary":"南洋僑商捐建、山頭站著印度兵的洋樓學校","intro":"睿友學校位於金沙鎮碧山聚落，由南洋僑商陳睿友捐建。他幼年隨舅父到星洲學習經商，後開設「金和美」商號經營木材致富。民國23年（1934）提撥銀元二萬元，委託同宗華僑陳德幸返鄉籌建，第一期主體於民國25年（1936）竣工，招收碧山及鄰村兒童並免學雜費，還獲廈門集美學校協助師資。第二期工程因抗戰爆發、金門遭日軍占領而停擺。古寧頭戰役時校舍改作營房，後借給碧山小學與村公所，荒廢十餘年，民國101年（2012）修復，民國107年（2018）起作文學館。山頭有印度兵、旭日與冠軍獎盃泥塑。","highlights":["山頭三扇窗兩側的印度兵泥塑","黃橘色嵌磁拼出的「睿友學校」門匾","望柱與女兒牆矮柱上的冠軍獎盃造型"],"funFact":"山頭望柱和女兒牆矮柱上都立著冠軍獎盃泥塑，彷彿整棟樓都在幫學生加油。","photoSpot":"在前埕正面拍山頭泥塑與門匾","visitMin":30,"openNote":"位於金沙鎮碧山聚落，現作文學館展示使用，官方資料記載上午9點至下午5點開放，每週四休館。開車或騎機車前往較方便。可順道散步碧山聚落。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的屋頂上，怎麼站著兩個穿制服的人？"},{"who":"A","text":"那是印度兵的泥塑。睿友學校的山頭很熱鬧，還有國旗、黨旗、旭日和冠軍獎盃。"},{"who":"R","text":"學校屋頂放獎盃，是要每天提醒學生拿第一名嗎？"},{"who":"A","text":"搞不好喔！這所學校是南洋僑商陳睿友捐建的，民國25年完工，附近村子的孩子都免學雜費。"},{"who":"R","text":"免學雜費？我好想穿越回去報名上學！"},{"who":"A","text":"那時還請廈門集美學校推薦校長、支援師資，辦學非常認真。"},{"who":"R","text":"那後來呢？為什麼現在變成文學館？"},{"who":"A","text":"抗戰時第二期工程停擺，古寧頭戰役時校舍當營房，後來借給小學和村公所，荒廢多年才修好。"},{"who":"R","text":"那我要去數數看，山頭和欄杆上到底站了幾座冠軍獎盃！"}],"clues":["我的山頭站著印度兵，還有冠軍獎盃","我曾讓附近村子的孩子免費讀書，現在是文學館","碧山聚落裡民國25年完工、由南洋僑商捐建的洋樓學校"],"quiz":[{"q":"睿友學校曾獲得哪所學校協助師資與經費？","options":["廈門大學","鼓浪嶼英華書院","泉州培元中學","集美學校"],"answer":3,"explain":"辦學曾獲廈門集美學校補助經費並支援師資。"},{"q":"睿友學校今天作為什麼用途？","options":["文學館","村公所","國小教室","營區"],"answer":0,"explain":"民國107年起再利用為文學館展示使用。"}],"images":[]},{"id":"lieyu-qingqilantingbie","name":"青岐蘭亭別墅","short":"蘭亭別墅","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["宅第"],"lat":24.41535,"lng":118.228078,"address":"金門縣烈嶼鄉青岐122號","announced":"2017-01-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170104000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-10/dfdcd952-8ffc-41dd-a8cc-0fb98075deba/青岐蘭亭別墅.png","year":1936,"yearText":"約1936年（民國25年）","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"古厝護龍加蓋洋樓，泥塑天使與印度人像彩磁","intro":"青岐蘭亭別墅位於烈嶼鄉青岐聚落，由旅居新加坡經商有成的何寶返鄉興建，約於民國25年（1936）完成，正值金門僑匯洋樓興建高峰。建築以一落四櫸頭古厝為主體，再於左護龍增建兩層五腳基洋樓，也就是「蘭亭別墅」，有獨立的門樓；這種護龍起洋樓的形式規模龐大，在金門少見。山牆、窗楣與簷牆裝飾獅子、老鷹、天使、寶燈、蝙蝠、桃子與玫瑰等灰泥塑，還有印度人像彩磁。日軍占領金門期間曾有日軍進駐，戰後憲兵部隊也曾使用，並曾作為上岐國小教師宿舍。目前以鋼棚架防護，北向牆面仍留有大量彈著痕跡。","highlights":["南向山牆雙獅與老鷹、北向天使與老鷹泥塑","水平、弧形、火焰形等多樣窗楣","北向牆面留下的大量彈著痕跡"],"funFact":"洋樓裝飾裡藏著印度人像彩磁，是南洋僑匯把異國元素帶回金門的有趣例子。","photoSpot":"從北側拍天使與老鷹山牆泥塑","visitMin":15,"openNote":"位於烈嶼鄉青岐聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；目前搭有鋼棚架防護。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，這棟房子好奇怪，左邊是古厝，旁邊卻冒出一棟兩層洋樓！"},{"who":"A","text":"你抓到重點了！這是青岐的蘭亭別墅，何寶在新加坡經商有成，回來在古厝左護龍加蓋洋樓。"},{"who":"R","text":"等於在老家旁邊加蓋一間豪華套房？"},{"who":"A","text":"可以這樣想，這種護龍起洋樓的做法規模很大，在金門很少見，大約在民國25年完成。"},{"who":"R","text":"牆上的小雕像好可愛，有獅子、老鷹，還有長翅膀的小天使！"},{"who":"A","text":"還有寶燈、蝙蝠、桃子、玫瑰，甚至有印度人像的彩磁，南洋風情全帶回來了。"},{"who":"R","text":"咦，可是北邊的牆面怎麼坑坑洞洞的？"},{"who":"A","text":"那是戰爭留下的彈痕。這裡經歷過日軍占領和後來的砲戰，牆面默默記下了那段艱難的日子。"},{"who":"A","text":"待會繞到北側，在天使和老鷹泥塑的下方，靜靜看看這些歷史留下的痕跡。"}],"clues":["我是在古厝左護龍加蓋的兩層洋樓","我的山牆上有雙獅、老鷹和天使泥塑，北牆滿是彈痕","我是小金門青岐聚落一位新加坡華僑蓋的別墅"],"quiz":[{"q":"蘭亭別墅蓋在古厝的哪個位置？","options":["正身後方","右護龍","前埕","左護龍"],"answer":3,"explain":"何寶在一落四櫸頭古厝的左護龍增建兩層洋樓。"},{"q":"下列哪一種裝飾出現在蘭亭別墅上？","options":["印度人像彩磁","日式鬼瓦","彩繪玻璃窗","銅鑄獅頭"],"answer":0,"explain":"洋樓有獅子、老鷹、天使泥塑，還有印度人像彩磁。"}],"images":[]},{"id":"lieyu-shanglinlinxinping","name":"上林林信屏洋樓","short":"林信屏洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["宅第"],"lat":24.427002,"lng":118.230154,"address":"金門縣烈嶼鄉上林35號","announced":"2017-01-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170126000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-10/9ae35350-e4e5-450b-8d66-60f3697d993a/01(封面).jpg","year":1937,"yearText":"1937年（民國26年）落成","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"罌粟花彩磁與回字型陽臺的新加坡僑商洋樓","intro":"上林林信屏洋樓位於烈嶼鄉上林聚落。林信屏生於1887年，年輕時遠赴新加坡謀生，從苦力做起，後來創立「協發」商號，經營船舶零件與海運貿易。民國25年（1936）他以僑匯五千銀圓返鄉建屋，由堂侄負責管理監造，延聘大陸名師設計，建材多自福建沿海運來，民國26年（1937）竣工。建築為五腳基洋樓帶前落與二櫸頭，正立面以馬約利卡磁磚裝飾，其中五片彩磁拼成的罌粟花圖飾，以及二樓弧形樓梯通往屋頂形成的回字型陽臺，都是金門孤例。落成不久遇上日軍占領，曾被徵為鹽場宿舍；戰後曾作軍方使用，也當過上林國民學校與村辦公處。","highlights":["五片彩磁拼成的罌粟花圖飾，金門孤例","二樓山頭以馬賽克拼出的堂號「西河衍派」","山頭上雙獅、老鷹、天使等精緻泥塑"],"funFact":"這棟洋樓從看風水、僱工、備料到擇日都有完整紀錄保存，是研究金門建築史的珍貴史料。","photoSpot":"正面仰拍二樓山頭與「西河衍派」字樣","visitMin":15,"openNote":"位於烈嶼鄉上林聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；目前作為文史工作室與住所使用。可經金門大橋開車或騎車前往。","dialogue":[{"who":"A","text":"阿拉蕾，今天到小金門上林，這棟洋樓的主人林信屏，可是從苦力一路拚到老闆的。"},{"who":"R","text":"從苦力到老闆？他是在哪裡打拚的？"},{"who":"A","text":"新加坡！他創立「協發」商號，賣船舶零件、做海運，民國25年匯了五千銀圓回鄉蓋房子。"},{"who":"R","text":"五千銀圓，聽起來可以買好多好多碗蚵仔麵線！"},{"who":"A","text":"你的換算單位真的很金門。洋樓在民國26年完工，正面貼滿漂亮的馬約利卡彩色磁磚。"},{"who":"R","text":"哇，上面那朵花好特別，是什麼花呀？"},{"who":"A","text":"是五片彩磁拼成的罌粟花，在金門找不到第二例。二樓還有弧形樓梯通上屋頂，繞成回字型陽臺。"},{"who":"R","text":"這麼漂亮的房子，主人一定住得很開心吧？"},{"who":"A","text":"可惜落成不久就遇上日軍占領，後來還當過學校和村辦公處。在門外抬頭，找找山頭上的天使和老鷹吧！"}],"clues":["我落成後當過鹽場宿舍、學校和村辦公處","我的正面有五片彩磁拼成的罌粟花，金門僅此一例","我是小金門上林聚落一位新加坡僑商蓋的洋樓"],"quiz":[{"q":"林信屏在新加坡創立的商號叫什麼？","options":["協發","金聯發","明發號","金合發"],"answer":0,"explain":"林信屏創立「協發」，經營船舶零件與海運貿易。"},{"q":"洋樓正面五片彩磁拼成的是哪一種花？","options":["牡丹","荷花","梅花","罌粟花"],"answer":3,"explain":"五片彩磁拼成的罌粟花圖飾是金門孤例。"}],"images":[]},{"id":"lieyu-luocuoluoshixiong","name":"羅厝羅氏兄弟洋樓","short":"羅氏兄弟洋樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"烈嶼鄉","types":["宅第"],"lat":24.42578,"lng":118.25984,"address":"金門縣烈嶼鄉羅厝53號","announced":"2017-01-04","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20170104000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-10/d278f8a2-69d7-4564-835f-065252332821/2.羅厝羅氏兄弟洋樓-代表圖像.jpg","year":1946,"yearText":"1946–1948年（民國35–37年）興建","era":"postwar","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"三兄弟同心興建的六柱五開間紅磚拱廊洋樓","intro":"羅厝羅氏兄弟洋樓位於烈嶼鄉羅厝聚落北側，由羅金望、羅金頂、羅金尋三兄弟興建。三兄弟於民國26年（1937）為避戰亂前往新加坡，以船業致富，民國35年至37年間（1946–1948）返鄉興建洋樓供家族長輩居住，並自行前往廈門購料。洋樓為二層五腳基形式，立面以煙炙磚柱為特徵，六柱五開間，一樓疊澀柱頭，二樓以拱圈相連，配綠釉花瓶欄杆；構造以傳統硬山擱檁為主，再以鋼筋混凝土梁輔助支承樓板與拱圈，中西合璧，是金門鋼筋混凝土構造發展的見證。羅金頂、羅金尋後來倡議成立旅新羅厝人的電船同業公會，也出資重建家鄉的羅氏家廟。","highlights":["六柱五開間的煙炙磚柱與二樓連續拱圈","二樓外廊的綠釉花瓶欄杆","門窗上的彩繪聯對，如「荊樹有花兄弟樂」"],"funFact":"二樓正廳樓板開了一扇「地窗」，方便和一樓溝通，還兼具防盜功能。","photoSpot":"正面拍六柱五開間拱廊全景","visitMin":15,"openNote":"位於烈嶼鄉羅厝聚落北側，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，這棟紅磚洋樓好整齊，一排柱子像在列隊歡迎我們耶！"},{"who":"A","text":"觀察力不錯！這是羅厝的羅氏兄弟洋樓，六根煙炙磚柱分成五開間，二樓用拱圈連起來。"},{"who":"R","text":"兄弟洋樓？是幾個兄弟一起蓋的？"},{"who":"A","text":"三個！羅金望、羅金頂、羅金尋，民國26年為了避戰亂去新加坡，靠船業打拚出一片天。"},{"who":"R","text":"三兄弟一起創業不吵架，真不容易，我跟Allan搶一個燒餅都會吵。"},{"who":"A","text":"那是因為你都挑大的！他們在民國35年到37年間回鄉蓋這棟樓，給家裡長輩住。"},{"who":"R","text":"好孝順！那它在技術上有什麼特別？"},{"who":"A","text":"傳統的硬山擱檁，再加鋼筋混凝土梁撐樓板和拱圈，新舊工法分工合作，就像三兄弟一樣。"},{"who":"A","text":"在門外抬頭看二樓，找找門框上那句「荊樹有花兄弟樂」的聯對吧！"}],"clues":["我是三兄弟從新加坡船業致富後合力蓋的","我正面有六根煙炙磚柱，分成五個開間","我是小金門羅厝聚落北側的五腳基洋樓"],"quiz":[{"q":"羅氏三兄弟在新加坡靠什麼行業致富？","options":["橡膠園","錫礦","船業","銀行"],"answer":2,"explain":"三兄弟避居新加坡後以船業致富。"},{"q":"洋樓正立面的柱子配置是？","options":["四柱三開間","六柱五開間","八柱七開間","二柱一開間"],"answer":1,"explain":"立面以煙炙磚柱分成六柱五開間。"}],"images":[]},{"id":"jincheng-juguanglou","name":"莒光樓","short":"莒光樓","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金城鎮","types":["其他設施"],"lat":24.42478,"lng":118.31872,"address":"金門縣金城鎮南門里賢城路1號","announced":"2006-06-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20060613000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-29/07bfcef0-6143-46d0-bc3d-5ee7f6370837/莒光樓「代表圖檔」.jpg","year":1953,"yearText":"1953年（民國42年）落成","era":"postwar","themes":["戰地史蹟","公共建築"],"yearUnknown":false,"summary":"仿紫禁城角樓的金門戰地精神地標","intro":"莒光樓位於金城鎮南門里賢城路，民國41年（1952）由胡璉將軍主導興建，次年秋天完工，當時金門軍民都參與構築，用以表彰金門戰役官兵事蹟並揭示「毋忘在莒」，當年又稱金門英雄館。樓高3層、約16公尺，為鋼筋混凝土造，仿紫禁城角樓的十字形平面與十字脊屋頂，覆青色琉璃瓦，斗栱與昂嘴皆以鋼筋混凝土仿木作。三樓「莒光樓」匾額由大二膽戰役中完成前線任務的賴生明所書。內部先後作為英雄館、金門歷史文物館等，現由金門縣政府觀光處管理，登頂可眺望後浦、浯江與烈嶼。","highlights":["仿紫禁城角樓的十字脊與青色琉璃瓦","三樓由賴生明題寫的「莒光樓」匾額","頂樓眺望後浦、浯江與烈嶼的風景"],"funFact":"莒光樓的十字屋脊約4公尺高，就佔了頂層一半的高度，難怪遠遠就能認出來。","photoSpot":"在樓前廣場仰拍十字脊屋頂","visitMin":30,"openNote":"位於金城鎮南門里賢城路，官方資料記載每日08:00至22:00開放，一樓為服務臺。可從金城市區步行，或開車、騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，來金門沒來莒光樓，就像吃燒餅沒有芝麻，少了一味喔！"},{"who":"R","text":"這棟樓的屋頂好華麗，好像古裝劇裡的宮殿！"},{"who":"A","text":"眼光不錯，它仿的是北京紫禁城角樓，十字形平面、十字脊屋頂，還鋪了青色琉璃瓦。"},{"who":"R","text":"那它也跟其他古蹟一樣，是幾百年前蓋的嗎？"},{"who":"A","text":"其實很年輕，民國41年由胡璉將軍主導興建，隔年完工，當時軍民一起參與構築。"},{"who":"R","text":"那為什麼要在金門蓋這樣一座樓呢？"},{"who":"A","text":"為了表彰金門戰役的官兵，也揭示「毋忘在莒」，當年又叫金門英雄館，是那個年代的精神象徵。"},{"who":"R","text":"原來它見證了金門的戰地歲月。那我們可以上樓嗎？"},{"who":"A","text":"可以，登上頂樓能看後浦和浯江。請你在三樓找找「莒光樓」匾額，記住題字的人是誰！"}],"clues":["我的匾額由一位大二膽戰役的戰鬥英雄題寫","我仿照紫禁城角樓，屋頂是十字脊與青色琉璃瓦","金城賢城路上，揭示「毋忘在莒」的三層樓"],"quiz":[{"q":"莒光樓的造型仿照哪一座建築？","options":["天壇祈年殿","紫禁城角樓","武昌黃鶴樓","湖南岳陽樓"],"answer":1,"explain":"仿紫禁城角樓的十字形平面與十字脊屋頂。"},{"q":"莒光樓由哪位將軍主導興建？","options":["黃杰","孫立人","胡璉","俞大猷"],"answer":2,"explain":"民國41年由胡璉將軍主導興建。"}],"images":[{"file":"Juguang Tower 20180727 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/Juguang_Tower_20180727_%28cropped%29.jpg/960px-Juguang_Tower_20180727_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Juguang_Tower_20180727_(cropped).jpg","artist":"姜 明雄","license":"CC0","licenseUrl":"http://creativecommons.org/publicdomain/zero/1.0/deed.en","local":"img/jincheng-juguanglou-0.webp","small":"img/jincheng-juguanglou-0-s.webp"}]},{"id":"jinning-shuangrushankeng","name":"金門雙乳山坑道","short":"雙乳山坑道","category":"縣定古蹟","level":"縣(市)定古蹟","town":"金寧鄉","types":["其他設施"],"lat":24.446958,"lng":118.357772,"address":"金門縣金寧鄉后盤山段14、16、16-1、352、352-3、352-6、353地號","announced":"2019-09-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/20191108000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-22/3ebb66a1-51fa-4596-90a1-be52e7746469/金門雙乳山坑道 (1).jpg","year":1957,"yearText":"1957年（民國46年）竣工","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"金門唯一穿越中央公路的環形坑道系統","intro":"金門雙乳山坑道位於金寧鄉雙乳山，地處金門島蜂腰部，可瞰制南北海岸、扼東西交通。1954年九三砲戰暴露金門戰備設施的脆弱，國軍開始將陣地逐步地下化，雙乳山坑道於1956年10月規劃，1957年10月竣工，乳南主入口有團長程仲宇銘刻的〈雙乳山坑道工程構建序〉。興建時投入約11萬700人日，有5人殉職。坑道分乳南、乳北兩部分，北乳山採披覆式挖掘、順等高線形成罕見的環形坑道，南乳山則以鑽挖式深入山腹，至今仍是金門唯一貫通伯玉路的坑道系統。坑道內留有1950年代風格的泥塑標語，2019年指定為縣定古蹟。","highlights":["北乳山順著等高線挖設的環形坑道","穿越伯玉路下方、以頂樑加強結構的坑道段","坑道節點的轉折射口與1950年代泥塑標語"],"funFact":"雙乳山坑道是金門唯一從中央公路伯玉路底下穿過去的坑道系統。","photoSpot":"在坑道入口拍銘刻的工程構建序","visitMin":40,"openNote":"位於金寧鄉雙乳山一帶。官方資料未載明開放時間，坑道與營區是否開放請以金門縣政府公告與現場告示為準，勿擅入未開放的坑道與營舍。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這座山為什麼叫雙乳山？我有點不好意思問。"},{"who":"A","text":"名字來自兩座相連的山頭，坑道也分成乳南和乳北兩部分。它在金門島最窄的蜂腰部，位置非常重要。"},{"who":"R","text":"所以山底下挖了坑道？是為了什麼呢？"},{"who":"A","text":"1954年九三砲戰後，國軍決定把陣地地下化。坑道1956年規劃，1957年竣工。"},{"who":"A","text":"當年動用約11萬700人日，有5位官兵在施工中殉職，這段歷史值得我們安靜記住。"},{"who":"R","text":"原來每一公尺都這麼不容易，我會放輕腳步。"},{"who":"A","text":"北乳山的坑道順著等高線繞成環形，而且是金門唯一從伯玉路底下穿過去的坑道系統。"},{"who":"R","text":"在馬路底下走路，上面的車子知道嗎？我覺得好像在玩地道探險。"},{"who":"A","text":"牆上還有很多泥塑標語，像「精忠報國」「還我河山」。請你找找入口刻的構建序，是哪位團長寫的？"}],"clues":["九三砲戰後，國軍把我挖進山腹，1957年竣工","我有一段環形坑道，還從中央公路底下穿過","我在金門島蜂腰部，分成乳南和乳北兩部分"],"quiz":[{"q":"雙乳山坑道是在哪一場砲戰後開始規劃興建的？","options":["古寧頭戰役","八二三砲戰","九三砲戰","六一七砲戰"],"answer":2,"explain":"1954年九三砲戰後陣地逐步地下化，1956年規劃坑道。"},{"q":"雙乳山坑道在金門有什麼獨特之處？","options":["唯一貫通伯玉路的坑道","唯一可通行船艦的坑道","金門最早的坑道","唯一位在小金門的坑道"],"answer":0,"explain":"它至今仍是金門唯一貫通中央公路伯玉路的坑道系統。"}],"images":[]},{"id":"jincheng-shuitou","name":"水頭（又名前水頭、金水）","short":"水頭聚落","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.41147,"lng":118.29996,"address":"金門縣金城鎮前水頭金水里","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000016","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-09-12/b38cc54a-c9ff-4e16-9947-b64617d485b0/水頭-代表圖像.jpg","year":1315,"yearText":"1315年（元延祐2年）黃氏開基","era":"dutch","themes":["聚落地景","閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"有水頭富，無水頭厝，古厝洋樓共演的僑鄉","intro":"水頭又名前水頭、金水，位於金門島西南方的金城鎮。相傳最早有白姓漁民在此搭寮避風；有文字記載的開庄，則是元延祐2年（1315）登進士的黃輔（仲卿公）避元亂遷居於此。清乾隆以後黃氏在杭州、錦州經商致富，修建宗祠與屋舍，留下「十八支樑」等棋盤式布局的二落大厝，贏得「有水頭富，無水頭厝」美名。19世紀中葉後族人大量出洋，以印尼華僑最著名，僑匯興建了得月樓洋樓群與金水小學。聚落分頂界、中界、下界、後界，有5座宗祠與4座宮廟，是多姓聚落。","highlights":["清乾隆年間棋盤式排列的「十八支樑」大厝群","得月樓洋樓群與國定古蹟黃氏酉堂別業","5座宗祠與金水寺等4座宮廟"],"funFact":"水頭是多姓聚落，除黃姓外，還有從同安遷來的李姓與瓊林蔡氏前水頭支派。","photoSpot":"在頂界巷弄拍大厝燕尾與洋樓同框","visitMin":90,"openNote":"位於金城鎮金水里，聚落巷弄可自由步行參觀，部分建築由金門國家公園管理處設為展示館開放；多數古厝仍有人居住，請勿擅入、勿打擾住戶。可搭金門縣公車到水頭，鄰近水頭碼頭。","dialogue":[{"who":"A","text":"金門有句老話：「有水頭富，無水頭厝。」阿拉蕾，你猜這是在誇什麼？"},{"who":"R","text":"誇水頭人很有錢，可是房子還是比不上水頭漂亮？"},{"who":"A","text":"答對！水頭的開基祖黃輔是元朝1315年的進士，因為不想當元朝的官，就避居在這裡。"},{"who":"R","text":"考上進士卻不當官，好有個性喔！"},{"who":"A","text":"清乾隆以後黃家到杭州、錦州做生意發財，蓋了十八支樑大厝，排得像棋盤一樣整齊。"},{"who":"R","text":"那洋樓呢？我剛剛看到好多西式陽台。"},{"who":"A","text":"19世紀中葉以後族人到印尼打拚，把錢匯回來蓋洋樓、辦學校，得月樓就是代表。"},{"who":"R","text":"一個聚落就有元朝、清朝和南洋風，根本是時光走廊！"},{"who":"A","text":"逛累了可以吃碗蚵仔麵線。最後請你在巷弄裡找出一棟大厝和一棟洋樓，拍一張同框照！"}],"clues":["相傳最早有白姓漁民在我這裡搭草寮避風","元朝進士黃輔避亂定居，清代留下棋盤式大厝群","人說「有ＸＸ富，無ＸＸ厝」，我又名金水"],"quiz":[{"q":"水頭黃氏開基祖黃輔是哪個朝代的進士？","options":["宋朝","元朝","明朝","清朝"],"answer":1,"explain":"黃輔於元延祐2年（1315）登進士。"},{"q":"水頭聚落19世紀中葉後的華僑以哪裡最著名？","options":["印尼","菲律賓","日本","美國"],"answer":0,"explain":"官方資料記載以印尼華僑最為著稱。"}],"images":[]},{"id":"jincheng-zhushan","name":"珠山（薛厝坑、山仔兜）","short":"珠山聚落","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.402099,"lng":118.321008,"address":"金門縣金城鎮珠山聚落","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000021","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-26/753d7420-264b-46b4-8193-0ef7a15f1cd5/01封面.jpg","year":1345,"yearText":"1345年（元代）薛氏渡海開基","era":"dutch","themes":["聚落地景","閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"薛氏單姓聚落，大潭倒映古厝與洋樓","intro":"珠山聚落位於金城鎮，開基祖薛貞固世居同安，官方資料記載元代1345年避難渡海來浯洲，先居太文山之南，稱「薛厝坑」；其子薛成濟移居雞庵山麓，聚落中央有大潭，稱「龜山兜」或「山仔兜」，民國初年改名珠山。薛氏家廟建於清乾隆33年（1768），以家廟為中心分大社、小社。19世紀中葉後族人多赴呂宋，僑匯興建了下三落、大夫第等建築，也創辦珠山小學。1937年日軍占領金門後僑匯中斷，有273位居民逃往大嶝避難；1958年八二三砲戰，聚落受損嚴重，歷經很長時間才復原。","highlights":["聚落中央的大潭與倒映其中的古厝群","以薛氏家廟為中心分成大社、小社的格局","呂宋僑匯興建的下三落、大夫第等洋樓"],"funFact":"珠山舊名「山仔兜」，民國初年才改名珠山，六百多年來幾乎都是薛氏宗親。","photoSpot":"在大潭邊拍古厝群倒影","visitMin":60,"openNote":"位於金城鎮珠山聚落，巷弄可自由步行參觀，部分建築修復後作為展示館、餐飲或住宿使用；多數古厝仍有人居住，請勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這個聚落中間有一大池水，好像一面鏡子喔！"},{"who":"A","text":"那是大潭，以前聚落就叫龜山兜或山仔兜，民國初年才改名叫珠山。"},{"who":"R","text":"名字改得好，聽起來像一顆珍珠放在山腳下。"},{"who":"A","text":"這裡是薛氏聚落，開基祖薛貞固在元代從同安渡海來金門，後代就在潭邊繁衍。"},{"who":"A","text":"19世紀中葉以後，很多珠山人到呂宋，也就是菲律賓打拚，把錢寄回來蓋洋樓、辦小學。"},{"who":"R","text":"所以這裡古厝和洋樓混在一起，是南洋寄回來的家書變成的房子。"},{"who":"A","text":"說得真美。不過1958年八二三砲戰時，聚落受損很嚴重，花了很長時間才慢慢復原。"},{"who":"R","text":"能一直守住這片家園，真的很不簡單。"},{"who":"A","text":"逛完記得吃碗炒泡麵補體力。請你站在大潭邊，拍一張古厝倒映在水面的照片！"}],"clues":["我舊名叫薛厝坑、山仔兜，民國初年才改名","我中央有一座大潭，族人多到呂宋打拚","我是金城鎮的薛氏聚落，以家廟為中心分大社小社"],"quiz":[{"q":"珠山聚落的居民主要姓什麼？","options":["黃","蔡","陳","薛"],"answer":3,"explain":"珠山是薛氏聚落，開基祖為薛貞固。"},{"q":"珠山人在19世紀中葉後主要僑居哪裡？","options":["呂宋","印尼","緬甸","新加坡"],"answer":0,"explain":"官方資料記載以呂宋為主要僑居地。"}],"images":[{"file":"金門古厝聚落.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/%E9%87%91%E9%96%80%E5%8F%A4%E5%8E%9D%E8%81%9A%E8%90%BD.jpg/960px-%E9%87%91%E9%96%80%E5%8F%A4%E5%8E%9D%E8%81%9A%E8%90%BD.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E5%8F%A4%E5%8E%9D%E8%81%9A%E8%90%BD.jpg","artist":"潘同正","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-zhushan-0.webp","small":"img/jincheng-zhushan-0-s.webp"}]},{"id":"jincheng-lishijiamiao","name":"李氏家廟","short":"李氏家廟","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.41101,"lng":118.29718,"address":"金門縣金城鎮前水頭80號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000054","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-30/a8e2a8dc-3695-4075-ac59-d6a14d512ad7/李氏家廟 (1).jpg","year":1380,"yearText":"相傳創建於明初，清代遷界後重建","era":"dutch","themes":["宗祠家廟"],"yearUnknown":false,"summary":"相傳原有五落、遷界後僅復建一落的李氏家廟","intro":"李氏家廟位於金城鎮水頭聚落中界，這一帶舊稱「奈社」。元代至元18年（1281），李良亨從同安奈厝遷居於此。明代李氏宦績顯赫，相傳創建於明初的家廟原有五落，明末遭倭亂燒毀；清初遷界後返鄉的族人只復建一落。家廟在清光緒年間與1984年整修，2010年秋由前水頭李氏宗親會申請修復獎助進行整體修復，2011年竣工。建築為一落帶牆規門，翹脊兩端有釉陶龍隱，門楣刻「李氏家廟」、「奈社」等字，兩側聯對為「源出山西綿世澤，支分奈社振家聲」。正廳大通彩繪二十四孝與唐太宗故事，每年冬至祭祖。","highlights":["門楣上的「李氏家廟」與「奈社」刻字","聯對「源出山西綿世澤，支分奈社振家聲」","翹脊兩端的釉陶龍隱裝飾"],"funFact":"相傳明初的李氏家廟原有五落，明末遭倭亂燒毀，清代族人只復建了一落。","photoSpot":"牆規門前拍門楣刻字與翹脊","visitMin":10,"openNote":"位於金城鎮水頭聚落中界，宗族家廟，官方資料記載於冬至祭祖，平日請在外觀參觀，勿擅入；祭祖時請勿打擾。水頭聚落鄰近水頭碼頭，可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這座家廟只有一落，看起來小巧玲瓏耶。"},{"who":"A","text":"小巧是現在的樣子。相傳水頭的李氏家廟在明初創建時，可是有五落的大家廟。"},{"who":"R","text":"五落變一落？是被縮小燈照到了嗎？"},{"who":"A","text":"沒那麼科幻。明末遭倭亂燒毀，清初又遇到遷界，族人回鄉後只能先復建一落。"},{"who":"R","text":"原來背後這麼艱辛。那李家是什麼時候來到水頭的？"},{"who":"A","text":"1281年元代，李良亨從同安奈厝搬來，這一帶就叫奈社，門楣上還刻著奈社兩個字。"},{"who":"R","text":"把老家的名字帶過來，好像在說我們沒有忘本。"},{"who":"A","text":"沒錯，門聯寫著源出山西綿世澤，支分奈社振家聲。念完我都想吃碗石蚵麵線補補元氣。"},{"who":"A","text":"請你站到牆規門前，看看翹脊兩端的龍隱，找找牠們是什麼顏色的釉陶！"}],"clues":["相傳我原有五落，明末遭倭亂燒毀","我的祖先在1281年從同安奈厝遷來","我的門楣刻著奈社，每年冬至祭祖"],"quiz":[{"q":"相傳明初創建的李氏家廟原本有幾落？","options":["二落","三落","七落","五落"],"answer":3,"explain":"相傳原為五落，明末遭倭亂燒毀。"},{"q":"李氏家廟門楣上刻的舊地名是？","options":["奈社","金水","許坑","平林"],"answer":0,"explain":"這一帶昔稱奈社，門楣刻有「奈社」。"}],"images":[]},{"id":"jincheng-qianshuitouhuang","name":"前水頭黃氏家廟","short":"前水頭黃氏家廟","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.40988,"lng":118.29952,"address":"金門縣金城鎮前水頭30號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000028","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-29/3a7fb422-f685-4938-8a65-31b0aaf72162/01封面.jpg","year":1395,"yearText":"約1390年代（明洪武末年）","era":"dutch","themes":["宗祠家廟"],"yearUnknown":false,"summary":"官方記載約建於明洪武末年的水頭家廟","intro":"前水頭黃氏家廟位於金城鎮水頭聚落，官方資料記載約興建於明洪武末年（約1390–1398），清末民初曾重修，2015至2016年依《金門縣私有歷史建築修復獎助辦法》完成整體修復。建築為二落大厝加右護龍，大厝屋頂是閩南雙坡三川脊，脊肚有交趾陶與剪黏裝飾，屋坡鋪紅瓦。正面採榻受，以子午窗、插角、吊筒等木雕裝飾，並施彩繪與按金，正門兩側有抱鼓石；向埕的牆面額堵畫著山水彩繪。右護龍門也做榻受，對看堵為單色壁畫。家廟目前不開放參觀，官方說明詳細歷史仍待日後深入調查。","highlights":["三川脊脊肚的交趾陶與剪黏裝飾","榻受的子午窗、插角與吊筒木雕","正門兩側的一對抱鼓石"],"funFact":"官方紀錄它約興建於明洪武末年，比同在水頭、1760年興建的世澤堂早了300多年。","photoSpot":"前埕正面拍三川脊與紅瓦屋坡","visitMin":10,"openNote":"位於金城鎮水頭聚落，宗族家廟，官方資料記載不開放參觀，請在外觀欣賞，勿擅入。水頭聚落鄰近水頭碼頭，可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，妳覺得水頭聚落裡最資深的長輩是誰？"},{"who":"R","text":"是村口那位最會泡茶、最愛講古的阿公嗎？"},{"who":"A","text":"論年紀，這座前水頭黃氏家廟可能更資深。官方資料說它約建於明洪武末年，也就是1390年代。"},{"who":"R","text":"1390年代？那它已經600多歲了，比我生日蛋糕的蠟燭多太多了！"},{"who":"A","text":"中間當然修過很多次，清末民初重修過，2015到2016年又做了整體修復，才有現在的模樣。"},{"who":"R","text":"那它從外面看起來，長得是什麼樣子？"},{"who":"A","text":"二落大厝加右護龍，屋頂是三川脊，中間高、兩側低，脊肚裝飾著交趾陶和剪黏，配上紅瓦很亮眼。"},{"who":"R","text":"那我可以走進去看看裡面的牌匾嗎？"},{"who":"A","text":"這裡目前不開放參觀，我們在外面看就好。請你找找正門兩側那對抱鼓石，拍下它圓滾滾的樣子！"}],"clues":["官方說我約建於明洪武末年","我是二落大厝加右護龍，正門兩側有抱鼓石","我在水頭聚落，目前不開放參觀，只能看外觀"],"quiz":[{"q":"官方資料記載這座家廟約興建於何時？","options":["宋代末年","明洪武末年","清乾隆年間","民國初年"],"answer":1,"explain":"官方資料記載約興建於明洪武末年。"},{"q":"家廟正門兩側有什麼石雕？","options":["石獅","石敢當","抱鼓石","石筍"],"answer":2,"explain":"榻受正門兩側設有抱鼓石。"}],"images":[]},{"id":"jinhu-chenkengchenyuxiu","name":"陳坑陳與秀墓","short":"陳與秀墓","category":"歷史建築","level":"","town":"金湖鎮","types":["墓葬"],"lat":24.44221,"lng":118.40053,"address":"金門縣金湖鎮塔后段745-2地號","announced":"2022-03-07","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20220401000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-04-01/33da9d34-5cb1-424e-b602-1298ecfe18b9/陳坑陳與秀墓01.jpg","year":1400,"yearText":"約明代初年（距今600餘年）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"通體灰砂夯築的明初庶人大墓","intro":"陳坑陳與秀墓位於金湖鎮夏興聚落東北側高地。墓主陳與秀是陳八郎派下第八世、夏興「五房張厝房」的開基祖，生卒年不詳，依同時代族人陳顯的生卒推估約逝世於明初，墓塋至今600餘年，族人世代於清明祭掃。墓碑無碑文，坐落岩坡、前望大海、後倚巨石，墓前凹地早年匯水成池，又稱「田螺墓」。墓由墓碑、墓桌、墓龜、護牆與三組曲手組成，全以混合灰、土、砂、糯米的灰砂夯築，沒有一處石構件，在金門明代墓中極為少見；墓名則取陳與秀出生地成功村的舊名「陳坑」。","highlights":["全墓沒有石構件，通體以灰砂夯築","護牆仿紅磚疊澀的鋸齒紋與雙波浪紋","墓碑中央已風化的瑞日、祥雲紋樣"],"funFact":"墓前凹地早年積水，「田螺生在其中」，所以在地人叫它「田螺墓」。","photoSpot":"在墓埕外側拍階梯狀的三組曲手","visitMin":15,"openNote":"位於金湖鎮夏興聚落東北側高地，官方資料記載參觀無限制；墓塋仍由陳氏族人清明祭掃，請保持肅靜，勿攀爬墓體。開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，這座古墓看起來灰灰的，其實它是用灰砂整座夯出來的，連一塊石頭構件都沒有喔。"},{"who":"R","text":"沒有石頭？Allan，那不就像用水泥灌出來的？這樣也能撐600多年？"},{"who":"A","text":"古人的灰砂配方很講究，灰、土、砂再加上糯米，有點像超強版的麻糬黏著劑。"},{"who":"R","text":"拿糯米蓋墳墓，我聽了都餓了。那墓主是誰呀？"},{"who":"A","text":"族人世代相傳是陳與秀，夏興這一支五房張厝房的開基祖。墓碑沒有刻字，全靠口耳相傳。"},{"who":"R","text":"沒刻字還能記得600年，這家族的記性比我的硬碟還好！"},{"who":"A","text":"早年墓前凹地會積水，田螺就住在裡面，所以在地人也叫它田螺墓。"},{"who":"R","text":"田螺墓，好可愛的綽號！那我們今天的任務是什麼？"},{"who":"A","text":"看看護牆上一排排的鋸齒紋，那是在模仿紅磚疊砌。欣賞時記得保持肅靜，別踩上墓體喔。"}],"clues":["我沒有刻字的墓碑，身分全靠族人代代口傳","我全身沒有一塊石構件，是灰、砂、糯米夯成的","我在夏興高地，因墓前積水養田螺而得綽號"],"quiz":[{"q":"這座古墓的主體是用什麼材料建成？","options":["花崗石雕件","灰砂夯築","紅磚疊砌","木構外包石板"],"answer":1,"explain":"全墓無石構件，以灰、土、砂、糯米混合的灰砂夯築。"},{"q":"在地人給這座墓取的綽號是？","options":["石獅墓","海龜墓","風獅墓","田螺墓"],"answer":3,"explain":"墓前凹地早年積水有田螺，因此稱為田螺墓。"}],"images":[]},{"id":"jincheng-chengbeimenwaiming","name":"金門城北門外明遺古街","short":"明遺古街","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.40368,"lng":118.3089,"address":"金門縣金城鎮金門城北門外","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000015","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-02-20/1b52f8cb-b6e4-43e0-9e96-f13c47a5c42b/明遺古街.jpg","year":1500,"yearText":"約16世紀（明代中葉）","era":"dutch","themes":["市場商業","聚落地景","城池衛所"],"yearUnknown":false,"summary":"明代所城外的商街，疊著各時代建築","intro":"金門城北門外明遺古街位於金城鎮金門城聚落北門外，創建於明代中葉。當時金門守禦千戶所城內的市街已不敷需求，城東古崗、珠山、歐厝等聚落又多由北門出入，於是城外發展出另一條商街，明代至清初是金門最繁榮的市街之一。清代總兵署移往後浦後逐漸沒落。古街總長約135公尺，中央以花崗石鋪面，靠城牆的南端稱「街頂」、北端稱「街下」，原設有隘門。街上有二進一天井的長條店屋、閩南合院、1921年新加坡醫生黃天佑興建的洋樓，以及1978年後的新式樓房。","highlights":["中央花崗石鋪面與兩側40公分寬的「轍車道」","二進一天井長條店屋，牆面內縮的「戶碇」","街下的王公宮（迴向殿）與隘門石條遺跡"],"funFact":"砲戰後路面受損，居民每戶出資900元，配合政府經費重修這條老街。","photoSpot":"從街頂往街下拍石板路與店屋","visitMin":25,"openNote":"位於金城鎮金門城聚落北門外，街道為開放空間可步行參觀；沿街多為私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這條小街窄窄的，地上還有一條石頭路，好像古裝劇的場景！"},{"who":"A","text":"眼光不錯！這是金門城北門外的明遺古街，明代中葉就形成了，是城外的商業街。"},{"who":"R","text":"為什麼要在城外開店？城裡不夠賣嗎？"},{"who":"A","text":"對，城內市街容納不下，城東古崗、珠山等聚落的人又多走北門，生意就做到城門外啦。"},{"who":"R","text":"那為什麼現在這條街這麼安靜呢？"},{"who":"A","text":"清代總兵署搬到後浦，人潮跟著走，這裡就沒落了，就像我的減肥計畫，熱鬧一陣就散了。"},{"who":"R","text":"你那個比喻好心酸。街上的房子都一樣老嗎？"},{"who":"A","text":"不一樣！有明清店屋、民國初年的洋樓，也有1978年後的新樓房，135公尺就像一本建築史。"},{"who":"A","text":"走的時候請低頭看，找找石板路兩旁那條40公分寬的轍車道，想像當年推車經過的樣子。"}],"clues":["我在明代中葉成形，因為城內市街不夠用才延伸到城外","我全長約135公尺，南端叫街頂、北端叫街下","我在金門城北門外，是一條花崗石鋪面的老街"],"quiz":[{"q":"這條古街為何在清代逐漸沒落？","options":["遭颱風摧毀","港口淤積","總兵署移至後浦","改朝換代被拆除"],"answer":2,"explain":"清代總兵署移置後浦，人口遷出，北門外市街隨之沒落。"},{"q":"古街靠城牆的南端被稱為什麼？","options":["街頂","街頭","街尾","街心"],"answer":0,"explain":"靠城牆的南端稱街頂，北端稱街下。"}],"images":[{"file":"石板路 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/%E7%9F%B3%E6%9D%BF%E8%B7%AF_%28cropped%29.jpg/960px-%E7%9F%B3%E6%9D%BF%E8%B7%AF_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E7%9F%B3%E6%9D%BF%E8%B7%AF_(cropped).jpg","artist":"張南翥","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-chengbeimenwaiming-0.webp","small":"img/jincheng-chengbeimenwaiming-0-s.webp"}]},{"id":"jinhu-shunjigong","name":"順濟宮","short":"料羅順濟宮","category":"歷史建築","level":"","town":"金湖鎮","types":["寺廟"],"lat":24.41963,"lng":118.43458,"address":"金門縣金湖鎮料羅段1090地號","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000011","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-20/33fc567b-6aa8-4766-8bbc-b99a7054b1e6/1封面.jpg","year":1500,"yearText":"明代創建（確切年代不詳），2019年重建","era":"dutch","themes":["宗教信仰","牌坊碑碣"],"yearUnknown":false,"summary":"金門第一座媽祖廟，留有清乾隆石碑","intro":"順濟宮位於金湖鎮料羅聚落，據縣誌記載興建於明代，是金門地區第一座媽祖廟。廟宇主祀媽祖（大媽、二媽、三媽），並祀聖祖媽、觀音、中壇元帥、千里眼與順風耳，陪祀水僊尊王與註生娘娘，每年農曆3月23日為媽祖千秋日。民國72年（1983）因年久與戰火毀損，由村民捐款重修；2014年再動工重建，2019年完工，保留左右大規壁、後寮牆的石構材料與正殿拜石。殿內仍保存一塊清乾隆21年（1756）石碑，內容為「勒石永禁嶼內外不許設立繒棚」。","highlights":["左側龍井下方的清乾隆21年石碑","舊廟保留下來的石構大規壁與正殿拜石","後殿藻井與金碧輝煌的木雕棟架"],"funFact":"相傳順濟宮所在之地是「虎穴」，所以香火特別旺盛。","photoSpot":"在廟埕拍三川門與一對龍柱","visitMin":20,"openNote":"位於金湖鎮料羅聚落，為地方信仰中心，開放民眾參拜，開放時間依廟方安排；參觀請保持安靜、尊重祭祀。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，這間廟金光閃閃，看起來好新，怎麼會是文化資產？"},{"who":"A","text":"它2019年才重建完成沒錯，不過根據縣誌，順濟宮在明代就有了，是金門第一座媽祖廟。"},{"who":"R","text":"第一座！那媽祖在金門資歷最深的辦公室就在料羅囉？"},{"who":"A","text":"可以這麼說。廟裡供奉大媽、二媽、三媽，每年農曆3月23日媽祖千秋，是村裡最熱鬧的日子。"},{"who":"R","text":"那重建以後，還留下什麼老東西嗎？"},{"who":"A","text":"兩側大規壁和後牆的老石材、正殿拜石都保留了，還有一塊清乾隆21年的石碑，內容是禁止設立繒棚。"},{"who":"R","text":"把禁令刻在石頭上，比貼在布告欄還有魄力！"},{"who":"A","text":"對啊，想撕都撕不掉。進廟參拜後，到左側龍井下方找找這塊乾隆石碑，看看上面的字吧！"}],"clues":["我重建過，但身上藏著一塊清乾隆21年的禁令碑","我供奉大媽、二媽、三媽，農曆3月23日最熱鬧","我在料羅，縣誌說我是金門第一座媽祖廟"],"quiz":[{"q":"根據縣誌，順濟宮在金門有什麼特別地位？","options":["第一座媽祖廟","最大的王爺廟","最早的佛寺","唯一的海神廟"],"answer":0,"explain":"縣誌記載順濟宮興建於明代，是金門第一座媽祖廟。"},{"q":"殿內清乾隆石碑的內容是什麼？","options":["捐款人芳名","重修廟宇紀錄","禁止設立繒棚","媽祖顯靈事蹟"],"answer":2,"explain":"碑文為「勒石永禁嶼內外不許設立繒棚」。"}],"images":[]},{"id":"jincheng-zhupuxushijiamiao","name":"珠浦許氏家廟","short":"珠浦許氏家廟","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.43152,"lng":118.31605,"address":"金門縣金城鎮珠浦南路28號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000068","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-27/ab6d4857-0769-4133-a72d-8d46b4161044/(1)封面.jpg","year":1533,"yearText":"1533年（明嘉靖12年）","era":"dutch","themes":["宗祠家廟"],"yearUnknown":false,"summary":"明代創建的三落家廟，許氏明代出了28位進士","intro":"珠浦許氏家廟位於金城鎮後浦珠浦南路，創建於明嘉靖12年（1533），清雍正9年（1731）大修，20世紀因戰亂部分坍塌，1971年重建，歷時4年完工，2003至2004年再由縣府補助修復。家廟曾作宗族私塾，戰地政務時期也充當小學教室與公家辦公處所。許氏是後浦望族，明代即出了文進士28人、武進士3人，祖龕上方高掛「鄉賢」聖旨，表彰會元許獬。建築為三落，前落屋面採金門罕見的「斷簷升箭口」做法，穿堂兩側水池養著魚與龜。廟旁立有清同治9年與民國元年禁止爭佔許氏渡船、渡頭事業的石碑。","highlights":["前落金門罕見的「斷簷升箭口」屋頂","中落祖龕上方表彰許獬的「鄉賢」聖旨","廟旁兩座禁止爭佔許氏渡船、渡頭的石碑"],"funFact":"早年旅居澎湖的許氏宗親，每年冬至都僱船趕回金門祭祖，持續了很長一段時間。","photoSpot":"在門口埕拍前落斷簷升箭口屋頂","visitMin":20,"openNote":"位於金城鎮後浦珠浦南路，官方資料記載家廟平日不開放，採預約參觀制，其餘時間請在外觀參觀。金城車站附近，可步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，考試前大家都拜文昌帝君，但在後浦，有一家人光明朝就出了28位文進士。"},{"who":"R","text":"28位？那他們家吃飯是不是都在討論八股文？"},{"who":"A","text":"哈，有可能喔。這就是珠浦許氏，家廟在1533年明嘉靖年間就創建了。"},{"who":"R","text":"這麼多進士裡，最有名的是哪一位？"},{"who":"A","text":"會元許獬。祖龕上方還掛著一道「鄉賢」聖旨，就是表彰他的。"},{"who":"R","text":"好厲害！那廟門口兩塊石碑寫什麼？"},{"who":"A","text":"是清同治和民國元年頒的碑，禁止別人爭佔許家的渡船和渡頭事業，等於是古代的營業執照。"},{"who":"R","text":"原來許家不只會讀書，還很會做海運生意！"},{"who":"A","text":"家廟平日要預約才能進去。在外面請你抬頭看，前落屋頂中間是不是高起來一截，那就是斷簷升箭口！"}],"clues":["我的前落屋頂採金門罕見的斷簷升箭口","我旁邊有兩座禁止爭佔渡船、渡頭事業的石碑","我是後浦望族的家廟，明嘉靖12年創建"],"quiz":[{"q":"珠浦許氏家廟創建於哪個年代？","options":["元代","明嘉靖年間","清乾隆年間","民國初年"],"answer":1,"explain":"家廟創建於明嘉靖12年（1533）。"},{"q":"家廟祖龕上方的「鄉賢」聖旨是表彰哪一位？","options":["許獬","許金鐘","許忠輔","許延年"],"answer":0,"explain":"聖旨表彰會元傳臚編脩許獬。"}],"images":[]},{"id":"jinhu-dingxiaohedengtai","name":"(明)丁肖鶴登太武山題詩碑","short":"丁肖鶴題詩碑","category":"歷史建築","level":"","town":"金湖鎮","types":["碑碣"],"lat":24.46049,"lng":118.41029,"address":"金門縣金湖鎮太武山上","announced":"2005-12-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051219000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-27/002fe510-f1fd-41e1-be6a-a344a564ac16/(明)丁肖鶴登太武山題詩碑封面.jpg","year":1572,"yearText":"1572年（明隆慶6年）","era":"dutch","themes":["摩崖石刻"],"yearUnknown":false,"summary":"四百多年前遊客刻在太武山眠雲石上的詩","intro":"丁肖鶴登太武山題詩碑位於金湖鎮太武山上，刻在通往中華電信發射臺道路旁的兩塊花崗石之間，約兩公尺見方。丁一中號肖鶴，南京丹陽人，時任溫陵郡丞，1572年（明隆慶6年）夏天來金門遊覽，與柳遇春等多位友人同登太武山，有感而題詩兩首，以陰刻鐫於石上，至今四百多年，大部分字跡仍清晰可辨。詩中「白石眠雲萬慮閒」等句描寫登山所見。明代洪受《滄海紀遺》記載題詩刻在「風動石之左」，實際上刻詩的是眠雲石，旁邊刻有「鳴寉」（寉為鶴的異體字）字樣的才是風動石，兩者都是昔日太武山的奇石景觀。丁肖鶴也曾登臨金門城南郊的嘯臥亭題詩。","highlights":["刻在眠雲石上的兩首七言律詩","詩末一長串同遊友人的姓名","一旁刻有「鳴寉」二字的風動石"],"funFact":"收錄這首詩的《滄海紀遺》據說成書於隆慶二年，卻記下隆慶六年的題詩，原因至今是個謎。","photoSpot":"在步道旁拍刻詩巨石與遠方海景","visitMin":15,"openNote":"位於金湖鎮太武山上，需步行登山前往。太武山屬軍事管制區域，步道開放時間依軍方與管理單位公告為準。","dialogue":[{"who":"A","text":"爬到太武山這裡，先喘口氣。阿拉蕾，妳看這塊大石頭上刻滿了字。"},{"who":"R","text":"這是誰的塗鴉？在古蹟上亂寫字不是會被罵嗎？"},{"who":"A","text":"哈，這可是正式的題詩碑。1572年明隆慶6年，溫陵郡丞丁肖鶴和一大群朋友一起登太武山，留下兩首詩。"},{"who":"R","text":"一大群人一起爬山，根本是明代的登山社！"},{"who":"A","text":"詩的最後還把同遊的朋友名字全刻上去，等於四百多年前的團體大合照。"},{"who":"R","text":"那詩裡寫了什麼？我想聽一句看看！"},{"who":"A","text":"像是「白石眠雲萬慮閒」，躺在白石上看雲，什麼煩惱都沒了，跟我吃完一包貢糖的心情一樣。"},{"who":"R","text":"你的煩惱也太容易被貢糖解決了吧！"},{"who":"A","text":"刻詩的這塊叫眠雲石，旁邊還有一塊風動石。請你找找哪塊石頭刻著「鳴鶴」，鶴字還用了古老的寫法。"}],"clues":["我身上刻著一長串同遊者的名字","我刻在眠雲石上，古書卻說我在風動石之左","我是明隆慶年間一位郡丞登太武山留下的兩首詩"],"quiz":[{"q":"丁肖鶴在哪一年登太武山題詩？","options":["1371年","1572年","1662年","1726年"],"answer":1,"explain":"丁肖鶴於明隆慶6年（1572）夏天來金登太武山題詩。"},{"q":"題詩實際刻在哪一塊石頭上？","options":["風動石","仙人石","海印石","眠雲石"],"answer":3,"explain":"題詩勒石處為眠雲石，「鳴鶴」鐫石處才是風動石。"}],"images":[]},{"id":"jincheng-oucuoouyangshikai","name":"歐厝歐陽氏開基祖暨三房祖明代古墓","short":"歐厝明代古墓","category":"歷史建築","level":"","town":"金城鎮","types":["墓葬"],"lat":24.404506,"lng":118.329657,"address":"金門縣金城鎮歐厝聚落外圍","announced":"2018-03-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20180428000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-10-14/2edd9283-0303-48f1-9dc3-c5a20bafa41b/01.jpg","year":1600,"yearText":"明代（約16世紀末至17世紀初）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"歐厝開基祖與三房祖的花崗石明代墓塋","intro":"這兩座墓位於金城鎮歐厝聚落外圍，分屬歐厝開基祖歐陽文卿與三房祖歐陽定日。據1984年編纂的《金門歐陽族譜》，歐陽文卿是明代晉江蚶江里人，嘉靖年間駕竹筏出海捕魚遇颱風，漂到金門登岸，在煙墩山南麓墾荒定居，薛厝坑（今珠山）薛公把女兒嫁給他，生下五子，「歐厝」就是他的故居之名。三房祖歐陽定日終身擔任塾師，推測生於約1570至1580年間。宗親相傳開基祖墓是在三房祖墓修成後才整修，所以兩墓形制相近。兩墓都以花崗石壘砌，而非一般常用的三合土，墓龜刻六角龜背紋，曲手有勾唇龍首雕刻。","highlights":["墓龜上整塊花崗石刻成的六角龜背紋","二曲手脊飾上的勾唇龍首雕刻","三房祖墓桌下方的「福」「祿」「壽」三字"],"funFact":"據族譜，開基祖乘竹筏遇颱風漂到金門，竹筏又被浪沖走，回不去只好在此落地生根。","photoSpot":"墓埕外側拍花崗石墓龜與曲手","visitMin":20,"openNote":"位於金城鎮歐厝聚落外圍，屬戶外家族墓葬，請保持尊重，勿攀爬、勿踩踏墓體與墓埕；部分曲手已傾斜，請勿碰觸。可騎機車或開車前往歐厝聚落。","dialogue":[{"who":"A","text":"阿拉蕾，歐厝這個聚落的名字是怎麼來的，妳猜得到嗎？"},{"who":"R","text":"因為大家都姓歐陽？還是因為這裡的人考試都歐趴？"},{"who":"A","text":"是歐陽家！族譜記載，明代嘉靖年間，晉江的歐陽文卿駕竹筏出海捕魚，遇到颱風漂到了金門。"},{"who":"R","text":"被颱風吹來的開基祖！那他後來怎麼回家？"},{"who":"A","text":"竹筏被浪捲走，回不去了，他就在煙墩山南邊開墾。珠山的薛公看他敦厚老實，把女兒嫁給他，生了五個兒子。"},{"who":"R","text":"落難變良緣，比偶像劇還精彩耶！"},{"who":"A","text":"這裡就是開基祖和三房祖的明代古墓，都用花崗石壘砌，不是一般常見的三合土。"},{"who":"R","text":"那這兩座墓上有什麼特別的雕刻嗎？"},{"who":"A","text":"墓龜刻著六角龜背紋。請保持尊重，在墓埕外找找曲手上的勾唇龍首，看看是什麼表情。"}],"clues":["我的主人駕竹筏遇颱風，漂流到金門","主人娶了薛厝坑薛公的女兒，生下五子","我們是開基祖和三房祖的花崗石明代墓塋"],"quiz":[{"q":"歐厝開基祖歐陽文卿是怎麼來到金門的？","options":["竹筏遇颱風漂流而來","隨軍隊來島駐防","受聘來島上教書","經商後舉家遷居"],"answer":0,"explain":"他駕竹筏出海捕魚遇颱風，漂至金門登岸。"},{"q":"這兩座明代墓塋主要用什麼材料壘砌？","options":["三合土","紅磚","玄武岩","花崗石"],"answer":3,"explain":"兩墓以花崗石壘砌，取代民間常用的三合土。"}],"images":[]},{"id":"lieyu-qianpubaozhanggong","name":"前埔保障宮","short":"前埔保障宮","category":"歷史建築","level":"","town":"烈嶼鄉","types":["寺廟"],"lat":24.42823,"lng":118.23455,"address":"金門縣烈嶼鄉前埔測段1061、1064地號","announced":"2016-06-06","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20160606000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-14/39615142-1553-436a-9624-a96794cff800/1 封面.jpg","year":1600,"yearText":"相傳創建於明代，現貌為1969年（民國58年）重修","era":"dutch","themes":["宗教信仰"],"yearUnknown":false,"summary":"迷你小廟藏著64幅薛仁貴東征黑白連環壁畫","intro":"前埔保障宮位於烈嶼鄉上林村前埔聚落，主祀玄天上帝，並奉祀三太公、太子爺、註生娘娘及福德正神。相傳廟宇最早起建於明代，民國20年代曾修建，後受砲擊毀損，民國58年（1969）重修，壁畫彩繪委由烈嶼匠師林天助負責。廟寬僅約4公尺、長約5.4公尺，室內卻滿布黑白壁畫：兩側牆面各四列、每列八幅，共64幅，以薛仁貴東征為主題，另有八仙、門神、南極仙翁與麻姑等。這種連環畫式壁畫又稱「女兒圖」，由村內女兒、女婿分擔重建經費，並把捐獻者姓名寫在圖上。民國108年（2019）完成建築與壁畫修復。","highlights":["兩面牆共64幅的薛仁貴東征連環壁畫","寫有捐獻女兒、女婿姓名的「女兒圖」","大門兩側古樸的圓形竹節窗"],"funFact":"林天助沒有拜師學藝，靈感來自章回小說，直接以黑墨在灰壁上作畫，是戰地前線自學而成的畫風。","photoSpot":"在廟門前拍竹節窗與「保障宮」牌匾","visitMin":15,"openNote":"位於烈嶼鄉上林村前埔聚落，為地方廟宇，參觀請保持安靜、尊重祭祀，壁畫請勿觸摸或使用閃光燈。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，這間廟好迷你喔，我張開手臂差不多就碰到兩邊牆了！"},{"who":"A","text":"有點誇張，不過真的小，寬大約4公尺。但一進門抬頭，你就會被滿牆的黑白壁畫嚇一跳。"},{"who":"R","text":"哇，一格一格的，好像在看古代漫畫！"},{"who":"A","text":"就是連環畫！兩面牆各四列、每列八幅，一共64幅，講的是薛仁貴東征的故事。"},{"who":"R","text":"這是誰畫的呀？也太有耐心了吧！"},{"who":"A","text":"烈嶼匠師林天助，他沒拜過師，靈感來自章回小說，民國58年重修時畫下這些作品。"},{"who":"R","text":"自學成才耶！那為什麼又叫「女兒圖」？"},{"who":"A","text":"因為修廟經費由村裡的女兒和女婿分擔，名字就寫在畫上，等於一份會說故事的感謝狀。"},{"who":"A","text":"進廟記得放輕腳步，找找看壁畫上寫著捐獻者名字的地方，想想他們和村子的緣分。"}],"clues":["我的牆上有64格黑白連環壁畫","我身上的壁畫又叫「女兒圖」，寫著出資者的名字","我是小金門前埔聚落主祀玄天上帝的小廟"],"quiz":[{"q":"前埔保障宮連環壁畫的故事主題是？","options":["孫臏鬥龐涓","封神演義","西遊記","薛仁貴東征"],"answer":3,"explain":"兩面牆共64幅，以薛仁貴東征為主題。"},{"q":"「女兒圖」這個名稱的由來是？","options":["畫的都是女神","由女兒女婿出資修廟","由女畫師繪製","為女兒出嫁祈福"],"answer":1,"explain":"村內女兒、女婿分擔經費，姓名寫在連環圖上。"}],"images":[{"file":"金門烈嶼保障宮中距離.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/%E9%87%91%E9%96%80%E7%83%88%E5%B6%BC%E4%BF%9D%E9%9A%9C%E5%AE%AE%E4%B8%AD%E8%B7%9D%E9%9B%A2.jpg/960px-%E9%87%91%E9%96%80%E7%83%88%E5%B6%BC%E4%BF%9D%E9%9A%9C%E5%AE%AE%E4%B8%AD%E8%B7%9D%E9%9B%A2.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E7%83%88%E5%B6%BC%E4%BF%9D%E9%9A%9C%E5%AE%AE%E4%B8%AD%E8%B7%9D%E9%9B%A2.jpg","artist":"陳辰鈺","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/lieyu-qianpubaozhanggong-0.webp","small":"img/lieyu-qianpubaozhanggong-0-s.webp"}]},{"id":"jincheng-guquchenshijiamiao","name":"古區陳氏家廟","short":"古區陳氏家廟","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.41005,"lng":118.31295,"address":"金門縣金城鎮古區21號","announced":"2016-12-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20170126000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-17/7d0b6edb-3652-4ed0-8fba-4f5a52aa8d6b/古區陳氏家廟.jpg","year":1622,"yearText":"明末（約1620年代，推測於陳昌文中進士後興建）","era":"dutch","themes":["宗祠家廟"],"yearUnknown":false,"summary":"紀念明末進士陳昌文、歷經砲戰重建的家廟","intro":"古區陳氏家廟位於金城鎮古區聚落，古區是陳姓單姓村。族譜記載明朝末年已建有祖厝，推測是八世祖陳昌文在天啟2年（1622）考中進士後，家族興建宗祠以凝聚向心力。陳昌文曾任廣西平樂推官、刑科給事中，家廟內「諫垣大臣」匾指的就是他。家廟1924年翻修；1954年九三砲戰期間，村裡國軍彈藥庫爆炸，全村房屋幾乎全倒，並有村民罹難，家廟也遭波及而重建。1984年修繕時正廳改為鋼筋混凝土仿木，2021至2023年整修時又改回傳統木棟架。石台基、柱與石鼓仍是早期原物，內牆畫有二十四孝故事。","highlights":["榻受牆面的二十四孝彩磁","第一進門口的石鼓與早期地坪石材","2023年改回傳統木構的三通五瓜棟架"],"funFact":"1984年修繕時棟架改成鋼筋混凝土仿木，2023年整修完成後又改回傳統木棟架。","photoSpot":"前埕拍二落翹脊與榻受木雕","visitMin":15,"openNote":"位於金城鎮古區聚落，宗族家廟，平日多不開放，請在外觀參觀，勿擅入；祭祖時請勿打擾。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，古區這個村子裡，為什麼大家都姓陳啊？"},{"who":"A","text":"古區是陳姓單姓村。族譜說600多年前，祖先從漳州南院遷來，後來分成好幾房。"},{"who":"R","text":"那這座陳氏家廟是什麼時候蓋的？"},{"who":"A","text":"族譜記載明朝末年就有祖厝，推測是八世祖陳昌文1622年考上進士，家族引以為榮才蓋了宗祠。"},{"who":"R","text":"考上進士就蓋祠堂，那我考一百分可以蓋個樹屋嗎？"},{"who":"A","text":"先考到再說！陳昌文後來當上給事中，裡面那塊諫垣大臣的匾額，說的就是他。"},{"who":"A","text":"不過家廟也經歷過傷痛。1954年九三砲戰期間，村裡的彈藥庫爆炸，全村房屋幾乎全倒，也有村民不幸罹難。"},{"who":"R","text":"那真的是很沉重的一段歷史，家廟後來是重新蓋起來的嗎？"},{"who":"A","text":"對，之後多次重修。請你看看榻受牆上的二十四孝彩磁，找找自己認得的那一個故事。"}],"clues":["我所在的村子是陳姓單姓村","我的匾額「諫垣大臣」說的是明末一位進士","1954年九三砲戰時村裡彈藥庫爆炸，我也受損重建"],"quiz":[{"q":"家廟內「諫垣大臣」匾指的是哪位先人？","options":["陳顯","陳光求","陳昌文","陳健"],"answer":2,"explain":"諫垣大臣指的是八世祖、明天啟進士陳昌文。"},{"q":"2021至2023年整修時，正廳棟架有什麼改變？","options":["改回傳統木棟架","改為鋼筋混凝土仿木","改為鋼骨結構","改為花崗石樑柱"],"answer":0,"explain":"整修時將全區棟架改回傳統木棟架系統。"}],"images":[]},{"id":"jincheng-shuitouwangshigu","name":"水頭王氏古厝","short":"水頭王氏古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41133,"lng":118.29608,"address":"金門縣金城鎮前水頭108號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000040","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-27/91242268-016e-4e16-a782-3926d22f83cc/(1)封面.jpg","year":1650,"yearText":"約17世紀中葉（明末清初）始建，1943年前後擴建","era":"dutch","themes":["閩南古厝"],"yearUnknown":false,"summary":"明末清初老厝，前有照壁與龍眼樹","intro":"水頭王氏古厝位於金城鎮水頭聚落，原為明末清初的建築，當時只有後落。1943、1944年間，屋主王成南隨父親赴印尼經營雜貨生意後，攜母親返回金門，修補殘破的後落並加建前落，成為今日的二落大厝。古厝前有斗砌「凸」字型照壁擋住巷沖，旁邊伴著一棵枝葉濃密的龍眼樹，前埕形成族人聚會的舒適空間。每年農曆七月十八日水頭普渡，這裡也是聚落內設醮的八處之一。門楣高掛「太原衍派」匾額，榻受身堵繪有八仙器物，寓意吉祥長壽。","highlights":["開有花窗的「凸」字型斗砌照壁","門楣上的「太原衍派」匾額","榻受身堵的卍字紋與八仙器物彩繪"],"funFact":"照壁可擋住巷子直衝而來的「巷沖」，龍眼樹提供遮蔭，讓前埕成為族人聚會處。","photoSpot":"在照壁旁拍龍眼樹與古厝正面","visitMin":10,"openNote":"位於金城鎮水頭聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車到水頭。","dialogue":[{"who":"R","text":"Allan，這間古厝前面為什麼要擋一面牆？是怕人家偷看嗎？"},{"who":"A","text":"那叫照壁，用來擋住巷子直衝過來的巷沖，旁邊還有一棵龍眼樹幫忙遮太陽。"},{"who":"R","text":"牆加大樹，簡直是天然的冷氣客廳耶！"},{"who":"A","text":"對，族人以前就在前埕聚會聊天。這間王氏古厝原本是明末清初的老房子，當時只有後落。"},{"who":"R","text":"那前面這一落是後來才長出來的嗎？"},{"who":"A","text":"1943年前後，王成南從印尼回來，把破舊的後落修好，又加蓋前落，變成二落大厝。"},{"who":"R","text":"等於幫老房子加了一個前院和玄關，好孝順的房子。"},{"who":"A","text":"每年農曆七月十八日水頭普渡，這裡還是聚落設醮的八個地點之一，地位不簡單。"},{"who":"A","text":"請在屋外抬頭找找門楣上的「太原衍派」匾額，再數一數照壁上開了幾扇花窗！"}],"clues":["我前面有一座開花窗的凸字型照壁和一棵龍眼樹","我原是明末清初的老屋，1943年前後才加建前落","我是水頭聚落的二落大厝，門楣掛「太原衍派」"],"quiz":[{"q":"古厝前的照壁主要作用是什麼？","options":["擋住巷沖","曬穀子","張貼告示","防止颱風"],"answer":0,"explain":"照壁阻擋巷沖，讓前埕成為內聚空間。"},{"q":"水頭普渡在每年農曆哪一天？","options":["正月十五日","七月十八日","八月二十三日","十月十五日"],"answer":1,"explain":"每年農曆七月十八日水頭普渡，此處設醮。"}],"images":[]},{"id":"lieyu-linshiliuludacuo","name":"林氏六路大厝","short":"林氏六路大厝","category":"歷史建築","level":"","town":"烈嶼鄉","types":["宅第"],"lat":24.43539,"lng":118.23789,"address":"金門縣烈嶼鄉西口村西方36號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000027","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-22/579c6d06-1c31-4892-a9ea-b4df56c4f243/1封面.jpg","year":1650,"yearText":"約明末清初","era":"dutch","themes":["閩南古厝","宗祠家廟","風獅爺民俗"],"yearUnknown":false,"summary":"外牆鑲嵌百年風獅爺的林氏祖厝","intro":"林氏六路大厝位於烈嶼鄉西方聚落，約建於明末清初，是林氏祖厝，族人每年農曆10月17日會到祖厝舉行祭祖儀式。建築為一落四櫸頭加雙突歸，又稱「小六路厝」，採硬山擱楹承重牆系統，中軸由牆規樓、深井、巷頭到正廳，深井兩側各有二櫸頭，正廳兩側為房，房外再接突歸。正身與突歸屋脊為翹脊，脊墜以彩繪裝飾，櫸頭為圓脊，整體樸實。牆體右側鑲有一尊百年風獅爺，正廳鏡面牆上緣有卍字不斷紋彩繪，中央置「西河衍派」堂號。民國100年（2011）由金門縣政府補助完成整體修復，並開放民眾參觀。","highlights":["外牆右側鑲嵌的百年風獅爺","正廳「西河衍派」堂號與卍字不斷紋彩繪","一落四櫸頭加雙突歸的「小六路厝」格局"],"funFact":"這座祖厝至今仍是林氏族人凝聚的地方，每年農曆10月17日族人都會回來祭祖。","photoSpot":"在外牆右側拍鑲在牆中的風獅爺","visitMin":15,"openNote":"位於烈嶼鄉西方聚落，為林氏祖厝，依官方資料開放時間依管理人作息而定；請尊重祭祀空間，農曆10月17日祭祖時勿打擾。可經金門大橋開車或騎車前往。","dialogue":[{"who":"A","text":"西方聚落再一站，阿拉蕾，這次不看洋樓，我們來看一座明末清初的老祖厝。"},{"who":"R","text":"明末清初！那不就跟古裝劇裡的房子一樣老？"},{"who":"A","text":"差不多喔，這是林氏六路大厝，林氏族人每年農曆10月17日都會回來祭祖。"},{"who":"R","text":"六路是指房子有六條路可以走嗎？"},{"who":"A","text":"想像力滿分！它是一落四櫸頭再加兩邊突歸，又叫小六路厝，房間左右一路排開。"},{"who":"R","text":"那牆上那個小小的石像是誰？好像在對我笑。"},{"who":"A","text":"那是鑲在牆裡的百年風獅爺，在金門，風獅爺是守護聚落、擋風鎮煞的好夥伴。"},{"who":"R","text":"守了一百年一定很累，要不要請牠吃一碗廣東粥？"},{"who":"A","text":"心意到了就好！到外牆右側找到這尊風獅爺，看看牠的表情是在笑還是在兇。"}],"clues":["我的外牆右側嵌著一尊百年風獅爺","族人每年農曆10月17日回來祭祖","我是小金門西方聚落明末清初的林氏祖厝"],"quiz":[{"q":"林氏族人每年哪一天回祖厝祭祖？","options":["農曆1月15日","農曆7月15日","農曆3月23日","農曆10月17日"],"answer":3,"explain":"族人每年農曆10月17日到祖厝舉行祭祖儀式。"},{"q":"林氏六路大厝外牆右側鑲著什麼？","options":["石敢當","百年風獅爺","八卦鏡","劍獅"],"answer":1,"explain":"牆體右側鑲有一尊百年風獅爺。"}],"images":[]},{"id":"jincheng-houpuwumiao","name":"後浦武廟","short":"後浦武廟","category":"歷史建築","level":"","town":"金城鎮","types":["寺廟"],"lat":24.4331,"lng":118.31674,"address":"金門縣金城鎮莒光路122號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000072","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-26/3cac732e-2912-4eae-99c5-2a93b2881805/封面1.png","year":1652,"yearText":"相傳1652年（明永曆6年）創建","era":"zheng","themes":["宗教信仰"],"yearUnknown":false,"summary":"相傳鄭成功練兵時所建，供奉關聖帝君的內武廟","intro":"後浦武廟位於金城鎮莒光路，在地人稱「內武廟」或「後浦關帝廟」，主祀關聖帝君，並祀關平、周倉，民國後也依各地武廟之例增設岳武穆神位。相傳創建於明永曆6年（1652），是鄭成功在後浦訓練水師時所建，清代曾重建。據《顯影》月刊報導，1925年曾作為公立女學校舍，神像暫移北門上帝宮；1930年在破除迷信風潮中遭毀損。1949年起作為民用物資供應處與稅捐處辦公場所，1983年才歸還武廟管理委員會，1984、1987年重修，以鋼筋混凝土仿木構造成今日面貌。正殿前石階中央的斜面「御路石」是廟中最具特色的古物。","highlights":["正殿臺基前石階中央的斜面「御路石」","門楣上的「聖旨」牌匾與頂堵「武廟」匾","屋脊中央福祿壽三仙與彩龍、鳳凰剪黏"],"funFact":"門楣上掛著「聖旨」牌匾，象徵武廟祭祀曾被清代朝廷列入官方祀典。","photoSpot":"莒光路上拍石獅與屋脊福祿壽剪黏","visitMin":20,"openNote":"位於金城鎮莒光路，官方資料記載上午4:00至下午8:00開放，參拜請遵守廟方規定。從金城車站步行可達，鄰近總兵署與模範街。","dialogue":[{"who":"R","text":"Allan，這間關帝廟為什麼叫內武廟？難道還有外武廟嗎？"},{"who":"A","text":"在地人習慣叫它內武廟，也叫後浦關帝廟。相傳1652年鄭成功在後浦練水師時興建，主祀關聖帝君。"},{"who":"R","text":"鄭成功也來過這裡！那它一直都香火鼎盛嗎？"},{"who":"A","text":"其實很坎坷。1925年它被拿來當女學校舍，神像暫時搬到北門上帝宮，1930年還遭到毀損。"},{"who":"R","text":"連關公都被迫搬家，祂老人家好辛苦喔！"},{"who":"A","text":"1949年以後又當過物資供應處和稅捐處的辦公室，1983年才還給廟方，後來重修成現在的樣子。"},{"who":"R","text":"當過學校又當過稅捐處，這間廟的履歷比Allan還精彩耶！"},{"who":"A","text":"我的履歷只有吃遍金門燒餅啦。廟裡最珍貴的，是正殿前石階中央那塊斜斜的御路石。"},{"who":"A","text":"到現場請找找那塊御路石，再抬頭看看門楣上掛的是什麼牌匾！"}],"clues":["相傳我在1652年因鄭成功練兵而興建","1925年我曾當女學校舍，神像暫移北門上帝宮","我在莒光路，在地人叫我內武廟"],"quiz":[{"q":"後浦武廟正殿前石階中央最有特色的古物是？","options":["石獅","古井","石香爐","御路石"],"answer":3,"explain":"正殿臺基前石階中央的斜面御路石最具特色。"},{"q":"1925年後浦武廟曾被作為什麼使用？","options":["女學校舍","郵局","縣政府","市場"],"answer":0,"explain":"據《顯影》月刊，1925年曾做為公立女學校舍。"}],"images":[{"file":"後浦武廟夜景 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/81/%E5%BE%8C%E6%B5%A6%E6%AD%A6%E5%BB%9F%E5%A4%9C%E6%99%AF_%28cropped%29.jpg/960px-%E5%BE%8C%E6%B5%A6%E6%AD%A6%E5%BB%9F%E5%A4%9C%E6%99%AF_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E5%BE%8C%E6%B5%A6%E6%AD%A6%E5%BB%9F%E5%A4%9C%E6%99%AF_(cropped).jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-houpuwumiao-0.webp","small":"img/jincheng-houpuwumiao-0-s.webp"}]},{"id":"jinhu-chenggongchenshi","name":"成功陳氏宗祠","short":"成功陳氏宗祠","category":"歷史建築","level":"","town":"金湖鎮","types":["祠堂"],"lat":24.43895,"lng":118.39025,"address":"金門縣金湖鎮成功64-1號","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-29/75c2cc92-a820-4b3c-83e4-4d7625ea4caa/01封面.jpg","year":1689,"yearText":"1689年（清康熙28年）始建","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"全村出力重建的陳坑大宗祠","intro":"成功陳氏宗祠位於金湖鎮成功村，成功舊稱陳坑。宗祠始建於1689年（清康熙28年），原為二進，又稱「北方祠堂」，是陳氏的大宗宗祠。1755年重修時因經費拮据改為一進；1963年族人決議恢復二進，村內按丁口出資並向海外族僑募款，村中16到50歲男丁每人義務做工7天，1965年完工。2011年由縣府補助整體修復，2013年竣工。前落屋頂採三川脊，屋脊中央飾八仙，兩端有金門宗祠特有的上釉陶製龍隱；大門前有抱鼓石，兩側青斗石圓窗題「鴻基丕振」「祖德流芳」，正廳懸「永言孝思」匾。","highlights":["屋脊中央的八仙剪黏與兩端上釉陶製龍隱","青斗石圓窗上的「鴻基丕振」「祖德流芳」橫批","東廳牆上的〈浯邑陳坑陳氏宗祠重建落成誌〉"],"funFact":"1960年代重建時，村裡16到50歲的男丁每人義務做工7天，是全村一起蓋起來的祠堂。","photoSpot":"在宗祠外埕拍三川脊與抱鼓石","visitMin":15,"openNote":"位於金湖鎮成功村。宗族祭祀場所，官方資料未載開放時間；大門未開時請在外觀參觀，遇祭祀活動請保持肅靜、勿干擾。","dialogue":[{"who":"A","text":"阿拉蕾，成功村以前叫陳坑，這座陳氏宗祠，是全村陳姓族人的大宗祠堂。"},{"who":"R","text":"大宗祠堂？意思是陳家的總部嗎？"},{"who":"A","text":"可以這樣理解。它在1689年清康熙28年就開始蓋，當時是兩進，大家也叫它「北方祠堂」。"},{"who":"R","text":"那它從清代到現在一直都長這樣嗎？"},{"who":"A","text":"沒有喔，清乾隆年間重修時錢不夠，只好縮成一進。到了1963年，族人才決定恢復成兩進。"},{"who":"R","text":"縮水又長回來，好像我的毛衣洗了又拉回去！"},{"who":"A","text":"比喻很傳神！當時村裡16到50歲的男生，每人要義務來做工7天，海外族親也捐錢，大家一起把祠堂蓋起來。"},{"who":"R","text":"全村總動員，這才是真正的團隊合作！"},{"who":"A","text":"請你抬頭看屋脊，中央站著八位仙人，兩端還有金門宗祠特有的龍隱，數數看八仙有沒有到齊。"}],"clues":["我曾因經費拮据從二進縮成一進，後來又恢復二進","1960年代重建時，全村男丁每人義務做工7天","我是舊稱陳坑的村子裡，清康熙年間始建的大宗祠"],"quiz":[{"q":"成功村的舊稱是什麼？","options":["陳坑","下坑","碧湖","平林"],"answer":0,"explain":"成功舊稱陳坑，東廳碑記即題〈浯邑陳坑陳氏宗祠重建落成誌〉。"},{"q":"1755年重修時，宗祠為什麼從二進改為一進？","options":["颱風損毀","經費拮据","道路拓寬","戰火波及"],"answer":1,"explain":"清乾隆20年再次修建時，因經濟拮据改為一進。"}],"images":[]},{"id":"jincheng-yipinfurenlanmen","name":"一品夫人藍門翁氏墓","short":"藍門翁氏墓","category":"歷史建築","level":"","town":"金城鎮","types":["墓葬"],"lat":24.40237,"lng":118.3171,"address":"金門縣金城鎮珠山段197地號","announced":"2010-01-12","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20100112000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-06-27/fc960f72-56df-4fbf-9d5b-9decc8498283/代表圖片.jpg","year":1697,"yearText":"1697年（清康熙36年）遷葬","era":"qing","themes":["墓葬"],"yearUnknown":false,"summary":"清初名將藍理為曾祖母遷葬的一品夫人墓","intro":"這座墓位於金城鎮珠山與古崗之間的後山（又名鳳髻山）。墓主藍門翁氏是藍氏第九世藍孔頫的元配，生於明嘉靖32年（1553），22歲即過世，原葬於大陸，清康熙36年（1697）由曾孫藍理、藍瑗等人遷葬金門。藍理曾以參將身分隨施琅平定臺灣，後歷任多地總兵與福建陸路提督，翁氏因此被誥封「一品夫人」。藍理與藍廷珍、藍鼎元後人稱「藍氏三傑」。墓為夯土墓塋，形制古樸，碑文刻有「康熙丁丑年孟夏穀旦」等字，是藍氏一門在金門唯一的歷史證物。墓前原有石獅旗一對，因戰爭而遭拆除。","highlights":["碑上「誥贈一品夫人」的字樣","碑文列出藍理等曾孫共同立碑","形制古樸的早期夯土墓塋"],"funFact":"墓主22歲就過世，百餘年後因曾孫藍理平臺有功，被誥封為一品夫人。","photoSpot":"在墓埕外側拍墓碑與後山地景","visitMin":15,"openNote":"位於金城鎮珠山與古崗之間的後山，屬戶外墓葬，周邊常有雜草，建議穿長褲與包鞋。請保持尊重，勿攀爬、勿踩踏墓體。可騎機車或開車到珠山、古崗一帶再步行。","dialogue":[{"who":"A","text":"阿拉蕾，今天我們來拜訪一位一品夫人，她的墓就在珠山和古崗之間的後山。"},{"who":"R","text":"一品夫人？聽起來好像古裝劇裡最高等級的貴婦！"},{"who":"A","text":"等級的確很高。不過她22歲就過世了，這個封號是百餘年後，因為曾孫立了大功才得到的。"},{"who":"R","text":"曾孫幫曾祖母爭光？那這位曾孫是誰？"},{"who":"A","text":"他叫藍理，曾隨施琅平定臺灣，當過總兵和福建陸路提督，和藍廷珍、藍鼎元並稱藍氏三傑。"},{"who":"R","text":"藍氏三傑，聽起來好像一個樂團！那墓為什麼在金門？"},{"who":"A","text":"她原本葬在大陸，1697年才由藍理兄弟遷葬到這裡，碑上還刻著兄弟們一起立碑的名字。"},{"who":"R","text":"那墓前有沒有石獅子在守護她呢？"},{"who":"A","text":"原本有一對石獅旗，因為戰爭被拆除了。到現場請保持尊重，在墓埕外看看碑上刻了幾位曾孫的名字。"}],"clues":["我的墓主22歲就過世，卻得到很高的封號","1697年，我被曾孫兄弟從大陸遷葬到金門","墓主的曾孫隨施琅平定臺灣，是藍氏三傑之一"],"quiz":[{"q":"翁氏被誥封一品夫人，是因為哪位曾孫立下戰功？","options":["藍鼎元","藍廷珍","藍理","藍瑗"],"answer":2,"explain":"曾孫藍理隨施琅平定臺灣有功，翁氏獲誥封。"},{"q":"墓前原有的一對石獅旗後來怎麼了？","options":["移到博物館展示","被颱風吹倒","仍完整保存","因戰爭被拆除"],"answer":3,"explain":"墓前原豎石獅旗一對，因戰爭之故已被拆除。"}],"images":[]},{"id":"jinsha-zhangshigucuo3","name":"張氏古厝(沙美102號)","short":"張氏古厝102號","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49207,"lng":118.41245,"address":"金門縣金沙鎮沙美102號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/60b76a48-a583-472f-9a75-76857e0f395c/張氏古厝(沙美102號)_封面.jpg","year":1700,"yearText":"1700年（清康熙39年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"正面貼滿彩磁、官方記載建於康熙年間","intro":"這座張氏古厝位於金沙鎮沙美聚落，官方資料記載創建於清康熙39年（1700），前兩落由屋主家族的曾祖輩興建，第三落則由祖父輩加建。建築可視為三落，以二落為主體，加上右突歸、左護龍與第三落後房群。正面最吸睛的是滿滿的彩色磁磚，榻受牆、對看堵、水車堵、拱仔頭都以磁磚裝飾，前兩落的翹脊脊堵也貼磁磚。第二落鏡面牆門上寫著大字「詩禮傳家」，第三落鏡面窗則有書法聯對。八二三砲戰前國軍曾駐紮十餘年，建築受損，前後整修四次；目前前兩落結構良好，右突歸已塌落。","highlights":["正立面滿布的彩色磁磚裝飾","第二落鏡面牆門上的「詩禮傳家」大字","前兩落翹脊與後房群圓脊的對比"],"funFact":"國軍曾在這裡駐紮十餘年，房子前後整修了四次，才保存成今天的樣貌。","photoSpot":"在前埕正面拍滿牆彩磁","visitMin":10,"openNote":"位於金沙鎮沙美聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"R","text":"哇，Allan，這間古厝正面閃閃發亮，好像貼滿了彩色磁磚！"},{"who":"A","text":"沒錯，榻受牆、對看堵、水車堵通通貼上彩磁，連屋脊都不放過，是沙美古厝裡的時尚達人。"},{"who":"R","text":"這麼新潮，應該是很新的房子吧？"},{"who":"A","text":"官方資料記載它創建於清康熙39年，也就是1700年。前兩落是曾祖輩蓋的，第三落是祖父輩加建的。"},{"who":"R","text":"300多歲還這麼愛打扮，比你還注重外表！"},{"who":"A","text":"我是光頭，打扮很省事。這房子也吃過苦，八二三砲戰前國軍駐紮了十多年，前後整修了四次。"},{"who":"R","text":"修了四次還這麼有精神，這間古厝真是打不倒的老前輩！"},{"who":"A","text":"這裡是私人住宅，在門外欣賞就好。數數看正面貼了幾種不同圖案的彩色磁磚吧！"}],"clues":["我的正面幾乎貼滿了彩色磁磚","官方記載我在清康熙年間誕生","沙美聚落裡，門上寫著「詩禮傳家」的張家古厝"],"quiz":[{"q":"這座古厝正立面最大的裝飾特色是？","options":["木雕門扇","彩色磁磚","交趾陶屋脊","洗石子山頭"],"answer":1,"explain":"榻受牆、對看堵、水車堵、拱仔頭皆以磁磚裝飾。"},{"q":"第二落鏡面牆門上寫著哪四個字？","options":["福星高照","儒林衍派","詩禮傳家","清河衍派"],"answer":2,"explain":"第二落鏡面牆門上方寫有大字「詩禮傳家」。"}],"images":[]},{"id":"jinsha-huangshijiamiao","name":"黃氏家廟","short":"后埔頭黃氏家廟","category":"歷史建築","level":"","town":"金沙鎮","types":["祠堂"],"lat":24.48697,"lng":118.41431,"address":"金門縣金沙鎮后埔頭41號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000017","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-21/c14d576b-8263-4da4-acea-8709175e04cc/01封面.jpg","year":1709,"yearText":"1709年（清康熙48年）","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"康熙年間創建、前埕立「紫雲屏」照壁的二落家廟","intro":"黃氏家廟位於金沙鎮后埔頭聚落，創建於清康熙48年（1709），今日所見規模為清中葉以後重修的樣貌，是一座二落式祖厝，前埕立有「紫雲屏」照壁。民國38年至47年間，國軍師部曾駐紮於此；民國49年（1960）六一七砲戰時，後落遭砲擊損壞，隔年由聚落村人與南洋僑親集資重修，近年又再度整修並完成奠安。前落屋頂為三川脊，後落為雙坡翹脊，大規壁脊墜以交趾陶裝飾蝙蝠、花卉、螭龍與人物等吉祥題材；正廳主神龕上方懸掛「理學正宗」匾，左右神龕則有「文魁」「司馬」匾額。","highlights":["前埕的「紫雲屏」照壁，為家廟增添莊重氣勢","前落三川脊與後落雙坡翹脊的紅瓦屋頂","大規壁上蝙蝠、花卉、螭龍等交趾陶裝飾"],"funFact":"家廟在六一七砲戰中後落受損，隔年由村人和南洋僑親一起出錢修好，可見僑鄉與家鄉的緊密連結。","photoSpot":"站在照壁旁，拍家廟正面與三川脊","visitMin":15,"openNote":"位於金沙鎮后埔頭聚落，為宗族家廟，官方資料未載開放時間，請在外觀參觀，勿擅入；遇祭祀活動請尊重族人。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，來到金沙鎮后埔頭，先別急著進門，你看前埕這面大牆，叫做「紫雲屏」照壁。"},{"who":"R","text":"照壁？是讓祖先出門前照鏡子、整理儀容用的嗎？"},{"who":"A","text":"哈，不是啦！照壁立在家廟正前方，像一座大屏風，讓整個空間更莊重，有點像家廟的玄關。"},{"who":"R","text":"原來是玄關！那這間家廟幾歲了？"},{"who":"A","text":"清康熙48年，也就是1709年創建，現在看到的前後兩落，是清中葉以後重修的樣子。"},{"who":"R","text":"300多歲還這麼有精神，保養祕訣是什麼？"},{"who":"A","text":"靠族人一代代守護。民國49年六一七砲戰時後落被砲擊損壞，隔年村人和南洋僑親一起集資修好。"},{"who":"R","text":"好感人！那屋脊旁邊五顏六色的小裝飾又是什麼？"},{"who":"A","text":"那是交趾陶，有蝙蝠、花卉、螭龍和人物，都是吉祥寓意。在外面數數看，你能找到幾隻蝙蝠？"}],"clues":["國軍師部曾在我這裡駐紮將近10年","我前埕立著一面名叫「紫雲屏」的照壁","我是金沙鎮后埔頭黃姓族人的二落祖厝"],"quiz":[{"q":"家廟前埕那面照壁叫什麼名字？","options":["青雲壁","紫雲屏","朝天屏","瑞雲牆"],"answer":1,"explain":"前埕立有「紫雲屏」照壁，是家廟的重要特色。"},{"q":"民國49年哪一場砲戰讓家廟後落受損？","options":["九三砲戰","八二三砲戰","古寧頭戰役","六一七砲戰"],"answer":3,"explain":"民國49年六一七砲戰時後落遭砲擊損壞，隔年重修。"}],"images":[]},{"id":"lieyu-hongshigucuo","name":"洪氏古厝","short":"青岐洪氏古厝","category":"歷史建築","level":"","town":"烈嶼鄉","types":["宅第"],"lat":24.41397,"lng":118.22784,"address":"金門縣烈嶼鄉青岐16、16-3號","announced":"2006-11-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061109000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2023-02-14/6e42b4dd-9bcb-4db6-9ce9-de376be41e80/1.洪氏古厝.jpg","year":1730,"yearText":"約1720–1730年代（清雍正年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"廳房多達33間的二落三護龍大宅","intro":"洪氏古厝位於烈嶼鄉青岐聚落，青岐是「青岐洪氏」的發祥地。據族譜記載，始遷祖洪十七郎於南宋淳熙元年（1174）任同安縣尉，其孫裕庵避居烈嶼，成為青岐開基祖。此宅約於清雍正年間落成，原計畫興建三落大厝，因資金不足先建二落，後隨家族人丁興旺陸續增建護龍與突歸，形成金門少見的二落三護龍規模，廳與房多達33間。外牆下緣多以花崗石或烈嶼黑色玄武岩亂石砌，前落對看堵以煙炙磚組砌出仿窗櫺紋樣，門箱石雕卍字，腳踏石與櫃台腳有獸足雕飾。民國38年至47年曾有一整連官兵暫住，民國111年（2022）完成修復。","highlights":["金門少見的二落三護龍、33間廳房規模","前落以煙炙磚組砌的仿窗櫺對看堵","大量使用烈嶼黑色玄武岩的牆基"],"funFact":"原本打算蓋三落大厝，因資金不足先蓋兩落，後來人丁興旺，一路加蓋到33間廳房。","photoSpot":"在前埕拍對看堵與黑色玄武岩牆基","visitMin":15,"openNote":"位於烈嶼鄉青岐聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可經金門大橋開車或騎車前往。鄰近青岐蘭亭別墅。","dialogue":[{"who":"R","text":"Allan，這座古厝也太大了吧！我數到一半就數不清有幾間了。"},{"who":"A","text":"別數了，答案是33間廳房！這是青岐的洪氏古厝，二落大厝帶三條護龍，在金門很少見。"},{"who":"R","text":"33間！是不是一開始就計畫要蓋這麼大？"},{"who":"A","text":"剛好相反，原本想蓋三落大厝，錢不夠只先蓋兩落，後來家族人丁興旺，才一路往旁邊加蓋。"},{"who":"R","text":"原來是家族越長越大，房子也跟著長大，根本是成長紀錄片。"},{"who":"A","text":"形容得好！它大約在清雍正年間落成，青岐這裡本來就是青岐洪氏的發祥地。"},{"who":"R","text":"那古厝牆腳那些黑黑的石頭是什麼？"},{"who":"A","text":"那是烈嶼在地的黑色玄武岩，配上花崗石和紅磚，顏色層次很豐富。在屋外找找看，哪一面牆的黑石頭最多？"}],"clues":["我原本想蓋三落，錢不夠只先蓋了兩落","我有33間廳房，是少見的二落三護龍","我是小金門青岐聚落洪姓族人的大宅"],"quiz":[{"q":"這座古厝的廳與房一共有幾間？","options":["18間","24間","33間","45間"],"answer":2,"explain":"陸續增建後，廳與房多達33間。"},{"q":"古厝牆基大量使用的烈嶼在地石材是？","options":["黑色玄武岩","珊瑚礁石","砂岩","大理石"],"answer":0,"explain":"外牆下緣多以花崗石或烈嶼黑色玄武岩砌成。"}],"images":[]},{"id":"jincheng-huanghuigucuo","name":"黃輝古厝","short":"黃輝古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41039,"lng":118.29626,"address":"金門縣金城鎮前水頭110號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000041","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-27/83e35db6-a62f-4287-b9e4-be908b13920a/黃輝古厝01.png","year":1736,"yearText":"1736年（清乾隆元年）","era":"qing","themes":["閩南古厝","聚落地景"],"yearUnknown":false,"summary":"乾隆元年興建，門前還留著半月池的雙落大厝","intro":"黃輝古厝位於金城鎮水頭聚落，建於清乾隆元年（1736），興建人黃輝是清乾隆時期前往內陸「北碇」發展的前水頭人。古厝為雙落大厝加雙護龍及牆規門，左護龍不包在牆規之內，屋前保留一座半月池，是當地早期民宅的地域特色。大厝屋面為紅瓦翹脊，護龍則為圓脊；正立面的榻受牆、對看堵與拱仔頭以磁磚裝飾，後落鏡面格扇以花邊造型收尾。官方調查指出大厝本體結構大致良好，但右護龍木構造遭蟲蛀、屋頂破損，左護龍牆面也有滲漬裂損，有待修復。","highlights":["古厝前方的半月池，展現早期民宅配置","以磁磚裝飾的榻受牆、對看堵與拱仔頭","左護龍後側連接的弧形圍牆"],"funFact":"這棟古厝的左護龍沒有被圍進牆規之內，配置與一般雙護龍大厝不太一樣。","photoSpot":"站在半月池邊拍大厝倒影與紅瓦翹脊","visitMin":10,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；護龍有損壞，請勿靠近。可從金城車站搭公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這棟古厝前面怎麼有一個半圓形的水池？是給鴨子游泳的嗎？"},{"who":"A","text":"那叫半月池啦，是古厝前面的配置，也是這棟黃輝古厝最有辨識度的地方。"},{"who":"R","text":"那它到底幾歲了？看起來比你還要有歷史感耶。"},{"who":"A","text":"謝謝你喔。它建於清乾隆元年，也就是1736年，起造人黃輝是到內陸北碇發展的前水頭人。"},{"who":"R","text":"快三百歲了！那它身上還有什麼特別的地方？"},{"who":"A","text":"它是雙落大厝加雙護龍，可是左護龍沒有被包進牆規裡，正面還用磁磚裝飾榻受牆和拱仔頭。"},{"who":"R","text":"可是我聽說右邊的護龍被蟲蟲咬得很慘，屋頂也破了，好可憐。"},{"who":"A","text":"對，蟲蟻比我吃蚵仔麵線還兇，所以要盡快修復。請你在池邊找找，倒影裡看得到幾段翹脊？"}],"clues":["我建於清乾隆元年，起造人曾到內陸北碇發展","我的左護龍沒有被圍進牆規之內","我在水頭聚落，門前還保留一座半月池"],"quiz":[{"q":"黃輝古厝建於哪一年？","options":["1736年","1796年","1836年","1866年"],"answer":0,"explain":"古厝建於清乾隆元年，也就是1736年。"},{"q":"黃輝古厝前方保留了什麼特色景觀？","options":["一座石牌坊","一對風獅爺","一口八角井","一座半月池"],"answer":3,"explain":"古厝前仍保留半月池，展現當地民宅的地域風貌。"}],"images":[]},{"id":"jincheng-shizetang","name":"世澤堂（黃氏小宗宗祠）","short":"世澤堂","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.41112,"lng":118.29686,"address":"金門縣金城鎮前水頭88、88-1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000017","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/c8682b88-f4cb-4444-bf30-9781f25641a1/01封面.jpg","year":1760,"yearText":"1760年（清乾隆25年）","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"漳州富商黃汝標出資、石雕講究的水頭宗祠","intro":"世澤堂是水頭黃氏小宗宗祠，位於金城鎮水頭聚落中界。水頭黃氏開基祖黃輔為宋末進士，元代隱居浯洲，後裔稱「金水黃氏」。清乾隆年間，漳州長房黃汝標家資百萬，先在1743年出資重修黃氏大宗祠後落，又於乾隆25年（1760）興建這座小宗祠。建材選用福州杉木與泉州花崗石，相傳工匠鑿下一斗石粉就能換一斗銀兩。建築為兩落加左右護龍，正立面大量使用石構造，前檐以石作出屐支撐，屬漳州式做法；前有照壁題「紫雲屏」。祠堂曾於1921、1985、2017年整修，每年上元與冬至次日祭祖。","highlights":["照壁上題的「紫雲屏」三個字","前檐石作出屐與石斗栱的漳州式做法","兩側青斗石雕圓窗與大門石鼓"],"funFact":"傳說世澤堂興建時要求精雕細琢，工匠鑿下一斗石粉，就能換到一斗銀兩。","photoSpot":"照壁前拍石構正立面與門前石鼓","visitMin":15,"openNote":"位於金城鎮水頭聚落中界，宗族祠堂，平時供宗親祭祖集會，兩側廂房有人居住。請在外觀參觀，勿擅入、勿打擾住戶。水頭聚落鄰近水頭碼頭，可騎機車或開車前往。","dialogue":[{"who":"A","text":"來猜個謎，一斗石粉可以換什麼？答案就藏在水頭這座世澤堂。"},{"who":"R","text":"一斗石粉？應該只能換到一個白眼吧！"},{"who":"A","text":"傳說這裡興建時要求精雕細琢，工匠鑿下一斗石粉，就能換一斗銀兩，雕得越細賺越多。"},{"who":"R","text":"哇，那工匠一定雕到手軟！是誰這麼有錢？"},{"who":"A","text":"出資的是漳州長房的黃汝標，族人形容他家資百萬。他在1760年蓋了這座黃氏小宗宗祠。"},{"who":"R","text":"住在漳州還回金門蓋祠堂，真的很念舊耶。"},{"who":"A","text":"因為水頭是金水黃氏的根。他選了福州杉木和泉州花崗石，連前檐都用石頭出屐撐起來，是漳州式做法。"},{"who":"R","text":"用石頭撐屋簷，聽起來超堅固的！"},{"who":"A","text":"到照壁前找找紫雲屏三個字，再看看大門口的石鼓上雕了什麼花紋吧！"}],"clues":["相傳蓋我時，一斗石粉能換一斗銀兩","1760年，一位家資百萬的漳州族人出資興建我","我是水頭黃氏小宗宗祠，照壁題著紫雲屏"],"quiz":[{"q":"世澤堂照壁上題的是哪幾個字？","options":["紫雲屏","指日高陞","金水第一","世澤綿長"],"answer":0,"explain":"世澤堂前方照壁上書「紫雲屏」三字。"},{"q":"世澤堂前檐以石作出屐支撐，屬於哪一種做法？","options":["泉州式","福州式","漳州式","廣東式"],"answer":2,"explain":"前檐以石作出屐為支承，屬漳州式做法。"}],"images":[]},{"id":"jincheng-zhushandadaogong","name":"珠山大道宮","short":"珠山大道宮","category":"歷史建築","level":"","town":"金城鎮","types":["寺廟"],"lat":24.401864,"lng":118.320617,"address":"金門縣金城鎮珠山68號","announced":"2009-06-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090603000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-20/25154ae7-8129-4e73-9565-ff6e2ffcd08f/珠山大道宮.jpg","year":1761,"yearText":"清乾隆年間（現存1761年石香爐）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"珠山的「西宮」，供奉保生大帝與竹杯爺","intro":"珠山大道宮位於金城鎮珠山聚落圭峰西方，地方稱「西宮」，主祀保生大帝，並祀註生娘娘、福德正神、軍將爺及竹杯爺。創建年代已不可考，相傳海盜來襲時保生大帝顯靈護村，村民立廟供奉。珠山《顯影月刊》記載約建於清乾隆37年（1772），但宮內石香爐刻有乾隆辛巳年（1761）字樣。清嘉慶12年（1807）薛懋濟倡修，同治12年（1873）再修。1949年曾被國軍徵用為中山室，1958年受砲戰損壞，之後多次修復，2013年完成整修。建築為二落加右護龍，中央有捲棚拜亭。","highlights":["宮內刻有乾隆辛巳年字樣的石香爐","龍虎井牆面的龍、虎泥塑","四點金柱的圓盤式石柱礎"],"funFact":"右護龍叫「息仔室」，是讓戲班人員休息、停放神轎的地方。","photoSpot":"在廟埕拍屋脊剪黏與「開浯 大道宮」匾","visitMin":15,"openNote":"位於金城鎮珠山聚落，為地方信仰中心，開放民眾參拜，開放時間依廟方安排；參觀請保持安靜、尊重祭祀。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"珠山人說的「西宮」就是這裡，主祀保生大帝，大家都暱稱祂大道公。"},{"who":"R","text":"大道公我知道，是很會看病的醫神！那旁邊的竹杯爺是誰？"},{"who":"A","text":"竹杯爺是副祀神明之一，和軍將爺一起陪祀，名字聽起來就很接地氣吧。"},{"who":"R","text":"這間廟是什麼時候蓋的？有幾百歲了嗎？"},{"who":"A","text":"創建年代已不可考，傳說海盜來襲時大道公顯靈護村，村民才蓋廟。宮裡有一座1761年的石香爐。"},{"who":"R","text":"哇，香爐比廟的出生證明還可靠。"},{"who":"A","text":"1958年砲戰時廟也受損，之後村民一次次出錢修復，2013年才整修完成，很不容易。"},{"who":"R","text":"那右邊那排房間是做什麼的？給神明當宿舍嗎？"},{"who":"A","text":"那叫息仔室，給戲班休息、停神轎用。請你在龍虎井找找看，龍和老虎各在哪一邊！"}],"clues":["我右邊的息仔室，是戲班休息和停神轎的地方","我宮裡有一座刻著乾隆辛巳年的石香爐","我是珠山的「西宮」，主祀保生大帝"],"quiz":[{"q":"珠山大道宮主祀哪一位神明？","options":["媽祖","關聖帝君","保生大帝","觀音菩薩"],"answer":2,"explain":"大道宮主祀保生大帝，俗稱大道公。"},{"q":"大道宮右護龍的「息仔室」原本做什麼用？","options":["存放族譜","戲班休息與停放神轎","私塾教室","儲存糧食"],"answer":1,"explain":"息仔室供戲班人員休息與神轎停放。"}],"images":[{"file":"金門珠山大道宮 2019.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/93/%E9%87%91%E9%96%80%E7%8F%A0%E5%B1%B1%E5%A4%A7%E9%81%93%E5%AE%AE_2019.jpg/960px-%E9%87%91%E9%96%80%E7%8F%A0%E5%B1%B1%E5%A4%A7%E9%81%93%E5%AE%AE_2019.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E7%8F%A0%E5%B1%B1%E5%A4%A7%E9%81%93%E5%AE%AE_2019.jpg","artist":"Gloria2199","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-zhushandadaogong-0.webp","small":"img/jincheng-zhushandadaogong-0-s.webp"}]},{"id":"jincheng-huangshaoguangzhai","name":"黃紹光宅","short":"黃紹光宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40919,"lng":118.30048,"address":"金門縣金城鎮前水頭9號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000034","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/8ef91cd2-80ae-49f1-be44-f53b4ba94ee6/01封面.jpg","year":1765,"yearText":"約1765年（清乾隆30年）","era":"qing","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"水頭「頂界十八支樑」之一的乾隆年間二落大厝","intro":"黃紹光宅位於金城鎮水頭聚落的頂界，是「頂界十八支樑」建築群之一。清乾隆30至31年（1765～1766）間，水頭黃氏長房小宗派族人赴錦州、杭州經營南北貨與絲綢致富，返鄉後各自出資、聘請匠師，興建九棟二落大厝，每棟兩支樑、共十八支，並擇同一良辰上樑，因而有此美稱。黃紹光（1755～1812）十六歲中秀才，曾構築書齋「卓齋」供子孫讀書，也在後浦街開店。宅第為二落大厝加左護龍及牆規樓，1949年至1954年間曾有國軍進駐，部分門板與小木作因而遭拆取。","highlights":["牆規樓木板門上書寫的「十八」與「華宅」字樣","對看堵抹灰勾線的卍字不斷紋與山水彩繪拱仔頭","左護龍過水門旁的螭龍團爐圓窗"],"funFact":"族譜形容當年盛況是「洋船十八艘，錢銀壓折樓椽」，九棟大厝擇同一良辰上樑十八支。","photoSpot":"在前埕拍牆規樓與寫著「十八」的門板","visitMin":15,"openNote":"位於金城鎮水頭聚落頂界。官方資料記載開放時間依民宿營業時間，部分古厝修復後作為民宿使用；非住宿旅客請在外觀參觀，勿擅入、勿打擾住戶。可從金城車站搭公車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，水頭頂界這排整整齊齊的大厝，有個很霸氣的外號，叫做「十八支樑」。"},{"who":"R","text":"十八支樑？是十八個人一起扛屋頂嗎？聽起來好像武俠片裡的陣法！"},{"who":"A","text":"沒那麼熱血啦。清乾隆30年前後，也就是1765年，黃氏族人到錦州、杭州做南北貨和絲綢生意發了財。"},{"who":"R","text":"賺了錢就回家蓋房子，金門人好像都很愛這一套耶！"},{"who":"A","text":"他們一口氣蓋了九棟二落大厝，每棟兩支樑，九棟就是十八支，還挑同一個良辰一起上樑。"},{"who":"R","text":"九乘二等於十八，這題數學我會！那黃紹光又是誰？"},{"who":"A","text":"他十六歲就中秀才，還蓋了書齋卓齋給子孫讀書，在後浦街也開店，是會讀書又會做生意的人。"},{"who":"R","text":"十六歲中秀才？我十六歲大概只會準時中午吃飯吧。"},{"who":"A","text":"那等一下我請你吃廣東粥。到現場請找找牆規樓的木板門，上面寫著哪兩組字？"}],"clues":["起造我的族人曾到錦州、杭州做南北貨與絲綢生意","宅名裡的人十六歲中秀才，還蓋過書齋卓齋","我在水頭頂界，牆規樓門板寫著「十八」「華宅」"],"quiz":[{"q":"「頂界十八支樑」的「十八」指的是什麼？","options":["十八位兄弟合資興建","九棟二落大厝共十八支樑","十八艘洋船的船名","花了十八年才蓋完"],"answer":1,"explain":"九棟二落大厝每棟兩支樑，同一良辰共上樑十八支。"},{"q":"黃紹光為子孫讀書所構築的書齋叫什麼？","options":["酉堂","金水齋","卓齋","浯江書院"],"answer":2,"explain":"黃紹光家有餘裕而構築書齋「卓齋」供子孫學習。"}],"images":[]},{"id":"jinsha-huangchangminggu","name":"黃昌命（納）古厝","short":"黃昌命古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.510984,"lng":118.404411,"address":"金門縣金沙鎮西園57號","announced":"2006-11-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061109000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-23/3635838f-a892-4e9a-94bf-a52b7e8f85e2/黃昌命（納）古厝.jpg","year":1765,"yearText":"清乾隆年間（確切年份不詳）","era":"qing","themes":["閩南古厝","戰地史蹟"],"yearUnknown":false,"summary":"西園鹽商家族的乾隆年間特殊形制大厝","intro":"黃昌命（納）古厝位於金沙鎮西園聚落。西園黃氏在元末明初從南安遷來，起初協助官府闢建鹽田、販鹽，後代又購置田產，成為西園首屈一指的家族。古厝在清乾隆年間由黃昌命（納）興建，與長兄黃昌儀比鄰；父親黃肇基曾捐「正八品修職郎」官銜，仍以鹽田與田產為業。建築形制特殊：左右護厝夾著單開間大廳正身，正面中央為榻受，內部像三蓋廊的敞廳，前後共有八間房。八二三砲戰期間深井遭砲擊，駐軍在大廳內挖掘防空洞；民國60年前後與69年兩度請同村匠師整修，現僅作祭祀與倉儲使用。","highlights":["左右護厝夾單開間正身的特殊格局","左側牆面留下的軍事標語","下堵花崗石平砌、上堵紅磚斗子砌"],"funFact":"西園黃氏祖先初到金門時，是協助官府開闢鹽田、從事販鹽，後來成為西園首屈一指的家族。","photoSpot":"在左側外牆拍軍事標語與磚石牆","visitMin":10,"openNote":"位於金沙鎮西園聚落。私人產權，現作祭祀與倉儲使用，請在外觀參觀，勿擅入。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，西園這一帶以前有鹽田，這座古厝的主人家族，就是靠鹽起家的。"},{"who":"R","text":"靠鹽起家？那他們家煮菜一定都不缺鹽巴！"},{"who":"A","text":"哈哈，應該是。黃家元末明初遷來，先幫官府開鹽田、賣鹽，後來又買了很多田地。"},{"who":"R","text":"那這座古厝是在什麼時候蓋好的呢？"},{"who":"A","text":"清乾隆年間由黃昌命蓋的，跟大哥黃昌儀當鄰居。它的格局很特別，兩邊護厝夾著一個單開間的大廳。"},{"who":"R","text":"跟一般古厝長得不一樣耶，裡面有幾個房間？"},{"who":"A","text":"一共八間房。八二三砲戰時，深井曾遭砲擊，駐軍在大廳裡挖了防空洞，那是一段沉重的日子。"},{"who":"R","text":"原來古厝也經歷過那麼危險的時候。那現在還有人住嗎？"},{"who":"A","text":"現在只作祭祀和倉儲用。我們在外面看，到左側外牆找找，當年留下的軍事標語還看得見嗎？"}],"clues":["我的主人家族靠開鹽田、販鹽起家","我是左右護厝夾著單開間大廳的特殊大厝，共有八間房","西園一座清乾隆年間的古厝，八二三砲戰時大廳挖過防空洞"],"quiz":[{"q":"西園黃氏家族最早以什麼為業？","options":["捕魚","闢鹽田、販鹽","燒製陶瓷","釀酒"],"answer":1,"explain":"黃氏族人初時協助官衙闢建鹽田，並從事販鹽工作。"},{"q":"八二三砲戰期間，駐軍在古厝大廳內做了什麼？","options":["開設理髮店","架設廣播站","挖掘避難防空洞","改建為教室"],"answer":2,"explain":"深井遭砲擊後，軍隊在大廳內挖掘避難防空洞。"}],"images":[]},{"id":"jincheng-xueshidazongzongci","name":"薛氏大宗宗祠","short":"薛氏大宗宗祠","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.40188,"lng":118.32165,"address":"金門縣金城鎮珠山60號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000031","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-28/0415417e-9237-4724-9756-d7e9b0767d0b/01封面.jpg","year":1768,"yearText":"1768年（清乾隆33年）","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"珠山五房總祠，前有大潭後倚山巒","intro":"薛氏大宗宗祠位於金城鎮珠山聚落中軸線上，是開浯始祖薛貞固派下仁、義、禮、智、信五房裔孫的總祠，清乾隆33年（1768）由義房十六世薛繼本、薛道岸等族人倡建。此後於清道光10年、光緒20年，以及1918、1932、1962、2001年多次修建。宗祠為二落，前埕有一對石造旗桿座；前落屋頂為三川脊，翹脊兩端設有龍隱。正立面外側兩扇是青斗石雕圓窗，內側為木造八角窗。大廳掛有「開閩進士」「理學大臣」「御殿總提督」「總戎」等匾額。每年冬至舉行祭祖，祭後以「食頭」宴凝聚宗親感情。","highlights":["前埕的一對石造旗桿座","正立面青斗石雕圓窗與木造八角窗","大廳「開閩進士」「總戎」等族人匾額"],"funFact":"冬至祭祖後的「食頭」宴，是薛氏宗親一年一度凝聚感情的大聚餐。","photoSpot":"在大潭邊拍宗祠正面與燕尾屋脊","visitMin":15,"openNote":"位於金城鎮珠山聚落，為薛氏宗族祭祀場所，官方資料記載每年冬至祭祖；平日請在外觀參觀，祭典期間請勿打擾。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"站在珠山大潭邊往前看，正中間這座就是薛氏大宗宗祠，前有水、後靠山，風水滿分。"},{"who":"R","text":"大宗是什麼意思？是很大一包的意思嗎？"},{"who":"A","text":"哈，是總祠的意思。薛家分成仁、義、禮、智、信五房，大家都回到這裡祭祖。"},{"who":"R","text":"五房的名字好像五顆仁義禮智信的品德小勳章喔！"},{"who":"A","text":"宗祠在1768年清乾隆年間倡建，後來修了好幾次，最近一次是2001年。"},{"who":"R","text":"那五房的宗親什麼時候會全部回來團聚？"},{"who":"A","text":"每年冬至祭祖，祭完還有食頭宴，大家一起吃飯聯絡感情，比我去吃廣東粥還熱鬧。"},{"who":"R","text":"原來祭祖完還有團圓大餐，難怪宗親這麼團結。"},{"who":"A","text":"請你在宗祠外面找找看，正面左右兩邊各有一扇圓形石窗，雕的是什麼圖案？"}],"clues":["我門前有一對石造旗桿座，大廳掛著「總戎」匾","我每年冬至祭祖，祭後辦「食頭」宴","我是珠山薛氏五房的總祠，清乾隆33年倡建"],"quiz":[{"q":"薛氏大宗宗祠是哪幾房裔孫的總祠？","options":["天地玄黃四房","東西南北四房","仁義禮智信五房","金木水火土五房"],"answer":2,"explain":"宗祠為薛貞固派下仁義禮智信五房總祠。"},{"q":"薛氏宗親每年在什麼時候祭祖？","options":["清明節","端午節","中秋節","冬至"],"answer":3,"explain":"每年冬至舉行祭祖，祭後以食頭宴聯誼。"}],"images":[{"file":"DSC0150-1.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/DSC0150-1.jpg/960px-DSC0150-1.jpg","page":"https://commons.wikimedia.org/wiki/File:DSC0150-1.jpg","artist":"Gloria2199","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-xueshidazongzongci-0.webp","small":"img/jincheng-xueshidazongzongci-0-s.webp"}]},{"id":"jincheng-huangjigucuo","name":"黃濟古厝","short":"黃濟古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40985,"lng":118.29973,"address":"金門縣金城鎮前水頭29、29-2號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000033","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/a0c60a81-b957-4739-ba09-15ef4ef8359c/(1)封面.jpg","year":1770,"yearText":"約18世紀（清乾隆年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"「黃百萬」兄長樸素謙卑的故居","intro":"黃濟古厝位於金城鎮水頭聚落，緊鄰前水頭黃氏家廟，是清乾隆年間前水頭富商、人稱「黃百萬」的黃俊之兄黃濟的故居，為水頭黃氏早期的建築之一。原本是二落大厝加前兩櫸頭，因年代久遠後落與兩側櫸頭頹圮，後人撿拾舊料重建前兩櫸頭與牆規樓，形成今日一落四櫸頭加左護龍的格局。正立面以本地花崗石人字砌，轉角為水平聖旨砌，幾乎沒有裝飾，呈現謙卑樸素的民居特色。2004年11月由金門國家公園修復，正身目前作為民宿使用，護龍為一般民居。","highlights":["正立面花崗石人字砌與轉角的聖旨砌","櫸頭外牆上緣的「出磚入瓦」","花崗石門框的牆規樓入口"],"funFact":"弟弟黃俊人稱「黃百萬」，哥哥黃濟的家卻幾乎沒有裝飾，反而顯出謙卑樸素。","photoSpot":"拍花崗石人字砌牆面的紋理","visitMin":10,"openNote":"位於金城鎮水頭聚落黃氏家廟旁。正身修復後作為民宿使用，護龍為一般民居；私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你聽過水頭的黃百萬嗎？"},{"who":"R","text":"一百萬？Allan你中發票了嗎？要請我吃貢糖嗎？"},{"who":"A","text":"想得美！黃百萬是清乾隆年間前水頭的富商黃俊，這棟是他哥哥黃濟的故居。"},{"who":"R","text":"弟弟那麼有錢，哥哥的房子一定金光閃閃、很華麗吧？"},{"who":"A","text":"剛好相反！正面用本地花崗石砌成，幾乎沒有裝飾，官方形容它表現了謙卑的民居特色。"},{"who":"R","text":"低調的有錢人家，這樣反而好有品味。"},{"who":"A","text":"它原本是二落大厝，後落和櫸頭倒塌後，後人撿舊料重建，才成為現在的一落四櫸頭。"},{"who":"R","text":"撿舊料重建，環保又惜物，古人真厲害！"},{"who":"A","text":"請在牆外仔細看，花崗石像人字一樣斜斜排列，轉角卻是平砌，找找兩種砌法的交界在哪裡！"}],"clues":["我是清乾隆年間一位人稱黃百萬的富商哥哥的故居","我的正面以花崗石人字砌，幾乎沒有裝飾","我在前水頭黃氏家廟旁，現為一落四櫸頭加左護龍"],"quiz":[{"q":"人稱「黃百萬」的是誰？","options":["黃濟的弟弟黃俊","黃濟本人","黃廷宙","黃廷參"],"answer":0,"explain":"黃百萬是清乾隆年間前水頭富商黃俊，黃濟是他的兄長。"},{"q":"古厝正立面用什麼砌法？","options":["紅磚斗砌","出磚入瓦","花崗石人字砌","蠣殼灰洗石子"],"answer":2,"explain":"正立面為花崗石人字砌，轉角為水平聖旨砌。"}],"images":[]},{"id":"jincheng-huangjiqigucuo","name":"黃積啟古厝","short":"黃積啟古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40964,"lng":118.29933,"address":"金門縣金城鎮前水頭31號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000036","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/f89feac0-55a0-46f8-9fd5-b6777058cf58/(1)封面.jpg","year":1770,"yearText":"約18世紀（清乾隆年間，推估）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"格局少見的「單伸手」老屋","intro":"黃積啟古厝位於金城鎮水頭聚落，在前水頭黃氏家廟右側前方，官方推估與清乾隆年間興建的黃濟古厝年代相近。它的平面格局相當特殊，屬於「單伸手」，位在黃廷宙銃樓所屬二落大厝與左護龍的前側，看起來像是那座二落大厝增建的附屬建築。屋頂為雙坡圓脊，原有三個出入口，其中兩處在牆規門上，已用空心磚封閉。主要入口在南側建築，外牆下緣為封堵石砌、上緣斗砌，轉角以煙炙磚柱收邊。目前閒置作為堆放雜物的空間，詳細沿革仍待調查。","highlights":["少見的「單伸手」平面格局","牆規門上兩處已封閉的出入口","轉角以煙炙磚柱收邊的外牆"],"funFact":"它有三個出入口，其中兩個開在牆規門上，現在已被空心磚封起來。","photoSpot":"從黃氏家廟前拍古厝與周邊老屋","visitMin":10,"openNote":"位於金城鎮水頭聚落黃氏家廟旁。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；目前閒置未開放。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"在水頭黃氏家廟右前方，有一棟不起眼的小老屋，它的格局叫單伸手。"},{"who":"R","text":"單伸手？聽起來像在搭公車拉吊環。"},{"who":"A","text":"哈，很有畫面！一般古厝左右對稱，像張開雙手，它卻只伸出一邊，所以叫單伸手。"},{"who":"R","text":"那這棟小老屋大概是什麼時候蓋的？"},{"who":"A","text":"官方推估和旁邊清乾隆年間的黃濟古厝差不多時期，算是水頭的老前輩。"},{"who":"R","text":"那它旁邊那棟大房子又是誰家的？"},{"who":"A","text":"它就在黃廷宙銃樓所屬大厝的前側，看起來像是那棟二落大厝增建的附屬建築。"},{"who":"R","text":"原來它是隔壁大宅的小跟班！那現在裡面住人嗎？"},{"who":"A","text":"目前閒置，用來堆放雜物，所以我們只在外面看。"},{"who":"A","text":"它原本有三個出入口，兩個開在牆規門上，現在用空心磚封住了。請在屋外找找看，被封起來的門在哪裡！"}],"clues":["我的格局只伸出一邊，叫作單伸手","我有兩個開在牆規門上的出入口被空心磚封住","我在前水頭黃氏家廟右側前方，推估建於清乾隆年間"],"quiz":[{"q":"這棟古厝的特殊平面格局叫什麼？","options":["三蓋廊","一落四櫸頭","大九架","單伸手"],"answer":3,"explain":"黃積啟古厝平面格局類型特殊，屬於單伸手。"},{"q":"牆規門上的兩處出入口現況如何？","options":["改成鐵捲門","已用空心磚封閉","改為玻璃窗","完全拆除"],"answer":1,"explain":"牆規門上的兩處出入口目前已以空心磚封閉。"}],"images":[]},{"id":"jincheng-fushigucuo","name":"傅氏古厝","short":"傅氏古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43348,"lng":118.31865,"address":"金門縣金城鎮中興路124巷3號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000063","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-14/e1b84e99-27d0-4c6c-9374-f29a9e8b5e21/傅氏古厝-代表圖像.jpg","year":1790,"yearText":"約清代中葉以前（確切年代待考）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"傅氏船隊返鄉蓋的倉庫，因海難而停下的大宅夢","intro":"傅氏古厝位於金城鎮後浦城區中興路巷內，約建於清代中葉以前。據官方資料，當時傅氏家族在日本經營銅礦場，擁有7艘船往返中日之間，返鄉時先蓋了這座宅子作為倉庫。後來船隊在澎湖外海遇難，只有一人抱著木箱漂浮海上得以生還，原本興建大宅的計畫也因此停頓。1949至1955年間曾被國軍佔用，前埕照壁就是當時所建。建築為二落大厝加左右護龍，以牆規樓圍出前埕，正身立面是「皇宮起」形式；後落步口左右用木質落柱並加設格扇，官方指出這種形制在金門少見。詳細歷史仍待日後深入調查。","highlights":["牆規樓圍出的紅磚前埕與水井","正身「皇宮起」立面與煙炙磚柱","國軍駐紮時期以空心磚砌成的照壁"],"funFact":"傅氏的7艘船隊在澎湖外海遇難，只有一人抱著木箱漂浮海上倖存。","photoSpot":"巷口拍牆規樓與前後落翹脊","visitMin":15,"openNote":"位於金城鎮後浦城區中興路巷內。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。從金城車站步行可達。","dialogue":[{"who":"R","text":"Allan，這棟古厝前面有口井，還有一面照壁，看起來好有氣勢。"},{"who":"A","text":"這是傅氏古厝。說來妳可能不信，它一開始是蓋來當倉庫的。"},{"who":"R","text":"倉庫？蓋得這麼講究的倉庫，是要放寶物嗎？"},{"who":"A","text":"官方資料說，傅家當年在日本經營銅礦場，有7艘船往返中日兩地，返鄉時先蓋這裡放貨。"},{"who":"R","text":"7艘船！那他們應該準備蓋更大的豪宅吧？"},{"who":"A","text":"本來是的，可惜船隊在澎湖外海遇難，只有一人抱著木箱漂在海上活了下來，大宅計畫就此停下。"},{"who":"R","text":"原來這棟古厝背後，藏著這麼令人難過的故事。"},{"who":"A","text":"後來國軍也在這裡駐紮過，前面那面照壁就是那時候砌的，不同年代的痕跡都疊在一起了。"},{"who":"A","text":"請你在巷口看看前後兩落的屋脊，比比看哪一落的翹脊比較高！"}],"clues":["我原本是當倉庫用的，主人的船隊往返中日兩地","主人的船隊在澎湖外海遇難，只有一人倖存","國軍駐紮時在我的前埕砌了一面照壁"],"quiz":[{"q":"傅氏家族當年在日本經營什麼事業？","options":["茶葉行","錢莊","布莊","銅礦場"],"answer":3,"explain":"傅氏家族於日本經營銅礦場，有七艘船往返。"},{"q":"傅氏古厝前埕的照壁是誰建造的？","options":["傅氏族人","國軍","日本商人","清代官府"],"answer":1,"explain":"1949至1955年國軍佔用期間建造了照壁。"}],"images":[]},{"id":"jincheng-baishixianzucao","name":"白氏先祖草寮舊址（現為王宅）","short":"白氏草寮舊址","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.412644,"lng":118.296167,"address":"金門縣金城鎮前水頭151號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000043","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/3abe4f79-4a17-4546-a19d-64daafc2991e/01封面.jpg","year":1800,"yearText":"約19世紀初（清中葉），王氏居住至今二百餘年","era":"qing","themes":["閩南古厝","聚落地景"],"yearUnknown":false,"summary":"傳說水頭第一位居民搭草寮的地方","intro":"白氏先祖草寮舊址位於金城鎮水頭聚落後界靠海處，現為王宅。村老相傳，約在宋末以前水頭還沒有人居住時，有一位來自大陸的白姓漁夫到水頭海岸捕魚，為了避風就在此處搭草寮歇息，可說是水頭最早的居民。不過白氏並未長久定居，今天水頭已沒有白氏後裔。現在的建築是一落四櫸頭帶左突歸及牆規，居住者為來自金門東沙的王氏裔孫，至今已有二百餘年歷史。外牆皆以白漆粉刷，室內外樸實無華，右側混凝土平臺下方還有一處防空洞。","highlights":["傳說中水頭第一座草寮的所在位置","白漆粉刷、樸實無華的一落四櫸頭","以花崗石為門框的牆規樓入口"],"funFact":"傳說中第一位居民姓白，但他沒有留下來，所以今天的水頭找不到白氏後裔。","photoSpot":"在巷口拍白牆古厝與牆規樓","visitMin":10,"openNote":"位於金城鎮水頭聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車到水頭。","dialogue":[{"who":"R","text":"Allan，這間白白的小古厝看起來很普通，為什麼也是歷史建築？"},{"who":"A","text":"因為它的位置有故事。傳說在水頭還沒有人住的時候，一位白姓漁夫在這裡搭草寮避風。"},{"who":"R","text":"所以他是水頭的第一位居民？好像遊戲裡的新手村村長！"},{"who":"A","text":"可惜這位村長沒有留下來，今天水頭已經找不到白氏的後代了。"},{"who":"R","text":"那現在住在這裡的又是哪一家人呢？"},{"who":"A","text":"是從金門東沙遷來的王氏後代，已經住了二百多年，房子是一落四櫸頭。"},{"who":"R","text":"外牆全部刷白，該不會是為了紀念白先生吧？"},{"who":"A","text":"這是你的浪漫想像，官方沒有這麼說喔。不過樸素也是一種美，就像一碗白粥。"},{"who":"A","text":"請你在屋外找找看，主入口那座牆規樓的門框是用什麼石頭做的！"}],"clues":["傳說宋末以前，一位漁夫在我這裡搭草寮避風","現在住在我這裡的是金門東沙王氏的後代","我是水頭聚落白牆的一落四櫸頭，名字裡有一個顏色"],"quiz":[{"q":"傳說中水頭最早的居民是做什麼的？","options":["教書先生","漁夫","木匠","商人"],"answer":1,"explain":"相傳一位白姓漁夫到水頭海岸捕魚避風。"},{"q":"現在住在這處舊址的王氏來自哪裡？","options":["同安金柄","烈嶼東林","金門東沙","廈門鼓浪嶼"],"answer":2,"explain":"居住者為金門東沙社的王氏裔孫。"}],"images":[]},{"id":"jinsha-tangtoujinliansi","name":"塘頭金蓮寺","short":"塘頭金蓮寺","category":"歷史建築","level":"","town":"金沙鎮","types":["寺廟"],"lat":24.51479,"lng":118.41483,"address":"金門縣金沙鎮塘頭27-1號","announced":"2025-06-27","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20250630000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-09-12/3122e6ca-fbfc-47b8-8c12-dcbe32bed425/塘頭金蓮寺-代表圖像.jpg","year":1800,"yearText":"年代不詳（推測明清時期創建）","era":"unknown","themes":["宗教信仰"],"yearUnknown":true,"summary":"保存林天助濕壁畫的小型雙落廟宇","intro":"塘頭金蓮寺位於金沙鎮塘頭聚落，在金門島東北角、官澳東南側，清代《金門志》已記載塘頭鄰近官澳港口、周邊有鹽田。寺廟主祀觀音佛祖，建寺時間推測在明清時期，寺名可能取自門聯「金塘似鑒涵三界，蓮藕如船渡眾生」。前落在民國47年（1958）八二三砲戰中受損，民國49年簡單修繕，民國66年（1977）村民集資重修，聘請烈嶼彩繪師林天助繪製濕壁畫，題材有《西遊記》、《薛丁山征西》，龕壁繪福德正神與註生娘娘。這是金門僅存四處完整保存林天助作品的地方之一，民國114年（2025）登錄為歷史建築。","highlights":["正殿兩側林天助繪製的《西遊記》《薛丁山征西》濕壁畫","門神彩繪：左除難金剛、右伏魔金剛","正殿中央以洗石子做成「祈求平安」的拜石"],"funFact":"門額「香遠益清」畫蓮花水禽，「深秋獨豔」畫菊花配公雞，取「加冠」的吉祥諧音。","photoSpot":"在前埕拍「金蓮寺」門額與龍虎堵","visitMin":20,"openNote":"位於金沙鎮塘頭聚落，鄰近官澳，為地方信仰廟宇；官方資料未載明開放時間。參訪請保持安靜、尊重祭祀活動，勿觸摸壁畫。可開車、騎機車前往。","dialogue":[{"who":"A","text":"來到金門東北角的塘頭，阿拉蕾，這座小廟可是藏著一本大畫冊喔。"},{"who":"R","text":"畫冊？我只看到一間小小的廟，連招牌都不大耶。"},{"who":"A","text":"秘密在牆上！正殿兩側是烈嶼彩繪師林天助畫的濕壁畫，有西遊記，也有薛丁山征西。"},{"who":"R","text":"西遊記我知道！牆上有孫悟空嗎？"},{"who":"A","text":"有喔。這些畫是民國66年村民集資重修時請他畫的，現在金門完整保存他作品的地方只剩四處，這裡就是其中之一。"},{"who":"R","text":"只剩四處！那更要好好保護。為什麼廟要重修呢？"},{"who":"A","text":"前落在民國47年八二三砲戰時受損，村民先簡單修過，後來才集資重修。牆上的畫，也見證了那段重建的歲月。"},{"who":"R","text":"原來這些畫背後，藏著這麼多村子的故事。"},{"who":"A","text":"進廟記得放輕腳步、不要摸壁畫。找找看門神，左邊是除難金剛，右邊是哪一位？"}],"clues":["我的牆上有孫悟空和薛丁山的故事","我的門聯說蓮藕像船，能渡眾生","金門東北角塘頭聚落主祀觀音的小廟"],"quiz":[{"q":"寺內正殿濕壁畫是哪位彩繪師的作品？","options":["潘麗水","陳玉峰","林天助","李漢卿"],"answer":2,"explain":"民國66年重修時，聘請烈嶼彩繪師林天助繪製。"},{"q":"金蓮寺主祀哪一位神明？","options":["觀音佛祖","媽祖","關聖帝君","保生大帝"],"answer":0,"explain":"金蓮寺主祀觀音佛祖，寺名也與此有關。"}],"images":[]},{"id":"jincheng-gugangcaishikaiji","name":"古崗蔡氏開基祖厝","short":"蔡氏開基祖厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.39725,"lng":118.31703,"address":"金門縣金城鎮小古崗17號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000055","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-27/519b49ed-032d-45a0-b5f0-27b25d951b6a/古崗蔡氏開基祖厝01.png","year":1808,"yearText":"約1796–1820年（清嘉慶年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"瓊林蔡氏的發源地，滿牆人字砌黃花崗石","intro":"這座古厝位於金城鎮小古崗，是古崗蔡氏的開基祖厝，約建於清嘉慶年間（1796–1820）。濟陽派蔡氏在宋代遷到金門，居住在許坑（今古崗）；南宋初年蔡氏十七郎遷到平林（今瓊林），子孫繁衍，形成著名的「瓊林蔡」，明清時期再散居金門各地、烈嶼、大嶝以及臺灣、澎湖。建築由前棟一落四櫸頭與後棟一落二櫸頭組成，牆體大量使用在地黃花崗石，以人字砌為主、轉角用聖旨砌收邊，外觀質樸。後棟屋脊上有瓦將軍與獅子，背牆有石敢當，都是傳統民居常見的辟邪物；屋前約16公尺處還留有旗桿夾桿石。","highlights":["整面黃花崗石人字砌牆與轉角聖旨砌","後棟屋脊上的一對瓦將軍與獅子","屋前約16公尺處的旗桿夾桿石"],"funFact":"金門著名的「瓊林蔡」，祖先就是在南宋初年從許坑，也就是今天的古崗遷過去的。","photoSpot":"側面拍黃花崗石人字砌牆面紋理","visitMin":15,"openNote":"位於金城鎮小古崗聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；屋前夾桿石緊鄰民居，觀看時請放輕腳步。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這面牆好像排滿斜斜的人字，是誰在牆上寫字嗎？"},{"who":"A","text":"這叫人字砌，用金門在地的黃花崗石斜斜疊起來，轉角再用聖旨砌收邊。這裡是古崗蔡氏開基祖厝。"},{"who":"R","text":"開基祖厝？聽起來就是蔡家的老家。"},{"who":"A","text":"沒錯。蔡氏在宋代來到許坑，也就是今天的古崗，南宋初年有一支遷到瓊林，後來成了有名的瓊林蔡。"},{"who":"R","text":"原來瓊林蔡的老家在這裡！那這棟古厝是那時候蓋的嗎？"},{"who":"A","text":"那倒不是，現在這棟約建於清嘉慶年間，前棟一落四櫸頭，後棟一落二櫸頭。"},{"who":"R","text":"屋頂上那兩個小人和獅子，是在站崗嗎？"},{"who":"A","text":"那是瓦將軍和獅子，背牆還有石敢當，都是保平安的。看得我都想吃碗廣東粥壓壓驚。"},{"who":"A","text":"請你從側面看牆，找找轉角那幾塊橫豎交錯的聖旨砌，跟中間的人字砌比比看！"}],"clues":["我的牆用黃花崗石斜斜疊成人字","有一支族人從這裡遷到平林，後來開枝散葉","我在小古崗，屋脊上站著瓦將軍和獅子"],"quiz":[{"q":"這座古厝的牆體主要用什麼石材與砌法？","options":["青斗石平砌","黃花崗石人字砌","玄武岩亂石砌","咾咕石疊砌"],"answer":1,"explain":"牆體以在地黃花崗石人字砌為主。"},{"q":"南宋初年蔡氏十七郎從許坑遷到哪裡？","options":["山后","水頭","沙美","瓊林"],"answer":3,"explain":"十七郎遷至平林，也就是今天的瓊林。"}],"images":[]},{"id":"jinhu-caihanjurenzhai","name":"蔡翰舉人宅(一)","short":"蔡翰舉人宅一","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.45371,"lng":118.37474,"address":"金門縣金湖鎮瓊林104號","announced":"2005-12-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051219000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-25/f5e37017-1360-4a4c-949a-8d2b4f258508/(1)封面.jpg","year":1808,"yearText":"約1807年以後（清嘉慶年間）","era":"qing","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"掛著「副魁」匾、門前立旗杆座的一落兩櫸頭","intro":"蔡翰舉人宅（一）位於金湖鎮瓊林聚落。蔡翰（1732－1810）又名苑，號毅園，屬瓊林蔡氏新倉下二房，1801年（清嘉慶6年）鄉試以老生身分獲給副榜，回鄉立「副魁」匾；1807年會試後又由禮部依例給予舉人。此宅確切年代不詳，推估是他獲舉人後回鄉所建，同時建了兩棟，本宅為一落二櫸頭。正廳為大九架三開間，巷頭深約2公尺並設立柱與格扇，較為少見；正廳門楣懸「副魁」匾，神龕橫批「燕翼堂」，外埕立有「舉人旗杆」座，左側另建書房「仰瞻居」。今由承租者作為民居使用。","highlights":["正廳門楣上嘉慶辛酉科的「副魁」匾","外埕的「舉人旗杆」座","深約2公尺、設有立柱與格扇的巷頭"],"funFact":"蔡翰1801年獲副榜時已69歲，是以「老生」身分獲得的功名，真正活到老學到老。","photoSpot":"在外埕拍舉人旗杆座與古厝正面","visitMin":10,"openNote":"位於金湖鎮瓊林聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。","dialogue":[{"who":"R","text":"Allan，這間古厝門前立著一組石座，是給人坐的椅子嗎？"},{"who":"A","text":"那可不能坐，那是「舉人旗杆」座。古時候考上功名，就能在家門前立旗杆，等於掛上一面榮譽榜。"},{"who":"R","text":"原來是古代的金榜題名看板！屋主是誰？"},{"who":"A","text":"瓊林的蔡翰。他1801年鄉試拿到副榜，那年已經69歲，是用「老生」身分得到的功名。"},{"who":"R","text":"69歲還在考試！我寫一張考卷就想睡了。"},{"who":"A","text":"所以他把「副魁」匾掛在正廳門楣上。後來禮部又依例給他舉人，他就回鄉蓋了兩棟房子，這棟是一落兩櫸頭。"},{"who":"R","text":"那旁邊另一棟就是哥哥還是弟弟？"},{"who":"A","text":"算是兄弟檔，叫蔡翰舉人宅二。請你在屋外找找旗杆座，再想像當年旗子飄揚的樣子拍一張照。"}],"clues":["我的主人69歲時以老生身分獲得副榜","我的外埕有舉人旗杆座，左側有書房仰瞻居","我是瓊林一座一落兩櫸頭、掛著副魁匾的古厝"],"quiz":[{"q":"蔡翰舉人宅（一）正廳門楣上掛的是什麼匾？","options":["文魁","進士","副魁","武魁"],"answer":2,"explain":"蔡翰1801年獲給副榜，回鄉立「副魁」匾。"},{"q":"古厝外埕的石座原本是做什麼用的？","options":["拴馬","曬穀","放置香爐","豎立舉人旗杆"],"answer":3,"explain":"外埕設有「舉人旗杆」座，彰顯功名。"}],"images":[]},{"id":"jinhu-caihanjurenzhai2","name":"蔡翰舉人宅(二)","short":"蔡翰舉人宅二","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.45356,"lng":118.37504,"address":"金門縣金湖鎮瓊林106號","announced":"2005-12-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051219000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-20/9c32a9b4-5ece-48d6-9354-320eacbde973/1封面.jpg","year":1808,"yearText":"約1807年以後（清嘉慶年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"屋面全鋪筒瓦的瓊林二落大厝","intro":"蔡翰舉人宅（二）位於金湖鎮瓊林聚落，同樣由蔡翰興建，推估是他1807年依例獲給舉人後回鄉所建，與一落二櫸頭的（一）同期，本宅規模較大，為二落大厝加左護龍帶牆規。瓊林重視文教，明清兩代共出進士6人、舉人7人。本宅屋脊為翹脊，脊堵飾彩繪泥塑與剪黏，最特別的是二落屋面全用筒瓦，在瓊林及金門都很少見。門扇有木雕，門楣飾擂金畫，頂端以鏤空花雕兼顧採光。1949至1958年曾有約20名士兵借住，2014年完成整體修復；左護龍已改建為現代樓房。","highlights":["二落屋面全鋪筒瓦，瓊林與金門少見","門楣上的擂金畫與鏤空花雕門扇","脊堵的彩繪泥塑與剪黏裝飾"],"funFact":"瓊林在明清兩代出過6位進士、7位舉人，蔡翰也是這個文風聚落的一份子。","photoSpot":"從側面拍屋面一排排的筒瓦","visitMin":10,"openNote":"位於金湖鎮瓊林聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。","dialogue":[{"who":"A","text":"剛才看了蔡翰舉人宅一，現在換它的大兄弟登場，同樣是蔡翰蓋的，規模更大。"},{"who":"R","text":"大兄弟長什麼樣？跟剛剛那間有什麼不同？"},{"who":"A","text":"這棟是二落大厝加左護龍。重點在屋頂，整片都鋪筒瓦，在瓊林和整個金門都很少見。"},{"who":"R","text":"筒瓦是什麼？跟一般屋瓦差在哪？"},{"who":"A","text":"筒瓦像剖半的竹筒，一根一根排在屋面上，比較費工也比較氣派，就像炒泡麵多加一顆蛋，豪華升級。"},{"who":"R","text":"Allan你又在想吃的了！那瓊林為什麼出這麼多舉人？"},{"who":"A","text":"瓊林很重視讀書，明清兩代出了6位進士、7位舉人。蔡翰就是在這種風氣下，老當益壯考出功名。"},{"who":"R","text":"原來整個村子都是學霸，壓力好大喔！"},{"who":"A","text":"請你站到屋子側邊，看看屋面上的筒瓦，數數看一排大概有幾根。"}],"clues":["我和一座一落兩櫸頭的兄弟屋是同一人所建","我的二落屋面全鋪筒瓦，在金門少見","我是瓊林蔡家舉人所建的二落大厝加左護龍"],"quiz":[{"q":"蔡翰舉人宅（二）的屋面有什麼少見的作法？","options":["全鋪筒瓦","鋪設琉璃瓦","採用平屋頂","覆蓋茅草"],"answer":0,"explain":"二落大厝屋面整體採全筒瓦，為瓊林及金門少見。"},{"q":"瓊林在明清兩代共出了幾位進士？","options":["2位","4位","6位","10位"],"answer":2,"explain":"瓊林明清兩代共有進士6人、舉人7人。"}],"images":[]},{"id":"jincheng-jianweidi","name":"建威第","short":"建威第","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43105,"lng":118.31427,"address":"金門縣金城鎮民族路318巷3號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000062","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-08/6d71477f-e473-4922-ba4b-930586d32752/2.jpg","year":1815,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝","名人故居"],"yearUnknown":true,"summary":"清代安平副將陳光求的故居，有座捲棚軒亭","intro":"建威第位於金城鎮後浦城區民族路巷內，是清代武將陳光求的故居。陳光求是後浦人，乾隆年間投身軍旅，以擒捕海盜聞名，嘉慶年間曾隨李長庚追剿蔡牽黨羽，1813年赴臺任安平副將，主管臺灣水師協，後任定海總兵、蘇松總兵，《金門志》與《臺灣通志》都有他的列傳。《金門志》形容他「修髯偉幹，力能舉三百觔」，並修祖祠、砌石路、修義塚。不過金門的建威將軍只有邱良功一人，此宅為何名為建威第仍待研究。建築以單落為主體，前加四坡捲棚軒亭，翹脊末端有獅面泥塑；門額原有「建威第」泥塑匾，已經佚失。","highlights":["正身前的四坡捲棚軒亭，以四支方柱支撐","軒亭翹脊末端的獅面泥塑","牆規樓翹脊與門額上已佚失的匾位"],"funFact":"《金門志》形容陳光求「修髯偉幹，力能舉三百觔」，是位大鬍子大力士。","photoSpot":"巷口拍牆規樓翹脊與門額","visitMin":10,"openNote":"位於金城鎮後浦城區民族路巷內，左護龍與後棟仍有人居住。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。從金城車站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，給妳一個名字，建威第。妳猜這裡住過誰？"},{"who":"R","text":"聽起來很威風，應該是建威將軍吧？那不就是邱良功嗎？"},{"who":"A","text":"好推理，可惜不對！這是清代武將陳光求的故居。金門的建威將軍只有邱良功一人，這名字的由來還在研究。"},{"who":"R","text":"竟然是一樁懸案！那陳光求有多厲害？"},{"who":"A","text":"他曾追剿海盜蔡牽的黨羽，1813年還到臺灣當安平副將，主管臺灣的水師。"},{"who":"R","text":"從金門到臺灣，這是跨海出差耶！"},{"who":"A","text":"金門志說他鬍子長、身材高大，力氣能舉三百斤，比我扛一箱貢糖還輕鬆。"},{"who":"R","text":"大鬍子大力士！那房子有什麼特別的地方？"},{"who":"A","text":"正身前有一座四坡捲棚軒亭。請在巷口看看牆規樓的門額，原本的泥塑匾不見了，找找它原來的位置！"}],"clues":["我的主人1813年曾赴臺擔任安平副將","我的名字和主人的官銜對不起來，至今還在研究","我在後浦民族路巷內，門額的泥塑匾已經佚失"],"quiz":[{"q":"陳光求1813年赴臺擔任什麼職務？","options":["臺灣知府","澎湖通判","安平副將","臺灣總兵"],"answer":2,"explain":"陳光求1813年赴臺任安平副將，主管臺灣水師協。"},{"q":"官方說明中，金門唯一的建威將軍是誰？","options":["陳光求","邱良功","林可遠","陳昌文"],"answer":1,"explain":"金門之建威將軍僅邱良功一人，宅名仍待研究。"}],"images":[]},{"id":"jinsha-zhoushigucuo","name":"周氏古厝","short":"浦邊周氏古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47996,"lng":118.39028,"address":"金門縣金沙鎮浦邊5號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-20/8e8e1428-7dcb-4175-aa12-de236d10facb/1 封面.jpg","year":1820,"yearText":"約19世紀初（清嘉慶、道光年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"浦邊「北周」祖公厝，磚雕篆字聯對精美","intro":"周氏古厝位於金沙鎮浦邊聚落東北一隅，是浦邊周氏的祖公厝，族人由此分出。浦邊周氏以「濂溪」為堂號，相傳為宋代周敦頤之後，開基祖周賜於明初從福建南安遷來，兩個兒子分居南北，形成「北周」「南周」，這座古厝就在北周。族人說古厝約建於清嘉慶、道光年間，從精細的磚雕、木雕、石雕看也屬清代中葉以後，後來增建左右護龍。中脊中央嵌一塊八卦磚作為厭勝物；入口深井牆面有磚雕篆體聯對與兩幅博古圖。左護龍原有的僑匯時期疊樓，已於民國70年代拆改。","highlights":["中脊中央鑲嵌的八卦磚，是守護民居的厭勝物","入口深井牆上的磚雕篆體聯對與博古圖","燈樑兩側的蓮花、螃蟹木雕"],"funFact":"浦邊周氏開基祖的兩個兒子分居南北，族人以「北周」「南周」區分，這座祖公厝屬北周。","photoSpot":"從側面拍翹脊與中脊上的八卦磚","visitMin":15,"openNote":"位於金沙鎮浦邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往，或搭金門縣公車至沙美車站後轉乘。","dialogue":[{"who":"R","text":"Allan，我聽說浦邊有北周和南周，這裡是要上歷史課講南北朝嗎？"},{"who":"A","text":"哈哈，不是那個北周！浦邊周氏開基祖周賜明初從南安搬來，兩個兒子一南一北分開住，就成了北周、南周。"},{"who":"R","text":"原來是家族的南北分區！那這間是哪一邊的？"},{"who":"A","text":"這是北周的祖公厝，子孫從這裡開枝散葉。族人說大約是清嘉慶、道光年間蓋的。"},{"who":"R","text":"屋頂中間那塊方方的磚，上面好像畫了符號？"},{"who":"A","text":"那是八卦磚，用來守護家宅的厭勝物，等於古厝的平安符，比我口袋裡的貢糖還管用。"},{"who":"R","text":"你的貢糖明明只會保佑你自己的肚子！"},{"who":"A","text":"被你識破了。這裡是私人住宅，在外面欣賞就好。站到側面，看看你能不能找到中脊上那塊八卦磚！"}],"clues":["我是一個家族的祖公厝，子孫由我分出","我的中脊嵌著一塊八卦磚","浦邊「北周」的清代中葉大厝"],"quiz":[{"q":"浦邊周氏以什麼為堂號？","options":["潁川","隴西","清河","濂溪"],"answer":3,"explain":"浦邊周氏以「濂溪」為堂號，相傳為周敦頤之後。"},{"q":"中脊中央的八卦磚有什麼作用？","options":["標示方位","守護民居的厭勝物","紀念落成年份","幫助排水"],"answer":1,"explain":"八卦磚是守護民居的厭勝物。"}],"images":[]},{"id":"jincheng-lingjisi","name":"靈濟寺（觀音亭）","short":"靈濟寺","category":"歷史建築","level":"","town":"金城鎮","types":["寺廟"],"lat":24.43157,"lng":118.3186,"address":"金門縣金城鎮城北段448地號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000071","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-06-30/f1b2473e-2ae5-4737-bbf1-1ed2c46aec37/靈濟寺（觀音亭）_代表圖像.png","year":1825,"yearText":"1825年（清道光5年）重修並改名，始建年代不詳","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"靈泉救火而得名的後浦觀音亭","intro":"靈濟寺舊名觀音亭，位於金城鎮後浦東門，鄰近國定古蹟邱良功母節孝坊，主祀觀世音菩薩。寺頂大脊有1978年住持釋惟德所記「肇建唐朝貞元廿年」，但並無史料可證。據寺內1825年「靈濟寺」匾記，1824年農曆十二月寺北大火延及外亭，佛殿內忽湧靈泉，寺內無恙，地方人士倡議重修，並改名「靈濟寺」，記這段「靈泉普濟」。民國以來多次修繕，1978年增建鐘鼓樓。寺內保存多方清代匾額，周邊的「觀音亭街」也因寺得名。","highlights":["正殿中門由烈嶼彩繪師林天助繪製的門神","暗藏「浯江」「金門」地名的兩副窗聯","棟架上「靈慈顯濟」等多方清代匾額"],"funFact":"窗聯「金靈上剎隱梵樓，門濟煙霞千古留」，兩句開頭合起來正是「金門」。","photoSpot":"拜亭前拍彌勒佛與「靈濟寺」廟名","visitMin":20,"openNote":"位於金城鎮後浦市區，鄰近邱良功母節孝坊，官方資料記載全天開放；參拜請保持安靜、尊重宗教活動。可搭金門縣公車到金城車站後步行前往。","dialogue":[{"who":"R","text":"Allan，這裡是靈濟寺，可是大家好像都叫它觀音亭？"},{"who":"A","text":"沒錯，因為主祀觀世音菩薩，在地人習慣叫觀音亭，旁邊的街還叫觀音亭街呢。"},{"who":"R","text":"那為什麼它的正式名稱又叫靈濟呢？"},{"who":"A","text":"據寺內1825年的匾記，前一年冬天寺北大火燒到外亭，佛殿裡忽然湧出靈泉，寺內平安無事。"},{"who":"R","text":"哇，靈泉救火！所以就改名叫靈濟寺？"},{"who":"A","text":"答對，紀念「靈泉普濟」。脊上雖然寫著唐朝創建，但官方說沒有史料能證明喔。"},{"who":"R","text":"Allan你很誠實耶，不亂吹牛。"},{"who":"A","text":"導覽員的招牌就是實話實說，跟我的光頭一樣藏不住。對了，這裡的窗聯還藏著文字遊戲。"},{"who":"A","text":"請到正殿大門兩側，把每副窗聯上下兩句的第一個字連起來讀，看看藏了哪兩個地名！"}],"clues":["我曾遇大火，殿內湧出靈泉而平安，因此改了名字","我的窗聯暗藏浯江與金門兩個地名","我在後浦東門一帶，鄰近節孝坊，主祀觀世音菩薩"],"quiz":[{"q":"「靈濟」這個寺名是為了紀念什麼？","options":["高僧在此圓寂","大火時殿內湧出靈泉","皇帝御賜寺名","鄭成功在此駐軍"],"answer":1,"explain":"1824年大火時佛殿忽湧靈泉，寺內無恙，故改名靈濟寺。"},{"q":"正殿中門的門神由誰繪製？","options":["住持釋惟德","鄉民林俊元","同安匠師團隊","烈嶼彩繪師林天助"],"answer":3,"explain":"正殿明間中門門神由烈嶼彩繪師林天助繪製。"}],"images":[]},{"id":"jincheng-houpudafudi","name":"後浦大夫第","short":"後浦大夫第","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43319,"lng":118.31564,"address":"金門縣金城鎮光前路70巷3號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000064","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-19/b0ff889e-e2f6-4f7b-912b-8f8aa375b329/1.代表圖像.jpg","year":1841,"yearText":"約1841年（清道光21年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"後浦西門的二落大厝，牆上磚砌囍字與卍字","intro":"後浦大夫第位於金城鎮後浦城區光前路巷內，約建於清道光21年（1841），原屬蔣姓所有，後因家道中落轉賣給許姓。1949年國民政府遷臺後曾被佔住，直到1954年。官方評價它保存傳統風貌、樸實無華，是後浦西門重要的民宅。建築為二落大厝加牆規樓，屋頂是閩南雙坡圓脊，前落脊肚還看得到剪黏與泥塑。前落榻受正立面的窗櫺兩側，一邊用磚砌出「囍」字，另一邊砌成卍字不斷紋；門楣有「大夫第」字樣，額堵有山水字畫彩繪，插角是鳳凰木雕，大規壁脊墜有彩帶、捲雲紋泥塑。詳細歷史仍待日後深入調查。","highlights":["榻受兩側磚砌「囍」字與卍字不斷紋","門楣「大夫第」字樣與鳳凰木雕插角","大規壁脊墜的彩帶、捲雲紋泥塑"],"funFact":"這座大夫第原屬蔣姓，後來家道中落，才轉賣給許姓人家。","photoSpot":"巷口拍牆規樓與後方圓脊屋頂","visitMin":10,"openNote":"位於金城鎮後浦城區光前路巷內，後浦西門一帶。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。從金城車站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，我們在珠山看過一座大夫第，後浦西門這裡也有一座，叫後浦大夫第。"},{"who":"R","text":"怎麼金門到處都是大夫？是大夫比較多，還是醫生比較多？"},{"who":"A","text":"大夫是官銜啦。這座約建於1841年，原本屬於蔣家，後來家道中落，賣給了許家。"},{"who":"R","text":"房子換了主人，名字還是大夫第，好像繼承了一塊響亮的招牌。"},{"who":"A","text":"形容得很貼切。它是二落大厝加牆規樓，官方說它樸實無華，是後浦西門重要的民宅。"},{"who":"R","text":"樸實無華？那有沒有藏什麼小驚喜？"},{"who":"A","text":"有喔！正面窗櫺兩側，一邊用磚砌出囍字，另一邊是卍字不斷紋，像一副用磚頭寫的對聯。"},{"who":"R","text":"一邊辦喜事，一邊祝福綿延不斷，太浪漫了吧！"},{"who":"A","text":"請在巷口找找看，囍字在左邊還是右邊？記得只在外面看，不要打擾住戶喔。"}],"clues":["我約建於1841年，原屬蔣姓，後來轉賣給許姓","我的正面一邊砌著「囍」字，一邊是卍字不斷紋","我在後浦西門光前路巷內，門楣寫著官銜"],"quiz":[{"q":"後浦大夫第原本屬於哪一姓人家？","options":["蔣姓","陳姓","許姓","林姓"],"answer":0,"explain":"原為蔣姓所有，家道中落後變賣給許姓。"},{"q":"正面窗櫺兩側用磚砌出哪兩種圖樣？","options":["福字與壽字","龍紋與鳳紋","梅花與竹節","囍字與卍字不斷紋"],"answer":3,"explain":"一邊磚砌「囍」字，另一邊為卍字不斷紋。"}],"images":[]},{"id":"jincheng-linkeyuansanluoda","name":"林可遠三落大厝","short":"林可遠大厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43319,"lng":118.31897,"address":"金門縣金城鎮珠浦北路12巷5、6號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000058","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/8bcd45fd-e7bf-44a9-bac5-338cc27532e4/01封面.jpg","year":1860,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝","名人故居"],"yearUnknown":true,"summary":"奎閣捐建者林斐章之孫林可遠的三落大厝故居","intro":"林可遠三落大厝位於金城鎮後浦城區珠浦北路巷內，是地方仕紳林可遠的故居。林可遠是捐建奎閣的林斐章之孫，《金門志》記載他遵守祖父遺訓，捐資修大溝義塚、充實育嬰堂經費；咸豐年間黃得美起事攻陷廈門時，他招募餘丁兩百名駐守，金門得以平安，官府要獎勵他，他卻把功勞讓給堂弟。官方資料說他清同治年間因助官防盜、守衛鄉梓，獲贈「利周鄉黨」牌匾。建築為三落大厝加牆規樓，第三落前有歇山式軒亭；前落榻受以剪黏、磚雕與泥塑裝飾，有蝙蝠、八寶等吉祥圖樣。興建年代與詳細歷史仍待日後深入調查。","highlights":["前落榻受的蝙蝠、八寶吉祥磚雕","大規壁脊墜的蝙蝠、磬、捲雲泥塑","後落櫸頭屋頂以瓦片排出的幾何紋"],"funFact":"林可遠守衛鄉梓有功，官府要獎勵他，他推辭不成，便把功勞讓給堂弟林榮邦。","photoSpot":"巷內拍牆規樓與榻受的剪黏裝飾","visitMin":15,"openNote":"位於金城鎮後浦城區珠浦北路巷內。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。從金城車站步行可達，可和奎閣一起認識林家祖孫。","dialogue":[{"who":"A","text":"還記得捐建奎閣的林斐章嗎？他的孫子林可遠，就住在這座三落大厝。"},{"who":"R","text":"爺爺蓋奎閣，孫子住大厝，這家人也太會蓋房子了吧！"},{"who":"A","text":"他們家更會做好事。林可遠遵守爺爺的遺訓，捐錢修義塚，還補助育嬰堂的經費。"},{"who":"R","text":"原來做好事也能像傳家寶一樣代代相傳！"},{"who":"A","text":"咸豐年間廈門發生動亂，他自己招募兩百名壯丁守衛金門，同治年間還獲贈利周鄉黨的匾額。"},{"who":"R","text":"這麼有功勞，官府應該封他當大官吧？"},{"who":"A","text":"官府要獎勵他，他推辭不成，就把功勞讓給堂弟。這種氣度，比我把最後一塊貢糖讓給妳還難得。"},{"who":"R","text":"你哪有讓過我！好啦，這座大厝有什麼看頭？"},{"who":"A","text":"前落正面有蝙蝠和八寶圖樣的磚雕。請在巷子裡找找，那隻蝙蝠藏在榻受的哪個角落！"}],"clues":["我的主人是捐建奎閣那位富商的孫子","主人曾招募兩百名餘丁守衛金門，卻把功勞讓給堂弟","我有三落，中落掛著「利周鄉黨」匾額"],"quiz":[{"q":"林可遠的祖父捐建了哪一座建築？","options":["武廟","總兵署","模範街","奎閣"],"answer":3,"explain":"林可遠是獨資捐建奎閣的林斐章之孫。"},{"q":"林可遠獲贈的牌匾寫著什麼？","options":["利周鄉黨","樂善好施","急公好義","功在桑梓"],"answer":0,"explain":"同治年間因助官防盜，獲贈「利周鄉黨」匾。"}],"images":[]},{"id":"jinsha-zhangzhangmangucuo2","name":"張璋滿古厝(87號)","short":"張璋滿古厝87號","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49209,"lng":118.41288,"address":"金門縣金沙鎮沙美87號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-20/39e78d8d-cc43-4350-b036-8d1d952dbcbb/1封面.jpg","year":1867,"yearText":"約1867年（清同治6年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"泉州匠師打造、屋脊寫「福祿禎祥」","intro":"這棟張璋滿古厝位於金沙鎮沙美聚落，與相鄰的另一棟同為張氏赴檳城工作後返鄉興建。官方資料記載本棟約建於清同治6年（1867），比鄰棟早十多年，並聘請泉州匠師建造。正面下段為封堵石、上段紅磚斗砌，櫸頭女兒牆鑲綠釉花磚。翹脊的脊帶有「福祿禎祥」泥塑字樣，脊墜以泥塑與人物交趾陶點綴；拱仔頭、水車堵泥塑精美，也飾有人物交趾陶，門額同樣是「儒林衍派」家徽。室內向寮屏門雕卍字不斷紋，巷頭半樓門與後落門窗都有書法對聯。民國98年（2009）完成整體修復。","highlights":["屋脊脊帶上的「福祿禎祥」泥塑字","拱仔頭、水車堵的人物交趾陶","櫸頭女兒牆的綠釉花磚"],"funFact":"這棟大厝特地聘請泉州匠師來蓋，比隔壁同家族的那棟早了十多年完成。","photoSpot":"退到巷口拍屋脊「福祿禎祥」字樣","visitMin":15,"openNote":"位於金沙鎮沙美聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看看屋脊，你能讀出上面寫什麼嗎？"},{"who":"R","text":"我看看，福、祿、禎、祥！屋頂上也能寫字喔？"},{"who":"A","text":"這是泥塑字，直接把祝福放在全家最高的地方，連老天爺都看得到。"},{"who":"R","text":"是誰蓋的呀？它跟旁邊那棟長得好像喔。"},{"who":"A","text":"兩棟都是張家人去檳城打拚後回來蓋的。這一棟比較早，大約清同治6年，還特地請了泉州的師傅來施工。"},{"who":"R","text":"請外地師傅，好講究！就像你吃石蚵一定要指定金門產的。"},{"who":"A","text":"知我者阿拉蕾也！你看拱仔頭和水車堵，還有人物交趾陶點綴，像一座迷你戲臺。"},{"who":"R","text":"那我要好好看清楚他們在演什麼戲！"},{"who":"A","text":"這是私人住宅，請在外面欣賞。最後找找門額上的家徽，看看寫的是不是儒林衍派。"}],"clues":["我的屋脊上寫著「福祿禎祥」","我請來泉州匠師，比隔壁同家族那棟早十多年完工","沙美聚落裡，清同治年間由檳城僑匯興建的古厝"],"quiz":[{"q":"這棟古厝屋脊上有哪四個泥塑字？","options":["福星高照","紫微拱照","香遠益清","福祿禎祥"],"answer":3,"explain":"脊帶以泥塑裝飾，飾有「福祿禎祥」字樣。"},{"q":"這棟古厝聘請哪裡的匠師建造？","options":["泉州","漳州","廈門","汕頭"],"answer":0,"explain":"約建於清同治6年，聘請泉州匠師建造。"}],"images":[]},{"id":"jinsha-zhenshameiwanan","name":"金沙鎮沙美萬安堂","short":"沙美萬安堂","category":"歷史建築","level":"","town":"金沙鎮","types":["寺廟"],"lat":24.491038,"lng":118.41202,"address":"金門縣金沙鎮汶沙測段965地號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000020","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-31/0a9ae455-d777-40cc-b6c2-d3675ec86da2/01封面.jpg","year":1871,"yearText":"1871年（清同治10年）遷建現址","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"主祀保生大帝、以義務扶乩派藥聞名的廟","intro":"沙美萬安堂位於金沙鎮沙美，清同治10年（1871）由沙美張氏張珪笑遷建於現址，主祀保生大帝，正門嵌字聯「萬安香煙浯島巍巍大帝，安懷老少金砂赫赫真君」。據《金門縣誌》記載，萬安堂曾歷經三次重建，最早創建於元朝，原址在今小浦頭川德宮前，但歷代修建都沒有立碑，只靠傳聞流傳。早年醫療不普及，萬安堂以扶乩派藥濟世聞名，問神、乩童、譯乩全屬義務。相傳清光緒21年（1895）沙美發生瘟疫，鄉人請來三忠王制瘟，後移祀廟中。建築為兩落加左護龍，門額有同治10年的「萬安堂」木匾。","highlights":["清同治10年所立的「萬安堂」木匾","前落三川脊上的剪黏與交趾陶","身堵中央的太極圖圓形木雕窗"],"funFact":"「萬安堂」這個名字，取自保生大帝吳夲生前行醫時的堂號，等於把醫館招牌直接掛到廟門上。","photoSpot":"在前埕照壁旁拍廟門與三川脊","visitMin":20,"openNote":"位於金沙鎮沙美聚落，平日以祭祀為主，開放時間以廟方為準；參拜請尊重廟方規範、留意明火。鄰近沙美車站，可搭金門縣公車後步行前往。","dialogue":[{"who":"R","text":"Allan，這間廟的名字叫萬安堂，聽起來好像一間藥房喔！"},{"who":"A","text":"你猜得很接近！主祀保生大帝，也就是大道公，「萬安堂」就是取自吳真人行醫時的堂號。"},{"who":"R","text":"所以這間廟以前真的可以幫人看病嗎？"},{"who":"A","text":"早年醫療不普及，萬安堂以扶乩派藥出名，而且問神、乩童、譯乩全部義務，不收錢。"},{"who":"R","text":"免掛號費耶！那它是什麼時候蓋的？"},{"who":"A","text":"清同治10年由沙美張氏的張珪笑遷建到這裡，門上的木匾就是那年立的。縣誌還說它最早創建於元朝。"},{"who":"R","text":"元朝？那不就有七百多年的歷史了嗎？"},{"who":"A","text":"但歷代修建都沒有立碑，只靠口耳相傳，所以我們聽聽就好。相傳清光緒21年沙美鬧瘟疫，鄉人還請來三忠王鎮瘟。"},{"who":"R","text":"原來廟裡住了好多位神明！那我去找找門額上寫著年代的那塊老木匾！"}],"clues":["我的名字取自一位神醫生前行醫的堂號","早年在我這裡問神、拿藥方都不收錢","沙美一座清同治年間遷建、主祀保生大帝的廟"],"quiz":[{"q":"萬安堂主祀的神明是哪一位？","options":["保生大帝","開漳聖王","廣澤尊王","玄天上帝"],"answer":0,"explain":"嵌字聯「浯島巍巍大帝」顯示主祀保生大帝。"},{"q":"萬安堂早年在地方上以什麼聞名？","options":["舞龍舞獅","義務扶乩派藥","放天燈祈福","主辦科舉考試"],"answer":1,"explain":"以扶乩派藥濟世聞名，問神、乩童、神譯皆義務。"}],"images":[]},{"id":"jincheng-xueshiyimu","name":"薛師儀墓","short":"薛師儀墓","category":"歷史建築","level":"","town":"金城鎮","types":["墓葬"],"lat":24.4167,"lng":118.32414,"address":"金門縣金城鎮庵前劃測段498地號","announced":"2012-10-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20171204000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-18/80fbfd30-4828-4963-b595-01d7f9261f01/薛師儀墓封面.jpg","year":1873,"yearText":"約1873年（清同治12年）薛師儀辭世後","era":"qing","themes":["墓葬"],"yearUnknown":false,"summary":"珠山出身的金門總鎮、武功將軍之墓","intro":"薛師儀墓位於金城鎮庵前聚落東南側與小西門之間。薛師儀為珠山薛氏義房19世裔孫，名維坤，號鼎臣，生於清嘉慶25年（1820），卒於同治12年（1873）。《金門志》記載他自少失怙，靠長兄培養成材，官至金門總鎮，誥授武功將軍。父親薛懋昭是樂善好施的儒士，著有《圭峰吟稿》，列入《金門志》「義行」傳。墓碑以正楷刻「皇清誥授武功將軍顯考鼎臣薛公 誥封夫人顯妣諡敬穆陳夫人佳城」，與夫人陳氏合葬。墓體由墓碑、碑翼、墓桌、護牆、曲手、印斗立柱與拜石構成，部分構件已改建。","highlights":["正楷刻「皇清誥授武功將軍」的墓碑","左右碑翼、墓桌與印斗立柱等石構件","墓碑後方的墓龜與墓岸"],"funFact":"薛師儀的父親樂善好施，因兒子官至參將，也被追贈為武功將軍。","photoSpot":"在拜石外以恭敬角度拍墓碑全景","visitMin":10,"openNote":"位於金城鎮庵前與小西門之間的戶外空間，可參觀外觀；請保持肅靜，勿踩踏、攀爬墓體。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，我們今天要參觀的是一座墓，我是不是要說話小聲一點？"},{"who":"A","text":"很貼心喔，參觀墓葬要保持恭敬。這裡安葬的是清代的金門總鎮薛師儀和夫人陳氏。"},{"who":"R","text":"總鎮聽起來好威風，是很大的官嗎？"},{"who":"A","text":"是負責金門軍務的高階武官，他還被誥授武功將軍。他是珠山人，1820年出生，1873年辭世。"},{"who":"R","text":"這麼厲害，他小時候一定很順利吧？"},{"who":"A","text":"其實他從小失去父親，是長兄一路栽培才有成就，所以族譜很強調他的孝悌。"},{"who":"R","text":"哥哥好了不起，比我們兩個互相吐槽好太多了。"},{"who":"A","text":"哈，我們是另一種兄妹情。他父親也是愛寫詩又樂善好施的讀書人，還留下詩集呢。"},{"who":"A","text":"到了現場請在拜石外靜靜觀察墓碑，找出「武功將軍」這四個字在哪一行。"}],"clues":["我的墓碑刻著「皇清誥授武功將軍」","我安葬的武官從小失怙，靠長兄栽培成材","我位於庵前與小西門之間，墓主是珠山出身的金門總鎮"],"quiz":[{"q":"薛師儀官至哪一個職位？","options":["金門總鎮","福建巡撫","同安知縣","翰林編修"],"answer":0,"explain":"《金門志》載薛師儀官至金門總鎮。"},{"q":"薛師儀的父親有什麼著作？","options":["金門志","顯影月刊","獅聲座談","圭峰吟稿"],"answer":3,"explain":"父親薛懋昭喜為詩，著有《圭峰吟稿》。"}],"images":[]},{"id":"jinsha-zhangzhangmangucuo","name":"張璋滿古厝(85號)","short":"張璋滿古厝85號","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.492068,"lng":118.413029,"address":"金門縣金沙鎮沙美85號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/95f6b18f-1288-4080-b62f-7b018adcfe3f/張璋滿古厝(85號)-封面.jpg","year":1879,"yearText":"1879年（清光緒5年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"檳城僑匯興建、桃形框彩繪別緻的大厝","intro":"張璋滿古厝包括相鄰兩棟，位於金沙鎮沙美聚落，由張氏赴檳城工作後於清末返鄉興建；這一棟於清光緒5年（1879）竣工，比鄰棟晚完成。建築為二落大厝，翹脊雙坡屋頂，右側以上有花瓶欄杆的隘門與鄰棟相連。山牆脊墜以蝙蝠、如意捲紋、彩帶與書卷組成；正面窗楣泥塑「畫閣雕軒」「竹苞松茂」，檐板彩繪以五個桃形為框，內繪果物、珊瑚、牡丹。門額有「儒林衍派」家徽，門印為松鶴竹鹿石雕，內側保有防盜的輪錢門。國軍駐金時曾作連部住所，民國98年（2009）完成整體修復。","highlights":["檐板上以五個桃形為框的果物、牡丹彩繪","窗楣泥塑「畫閣雕軒」「竹苞松茂」","與鄰棟相連、上有花瓶欄杆的隘門"],"funFact":"「竹苞松茂」典出《詩經》，比喻家族像竹松一樣根基穩固、枝葉繁茂。","photoSpot":"在前埕拍窗楣泥塑與檐板彩繪","visitMin":15,"openNote":"位於金沙鎮沙美聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"R","text":"Allan，這面牆的屋簷下面，怎麼畫了一排桃子形狀的框框？"},{"who":"A","text":"好眼力！檐板彩繪用五個桃形當畫框，裡面畫水果、珊瑚和牡丹，全是吉祥寓意。"},{"who":"R","text":"看得我都餓了，好想馬上吃一顆桃子！"},{"who":"A","text":"我比較想吃燒餅。這間是張家人到檳城工作賺錢，回沙美蓋的二落大厝，清光緒5年完工。"},{"who":"R","text":"檳城？是在馬來西亞那個檳城嗎？"},{"who":"A","text":"對，就是那裡。旁邊還有一棟是同一家人蓋的，兩棟用隘門連在一起，門上還有花瓶欄杆。"},{"who":"R","text":"兩棟房子手牽手，好有愛！那窗戶上的字寫什麼？"},{"who":"A","text":"一邊是畫閣雕軒，一邊是竹苞松茂，祝福家宅華美、子孫興旺。這是私人住宅，我們在外面看就好。"},{"who":"R","text":"那我來數數，檐板上的桃形框框是不是真的剛好五個！"}],"clues":["我的檐板彩繪用桃子當畫框","我和隔壁鄰棟用一道隘門牽手","沙美聚落裡，檳城僑匯興建、清光緒5年竣工的大厝"],"quiz":[{"q":"古厝的起造人曾到哪裡工作？","options":["長崎","馬尼拉","檳城","勿里洞"],"answer":2,"explain":"張氏赴檳城工作後，於清末返鄉建造。"},{"q":"檐板彩繪以什麼形狀為外框？","options":["桃形","扇形","葫蘆形","八角形"],"answer":0,"explain":"檐板一邊以五個桃型為外框，內繪吉祥主題。"}],"images":[]},{"id":"jinsha-chenmingyougucuo","name":"陳明侑古厝","short":"陳明侑古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48587,"lng":118.44033,"address":"金門縣金沙鎮碧山69號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/fe644dd1-d440-45f9-ae14-58bf25840a2d/陳明侑古厝_封面.jpg","year":1880,"yearText":"清代（確切年代不詳）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"門兩邊高度不同、疑為對場作的一落四櫸頭","intro":"陳明侑古厝位於金沙鎮碧山聚落，建於清代，是一座一落四櫸頭的閩南古厝。屋主的祖父曾在新加坡經營「九八行」，這種貿易行因抽取2%利潤而得名；他原本打算把古厝翻修成兩落，卻在四十多歲過世，計畫沒有實現。大門兩邊高度不同，研究推測是兩位匠師各做一邊的「對場作」。古厝四面牆以花崗石人字砌，轉角作水平「聖旨砌」，入口牆規樓門楣上有泥塑彩繪，內壁有八角配十字磚雕。民國38至47年間曾駐紮多種兵種，也當過彈藥倉庫；民國105年莫蘭蒂颱風損及屋頂，民國107年由縣文化局修繕。","highlights":["大門兩側高度不一，疑為兩匠師的對場作","牆規樓門楣上方的泥塑彩繪","四面花崗石人字砌與轉角聖旨砌"],"funFact":"「九八行」是新加坡的貿易行，因為抽取2%的利潤而得名，屋主的祖父就是靠它打下家業。","photoSpot":"正面拍牆規樓，比較大門左右高低","visitMin":10,"openNote":"位於金沙鎮碧山聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。官方資料註明白天可在外觀欣賞。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，你看這扇大門，左邊跟右邊的高度好像不一樣耶，是蓋歪了嗎？"},{"who":"A","text":"觀察力滿分！研究推測這是「對場作」，就是請兩位匠師各蓋一邊，互相較勁。"},{"who":"R","text":"兩個師傅比賽蓋房子？那最後誰贏了？"},{"who":"A","text":"勝負沒人知道，但比賽留下的高低差就成了最好的證據。這座一落四櫸頭是清代蓋的。"},{"who":"R","text":"那這座古厝的屋主家族是做什麼的？"},{"who":"A","text":"屋主的祖父在新加坡開「九八行」，抽百分之2的利潤，原本想把古厝翻修成兩落，可惜四十多歲就過世了。"},{"who":"R","text":"抽百分之2就能蓋房子？那我以後幫Allan買蚵仔麵線，也要抽百分之2的跑腿費！"},{"who":"A","text":"你是要抽我碗裡的蚵仔吧！這裡還住著人，我們在外面看就好。比比看，大門左右兩邊到底差多少？"}],"clues":["我的大門左右高度不同，可能是兩位匠師較勁的結果","我的主人家族曾在新加坡開九八行，原本想把我改成兩落","碧山一座清代一落四櫸頭，曾當過彈藥倉庫"],"quiz":[{"q":"「九八行」這個名稱是怎麼來的？","options":["開業於98年","抽取2%的利潤","有98位員工","有98個房間"],"answer":1,"explain":"九八行是新加坡貿易行，以抽取2%利潤而得名。"},{"q":"大門兩邊高度不同，研究推測原因是什麼？","options":["地震造成傾斜","颱風損壞重修","兩位匠師對場作","國軍改建"],"answer":2,"explain":"推測由兩位匠師分兩邊施作，即「對場作」。"}],"images":[]},{"id":"jinsha-chenweidangucuo","name":"陳維淡古厝","short":"陳維淡古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48638,"lng":118.44318,"address":"金門縣金沙鎮碧山4號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-28/b7831cd3-2381-40c2-80e8-db5abcf58727/01封面.jpg","year":1880,"yearText":"清代（確切年代不詳）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"山牆開柳條花窗的碧山清代一落二櫸頭","intro":"陳維淡古厝位於金沙鎮碧山聚落，創建於清代，是一座一落二櫸頭的小型閩南古厝。四面牆以花崗石人字砌，轉角作水平聖旨砌；正立面圓脊牆規為傳統煙炙磚砌，櫸頭兩側砌有煙炙磚女兒牆。側面大規壁為傳統斗砌磚牆，規尾開有柳條花窗，並以鳥踏分隔下方的花崗石牆身。屋頂為雙坡翹脊，後牆與後方另一座一落二櫸頭相連。正身鏡面上緣為木作，窗額作木格扇雕花，正廳是穿鬥式木棟架，內部儉樸。古厝曾有國軍佔用，民國50至60年代間翻修，前埕加蓋鐵皮屋、櫸頭改為鋼筋混凝土。官方認為它表現了地域風貌與民間藝術特色。","highlights":["側面大規壁規尾的柳條花窗","四面花崗石人字砌牆","與後方古厝相連的後牆"],"funFact":"這座古厝的後牆和後方另一座一落二櫸頭連在一起，像兩戶人家背靠背坐著。","photoSpot":"從側面拍大規壁與柳條花窗","visitMin":10,"openNote":"位於金沙鎮碧山聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，碧山的大洋樓看多了，今天來看一間小巧的清代古厝。"},{"who":"R","text":"它真的比較小，前面還加了鐵皮屋，看起來好樸素。"},{"who":"A","text":"這叫一落二櫸頭，是金門古厝裡比較精簡的格局。不過小歸小，牆面可是很講究。"},{"who":"R","text":"哪裡講究？我只看到一堆斜斜的石頭。"},{"who":"A","text":"那些石頭斜斜排成人字形，叫人字砌，轉角改成水平排列，叫聖旨砌，四面都是這樣砌。"},{"who":"R","text":"原來排石頭也有學問，比我排積木認真多了！"},{"who":"A","text":"還有喔，它的後牆跟後面另一間古厝連在一起，像兩戶人家背靠背坐著聊天。"},{"who":"R","text":"背靠背的鄰居，冬天應該比較溫暖吧！"},{"who":"A","text":"說不定喔。這裡有人住，我們在外面看就好。繞到側面，找找山牆尾端那扇柳條花窗！"}],"clues":["我的後牆和後方另一座古厝背靠背相連","我的山牆尾端開著一扇柳條花窗","碧山一座清代的一落二櫸頭，前埕加蓋了鐵皮屋"],"quiz":[{"q":"陳維淡古厝的平面格局是哪一種？","options":["一落二櫸頭","一落四櫸頭","二落大厝","五腳基洋樓"],"answer":0,"explain":"平面格局為一落二櫸頭。"},{"q":"古厝側面大規壁的規尾開有什麼窗？","options":["八卦窗","柳條花窗","鑄鐵花窗","彩色玻璃窗"],"answer":1,"explain":"側立面大規壁規尾做柳條花窗。"}],"images":[]},{"id":"jinsha-zhaolinggong","name":"昭靈宮","short":"碧山昭靈宮","category":"歷史建築","level":"","town":"金沙鎮","types":["寺廟"],"lat":24.48632,"lng":118.44245,"address":"金門縣金沙鎮碧山38號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/7bd9c134-9f3f-4b5a-91be-2267d1d2b938/昭靈宮_封面.jpg","year":1884,"yearText":"1884年（清光緒10年）","era":"qing","themes":["宗教信仰"],"yearUnknown":false,"summary":"碧山村唯一廟宇，主祀田府元帥","intro":"昭靈宮位於金沙鎮碧山村，建於清光緒10年（1884），由碧山陳姓宗親合資興建，是村內唯一的廟宇，反映濃厚的地方信仰色彩，民國63年（1974）曾重修。宮內主祀田府元帥（大相江爺），從祀二相、三相江爺，以及金府王爺、媽祖、廣澤尊王，左右陪祀註生娘娘與福德正神。每年農曆九月十五日為田府元帥聖誕，當天設醮。建築為一落帶四架捲棚拜廳，側牆以花崗石作人字砌、轉角以聖旨砌收邊；正面榻受的水車堵繪有雙龍搶珠，龍虎堵也有泥塑彩繪，門旁石櫺窗四周有聯對與橫批。","highlights":["水車堵上的雙龍搶珠彩繪","側牆花崗石人字砌與轉角聖旨砌","門旁石櫺窗與「昭明仁武威鎮碧境」聯對"],"funFact":"宮內同時供奉三位田府元帥，信眾分別稱為大相、二相、三相江爺。","photoSpot":"在廟埕拍榻受水車堵與門額","visitMin":15,"openNote":"位於金沙鎮碧山村，官方資料標示全日開放。參拜請尊重廟方規矩；農曆九月十五日田府元帥聖誕設醮，活動以廟方公告為準。可開車、騎機車前往。","dialogue":[{"who":"A","text":"走進碧山村，阿拉蕾，你猜這村子裡有幾間廟？"},{"who":"R","text":"金門的廟那麼多，這裡至少有三間吧？"},{"who":"A","text":"只有一間，就是昭靈宮！清光緒10年由碧山陳姓宗親合資蓋的，是全村的信仰中心。"},{"who":"R","text":"一村一廟，好專一！裡面拜的是誰呀？"},{"who":"A","text":"主神是田府元帥，大家稱大相江爺，還有二相、三相江爺一起坐鎮，另外也有媽祖、廣澤尊王。"},{"who":"R","text":"三位江爺一起坐鎮，陣容好堅強！那什麼時候最熱鬧？"},{"who":"A","text":"農曆九月十五是田府元帥聖誕，當天會設醮。參拜完，我一定去找盤熱騰騰的炒泡麵。"},{"who":"R","text":"Allan，你的信仰中心大概是小吃攤吧！"},{"who":"A","text":"被你說中了。到現場抬頭看榻受上方，找找那兩條在搶珠子的龍，看看珠子在誰那邊！"}],"clues":["我是一個村子裡唯一的廟宇","我供奉大相、二相、三相三位元帥","碧山村陳姓宗親在清光緒10年合資興建的廟"],"quiz":[{"q":"昭靈宮主祀哪一位神明？","options":["保生大帝","關聖帝君","田府元帥","清水祖師"],"answer":2,"explain":"主奉田府元帥，信眾稱大相江爺。"},{"q":"田府元帥聖誕是農曆哪一天？","options":["三月二十三","九月十五","七月十五","正月初九"],"answer":1,"explain":"聖誕日為農曆九月十五日，此日設醮。"}],"images":[]},{"id":"jincheng-chengnanmenchuan","name":"金門城南門傳統建築群","short":"南門建築群","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40038,"lng":118.30577,"address":"金門縣金城鎮金門城57、58、62、63號","announced":"2011-10-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20111031000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-18/f5f2550f-0add-4606-9d45-21b2693f94c9/1.jpg","year":1885,"yearText":"約1880年代（清光緒年間）","era":"qing","themes":["閩南古厝","聚落地景"],"yearUnknown":false,"summary":"陳氏三兄弟同心興建的新厝埕院落","intro":"金門城南門傳統建築群位於金城鎮金門城聚落南隅，由陳、王兩姓的四棟古厝組成。清同治年間陳清白赴印尼峇里島經營咖啡原料，累積財富後於光緒年間僑匯回鄉，由三弟陳清泉策劃，依長幼次序請不同匠師興建三幢宅邸，分屬清白、清塔、清泉三兄弟。宅前內埕稱「新厝埕」，加上牆規、門樓與後牆隘門，形成完整的防禦院落。王氏古厝原為一落四櫸頭，戰後遭砲彈擊中五次，1967年重建為二落大厝。2016至2018年完成整體修復。","highlights":["陳清白古厝前落屋脊的螭虎、花鳥剪黏與交趾陶","陳清泉古厝精細的磚雕與鳳、花籃木雕插角","牆規、門樓與後牆隘門合圍的新厝埕"],"funFact":"1970年陳家買了黑白電視，對著門口埕播放，鄰居擠得人滿為患。","photoSpot":"在埕外拍四棟古厝並排的屋脊","visitMin":20,"openNote":"位於金城鎮金門城聚落南側。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；官方資料記載其中三棟不開放，另一棟修復後作為民宿使用，可依業者時間預約參觀。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，來猜謎，三兄弟一起蓋房子，最怕什麼？"},{"who":"R","text":"是怕分房間的時候，兄弟會吵架嗎？"},{"who":"A","text":"答對一半！金門城南門的陳家三兄弟感情好，依長幼次序各蓋一幢，還各請不同匠師。"},{"who":"R","text":"好有默契！蓋房子的錢是從哪裡來的呀？"},{"who":"A","text":"大哥陳清白在清同治年間到印尼峇里島做咖啡原料生意，光緒年間把錢寄回來，由三弟陳清泉策劃。"},{"who":"R","text":"咖啡蓋出來的古厝，聞起來會不會香香的？"},{"who":"A","text":"哈，香的是剪黏和木雕的手藝啦。宅前內埕叫新厝埕，有牆規、門樓和後牆隘門，是一個防禦院落。"},{"who":"R","text":"那旁邊的第四棟古厝又是誰家的呢？"},{"who":"A","text":"那是王家古厝，戰後曾遭砲彈擊中，1967年重建。這裡是私人住宅，請在埕外比比看，四棟的屋脊哪一棟最翹！"}],"clues":["我由一位在峇里島做咖啡原料生意的華僑出資興建","三兄弟依長幼次序各蓋一幢，宅前內埕叫新厝埕","我們在金門城南隅，由陳、王兩姓四棟古厝組成"],"quiz":[{"q":"陳清白在印尼經營什麼生意？","options":["咖啡原料","橡膠","錫礦","香料"],"answer":0,"explain":"陳清白在峇里島專營咖啡原料，累積財富後僑匯回鄉。"},{"q":"三兄弟宅前的內埕被稱為什麼？","options":["舊厝埕","陳家埕","新厝埕","大公埕"],"answer":2,"explain":"宅前留有內埕，被稱為新厝埕。"}],"images":[]},{"id":"jinning-jinshentang","name":"謹慎堂","short":"謹慎堂","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.479497,"lng":118.306323,"address":"金門縣金寧鄉古寧村南山102、103號","announced":"2003-12-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031222000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-24/4de0d712-4456-4ccd-a6e4-6a4c84d97e85/01.jpg","year":1885,"yearText":"約1880年代（清光緒年間）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"醫者獲贈門匾得名的古寧南山三落大厝","intro":"謹慎堂位於金寧鄉古寧村南山聚落，建於清光緒年間，由李家兄弟興建。兄弟中有人行醫，因醫治病患而獲贈「謹慎堂」門匾，宅名由此而來。建材講究，木料由漳州運來、石材由石碼運來。建築為三落雙突歸的大型格局，軸線依序為前廳、深井、大廳、深井、後廳；前落牆身上段磚砌抹灰、下段石條平砌，側牆下段為石塊人字砌。戰時曾有部隊駐紮，牆面被裹上海土而受損。目前前落屋頂破損、中落已嚴重坍塌，後落改以水泥與鐵皮修建，是一座需要好好守護的老厝。","highlights":["第一落正門上方因行醫獲贈的「謹慎堂」門匾","第一落翹脊與第三落圓脊的不同屋脊樣式","側牆下段的石塊人字砌，排列像魚骨"],"funFact":"蓋這棟房子的木料來自漳州、石材來自石碼，都是隔著海一船一船運到古寧頭來的。","photoSpot":"在屋前拍第一落翹脊與門匾","visitMin":15,"openNote":"位於金寧鄉古寧村南山聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；中落已坍塌，請勿靠近危險處。可搭金門縣公車或騎機車前往古寧頭一帶。","dialogue":[{"who":"R","text":"Allan，這間門上寫著「謹慎堂」，屋主是不是個超級小心的人？"},{"who":"A","text":"哈，猜對一半！清光緒年間李家兄弟蓋了這座大厝，其中一位是醫生，看好病人，對方送了這塊匾。"},{"who":"R","text":"所以謹慎是在說醫生看病很仔細？比你點小吃還仔細嗎？"},{"who":"A","text":"我點石蚵麵線也很謹慎啊，要加醋還是加辣，得想三秒。言歸正傳，這裡的木料是從漳州運來，石材來自石碼。"},{"who":"R","text":"哇，蓋房子還要跨海進口，那它的格局一定很大吧？"},{"who":"A","text":"是三落雙突歸，從前廳、深井、大廳一路走到後廳，可惜戰時部隊進駐，牆被裹上海土，中落現在也坍塌了。"},{"who":"R","text":"好心疼喔，那我們只能在外面看，不可以進去打擾。"},{"who":"A","text":"沒錯，這是私人住宅。請你在屋外找找第一落的紅瓦翹脊，再看看側牆像魚骨一樣的人字砌。"}],"clues":["我的木料來自漳州、石材來自石碼","我是三落雙突歸大厝，中落已經坍塌","我在古寧村南山，門匾是醫生行醫獲贈的"],"quiz":[{"q":"謹慎堂的門匾是怎麼來的？","options":["科舉中舉後官府頒贈","南洋經商成功自題","醫治病患後獲贈","宗族祭祖時共同立匾"],"answer":2,"explain":"興建的李家兄弟中有人行醫，醫治病患後獲贈此匾。"},{"q":"謹慎堂的木料是從哪裡運來的？","options":["泉州","漳州","廈門","福州"],"answer":1,"explain":"官方資料記載木料由漳州運來，石材由石碼運來。"}],"images":[]},{"id":"jinsha-zhangshisanluoda","name":"張氏三落大厝","short":"張氏三落大厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.4923,"lng":118.41259,"address":"金門縣金沙鎮沙美104、108號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000022","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-20/396e9f89-337b-41a0-9333-de1ad00157a0/(1)封面.jpg","year":1885,"yearText":"約清末（19世紀後期）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"門額「福星高照」的沙美三落大厝","intro":"張氏三落大厝位於金沙鎮沙美聚落，建於清末，由家族父輩四兄弟合力賺錢興建，供家族居住。平面為三落大厝，第三落左側另有突歸，右側設隘門，三落屋脊都是翹脊，屋面兩端各有三條筒瓦。入口大門以石板作門框，上方門印石刻精美，門額題「福星高照」，是這棟古厝最醒目的特徵，官方說明與縣定古蹟西山前李宅同為李愈所題。第二落巷頭採「大展步」格局，加大縱深與巷頭寬度。戰爭時期曾有國軍駐紮，八二三砲戰波及此宅，牆身留下多處傷痕，前後整修過三次。目前第二落正廳仍作祭祀。","highlights":["門額「福星高照」四字與精美門印石刻","三落大厝加第三落左突歸的格局","牆身留下的八二三砲戰傷痕"],"funFact":"第二落巷頭採「大展步」作法，把空間往外推，讓第二落更深、巷頭更寬。","photoSpot":"在前埕正面拍「福星高照」門額","visitMin":15,"openNote":"位於金沙鎮沙美聚落，部分屋頂破損。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，一般古厝是一落、兩落，你猜這間有幾落？"},{"who":"R","text":"看它從前面到後面這麼長，至少三落吧？"},{"who":"A","text":"答對了！這是清末四兄弟合力賺錢蓋的三落大厝，讓整個家族一起住。"},{"who":"R","text":"四兄弟一起蓋房子，不會吵架嗎？"},{"who":"A","text":"吵架的事沒寫進資料，不過門額寫著福星高照，大家一定希望好運一起來。官方說這四個字和西山前李宅同出一人手筆。"},{"who":"R","text":"Allan，牆上那些坑坑洞洞是什麼留下的？"},{"who":"A","text":"那是八二三砲戰留下的痕跡。當年國軍駐紮在這裡，砲火波及古厝，前後修了三次，這些傷痕提醒我們戰爭的代價。"},{"who":"R","text":"原來一面牆，也會默默記得那段歷史。"},{"who":"A","text":"第二落現在還在祭祀，請在外面安靜參觀。繞到側面數數看，這裡總共有幾道翹脊？"}],"clues":["我是四兄弟合力蓋起來的家","我的門額寫著「福星高照」","沙美聚落裡，有三進屋落的閩南大厝"],"quiz":[{"q":"這座大厝的門額題著哪四個字？","options":["福星高照","紫微拱照","詩禮傳家","竹苞松茂"],"answer":0,"explain":"入口門額題「福星高照」，是最明顯的特徵。"},{"q":"這座大厝是由誰合力興建？","options":["父子三人","四兄弟","同村商人","旅日商號"],"answer":1,"explain":"由家族父輩四兄弟合力賺錢建造。"}],"images":[]},{"id":"jinsha-zhangshigucuo","name":"張氏古厝","short":"沙美張氏古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49211,"lng":118.41207,"address":"金門縣金沙鎮沙美111、111-1號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/f63717a1-e950-4309-840c-194828989906/張氏古厝_封面.jpg","year":1885,"yearText":"約清末（19世紀後期）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"護龍加疊樓、牆留彈孔的多戶共居古厝","intro":"這座張氏古厝位於金沙鎮沙美聚落，興建於清末，完工後由同宗張氏族人多家共同居住。建築為「三蓋廊」加左護龍，護龍上另加建疊樓，採傳統瓦作雙坡屋面。前落榻受牆下緣為封堵石、上緣抹成磚紅色，左護龍則是紅磚斗砌；護龍女兒牆以煙炙磚疊成十字鏤空，背面女兒牆用綠釉花磚。八二三砲戰前已有國軍駐紮，砲戰時古厝遭彈藥擊中，牆身留下多處彈孔；民國50年代曾整修，榻受牆上至今隱約可見「一九六O」字樣。目前閒置，僅作祭祀，部分屋頂坍塌。","highlights":["左護龍上加建的疊樓","護龍十字鏤空女兒牆與背面綠釉花磚","榻受牆上依稀可辨的「一九六O」字跡"],"funFact":"這座古厝不是一戶獨居，而是蓋好後就讓好幾戶同宗張氏族人一起住。","photoSpot":"拍左護龍疊樓與十字鏤空女兒牆","visitMin":10,"openNote":"位於金沙鎮沙美聚落，部分屋頂坍塌。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"R","text":"Allan，沙美這一帶怎麼這麼多張氏古厝，我都要搞混了！"},{"who":"A","text":"張氏是沙美的大姓嘛。認這一間的小撇步，就是左邊護龍上面多長了一層疊樓。"},{"who":"R","text":"疊樓我知道，就是古厝版的加蓋二樓！"},{"who":"A","text":"沒錯。這間清末蓋好以後，是好幾戶張氏族人一起住，有點像古早的家族公寓。"},{"who":"R","text":"那一定很熱鬧，晚餐可以吃百家菜！"},{"who":"A","text":"你跟我一樣滿腦子都是吃，我現在就很想來碗廣東粥。不過這裡也見證過戰火，八二三砲戰時牆身被彈藥擊中，留下不少彈孔。"},{"who":"R","text":"那些洞是真的子彈打的，看了好心疼。"},{"who":"A","text":"民國50年代修過一次，正面牆上還隱約看得到寫著1960的字跡。現在閒置僅供祭祀，在外面看就好。"},{"who":"R","text":"收到！那我來找找，那幾個褪色的數字藏在牆上哪裡。"}],"clues":["我的左護龍上多了一層疊樓","我的牆上依稀寫著「一九六O」","沙美聚落裡，清末由多戶同宗族人共住的古厝"],"quiz":[{"q":"這座古厝的哪個部位加建了疊樓？","options":["前落榻受","後落正廳","左護龍","右櫸頭"],"answer":2,"explain":"建築為三蓋廊加左護龍，護龍加建疊樓。"},{"q":"古厝牆身的彈孔來自哪一場戰事？","options":["古寧頭戰役","八二三砲戰","九三砲戰","抗戰時期"],"answer":1,"explain":"八二三砲戰爆發時遭彈藥擊中，牆身留有彈孔。"}],"images":[]},{"id":"jincheng-dafudi","name":"大夫第","short":"珠山大夫第","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40106,"lng":118.32165,"address":"金門縣金城鎮珠山41號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000029","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/855f1487-5dd2-4853-862b-9be569be90db/1.jpg","year":1890,"yearText":"清代末年（確切年代待考）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"呂宋經商致富的薛紹纘捐官後興建的二落大厝","intro":"大夫第位於金城鎮珠山聚落，建於清代末年。興建者薛紹纘在呂宋（菲律賓）經商致富，捐得大夫官職後大興土木，蓋了這座大夫第與「上書房」等建築，並在門額高懸「大夫第」匾額光耀門楣。建築是二落大厝帶雙護龍，規模宏大；二落屋脊為翹脊並飾剪黏，護龍為圓脊。正立面下半部是石砌、上半部以磚雕裝飾，榻受牆有幾何圖樣磚雕，插角雕有花鳥彩繪木雕，櫃臺腳、門箱等石雕也很精美。2000年由金門國家公園管理處完成整體修復，之後作為民宿使用。官方說明詳細歷史仍待日後深入調查。","highlights":["門額高懸的「大夫第」匾額","榻受牆上的幾何圖樣磚雕與花鳥插角","二落翹脊上的剪黏與右護龍脊墜泥塑"],"funFact":"薛紹纘在呂宋經商致富後捐了大夫官職，除了大夫第，還興建了「上書房」等建築。","photoSpot":"珠山巷道中拍「大夫第」門額與翹脊","visitMin":15,"openNote":"位於金城鎮珠山聚落，修復後作為民宿使用，開放情形依經營者規定；非住宿者請在外觀參觀，勿擅入、勿打擾住客。可騎機車或開車前往珠山聚落。","dialogue":[{"who":"R","text":"Allan，門上寫著大夫第，所以這裡以前住過一位醫生嗎？"},{"who":"A","text":"此大夫非彼大夫！這裡的大夫是官銜。珠山的薛紹纘在呂宋，也就是菲律賓經商致富，捐了大夫的官職。"},{"who":"R","text":"原來官職可以用捐的？那這間房子就是他升官的紀念品囉？"},{"who":"A","text":"可以這麼說。他在清代末年大興土木，蓋了這座大夫第，還有上書房等建築，再把匾額高高掛上。"},{"who":"R","text":"好氣派！那這座大夫第到底有多大？"},{"who":"A","text":"二落大厝帶雙護龍，規模宏大。正面磚雕是幾何圖樣，插角雕著花鳥，石雕櫃臺腳也很精緻。"},{"who":"R","text":"那現在這座古厝還有人住在裡面嗎？"},{"who":"A","text":"2000年金門國家公園管理處修復後，作為民宿使用，所以請在外面欣賞，不要打擾住客。"},{"who":"A","text":"任務來了，請站在巷道裡看正面的幾何磚雕，找找看有沒有重複出現的圖案！"}],"clues":["我的主人在呂宋經商致富，捐了官職","我是二落大厝帶雙護龍，2000年由國家公園修復","我在珠山聚落，門額高懸以官銜為名的匾額"],"quiz":[{"q":"興建者薛紹纘在哪裡經商致富？","options":["新加坡","印尼","呂宋","日本"],"answer":2,"explain":"薛紹纘於呂宋，也就是菲律賓經商致富。"},{"q":"「大夫第」的「大夫」指的是什麼？","options":["醫生","官銜","教書先生","船長"],"answer":1,"explain":"大夫是官銜，薛紹纘致富後捐得大夫官職。"}],"images":[{"file":"金門珠山大夫第.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/35/%E9%87%91%E9%96%80%E7%8F%A0%E5%B1%B1%E5%A4%A7%E5%A4%AB%E7%AC%AC.jpg/960px-%E9%87%91%E9%96%80%E7%8F%A0%E5%B1%B1%E5%A4%A7%E5%A4%AB%E7%AC%AC.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E7%8F%A0%E5%B1%B1%E5%A4%A7%E5%A4%AB%E7%AC%AC.jpg","artist":"張雅倫","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-dafudi-0.webp","small":"img/jincheng-dafudi-0-s.webp"}]},{"id":"jincheng-chenshigucuo","name":"陳氏古厝","short":"庵前陳氏古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.4195,"lng":118.32088,"address":"金門縣金城鎮庵前11號","announced":"2007-01-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20070119000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-20/eb4a980e-64e6-4725-a578-b5153250c9be/01封面.jpg","year":1890,"yearText":"約清末（19世紀末）","era":"qing","themes":["閩南古厝","戰地史蹟"],"yearUnknown":false,"summary":"曾當發電廠與理髮廳的庵前古厝","intro":"陳氏古厝位於金城鎮庵前聚落，約建於清末。起造人原本只蓋二落大厝，因家族人口多、經費有餘才增建護龍，但護龍並未完工，紅磚牆至今沒有抹灰。1949年庵前是防衛司令官辦公處所，古厝被國軍借作臨時發電廠，大廳擺放柴油發電機，當時金門島上只有庵前在夜晚有供電。由於駐有重兵，1960年代護龍曾開設理髮廳，直到戰地政務終止、駐軍大減才停業，約1991年起閒置。屋頂為翹脊，水車堵堵頭仍留有書本、書卷造型泥塑。","highlights":["沒有抹灰、露出紅磚的未完工左護龍","水車堵堵頭的書本與書卷造型泥塑","拱仔頭殘存的山水泥塑"],"funFact":"1949年大廳曾擺柴油發電機，當時金門島上只有庵前在夜晚有電可用。","photoSpot":"在前埕外拍翹脊大厝與紅磚護龍","visitMin":10,"openNote":"位於金城鎮庵前聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；古厝目前閒置未開放。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這棟古厝旁邊的牆是紅磚的，怎麼沒有抹灰？是還沒裝潢好嗎？"},{"who":"A","text":"被你說中了！陳氏古厝蓋好二落大厝後加蓋護龍，結果護龍沒完工，紅磚就一直露在外面。"},{"who":"R","text":"原來是未完成的作品，好像我的暑假作業。"},{"who":"A","text":"哈哈，你的作業可沒當過發電廠。1949年國軍借用這裡，在大廳擺了柴油發電機。"},{"who":"R","text":"發電廠？真的在古厝裡面發電嗎？"},{"who":"A","text":"對，當時庵前是防衛司令官辦公的地方，金門島上只有庵前晚上有電，這裡功不可沒。"},{"who":"R","text":"那旁邊沒完工的護龍又做過什麼？"},{"who":"A","text":"1960年代這裡駐有重兵，護龍開過理髮廳，阿兵哥來理平頭，我這顆光頭倒是省了這筆錢。"},{"who":"A","text":"到現場請找找水車堵兩端的泥塑，看看能不能認出書本和書卷的造型！"}],"clues":["我的護龍沒完工，紅磚牆至今沒有抹灰","我曾當過臨時發電廠，後來護龍開過理髮廳","我在庵前聚落，是清末的二落大厝加左護龍"],"quiz":[{"q":"1949年古厝大廳曾擺放什麼？","options":["印刷機","電報機","柴油發電機","戲台布景"],"answer":2,"explain":"國軍借作臨時發電廠，在大廳擺放柴油發電機。"},{"q":"1960年代古厝護龍曾開設什麼店？","options":["理髮廳","雜貨店","冰果室","撞球間"],"answer":0,"explain":"庵前駐有重兵，護龍在1960年代曾作理髮廳。"}],"images":[]},{"id":"jincheng-huangkuanyongzhai","name":"黃寬永宅","short":"黃寬永宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43304,"lng":118.31874,"address":"金門縣金城鎮珠浦北路11、11-1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000056","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/c4f12885-3511-4526-8a1b-a88cbbf7a5c6/01封面.jpg","year":1890,"yearText":"約清末（19世紀末）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"菲律賓經商致富的後浦二落大厝","intro":"黃寬永宅位於金城鎮後浦市區珠浦北路，建於清末，是黃寬永到菲律賓經商致富後返鄉興建。格局為二落大厝加右護龍，深井與過水廊各有一口古井。正面榻受的交趾陶裝飾豐富：對看堵以四季博古為題，頂堵左為松鶴、右為竹鹿，身堵以花鳥搭配石榴與佛手，寓意多子多孫與長壽福氣。門額有「紫雲衍派」堂號，門簪可見石雕。部分拱仔頭與水車堵裝飾已佚失，屋頂與木構也有破損，官方評估建築整體受損嚴重，詳細沿革仍待調查。","highlights":["榻受頂堵左松鶴、右竹鹿的交趾陶","身堵花鳥配石榴與佛手的吉祥寓意","門額「紫雲衍派」堂號與石雕門簪"],"funFact":"身堵交趾陶的石榴象徵多子多孫，佛手寓意福氣長壽，一面牆塞滿祝福。","photoSpot":"在對街拍榻受交趾陶，勿靠近破損處","visitMin":10,"openNote":"位於金城鎮後浦市區珠浦北路。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築破損，請勿靠近。可搭金門縣公車到金城車站後步行前往。","dialogue":[{"who":"A","text":"在熱鬧的後浦街上，也藏著一棟清末古厝，屋主黃寬永是到菲律賓經商致富的。"},{"who":"R","text":"菲律賓？我以為金門人都去印尼或新加坡！"},{"who":"A","text":"金門人落番的地方很多，菲律賓也是其中之一。他賺了錢回鄉，蓋了二落大厝加右護龍。"},{"who":"R","text":"門口那些彩色的小人物和動物好可愛！"},{"who":"A","text":"那是交趾陶，頂堵左邊松鶴、右邊竹鹿，身堵還有石榴和佛手，祝福多子多孫、長壽有福。"},{"who":"R","text":"一面牆就塞滿這麼多祝福，簡直是立體賀卡！"},{"who":"A","text":"說得好！可惜部分裝飾已經佚失，屋頂也破損了，官方說受損嚴重，更值得好好記錄。"},{"who":"R","text":"那我們看的時候要小心，不要靠太近。"},{"who":"A","text":"對，請在外面欣賞就好。找找看榻受頂堵，左邊的鶴和右邊的鹿，哪一隻看起來比較有精神？"}],"clues":["我的主人到菲律賓經商致富，清末返鄉建屋","我的頂堵交趾陶左邊是松鶴、右邊是竹鹿","我位於後浦市區珠浦北路，是二落大厝加右護龍"],"quiz":[{"q":"黃寬永到哪裡經商致富？","options":["菲律賓","印尼","新加坡","馬來西亞"],"answer":0,"explain":"黃寬永到菲律賓經商，賺錢致富後返鄉興建。"},{"q":"榻受頂堵左側的交趾陶主題是？","options":["竹鹿","雙獅","松鶴","鯉魚"],"answer":2,"explain":"頂堵左側為松鶴、右側為竹鹿。"}],"images":[]},{"id":"jinhu-lvkepinggucuo","name":"呂克瓶古厝","short":"呂克瓶古厝","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.42757,"lng":118.44597,"address":"金門縣金湖鎮東村35號","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000012","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-28/3468c6d7-1253-4c3c-9fdf-3396cba86a96/01封面.jpg","year":1890,"yearText":"約1890年代（清光緒年間）","era":"qing","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"印尼橡膠致富的僑匯大厝，藏著遺產風波","intro":"呂克瓶古厝位於金湖鎮東村聚落。呂克瓶四歲喪父，婚後因母喪與家鄉謀生不易，遠赴印尼採集橡膠致富，約五十歲返鄉興建此宅，並把南洋產業交給兒子呂明欽。呂明欽36歲過世，獨子呂瑞生才9歲，因當地法令須滿16歲才能繼承，產業被另一房家人取得，呂瑞生隨母親回到金門，成年後曾赴印尼想取回而未果。1949至1954年左護龍曾借給國軍師部、團部使用，2003年整修。古厝為二落大厝加左護龍，左後側起疊樓，正面用黃花崗石，大廳正面用泉州白石，疊樓規壁上還有太陽造形泥塑。","highlights":["左護龍疊樓左側規壁上的太陽造形泥塑","正面黃花崗石與大廳泉州白石的不同石材","後落鏡面牆與疊樓二層正面的聯對"],"funFact":"呂家的南洋遺產因當地須滿16歲才能繼承的法令，被另一房家人取得，9歲的孫子只能回金門。","photoSpot":"在屋側拍疊樓規壁上的太陽泥塑","visitMin":10,"openNote":"位於金湖鎮東村聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。","dialogue":[{"who":"R","text":"Allan，這間古厝側邊的牆上有一個太陽圖案，好像在對我們笑耶！"},{"who":"A","text":"那是疊樓規壁上的太陽泥塑，是這棟呂克瓶古厝的招牌。不過屋主家的故事，可沒有太陽這麼燦爛。"},{"who":"R","text":"怎麼說？他不是去南洋發大財了嗎？"},{"who":"A","text":"呂克瓶在印尼採橡膠致富，大約五十歲回來蓋了這座二落大厝，再把南洋的生意交給兒子。"},{"who":"R","text":"聽起來是個圓滿結局啊，後來出了什麼事？"},{"who":"A","text":"兒子36歲就過世，孫子才9歲。當地法令要滿16歲才能繼承，南洋的產業就被另一房家人拿走了。"},{"who":"R","text":"天啊，這個劇情比八點檔連續劇還曲折！"},{"who":"A","text":"孫子長大後去印尼想討回來，最後沒成功。請你在屋外找到那個太陽泥塑，幫它拍一張大頭照。"}],"clues":["我的主人在印尼採橡膠致富，家族遺產卻因繼承法令落入他人之手","我的疊樓規壁上有太陽造形的泥塑","我是東村一座二落大厝加左護龍的古厝"],"quiz":[{"q":"呂克瓶在南洋從事什麼工作致富？","options":["開設錢莊","橡膠採集","經營航運","種植咖啡"],"answer":1,"explain":"呂克瓶前往印尼從事橡膠採集工作致富。"},{"q":"古厝疊樓左側規壁上有什麼造形的泥塑？","options":["月亮","風獅爺","蝙蝠","太陽"],"answer":3,"explain":"左護龍疊樓左側規壁有太陽造形泥塑。"}],"images":[]},{"id":"jinhu-chenzhenliuludacuo","name":"陳酙六路大厝","short":"陳酙六路大厝","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.43965,"lng":118.38894,"address":"金門縣金湖鎮成功120號","announced":"2007-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071009000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-23/d877ef7b-28c8-40f7-bc9c-b18283b9c3f1/陳酉科六路大厝.jpg","year":1890,"yearText":"清光緒年間（約1875–1908年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"越南行醫致富返鄉蓋的六路大厝","intro":"陳酙六路大厝位於金湖鎮成功聚落（舊稱陳坑）。陳酙幼年家貧，向鄉人學醫，後隨清道光22年（1842）以後的移民潮前往越南，以醫術深獲當地華人信賴，清光緒年間帶著數千白銀返鄉建屋，建材全部從泉州購入。建築為五開間二落大厝，兩側再加突歸，在金門稱「六路大厝」，前後落皆為翹脊，格局保存原貌。落成後曾無償借給三戶親族居住；民國38年（1949）起陸續作為國軍指揮所，1954至1958年也當過金門中學學生臨時宿舍。","highlights":["五開間二落加兩側突歸的完整六路大厝","鏡面牆對聯寫進「玉羊」「仙鶴」等地景","正面煙炙磚與斗仔砌、下堵石檻牆"],"funFact":"對聯「前寶獅後玉羊」的玉羊，指屋後山頂的羊角奇石；「右仙鶴」指右前方的仙鶴宮。","photoSpot":"在前埕外拍前後落雙翹脊","visitMin":15,"openNote":"位於金湖鎮成功聚落，鄰近陳景蘭洋樓。私人住宅，仍由家族管理使用，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"A","text":"這間大厝的主人陳酙，小時候家裡窮，跟鄉親學了一手醫術，後來到越南行醫。"},{"who":"R","text":"醫生耶！Allan，所以他是靠看病賺錢蓋房子的嗎？"},{"who":"A","text":"沒錯，他醫術好，深受當地華人信賴，清光緒年間帶著幾千兩白銀回鄉，建材全部從泉州買來。"},{"who":"R","text":"進口建材！那為什麼叫六路大厝？有六條路通到他家嗎？"},{"who":"A","text":"不是啦，是五開間二落大厝兩邊再加突歸，數起來有六道縱向牆，金門人就叫它六路大厝。"},{"who":"R","text":"原來是數牆壁，不是數馬路，我差點要開導航了。"},{"who":"A","text":"更妙的是對聯，「前寶獅後玉羊」裡的玉羊，指的是屋後山頂一塊羊角奇石，等於把風景寫進門聯。"},{"who":"R","text":"門聯兼地圖，太有創意了！那我們到現場要看什麼？"},{"who":"A","text":"這裡還有人住，請在屋外欣賞。站遠一點數數前後落的翹脊，再往屋後山頂望望，想像那塊羊角石吧！"}],"clues":["我的主人在越南以醫術聞名，帶白銀回鄉蓋屋","我的門聯把屋後的羊角石和仙鶴宮都寫了進去","我是成功聚落一座五開間二落加突歸的大厝"],"quiz":[{"q":"陳酙在越南靠什麼致富？","options":["經營橡膠園","開設船行","販賣布匹","行醫看病"],"answer":3,"explain":"陳酙學得醫術，在越南行醫深獲華人信賴。"},{"q":"對聯「後玉羊」的玉羊指的是什麼？","options":["村裡的石羊雕像","屋後山頂的羊角奇石","山上放牧的羊群","廟裡供奉的玉雕"],"answer":1,"explain":"玉羊指建築後方山頂的羊角奇石。"}],"images":[]},{"id":"jinsha-chenshiyiluosiju","name":"陳氏一落四櫸頭(碧山35號)","short":"碧山35號古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48602,"lng":118.44211,"address":"金門縣金沙鎮碧山35號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-29/e84bc19f-eaa6-420e-9352-867114a9de6c/01封面.jpg","year":1890,"yearText":"約清末（確切年代不詳）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"前埕有照壁的碧山清末一落四櫸頭","intro":"陳氏一落四櫸頭（碧山35號）位於金沙鎮碧山聚落，約創建於清末，是一落四櫸頭、前方帶照壁的閩南古厝格局，現在的照壁為新作。屋頂為傳統雙坡翹脊紅瓦，脊肚以彩磁裝飾。牆體以石砌為主，正身上緣為斗仔砌，背立面通體石砌，轉角以石條收邊；正身大廳採穿鬥式牆體。中軸線從照壁、前埕、深井、巷頭到正廳、壽堂後，深井兩側為櫸頭。鏡面牆額堵飾彩磁，正門兩側有聯對，馬鼻窗上方寫著「梅開五福」「竹報平安」。民國38至47年國軍曾駐紮於此，民國60至70年間曾整修。","highlights":["前埕正前方的照壁","馬鼻窗上「梅開五福」「竹報平安」","屋脊脊肚的彩磁裝飾"],"funFact":"馬鼻窗上的「梅開五福」「竹報平安」各四字，一梅一竹，把祝福寫成了一副小對聯。","photoSpot":"退到照壁旁，拍古厝正面與翹脊","visitMin":10,"openNote":"位於金沙鎮碧山聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，走進碧山這一戶之前，你有沒有發現前面多了一道牆？"},{"who":"R","text":"有！一道矮矮的牆擋在前埕前面，好像玄關的屏風。"},{"who":"A","text":"這叫照壁，這座古厝的格局就是一落四櫸頭前面再帶一道照壁，現在的照壁是後來新做的。"},{"who":"R","text":"那後面的古厝本身是什麼時候蓋的？"},{"who":"A","text":"大約清末。牆體大多是石砌，上面一段是斗仔砌的磚，屋脊中間還貼了彩磁。"},{"who":"R","text":"我看到窗戶上面寫著字，那是什麼？"},{"who":"A","text":"左右馬鼻窗上寫「梅開五福」和「竹報平安」，一梅一竹，比我寫的生日卡片有學問多了。"},{"who":"R","text":"Allan你寫的卡片都只有「生日快樂」四個字啦！"},{"who":"A","text":"被你抓包了。這裡有人住，在外面看就好。去找找看，哪一扇窗寫梅、哪一扇寫竹？"}],"clues":["我的前埕前方擋著一道照壁","我的兩扇馬鼻窗上分別寫著梅與竹的祝福","碧山一座約清末的一落四櫸頭，照壁是後來新做的"],"quiz":[{"q":"這座古厝馬鼻窗上方寫的是哪兩句？","options":["詩書傳家、忠厚繼世","福如東海、壽比南山","登高門第、要好兒孫","梅開五福、竹報平安"],"answer":3,"explain":"馬鼻窗上方以「梅開五福」「竹報平安」對聯裝飾。"},{"q":"這座古厝的格局有什麼特別之處？","options":["一落四櫸頭前帶照壁","三落大厝","帶銃樓的洋樓","五腳基疊樓"],"answer":0,"explain":"建築為一落四櫸頭，前方帶有照壁。"}],"images":[]},{"id":"jinsha-chenduqingucuo","name":"陳篤欽古厝","short":"陳篤欽古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48018,"lng":118.42766,"address":"金門縣金沙鎮陽翟24號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000025","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/2648d791-b250-4aab-883b-990756b05f4e/陳篤欽古厝_封面.jpg","year":1895,"yearText":"清末（確切年代不詳）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"交趾陶、泥塑、彩繪滿屋的陽翟二落大厝","intro":"陳篤欽古厝位於金沙鎮陽翟聚落，官方說明建於清末，由陳篤欽聘請福建籍匠師興建。建築為二落大厝，雙坡翹脊屋頂兩側各有三條筒瓦；牆身腰堵以下為石條平砌，以上為磚斗砌，轉角作煙炙磚柱。入口大門上方掛著「穎川世澤」匾額，正立面直櫺窗與對看堵上方都有橫批。它最大的特色是屋脊、脊墜、水車堵、壁堵與墀頭大量運用交趾陶、泥塑和彩繪，裝飾相當豐富。內部前落正廳有一道輪錢門，廳內門扇雕花精美，後落鏡面牆頂堵為卍字不斷紋。民國38至48年國軍曾駐紮於此，民國106年（2017）依縣府獎助辦法完成修復。","highlights":["屋脊、水車堵與墀頭的大量交趾陶與泥塑","大門上方的「穎川世澤」匾額","直櫺窗與對看堵上方的橫批"],"funFact":"官方點名這座古厝最大的特色就是裝飾：從屋脊、脊墜到墀頭，處處都有交趾陶、泥塑與彩繪。","photoSpot":"在前埕外拍屋脊與水車堵裝飾","visitMin":15,"openNote":"位於金沙鎮陽翟聚落，鄰近陽翟老街與金東電影院。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝的屋頂和牆上，到處都是彩色的小人和花，好熱鬧喔！"},{"who":"A","text":"你一眼就看到重點了！官方說它最大的特色，就是大量的交趾陶、泥塑和彩繪。"},{"who":"R","text":"交趾陶是什麼？是交給趾頭做的陶嗎？"},{"who":"A","text":"哈哈，不是用腳趾做的啦！是一種低溫燒製的彩色陶塑，常用來裝飾廟宇和大厝。"},{"who":"R","text":"原來如此！那這間房子是誰蓋的？"},{"who":"A","text":"主人陳篤欽在清末請福建的匠師來蓋，是一座二落大厝，大門上掛著「穎川世澤」。"},{"who":"R","text":"那這些裝飾放了一百多年，還這麼漂亮嗎？"},{"who":"A","text":"它在民國106年完成修復，所以很精神。看完這裡還能去旁邊的陽翟老街，吃碗蚵仔麵線。"},{"who":"R","text":"又在想吃的！那我先在屋脊上找找，有沒有騎馬的小人物！"}],"clues":["官方說我最大的特色，是滿身的交趾陶、泥塑與彩繪","我的大門上掛著「穎川世澤」，由福建籍匠師所建","陽翟一座清末二落大厝，民國106年完成修復"],"quiz":[{"q":"官方認為這座古厝最大的特色是什麼？","options":["高聳的銃樓","西式山頭","大量交趾陶泥塑彩繪","罕見的三落格局"],"answer":2,"explain":"屋脊、脊墜、水車堵、壁堵、墀頭大量運用交趾陶、泥塑與彩繪。"},{"q":"陳篤欽古厝的大門上方掛著什麼匾額？","options":["瓊林世澤","太原衍派","紫雲流芳","穎川世澤"],"answer":3,"explain":"入口大門上方有「穎川世澤」匾額。"}],"images":[]},{"id":"jinsha-zhouanbanggucuo","name":"周安邦古厝","short":"周安邦古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47933,"lng":118.39024,"address":"金門縣金沙鎮浦邊18號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-28/27e19d06-7c98-4740-9169-cba17b86e791/1.jpg","year":1899,"yearText":"1900年（清光緒26年）以前","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"旅日經商返鄉建造、木雕華美的二落大厝","intro":"周安邦古厝位於金沙鎮浦邊聚落，官方資料記載約興建於清光緒26年（1900）以前，興建人周安邦到日本經商有成後返鄉建造。建築為傳統二落大厝，屋脊為翹脊，前落脊端塑螭吻、後落塑坐獅，脊墜以剪黏、交趾陶與彩繪泥塑裝飾。正面門額題「濂溪演派」堂號，榻受牆有卍字不斷紋磚雕。室內木雕尤其精彩，前落屏門透雕「一路連科」「白頭富貴」「喜上眉梢」等吉祥圖樣，背面再雕卍字紋；大門保留輪錢門與門閂孔等防盜設施。民國103年（2014）依縣府獎助辦法完成整體修復。","highlights":["門額上的「濂溪演派」堂號","前落脊端的螭吻與後落的坐獅","榻受牆上的卍字不斷紋磚雕"],"funFact":"古厝屏門的透雕正面是吉祥圖案，背面卻雕卍字不斷紋，一扇門前後兩種花樣。","photoSpot":"在門前拍「濂溪演派」門額與磚雕","visitMin":15,"openNote":"位於金沙鎮浦邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往，或搭金門縣公車至沙美車站後轉乘。","dialogue":[{"who":"R","text":"Allan，這間古厝屋脊上好熱鬧，前面跟後面站的動物好像不一樣？"},{"who":"A","text":"被你發現了！前落脊端是螭吻，後落是坐獅，一前一後輪流站崗，比大樓保全還盡責。"},{"who":"R","text":"是誰這麼講究啊？連屋脊都安排了站崗班表！"},{"who":"A","text":"屋主周安邦到日本做生意有成，回浦邊蓋了這座二落大厝，官方說大約在清光緒26年以前完成。"},{"who":"R","text":"去日本做生意？我以為金門人都是下南洋！"},{"who":"A","text":"金門僑鄉的路線很多元，南洋、日本都有人去。你看門額寫濂溪演派，這是周家的堂號。"},{"who":"R","text":"外面就這麼講究，那裡面的裝飾應該也很厲害吧？"},{"who":"A","text":"屋裡木雕有一路連科、喜上眉梢這些吉祥圖樣，大門還留著防盜的輪錢門。不過這是私人住宅，我們看外觀就好。"},{"who":"R","text":"沒問題！我來找找正面那片卍字不斷紋磚雕，看它到底連了多長！"}],"clues":["我的主人到日本經商，返鄉蓋了我","我的屋脊前有螭吻、後有坐獅","浦邊聚落裡，清光緒年間由旅日商人建的二落大厝"],"quiz":[{"q":"周安邦是到哪裡經商有成後返鄉蓋屋？","options":["日本","菲律賓","印尼","新加坡"],"answer":0,"explain":"周安邦至日本經商有成後返鄉建造古厝。"},{"q":"古厝前落屋脊兩端塑的是什麼？","options":["坐獅","鳳凰","螭吻","鯉魚"],"answer":2,"explain":"前落兩側脊塞為螭吻，後落為坐獅。"}],"images":[]},{"id":"jincheng-chenzhenfanggucuo","name":"陳振芳古厝","short":"陳振芳古厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41997,"lng":118.32104,"address":"金門縣金城鎮庵前33號","announced":"2007-01-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20070119000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/8fc11b3c-17e0-4139-9019-c15bea5435ef/封面.png","year":1900,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝"],"yearUnknown":true,"summary":"藏著清嘉慶年間十折賀壽屏風的古厝","intro":"陳振芳古厝位於金城鎮庵前聚落，為二落大厝，正、背立面設有磚製「石敢當」。陳振芳生於1886年，父親陳詩落曾任清代總兵署的基層兵員，母親是同村鄉紳葉幹亭的孫女。葉家當年有船隊往返臺金經商，葉幹亭五十歲壽辰時，臺灣嘉義學教諭粘克成贈送賀壽屏風，葉家家道中落後由葉氏帶到陳家，至今仍在神龕後方。1949年國軍曾暫住，1951年在室內開挖避難地道；1991年後閒置，平日仍祭祖。官方資料未載興建年代，詳細沿革仍待調查。","highlights":["正、背立面的磚製「石敢當」","規壁脊墜的蝙蝠、吉磬、蝴蝶與如意泥塑","巷頭門上方的扇形採光窗"],"funFact":"神龕後的十折屏風是1814年嘉義學教諭送葉家的壽禮，後來跟著葉家女兒來到陳家。","photoSpot":"前埕外拍二落大厝與磚製石敢當","visitMin":10,"openNote":"位於金城鎮庵前聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；古厝目前閒置並作祭祖使用，未對外開放。可騎機車或開車前往。","dialogue":[{"who":"A","text":"庵前這棟二落大厝，藏著一件比房子還有故事的寶貝，你猜是什麼？"},{"who":"R","text":"該不會是一罐清朝留下來的古董貢糖吧？"},{"who":"A","text":"你跟我一樣滿腦子都是吃的！是一座十折賀壽屏風，清嘉慶19年由嘉義學教諭送的。"},{"who":"R","text":"嘉義？那不是在臺灣嗎？怎麼跑到金門來了？"},{"who":"A","text":"屏風原本屬於同村葉家，葉家當年有船隊往返臺金做生意，葉幹亭五十歲大壽時收到這份禮。"},{"who":"R","text":"那這座屏風怎麼會變成陳家的寶貝？"},{"who":"A","text":"陳振芳的母親是葉幹亭的孫女，葉家家道中落時，屏風就跟著來到陳家，至今還在神龕後方。"},{"who":"R","text":"一座屏風串起兩個家族，好浪漫！"},{"who":"A","text":"這裡是私人古厝，請在外面欣賞就好。找找看牆上那塊磚做的石敢當，它是守護房子的喔！"}],"clues":["我的神龕後方有一座清嘉慶年間的十折賀壽屏風","屋主的母親是同村一位擁有臺金船隊的鄉紳孫女","我是庵前聚落的二落大厝，正背立面都有磚製石敢當"],"quiz":[{"q":"古厝內的賀壽屏風原本屬於哪一家？","options":["陳家","黃家","王家","葉家"],"answer":3,"explain":"屏風原屬葉幹亭家，葉家家道中落後由葉氏攜至陳家。"},{"q":"古厝正、背立面設有什麼辟邪物？","options":["風獅爺","磚製石敢當","八卦鏡","劍獅"],"answer":1,"explain":"建築正、背立面都設有磚製石敢當。"}],"images":[]},{"id":"jinsha-zhoushierluodacuo","name":"周氏二落大厝","short":"周氏二落大厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47892,"lng":118.38995,"address":"金門縣金沙鎮浦邊15號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-21/d4658b99-5c85-4517-af0e-800533dbc004/封面.png","year":1900,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝"],"yearUnknown":true,"summary":"前落加蓋疊樓、紅磚拱圈隔間的大厝","intro":"周氏二落大厝位於金沙鎮浦邊聚落，依歷史建築清冊記載，是一位在日本經商的族人以僑匯興建，興建年代不詳。建築為二落大厝，最特別的是前落左右兩房向上加蓋疊樓，疊樓外牆開窗，上方有三拱弧形窗楣，木窗板內側還有鑄鐵窗柵；兩側櫸頭頂有煙炙磚砌成的十字形鏤空女兒牆。室內前廳與深井之間以四柱三開間的紅磚拱圈相隔；後落大規壁抹上添加紅色顏料的灰壁，再刻出仿斗砌的線條。古厝後來僅作祭祀使用，目前前廳屋頂坍塌、疊樓牆體開裂，待整體修復。","highlights":["前落左右加蓋的疊樓與三拱弧形窗楣","櫸頭上方十字形鏤空的煙炙磚女兒牆","後落紅色灰壁上刻出的仿斗砌線條"],"funFact":"後落山牆其實是紅色灰壁再刻線，假裝成一塊塊斗砌紅磚，是古早的仿磚手法。","photoSpot":"拍前落兩側疊樓與十字鏤空女兒牆","visitMin":10,"openNote":"位於金沙鎮浦邊聚落，部分屋頂坍塌。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，來玩大家來找碴，這面紅色山牆是真的紅磚嗎？"},{"who":"R","text":"一塊一塊排得那麼整齊，當然是紅磚啊！"},{"who":"A","text":"答錯囉！這是在灰壁裡加紅色顏料，再刻出仿斗砌的線條，古早版的仿真貼皮。"},{"who":"R","text":"哇，原來古人也會這招！這房子是誰蓋的？"},{"who":"A","text":"依清冊記載，是一位在日本經商的族人寄錢回來蓋的，興建年代沒有留下紀錄。"},{"who":"R","text":"我注意到前面左右兩邊，多長出兩個小樓！"},{"who":"A","text":"那叫疊樓，前落兩房往上加蓋，窗上還有三拱弧形窗楣，像大厝戴了兩頂小帽子。"},{"who":"R","text":"好可愛！那裡面現在還有人住嗎？還是空著呢？"},{"who":"A","text":"現在主要用來祭祀，部分屋頂已經坍塌，我們在外面看就好。去找找櫸頭上方那排十字形的鏤空女兒牆吧！"}],"clues":["我身上有一面假裝成紅磚的山牆","我的前落左右兩房都加蓋了疊樓","浦邊聚落裡，由旅日族人以僑匯興建的二落大厝"],"quiz":[{"q":"這座大厝前落左右兩房有什麼特色？","options":["改成店面","加蓋疊樓","設置銃樓","挖了水井"],"answer":1,"explain":"前落左、右兩房向上加建疊樓。"},{"q":"後落大規壁的紅色斗砌紋路其實是？","options":["彩色磁磚","真的紅磚","紅色灰壁刻線","木板彩繪"],"answer":2,"explain":"以添加紅色顏料的灰壁，陰刻出仿斗砌勾線。"}],"images":[]},{"id":"jinsha-shanhouzhongbao","name":"山后中堡中書第","short":"山后中書第","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.50436,"lng":118.44029,"address":"金門縣金沙鎮山后61號","announced":"2007-12-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071213000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-15/04e9d94e-43a0-4a56-8b37-38e8b6554c16/山后中堡中書第_代表圖像.jpg","year":1900,"yearText":"1900年（清光緒26年）完工","era":"qing","themes":["閩南古厝","聚落地景"],"yearUnknown":false,"summary":"山后十八間厝中最後落成、工藝最精","intro":"中書第位於金沙鎮山后中堡，屬「十八間厝」之一。山后王氏的王國珍清同治7年（1868）前往日本，先帶布袋戲班到長崎打開人脈，後在神戶經商致富，商號「復興號」。他返鄉擘畫中堡，興建十六棟二落大厝及海珠堂、王氏家廟，合稱十八間厝，自清光緒2年（1876）動工至26年（1900）完工，歷時25年。中書第屬國珍姪子王敬川，約清光緒22年起建、26年完成，是十八間厝中最後落成者，用料與裝飾臻於顛峰。前門掛「大夫第」匾，後落正廳嵌「中書第」匾，左突歸起疊樓並設軒亭。","highlights":["後落正廳門楣「中書第」匾與前門「大夫第」匾","古錢與四個葫蘆組成的「賜福含財」橫批窗","左突歸疊樓上的軒亭"],"funFact":"王國珍最初是帶著布袋戲班到長崎，靠戲偶打開人脈，後來才在神戶經商致富。","photoSpot":"在前埕古井旁拍大厝正面與匾額","visitMin":20,"openNote":"位於金沙鎮山后中堡，屬金門國家公園範圍，周邊十八間厝聚落可步行參觀。官方資料未載明本棟開放情形；私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你知道布袋戲可以蓋出一整座聚落嗎？"},{"who":"R","text":"布袋戲？Allan，你是不是又在唬我？"},{"who":"A","text":"這次是真的。山后的王國珍清同治7年帶著布袋戲班到長崎，用戲偶交朋友，後來在神戶做生意發大財。"},{"who":"R","text":"戲偶變成交際高手，這招也太厲害了吧！"},{"who":"A","text":"他回鄉規劃中堡，十六棟大厝加上海珠堂和王氏家廟，合稱十八間厝，從清光緒2年蓋到26年，足足25年。"},{"who":"R","text":"25年！那這棟中書第是第幾棟？"},{"who":"A","text":"它是最後完成的，屬於他的姪子王敬川，師傅越蓋越熟練，用料和雕工都到了顛峰，算是壓軸大戲。"},{"who":"R","text":"果然好戲都在最後，壓軸的最精彩！"},{"who":"A","text":"這裡請在外面欣賞喔。抬頭看看前門掛的匾額，猜猜上面寫的是哪三個字？"}],"clues":["我主人的叔叔，曾帶著布袋戲班到長崎","我是十八間厝中最後落成的一棟","山后中堡裡，前後掛著兩塊不同匾額的二落大厝"],"quiz":[{"q":"山后中堡的「十八間厝」是由誰擘畫興建？","options":["王敬祥","黃聰明","王國珍","李康塔"],"answer":2,"explain":"旅日華僑王國珍擘畫興建中堡十八間厝。"},{"q":"王國珍在日本經商的商號叫什麼？","options":["恆通號","復興號","瑞祥號","義發號"],"answer":1,"explain":"王國珍在神戶經商致富，商號名為「復興號」。"}],"images":[]},{"id":"jinsha-zhangshigucuo2","name":"張氏古厝(沙美101號)","short":"張氏古厝101號","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49193,"lng":118.41225,"address":"金門縣金沙鎮沙美101號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/c3717a24-0733-4e6b-81d5-5f942cba9638/張氏古厝(沙美101號)_封面.jpg","year":1900,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝"],"yearUnknown":true,"summary":"與前方倒座共用一面牆的一落二櫸頭","intro":"這座張氏古厝位於金沙鎮沙美聚落，創建年代不詳，完工後作為住家，八二三砲戰前曾有國軍駐紮。建築為一落二櫸頭，屋頂為閩南式雙坡翹脊，正面圓脊山牆，左右櫸頭上方有煙炙磚砌女兒牆，外牆下段花崗石、上段磚砌抹灰，轉角以斗砌磚柱收邊。它最特別的是和前方一棟倒座屬於同一組建築群，倒座正面牆與櫸頭相接，深井內再築一道圍牆區隔地界，形成兩戶共用的「共同壁」；民國110年（2021）依文化資產審議會建議修復了這道牆。正廳大門兩側有書法聯對，上方繪萬字不斷紋。","highlights":["與前方倒座共用、民國110年修復的共同壁","正廳大門兩側書法聯對與萬字不斷紋彩繪","櫸頭上方的煙炙磚女兒牆"],"funFact":"這道共同壁既是兩戶人家的地界，也讓前後兩棟房子連成同一組建築群。","photoSpot":"在巷口拍古厝與倒座相連的立面","visitMin":10,"openNote":"位於金沙鎮沙美聚落，古厝閒置、屋瓦有破損。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，跟鄰居共用一面牆，你覺得是好事還是壞事？"},{"who":"R","text":"看情況吧！如果鄰居很吵，那就很困擾。"},{"who":"A","text":"這間張氏古厝就是這樣，它和前面一棟倒座是同一組建築，深井裡砌了一道圍牆分地界，兩戶共用。"},{"who":"R","text":"倒座是什麼？難道是房子倒過來蓋嗎？"},{"who":"A","text":"哈哈，不是倒立！倒座是坐向和主屋相反、面對主屋的房子，兩棟面對面，像在大眼瞪小眼。"},{"who":"R","text":"原來是面對面的好鄰居。那這面牆有修過嗎？"},{"who":"A","text":"2021年前面那戶要整修，經過文化資產審議會同意，兩戶的共同壁也一起修好了，真是敦親睦鄰的典範。"},{"who":"R","text":"修牆還能修出好交情！那這間是什麼時候蓋的？"},{"who":"A","text":"官方說創建年代不詳。這是私人產業，我們在巷口看就好，找找兩棟房子是在哪裡連在一起的吧！"}],"clues":["我和前面的倒座共用一道牆","我的建造年代沒有人說得準","沙美聚落裡，一落二櫸頭的張家老屋"],"quiz":[{"q":"古厝與前方倒座之間的牆被稱為什麼？","options":["共同壁","防火牆","照壁","隘門"],"answer":0,"explain":"深井內築圍牆區隔地界，形成兩戶的共同壁。"},{"q":"這座古厝的平面格局是？","options":["三落大厝","五腳基洋樓","二落大厝","一落二櫸頭"],"answer":3,"explain":"建築平面格局為一落二櫸頭。"}],"images":[]},{"id":"jinsha-donghangxiaoxian","name":"東珩蕭顯柳古厝","short":"蕭顯柳古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48619,"lng":118.43401,"address":"金門縣金沙鎮東珩14號","announced":"2017-01-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20171204000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-17/60931c4d-fec7-4c5d-bb9c-6517efe9be21/01.jpg","year":1900,"yearText":"約1900年前後（清光緒末年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"印尼橡膠園致富的華僑返鄉大厝","intro":"東珩蕭顯柳古厝位於金沙鎮東珩聚落。蕭顯柳清同治6年（1867）生於金門，九歲隨族人前往印尼望加麗島，從打雜工人做起，後進入橡膠園工作，再把積蓄投資橡膠園而致富。約清光緒末年、三十歲左右返鄉興建此宅，建材與匠師都來自大陸，落成後便回到印尼，並未實際居住，晚年病逝南洋，金門有他的衣冠塚。民國25年前後，他的兒子一家返回金門居住。民國38年（1949）國軍進駐，直到民國54年（1965）撤離。建築為雙落大厝，四面下段石檻牆、上段斗子砌磚牆，工法精良。民國76年後閒置，目前屋頂塌陷。","highlights":["正面榻受左側保留的一座石磨","後落右側牆上「領袖」二字水泥標語","四面石檻牆與斗子砌磚牆的精良工法"],"funFact":"蕭顯柳九歲就出洋到印尼打雜，靠橡膠園翻身，卻沒在自己蓋的大厝住過。","photoSpot":"在右側拍牆上殘留的「領袖」標語","visitMin":10,"openNote":"位於金沙鎮東珩聚落，長期閒置，屋頂塌陷、結構不穩，請勿靠近或進入。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你鞋子的橡膠鞋底，跟這間古厝可是有關係的喔。"},{"who":"R","text":"啊？Allan，鞋底跟古厝到底能扯上什麼關係？"},{"who":"A","text":"屋主蕭顯柳九歲就跟族人到印尼望加麗島打雜，後來在橡膠園工作，還把存款投資橡膠園，就這樣致富。"},{"who":"R","text":"九歲就出國工作！我九歲還在玩溜滑梯耶。"},{"who":"A","text":"所以這房子是他用汗水換來的。清光緒末年他回來蓋大厝，建材和師傅都從大陸請來，可是蓋好又回印尼了。"},{"who":"R","text":"又是一位沒住過自己房子的屋主，金門華僑真的好辛苦，好讓人捨不得！"},{"who":"A","text":"後來國軍也進駐過，右邊牆上還留著領袖兩個水泥字。現在房子屋頂塌了，我們只能遠遠看。"},{"who":"R","text":"好，那我從外面找一找，正面左邊是不是真的放著一座石磨！"}],"clues":["我的主人九歲出洋，靠橡膠園致富","我的牆上還留著「領袖」兩個水泥字","東珩聚落裡，印尼華僑返鄉蓋的雙落大厝"],"quiz":[{"q":"蕭顯柳在印尼靠什麼產業致富？","options":["錫礦","胡椒園","橡膠園","布匹貿易"],"answer":2,"explain":"他進入橡膠園工作，再投資橡膠園後致富。"},{"q":"古厝正面榻受左側保留了什麼？","options":["石磨","石獅","水井","石碑"],"answer":0,"explain":"二落大厝正立面榻受左側置有石磨。"}],"images":[]},{"id":"jinsha-fengzhidi","name":"奉直第","short":"奉直第","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49546,"lng":118.418369,"address":"金門縣金沙鎮英坑15號","announced":"2006-11-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061109000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-28/c5bbe6af-070d-4b41-a1be-1aaa121814e1/金門縣 奉直第 (歷建)01.jpg","year":1901,"yearText":"1901年（清光緒27年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"長崎領事題匾的英坑旅日華僑大厝","intro":"奉直第位於金沙鎮英坑聚落。屋主黃聰明生於清光緒初年，年少時常被鄉人取笑，憤而遠赴日本長崎發展，結識清朝駐長崎領事卞綍昌，在他協助下經商，生意遍及日本、上海、新加坡等地。清光緒27年（1901）黃聰明帶著大批白銀返鄉娶妻、興建此宅，卞綍昌題「奉直第」相贈，鄉人因此稱為奉直大夫第。抗戰時期日軍占領金門，黃家兒子略懂日文而擔任翻譯。民國38年後國軍曾暫住，八二三砲戰時作為簡易醫護所。建築為二落大厝，前有圍牆與龍虎門，民國98年（2009）完成整體修復。","highlights":["榻受門額上「日本長崎正領事官」等題款","圍牆正面作為出入口的龍虎門","前落向寮格扇上方的「紫微拱照」四字"],"funFact":"黃聰明小時候不愛讀書常被笑，後來赴長崎闖出一片天，帶著大批白銀衣錦還鄉。","photoSpot":"在龍虎門外拍大厝正面與門額","visitMin":15,"openNote":"位於金沙鎮英坑聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，奉直第這三個字，是皇帝賞的嗎？"},{"who":"A","text":"不是皇帝，是朋友送的！屋主黃聰明年輕時不愛讀書，常被鄉親笑，他一氣之下跑去日本長崎打拚。"},{"who":"R","text":"被笑就出國，好有骨氣！後來呢？"},{"who":"A","text":"他在長崎認識清朝駐長崎的領事卞綍昌，兩人變成好朋友，在領事幫忙下做起生意，一路做到上海、新加坡。"},{"who":"R","text":"所以這是被人笑、最後逆轉勝的勵志劇本！"},{"who":"A","text":"清光緒27年，他帶著大批白銀回英坑娶妻蓋房，領事就題了奉直第三個字相贈，門額上還看得到領事的題款。"},{"who":"R","text":"早知道被笑可以變這樣，我也要讓你笑一笑！"},{"who":"A","text":"先把功課寫完再說。這裡是私人住宅，在龍虎門外看就好，找找門額上，哪幾個字寫著長崎？"}],"clues":["一位駐外領事為我題寫了門額","我的主人曾被鄉人取笑，後來在長崎致富","英坑聚落、清光緒27年落成的二落大厝"],"quiz":[{"q":"黃聰明是在哪個城市發展經商？","options":["神戶","橫濱","大阪","長崎"],"answer":3,"explain":"黃聰明前往日本長崎，結識駐長崎領事後經商。"},{"q":"八二三砲戰期間，奉直第曾作為什麼用途？","options":["簡易醫護所","彈藥庫","小學教室","雜貨店"],"answer":0,"explain":"八二三砲戰時，建築曾作為簡易醫護所。"}],"images":[]},{"id":"jinning-nanshanerluodacuo","name":"南山二落大厝群","short":"南山二落大厝群","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.479103,"lng":118.30586,"address":"金門縣金寧鄉古寧村南山101、107、112號","announced":"2003-12-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031222000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-20/520d7552-7a80-43c2-a387-63112b2890c5/01封面.jpg","year":1902,"yearText":"1902年（清光緒28年）","era":"qing","themes":["閩南古厝","聚落地景"],"yearUnknown":false,"summary":"越南僑匯興建、三棟並列的二落大厝群","intro":"南山二落大厝群位於金寧鄉古寧村南山聚落，由三棟並列的二落大厝組成，興建於清光緒28年（1902）。起造人李炎得到越南經商後僑匯返鄉，由惠安匠師主持營造，花費一千多兩白銀。三棟格局略有不同：一棟為二落大厝加左護龍，一棟為單純的二落大厝，另一棟加右突歸。前落正面上緣為斗仔砌與煙炙磚，下緣為泉州白石平砌，屋頂為閩南雙坡翹脊。1949年國軍曾拆下前廳門板當床舖使用。2002年其中一棟由國家公園補助修復，門額書「隴西衍派」，窗楣有「吉星高照」「人壽年豐」；另兩棟仍保有精美的水車堵泥塑與人物插角，但其中一棟已嚴重頹圮。","highlights":["修復大厝門額「隴西衍派」與窗楣吉祥字","未修復大厝水車堵的原始泥塑堵頭","前落下緣的泉州白石平砌"],"funFact":"1949年國軍駐紮時，曾把大厝前廳的門板拆下來當床舖使用。","photoSpot":"在巷口拍三棟大厝並排的翹脊天際線","visitMin":15,"openNote":"位於金寧鄉古寧村南山聚落。其中一棟仍有人居住，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；另兩棟閒置且部分坍塌，請勿進入。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"R","text":"Allan，南山這裡有三棟長得很像的大厝排排站，好像三胞胎耶！"},{"who":"A","text":"說是三胞胎也行，不過仔細看，個性都不一樣：一棟加左護龍，一棟加右突歸，一棟最單純。"},{"who":"R","text":"那是誰生的三胞胎？我是說，誰蓋的？"},{"who":"A","text":"清光緒28年，也就是1902年，李炎得到越南做生意，把錢寄回來，請惠安師傅蓋的。"},{"who":"R","text":"那這三棟大厝現在都還有人住嗎？"},{"who":"A","text":"只有修復好的那棟有人住，另外兩棟閒置，其中一棟已經嚴重坍塌，長滿植物，看了很心疼。"},{"who":"R","text":"聽說以前還有阿兵哥把門板拆去當床睡，是真的嗎？"},{"who":"A","text":"真的，1949年的事。睡門板應該很硬，我寧可去吃碗石蚵麵線補一下。請你找找修好的那棟，門額寫什麼？"}],"clues":["我們由到越南經商的僑民寄錢興建，請惠安師傅主持","我們三兄弟格局各不同，門板曾被拆去當床","我們在古寧頭南山，建於清光緒28年"],"quiz":[{"q":"南山二落大厝群的起造人李炎得在哪裡經商？","options":["新加坡","菲律賓","印尼","越南"],"answer":3,"explain":"李炎得至越南經商後僑匯返鄉興建大厝群。"},{"q":"1949年國軍曾把大厝的什麼東西拆下來當床舖？","options":["前廳門板","窗櫺木條","屋頂桁木","神龕壽屏"],"answer":0,"explain":"大厝群的前廳門板曾被國軍拆卸作為床舖使用。"}],"images":[]},{"id":"jinsha-herencigucuo","name":"何仁慈古厝","short":"何仁慈古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47884,"lng":118.38904,"address":"金門縣金沙鎮浦邊32號","announced":"2015-03-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150302000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-12-23/65e9c31b-3221-4bbb-8a10-08162e6be1c5/messageImage_1766481611296.jpg","year":1903,"yearText":"1903年（清光緒29年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"菲律賓僑商捐官「都戎」的雙落大厝","intro":"何仁慈古厝位於金沙鎮浦邊村。興建人何仁慈早年到菲律賓經營雜貨致富，多次往返兩地，後來捐官擔任「都戎」，古厝左側宅第門額題有「昭武第」，他也協助修建宗祠與廟宇。古厝起建於清光緒29年（1903），為傳統閩式雙落大厝，前方有石板廣場與迴向；迴向當年作私塾教學使用，民國70年間倒塌，民國114年（2025）在獎助下修復完成。正面採榻受作法，水車堵與拱仔頭的泥塑、彩繪精細，正門有石雕門印，次間石窗刻聯對「鏡懸人壽」「雲靄吉祥」，大門上方為「廬江衍派」堂號。古厝與周邊洋樓、昭武第形成群聚景觀。","highlights":["石窗聯對「鏡懸人壽」「雲靄吉祥」","正門上方石雕門印與「廬江衍派」堂號","榻受屋楹的鳥獸花草木雕插角"],"funFact":"古厝前方的迴向當年是私塾教室，民國70年間倒塌，民國114年才修復重現。","photoSpot":"在石板廣場外拍正面榻受","visitMin":15,"openNote":"位於金沙鎮浦邊村，官方未公布開放時間。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。鄰近浦邊多處古厝與洋樓，開車或騎機車前往較方便。","dialogue":[{"who":"A","text":"阿拉蕾，你看門額上的字，猜猜這家主人是文官還是武官？"},{"who":"R","text":"旁邊那棟寫著昭武第，聽起來很會打架，是武官吧？"},{"who":"A","text":"答對一半！何仁慈在菲律賓做雜貨生意致富，後來捐官當都戎，左邊宅第才題昭武第。"},{"who":"R","text":"原來官職可以用捐的，那他蓋的這棟呢？"},{"who":"A","text":"這棟是清光緒29年起建的雙落大厝，前面還有石板廣場和迴向，廣場兩側都有門可以進出。"},{"who":"R","text":"迴向是什麼？聽起來像念經的地方。"},{"who":"A","text":"哈哈，這裡的迴向是前方的附屬建築，當年作私塾上課，倒塌後在民國114年修復完成。"},{"who":"R","text":"孩子們讀書的地方又回來了，真開心！"},{"who":"A","text":"去正面次間的石窗找找聯對，「鏡懸人壽」的另一邊寫的是什麼？"}],"clues":["我的主人在菲律賓賣雜貨，後來捐官當上都戎","我的石窗刻著「鏡懸人壽」「雲靄吉祥」","浦邊村清光緒29年起建、旁邊就是昭武第的雙落大厝"],"quiz":[{"q":"何仁慈捐官擔任的是什麼職位？","options":["總兵","知縣","都戎","提督"],"answer":2,"explain":"何仁慈捐官擔任都戎，左側宅第題「昭武第」。"},{"q":"古厝前方的迴向當年作什麼用途？","options":["私塾教學","存放米糧","祭祀祖先","開設商行"],"answer":0,"explain":"迴向當時作私塾教學使用，後倒塌再修復。"}],"images":[]},{"id":"jinsha-zhaowudi","name":"昭武第","short":"昭武第","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47876,"lng":118.38895,"address":"金門縣金沙鎮浦邊33號","announced":"2015-03-02","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150302000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-05-20/d86a9bcd-1cd5-4910-9257-aaf7ec0a4c09/代表圖片.jpg","year":1903,"yearText":"1903年（清光緒29年）修建，創建年代不詳","era":"qing","themes":["閩南古厝","戰地史蹟"],"yearUnknown":false,"summary":"菲律賓華僑捐官後依官職題名的祖厝","intro":"昭武第位於金沙鎮浦邊聚落。何仁慈（1885–1930），本名何敬慈，早年南渡菲律賓從事雜貨買賣，經商有成後常往來金門與菲律賓。這座雙落大厝在他任官前就已存在，創建年代不詳；清光緒29年（1903）他捐官擔任「都戎」，定居浦邊並修建祖厝，依官職在門額題上「昭武第」。他又在右側另建一座兩落大厝（何仁慈古厝），兩屋以前後隘門相連。建築正面上段紅磚斗砌、下段花崗石檻牆，屋脊為翹脊；左前房在民國47年（1958）砲戰期間開挖了可容納15人的防空洞。民國113年（2024）修復完成，現由屋主自住。","highlights":["門額上依官職題寫的「昭武第」","與右側何仁慈古厝相連、飾綠釉花磚的隘門","正面紅磚斗砌與花崗石檻牆"],"funFact":"左前房在民國47年砲戰期間挖了防空洞，最多可容納15個人避難。","photoSpot":"拍正面隘門上的綠釉花磚","visitMin":15,"openNote":"位於金沙鎮浦邊聚落，修復後由屋主自住。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。官方資料註明可預約安排參觀時間。可開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，昭武第聽起來好威風，是將軍住的地方嗎？"},{"who":"A","text":"有點接近。屋主何仁慈在菲律賓做雜貨生意致富，清光緒29年捐了一個武官頭銜，叫都戎。"},{"who":"R","text":"捐官？Allan，官位可以用錢換喔？"},{"who":"A","text":"清代確實有捐納制度，有錢人可以捐得官銜。他拿到頭銜後修了祖厝，門額就照官職題上昭武第。"},{"who":"R","text":"那等於是把自己的名片刻在大門上嘛！"},{"who":"A","text":"形容得真好。他後來又在右邊蓋了一座兩落大厝，兩棟用隘門連起來，成了自家的小社區。"},{"who":"R","text":"那這座古厝，有經歷過砲戰的年代嗎？"},{"who":"A","text":"民國47年砲戰期間，家人在左前房挖了防空洞，可以躲15個人。現在修好由屋主自住，請在外面參觀。"},{"who":"R","text":"了解！那我去看看，連接兩棟房子的隘門上，鑲的是什麼顏色的花磚。"}],"clues":["我的主人花錢捐了一個武官頭銜","我的左前房地下藏著可躲15人的防空洞","浦邊聚落裡，菲律賓華僑修建、門額依官職題名的大厝"],"quiz":[{"q":"何仁慈捐官擔任的職銜是？","options":["知縣","都戎","游擊","千總"],"answer":1,"explain":"清光緒29年捐官擔任都戎，門額因此題「昭武第」。"},{"q":"左前房的防空洞可以容納多少人？","options":["5人","10人","15人","30人"],"answer":2,"explain":"民國47年砲戰期間建置，可容納15人。"}],"images":[]},{"id":"jinsha-chenshierluodacuo","name":"陳氏二落大厝","short":"碧山陳氏大厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48596,"lng":118.44021,"address":"金門縣金沙鎮碧山70號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/324f88a6-312e-4e65-938e-a569cb07be3b/陳氏二落大厝_封面.jpg","year":1903,"yearText":"約20世紀初（官方稱「百年前」所建）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"兒子在父親古厝旁蓋起的二落大厝加突歸","intro":"陳氏二落大厝位於金沙鎮碧山聚落，官方說明是隔壁歷史建築陳明侑古厝創建人陳明侑的兒子在百年前所建，家族曾在新加坡經營抽取2%利潤的「九八行」。建築平面為二落大厝加右側「突歸」，二落大厝為雙坡翹脊，突歸作圓脊；大門門楣掛著「穎川衍派」堂號。正立面下堵為封堵石，身堵、拱仔頭與水車堵後來改貼現代磁磚；其餘三面牆是花崗石人字砌，轉角作水平聖旨砌。內部由前廳、寮向、深井、巷頭到大廳，巷頭兩側有半樓，右側巷頭另有門通往突歸。民國38至47年間曾駐紮多種兵種國軍。","highlights":["右側加出的突歸與通往它的巷頭小門","大門門楣的「穎川衍派」堂號","側面花崗石人字砌與轉角聖旨砌"],"funFact":"隔壁是父親創建的一落四櫸頭，兒子則蓋了二落大厝再加突歸，父子兩代的房子比鄰而居。","photoSpot":"從巷口斜拍大厝與右側突歸","visitMin":10,"openNote":"位於金沙鎮碧山聚落，與陳明侑古厝相鄰。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，我們剛看完陳明侑古厝，往旁邊走一步，就到了它的兒子家。"},{"who":"R","text":"房子也有兒子？Allan你在說繞口令嗎？"},{"who":"A","text":"哈哈，是真的父子。陳明侑古厝是陳明侑創建的，這座二落大厝則是他的兒子在百年前蓋的。"},{"who":"R","text":"爸爸家是一落，兒子家是二落，兒子贏了一落耶！"},{"who":"A","text":"而且右邊還多長出一塊，叫做「突歸」，就是在大厝旁邊再加出來的空間。"},{"who":"R","text":"突歸，聽起來像突然歸來的遊子！"},{"who":"A","text":"這個聯想很有詩意。大門上掛著「穎川衍派」，是陳姓的堂號，代表祖先來自穎川。"},{"who":"R","text":"那牆壁上一格一格斜斜的石頭是怎麼排的？"},{"who":"A","text":"那是人字砌，轉角改成水平的聖旨砌。這裡有人住，我們在外面看就好，去側面找找人字砌吧！"}],"clues":["我是隔壁那座一落四櫸頭主人的兒子所蓋","我的右側多出一塊叫「突歸」的空間","碧山一座約百年前興建、門楣掛「穎川衍派」的二落大厝"],"quiz":[{"q":"這座二落大厝右側加出來的空間稱為什麼？","options":["突歸","疊樓","銃樓","五腳基"],"answer":0,"explain":"平面格局為二落大厝加右突歸。"},{"q":"這座大厝是由誰興建的？","options":["國軍工兵","陳德幸","陳明侑的兒子","陳清吉"],"answer":2,"explain":"官方說明此宅為陳明侑古厝創建人陳明侑之子所建。"}],"images":[]},{"id":"jincheng-houpuchenshicitang","name":"後浦陳氏祠堂","short":"後浦陳氏祠堂","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.43293,"lng":118.31705,"address":"金門縣金城鎮莒光路106號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000070","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-08/9798641a-adec-4ebf-8717-30bb3fb97ea9/1封面.jpg","year":1904,"yearText":"1904年（清光緒30年）興建，1910年（清宣統2年）落成","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"金門十三陳的總祠，掛著13位進士匾額","intro":"後浦陳氏祠堂位於金城鎮莒光路，是「金門十三陳」的總祠，主祀唐太傅陳邕，正堂為紀念陳顯的「忠賢祠」。陳氏是金門第一大姓，族人長期缺少一座總祠。1900年後浦西門的右營遊擊署遷回同安，陳佐才等6人倡議募款，1902年以銀二千兩承買衙署，1904年動工，1910年落成。因工程繁多，依各派人丁多寡分成十三股分工，形成「十三陳」的說法。1950年曾被徵作官兵福利社，1963年東廂改建為12間店屋收租。建築為閩式雙落大厝，屋面全鋪綠色筒瓦，堂上掛有明清兩代13位進士匾額，點金柱上有1910年完成的鎏金對聯8片。","highlights":["整片綠色筒瓦屋面與前落三川脊","堂上明清兩代13位陳氏進士匾額","點金柱上1910年的鎏金對聯8片"],"funFact":"「十三陳」的說法，來自蓋祠堂時依各派人丁多寡分成十三股分工。","photoSpot":"莒光路上拍綠色筒瓦與三開門正面","visitMin":20,"openNote":"位於金城鎮莒光路，宗族總祠，官方資料未載固定開放時間，請在外觀參觀，祭祖時勿打擾；東廂為店屋。從金城車站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，妳看這座祠堂的屋瓦，是什麼顏色？"},{"who":"R","text":"綠色的！整片綠油油的，好像一塊抹茶蛋糕。"},{"who":"A","text":"這是後浦陳氏祠堂，金門十三陳的總祠。陳氏是金門第一大姓，這裡原本是清代的右營遊擊署。"},{"who":"R","text":"衙門變祠堂？他們是怎麼辦到的？"},{"who":"A","text":"遊擊署遷回同安後，族人1902年用銀二千兩買下，1904年動工，1910年才落成。"},{"who":"R","text":"蓋了6年！那十三陳是說有十三位陳先生嗎？"},{"who":"A","text":"不是喔。當年工程繁多，依各派人丁多寡分成十三股分工，後來就叫十三陳。"},{"who":"R","text":"原來是分組合作完成的大工程！那裡面有什麼寶貝？"},{"who":"A","text":"堂上掛著明清兩代13位進士的匾額。請在門外找找三開門兩側的聯對，看看寫了什麼祝福吧！"}],"clues":["我原本是清代右營遊擊署，族人用銀二千兩買下","我的屋頂鋪滿綠色筒瓦","我是金門十三陳的總祠，堂上有13位進士匾額"],"quiz":[{"q":"「十三陳」這個說法是怎麼來的？","options":["族中出了13位進士","建祠時分十三股分工","族人分布13個聚落","祠堂前後整修13次"],"answer":1,"explain":"建祠時依各派人丁多寡分十三股，形成十三陳。"},{"q":"陳氏祠堂的基地原本是什麼？","options":["清代右營遊擊署","明鄭內校場","清代縣丞署","浯江書院"],"answer":0,"explain":"族人於1902年以銀二千兩承買右營遊擊署。"}],"images":[]},{"id":"jinhu-chencijugucuo","name":"陳祠櫸古厝","short":"陳祠櫸古厝","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.44007,"lng":118.39586,"address":"金門縣金湖鎮夏興18號","announced":"2025-02-08","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20250317000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-03-26/8041d633-6e81-468e-880f-dd5a0b0cbd24/古蹟_陳祠櫸古厝_代表圖像(馬賽克).jpg","year":1905,"yearText":"約1900年代（清光緒末年）","era":"qing","themes":["閩南古厝"],"yearUnknown":false,"summary":"越南僑匯蓋成的夏興三蓋廊古厝","intro":"陳祠櫸古厝位於金湖鎮夏興聚落。夏興舊名「下坑」，民國45年（1956）才改為今名。陳祠櫸是陳八郎派下第25世，祖先正是明初移居下坑的陳與秀；他在清光緒末年從越南匯款回鄉興建此屋。建築為三蓋廊加左護龍，是夏興少見的形式，正廳採穿鬥式木棟架、中堵為樸素木屏，在金門相當罕見。前落有面向門廊的銃眼與輪錢門遺構，後落設夾層「走馬樓」，反映鄰海聚落防範盜寇的需求；深井兩側還留有民國40年代的「新速實簡」標語。","highlights":["三蓋廊門額「奎壁聯輝」與花矸博古圖彩繪","屋脊脊墜以「琴」「書」泥塑象徵詩禮傳家","前落女兒牆上的綠釉柿蒂紋花磚"],"funFact":"夏興原名下坑，傳說宋代陳氏兄弟分居坑溝上下而得名，民國45年才改稱夏興。","photoSpot":"在屋前拍三蓋廊門額與左右脊墜","visitMin":15,"openNote":"位於金湖鎮夏興聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，夏興這個名字聽起來好有活力，是因為夏天特別興旺嗎？"},{"who":"A","text":"哈，其實它原本叫下坑。傳說宋代陳家兄弟一個住坑溝上、一個住坑溝下，民國45年才改名夏興。"},{"who":"R","text":"原來是上下鋪兄弟！那這間古厝跟陳家有關係嗎？"},{"who":"A","text":"屋主陳祠櫸是陳八郎第25世後代，清光緒末年從越南寄錢回家，蓋了這間三蓋廊加左護龍的大厝。"},{"who":"R","text":"三蓋廊？聽起來像有三層蓋子的便當盒。"},{"who":"A","text":"差不多是門口多了一道有屋頂的廊子啦。門額寫著「奎壁聯輝」，兩邊牆上畫著花瓶和四季花卉。"},{"who":"R","text":"我看到屋脊兩端好像掛著東西，那是什麼？"},{"who":"A","text":"那叫脊墜泥塑。請在屋外抬頭找找看，左邊是琴、右邊是書，象徵詩禮傳家喔！"}],"clues":["我的屋主在越南打拚，清光緒末年寄錢回鄉蓋屋","我深井旁還留著「新速實簡」的軍管時期標語","我是夏興聚落少見的三蓋廊加左護龍古厝"],"quiz":[{"q":"夏興聚落原本的名稱是？","options":["上坑","陳坑","下坑","后園"],"answer":2,"explain":"夏興原名下坑，民國45年改為今名。"},{"q":"古厝屋脊的「琴」「書」泥塑象徵什麼？","options":["詩禮傳家","多子多孫","鎮宅避邪","五穀豐收"],"answer":0,"explain":"左琴右書的脊墜泥塑，象徵詩禮傳家。"}],"images":[]},{"id":"lieyu-fangzhai","name":"方宅","short":"西方方宅","category":"歷史建築","level":"","town":"烈嶼鄉","types":["宅第"],"lat":24.43578,"lng":118.23808,"address":"金門縣烈嶼鄉西口村西方51號旁","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000028","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/dd417bf1-6d34-4759-b494-bac7da15c0e7/方宅_封面.jpg","year":1905,"yearText":"約1900年代（清末）","era":"qing","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"突歸加疊樓、綠釉花磚窗的南洋僑匯古厝","intro":"方宅位於烈嶼鄉西方聚落，是方氏族人赴新加坡發展後，約於1900年代以僑匯返鄉興建。起建時格局為一落二櫸頭加右突歸，後來在突歸上增建疊樓。外牆下緣混用花崗石平砌與不同材質的亂石砌，上緣為紅磚斗砌，正身鏡面下緣以玄武岩砌成，整體樸實無華。突歸疊樓的女兒牆以煙炙磚疊砌，鏡面以綠釉花磚砌成窗，兩扇窗都有書法聯對，橫批字跡仍清楚可見。戰地政務時期屋內挖有防空洞，頗具地方特色。目前建築受損嚴重，屋頂局部塌落、植物茂盛，詳細歷史仍待未來調查。","highlights":["突歸疊樓以綠釉花磚砌成的窗","煙炙磚疊砌的疊樓女兒牆","花崗石、亂石與紅磚混搭的外牆"],"funFact":"戰地政務時期，方宅屋內挖了防空洞，讓住家同時成為避難空間。","photoSpot":"在屋外遠拍疊樓的綠釉花磚窗","visitMin":10,"openNote":"位於烈嶼鄉西方聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築受損嚴重、屋頂局部塌落，請勿靠近。可經金門大橋開車或騎車前往。","dialogue":[{"who":"A","text":"阿拉蕾，同樣在西方聚落，這間方宅走低調路線，沒有華麗的洋樓立面，卻很有味道。"},{"who":"R","text":"低調？可是我看到旁邊突出一塊，上面還多長了一層耶。"},{"who":"A","text":"那叫突歸，原本是一落二櫸頭加右邊的突歸，後來又在突歸上加蓋疊樓。"},{"who":"R","text":"房子也會長高，是喝了轉骨湯嗎？"},{"who":"A","text":"喝的是南洋僑匯！方氏族人去新加坡打拚，約在1900年代把錢寄回來蓋房子。"},{"who":"R","text":"疊樓上的窗戶綠綠的，看起來好漂亮！"},{"who":"A","text":"那是綠釉花磚砌成的窗，兩扇窗都有書法聯對，橫批到現在還看得清楚。"},{"who":"R","text":"可是房子看起來有點累了，屋頂好像塌了一塊。"},{"who":"A","text":"是啊，現在受損嚴重，請在外面看就好。遠遠找找看，綠釉花窗上的橫批寫了什麼字？"}],"clues":["我在旁邊的突歸上加蓋了一層疊樓","我的疊樓窗戶用綠釉花磚砌成","我是小金門西方聚落方姓族人的僑匯古厝"],"quiz":[{"q":"方宅疊樓的窗戶是用什麼砌成的？","options":["彩色玻璃","馬約利卡磁磚","綠釉花磚","木雕格扇"],"answer":2,"explain":"突歸疊樓的鏡面以綠釉花磚砌成窗。"},{"q":"方氏族人是到哪裡發展後返鄉建屋？","options":["新加坡","汶萊","印尼","菲律賓"],"answer":0,"explain":"方氏族人赴新加坡發展，以僑匯返鄉興建。"}],"images":[]},{"id":"jincheng-minwangci","name":"閩王祠","short":"閩王祠","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.431968,"lng":118.318427,"address":"金門縣金城鎮莒光路26巷10號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000069","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-08-26/14f42956-15a2-4e1e-8bdb-c29d18aee1bd/閩王祠_代表圖像.jpg","year":1909,"yearText":"1909年（清宣統元年）倡建，約兩年後落成","era":"qing","themes":["宗祠家廟"],"yearUnknown":false,"summary":"金門王姓族人共同的總祠","intro":"閩王祠位於金城鎮後浦市區莒光路巷內，是金門王姓的總祠。金門后宅、山后、東沙、尚義等地都有王姓族人，全縣共有九座王氏宗祠，但原本沒有總祠。1909年族人王廷恭倡議興建，他在王氏家塾執教五十多年，奔走海內外勸募，新加坡及日本宗親贊助最多，建材多是從廈門運來的上等木料與磚石，兩年後竣工，正逢中華民國肇建。1958年八二三砲戰時遭砲彈擊中，1972年起族人與印尼、新加坡宗親出資修復，之後多次整建，2003年整建為今貌。","highlights":["門前一對石獅與三扇對開門板上的門神","大廳兩側12幅王氏先賢歷史故事","中央祖龕縮小版的斗栱、吊筒木雕"],"funFact":"倡建人王廷恭在王氏家塾教書五十多年，學生滿天下，所以登高一呼就募得款項。","photoSpot":"門口埕拍石獅與「閩王祠」匾額","visitMin":15,"openNote":"位於金城鎮後浦市區莒光路巷內，為宗族祭祀使用的宗祠，官方未記載固定開放時間，請在外觀參觀並尊重祭祀活動。可搭金門縣公車到金城車站後步行前往。","dialogue":[{"who":"R","text":"Allan，這座祠堂叫閩王祠，是祭拜福建的國王嗎？"},{"who":"A","text":"名字很霸氣吧！其實它是金門王姓的總祠，算是全金門九座王氏宗祠的大家長。"},{"who":"R","text":"原來是王家的總部！什麼時候蓋的？"},{"who":"A","text":"1909年清宣統元年，由王廷恭倡議，他在王氏家塾教書五十多年，學生滿天下。"},{"who":"R","text":"老師一開口，學生都來捐錢，好有號召力！"},{"who":"A","text":"對啊，新加坡和日本的宗親捐最多，木料磚石從廈門運來，兩年後落成，剛好碰上民國肇建。"},{"who":"R","text":"那我們現在看到的是當年的樣子嗎？"},{"who":"A","text":"不是喔，1958年八二三砲戰時它被砲彈擊中，之後族人和海外宗親多次出錢修建，2003年才成今貌。"},{"who":"A","text":"如果剛好遇到祠堂開門，可以看看大廳兩側的12幅先賢故事，沒開門就找找門口那對石獅！"}],"clues":["我在清宣統元年由一位教書五十多年的老師倡建","新加坡和日本的宗親捐款最多，建材從廈門運來","我是金門王姓的總祠，位在後浦莒光路巷內"],"quiz":[{"q":"這座祠堂是金門哪一姓的總祠？","options":["陳姓","王姓","黃姓","蔡姓"],"answer":1,"explain":"閩王祠是金門王姓的總祠，全金門共有九座王氏宗祠。"},{"q":"1958年祠堂因什麼事件受損？","options":["強烈颱風","鄰屋大火","大地震","八二三砲戰"],"answer":3,"explain":"1958年八二三砲戰時遭砲彈擊中，1972年起修復。"}],"images":[]},{"id":"jinsha-pubianzhouwenxian","name":"浦邊周文献古厝","short":"周文獻古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47948,"lng":118.389853,"address":"金門縣金沙鎮浦邊19號（主入口）、20號（側門）","announced":"2019-01-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20190409000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-08/74a2aa0b-331b-4b64-9622-2945d97158fb/01封面.jpg","year":1910,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝"],"yearUnknown":true,"summary":"大展步格局與石拱挑陽台的浦邊僑匯大厝","intro":"浦邊周文獻古厝位於金沙鎮浦邊聚落，官方說明它是菲律賓僑匯建築，反映浦邊聚落的建築發展。主體是二落大厝，後落大厝身採金門少見的「大展步」格局，前方增建迴向，旁邊再接一棟兩層的疊樓，彼此圍出內院，整體配置完整而特殊。前落木屏門是雙面四季花透雕，後落步口兩側有精美的木雕斗栱組。疊樓的陽台以石拱出挑承接，相當少見。廳內神桌上的木刻神像雕法寫實，祖龕採宗祠才常見的內退式內龕，官方指出這在金門民宅中寥寥可數。民國74年（1985）屋主曾自費整修屋頂與立面，部分牆堵改為彩磁。","highlights":["左前二層疊樓以石拱出挑承接陽台","後落大厝身金門少見的大展步格局","前落雙面四季花透雕木屏門"],"funFact":"這裡的祖龕位在民宅，卻做成宗祠祖龕式的內退式內龕，官方說這種做法在金門寥寥可數。","photoSpot":"從巷口拍疊樓的石拱出挑陽台","visitMin":15,"openNote":"位於金沙鎮浦邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。旁側部分建物曾坍損，請勿靠近。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝旁邊怎麼黏著一棟兩層樓的小樓，好像大哥背著小弟？"},{"who":"A","text":"形容得好！那叫疊樓，是後來增建的。它的陽台不是用水泥板撐，而是用石拱挑出來的，很少見。"},{"who":"R","text":"用石頭拱起來托陽台？那站上去會不會有點緊張？"},{"who":"A","text":"放心，閩南匠師的功力很穩。這間主體是二落大厝，後落採用「大展步」格局，官方說在金門不多見。"},{"who":"R","text":"大展步？聽起來像武功招式耶，是要扎馬步嗎？"},{"who":"A","text":"哈哈，不是啦，是大厝身步口那一段空間的做法。這裡的木雕斗栱和四季花屏門都很精緻。"},{"who":"R","text":"蓋這麼講究的大厝，那這些錢是從哪裡來的？"},{"who":"A","text":"官方說它是菲律賓僑匯建築，代表浦邊人下南洋打拚的成果。屋裡有人住，我們在外面欣賞就好。"},{"who":"R","text":"好！那我去巷口找角度，把那個石拱托陽台的地方拍下來！"}],"clues":["我的陽台不靠樑撐，而是由石拱挑出來","我的祖龕做成宗祠式的內退式內龕，在民宅很少見","浦邊一座帶疊樓的菲律賓僑匯二落大厝"],"quiz":[{"q":"這座古厝左前方疊樓的陽台是怎麼支撐的？","options":["鋼筋水泥懸臂","木樑斜撐","石拱出挑承接","鐵柱落地支撐"],"answer":2,"explain":"二層疊樓檐口陽台採石拱出挑承接，相當特殊。"},{"q":"官方說明這座古厝是哪裡的僑匯建築？","options":["新加坡","印尼","日本","菲律賓"],"answer":3,"explain":"浦邊周文獻古厝為菲律賓僑匯建築。"}],"images":[]},{"id":"jinhu-zhengyouzhengyang","name":"鄭由整洋樓","short":"鄭由整洋樓","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.44253,"lng":118.4607,"address":"金門縣金湖鎮溪邊村73、73-3號","announced":"2006-11-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20070119000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-04/e2581b92-6fd5-42ea-bb87-ab217542eec7/1..jpg","year":1915,"yearText":"1915年（民國4年）興建，1917年竣工","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"換地興建的溪邊洋樓，見證戰地年代","intro":"鄭由整洋樓位於金湖鎮溪邊村。鄭家早年在新加坡開設「金福源」商行致富，1915年（民國4年）鄭由整之父鄭炮返鄉建屋，原定地點侵占到鄰地，便與族叔協商換地，1917年竣工。1937年家族赴新加坡避難，洋樓遭日軍占用；1949年後先作溪邊小學，1952至1955年美國情報機構西方公司在此設閩南指揮部，之後又有心戰大隊政宣部等單位借用，1958年蔣中正夫婦訪金時也曾住過。洋樓分主棟與前棟迴向，都是兩層五腳基洋樓，主棟為六柱五開間磚砌拱圈，以花瓶欄杆裝飾。","highlights":["主棟六柱五開間的磚砌拱圈外廊","二樓柱間與女兒牆的花瓶欄杆","主棟二樓花鳥木雕與人物彩繪的木製壽屏"],"funFact":"原本預定的建地侵占到鄰居土地，鄭家便和族叔換地，洋樓才蓋在現在的位置。","photoSpot":"在屋前拍主棟五開間拱圈立面","visitMin":15,"openNote":"位於金湖鎮溪邊村。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築多處破損，請勿靠近。","dialogue":[{"who":"R","text":"Allan，這棟洋樓一排拱門好整齊，數一數剛好五個！"},{"who":"A","text":"答對，主棟是六根柱子撐起五開間拱圈。屋主鄭家在新加坡開金福源商行，1915年回溪邊蓋了這棟樓。"},{"who":"R","text":"聽說蓋房子前還發生了一點小插曲？"},{"who":"A","text":"原本選的地太大，蓋到鄰居的土地，鄭家就跟族叔商量換地。這種喬地方的智慧，比我找停車位還高明。"},{"who":"R","text":"哈哈，那蓋好以後一家人就一直住在這裡嗎？"},{"who":"A","text":"沒有。1937年戰爭爆發，日軍占用洋樓。1949年後這裡當過小學，美國情報機構西方公司也在這設過指揮部。"},{"who":"R","text":"一棟民宅竟然住過這麼多單位，好像一部戰地年代的縮影！"},{"who":"A","text":"1958年蔣中正夫婦訪問金門時也住過這裡。請你在屋外看看主棟二樓柱子之間，哪裡是花瓶欄杆、哪裡是磚砌矮牆。"}],"clues":["我的建地原本侵占到鄰人土地，後來換地興建","美國情報機構西方公司曾在我這裡設閩南指揮部","我是溪邊村一座主棟五開間拱圈的新加坡僑商洋樓"],"quiz":[{"q":"鄭家在新加坡開設的商行叫什麼？","options":["金興利","宗記商行","金福源","金合利"],"answer":2,"explain":"鄭氏家族在新加坡開設「金福源」商行致富。"},{"q":"1952至1955年在鄭由整洋樓設閩南指揮部的是？","options":["金門防衛司令部","金門縣政府","溪湖國小","西方公司"],"answer":3,"explain":"美國情報機構西方公司曾在此設置閩南指揮部。"}],"images":[]},{"id":"jincheng-ouyangzhongyuan","name":"歐陽鐘遠洋樓","short":"歐陽鐘遠洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.408052,"lng":118.331587,"address":"金門縣金城鎮歐厝50號","announced":"2015-02-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150226000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-18/7452b42b-8dde-489e-9747-71c03bbbfbcf/歐陽鐘遠洋樓封面.jpg","year":1916,"yearText":"1916年（民國5年）起建，1918年完工","era":"japan","themes":["僑鄉洋樓","教育書院"],"yearUnknown":false,"summary":"民國後金門第一棟洋樓，外廊竟設在背面","intro":"歐陽鐘遠洋樓位於金城鎮歐厝聚落，由在新加坡、馬來西亞經商致富的歐陽鐘遠於1916年匯款返鄉，託親人聘請福建匠師興建，歷時兩年完工。當時聚落少有如此氣派的建築，人稱「歐厝大樓」，官方資料稱它是民國後金門第一棟洋樓。1945年鄉僑在此創辦私立金獅小學，後改為公立歐厝國民學校、沙鷗國校，1957年學校遷往珠山後改作商店。2008年起由金門國家公園管理處取得管理權並修復。它最特別的是五腳基外廊設在背面，以背為正面，與一般洋樓相反。","highlights":["五腳基外廊設在背面、以背為正面的罕見配置","人字山牆上的「獅子銜寶劍」與雙面旗泥塑","圓弧窗楣下的泥塑與花崗石人字砌牆面"],"funFact":"1948年鄉僑在洋樓創辦《獅聲座談》期刊，向海外報導家鄉消息，1949年因戰事停刊。","photoSpot":"在隘門內院拍五腳基外廊與花瓶欄杆","visitMin":15,"openNote":"位於金城鎮歐厝聚落，由金門國家公園管理處管理並修復，目前活化作為商店使用，參觀請尊重營業與現場規定。可搭金門縣公車、騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，歐厝聚落這棟洋樓，當年村裡人都叫它「歐厝大樓」，官方說它是民國後金門第一棟洋樓喔。"},{"who":"R","text":"第一棟？那蓋房子的人一定很會賺錢，是在哪裡打拚的？"},{"who":"A","text":"歐陽鐘遠在新加坡和馬來西亞經商致富，1916年匯錢回鄉，託親人請福建師傅來蓋，花了兩年才完工。"},{"who":"R","text":"Allan，我繞了一圈，怎麼覺得它的騎樓外廊長在後面？"},{"who":"A","text":"觀察力滿分！一般五腳基外廊在正面，這棟偏偏設在背面，就像我把眼鏡戴在後腦勺一樣與眾不同。"},{"who":"R","text":"那你就能看到後面有沒有人偷吃你的貢糖了，超實用！"},{"who":"A","text":"它還當過學校，1945年鄉僑在這裡辦金獅小學，後來改名沙鷗國校，1957年才遷到珠山。"},{"who":"R","text":"原來這裡以前有小朋友在背書，難怪看起來這麼有氣質。"},{"who":"A","text":"到了現場，請你抬頭找人字山牆上那隻嘴裡咬著寶劍的獅子，拍下來給我看！"}],"clues":["我的五腳基外廊不在前面，反而設在背面","我曾是金獅小學、沙鷗國校的上課地點","村裡人叫我「歐厝大樓」，是民國後金門第一棟洋樓"],"quiz":[{"q":"這棟洋樓的五腳基外廊設在哪一面？","options":["建築正面","建築背面","建築左側","建築右側"],"answer":1,"explain":"它以背為正面，外廊設在背立面。"},{"q":"1945年鄉僑在這棟洋樓創辦了什麼？","options":["私立金獅小學","僑鄉博物館","金門商會","獅聲戲院"],"answer":0,"explain":"鄉僑在歐厝大樓創立私立金獅小學。"}],"images":[{"file":"閩洋一家.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/%E9%96%A9%E6%B4%8B%E4%B8%80%E5%AE%B6.jpg/960px-%E9%96%A9%E6%B4%8B%E4%B8%80%E5%AE%B6.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%96%A9%E6%B4%8B%E4%B8%80%E5%AE%B6.jpg","artist":"Deepblue5042","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-ouyangzhongyuan-0.webp","small":"img/jincheng-ouyangzhongyuan-0-s.webp"}]},{"id":"jincheng-shuitoudihaoyang","name":"水頭417 地號洋樓（出洋客的故事）","short":"水頭417地號洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.40964,"lng":118.29834,"address":"金門縣金城鎮前水頭48、49號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000050","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-26/1b06b814-ff86-4b0e-8e53-e7e777841615/01封面.jpg","year":1916,"yearText":"約1916年（民國5年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"護龍改建的疊樓式洋樓，曾展出出洋客故事","intro":"水頭417地號洋樓位於金城鎮水頭聚落，相傳由黃金龍及其子黃廷宙、黃廷瓢所建。門匾書「燕貽鴻圖」，落款「民國丙辰」，因此推測約建於1916年。從格局看，它原本應是護龍，因地基較深而改建成二層樓、一落二櫸頭的「疊樓式」閩南折衷洋樓，前方加捲棚軒亭。一樓是西式拱圈柱廊，二樓則是中式木結構軒亭，華洋對比強烈。2001年金門國家公園管理處整體修建，設立僑鄉博物館展出「出洋客的故事」，2004年休館，後在金管處輔導下作為餐廳經營。","highlights":["一樓西式拱圈柱廊對上二樓中式木軒亭","門匾「燕貽鴻圖」與「民國丙辰」落款","二樓外牆彩繪的仿斗子砌磚縫"],"funFact":"二樓的磚縫其實是在灰泥牆上「畫」出來的仿斗子砌，遠看幾可亂真。","photoSpot":"在深井前仰拍一樓拱廊與二樓軒亭","visitMin":15,"openNote":"位於金城鎮水頭聚落，官方資料記載開放時間每日08:30至17:00、農曆除夕休館；目前作為餐廳經營，實際開放以現場公告為準。可搭金門縣公車到水頭，或從水頭碼頭步行前往。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的名字怎麼像門牌號碼，叫「417地號」？"},{"who":"A","text":"因為水頭有兩棟洋樓是用土地地號來命名的，一棟417，一棟57，好認又不會吵架。"},{"who":"R","text":"那它是誰蓋的？看起來一半洋派、一半很古典耶。"},{"who":"A","text":"相傳是黃金龍和兒子黃廷宙、黃廷瓢所建，門匾落款民國丙辰，所以推測大約是1916年。"},{"who":"A","text":"它原本是護龍，因為地基比較深，就加蓋成兩層樓，一樓西式拱廊，二樓中式軒亭，像穿西裝配長袍。"},{"who":"R","text":"這種混搭我喜歡！那門匾「燕貽鴻圖」是什麼意思？"},{"who":"A","text":"就是祈求家運昌盛、子孫興旺。對聯還寫「山不矜高自極天」，提醒後人做人別驕傲。"},{"who":"R","text":"這句送給你，每次吃完一碗廣東粥就說自己是美食家。"},{"who":"A","text":"好啦，我虛心受教。到現場請你仔細看二樓外牆的磚縫，猜猜它是真磚還是畫上去的！"}],"clues":["我原本是護龍，後來加蓋成兩層的疊樓式洋樓","我的門匾寫著「燕貽鴻圖」，落款民國丙辰","我在水頭，名字裡有一個土地地號數字"],"quiz":[{"q":"這棟洋樓的門匾題字是哪四個字？","options":["紫雲衍派","金玉滿堂","福如東海","燕貽鴻圖"],"answer":3,"explain":"門匾書「燕貽鴻圖」，祈望家運昌盛。"},{"q":"2001年修建後，這裡曾設立什麼展館？","options":["戰地史館","貢糖文化館","僑鄉博物館","民俗文物館"],"answer":2,"explain":"金管處設僑鄉博物館展出「出洋客的故事」。"}],"images":[]},{"id":"jinsha-pubianhejingzhou","name":"浦邊何敬宙洋樓","short":"何敬宙洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.479254,"lng":118.389028,"address":"金門縣金沙鎮浦邊30號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200325000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-30/bab93615-facb-4196-bc7e-3ba88b728743/01封面.jpg","year":1918,"yearText":"約1915–1920年（民國4至9年間）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"主人出資興建卻始終未能返鄉入住的洋樓","intro":"浦邊何敬宙洋樓位於金沙鎮浦邊聚落。何敬宙（1871–1936）是浦邊何氏第十八世，早年到新加坡、馬來西亞、呂宋等地經商致富，約民國4至9年間（1915–1920）匯款返鄉，由妻子陳氏邀請大陸匠師興建這棟三開間五腳基洋樓。落成後他因南洋局勢動盪始終沒有回來；兒子何文註曾參與抗日地下組織「金門復土救鄉團」，為躲避日軍追緝遠走印尼。民國38至44年國軍借作營舍，在後牆留下「反共抗俄」標語。民國108年（2019）完成整體修復，隔年由「何氏洋樓」更名為今名，以紀念創建者。","highlights":["一、二樓廊柱的六角龜紋洗石子裝飾","柱頭的「天官賜福」與壽字泥塑","背立面國軍留下的「反共抗俄」標語"],"funFact":"民國44年後宗親居住期間，一樓左側房間曾借給退伍老兵開理髮店，還為此在後牆開了一道小門。","photoSpot":"在屋前斜角拍二樓尖拱窗楣與廊柱","visitMin":15,"openNote":"位於金沙鎮浦邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。官方資料註明屋主在家時才有機會參觀，請尊重住戶意願。可開車或騎機車前往，金門縣公車班次請查詢公車處公告。","dialogue":[{"who":"A","text":"阿拉蕾，你看這棟洋樓的廊柱，表面一格一格的六角形，像不像烏龜殼？"},{"who":"R","text":"真的耶！Allan，這是誰家的房子，連柱子都這麼講究？"},{"who":"A","text":"屋主叫何敬宙，年輕時到新加坡、馬來西亞和呂宋做生意，賺了錢就寄回浦邊蓋洋樓。"},{"who":"R","text":"蓋了這麼漂亮的房子，那他住進來一定很得意吧！"},{"who":"A","text":"說來可惜，房子是太太陳氏請匠師蓋的，落成後南洋局勢不穩，他本人始終沒有回來住過。"},{"who":"R","text":"自己出錢蓋的房子卻一天都沒住到，好讓人心疼喔。"},{"who":"A","text":"後來國軍借住過，在後牆留下「反共抗俄」標語，一樓還曾借給退伍老兵開理髮店。"},{"who":"R","text":"洋樓兼理髮廳，剪完頭髮還能欣賞柱頭雕花，這服務也太高級了！"},{"who":"A","text":"現在還有家人住在這裡，我們在外面看就好。抬頭找找看，哪一根柱頭寫著「天官賜福」？"}],"clues":["我的主人出錢蓋了我，卻因南洋局勢動盪沒能回來住","我的一樓曾借給退伍老兵開理髮店","浦邊一棟廊柱有六角龜紋的五腳基洋樓"],"quiz":[{"q":"這棟洋樓興建時，實際主持工程的是誰？","options":["屋主本人","屋主的兒子","浦邊的族長","屋主的妻子陳氏"],"answer":3,"explain":"何敬宙在南洋匯款，由妻子陳氏邀請大陸匠師興建。"},{"q":"洋樓背立面留有國軍砌上的哪一句標語？","options":["反共抗俄","勤儉建國","毋忘在莒","莊敬自強"],"answer":0,"explain":"民國38至44年國軍借用時，在後寮牆砌上「反共抗俄」。"}],"images":[]},{"id":"jincheng-dongshishidongshi","name":"董石獅、董詩揚(石羊)二落大厝","short":"董石獅二落大厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.398654,"lng":118.314829,"address":"金門縣金城鎮大古崗33號","announced":"2007-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071009000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-08-15/7862efef-8131-433b-b616-6fe9ccf474a1/1.董石獅、董詩揚(石羊)二落大厝-代表圖像.jpg","year":1920,"yearText":"年代不詳（約清末至民國初年）","era":"unknown","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":true,"summary":"兩組匠師對場拼建，櫸頭上還起了軒亭","intro":"董石獅、董詩揚（石羊）二落大厝位於金城鎮大古崗聚落。清末董石獅赴新加坡發展，並引薦弟弟董詩揚的兒子前往，由董石獅與董詩揚之子金國、金鐘、金圖共同出資，董詩揚監工興建。建造時委託兩組師傅以中軸線分左右「拼場」施工，至今仍可從磚材、砌法與手藝看出差異，在民宅中相當少見。大厝為三開間二落，前後落皆為圓規山牆，後落比一般大厝高，深井兩側櫸頭上各起一座軒亭，為金門罕見。日軍占領期間曾被強行占用，1949至1958年部分空間由國軍使用，砲戰時正面石牆與石窗曾被砲彈擊中損壞。","highlights":["左右兩邊由不同匠師「拼場」的牆體差異","櫸頭磚坪上的軒亭與星月、號角寶劍泥塑","圓規山牆上的天使與老鷹泥塑脊墜"],"funFact":"前廳橫楣的歷史故事彩繪出自彩繪師傅陳顯祖、陳景輝之手。","photoSpot":"在正面拍左右兩半的牆面做比較","visitMin":15,"openNote":"位於金城鎮大古崗聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；後落屋頂崩塌，請保持距離。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這棟大厝左右兩邊看起來好像有一點點不一樣耶？"},{"who":"A","text":"好眼力！這叫拼場，請兩組師傅以中軸線為界，各蓋一半，互相較勁手藝。"},{"who":"R","text":"好像烹飪比賽，左邊一隊右邊一隊，最後看誰做得漂亮！"},{"who":"A","text":"正是如此，磚材、砌法都不一樣，在民宅裡很少見。房子由董石獅和弟弟董詩揚家族一起出錢。"},{"who":"R","text":"他們家也是去南洋打拚，才有錢蓋大厝的嗎？"},{"who":"A","text":"清末董石獅到新加坡發展，還帶姪子們一起去，賺了錢再合力回鄉蓋屋。"},{"who":"A","text":"日軍占領時這裡曾被強行占用，後來砲戰期間正面石牆和石窗也被砲彈擊中受損。"},{"who":"R","text":"這棟房子經歷好多事，可是天使和老鷹還是站在山牆上守著。"},{"who":"A","text":"等一下我請你吃貢糖當評審費。請在屋外比較左右兩邊的牆面，你覺得哪一隊贏？"}],"clues":["我是請兩組匠師以中軸線分左右「拼場」蓋成的","我的櫸頭上各起一座軒亭，山牆有天使和老鷹泥塑","我在大古崗，由一對兄弟家族合建"],"quiz":[{"q":"這座大厝用什麼特殊方式興建？","options":["一位匠師獨力完成","兩組匠師左右拼場","全部從南洋運來組裝","由軍隊協助興建"],"answer":1,"explain":"以中軸線分左右，由兩組師傅拼場興建。"},{"q":"董石獅清末前往哪裡發展？","options":["菲律賓","印尼","緬甸","新加坡"],"answer":3,"explain":"清末董石獅至新加坡發展，並引薦姪子前往。"}],"images":[]},{"id":"jinning-wengjunqinzhentuan","name":"翁君琴、振團、耀韮三代古厝","short":"翁家三代古厝","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.44824,"lng":118.34044,"address":"金門縣金寧鄉頂堡109號","announced":"2007-01-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20070119000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-25/c2608ad2-edcc-43b8-94c9-7441f778b459/1.jpg","year":1920,"yearText":"年代不詳（由祖孫三代接力完成）","era":"unknown","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":true,"summary":"祖孫三代接力完成、滿牆彩磁的雙落大厝","intro":"翁君琴、振團、耀韮三代古厝位於金寧鄉盤山村頂堡。翁君琴在清道光年間前往印尼發展，用積蓄買下橡膠園經營致富，再匯錢返鄉，由兒子翁振團購買建屋材料，最後由孫子翁耀韮完成興建，一棟房子串起祖孫三代。古厝為傳統閩式雙落大厝，正立面的榻受牆、對看堵、水車堵、拱仔頭與直櫺窗大量使用日製彩釉磁磚，也就是馬約利卡磁磚，門額印有「六桂衍派」，屋脊有剪黏與彩繪泥塑。1949年國軍駐守金門，女青年工作隊曾住在這裡，後來師長家眷也一同入住，直到1953年後才搬離。1958年八二三砲戰時，家人在深井挖了防空洞躲避砲擊，現已填平。","highlights":["正立面大量使用的馬約利卡彩釉磁磚","門額「六桂衍派」字樣","屋脊的剪黏與彩繪泥塑"],"funFact":"八二三砲戰時，屋主在古厝的深井裡挖了防空洞躲砲彈，如今已經填平。","photoSpot":"在前埕拍滿是彩磁的榻受牆與對看堵","visitMin":10,"openNote":"位於金寧鄉盤山村頂堡。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，蓋一棟房子要多久？這棟古厝的答案是：要三代人。"},{"who":"R","text":"三代？那不就是阿公出錢、爸爸買料、孫子動工的接力賽嗎？"},{"who":"A","text":"完全正確！翁君琴在清道光年間到印尼經營橡膠園，兒子翁振團買建材，孫子翁耀韮把它蓋完。"},{"who":"R","text":"這比我寫暑假作業還要拖，不過結果好漂亮！"},{"who":"A","text":"正面貼滿彩色磁磚，叫馬約利卡磁磚，從榻受牆、對看堵到窗戶都有，是僑鄉最潮的裝潢。"},{"who":"R","text":"這棟古厝後來有沒有住過特別的客人？"},{"who":"A","text":"1949年女青年工作隊住過這裡，後來師長家眷也搬進來。八二三砲戰時家人還在深井挖防空洞。"},{"who":"R","text":"原來漂亮的房子也有緊張的日子。"},{"who":"A","text":"是啊。請你在門額找一找「六桂衍派」四個字，順便數數旁邊的磁磚有幾種花色！"}],"clues":["我由阿公出錢、兒子買料、孫子完工","女青年工作隊曾住過我，深井還挖過防空洞","我在盤山頂堡，門額寫「六桂衍派」，滿牆彩磁"],"quiz":[{"q":"翁君琴當年在印尼經營什麼致富？","options":["椰乾貿易","錫礦","茶葉公司","橡膠園"],"answer":3,"explain":"翁君琴前往印尼發展，買下橡膠園經營後致富。"},{"q":"八二三砲戰時，屋主在古厝的哪裡挖了防空洞？","options":["前埕","深井","護龍","後巷"],"answer":1,"explain":"為躲避砲彈，在建築深井空間開挖防空洞，現已填平。"}],"images":[]},{"id":"jincheng-gugangxuexiao","name":"古崗學校","short":"古崗學校","category":"歷史建築","level":"","town":"金城鎮","types":["學校"],"lat":24.39937,"lng":118.31486,"address":"金門縣金城鎮大古崗54號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000025","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-21/1c3e74ce-f8e6-4046-8936-b0156340d778/1 封面.jpg","year":1921,"yearText":"1921年（民國10年）興建，1922年落成","era":"japan","themes":["教育書院","僑鄉洋樓"],"yearUnknown":false,"summary":"印尼鄉僑董允耀號召興建的五腳基洋樓校舍","intro":"古崗學校位於金城鎮古崗聚落，緊鄰董氏家廟。民國初年古崗借用董氏家廟當私塾，旅居印尼的鄉僑董允耀（1880–1945）返鄉時見家鄉教育資源匱乏，號召族親並向南洋鄉僑募款，在家廟旁興建學校，1921年動工、1922年落成。學校增設國語、算術、自然、音樂等科目，還創辦《鏡光月刊》向南洋報告辦學情形；董允耀又在鼓浪嶼購置店屋、戲院與洋樓收租，支應校務。1933年在此設金城國校，後改名古崗國校，1959年併入古城國校。建築為五腳基洋樓，山頭題「誠實」二字，2005年修復完成。","highlights":["五彎波浪形山頭上題寫的「誠實」二字","中央石柱聯對「古博今通振興教育」","女兒牆末端柱頭上的石獅裝飾"],"funFact":"門柱聯對的橫批寫作「古岡學校」，用的是「岡」字，不是「崗」。","photoSpot":"正面拍六柱五開間與「誠實」山頭","visitMin":15,"openNote":"位於金城鎮古崗聚落董氏家廟旁，由古崗董氏宗親會管理，規劃作為展示空間並搭配賣店使用，開放時間請以現場公告為準。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，這棟有拱廊的洋樓看起來像豪宅，其實是一間學校，古崗學校。"},{"who":"R","text":"學校長這樣？那上課時會不會一直想看窗外的風景？"},{"who":"A","text":"很有可能喔。1921年，旅居印尼的董允耀回鄉，發現孩子只能在家廟裡上私塾，決定蓋一間新學校。"},{"who":"R","text":"從印尼回來就蓋學校，好有心！錢從哪裡來？"},{"who":"A","text":"他自己捐款，又向南洋鄉僑募款，還辦了「鏡光月刊」，讓海外鄉親知道學校辦得怎麼樣。"},{"who":"R","text":"好像學校的電子報耶！那現在還在上課嗎？"},{"who":"A","text":"1959年就併入古城國校了。他還在鼓浪嶼買房收租當辦學基金，真是深謀遠慮。"},{"who":"R","text":"比Allan存零用錢買燒餅厲害太多了吧！"},{"who":"A","text":"這點我承認。請你抬頭找山頭上的兩個大字，那是學校給學生最重要的叮嚀！"}],"clues":["我由旅居印尼的鄉僑號召族親興建","我曾設金城國校，1959年併入古城國校","我的山頭寫著「誠實」，旁邊就是董氏家廟"],"quiz":[{"q":"號召興建古崗學校的董允耀旅居哪裡？","options":["新加坡","菲律賓","印尼","馬來西亞"],"answer":2,"explain":"旅居印尼的鄉僑董允耀號召族親興建學校。"},{"q":"古崗學校山頭上題的是哪兩個字？","options":["誠實","勤儉","忠孝","博愛"],"answer":0,"explain":"五彎拱波浪形山頭上題「誠實」二字。"}],"images":[]},{"id":"jincheng-houpuhezhai","name":"後浦何宅","short":"後浦何宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43136,"lng":118.31669,"address":"金門縣金城鎮民族路210巷12號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000066","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/f1ceafbb-8b9c-4473-af11-15dc73d9c90d/後浦何宅_封面.jpg","year":1921,"yearText":"1921年（民國10年）","era":"japan","themes":["僑鄉洋樓","宗教信仰"],"yearUnknown":false,"summary":"惠安木匠與幫傭妻子胼手胝足蓋起的洋樓","intro":"後浦何宅位於金城鎮後浦城區民族路巷內，興建於民國10年（1921），由何夫人陳氏興建。何水贊是福建惠安籍木匠，因工作四處遷徙，何夫人陳氏因此遷居金門，起初租屋並靠幫傭維持家計，夫妻以畢生積蓄買地蓋屋，在後浦落地生根。何家信奉基督教，選擇當時流行的洋樓樣式，入口門聯寫著「主賜平安」。何夫人享壽103歲，葬禮在基督教會堂舉行。1949年後二樓部分空間曾由國軍高階將領借住。建築以五腳基洋樓為主，女兒牆有水泥預鑄花瓶欄杆與獎盃，落水口做成泥塑鰲魚。因前方與右側緊鄰民宅，從外面主要看得到左側與背面。","highlights":["女兒牆上的水泥預鑄獎盃與波浪形花瓶欄杆","泥塑鰲魚造型的落水口","左側入口門樓的幾何圖形洗石子飾面"],"funFact":"何家信奉基督教，洋樓入口的門聯寫的是「主賜平安」。","photoSpot":"巷道中拍左側門樓與二樓圓弧窗楣","visitMin":10,"openNote":"位於金城鎮後浦城區民族路巷內，官方資料記載參觀需洽詢屋主。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。從金城車站步行可達。","dialogue":[{"who":"R","text":"Allan，金門的洋樓，不都是落番發財的華僑蓋的嗎？"},{"who":"A","text":"大部分是，但這棟後浦何宅不一樣。它是惠安來的木匠何水贊和太太陳氏，一點一滴存錢蓋的。"},{"who":"R","text":"木匠蓋自己的房子，那一定很講究吧！"},{"who":"A","text":"何夫人當年在金門靠幫傭維持家計，夫妻用畢生積蓄買地，1921年蓋起這棟洋樓。"},{"who":"R","text":"好感人，這才是真正的白手起家！"},{"who":"A","text":"何家信奉基督教，入口門聯就寫主賜平安。何夫人活到103歲，金門麵線象徵長壽，她就是最好的代言人。"},{"who":"R","text":"哈哈，那洋樓上有什麼可愛的裝飾？"},{"who":"A","text":"屋頂女兒牆上有水泥做的獎盃，排水口還是一條泥塑鰲魚。"},{"who":"A","text":"前面和右邊都貼著民宅，請在巷子裡從左側看，找找那隻鰲魚是從哪裡吐水的！"}],"clues":["我的主人是惠安來的木匠，太太靠幫傭維持家計","我的門聯寫著「主賜平安」","我在後浦巷內，排水口是一條泥塑鰲魚"],"quiz":[{"q":"何宅男主人何水贊原本從事什麼工作？","options":["木匠","船員","商人","教師"],"answer":0,"explain":"何水贊為福建惠安籍木匠，因工作遷徙各地。"},{"q":"何宅屋頂的落水口做成什麼造型？","options":["獅頭","龍頭","鰲魚","葫蘆"],"answer":2,"explain":"女兒牆的落水口造型為泥塑鰲魚。"}],"images":[]},{"id":"jincheng-dengzhangshouyang","name":"鄧長壽洋樓","short":"鄧長壽洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.432686,"lng":118.318246,"address":"金門縣金城鎮浯江街53號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000065","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-28/63333a34-a496-4506-90c3-2fc201a84e8a/鄧長壽洋樓封面.jpg","year":1921,"yearText":"1921年（民國10年）","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"從僑宅變成戰地招待所的出龜洋樓","intro":"鄧長壽洋樓位於金城鎮後浦浯江街，1921年由新加坡華僑鄧長壽興建。戰地政務時期曾作為第一招待所（浯江招待所），1960年後改為招待外賓、將軍及勞軍藝人的場所。美援期間，臺灣基督教救濟會與天主教福利會在金門進行賑濟，救濟會便設在這棟洋樓，直到1995年才歸還民用。洋樓外有圍牆環繞，分為前棟出龜洋樓與後棟，皆為二層。米白色山頭分上下兩段，上段兩望柱間有獅頭泥塑，柱頭立著寶燈；下段為弧形，飾有花鳥捲草。目前建築被大型榕樹攀附，樹根深入牆體造成裂隙。","highlights":["山頭望柱間的獅頭泥塑與柱頂寶燈","向前突出的「出龜」洋樓造型","二樓正側面的三角形窗楣"],"funFact":"這棟洋樓戰地政務時期接待過外賓、將軍與勞軍藝人，是後浦的「戰地招待所」。","photoSpot":"在浯江街上拍米白色山頭與寶燈","visitMin":10,"openNote":"位於金城鎮後浦浯江街，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築受榕樹攀附損壞，請保持距離。金城車站附近，可步行前往。","dialogue":[{"who":"R","text":"Allan，這棟米白色洋樓的山頭上，怎麼好像有兩盞燈？"},{"who":"A","text":"那是泥塑的寶燈，立在望柱上，中間還有一顆獅頭。這是新加坡華僑鄧長壽在1921年蓋的。"},{"who":"R","text":"那這棟洋樓一直都是鄧家人自己住的嗎？"},{"who":"A","text":"不完全是。戰地政務時期它變成第一招待所，也叫浯江招待所，接待外賓、將軍和勞軍藝人。"},{"who":"R","text":"勞軍藝人！所以以前有明星住過這裡嗎？"},{"who":"A","text":"官方資料只說是勞軍藝人的招待場所，名字就不亂猜了。美援期間，基督教救濟會也設在這裡。"},{"who":"R","text":"從僑宅到招待所再到救濟會，這棟樓的履歷好豐富。"},{"who":"A","text":"直到1995年才歸還民用。可惜現在被大榕樹抱得太緊，樹根都鑽進牆裡了。"},{"who":"A","text":"請你在浯江街上找找看，山頭那顆獅頭的兩旁，各立著幾盞寶燈！"}],"clues":["我的山頭立著寶燈，中間有一顆獅頭泥塑","戰地政務時期我是接待外賓與勞軍藝人的招待所","我在後浦浯江街，1921年由新加坡華僑興建"],"quiz":[{"q":"戰地政務時期，鄧長壽洋樓曾作為什麼用途？","options":["第一招待所","戰地醫院","心戰廣播站","軍官學校"],"answer":0,"explain":"曾為第一招待所，又稱浯江招待所。"},{"q":"鄧長壽洋樓在哪一年歸還民用？","options":["1960年","1979年","1992年","1995年"],"answer":3,"explain":"救濟會使用至1995年才歸還民用。"}],"images":[]},{"id":"jinhu-chenjinglanyanglou","name":"陳景蘭洋樓（陳坑大洋樓）","short":"陳景蘭洋樓","category":"歷史建築","level":"","town":"金湖鎮","types":["宅第"],"lat":24.437288,"lng":118.390161,"address":"金門縣金湖鎮成功1-1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000015","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-29/629f9037-1b0c-4b7e-87bb-d51b74f2f77c/01封面.jpg","year":1921,"yearText":"1921年（民國10年）落成","era":"japan","themes":["僑鄉洋樓","名人故居","戰地史蹟"],"yearUnknown":false,"summary":"金門規模最大的洋樓，見證僑鄉與戰地","intro":"陳景蘭洋樓位於金湖鎮成功聚落，又稱陳坑大洋樓。陳景蘭（1881–1941）21歲南渡新加坡，後在印尼勿里洞創辦南金號，並在新加坡設成源號，成為南洋重要僑商。民國6年（1917）他攜回洋人設計的藍圖返鄉建屋，聘廈門、金門匠師施工，歷時四年於1921年完工，成為金門規模最大的洋樓，部分空間還作為陳坑小學校舍。此後洋樓歷經日軍占領時期占用、國軍醫院、金門中學臨時宿舍與官兵休假中心等用途，1999年颱風造成屋頂崩塌，2008年修復後作為展示館開放。","highlights":["正面八柱七開間拱廊與「景蘭山莊」泥塑","陳景蘭題句「余望後輩當念建業艱難」","右側附屬建築山牆上的「1921」字樣"],"funFact":"建材用三桅帆船運到陳坑海邊，再以騾車運上岸，整個工程花費超過十萬元。","photoSpot":"在前埕欄杆邊拍拱廊全景與海灣","visitMin":40,"openNote":"位於金湖鎮成功聚落，官方資料記載每日8:30至17:30開放，館內有自導式解說展示，由金湖鎮公所管理。可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"A","text":"站在成功聚落的高處往下看，整片南部海灣都在眼前，這棟大洋樓的主人很會挑地點。"},{"who":"R","text":"哇，Allan，前面一整排拱門，好像歐洲宮殿！主人是誰呀？"},{"who":"A","text":"他叫陳景蘭，21歲到新加坡打拚，後來在印尼勿里洞開了南金號，成為南洋僑商。"},{"who":"R","text":"從南洋打拚回來，他是怎麼把房子蓋起來的？"},{"who":"A","text":"民國6年他帶著洋人畫的藍圖回鄉，建材用三桅帆船運到海邊，再讓騾車拉上岸，蓋了整整四年。"},{"who":"R","text":"騾車快遞！這麼辛苦蓋好的房子，後來一直是陳家人在住嗎？"},{"who":"A","text":"用途可多了，當過小學校舍、醫院、金門中學臨時宿舍和官兵休假中心，2008年修復後才開放。"},{"who":"R","text":"一棟樓換過這麼多身分，根本是演技派！"},{"who":"A","text":"而且主人還題了「余望後輩當念建業艱難」。進館後找找這句話，再到右側山牆找「1921」字樣吧！"}],"clues":["我當過小學、醫院、宿舍，也當過官兵休假中心","我的主人在勿里洞開南金號，在新加坡設成源號","我是金門規模最大的洋樓，位在金湖鎮成功聚落"],"quiz":[{"q":"陳景蘭洋樓的建材是怎麼運上岸的？","options":["用騾車拉上岸","用牛車拉上岸","由人力肩挑","用滑輪吊上岸"],"answer":0,"explain":"建材由三桅帆船運到陳坑海邊，再以騾車運上岸。"},{"q":"洋樓修復完成、作為展示館是在哪一年？","options":["1999年","2004年","2008年","2012年"],"answer":2,"explain":"2008年8月修復竣工，再利用為展示館。"}],"images":[{"file":"金門 陳景蘭洋樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/%E9%87%91%E9%96%80_%E9%99%B3%E6%99%AF%E8%98%AD%E6%B4%8B%E6%A8%93.jpg/960px-%E9%87%91%E9%96%80_%E9%99%B3%E6%99%AF%E8%98%AD%E6%B4%8B%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80_%E9%99%B3%E6%99%AF%E8%98%AD%E6%B4%8B%E6%A8%93.jpg","artist":"Shuzhenlee","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinhu-chenjinglanyanglou-0.webp","small":"img/jinhu-chenjinglanyanglou-0-s.webp"}]},{"id":"jincheng-jidujiaohuitang","name":"基督教會堂","short":"基督教會堂","category":"歷史建築","level":"","town":"金城鎮","types":["教堂"],"lat":24.433771,"lng":118.317543,"address":"金門縣金城鎮珠浦北路30、30-1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000018","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-30/b61cc196-8286-45d2-beff-ab08c06e082a/基督教會堂 (1).jpg","year":1924,"yearText":"1924年（民國13年）","era":"japan","themes":["宗教信仰","公共建築"],"yearUnknown":false,"summary":"山牆刻著1924的紅磚教堂，還有美國製福音鐘","intro":"基督教會堂位於金城鎮珠浦北路。1922年歐陽侯牧師因舊教堂不敷使用，發起興建新教堂，購買清代舊縣丞署原址的部分土地，興建會所並附設培德小學與幼稚園，教堂於1924年落成。1929年以剩餘款項購置一口福音鐘，鐘座鑄有美國俄亥俄州製造商的字樣；1950年代曾被軍方徵用作警報器，1970年才歸還教會。教堂是一層番仔厝，紅磚牆身、花崗石基座，山牆刻著「基督教會堂」與「1924」，上方有立體十字架。原牧師樓建於1934年，2006至2007年拆除重建；教堂在2010年完成整體修復，至今仍是聚會場所。","highlights":["山牆上的「基督教會堂」與「1924」字樣","山牆頂端的立體十字架與兩側花瓶欄杆","1929年購置、曾當警報器的美國製福音鐘"],"funFact":"教會的福音鐘在1950年代被軍方徵用當警報器，直到1970年才歸還教會。","photoSpot":"前埕外拍山牆十字架與「1924」","visitMin":15,"openNote":"位於金城鎮珠浦北路，至今仍是教會聚會場所，官方資料記載依教會活動時間開放，聚會時請保持安靜、勿打擾。從金城車站步行可達。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看看山牆，上面刻著哪一個年份？"},{"who":"R","text":"1924！還有一個立體的十字架，這裡是教堂吧？"},{"who":"A","text":"答對了，這是金城的基督教會堂。1922年歐陽侯牧師覺得舊教堂太擠，發起蓋新的，1924年落成。"},{"who":"R","text":"那教堂蓋在這裡，有什麼特別的原因嗎？"},{"who":"A","text":"這塊地是清代舊縣丞署原址的一部分。教會還辦了培德小學和幼稚園，熱鬧得很。"},{"who":"R","text":"從衙門變成教堂和學校，這塊地的轉職也太成功了！"},{"who":"A","text":"還有更妙的。1929年教會買了一口美國製的福音鐘，1950年代竟被軍方借去當警報器。"},{"who":"R","text":"從叫大家來做禮拜，變成提醒大家注意警報，這口鐘也太忙了吧！"},{"who":"A","text":"直到1970年才回到教會。請在前埕外看看山牆兩側的花瓶欄杆，數數一邊有幾根。"}],"clues":["我的土地原是清代舊縣丞署的一部分","1950年代，我的鐘被借去當警報器","我的山牆刻著1924，頂上有立體十字架"],"quiz":[{"q":"教會的福音鐘在1950年代曾被當作什麼？","options":["學校上課鐘","警報器","寺廟鐘","船鐘"],"answer":1,"explain":"福音鐘曾遭軍方徵用作為警報器，1970年歸還。"},{"q":"基督教會堂的土地原本是清代的什麼地方？","options":["總兵署","浯江書院","內校場","舊縣丞署原址"],"answer":3,"explain":"教會購買清代舊縣丞署原址的部分土地興建。"}],"images":[]},{"id":"jincheng-mofanjie","name":"模範街（一度於戰地政務時期稱為自強街)","short":"模範街","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.43193,"lng":118.31924,"address":"金門縣金城鎮東門里模範街","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000020","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-23/fc29c903-03f5-4bfe-a2db-e691a5663005/01封面.jpg","year":1924,"yearText":"1924年（民國13年）","era":"japan","themes":["市場商業","僑鄉洋樓"],"yearUnknown":false,"summary":"南洋集資興建的紅磚拱廊老街，後浦舊商業中心","intro":"模範街位於金城鎮東門里，1924年由金門縣商會會長傅錫琪與仕紳翁同文等人倡議，向南洋集資興建，基地是明鄭時期的內校場。全長約75公尺，直街與橫街共40間店屋，由惠安匠師王廷元設計，紅磚拱廊受南洋「五腳基」風格影響，但各戶自聘師傅施工，所以窗楣與二樓細節各不相同。1950、60年代縣政府、郵局、衛生院等機關曾設在附近，1960年前後是後浦的民生消費中心；「單打雙不打」期間也曾是砲擊目標之一，店屋部分輕微損毀。後來機關陸續遷出，商圈轉移；1980年曾改名自強街，戰地政務解除後已少有人這樣稱呼。","highlights":["整排紅磚拱廊與綠釉花瓶欄杆女兒牆","每戶窗楣不同，有圓拱、平頂、火焰造型","窗楣上的卍字、壽桃與篆體字磚雕"],"funFact":"店屋外觀由王廷元統一設計，但各戶自己找師傅施工，所以每家的窗戶都不一樣。","photoSpot":"街口沿著拱廊拍出紅磚透視感","visitMin":30,"openNote":"位於金城鎮東門里，街道全天開放；店屋由各戶自行經營或居住，營業時間依各店家，請勿擅入私人空間。從金城車站步行可達，鄰近總兵署。","dialogue":[{"who":"R","text":"Allan，這條紅磚拱廊街好好拍！為什麼叫模範街？"},{"who":"A","text":"1924年它蓋好時，金門人都很羨慕，商會會長傅錫琪就取名模範街，要當新時代商街的模範。"},{"who":"R","text":"自己取名叫模範，好有自信！錢是從哪裡來的？"},{"who":"A","text":"向南洋鄉親集資，基地是明鄭時期的內校場。全長約75公尺，共有40間店屋。"},{"who":"R","text":"怪不得這排拱廊看起來這麼有南洋味！"},{"who":"A","text":"這叫五腳基，騎樓讓人遮陽避雨。外觀由惠安匠師王廷元設計，可是每戶各自找師傅施工。"},{"who":"R","text":"所以每一家店屋長得都不太一樣嗎？"},{"who":"A","text":"對，拱廊統一，窗楣卻有圓拱、平頂、火焰造型。單打雙不打時期，這裡也曾受到砲擊，所幸店屋只有輕微損毀。"},{"who":"A","text":"走一趟拱廊，邊吃燒餅邊找找看，哪一戶的窗楣上有壽桃磚雕！"}],"clues":["我由南洋集資興建，基地原是明鄭的內校場","我有40間店屋，窗楣造型各不相同","戰地政務時期我曾被改名為自強街"],"quiz":[{"q":"模範街的基地原本是什麼地方？","options":["清代縣丞署","明鄭時期內校場","右營遊擊署","魚市場"],"answer":1,"explain":"傅錫琪等人購置明鄭時期的內校場作為基地。"},{"q":"模範街店屋的拱廊風格深受什麼影響？","options":["日本町家","歐洲巴洛克","北方四合院","南洋五腳基"],"answer":3,"explain":"紅磚拱廊受南洋熱帶殖民建築五腳基影響。"}],"images":[]},{"id":"jinsha-biyuexuan","name":"碧月軒","short":"碧月軒","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47937,"lng":118.38919,"address":"金門縣金沙鎮浦山村浦邊35號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000013","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-19/478b41fd-b062-4c4c-8cbb-2e77fc1a2e68/碧月軒_封面.jpg","year":1924,"yearText":"1924年（民國13年）落成","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"山頭立著聖母與天使像的浦邊洋樓","intro":"碧月軒位於金沙鎮浦邊聚落，主人何敬槐約清光緒16年（1890）前往菲律賓，省吃儉用把收入匯回金門，還回饋鄉里興建學堂。民國9年（1920）他回鄉籌建碧月軒，花費約白銀7000元，聘請福州匠師設計，民國13年（1924）落成。洋樓在舊有傳統民居格局上向上加蓋，正面四柱三開間，用不同粒徑的蠣殼洗石子做出八卦紋、柿蒂紋與牡丹花瓶等裝飾；山頭有老鷹、雙獅泥塑，頂端還立著瑪麗亞與天使塑像。民國28年（1939）何家因戰亂遷往新加坡，洋樓從此閒置，樓板屋頂已坍塌，民國109年搭設鋼棚架暫時防護。","highlights":["山頭頂端的瑪麗亞雕像與天使塑像","二樓陽台柱上「登高門第須積善」聯對","門額兩側牡丹花瓶蠣殼洗石子裝飾"],"funFact":"二樓聯對「豈但欲窮千里，須當更上一層」，把登樓的名句變成勉勵子孫讀書向上的家訓。","photoSpot":"在屋外遠處仰拍山頭的聖母天使像","visitMin":10,"openNote":"位於金沙鎮浦邊聚落。私人產權，現況閒置、樓板與屋頂坍塌並搭有鋼棚架，請在外觀參觀，勿擅入、勿靠近。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，抬頭看這棟洋樓最頂端，你看到什麼？"},{"who":"R","text":"咦，有一位聖母和天使站在屋頂上！Allan，金門的古厝不是都放風獅爺嗎？"},{"who":"A","text":"所以才特別！主人何敬槐清光緒年間就到菲律賓打拚，帶回了南洋混搭的審美。"},{"who":"R","text":"他是在菲律賓賺了很多錢，才蓋得起這種洋樓嗎？"},{"who":"A","text":"他很節儉，一筆一筆匯回家，還捐錢蓋學堂。民國9年回鄉蓋洋樓，花了約白銀7000元。"},{"who":"R","text":"那現在何家的子孫還住在這棟洋樓裡嗎？"},{"who":"A","text":"民國28年因為戰亂，家人搬到新加坡，房子就閒置了，現在樓板屋頂都塌了，只能在外面看。"},{"who":"R","text":"好可惜，那二樓柱子上寫的字是什麼意思？"},{"who":"A","text":"「登高門第須積善，要好兒孫在讀書」，比我老爸的碎碎念有文采多了。你從遠處數數看，屋頂上有幾隻獅子？"}],"clues":["我的屋頂站著聖母與天使，在金門古厝中很少見","我的主人清光緒年間就到菲律賓打拚，還在家鄉捐建學堂","浦邊一棟以門額三字為名的洋樓，現在罩著鋼棚架"],"quiz":[{"q":"碧月軒的山頭頂端立著什麼塑像？","options":["瑪麗亞與天使","風獅爺","關公與媽祖","福祿壽三仙"],"answer":0,"explain":"山頭頂有瑪麗亞雕像與天使塑像，形成視覺焦點。"},{"q":"何家在哪一年因戰亂舉家遷往新加坡？","options":["1920年","1924年","1930年","1939年"],"answer":3,"explain":"民國28年（1939）何以碧舉家遷往新加坡。"}],"images":[{"file":"Biyuexuan (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/14/Biyuexuan_%28cropped%29.jpg/960px-Biyuexuan_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Biyuexuan_(cropped).jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-biyuexuan-0.webp","small":"img/jinsha-biyuexuan-0-s.webp"}]},{"id":"jincheng-huangwendongzhai","name":"黃文東宅","short":"黃文東宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40976,"lng":118.30045,"address":"金門縣金城鎮前水頭17號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000035","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/6f2182cc-f79d-476f-b369-82d4d8d13afd/黃文東宅_封面.jpg","year":1925,"yearText":"1925年（民國14年，乙丑年）","era":"japan","themes":["閩南古厝"],"yearUnknown":false,"summary":"門額落款「乙丑年 文東建造」的大厝","intro":"黃文東宅位於金城鎮水頭聚落，建於1925年，是黃文東到印尼麻里巴板經商後匯款返鄉興建的傳統閩式二落大厝。大門上方有「江夏流芳」堂號門額，並落款「乙丑年 文東建造」，外側聯對書有「靜以修身儉以養德，入則篤行出則友賢」。建築用料講究、施工精細，雙落皆為翹脊，脊墜有泥塑與交趾陶；鳳凰牡丹木雕插角象徵富貴吉祥，裙堵四角有蝙蝠、蝴蝶磚雕。屋主細心維護，保存狀況良好，並保有當年購地的賣契與驗稅契證。","highlights":["門額「乙丑年 文東建造」的落款","象徵富貴吉祥的鳳凰牡丹木雕插角","裙堵四角的蝙蝠、蝴蝶磚雕"],"funFact":"門額落款「乙丑年 文東建造」，乙丑年就是1925年，屋主把名字直接寫在門上。","photoSpot":"在前埕外拍門額落款與翹脊","visitMin":10,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往水頭。","dialogue":[{"who":"R","text":"Allan，這棟門上寫著「乙丑年 文東建造」，好像在簽名耶！"},{"who":"A","text":"這就是古厝的簽名檔。乙丑年是1925年，屋主黃文東在印尼麻里巴板經商，匯錢回鄉蓋了這棟大厝。"},{"who":"R","text":"把名字寫在大門上，好有自信！門邊的對聯又寫什麼？"},{"who":"A","text":"外側寫「靜以修身儉以養德，入則篤行出則友賢」，等於把家訓直接貼在門口。"},{"who":"R","text":"這比貼在冰箱上的便條紙還有效！"},{"who":"A","text":"而且這棟用料講究、施工精細，屋主一直細心維護，到現在還保存得很好。"},{"who":"R","text":"難怪看起來這麼整齊！還有什麼細節？"},{"who":"A","text":"插角還有鳳凰牡丹木雕象徵富貴吉祥，裙堵四角則有蝙蝠和蝴蝶磚雕。"},{"who":"R","text":"蝙蝠也算吉祥圖案嗎？我以為牠很可怕。"},{"who":"A","text":"蝠和福同音，是好兆頭。這裡有人住，請在外面找找看，蝙蝠和蝴蝶磚雕各藏在哪個角落！"}],"clues":["我的門額寫著乙丑年和屋主的名字","我的主人在印尼麻里巴板經商，1925年匯款回鄉建屋","我是水頭聚落的二落大厝，堂號是江夏流芳"],"quiz":[{"q":"門額落款的「乙丑年」是西元幾年？","options":["1913年","1937年","1925年","1901年"],"answer":2,"explain":"黃文東宅建於1925年，即乙丑年。"},{"q":"裙堵四角的磚雕是什麼圖案？","options":["蝙蝠與蝴蝶","龍與鳳","獅與象","鯉魚與蝦"],"answer":0,"explain":"裙堵四角有蝙蝠、蝴蝶磚雕裝飾。"}],"images":[]},{"id":"jinsha-hejingyanzhai","name":"何敬嚴宅（小築佳趣）","short":"小築佳趣","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47894,"lng":118.38816,"address":"金門縣金沙鎮浦邊66號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000012","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-30/70f4ef22-0235-4e8c-9928-1b4db3245bcb/何敬嚴宅（小築佳趣）.jpg","year":1925,"yearText":"1920年代（民國10年代）","era":"japan","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"二樓蓋了涼亭的罕見疊樓古厝","intro":"何敬嚴宅位於金沙鎮浦邊聚落，門上匾額題「小築佳趣」。民國10年代（1920年代），何敬嚴在呂宋經營橡膠園，寄款返鄉興建此宅。它是金門罕見的「疊樓帶軒亭」傳統建築：主體為兩層疊樓，二樓前側磚坪上設四柱捲棚軒亭作為休憩場所，外圍以煙炙磚女兒牆搭配青瓷花瓶欄杆。一樓入口榻受的交趾燒裝飾與聯對保存完好，內埕以紅磚鋪地，圍牆頂以瓦片排成瓦花，兼具防盜功能。民國101年（2012）起由金門縣文化局獎助整體修復，民國102年（2013）11月完成。官方說明表示，更詳細的歷史沿革尚待日後調查。","highlights":["二樓前側的四柱捲棚軒亭","青瓷花瓶欄杆與煙炙磚女兒牆","入口「小築佳趣」匾額與交趾燒裝飾"],"funFact":"圍牆頂的瓦片排成鏤空瓦花，看起來優雅，其實也有防盜功能。","photoSpot":"從院牆外仰拍二樓軒亭","visitMin":20,"openNote":"位於金沙鎮浦邊聚落，官方資料記載採預約制，開放時段為09:00至11:00、15:00至17:00。屬私人產權，未預約時請在外觀參觀，勿擅入、勿打擾住戶。開車或騎機車前往較方便。","dialogue":[{"who":"R","text":"Allan，快看！那棟古厝的二樓上面，怎麼長出一座小涼亭？"},{"who":"A","text":"那叫軒亭！這是何敬嚴宅，門匾寫著小築佳趣，是金門很少見的疊樓帶軒亭。"},{"who":"R","text":"在自己家二樓蓋一座涼亭，屋主一定很懂得享受生活。"},{"who":"A","text":"沒錯，民國10年代何敬嚴在呂宋經營橡膠園，寄錢回浦邊蓋了這棟房子。"},{"who":"R","text":"在亭子裡喝茶吹風，Allan，你要不要也在家裡蓋一座？"},{"who":"A","text":"我家頂樓只放得下曬衣架啦！你看軒亭旁的欄杆，是青瓷花瓶造型，很講究。"},{"who":"R","text":"還有圍牆上那些瓦片排成一朵一朵的花樣，也是裝飾嗎？"},{"who":"A","text":"那是瓦花，好看之外還能防盜，一兼二顧。最後抬頭找找門上的小築佳趣四個字吧！"}],"clues":["我的二樓前方蓋了一座四柱涼亭","我的主人在呂宋經營橡膠園，寄錢回鄉蓋我","浦邊聚落裡罕見的疊樓帶軒亭，門匾四個字"],"quiz":[{"q":"何敬嚴是在哪裡經營橡膠園？","options":["爪哇","安南","呂宋","馬來半島"],"answer":2,"explain":"何敬嚴於呂宋經營橡膠園，寄款返鄉建宅。"},{"q":"圍牆頂排成瓦花的瓦片，除了裝飾還有什麼功能？","options":["排水","防盜","通風","祭祀"],"answer":1,"explain":"牆頂以瓦片做瓦花，具有防盜功能。"}],"images":[]},{"id":"jinsha-zhangshiyanglou","name":"張氏洋樓","short":"沙美張氏洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49195,"lng":118.41211,"address":"金門縣金沙鎮沙美99號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000021","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-20/bdfdad01-eff5-44c6-bb64-58ae22cd2a56/01封面.jpg","year":1925,"yearText":"年代不詳","era":"unknown","themes":["僑鄉洋樓"],"yearUnknown":true,"summary":"洋蔥窗楣、麥穗脊墜的沙美小洋樓","intro":"張氏洋樓位於金沙鎮沙美聚落，創建年代不詳，官方表示詳細歷史待日後修復計畫深入調查。建築由正身二層五腳基洋樓、前方兩座櫸頭和牆規組成，屋頂仍是傳統雙坡瓦作，展現中西合璧的手法。正身二樓開窗，窗楣做成洋蔥造型；櫸頭大規壁的脊墜是兩支麥穗相交，上方還有葫蘆造型煙囪。牆規樓門開在中心偏右，是磚砌圓拱造型，兩側飾有蝙蝠泥塑。深井與鏡面牆之間有四柱三開間的圓拱門，上方女兒牆有花瓶欄杆。目前整體損壞嚴重，牆面剝落、植物攀附，木構造多處腐朽。","highlights":["二樓窗上的洋蔥造型窗楣","櫸頭脊墜的雙麥穗與葫蘆造型煙囪","牆規樓門兩側的蝙蝠泥塑"],"funFact":"這棟洋樓的身世至今成謎，官方說明連創建年代都還待日後調查。","photoSpot":"在牆規外拍圓拱樓門與蝙蝠泥塑","visitMin":10,"openNote":"位於金沙鎮沙美聚落，建築損壞嚴重，請勿靠近或進入。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，這棟張氏洋樓是一位神秘客，連官方都還不知道它是哪一年蓋的。"},{"who":"R","text":"神秘客？聽起來好刺激！那我們有什麼線索可以認出它？"},{"who":"A","text":"線索一，二樓窗上的窗楣做成洋蔥形狀。線索二，前面櫸頭的脊墜是兩支麥穗交叉。"},{"who":"R","text":"洋蔥加麥穗，聽起來好像一份早餐菜單，好想咬一口！"},{"who":"A","text":"再配一碗麵線就完美了。線索三，屋頂旁有葫蘆形的煙囪，牆規大門兩邊還有蝙蝠泥塑，象徵福氣。"},{"who":"R","text":"蝙蝠代表福，這個我學過！那它現在的狀況怎麼樣？"},{"who":"A","text":"損壞得很嚴重，牆面剝落、植物攀附。等以後修復調查，說不定就能解開它的身世之謎。"},{"who":"R","text":"那我先當小偵探，在外面把三個線索都找出來，看看誰先找齊！"}],"clues":["我的窗楣長得像洋蔥","我的脊墜是兩支交叉的麥穗","沙美聚落裡，年代不詳的二層五腳基洋樓"],"quiz":[{"q":"這棟洋樓二樓窗楣是什麼造型？","options":["火焰造型","洋蔥造型","書卷造型","半圓造型"],"answer":1,"explain":"正身二層開一面窗，窗楣為洋蔥造型。"},{"q":"櫸頭大規壁上方有什麼造型的煙囪？","options":["葫蘆","寶瓶","蓮花","燈籠"],"answer":0,"explain":"脊墜為兩麥穗相交，上方可見葫蘆造型煙囪。"}],"images":[]},{"id":"jinsha-heyongyanglou","name":"何永洋樓","short":"何永洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47891,"lng":118.38917,"address":"金門縣金沙鎮浦邊28號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000011","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/73b28fce-2f4b-4cfb-bf1c-3e526a22f195/何永洋樓_封面.jpg","year":1926,"yearText":"1926年（民國15年）","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"山頭塑國旗與鳳凰的菲律賓僑匯洋樓","intro":"何永洋樓位於金沙鎮浦邊聚落，創建人何敬永（1879–1930）人稱「何永」。何家自清咸豐、同治年間起陸續前往菲律賓謀生，清光緒16年（1890）何敬永也遠赴馬尼拉協助家業。他在民國9年（1920）返鄉，民國14年起自籌興建洋樓，民國15年（1926）竣工。建築為五腳基洋樓帶圍牆與後裙房，正面蔥頭型山頭塑有十八星旗、五色旗與鳳凰，二樓壽屏也雕著兩旗交叉。竣工時已設防空洞，外圍還有輪錢門、監視孔等防禦設施。戰地政務時期曾作為連級指揮所，民國98年（2009）後閒置至今。","highlights":["蔥頭型山頭上的十八星旗、五色旗與鳳凰泥塑","簷口線板上鰲魚造型的吐水口","前院戰地政務時期留下的洗面臺與標語殘跡"],"funFact":"民國27年何敬永的兒子病逝，他認為和風水有關，拆掉北向圍牆，才形成今天的圍牆配置。","photoSpot":"在洋樓正前方仰拍蔥頭型山頭","visitMin":15,"openNote":"位於金沙鎮浦邊聚落，目前閒置、外牆有剝落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往，或搭金門縣公車至沙美車站後轉乘。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的山頭好特別，圓圓尖尖的，好像一顆洋蔥！"},{"who":"A","text":"你說對了，這就叫蔥頭型山頭。屋主何敬永人稱何永，在菲律賓打拚多年，民國15年蓋好這棟樓。"},{"who":"R","text":"山頭中間那幾面旗子是什麼？我只認得現在的國旗耶。"},{"who":"A","text":"那是十八星旗和五色旗，都是民國初年用過的旗子，旁邊還有鳳凰和牡丹，華僑用它表達對國家的心意。"},{"who":"R","text":"哇，等於把愛國心直接貼在屋頂上！"},{"who":"A","text":"而且這房子很有危機意識，一蓋好就有防空洞，還有輪錢門和監視孔。當年盜匪多，有錢人家睡覺都要睜一隻眼。"},{"who":"R","text":"這麼氣派的洋樓，那現在是誰住在裡面呢？"},{"who":"A","text":"戰地政務時期這裡當過連級指揮所，後來家族陸續搬走，現在閒置中，我們在外面欣賞就好。"},{"who":"R","text":"好，那我來找找簷口下面，有沒有鰲魚造型的吐水口！"}],"clues":["我的主人在馬尼拉打拚，返鄉後蓋了我","我的山頭上塑著十八星旗與五色旗","浦邊聚落裡，山頭像顆洋蔥的五腳基洋樓"],"quiz":[{"q":"洋樓正立面的山頭是什麼造型？","options":["蔥頭型","馬背型","燕尾型","圓拱型"],"answer":0,"explain":"正立面為造型特殊的「蔥頭型」山頭。"},{"q":"戰地政務時期，何永洋樓曾被編為什麼？","options":["連級指揮所","衛生所","小學校舍","郵政代辦所"],"answer":0,"explain":"國軍進駐浦邊組成戰鬥村，洋樓被編為連級指揮所。"}],"images":[]},{"id":"jinsha-hesudianhesuhai","name":"何肅點、何肅海兄弟洋樓","short":"何肅點兄弟洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47927,"lng":118.38957,"address":"金門縣金沙鎮浦邊22號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000011","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/8dbf9bab-0f75-4f92-aeaa-b94030c99b3b/1.jpg","year":1926,"yearText":"1926年（民國15年）","era":"japan","themes":["僑鄉洋樓","市場商業"],"yearUnknown":false,"summary":"前店後樓、花了七仟大洋的兄弟洋樓","intro":"何肅點、何肅海兄弟洋樓位於金沙鎮浦邊聚落，民國15年（1926）由兩兄弟興建。兄弟倆在浦邊經營雜貨店，逐步累積資金，總共花了七仟大洋蓋成。興建時何肅海曾帶200銀元到大陸買木材，途中遭海盜洗劫並被軟禁五十多天，最後以500銀元贖回。建築前落是傳統店屋、後落為二層五腳基洋樓，柱頭和柱身以蠣殼、蚵殼裝飾，二樓採煙炙磚砌並搭配花瓶欄杆，正廳地坪還設有防禦窺孔。民國48年（1959）深井曾遭宣傳彈擊中。整體裝飾樸實，以材料與砌法展現在地民居風格。","highlights":["前落傳統店屋、後落五腳基洋樓的配置","柱頭、柱身以蠣殼、蚵殼做成的裝飾","二樓煙炙磚砌外廊與花瓶欄杆"],"funFact":"何肅海為了買建材被海盜擄走，帶去的200銀元沒了，還得花500銀元才贖回自己。","photoSpot":"拍二樓煙炙磚外廊與花瓶欄杆","visitMin":10,"openNote":"位於金沙鎮浦邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往，或搭金門縣公車至沙美車站後轉乘。","dialogue":[{"who":"A","text":"阿拉蕾，今天考你一題：蓋這棟樓總共花了多少錢？"},{"who":"R","text":"我猜一百萬！不對，那時候應該不是用新臺幣吧？"},{"who":"A","text":"沒錯，用的是大洋，總共七仟大洋。何肅點、何肅海兄弟在浦邊開雜貨店，一點一滴存下來，民國15年蓋好。"},{"who":"R","text":"存錢蓋房子，好勵志！過程應該很順利吧？"},{"who":"A","text":"才不呢！何肅海帶200銀元去大陸買木材，半路被海盜搶了，還被關了五十多天，最後花500銀元才贖回來。"},{"who":"R","text":"什麼！買木材還倒賠，這也太慘了吧！"},{"who":"A","text":"所以房子特別低調實在，柱頭用金門常見的蠣殼、蚵殼裝飾。看到蚵殼，我就想去吃一碗蚵仔麵線。"},{"who":"R","text":"你每次都繞回吃的！這裡現在可以進去嗎？"},{"who":"A","text":"這是私人住宅，我們在外面看就好。你去看看二樓外廊，是用什麼顏色的磚砌成的？"}],"clues":["我的主人為了買木材，被海盜軟禁五十多天","我前面是店屋，後面是兩層五腳基洋樓","浦邊一對開雜貨店的兄弟，花七仟大洋蓋了我"],"quiz":[{"q":"何肅海去大陸買木材時遭遇什麼事？","options":["被海盜洗劫軟禁","遇到颱風翻船","木材被官府沒收","商號突然倒閉"],"answer":0,"explain":"途中遭海盜洗劫，軟禁五十多天後以500銀元贖回。"},{"q":"這棟洋樓的柱頭用什麼材料裝飾？","options":["彩色磁磚","交趾陶","鑄鐵花飾","蠣殼與蚵殼"],"answer":3,"explain":"柱頭與柱身以蠣殼、蚵殼為材料裝飾。"}],"images":[]},{"id":"jincheng-xueyongnanxiongdi","name":"薛永南兄弟大樓","short":"薛永南兄弟大樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40267,"lng":118.32065,"address":"金門縣金城鎮珠山82號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000032","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/bfb677a5-c602-4fea-9e54-a67d287d04a4/01封面.jpg","year":1928,"yearText":"1928年（民國17年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"珠山第一棟洋樓，菲律賓碾米廠致富所建","intro":"薛永南兄弟大樓位於金城鎮珠山聚落龜山南麓，又稱「龜山頂大樓」。清光緒15年（1889）薛永南兄弟前往菲律賓經營碾米廠致富，1928年返鄉興建，是珠山第一棟洋樓，牆上勒石記載「薛永南兄弟建置」與石匠、木匠、土匠姓名及「民國十七年造」。建築除主棟二層五腳基洋樓外，還有前棟迴向作灶間，右後方有防禦用的「更樓」與作書房的「書齋」。主棟正立面為六柱五開間拱圈，通體磚砌並有多層線腳，二層與女兒牆都是花瓶欄杆。2002年由金門國家公園管理處完成整體修復。","highlights":["六柱五開間的磚砌拱圈正立面","二樓出入口左側記載匠師的建造勒石","右後方具防禦功能的兩層更樓"],"funFact":"勒石上把石匠、木匠、土匠的名字都刻上去，讓蓋房子的師傅也一起留名。","photoSpot":"在前方拍六柱五開間拱圈立面","visitMin":15,"openNote":"位於金城鎮珠山聚落，由金門國家公園管理處修復，目前作住宿使用，開放情形依經營者營業時間；請在外觀參觀，勿打擾住客。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，珠山這麼多洋樓，哪一棟是最早蓋的？"},{"who":"A","text":"就是這棟薛永南兄弟大樓，1928年完工，是珠山第一棟洋樓，大家也叫它龜山頂大樓。"},{"who":"R","text":"他們兄弟是在南洋做什麼生意，才能蓋得這麼氣派？"},{"who":"A","text":"1889年清光緒年間，他們到菲律賓開碾米廠，一粒一粒米累積成一棟大樓。"},{"who":"R","text":"所以這是米飯蓋起來的房子！我突然好想吃飯。"},{"who":"A","text":"想吃飯我奉陪。你看二樓門口旁邊的勒石，連石匠、木匠、土匠的名字都刻上去了。"},{"who":"R","text":"好暖心，蓋房子的師傅也能留名千古。"},{"who":"A","text":"右後方還有一座更樓，以前是防禦用的，旁邊的書齋則是讀書的地方。"},{"who":"A","text":"請你在屋外數數看，正面一共有幾根柱子撐起那一排拱圈！"}],"clues":["我身邊有防禦用的更樓和讀書用的書齋","我的勒石刻著石匠、木匠、土匠的名字和民國十七年","我是珠山第一棟洋樓，靠菲律賓碾米廠的收入興建"],"quiz":[{"q":"薛永南兄弟在菲律賓經營什麼生意？","options":["碾米廠","橡膠園","錫礦","船頭行"],"answer":0,"explain":"兄弟前往菲律賓經營碾米廠致富。"},{"q":"大樓右後方的「更樓」原本有什麼功能？","options":["存放米糧","防禦","祭祖","養雞"],"answer":1,"explain":"右後方更樓為防禦之用。"}],"images":[]},{"id":"jincheng-shimaotang","name":"世懋堂(黃氏三房宗祠)","short":"世懋堂","category":"歷史建築","level":"","town":"金城鎮","types":["祠堂"],"lat":24.41215,"lng":118.29544,"address":"金門縣金城鎮前水頭137號（原為134號，後改為137號）","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000027","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-10-28/fea89c21-e02c-469c-87de-1b1eb3f2b098/歷建120世懋堂(黃氏三房宗祠)_代表圖像.jpg","year":1929,"yearText":"1929年（民國18年）","era":"japan","themes":["宗祠家廟"],"yearUnknown":false,"summary":"水頭黃氏三房宗祠，照壁寫著「指日高陞」","intro":"世懋堂是金城鎮水頭聚落黃氏三房的宗祠，始建於民國18年（1929），位在水頭後界。黃氏宗族源自河南固始，輾轉遷到泉州、同安金柄、南安白石，再到浯洲金水（水頭）定居，以「紫雲衍派」為郡號，每年冬至祭祖。祠堂1969年因白蟻蛀蝕局部修繕，1984年翻修，部分經費來自旅居臺南安平的宗親，1989年奠安；2005年曾被翻覆的吊車撞毀，2008年修復完成。建築為一落二翼廊加牆規樓，前有前埕與照壁，正身為翹脊加八字規，正廳祖龕木雕精美並飾金漆，題材有人物故事與花鳥走獸。","highlights":["照壁上的「指日高陞」四個大字","門框聯對「源出潁川名第一，宗開金水序屬三」","正身翹脊加八字規，兩側各三壟筒瓦"],"funFact":"2005年一輛載運水泥方塊的吊車翻覆，撞毀了祠堂，前後修了3年才完工。","photoSpot":"前埕拍照壁「指日高陞」與宗祠正面","visitMin":10,"openNote":"位於金城鎮水頭聚落後界，宗族祠堂，平日多不開放，請在外觀參觀，勿擅入；冬至祭祖時請勿打擾。水頭聚落鄰近水頭碼頭，可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，照壁上寫「指日高陞」，這是在祝福大家升官發財嗎？"},{"who":"A","text":"正是！這裡是水頭黃氏三房的宗祠世懋堂，1929年蓋的，照壁天天對著祠堂說吉祥話。"},{"who":"R","text":"三房？所以水頭還有大房、二房囉？"},{"who":"A","text":"對，門框聯對就寫「宗開金水序屬三」，金水就是水頭，意思是在水頭排行第三房。"},{"who":"R","text":"原來對聯也能當身分證！那這座祠堂一路都很平安嗎？"},{"who":"A","text":"考驗可不少。1969年被白蟻蛀，1984年翻修時，還有旅居臺南安平的宗親捐款幫忙。"},{"who":"R","text":"白蟻真的是金門古厝的頭號敵人耶！"},{"who":"A","text":"最誇張的是2005年，一輛載水泥方塊的吊車翻覆，直接撞上祠堂，修了3年才修好，比我打翻炒泡麵還慘烈。"},{"who":"A","text":"現在請你站在前埕，找找門框上「序屬三」三個字，再回頭和照壁合拍一張！"}],"clues":["我的照壁寫著祝福升官的四個字","門聯說我在金水排行第三","2005年我被翻覆的吊車撞毀，3年後修復"],"quiz":[{"q":"世懋堂照壁上寫的是哪四個字？","options":["紫雲衍派","指日高陞","祖德宗庥","福壽康寧"],"answer":1,"explain":"照壁上書「指日高陞」，祈願子孫高升。"},{"q":"世懋堂在2005年為何受損？","options":["白蟻蛀蝕","颱風吹襲","吊車翻覆撞擊","地震震損"],"answer":2,"explain":"載運水泥方塊的吊車翻覆撞毀祠堂，2008年修復。"}],"images":[]},{"id":"jincheng-caikaishengzhaidi","name":"蔡開盛宅第","short":"蔡開盛宅第","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41092,"lng":118.29807,"address":"金門縣金城鎮前水頭63號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000038","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-05-29/a07e611f-65de-4fa0-ae3e-aeaa9626ebad/蔡開盛宅.jpg","year":1929,"yearText":"約1929年（民國18年）前後","era":"japan","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"花了二萬白銀，正廳擂金畫金門民宅少見","intro":"蔡開盛宅第位於金城鎮水頭聚落，由蔡開國、蔡清竹叔姪在印尼巴東經營「光大行」土產生意致富後，匯錢給蔡開盛（蔡清竹之父）興建。格局為二落大厝加右護龍疊樓，當時造價二萬白銀，其中一萬用於建材、一萬用於室內裝修，因此裝飾極為華麗。正廳的擂金畫是金門民宅少見的作品，彩繪推測完成於1929至1930年，出自受聘來金的福建師傅。右護龍後段為二層五腳基洋樓，有洋蔥型窗楣與雙龍戲珠泥塑。1958年八二三砲戰時深井受損，後以水泥重砌。門額為蔡氏堂號「濟陽衍派」。","highlights":["大規壁上雙螭龍圍繞的人物交趾脊墜","右護龍二層洋樓的洋蔥型窗楣與雙龍戲珠泥塑","門額堂號「濟陽衍派」與人物石雕門印"],"funFact":"二萬白銀的造價，一半花在建材，另一半全花在室內裝修上。","photoSpot":"在前埕拍二落大厝與右側洋樓疊樓","visitMin":15,"openNote":"位於金城鎮水頭聚落，目前作住宿使用，官方資料記載參觀請先電洽管理人詢問；未經同意請在外觀參觀，勿擅入、勿打擾住客。可搭金門縣公車到水頭。","dialogue":[{"who":"A","text":"阿拉蕾，如果有二萬白銀蓋房子，你會怎麼分配？"},{"who":"R","text":"一萬蓋房子，一萬全部拿去買零食！"},{"who":"A","text":"蔡家比你有品味一點，一萬買建材，另一萬全部花在室內裝修，所以這裡華麗得不得了。"},{"who":"R","text":"這麼多錢是從哪裡來的？又是南洋寄回來的嗎？"},{"who":"A","text":"對，蔡開國、蔡清竹叔姪在印尼巴東開光大行做土產生意，賺了錢匯給蔡開盛蓋房子。"},{"who":"R","text":"叔叔和姪子一起打拚，再把錢寄回家給爸爸，好溫馨。"},{"who":"A","text":"正廳的擂金畫是金門民宅少見的珍品，大約1929年由福建師傅畫的，可惜現在有剝落問題。"},{"who":"R","text":"那右邊那棟兩層樓的洋房也是同一家嗎？"},{"who":"A","text":"是右護龍的洋樓。請你在屋外找找它二樓背面的窗楣，看看像不像一顆洋蔥！"}],"clues":["我的造價二萬白銀，一半花在室內裝修","我正廳的擂金畫是金門民宅少見的作品","我在水頭，由印尼巴東光大行的叔姪出資興建"],"quiz":[{"q":"蔡開盛宅第的建造經費來自哪家商行？","options":["協德船頭行","光大行","董允耀公司","碾米廠"],"answer":1,"explain":"蔡開國、蔡清竹叔姪在印尼巴東經營光大行。"},{"q":"蔡開盛宅第正廳哪一種裝飾是金門民宅少見的？","options":["馬賽克磁磚","西洋油畫","擂金畫","石雕屏風"],"answer":2,"explain":"正廳擂金畫為金門民宅少見。"}],"images":[]},{"id":"jincheng-hongheshenghonghe","name":"洪合剩、洪合達宅","short":"洪合剩洪合達宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.4333,"lng":118.31844,"address":"金門縣金城鎮珠浦北路15之2號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000060","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/35587723-44cf-44ae-ac1d-09dbeb393a80/1 封面.jpg","year":1930,"yearText":"1930年（民國19年）完竣","era":"japan","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"兄弟為感念三嬸，在大厝旁加蓋疊樓相贈","intro":"洪合剩、洪合達宅位於金城鎮後浦市區珠浦北路。1920年代洪合淵、洪合剩、洪合達兄弟赴印尼經營土產生意，返鄉興建兩幢連棟二落大厝，1930年完竣，本宅即右側一幢。兄弟成年後皆下南洋，妻小靠三嬸照料，兄弟為感念她，特在大厝右側增建一座疊樓相贈。1937年日軍占領金門期間，建築被日軍駐紮占用；二次大戰時在印尼的洪氏兄弟因戰事離散、下落不明。1949年後國軍進駐，後租作救國團金門總部，直到1992年底才歸還。榻受以鵝黃色彩磁拼貼花鳥與牡丹蝴蝶，清麗和諧。","highlights":["榻受四塊一組、鵝黃色系的花鳥與牡丹蝴蝶彩磁","右側獻給三嬸的疊樓與綠釉花瓶欄杆","前方水泥門樓頂部的救國團標誌"],"funFact":"兩座大厝之間的巷道前設隘門、後設石柵，是兼具防禦功能的連棟建築群。","photoSpot":"在前埕拍榻受彩磁與右側疊樓","visitMin":15,"openNote":"位於金城鎮後浦市區珠浦北路，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築年久失修，請保持距離。金城車站附近，可步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，你最感謝誰照顧你？這棟大厝旁邊的疊樓，就是一份送給長輩的謝禮。"},{"who":"R","text":"用整棟樓當謝禮？誰這麼大手筆啊？"},{"who":"A","text":"洪合剩、洪合達兄弟。他們年輕就到印尼做土產生意，家裡的妻小都靠三嬸照顧。"},{"who":"R","text":"三嬸好偉大！所以兄弟們就在大厝旁邊加蓋一棟送她。"},{"who":"A","text":"對，1930年和隔壁的洪合淵宅一起完工。可惜二次大戰時，在印尼的兄弟因戰事離散，至今下落不明。"},{"who":"R","text":"好令人難過，家鄉的人一直等不到他們回來。"},{"who":"A","text":"是啊。戰後這裡還當過救國團金門總部，門樓上的標誌到現在都還看得到。"},{"who":"R","text":"那我要把感謝說出口，等一下請你吃麵線，不用蓋樓吧？"},{"who":"A","text":"一碗就很夠了。到現場請你在屋外找找榻受上那組黃色的牡丹蝴蝶彩磁！"}],"clues":["我右側的疊樓，是兄弟們送給照顧家人的三嬸的禮物","我曾被日軍占用，戰後又租作救國團金門總部","我在後浦珠浦北路，和兄長的大厝連棟，1930年完竣"],"quiz":[{"q":"洪氏兄弟增建右側疊樓是為了感謝誰？","options":["母親","祖父","三嬸","老師"],"answer":2,"explain":"兄弟感念三嬸照料家庭，增建疊樓相贈。"},{"q":"這座大厝戰後曾租用作為什麼單位的總部？","options":["金門日報","救國團","郵電局","紅十字會"],"answer":1,"explain":"租用為救國團金門總部，1992年底歸還。"}],"images":[]},{"id":"jincheng-hongheyuanzhai","name":"洪合淵宅","short":"洪合淵宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43326,"lng":118.3185,"address":"金門縣金城鎮珠浦北路15之1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000059","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-21/e0fdf47e-966e-49cf-9107-65e7cb471793/1封面.jpg","year":1930,"yearText":"1930年（民國19年）完竣","era":"japan","themes":["閩南古厝"],"yearUnknown":false,"summary":"大廳彩繪留下「民國十九年」落款的二落大厝","intro":"洪合淵宅位於金城鎮後浦市區珠浦北路，與右側的洪合剩、洪合達宅為同期興建的連棟二落大厝。1921年洪合淵三兄弟赴印尼經營土產生意，返鄉建屋，1930年完竣，大廳彩繪至今仍留有「民國十九年」落款。榻受裙堵採泉州白石，櫃檯腳、柱礎與半牌雕刻花卉祥獸，窗楣為書法泥塑，門額刻洪氏堂號「燉煌衍派」。日軍占領金門期間曾被日軍憲兵駐紮；戰後國軍進駐，後租作救國團金門總部，1992年底歸還。左大規壁原有藍漆國軍標語，如今已風化難辨。","highlights":["泉州白石櫃檯腳與半牌上的花卉祥獸雕刻","門額石匾「燉煌衍派」與書法泥塑窗楣","左大規壁風化中的藍漆國軍標語痕跡"],"funFact":"大廳壽屏的擂金畫與書法旁留有民國19年落款，正好替房子「報上年紀」。","photoSpot":"從巷口拍兩座連棟大厝與隘門","visitMin":15,"openNote":"位於金城鎮後浦市區珠浦北路，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。金城車站附近，可步行前往。","dialogue":[{"who":"R","text":"Allan，這棟大厝跟隔壁那棟長得好像，是雙胞胎嗎？"},{"who":"A","text":"可以這麼說。洪合淵和弟弟們一起從印尼匯錢回來，兩幢連棟大厝在1930年同時完工。"},{"who":"R","text":"那怎麼知道是1930年？房子又不會自己講。"},{"who":"A","text":"它會喔！大廳彩繪上留著「民國十九年」的落款，等於在牆上寫了出生證明。"},{"who":"R","text":"好聰明，比你每次忘記自己吃了幾個燒餅還清楚。"},{"who":"A","text":"咳，這不重要。日軍占領金門時，這裡被日軍憲兵駐紮，戰後又成了救國團金門總部。"},{"who":"R","text":"一棟房子住過這麼多不同的人，牆壁應該有很多話想說。"},{"who":"A","text":"左邊大牆上原本還有藍漆國軍標語，現在已經風化看不清楚了。"},{"who":"A","text":"請你站在屋外仔細看門框上的石匾，找出洪家的堂號四個字！"}],"clues":["我的大廳彩繪留有「民國十九年」的落款","我左邊大牆上的藍漆國軍標語已經風化難辨","我在後浦珠浦北路，和弟弟們的大厝連棟而建"],"quiz":[{"q":"洪合淵宅門額石匾上刻的洪氏堂號是？","options":["太原衍派","紫雲衍派","濟陽衍派","燉煌衍派"],"answer":3,"explain":"門額石作牌匾刻「燉煌衍派」，為洪氏堂號。"},{"q":"從哪裡可以知道洪合淵宅在1930年完工？","options":["大廳彩繪落款","地契文件","族譜記載","報紙新聞"],"answer":0,"explain":"大廳彩繪仍留有「民國十九年」之落款。"}],"images":[]},{"id":"jincheng-huangnaifufanzai","name":"黃乃甫番仔厝","short":"黃乃甫番仔厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40905,"lng":118.30059,"address":"金門縣金城鎮前水頭6號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000045","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/b024e9a5-a9e4-4549-b87e-44987bf78485/黃乃甫番仔厝_封面.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":true,"summary":"印尼雜貨商返鄉蓋的華麗番仔厝","intro":"黃乃甫番仔厝位於金城鎮水頭聚落（前水頭），由黃乃甫在印尼經營雜貨店致富後返鄉興建，興建年代官方資料尚待調查。建築分前後兩棟，前棟為「大九架番仔厝」，後棟為一廳兩房，中間以深井相連。前棟立面裝飾華麗：近似三葉形的山頭中央以藍框藍字寫著「紫雲衍派」堂號，上方有飛鷹與雙獅戲球泥塑，左右是飛馬；四根柱頭外側為天使、內側為蓮花，頂上立著寶燈，女兒牆為花瓶欄杆。榻受橫樑、對看堵與聯對大量使用彩磁，橫樑左右端還有兔子造型泥塑。","highlights":["山頭藍框藍字的「紫雲衍派」與飛鷹、飛馬泥塑","柱頭外側的天使、內側的蓮花與四座寶燈","榻受橫樑兩端的兔子造型泥塑"],"funFact":"側面第三扇窗的窗楣是洋蔥形，和前兩扇弧形窗楣不同，窗下還有飛鳥泥塑。","photoSpot":"在前埕外拍三葉形山頭與天使柱頭","visitMin":15,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。鄰近水頭碼頭，可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"這棟番仔厝的山頭像不像一座動物園？飛鷹、雙獅、飛馬，連兔子都有！"},{"who":"R","text":"兔子？在哪裡在哪裡？我要第一個找到！"},{"who":"A","text":"別急，兔子躲在榻受橫樑的左右兩端。這是黃乃甫在印尼開雜貨店，賺了錢回來蓋的。"},{"who":"R","text":"開雜貨店就能蓋這麼漂亮的房子，生意一定很好！"},{"who":"A","text":"是啊，它是大九架番仔厝，前棟有西式山頭，後棟一廳兩房，中間用深井連起來。"},{"who":"R","text":"柱子上有小天使，旁邊又有蓮花，好混搭！"},{"who":"A","text":"這就是僑鄉建築的魅力，南洋、西洋和閩南一起來，像一碗料很多的廣東粥。"},{"who":"R","text":"你每次比喻都跟吃有關，不過好像真的很貼切。"},{"who":"A","text":"這裡有人居住，請在外面看就好。請你數一數，山頭和柱頭上一共立了幾座寶燈！"}],"clues":["我的主人在印尼經營雜貨店致富後返鄉建屋","我的山頭有飛鷹、雙獅和飛馬，橫樑兩端還有兔子","我是水頭聚落的大九架番仔厝，前後兩棟以深井相連"],"quiz":[{"q":"黃乃甫在印尼經營什麼生意？","options":["船頭行","咖啡原料","承包工程","雜貨店"],"answer":3,"explain":"黃乃甫至印尼經營雜貨店生意，致富返鄉興建此宅。"},{"q":"榻受橫樑兩端有什麼動物造型泥塑？","options":["猴子","兔子","鯉魚","蝙蝠"],"answer":1,"explain":"榻受橫樑左右端有兔子造型泥塑。"}],"images":[]},{"id":"jincheng-huangtianluzhai","name":"黃天露宅","short":"黃天露宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40943,"lng":118.30102,"address":"金門縣金城鎮前水頭4、5號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000026","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-29/8efd4f14-0f6e-4e4a-a15e-a23be7566d88/01封面.jpg","year":1930,"yearText":"1930年（民國19年）起建，歷時兩年多","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"挑擔叫賣到印尼打拚的落番故事","intro":"黃天露宅位於金城鎮水頭聚落，據族譜，屋主本名應為「黃天路」。他早年喪妻，獨自帶三個兒子挑擔、搖鼓沿街叫賣雜貨，約1905年隨族人遠赴印尼，先在三馬林達做苦力，後經營雜貨買賣；次子黃祝恭從水電修繕做到承包建路工程，一家人在麻里巴板安居。1930年黃天路與族親黃文東相約返鄉建屋，由長子主持，聘同安匠師歷時兩年多完成，格局為二落大厝加右護龍，護龍後段起疊樓，立面寫有「民國十九年」落款。2007年由金門國家公園管理處修復完成，之後作為民宿使用。","highlights":["鏡面牆到拱仔頭滿布的馬約利卡彩磁","疊樓紅磚拱圈外廊與「民國十九年」落款","護龍屋頂三拱波浪形的規帶"],"funFact":"屋主本名據族譜應是「黃天路」，他曾挑著擔子、搖鼓沿街叫賣日用雜貨。","photoSpot":"拍疊樓紅磚拱圈與波浪形山頭","visitMin":15,"openNote":"位於金城鎮水頭聚落。由金門國家公園管理處修復後作為民宿使用，非住宿者請在外觀參觀，勿擅入、勿打擾住客與住戶。鄰近水頭碼頭，可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這面牆上的花磚顏色好鮮豔，是新貼的嗎？"},{"who":"A","text":"這是馬約利卡彩磁，色彩經久不衰。不過比花磚更精彩的，是屋主黃天路的故事。"},{"who":"R","text":"咦，這裡的名字不是叫黃天露嗎？"},{"who":"A","text":"族譜記載本名應是黃天路。他年輕時喪妻，自己帶三個兒子挑擔、搖鼓，沿街叫賣雜貨。"},{"who":"R","text":"一個人帶三個孩子好辛苦喔，後來呢？"},{"who":"A","text":"約1905年他帶著孩子到印尼打拚，從苦力做到雜貨生意，二兒子還承包過建路工程。"},{"who":"R","text":"真的是一路打拚上來！那這棟房子什麼時候蓋的？"},{"who":"A","text":"1930年他和族親黃文東相約回鄉建屋，長子主持，請同安匠師蓋了兩年多，疊樓上還寫著民國十九年。"},{"who":"A","text":"那就像房子的出生證明。請你在外面找找疊樓的紅磚拱圈外廊，數數一共有幾個拱！"}],"clues":["我的主人據族譜本名叫黃天路，年輕時挑擔叫賣雜貨","他和族親黃文東相約在1930年回鄉建屋","我是水頭聚落的二落大厝，護龍疊樓寫著民國十九年"],"quiz":[{"q":"依族譜記載，黃天露的本名應是？","options":["黃天祿","黃天助","黃天路","黃天佑"],"answer":2,"explain":"據金水黃氏族譜，黃天露本名應為黃天路。"},{"q":"疊樓立面上的落款年份是？","options":["民國十九年","民國十年","民國二十三年","清光緒三十一年"],"answer":0,"explain":"疊樓波浪形山頭中央書寫民國十九年落款。"}],"images":[{"file":"金門黃天露宅可愛的窗飾.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/%E9%87%91%E9%96%80%E9%BB%83%E5%A4%A9%E9%9C%B2%E5%AE%85%E5%8F%AF%E6%84%9B%E7%9A%84%E7%AA%97%E9%A3%BE.jpg/960px-%E9%87%91%E9%96%80%E9%BB%83%E5%A4%A9%E9%9C%B2%E5%AE%85%E5%8F%AF%E6%84%9B%E7%9A%84%E7%AA%97%E9%A3%BE.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E9%BB%83%E5%A4%A9%E9%9C%B2%E5%AE%85%E5%8F%AF%E6%84%9B%E7%9A%84%E7%AA%97%E9%A3%BE.jpg","artist":"Deepblue5042","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-huangtianluzhai-0.webp","small":"img/jincheng-huangtianluzhai-0-s.webp"}]},{"id":"jincheng-huangtingcansanluo","name":"黃廷參三落大厝","short":"黃廷參三落大厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41069,"lng":118.29713,"address":"金門縣金城鎮前水頭82號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000039","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/71c207cb-65c2-4834-8a59-1d83cf1f3f08/01封面.jpg","year":1930,"yearText":"約1930年（民國19年）起建，歷時4年","era":"japan","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"水頭目前唯一的三落大厝","intro":"黃廷參三落大厝位於金城鎮水頭聚落，鄰近李氏家廟。黃廷參是水頭黃氏長房子孫，晚清赴印尼麻里巴板經營船頭行致富，五十多歲返鄉定居。他在1925年購地，約1930年起建，耗資1萬3000銀元、歷時4年完成，是水頭目前唯一的三落大厝。前兩落為閩南傳統式，第三落略帶南洋風格，但第三落大廳與右房已坍塌。大門上方有「江夏流芳」堂號，兩旁是三國演義主題彩繪，脊墜交趾陶人物以玻璃罩保護。現前落作為商店開放，並展示當年購地的契書。","highlights":["大門上方「江夏流芳」堂號與三國演義彩繪","以玻璃罩保護、色彩艷麗的交趾陶脊墜","瓜筒上獅頭啣慶牌的精細木雕"],"funFact":"這座大厝耗資1萬3000銀元、蓋了4年，前落還展示當年買地的賣契與驗稅契證。","photoSpot":"在前埕拍翹脊與玻璃罩裡的交趾陶","visitMin":20,"openNote":"位於金城鎮水頭聚落。官方資料記載前落作為商店開放，每日11:00至21:00；後落為私人住宅，請勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，大部分古厝是一落、二落，這棟怎麼有三落？"},{"who":"A","text":"好眼力！這是水頭目前唯一的三落大厝，蓋了4年，花了1萬3000銀元。"},{"who":"R","text":"1萬3000銀元！黃廷參是做什麼的？"},{"who":"A","text":"他晚清到印尼麻里巴板經營船頭行，就是和船運有關的生意，五十多歲才回鄉定居。"},{"who":"R","text":"那這三落的樣子都長得一模一樣嗎？"},{"who":"A","text":"前兩落是閩南傳統式，第三落帶點南洋味，不過第三落的大廳已經坍塌了。"},{"who":"R","text":"好可惜。那門口有什麼值得看的？"},{"who":"A","text":"大門上方有「江夏流芳」堂號，兩邊是三國演義彩繪，脊墜交趾陶還戴著玻璃罩，像戴了安全帽。"},{"who":"A","text":"前落是商店，可以看當年的買地契書。請你找找看，三國彩繪裡認得出哪一位英雄？"}],"clues":["我耗資1萬3000銀元、蓋了4年才完成","我的主人在印尼麻里巴板經營船頭行","我是水頭聚落目前唯一有三落的大厝"],"quiz":[{"q":"黃廷參在印尼經營什麼生意？","options":["雜貨店","船頭行","橡膠園","咖啡原料"],"answer":1,"explain":"黃廷參晚清時赴印尼麻里巴板經營船頭行致富。"},{"q":"大門兩旁的彩繪是什麼主題？","options":["西遊記","封神榜","二十四孝","三國演義"],"answer":3,"explain":"大門兩旁以三國演義為題材，繪有兩幅彩繪。"}],"images":[]},{"id":"jincheng-huangchaobinzhai","name":"黃朝賓宅（前水頭116號）","short":"黃朝賓宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41143,"lng":118.29575,"address":"金門縣金城鎮前水頭116號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000074","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-09/de13320c-6b6e-4dbd-928f-2837d647cc66/01封面.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["閩南古厝"],"yearUnknown":true,"summary":"彩磁貼滿正面、由宗親代管多年的大厝","intro":"黃朝賓宅位於金城鎮水頭聚落，是黃朝賓家族遠渡印尼發展、致富後返鄉興建的二落大厝，官方資料未載確切興建年代。日軍占領金門期間，家族為躲避戰火遷往南洋，此後不再返鄉定居。房產先後由宗親與姻親代管、代繳稅捐，期間親友陸續入住，也曾租給酒廠當倉庫，代管人還用租金修繕前落。2014年產權出售，現在閒置。建築正面的榻受牆、對看堵、拱仔頭與水車堵貼滿色彩鮮明的彩磁，門額有「紫雲衍派」堂號，大門、窗楣與對看堵上方都有聯對，櫸頭上方女兒牆採花瓶欄杆形式。","highlights":["正面貼滿色彩鮮明的彩磁","大門、窗楣與對看堵上方的訓誡聯對","櫸頭上方花瓶欄杆形式的女兒牆"],"funFact":"家族遷居南洋後，宗親代管房子數十年，還曾租給酒廠當倉庫，再用租金修繕前落。","photoSpot":"在前埕外拍滿牆彩磁立面","visitMin":10,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；目前閒置未開放。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，這棟大厝的正面像不像一面彩色拼貼牆？"},{"who":"R","text":"超像！紅的、藍的、綠的花磚，我眼睛都忙不過來了。"},{"who":"A","text":"這些是彩磁，從榻受牆、對看堵一路貼到水車堵。黃朝賓家族在印尼致富後回鄉蓋了它。"},{"who":"R","text":"那黃家的後人現在還住在這裡嗎？"},{"who":"A","text":"日軍占領金門時，家族為了躲避戰火遷往南洋，之後就沒有回來定居了。"},{"who":"R","text":"那主人不在家，房子由誰照顧呢？"},{"who":"A","text":"由宗親和姻親先後代管，還幫忙繳稅，甚至租給酒廠當倉庫，再用租金修繕前落。"},{"who":"R","text":"好有人情味！親戚幫忙顧房子顧了這麼久。"},{"who":"A","text":"可惜2014年產權已經出售，現在房子閒置，只能從外面欣賞那面彩磁牆。"},{"who":"A","text":"這是金門僑鄉很常見的故事。請在門外數數看，正面的門窗和牆上一共有幾副聯對！"}],"clues":["我的家族在日軍占領時期遷往南洋，房子由親戚代管","我曾被租給酒廠當倉庫，租金拿來修繕前落","我是水頭聚落的二落大厝，正面貼滿鮮豔彩磁"],"quiz":[{"q":"黃朝賓家族為何遷往南洋、不再返鄉定居？","options":["日軍占領時躲避戰火","八二三砲戰時疏散","清末海盜侵擾","經商失敗外出還債"],"answer":0,"explain":"日軍占領金門期間，家族為躲避戰火逃往南洋。"},{"q":"代管期間這棟大厝曾租給誰當倉庫？","options":["郵局","農會","酒廠","學校"],"answer":2,"explain":"代管期間曾租賃予酒廠當倉庫，租金用來修繕前落。"}],"images":[]},{"id":"jincheng-huangshuiyingzhai","name":"黃水應宅","short":"黃水應宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.412896,"lng":118.29716,"address":"金門縣金城鎮前水頭177號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000044","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-07-19/027f179c-cdb1-41f9-b906-0d6d27a78a2c/01.封面.jpg","year":1930,"yearText":"1931年（民國20年）以前改建","era":"japan","themes":["閩南古厝"],"yearUnknown":false,"summary":"前水頭唯一的三蓋廊古厝","intro":"黃水應宅位於金城鎮水頭聚落，原為洪氏所有的一落四櫸頭，後由黃水應之父黃光明收購，在1931年以前改建為形式獨特的「三蓋廊」建築，成為前水頭唯一的三蓋廊古厝。改建資金來源有兩種說法：一說黃水應在廈門經營「合利客棧」致富，另一說是他遠渡南洋致富後僑匯回鄉。建築屋脊為翹脊，與前落兩側房及櫸頭上方的磚砌女兒牆構成典雅的天際線；正立面榻受牆、拱仔頭、水車堵以彩繪裝飾，對看堵為彩繪泥塑，門額有「紫雲衍派」堂號。詳細沿革官方仍待調查。","highlights":["前水頭唯一的三蓋廊形式","翹脊與磚砌女兒牆構成的天際線","背立面花崗石人字砌的牆基"],"funFact":"改建資金有兩種說法：一說在廈門開「合利客棧」致富，一說是落番南洋賺來的。","photoSpot":"退到巷口拍翹脊與女兒牆天際線","visitMin":10,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這棟古厝屋頂邊邊有一圈矮牆，跟旁邊的房子不太一樣耶。"},{"who":"A","text":"你發現重點了！這是三蓋廊的特色，黃水應宅是前水頭唯一的三蓋廊古厝。"},{"who":"R","text":"三蓋廊？聽起來像有三層蓋子的便當。"},{"who":"A","text":"哈，就是前落兩側房和櫸頭上方砌了磚女兒牆，天際線很優雅。它原本是洪家的一落四櫸頭喔。"},{"who":"R","text":"那到底是誰把它改建成三蓋廊的？"},{"who":"A","text":"黃水應的父親黃光明買下改建。資金有兩種說法，一說在廈門開合利客棧，一說到南洋打拚。"},{"who":"R","text":"一棟房子兩種身世，好像推理小說！Allan你猜是哪一個？"},{"who":"A","text":"官方兩說並陳，我們也不亂下結論。請在巷口退幾步，看看翹脊和女兒牆連成的天際線像什麼形狀！"}],"clues":["我原本是洪家的一落四櫸頭，後來被收購改建","改建資金一說來自廈門的合利客棧","我是前水頭唯一的三蓋廊古厝"],"quiz":[{"q":"黃水應宅屬於哪一種特殊形式？","options":["三落大厝","三蓋廊","大九架番仔厝","六路大厝"],"answer":1,"explain":"黃水應宅是前水頭唯一的三蓋廊形式古厝。"},{"q":"黃水應宅改建前原屬哪一姓？","options":["李氏","陳氏","王氏","洪氏"],"answer":3,"explain":"原建築為一落四櫸頭，由洪氏所有，後經黃光明收購。"}],"images":[]},{"id":"jinning-lisenpengyanglou","name":"李森掽洋樓","short":"李森掽洋樓","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.48062,"lng":118.3109,"address":"金門縣金寧鄉北山171號","announced":"2015-02-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150226000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-17/dea1a3b2-74f5-4d35-b1ed-ec21517b2f97/李森掽洋樓封面.jpg","year":1930,"yearText":"約1931年以前（民國20年前後）","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"妻子在地監工完成的菲律賓僑匯洋樓","intro":"李森掽洋樓位於金寧鄉古寧村北山聚落。李森掽民國初年到菲律賓經商致富，因事業繁忙無法返鄉，便匯款回來，由妻子李許瑞在地監工，約於1931年以前完成，建材主要來自大陸，混凝土部分來自南洋，花費近一千五百元正銀。1937年日軍攻占金門時，家族仍住在洋樓內。1949年古寧頭戰役的激烈巷戰在建物留下彈孔，一家人避居後浦，洋樓成為國軍指揮所，加建屋頂房舍與哨亭；1975年曾作為古寧村公所，之後也開過雜貨店。2009年交由金門國家公園管理處修復後招標再利用。建築為五腳基洋樓併右護龍，山牆做成水形彎脊，室內鋪六角磚。","highlights":["洋樓山牆的水形彎脊造型","古寧頭戰役留下的彈孔遺痕","一、二樓半廳紅牆面與六角磚地坪"],"funFact":"這棟洋樓蓋的時候男主人人在菲律賓，從頭到尾是由妻子李許瑞在金門監工完成。","photoSpot":"在洋樓斜前方拍水形彎脊山牆","visitMin":15,"openNote":"位於金寧鄉古寧村北山聚落，由金門國家公園管理處管理，修復後招標再利用，部分古厝修復後作為民宿使用；非住宿旅客請在外觀參觀，勿擅入、勿打擾住宿旅客。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"A","text":"阿拉蕾，北山這棟洋樓有一位很厲害的女主角，她叫李許瑞。"},{"who":"R","text":"女主角？她是這棟洋樓的設計師嗎？"},{"who":"A","text":"她是工地主任。丈夫李森掽在菲律賓忙生意，沒辦法回來，就匯錢回家，由她在地監工蓋好。"},{"who":"R","text":"太帥了！丈夫負責賺錢，太太負責驗收，分工超明確。"},{"who":"A","text":"1949年古寧頭戰役時，這裡也經歷巷戰，留下彈孔，一家人只好避居後浦，洋樓變成國軍指揮所。"},{"who":"R","text":"這棟洋樓後來還做過什麼工作呢？"},{"who":"A","text":"1975年當過古寧村公所，後來還借給親戚開雜貨店，換工作的次數比我換眼鏡還多。"},{"who":"R","text":"那這棟洋樓最好認的特徵是什麼？"},{"who":"A","text":"看山牆，做成像流水一樣的彎彎曲線，叫水形彎脊。請你從側面拍下那道波浪形的山牆！"}],"clues":["我蓋好的時候，男主人人在菲律賓","我當過國軍指揮所，1975年還做過村公所","我在古寧頭北山，由女主人李許瑞監工完成"],"quiz":[{"q":"李森掽洋樓興建時是由誰在金門監工？","options":["李森掽本人","惠安匠師","妻子李許瑞","國軍工兵"],"answer":2,"explain":"李森掽在菲律賓事業繁忙，由妻子李許瑞在地監工建造。"},{"q":"1975年李森掽洋樓曾作為什麼用途？","options":["國民學校","古寧村公所","郵局","醫務所"],"answer":1,"explain":"民國64年洋樓曾當作古寧村公所使用。"}],"images":[]},{"id":"jinning-yangjinyuyangdu","name":"楊金魚、楊篤選宅第","short":"楊金魚宅第","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.45636,"lng":118.30721,"address":"金門縣金寧鄉湖下86、87號","announced":"2007-01-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20070119000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-08/7841559c-66cf-4b27-a29e-aaeabe6b17a6/01-封面.jpg","year":1930,"yearText":"年代不詳（1937年以前，民國初年）","era":"unknown","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":true,"summary":"燈樑掛著「金魚」的兄弟大厝與小疊樓","intro":"楊金魚、楊篤選宅第位於金寧鄉湖浦村湖下聚落，由兩座二落大厝加左護龍疊樓組成。楊金魚、楊篤選兄弟早年隨親族到星馬發展，致富後返鄉興建，哥哥住在左側增建疊樓護龍的一棟，另一棟由弟弟居住。據說動工前，石匠們在附近租屋將近兩年，才把所需石材打造完成。哥哥那棟的大廳燈樑上，還懸掛著和他名字相同的吉祥物「金魚」。抗戰時期日軍侵華，楊金魚一家遷往星馬，從此沒有再回到家鄉。1949年國軍駐守金門，宅第因規模宏大被選為旅部辦公室。左護龍疊樓一樓為拱圈五腳基，二樓露臺與女兒牆的花瓶欄杆花紋交錯排列，十分特殊。","highlights":["大廳燈樑上懸掛的吉祥物「金魚」","疊樓花紋不同、交錯排列的花瓶欄杆","正立面交趾陶、木雕插角與彩繪"],"funFact":"為了準備石材，石匠在附近租屋將近兩年；當時一個小工的工資是一塊半。","photoSpot":"在巷口拍疊樓的拱圈與花瓶欄杆","visitMin":15,"openNote":"位於金寧鄉湖浦村湖下聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，湖下這兩棟兄弟大厝裡，藏著一條不會游泳的金魚，你猜在哪裡？"},{"who":"R","text":"不會游泳的金魚？是烤魚嗎？Allan 你又餓了吧！"},{"who":"A","text":"冤枉喔。哥哥叫楊金魚，他在大廳燈樑上掛了一個和名字一樣的吉祥物金魚。"},{"who":"R","text":"把自己的名字掛在天花板上，好有自信喔！"},{"who":"A","text":"兄弟倆到星馬發展致富回來蓋房子。光是石材，石匠就在附近租屋打造將近兩年。"},{"who":"R","text":"兩年只做石頭！那石頭一定被磨得超漂亮。"},{"who":"A","text":"可惜日軍侵華時楊金魚一家遷往星馬，再也沒回來。1949年後這裡還當過國軍旅部辦公室。"},{"who":"R","text":"那從外面看，有什麼特別的地方？"},{"who":"A","text":"看左邊的小疊樓，二樓花瓶欄杆有好幾種花紋交錯排列。請你數數看，一共有幾種不同的花紋？"}],"clues":["為了我的石材，石匠在附近租屋將近兩年","我的大廳燈樑上掛著和主人同名的吉祥物","我在湖下，是一對星馬僑商兄弟的大厝"],"quiz":[{"q":"楊金魚在大廳燈樑上懸掛了什麼吉祥物？","options":["葫蘆","金魚","八卦鏡","蝙蝠"],"answer":1,"explain":"楊金魚在大廳燈樑上懸掛與名字相同的吉祥物「金魚」。"},{"q":"1949年國軍駐守金門時，這處宅第被用作什麼？","options":["野戰醫院","國民學校","旅部辦公室","糧食倉庫"],"answer":2,"explain":"因建築規模宏大，被選為金西旅旅部辦公室。"}],"images":[]},{"id":"jinning-wengzanshangweng","name":"翁贊商、翁贊榮洋樓","short":"翁贊商洋樓","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.44672,"lng":118.33797,"address":"金門縣金寧鄉盤山村下堡86、87號","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000013","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-15/7d8dc8bb-f92d-4455-9fb4-0287ba684bd9/翁贊商、翁贊榮洋樓_代表圖像.jpg","year":1930,"yearText":"年代不詳（1949年以前）","era":"unknown","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":true,"summary":"煙炙磚砌出拱廊美學的出龜五腳基洋樓","intro":"翁贊商、翁贊榮洋樓位於金寧鄉盤山村下堡。兄弟倆原在家鄉務農，並經營榨油與雜貨，打拚數年累積資金後共同建造二層洋樓，由福建惠安的張師傅父子設計，建材都從大陸購得。洋樓建成後，翁贊商才前往新加坡，再轉往印尼蘇門答臘巴東，與同父異母的弟弟翁贊謀會面，之後經營印尼與新加坡間的貿易，把橡膠汁液、椰乾與西穀米原料運往新加坡加工外銷，並定居新加坡。古寧頭戰役時，國軍曾在此設置指揮總部。洋樓為出龜五腳基形式，正立面以煙炙磚疊砌拱廊，柱頭疊澀精美，雖然沒有華麗裝飾，卻展現磚砌結構之美；山牆開有圓洞竹節窗。","highlights":["正立面煙炙磚疊砌的出龜五腳基拱廊","柱頭不同作法的磚疊澀","山牆上的圓洞竹節窗"],"funFact":"這棟洋樓是兄弟在金門靠務農、榨油和雜貨存錢蓋的，蓋好之後哥哥才出洋打拚。","photoSpot":"在前方拍煙炙磚拱廊與柱頭疊澀","visitMin":15,"openNote":"位於金寧鄉盤山村下堡。官方資料記載開放時間依藝文咖啡廳營業時間；其餘時間請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，金門的洋樓大多是先出洋賺錢再回來蓋，這棟卻剛好相反。"},{"who":"R","text":"相反？難道是先蓋房子，再出去賺錢？這樣不會倒過來嗎？"},{"who":"A","text":"答對了。翁贊商、翁贊榮兄弟在金門務農，還做榨油和雜貨，存夠錢先蓋好洋樓。"},{"who":"R","text":"那洋樓蓋好之後，哥哥去了哪裡？"},{"who":"A","text":"哥哥翁贊商才去新加坡，再到印尼巴東找弟弟，做起橡膠、椰乾和西米原料的貿易。"},{"who":"R","text":"西米！就是西米露的那個西米嗎？我突然好想喝一碗。"},{"who":"A","text":"就是那種原料。古寧頭戰役時，國軍還在這裡設過指揮總部。"},{"who":"R","text":"那這棟洋樓好看在哪裡？我沒看到很多花紋耶。"},{"who":"A","text":"它的美在磚。請你仔細看正面拱廊的柱頭，煙炙磚一層一層往外疊出來，數數看疊了幾層？"}],"clues":["我的主人兄弟在金門靠務農、榨油與雜貨存錢蓋我","我蓋好後，哥哥才前往新加坡與印尼巴東經商","我在盤山下堡，是煙炙磚砌的出龜五腳基洋樓"],"quiz":[{"q":"翁贊商、翁贊榮兄弟蓋洋樓的資金主要從哪裡來？","options":["在新加坡經商","在菲律賓開礦","在金門務農、榨油與雜貨","在越南經營米行"],"answer":2,"explain":"兄弟在家鄉務農並經營榨油與雜貨業，累積資金後共同建造。"},{"q":"這棟洋樓的設計者是誰？","options":["陳坑匠師陳江","惠安張師傅父子","廈門土水師","新加坡建築師"],"answer":1,"explain":"洋樓設計者為來自福建惠安縣的張師傅父子。"}],"images":[]},{"id":"jinsha-hesuqiangyanglou","name":"何肅墻洋樓","short":"何肅墻洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47958,"lng":118.38948,"address":"金門縣金沙鎮浦邊74號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000013","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-12-24/b47bf0d7-aa80-42cb-9d39-b3cf2475cd9e/20250806_163253.jpg","year":1930,"yearText":"年代不詳","era":"unknown","themes":["僑鄉洋樓","市場商業"],"yearUnknown":true,"summary":"門楣仍留「義發」二字的雜貨店洋樓","intro":"何肅墻洋樓位於金沙鎮浦邊聚落。興建者何肅墻清末前往同安經商，以花生油買賣致富，是浦邊的重要領袖，族人尊稱「墻伯公」；民國19年（1930）曾擔任防衛海盜的民團團長，也常出面替族人調解紛爭。洋樓為二層五腳基洋樓，民國38年（1949）起一樓經營雜貨店「義發商店」，前後約40多年，門楣至今仍可見「義發」二字。整體造型簡樸，一樓窗楣為拱形、二樓為圓弧形。民國112年（2023）杜蘇芮颱風造成屋頂與外牆受損，民國114年（2025）9月完成緊急修復。官方資料未載明興建年代。","highlights":["一樓門楣上的「義發」二字，見證40多年雜貨店歲月","一樓拱形、二樓圓弧形的不同窗楣","左側牆面下緣的人字砌磚牆"],"funFact":"何肅墻能言善道、才思敏捷，族人有紛爭常請他主持公道，因此被尊稱為「墻伯公」。","photoSpot":"拍一樓圓拱門與「義發」門楣","visitMin":10,"openNote":"位於金沙鎮浦邊聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往，或搭金門縣公車至沙美車站後轉乘。","dialogue":[{"who":"A","text":"阿拉蕾，猜猜看，這棟洋樓以前一樓在賣什麼？"},{"who":"R","text":"看起來樸素又可愛，該不會是賣貢糖的吧？"},{"who":"A","text":"接近了！民國38年起這裡開了雜貨店，叫義發商店，一開就是40多年，門楣到現在還看得到義發兩個字。"},{"who":"R","text":"那當初蓋房子的人，也是開店做生意的嗎？"},{"who":"A","text":"興建者何肅墻清末到同安做花生油生意致富，回到浦邊後，是大家口中的墻伯公。"},{"who":"R","text":"墻伯公？這個稱呼聽起來好有份量喔。"},{"who":"A","text":"他口才好，族人吵架都找他評理，民國19年還當過防海盜的民團團長，簡直是調解委員兼保全隊長。"},{"who":"R","text":"哈哈，一人分飾兩角！那房子後來還好嗎？"},{"who":"A","text":"2023年杜蘇芮颱風把屋頂和外牆打壞，2025年完成緊急修復。這是私人住宅，比一比一樓和二樓的窗楣形狀有什麼不同吧！"}],"clues":["我曾是雜貨店，門楣上還留著店名","我的主人以花生油生意致富，被尊稱為伯公","浦邊聚落的二層五腳基洋樓，一樓曾是義發商店"],"quiz":[{"q":"洋樓一樓門楣上仍可見哪兩個字？","options":["興發","瑞祥","義發","源泰"],"answer":2,"explain":"一樓曾經營「義發商店」，門楣仍留「義發」二字。"},{"q":"何肅墻當年靠什麼生意致富？","options":["布匹買賣","橡膠種植","南北貨批發","花生油買賣"],"answer":3,"explain":"何肅墻清末到同安經商，以花生油買賣致富。"}],"images":[]},{"id":"jinsha-chenshixiaozong","name":"陳氏小宗宗祠","short":"陳氏小宗宗祠","category":"歷史建築","level":"","town":"金沙鎮","types":["祠堂"],"lat":24.48613,"lng":118.44288,"address":"金門縣金沙鎮碧山14號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-26/ef67deba-19e8-4c40-a748-a3da48454f5e/01封面.jpg","year":1930,"yearText":"1930年（民國19年）改建為洋樓式宗祠","era":"japan","themes":["宗祠家廟","僑鄉洋樓"],"yearUnknown":false,"summary":"南洋族親出資改建成西式洋樓的宗祠","intro":"陳氏小宗宗祠俗稱「東祖厝」，位於金沙鎮碧山聚落，屬碧山陳氏西間長房，始建於清末。由於這一房族親旅居南洋事業有成者眾，民國19年（1930）由族親籌資，把原本的二落大厝改建成二層西式洋樓宗祠。民國38年宗祠被軍隊借用，先作辦公室，後為訓練班講堂，民國70年軍隊撤出；民國78年（1989）宗親每丁出資新臺幣四千元整修，成為今日樣貌。據《碧山陳氏宗祠重修誌》，開基祖陳存仁一家渡海遇風，漂至金門海邊定居，後來五子分為五房。前落為三開間，水車堵留有僑匯時期的馬約利卡彩磁，後落二樓有曲線山頭與「穎川堂」字樣。","highlights":["鏡面牆圓窗裡三根綠釉欄杆與四角蝙蝠","後落二樓曲線山頭與「穎川堂」字樣","前落水車堵的馬約利卡彩磁"],"funFact":"祖龕上方橫樑寫著靛藍色的「平章事」，紀念先祖陳德宗在元朝官居一品平章事。","photoSpot":"在宗祠前拍洋樓山頭與前落門楣","visitMin":15,"openNote":"位於金沙鎮碧山聚落。宗族祠堂，官方資料未載開放時間，請在外觀參觀，勿擅入；遇祭祖等宗族活動請保持安靜、尊重宗親。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這座宗祠怎麼有二樓，還有洋樓的山頭？我以為宗祠都是紅瓦平房！"},{"who":"A","text":"所以它很特別！民國19年，旅居南洋的族親出錢，把原本的二落大厝改建成洋樓式宗祠。"},{"who":"R","text":"連祖先都住進洋樓了，這也太時髦了吧！"},{"who":"A","text":"這是碧山陳氏西間長房的小宗祠，俗稱「東祖厝」。族譜說開基祖陳存仁帶著妻子渡海遇風，漂到金門海邊定居。"},{"who":"R","text":"被風吹來的祖先，好像漂流冒險故事！"},{"who":"A","text":"後來他生了五個兒子，分成五房。民國38年這裡被軍隊借用，當過辦公室和訓練班講堂。"},{"who":"R","text":"那這座宗祠後來是怎麼修好的呢？"},{"who":"A","text":"民國78年宗親每丁出資四千元重修。宗祠平常不一定開放，我們在外面欣賞。找找鏡面牆的圓窗，裡面有幾根綠色欄杆？"}],"clues":["我原本是二落大厝，後來被南洋族親改建成二層洋樓","我俗稱「東祖厝」，祖龕橫樑寫著「平章事」","碧山陳氏西間長房的洋樓式小宗祠"],"quiz":[{"q":"這座宗祠在民國19年被改建成什麼樣式？","options":["二落大厝","三川殿廟宇","二層西式洋樓","日式木造建築"],"answer":2,"explain":"民國19年由南洋族親籌資，改建為二樓西式洋樓小宗祠。"},{"q":"陳氏小宗宗祠俗稱什麼？","options":["西祖厝","東祖厝","大宗祠","頂祖厝"],"answer":1,"explain":"陳氏小宗宗祠俗稱「東祖厝」，屬西間房派。"}],"images":[]},{"id":"jincheng-xuefangjianyanglou","name":"薛芳見洋樓","short":"薛芳見洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.401066,"lng":118.32066,"address":"金門縣金城鎮珠山7號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000019","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/531c2708-bf6b-4190-9795-d04200105e94/01封面.jpg","year":1931,"yearText":"1931年（民國20年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"高大兼具防禦的「機關樓」，正等待修復","intro":"薛芳見洋樓位於金城鎮珠山聚落，由菲律賓僑匯返鄉興建，二樓門口左側勒石記載「民國弍拾年，樓薛芳見造」及木匠、石匠、塗匠姓名，可知建於1931年。因建物高大，又被賦予防禦功能，俗稱「機關樓」。前棟為二層五腳基洋樓，正立面六柱五開間拱圈，一層以蠣殼灰洗石子作方格裝飾，前廊橫樑可見早期鋼筋混凝土構造；後棟為帶花瓶欄杆的洋式單層建築。洋樓因產權不明長期閒置，屋頂坍塌、拱圈開裂，金門國家公園管理處曾於2020年清除植生，2024年12月完成前廊緊急加固。","highlights":["一層蠣殼灰洗石子的方格裝飾","二樓門口左側記載民國20年建造的勒石","後棟帶多重線腳扶手的洋式花瓶欄杆"],"funFact":"「機關樓」的名稱不是因為有機關暗器，而是建物高大又兼具防禦功能。","photoSpot":"在路旁安全距離拍拱圈立面","visitMin":10,"openNote":"位於金城鎮珠山聚落，私人產業且產權不明、長期閒置；建築損壞嚴重，2024年底才完成前廊緊急加固，請在外觀參觀並保持安全距離，勿進入。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，聽說這棟洋樓叫機關樓，裡面是不是有暗門和陷阱？"},{"who":"A","text":"哈，你武俠片看太多了。它叫機關樓，是因為建物高大，又兼具防禦功能。"},{"who":"R","text":"原來如此，那這棟高大的洋樓是誰蓋的？"},{"who":"A","text":"二樓門口旁的勒石寫著民國20年，也就是1931年，由薛芳見興建，資金來自菲律賓僑匯。"},{"who":"R","text":"它跟隔壁那些漂亮洋樓比起來，看起來好滄桑喔。"},{"who":"A","text":"因為產權不明，長期沒人管理，屋頂坍塌、拱圈也裂了，2024年底才做了前廊緊急加固。"},{"who":"R","text":"好心疼，希望它能像吃完一碗熱粥一樣恢復元氣。"},{"who":"A","text":"我也這麼希望。注意看一樓牆面，用蠣殼灰洗石子做出一格一格的方格裝飾。"},{"who":"A","text":"請你在路邊安全距離外，數數看一樓牆面上的方格，記得千萬不要靠近喔！"}],"clues":["我一層牆面用蠣殼灰洗石子做出方格裝飾","我因高大又能防禦，俗稱「機關樓」","我在珠山，勒石記載民國20年由菲律賓僑匯興建"],"quiz":[{"q":"薛芳見洋樓為什麼俗稱「機關樓」？","options":["樓內藏有機關暗器","曾是政府機關","高大又兼具防禦功能","屋頂裝有風車機械"],"answer":2,"explain":"因建物高大，被賦予防禦功能而得名。"},{"q":"薛芳見洋樓的建造資金主要來自哪裡？","options":["菲律賓僑匯","印尼僑匯","緬甸僑匯","新加坡僑匯"],"answer":0,"explain":"官方資料記載由菲律賓僑匯返鄉興建。"}],"images":[{"file":"薛芳見洋樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/%E8%96%9B%E8%8A%B3%E8%A6%8B%E6%B4%8B%E6%A8%93.jpg/960px-%E8%96%9B%E8%8A%B3%E8%A6%8B%E6%B4%8B%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%96%9B%E8%8A%B3%E8%A6%8B%E6%B4%8B%E6%A8%93.jpg","artist":"Shuzhenlee","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jincheng-xuefangjianyanglou-0.webp","small":"img/jincheng-xuefangjianyanglou-0-s.webp"}]},{"id":"jincheng-huangfuxingzhai","name":"黃福星宅","short":"黃福星宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41046,"lng":118.29598,"address":"金門縣金城鎮前水頭111-1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000042","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/5627ed3a-df75-4283-9bb4-6b34f96894c4/01封面.jpg","year":1931,"yearText":"約1931年（民國20年）","era":"japan","themes":["閩南古厝"],"yearUnknown":false,"summary":"菲律賓僑匯興建的彩磁二落大厝","intro":"黃福星宅位於金城鎮水頭聚落，約建於1931年，是黃福星到菲律賓發跡後寄回資金興建的二落大厝。牆身下堵為石板條平砌、中上堵為紅磚斗仔砌，屋身為硬山擱檁構造，雙落屋脊皆為翹脊。正面採榻受作法，身堵嵌入手繪彩磁「五福臨門」、「六合同春」以及象徵「花開富貴」的博古花卉圖，祈求家族趨吉納福。前落設有雕刻精緻的木作格扇門，以萬字紋與花鳥圖案裝飾，兩側腰堵有花卉泥塑。官方資料記載詳細沿革仍待調查。","highlights":["身堵手繪彩磁「五福臨門」與「六合同春」","象徵花開富貴的博古花卉彩磁","雙落翹脊與石板條平砌牆基"],"funFact":"水頭不少古厝來自印尼僑匯，黃福星則是在菲律賓發跡後寄錢回鄉蓋屋。","photoSpot":"拍榻受身堵的手繪彩磁","visitMin":10,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這面牆上的磁磚畫有好多花和瓶子，是在賣古董嗎？"},{"who":"A","text":"那是博古花卉圖，象徵花開富貴。旁邊還有手繪彩磁「五福臨門」和「六合同春」。"},{"who":"R","text":"五福臨門我知道，六合同春是什麼意思？"},{"who":"A","text":"六合指天地和東西南北四方，合起來就是到處都充滿春天的祝福。"},{"who":"R","text":"好多祝福，一面牆就是一個大紅包！"},{"who":"A","text":"屋主黃福星在菲律賓發跡，約1931年寄錢回來，蓋了這棟二落大厝。"},{"who":"R","text":"寄錢回家蓋房子，家人一定很驕傲。"},{"who":"A","text":"前落還有萬字紋和花鳥木雕的格扇門，不過這是私人住宅，我們在外面欣賞，等一下再去吃碗蚵仔麵線。"},{"who":"A","text":"請在榻受兩側的彩磁裡找一找，哪一幅是五福臨門，哪一幅是六合同春！"}],"clues":["我的主人在菲律賓發跡，寄錢回鄉建屋","我的身堵有手繪彩磁五福臨門與六合同春","我是水頭聚落約1931年興建的二落大厝"],"quiz":[{"q":"黃福星在哪裡發跡？","options":["印尼","菲律賓","新加坡","越南"],"answer":1,"explain":"黃福星至菲律賓發跡後，寄回資金興建此宅。"},{"q":"身堵的博古花卉圖象徵什麼？","options":["竹報平安","子孫滿堂","魚躍龍門","花開富貴"],"answer":3,"explain":"身堵嵌入象徵花開富貴的博古花卉圖。"}],"images":[]},{"id":"jinning-likaiheyanglou","name":"李開和洋樓","short":"李開和洋樓","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.47825,"lng":118.30734,"address":"金門縣金寧鄉古寧村南山36號","announced":"2003-12-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031222000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/3c499b80-5df6-41fb-a945-7380954eded1/李開和洋樓_封面.jpg","year":1931,"yearText":"1931年（民國20年）","era":"japan","themes":["僑鄉洋樓","名人故居"],"yearUnknown":false,"summary":"在新加坡畫好設計圖寄回家鄉的出龜洋樓","intro":"李開和洋樓位於金寧鄉古寧村南山聚落。李開和（1892～1943）21歲出洋到馬來西亞彭亨，後移居新加坡，從水客做到船主，曾擔任和豐號船主六年，之後定居新加坡開設和源號經營橡膠貿易。1931年他在新加坡完成設計，把圖寄回家鄉，委託親友到廈門購買建材，花費3000銀元，由陳坑大木匠師陳江主持，並與廈門匠師合作興建。洋樓為出龜式，一樓前廊用花崗岩六角柱，檐板有水果、花卉、獅頭等水泥預鑄裝飾，圍牆頂還有防盜的玻璃刀山。古寧頭戰役時國軍曾進駐，八二三砲戰留下砲損，1991年修繕屋頂，至今仍由家族後代居住。","highlights":["檐板上水果、花卉、捲草與獅頭的水泥預鑄裝飾","一樓出龜前廊的花崗岩六角柱","圍牆頂端防盜用的玻璃刀山"],"funFact":"這棟洋樓的設計圖是在新加坡畫好再寄回金門的，建材則委託親友到廈門採購。","photoSpot":"在圍牆外拍出龜立面與檐板飾帶","visitMin":15,"openNote":"位於金寧鄉古寧村南山聚落。私人住宅，仍由家族後代居住，請在外觀參觀，勿擅入、勿打擾住戶。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的屋簷上好像掛滿水果，是要開水果攤嗎？"},{"who":"A","text":"那是水泥預鑄的裝飾，有水果、花卉、捲草，還有獅頭，看久了我都餓了，想吃廣東粥。"},{"who":"R","text":"你什麼都能想到吃的！那這棟是誰蓋的？"},{"who":"A","text":"李開和，他從水客做到船主，後來在新加坡開和源號做橡膠生意，事業很成功。"},{"who":"R","text":"水客是什麼？是很會游泳的人嗎？"},{"who":"A","text":"水客是幫僑胞帶錢和貨物往返家鄉與南洋的人啦。1931年他在新加坡畫好設計圖，寄回家鄉蓋這棟洋樓。"},{"who":"R","text":"遠端設計耶，好有現代感！跟我們線上開會一樣！那牆上的小洞洞是什麼？"},{"who":"A","text":"那是戰爭留下的彈孔與修補痕跡。最後請你抬頭找找圍牆頂端，有沒有一排防小偷的玻璃刀山？"}],"clues":["我的主人從水客做到船主，後來經營橡膠貿易","我的設計圖在新加坡畫好，再寄回家鄉","我在古寧頭南山，檐板上有水果和獅頭裝飾"],"quiz":[{"q":"李開和在新加坡開設的商號叫什麼？","options":["和豐號","聯芳公司","協德號","和源號"],"answer":3,"explain":"李開和定居新加坡後開設和源號，經營橡膠貿易。"},{"q":"李開和洋樓圍牆頂端的玻璃刀山有什麼功能？","options":["防盜","排水","裝飾風水","通風"],"answer":0,"explain":"圍牆頂部設玻璃刀山，是防盜功能的設計。"}],"images":[]},{"id":"jinsha-chendexingyanglou","name":"陳德幸洋樓","short":"陳德幸洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.485689,"lng":118.440316,"address":"金門縣金沙鎮碧山1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000007","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-31/135f4cb3-fded-4013-b0e7-9a123c7ee003/01封面.jpg","year":1931,"yearText":"1929–1931年（民國18至20年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"因母親一句話而取消疊樓的碧山出龜洋樓","intro":"陳德幸洋樓位於金沙鎮碧山聚落。陳德幸（1889–1967）年輕時務農難以溫飽，遠赴新加坡投靠堂哥陳睿友經營的「金和美」商號，擔任經理並協助管理橡膠園等事務。積蓄有成後，他延聘福建惠安與金門工匠，民國18年（1929）動工、約民國20年落成；建築本體就花了七千餘圓，當時一棟一落四櫸頭約一千餘圓，加上後續工程總計一萬餘元，期間還得再下南洋籌錢。洋樓為出龜式，正面以燕子磚、彩磁和紅藍洗石子裝飾，山頭有雙鼠、雙鳳、雙龍泥塑，寓意「望子成龍」。民國38年起國軍陸續進駐，撤離後閒置至今。","highlights":["山頭雙鼠、雙鳳、雙龍泥塑，寓意望子成龍","一樓正面燕子磚組砌與紅藍洗石子","山頭牛眼洞下方的砲彈損痕"],"funFact":"後方櫸頭原本要蓋疊樓，陳德幸的母親擔心會擋住後方祖厝祖先與神明的視線，計畫就此取消。","photoSpot":"在屋前仰拍出龜五角形山頭","visitMin":15,"openNote":"位於金沙鎮碧山聚落。私人產權，現況閒置，請在外觀參觀，勿擅入。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，這棟洋樓的二樓後面，本來應該還要再疊一層樓，你知道為什麼沒蓋嗎？"},{"who":"R","text":"是錢不夠嗎？還是怕颱風把它吹倒？"},{"who":"A","text":"都不是。陳德幸的媽媽說，疊樓太高會擋住後面祖厝裡祖先和神明的視線，於是就取消了。"},{"who":"R","text":"哇，媽媽一句話就改設計圖，這就是傳說中的家庭最高法院吧！"},{"who":"A","text":"哈哈，沒錯。陳德幸在新加坡投靠堂哥陳睿友的商號當經理，存了錢回來，光主體就花了七千多圓。"},{"who":"R","text":"七千多圓在那個年代，到底算不算很多呢？"},{"who":"A","text":"那時一棟一落四櫸頭大約一千多圓，所以這棟可以抵好幾棟古厝。他還為了後續工程再下南洋籌錢。"},{"who":"R","text":"那山頭中間那個破洞是怎麼來的？"},{"who":"A","text":"那是兩岸砲擊時期被砲彈擊中留下的痕跡，提醒我們那段艱難的歲月。仔細看山頭，找找雙鼠、雙鳳和雙龍在哪裡。"}],"clues":["我的後方原本要加蓋疊樓，卻因主人母親的顧慮而取消","我的山頭泥塑有雙鼠、雙鳳、雙龍，寓意望子成龍","碧山一棟由新加坡商號經理興建的出龜洋樓"],"quiz":[{"q":"洋樓後方的疊樓為什麼沒有蓋？","options":["土地糾紛","建材運不過來","母親擔心遮住祖厝視線","官府禁止蓋高樓"],"answer":2,"explain":"陳德幸母親認為疊樓會遮蔽後方祖厝祖先與神明視線。"},{"q":"山頭的雙鼠、雙鳳、雙龍泥塑寓意什麼？","options":["五穀豐收","平安歸鄉","招財進寶","望子成龍"],"answer":3,"explain":"山頭三段式泥塑有雙鼠、雙鳳、雙龍，寓意望子成龍。"}],"images":[{"file":"被遺忘的洋樓.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/%E8%A2%AB%E9%81%BA%E5%BF%98%E7%9A%84%E6%B4%8B%E6%A8%93.jpg/960px-%E8%A2%AB%E9%81%BA%E5%BF%98%E7%9A%84%E6%B4%8B%E6%A8%93.jpg","page":"https://commons.wikimedia.org/wiki/File:%E8%A2%AB%E9%81%BA%E5%BF%98%E7%9A%84%E6%B4%8B%E6%A8%93.jpg","artist":"鐘堡","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-chendexingyanglou-0.webp","small":"img/jinsha-chendexingyanglou-0-s.webp"}]},{"id":"jinsha-huangxinjianzhai","name":"黃信堅宅","short":"黃信堅宅","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49545,"lng":118.41889,"address":"金門縣金沙鎮英坑23號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000015","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-15/02b0a2cb-b576-4359-8933-706c1c56f39b/黃信堅宅.jpg","year":1931,"yearText":"約1931–1934年（民國20至23年）","era":"japan","themes":["閩南古厝","名人故居"],"yearUnknown":false,"summary":"神戶華僑家族匯款興建的大厝加疊樓","intro":"黃信堅宅位於金沙鎮英坑聚落，是旅日重要商僑黃信堅（1900–1983）匯款回鄉興建，約民國20年（1931）動工、23年前後完成。黃家出洋始於清光緒元年（1875），祖父黃禮蘭到日本神戶經商，經營火柴產業，成為當地華僑領袖之一；父親黃智泰後來轉往印尼發展。黃信堅16歲再赴神戶當學徒，民國23年創立貿易商行。據《金門縣誌》，此宅曾於民國23年遭盜匪侵入，所幸只有財物損失。中日戰爭爆發後他一度返鄉居住於此。建築為一落四櫸頭加前迴向五腳基疊樓，形式特殊，並以隘門連接左側建築作防禦。民國38至78年間曾由國軍駐紮。","highlights":["一落四櫸頭前加五腳基疊樓的特殊形式","鏡面牆上的「紫雲流芳」與壽屏「儉能養德」","女兒牆的綠釉花磚與火焰形窗楣"],"funFact":"黃家祖父黃禮蘭在神戶做火柴生意，把手工製作改成機器量產，產品還外銷香港、南洋與歐洲。","photoSpot":"在屋外拍疊樓花瓶欄杆與黃色拱帶","visitMin":15,"openNote":"位於金沙鎮英坑聚落。私人產權，現借親友居住，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝前面怎麼多了一棟兩層樓的洋式房子？好像戴了一頂新帽子。"},{"who":"A","text":"形容得妙！後面是傳統的一落四櫸頭，前面加了一排五腳基疊樓，這種組合官方說很特殊。"},{"who":"R","text":"那這裡的主人是不是也下南洋賺錢？"},{"who":"A","text":"這次不一樣，黃家主要是在日本神戶打拚。祖父黃禮蘭清光緒元年就去神戶，做火柴生意起家。"},{"who":"R","text":"火柴！一根一根擦亮，就擦出了一間大房子！"},{"who":"A","text":"哈哈，好冷但很貼切。孫子黃信堅後來也到神戶創業，民國20年匯錢回來蓋了這座宅第。"},{"who":"R","text":"那黃家的人現在還住在這座宅第裡嗎？"},{"who":"A","text":"家族散居印尼、日本和臺灣，房子借給親友住，我們在外面看。壽屏上的家訓是「儉能養德」，提醒有錢也要節儉。"},{"who":"R","text":"收到！那我去找找看，疊樓拱形梁上那條亮黃色的裝飾帶！"}],"clues":["我的主人家族三代在日本神戶與印尼打拚，祖父做火柴生意","我是一落四櫸頭，前面再加一排五腳基疊樓","英坑一座由旅日商僑匯款興建、壽屏寫著「儉能養德」的宅第"],"quiz":[{"q":"黃信堅的祖父黃禮蘭在神戶經營什麼產業？","options":["火柴","茶葉","紡織","陶瓷"],"answer":0,"explain":"黃禮蘭在神戶成立廣駿源號，經營火柴產業。"},{"q":"黃信堅宅的壽屏上方橫批寫著哪四個字？","options":["詩書傳家","相國遺澤","儉能養德","紫雲流芳"],"answer":2,"explain":"壽屏上方橫批大字「儉能養德」，是家族的訓誡。"}],"images":[]},{"id":"jinsha-huanglouyanglou","name":"黃樓洋樓","short":"黃樓洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.51157,"lng":118.40453,"address":"金門縣金沙鎮西園151號","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000008","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-15/4448cb86-cbd3-4730-b445-4c3cad5990b2/黃樓洋樓_代表圖像(壓縮).jpg","year":1931,"yearText":"1929–1931年（民國18至20年）","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"西園村裡唯一的五腳基洋樓","intro":"黃樓洋樓位於金沙鎮西園聚落，是西園村中唯一的洋樓建築。黃樓早年在新加坡經營貿易商行致富，民國18年（1929）返鄉籌建，興建期間多次往返新加坡與金門，民國20年（1931）竣工。民國26年他與妻子、長子返鄉定居，但民國28年黃樓病逝，長子回新加坡謀生後就失去聯絡。民國38年洋樓被國軍作為營指揮所，門板和房門幾乎全被拆去構築碉堡；民國47年為躲避砲火，又在屋內挖設防空洞。民國75年國軍歸還時損毀嚴重，民國94年（2005）完成整體修復。洋樓為六柱五開間的五腳基形式，一樓圓磚柱配雙魚插角，二樓以拱圈相連。","highlights":["六柱五開間立面與二樓連續拱圈","一樓柱頭的西式線腳與雙魚插角","山牆中央圓窗上的火焰形窗楣"],"funFact":"國軍進駐時，洋樓的大門與房門板幾乎全被拆去構築碉堡，現在看到的門都是修復後的樣貌。","photoSpot":"在屋前拍六柱五開間的完整立面","visitMin":15,"openNote":"位於金沙鎮西園聚落，與黃昌命（納）古厝同在西園。私人產權，請在外觀參觀，勿擅入、勿打擾。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，整個西園村走一圈，好像只有這一棟是洋樓耶！"},{"who":"A","text":"觀察正確！官方說黃樓洋樓是西園村中唯一的洋樓，主人黃樓在新加坡經營貿易商行致富。"},{"who":"R","text":"那他蓋好以後一定住得很開心吧？"},{"who":"A","text":"他民國20年蓋好，民國26年才帶家人回來定居，沒想到兩年後就病逝了，兒子回新加坡後也失去聯絡。"},{"who":"R","text":"好讓人難過，房子還在，家人卻散了。"},{"who":"A","text":"是啊。後來國軍把這裡當營指揮所，門板幾乎都拆去蓋碉堡，民國47年還在屋裡挖了防空洞。"},{"who":"R","text":"連門都被拆走，那它現在怎麼還這麼漂亮？"},{"who":"A","text":"民國94年完成整體修復，才恢復現在的樣子。一樓柱頭有兩條魚做成的插角，像在柱子上游泳。"},{"who":"R","text":"柱子上的魚！那我要在外面數數看，一樓一共有幾對雙魚！"}],"clues":["我是整個西園村裡唯一的洋樓","國軍進駐時，我的門板幾乎全被拆去構築碉堡","西園一棟六柱五開間、柱頭有雙魚插角的五腳基洋樓"],"quiz":[{"q":"黃樓洋樓在西園村有什麼特別之處？","options":["村中最古老的建築","村中唯一的廟宇","村中最高的碉堡","村中唯一的洋樓"],"answer":3,"explain":"黃樓洋樓為西園村中唯一的洋樓建築。"},{"q":"國軍進駐時，洋樓的門板被拿去做什麼？","options":["當柴火燒","做成床板","構築碉堡","製作看板"],"answer":2,"explain":"大門及房門板全數被拆除，作為構築碉堡建材。"}],"images":[]},{"id":"lieyu-dongkengsunjiatong","name":"東坑孫嘉通洋樓","short":"孫嘉通洋樓","category":"歷史建築","level":"","town":"烈嶼鄉","types":["宅第"],"lat":24.44279,"lng":118.23155,"address":"金門縣烈嶼鄉東坑51號","announced":"2016-12-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20161226000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-28/435e726b-1b2b-4131-a02a-735f93d8f6ac/代表圖像.jpg","year":1931,"yearText":"1931年（民國20年）落成","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"兒子南洋打拚、以父親之名蓋成的洋樓","intro":"東坑孫嘉通洋樓位於烈嶼鄉東坑聚落。孫嘉通以務農為業；長子孫志駕（1891–1986）約於民國10年（1921）赴新加坡，創立「明發號」經營土產買賣與九八行貿易。累積資金後，他返鄉購地，以父親名義興建洋樓並親自督工，木料、石材、紅料皆購自廈門，民國18年（1929）動工，民國20年（1931）落成。建築為五腳基洋樓帶前落二櫸頭，側立面裙堵以蚵堵石人字砌，俗稱「蜈蚣砌」或「魚鱗砌」，與在地蚵田產業息息相關。屋內留有民國43年（1954）所建的防空洞。目前前落與前廊嚴重傾頹，建築閒置。","highlights":["側立面蚵堵石人字砌的「蜈蚣砌」","二樓紅磚圓拱窗楣與葫蘆造型鏤空規尾窗","前落煙炙磚砌的女兒牆"],"funFact":"洋樓掛的是父親孫嘉通的名字，真正出錢又親自督工的，是在新加坡打拚的長子孫志駕。","photoSpot":"特寫側牆蜈蚣砌的石紋","visitMin":10,"openNote":"位於烈嶼鄉東坑聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶；建築嚴重傾頹，請勿靠近。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，這棟明明叫孫嘉通洋樓，你為什麼一直提另一個人的名字？"},{"who":"A","text":"因為真正出錢的是他兒子孫志駕！爸爸務農，總覺得家裡住不下，兒子就決定去新加坡打拚。"},{"who":"R","text":"好孝順！那他在新加坡做什麼生意？"},{"who":"A","text":"他開了「明發號」做土產買賣和九八行貿易，賺了錢回來，用爸爸的名義蓋洋樓，還親自督工。"},{"who":"R","text":"這根本是送給爸爸的超大禮物吧！"},{"who":"A","text":"而且很講究，木料、石材、紅磚都從廈門買，民國18年動工，民國20年完工。"},{"who":"R","text":"咦，側面的石牆紋路好像魚鱗耶！"},{"who":"A","text":"就叫魚鱗砌，也叫蜈蚣砌，用的是蚵堵石，跟這裡的蚵田生活有關。等一下去吃石蚵，也算向蚵田致敬。"},{"who":"A","text":"現在建築傾頹了，請在屋外看就好。找找側牆上斜斜排列的石塊，像不像一隻蜈蚣？"}],"clues":["我掛著父親的名字，出錢的卻是兒子","我的側牆用蚵堵石人字砌，人稱蜈蚣砌","我是小金門東坑聚落在1931年落成的洋樓"],"quiz":[{"q":"孫志駕在新加坡創立的商號是？","options":["協發","金聯發","明發號","金合發"],"answer":2,"explain":"孫志駕創立「明發號」，經營土產與九八行貿易。"},{"q":"「蜈蚣砌」使用的是哪一種石材？","options":["玄武岩","蚵堵石","珊瑚礁石","砂岩"],"answer":1,"explain":"側立面裙堵以蚵堵石人字砌，又稱蜈蚣砌。"}],"images":[]},{"id":"jincheng-jinshuiguoxiao","name":"金水國小","short":"金水國小","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.40929,"lng":118.29796,"address":"金門縣金城鎮前水頭47號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000053","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-06-04/17877c42-77d5-4ee0-a3e7-7de133205be1/金水國小.jpg","year":1932,"yearText":"1932年（民國21年）落成","era":"japan","themes":["教育書院","僑鄉洋樓"],"yearUnknown":false,"summary":"僑匯興建、金門規模最大的僑辦小學","intro":"金水國小位於金城鎮水頭聚落（前水頭），1932年落成，由水頭黃氏族人與旅居印尼的鄉僑集資興建，是僑匯時期金門規模最大的僑辦小學。1927年起向印尼華僑募款，1931年動工，聘同安與本地匠師施工，村中16歲以上壯丁每人義務出工6天。學校在印尼麻里巴板設20間校產店舖，以租金支應校務。日軍占領時期停辦，曾作野戰醫院；戰後復校，1950年改為公立，國軍也曾借用辦理士官學校。1986年併校後停用，現由金門國家公園管理處修復為僑鄉展示館。","highlights":["正面中央山頭的天使、彩帶、葡萄與字母泥塑","回字型平面，中央講堂四周環繞教室與廊道","以落番路徑、僑匯與皮箱書信為主題的展覽"],"funFact":"1920年代起學校辦過校刊《塔峰月刊》，讓僑居地的鄉親也能讀到家鄉消息。","photoSpot":"正面拍三座山頭與老鷹、天使泥塑","visitMin":40,"openNote":"位於金城鎮水頭聚落，由金門國家公園管理處作為展示館開放，官方資料記載每日8:30至17:00，農曆除夕休館。鄰近水頭碼頭，可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間學校門口有天使和老鷹，是不是專門給小天使上課的地方？"},{"who":"A","text":"哈，這裡的學生都是水頭的小朋友啦！金水國小1932年落成，是金門規模最大的僑辦小學。"},{"who":"R","text":"僑辦？意思是海外華僑出錢蓋的學校嗎？"},{"who":"A","text":"對，水頭黃氏族人和旅居印尼的鄉親集資，村裡16歲以上的壯丁，每人還義務出工6天。"},{"who":"R","text":"好團結！那蓋好之後，老師的薪水誰付呢？"},{"who":"A","text":"他們在印尼麻里巴板設了20間校產店舖，靠租金養學校，可說是跨國經營的校務基金。"},{"who":"R","text":"太有遠見了，比你只會存零錢買貢糖厲害多了。"},{"who":"A","text":"喂，貢糖也是投資啊。現在這裡是僑鄉展示館，有皮箱和書信，訴說落番的辛苦。"},{"who":"A","text":"進去前先在正門抬頭找一找，中央山頭上除了天使，還藏著一個大大的英文字母，是哪一個？"}],"clues":["我1932年落成，村裡壯丁每人義務出工6天蓋我","我在南洋有20間校產店舖，用租金支撐校務","我是水頭聚落的僑辦小學，現在是僑鄉展示館"],"quiz":[{"q":"這所學校的校務經費主要靠什麼支應？","options":["政府的教育補助","印尼的校產店舖租金","學生繳交的學費","家廟的香油錢"],"answer":1,"explain":"學校在印尼麻里巴板設20間店舖，以租金做校務基金。"},{"q":"興建時村裡16歲以上壯丁每人義務出工幾天？","options":["3天","10天","15天","6天"],"answer":3,"explain":"工程期間16歲以上壯丁每人義務出工6天。"}],"images":[{"file":"Jinshui Elementary School 金水國小 - panoramio (1).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5f/Jinshui_Elementary_School_%E9%87%91%E6%B0%B4%E5%9C%8B%E5%B0%8F_-_panoramio_%281%29.jpg/960px-Jinshui_Elementary_School_%E9%87%91%E6%B0%B4%E5%9C%8B%E5%B0%8F_-_panoramio_%281%29.jpg","page":"https://commons.wikimedia.org/wiki/File:Jinshui_Elementary_School_%E9%87%91%E6%B0%B4%E5%9C%8B%E5%B0%8F_-_panoramio_(1).jpg","artist":"lienyuan lee","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/jincheng-jinshuiguoxiao-0.webp","small":"img/jincheng-jinshuiguoxiao-0-s.webp"}]},{"id":"jincheng-xujinzhongyanglou","name":"許金鐘洋樓","short":"許金鐘洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.43099,"lng":118.31511,"address":"金門縣金城鎮民族路266巷7號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000067","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-23/3aef4183-08e7-4495-933c-b08e0a45e5bb/01封面.jpg","year":1933,"yearText":"1933年（民國22年）","era":"japan","themes":["僑鄉洋樓","市場商業"],"yearUnknown":false,"summary":"沒出過洋的船頭行老闆與緬甸弟弟合建","intro":"許金鐘洋樓位於金城鎮後浦民族路巷內，1933年竣工，由珠浦許氏第22世許金鐘與弟弟許金榜合資興建。許金鐘本人沒有出洋，而是在後浦南門同安碼頭經營「協德船頭行」，往返廈門、漳州、集美、石尾販運貨物；許金榜則在緬甸經商起家。兄弟拆除不敷使用的老宅，聘福建匠師、從廈門輸入建材興建洋樓。1937年日軍占領金門，一樓被占用，家人集中住在二樓；1949年後國軍進駐，軍民同住。官方資料記載許金榜二子後被部隊以攜帶鴉片罪名提審，被迫出外避難，1985年才在新加坡重逢。洋樓前有牆門，山頭飾飛鷹與天使泥塑。","highlights":["牆規樓山頭的飛鷹與兩側天使泥塑","屋頂綠釉花瓶欄杆女兒牆","二樓門楣「高陽衍派」堂號與藏頭門聯"],"funFact":"洋樓正面原有山頭嵌著聖母瑪麗亞塑像，屋頂倒塌改建後未復原，塑像由所有權人保存。","photoSpot":"在巷口拍牆規樓飛鷹山頭","visitMin":10,"openNote":"位於金城鎮後浦民族路巷內，私人產業，官方資料記載不開放參觀；建築荒廢損壞，請在外觀參觀並保持距離，勿擅入。金城車站附近，可步行前往。","dialogue":[{"who":"A","text":"阿拉蕾，金門洋樓大多是出洋賺錢回來蓋的，但這棟的主人許金鐘，其實一輩子沒出過洋。"},{"who":"R","text":"沒出洋也能蓋洋樓？他是不是偷偷中了樂透？"},{"who":"A","text":"不是啦，他在後浦南門的同安碼頭開協德船頭行，船隻往返廈門、漳州，做進口貨生意。"},{"who":"R","text":"原來是在家門口做大生意！那出洋的是誰？"},{"who":"A","text":"是弟弟許金榜，在緬甸經商起家。兄弟合資在1933年蓋好這棟洋樓，一家人住在一起。"},{"who":"A","text":"後來經歷日軍占領和國軍駐紮，家人曾和駐軍同住，許金榜的兩個兒子也被迫離鄉，多年後才在新加坡重逢。"},{"who":"R","text":"一棟樓裝了這麼多離別，聽了心裡酸酸的。"},{"who":"A","text":"是啊。現在洋樓荒廢不開放，不過牆門山頭的飛鷹和小天使還在守著。"},{"who":"A","text":"請你在巷口抬頭找找那隻飛鷹，再看看兩旁的天使在做什麼動作！"}],"clues":["我的主人沒出過洋，在同安碼頭經營船頭行","我門前牆規樓的山頭有一隻飛鷹和兩位天使","我在後浦民族路，由許氏兄弟1933年合建"],"quiz":[{"q":"許金鐘本人從事什麼行業？","options":["在緬甸開商行","在菲律賓開碾米廠","在印尼做土產","在同安碼頭經營船頭行"],"answer":3,"explain":"許金鐘未出洋，在同安碼頭經營協德船頭行。"},{"q":"許金鐘的弟弟許金榜在哪裡經商起家？","options":["新加坡","菲律賓","緬甸","印尼"],"answer":2,"explain":"許金榜年輕時出洋，在緬甸經商起家。"}],"images":[]},{"id":"jinsha-chenqingjiyanglou","name":"陳清吉洋樓","short":"陳清吉洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.4858,"lng":118.44305,"address":"金門縣金沙鎮碧山20號","announced":"2005-12-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051219000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-20/e605e517-e21c-40f9-9563-6b4125ed000a/陳清吉洋樓封面.png","year":1933,"yearText":"1931–1933年（民國20至22年）","era":"japan","themes":["僑鄉洋樓","名人故居"],"yearUnknown":false,"summary":"橫樑寫著英文「團結就是力量」的豪華洋樓","intro":"陳清吉洋樓位於金沙鎮碧山聚落。陳清吉（1887–1966）11歲隨父親下南洋，從新加坡碼頭舢舨苦力做起，24歲創辦「和通」商號，經營胡椒、米、橡膠，並投資磚場與民信局，在新加坡還闢建店屋，命名「金門園」「金門路」，是僑界領袖之一。他聘洋山匠師王城譽設計，民國20年（1931）動工、22年完工，工料約銀四萬圓。洋樓為三榻受形式，融合南洋與閩南風格：一樓橫樑有英文「團結就是力量」標語、印度人偶與舢舨船伕泥塑，檐口貼滿馬約利卡彩磁。民國38年後國軍進駐至民國70年代，之後長期閒置，民國102年電影《軍中樂園》曾在此取景。","highlights":["一樓橫樑英文標語與舢舨船伕、印度人偶泥塑","門楣「相國遺澤」與山頭稻穗、牡丹泥塑","圍牆兩側精美門樓與馬約利卡彩磁"],"funFact":"陳清吉在新加坡蓋的店屋與公寓被稱為「金門園」「金門路」，把家鄉的名字帶到了南洋。","photoSpot":"在門樓外拍洋樓山頭與雙獅","visitMin":15,"openNote":"位於金沙鎮碧山聚落。私人產權，建築嚴重受損，所有權人已在門樓張貼禁止擅入標示，請在圍牆外觀賞，勿進入。可開車或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，這棟洋樓的一樓橫樑上，有一句英文標語，意思是「團結就是力量」。"},{"who":"R","text":"古厝寫英文？Allan，這位主人一定很洋派！"},{"who":"A","text":"他叫陳清吉，11歲跟爸爸下南洋，在新加坡碼頭當舢舨苦力，後來創辦「和通」商號，成了僑界領袖。"},{"who":"R","text":"從碼頭苦力變成大老闆，好勵志喔！"},{"who":"A","text":"所以橫樑上還塑了舢舨船伕和印度人偶，紀念他靠舢舨起家。這棟洋樓花了大約銀四萬圓。"},{"who":"R","text":"四萬圓！其他洋樓不是幾千圓嗎？"},{"who":"A","text":"對，所以裝飾特別豪華，彩磁、雙獅、獎盃柱頭全都有。他在新加坡蓋的房子還叫「金門園」。"},{"who":"R","text":"把家鄉帶出國，好浪漫。那現在可以進去參觀嗎？"},{"who":"A","text":"建築損壞嚴重，屋主已經貼了禁止進入的告示，我們在圍牆外看。找找看門樓山頭上有沒有一條龍！"}],"clues":["我的一樓橫樑上有一句英文標語和舢舨船伕泥塑","我的主人在新加坡蓋了「金門園」，自己從碼頭苦力起家","碧山一棟花費銀四萬圓、拍過電影的豪華洋樓"],"quiz":[{"q":"陳清吉年輕時在新加坡最早從事什麼工作？","options":["教書先生","碼頭舢舨苦力","橡膠園技師","藥材行學徒"],"answer":1,"explain":"陳清吉初為新加坡碼頭舢舨業之苦力。"},{"q":"陳清吉在新加坡闢建的店屋與公寓被稱為什麼？","options":["浯江新村","碧山大樓","金門園","和通花園"],"answer":2,"explain":"他在實龍崗附近闢建店屋與公寓，稱為「金門園」「金門路」。"}],"images":[{"file":"陳清吉洋樓正面 (cropped).jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/56/%E9%99%B3%E6%B8%85%E5%90%89%E6%B4%8B%E6%A8%93%E6%AD%A3%E9%9D%A2_%28cropped%29.jpg/960px-%E9%99%B3%E6%B8%85%E5%90%89%E6%B4%8B%E6%A8%93%E6%AD%A3%E9%9D%A2_%28cropped%29.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%99%B3%E6%B8%85%E5%90%89%E6%B4%8B%E6%A8%93%E6%AD%A3%E9%9D%A2_(cropped).jpg","artist":"李家宇","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinsha-chenqingjiyanglou-0.webp","small":"img/jinsha-chenqingjiyanglou-0-s.webp"}]},{"id":"jincheng-huangtingzhouchong","name":"黃廷宙銃樓","short":"黃廷宙銃樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.40981,"lng":118.2992,"address":"金門縣金城鎮前水頭32、34號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000037","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-28/50cbdb99-98e8-43a1-9ca3-237a89083eab/1 封面.jpg","year":1934,"yearText":"1934年（民國23年）興建，1935年落成","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"遭盜匪洗劫後蓋起的防禦銃樓","intro":"黃廷宙銃樓位於金城鎮水頭聚落。黃廷宙生於1871年，綽號「黑面宙」，早年到印尼三馬林達投靠鄉人的公司做工，升任工頭，後轉往因石油開採而繁榮的麻里巴板，創立「中和合記」商號，經營糖、油、米等買賣致富。1933年他返鄉慶壽時，家中遭五十多名假扮軍人的盜匪持械搶劫，家屬被綁架。隔年他在清乾隆年間的二落大厝右側興建番仔厝，右前房加建約9公尺高的銃樓，設鐵板窗、鐵柵門與多達27處槍眼，1935年落成。2004年由金門國家公園修復，之後作為民宿使用。","highlights":["高約9公尺、頂部有垛口與槍眼的銃樓","門額九疊篆「金玉滿堂」洗石子浮雕","竹節造型檐口線腳與鯉魚、佛手排水口"],"funFact":"銃樓窗戶內設鐵板門，每扇有5處活動式槍口，外面看不進來，裡面卻能觀察動靜。","photoSpot":"從巷口仰拍銃樓垛口與番仔厝立面","visitMin":20,"openNote":"位於金城鎮水頭聚落。番仔厝修復後作為民宿使用，二落大厝仍有人居住；私人住宅，請在外觀參觀，勿擅入、勿打擾住戶與住客。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"水頭的天際線上，有一座特別高的塔樓，那就是黃廷宙銃樓，高約9公尺。"},{"who":"R","text":"為什麼住家要蓋那麼高的塔？是要看風景嗎？"},{"who":"A","text":"是為了防盜。1933年黃廷宙回鄉慶壽，家裡遭五十多名假扮軍人的盜匪搶劫，還有家屬被綁走。"},{"who":"R","text":"好可怕！難怪要蓋銃樓保護家人。"},{"who":"A","text":"是啊，隔年他就在乾隆年間的老大厝旁蓋番仔厝和銃樓，設了27處槍眼和鐵板窗。"},{"who":"R","text":"黃廷宙當年是怎麼在南洋發財的呢？"},{"who":"A","text":"他綽號黑面宙，在印尼從做工升到工頭，後來在麻里巴板開商號，賣糖、油、米，人稱半山富。"},{"who":"R","text":"黑面宙這個綽號，聽起來很有個性！"},{"who":"A","text":"門額還有九疊篆寫的「金玉滿堂」，筆畫彎來彎去像麵線。請在屋外試著認出「滿」字在哪裡！"}],"clues":["我的主人綽號黑面宙，在印尼經營糖、油、米致富","我高約9公尺，設有27處槍眼防範盜匪","我在水頭聚落，是番仔厝旁加建的防禦塔樓"],"quiz":[{"q":"黃廷宙興建銃樓的主要原因是？","options":["砲戰期間防空避難","監看海上往來漁船","當作眺望海景的涼亭","家中曾遭盜匪持械搶劫"],"answer":3,"explain":"1933年家中遭盜匪搶劫，隔年興建附銃樓的番仔厝防衛。"},{"q":"番仔厝門額「金玉滿堂」用什麼字體？","options":["隸書","九疊篆","草書","瘦金體"],"answer":1,"explain":"門額為九疊篆字體，以蠣殼灰洗石子浮雕泥塑書寫。"}],"images":[]},{"id":"jincheng-huangyongqianhuang","name":"黃永遷、黃永鑿兄弟洋樓","short":"黃永遷兄弟洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.409527,"lng":118.298656,"address":"金門縣金城鎮水頭42號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000046","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-28/e458c879-b701-4d9c-9999-e0bd3acc8471/黃永遷、黃永鑿兄弟洋樓.jpg","year":1934,"yearText":"1934至1935年（民國23至24年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"兄弟同心在印尼打拚蓋起的二層洋樓","intro":"黃永遷、黃永鑿兄弟洋樓位於金城鎮水頭聚落，原址為二落大厝加前二櫸頭。兄弟倆渡海到印尼巴厘吧板經商致富後，在1934至1935年興建這棟洋樓，之後交由弟弟黃永甫管理，現由其後代代管。建築分前棟二層洋樓與右後側一層附屬建築，前埕以牆規樓環繞，入口在左側。洋樓屋頂為傳統龜殼式，山頭近似三葉形，中央以深藍色寫「紫雲衍派」，兩旁有星芒與捲草；四柱三間的前廊柱身以蠣殼灰洗石子作幾何造型，一樓柱頭有天使泥塑，二樓門額寫著「福祿壽囍」。","highlights":["淡藍底色山頭與深藍「紫雲衍派」堂號","一樓前廊柱頭兩側的天使泥塑","左側雙峰形山頭的牆規樓入口"],"funFact":"洋樓牆面是淡紅色，屋頂卻是傳統紅瓦龜殼式，西式山頭配閩南屋頂，中西合璧。","photoSpot":"從牆規樓外拍二層洋樓與前廊","visitMin":15,"openNote":"位於金城鎮水頭聚落，官方資料記載每日8:30至17:00開放參觀，實際開放情形以現場公告為準；周邊多為私人住宅，請勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"A","text":"俗話說兄弟同心，其利斷金。在水頭，兄弟同心還能蓋出一棟洋樓！"},{"who":"R","text":"什麼意思？是兩兄弟一起蓋的嗎？"},{"who":"A","text":"對，黃永遷和黃永鑿兩兄弟到印尼巴厘吧板做生意，賺了錢，1934年回來蓋這棟二層洋樓。"},{"who":"R","text":"那這棟洋樓蓋好之後由誰來管理呢？"},{"who":"A","text":"交給弟弟黃永甫管理，現在由他的子孫代管，等於三兄弟都出了一份力。"},{"who":"R","text":"這棟的屋頂跟其他洋樓好像不太一樣？"},{"who":"A","text":"屋頂是傳統紅瓦的龜殼式，下面卻是西式山頭和天使泥塑，就像燒餅夾火腿，中西合璧。"},{"who":"R","text":"你連形容建築都要用吃的，不過我懂了！那二樓有什麼特別的嗎？"},{"who":"A","text":"二樓前廊的門額寫著「福祿壽囍」四個字，福氣、官祿、長壽、喜事一次全包。"},{"who":"A","text":"一樓前廊中間柱頭兩邊都有天使，請你找找看，一共有幾個小天使在守門！"}],"clues":["我由兩兄弟在印尼經商致富後興建，後來交給么弟管理","我的二樓門額寫著福祿壽囍","我是水頭聚落的二層洋樓，屋頂是龜殼式"],"quiz":[{"q":"這棟洋樓興建後交由誰管理？","options":["大哥黃永遷","二哥黃永鑿","金門縣政府","弟弟黃永甫"],"answer":3,"explain":"興建後交由弟弟黃永甫管理，現由其子孫代管。"},{"q":"二樓前廊門額寫的是哪四個字？","options":["金玉滿堂","福祿壽囍","江夏流芳","燕翼詒謀"],"answer":1,"explain":"二層前廊門額書有福祿壽囍。"}],"images":[{"file":"風獅爺文物坊 Wind Lion God Workshop - panoramio.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/75/%E9%A2%A8%E7%8D%85%E7%88%BA%E6%96%87%E7%89%A9%E5%9D%8A_Wind_Lion_God_Workshop_-_panoramio.jpg/960px-%E9%A2%A8%E7%8D%85%E7%88%BA%E6%96%87%E7%89%A9%E5%9D%8A_Wind_Lion_God_Workshop_-_panoramio.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%A2%A8%E7%8D%85%E7%88%BA%E6%96%87%E7%89%A9%E5%9D%8A_Wind_Lion_God_Workshop_-_panoramio.jpg","artist":"lienyuan lee","license":"CC BY 3.0","licenseUrl":"https://creativecommons.org/licenses/by/3.0","local":"img/jincheng-huangyongqianhuang-0.webp","small":"img/jincheng-huangyongqianhuang-0-s.webp"}]},{"id":"jinsha-wangrenjiwangren","name":"王仁吉、王仁乾、王仁忠兄弟洋樓","short":"王氏兄弟洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48139,"lng":118.39432,"address":"金門縣金沙鎮后宅1號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000014","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-20/bc9b4eb6-368f-4870-8e54-b1798f8a1d10/01封面.jpg","year":1934,"yearText":"1931–1934年（民國20至23年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"三兄弟出錢、監工、當小工合力蓋成的洋樓","intro":"王仁吉、王仁乾、王仁忠兄弟洋樓位於金沙鎮后宅聚落。大哥王仁吉在印尼從小販做起，經營貿易致富後匯款回鄉；二弟王仁乾負責監工並自燒白灰，三弟王仁忠當小工，延請廈門鼓浪嶼匠師設計，民國20年（1931）動工，歷時3年於民國23年完工，花費3000多元現大洋。日軍占領時期洋樓被日軍占用，民國38年後國軍進駐，牆上留下許多掛槍、掛蚊帳的釘孔，原本山頭上的大時鐘也不知去向。正面為出龜洋樓，鑰匙孔般的三葉形山頭下飾有「太原衍派」，民國106年（2017）完成整體修復。","highlights":["輪廓像鑰匙孔的三葉形山頭與「太原衍派」","大門旁松鶴、竹鹿兩幅油畫","一樓洋蔥形窗楣與十字紋、龜背紋洗石子"],"funFact":"當年經費吃緊，後裙房沒錢開挖地基，結果後裙房反而比前面的洋樓高出一截，現在還看得出來。","photoSpot":"在圍牆外正面拍鑰匙孔形山頭","visitMin":15,"openNote":"位於金沙鎮后宅聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的屋頂上面有個洞，形狀好像鑰匙孔喔！"},{"who":"A","text":"眼尖！那是三葉形山頭的鏤空，下面還寫著「太原衍派」，是王姓的堂號。"},{"who":"R","text":"Allan，聽說這棟洋樓是三兄弟一起蓋的？"},{"who":"A","text":"對，大哥王仁吉在印尼打拚出錢，二哥王仁乾監工還自己燒白灰，小弟王仁忠就當小工搬磚。"},{"who":"R","text":"一個出錢、一個出力、一個出汗，分工超明確！"},{"who":"A","text":"可是錢還是不太夠，後面的裙房沒預算挖地基，結果蓋得比前面的洋樓還高，現在都看得出來。"},{"who":"R","text":"哈哈，後面的房間反而站得比較高，像在偷看前面耶！"},{"who":"A","text":"這裡日軍占領時期被占用，後來國軍也進駐過，連山頭上的大時鐘都不見了。屋主還住著，我們在外面看就好。"},{"who":"R","text":"了解！那我去找大門兩邊的油畫，看哪一幅畫的是仙鶴，哪一幅是鹿！"}],"clues":["我的山頭鏤空像一個鑰匙孔","我的後裙房因為沒錢挖地基，反而比前棟還高","后宅三兄弟分工出錢、監工、當小工蓋成的洋樓"],"quiz":[{"q":"三兄弟中，負責監工並自己燒白灰的是誰？","options":["大哥王仁吉","三弟王仁忠","鼓浪嶼匠師","二弟王仁乾"],"answer":3,"explain":"二弟王仁乾監工、自燒白灰，三弟王仁忠充當小工。"},{"q":"為什麼後裙房的地基比前面洋樓還高？","options":["為了防颱","沒有預算開挖地基","風水師的建議","地下有岩盤"],"answer":1,"explain":"籌建經費辛苦，後裙房沒有預算開挖地基而偏高。"}],"images":[]},{"id":"jincheng-xueqingjiangzhai","name":"薛清江宅","short":"薛清江宅","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41184,"lng":118.33633,"address":"金門縣金城鎮泗湖24號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000023","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-28/c62e71fc-cc50-4a0b-87af-f228f5a711b1/01封面.jpg","year":1935,"yearText":"1935年（民國24年）","era":"japan","themes":["閩南古厝"],"yearUnknown":false,"summary":"白石板配紅磚的大厝，門前守著泗湖最老的井","intro":"薛清江宅位於金城鎮泗湖聚落，是1935年興建的二落大厝。建築本體上堵為紅磚斗仔砌，下堵為花崗石人字砌，正面壁堵則鋪泉州白石板，從格扇小木作到地坪鋪面都展現富裕氣勢。前後落中脊留有太極八卦彩繪，水車堵以交趾陶人物故事裝飾，其中一冊書卷封面寫著「中華民國歲次戊辰重修」，推測曾於1988年修建。建築後側牆面鑲有石敢當鎮煞。前埕的水井是泗湖聚落最古老的井「龍水井」。目前木構件遭白蟻大面積蛀蝕，亟需處理。","highlights":["前埕泗湖最古老的水井「龍水井」","水車堵交趾陶裡寫著「戊辰重修」的書卷","屋後牆面鑲嵌的石敢當"],"funFact":"工匠把修建年份藏在交趾陶書卷的封面上，「戊辰」推測就是1988年。","photoSpot":"在前埕拍龍水井與大厝正面","visitMin":10,"openNote":"位於金城鎮泗湖聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，來泗湖別急著看房子，先看門口這口井，它叫龍水井，是泗湖最古老的井。"},{"who":"R","text":"龍水井？聽起來打上來的水會噴火耶！"},{"who":"A","text":"噴火就不用煮麵線了。這口井守著的是薛清江宅，一棟1935年興建的二落大厝。"},{"who":"R","text":"它的牆面怎麼白白紅紅的，像草莓牛奶？"},{"who":"A","text":"正面壁堵鋪的是泉州白石板，上面配紅磚斗仔砌，下面是花崗石人字砌，很講究。"},{"who":"R","text":"那屋頂上那個圖案是太極八卦嗎？"},{"who":"A","text":"對，前後落中脊都有太極八卦彩繪。屋後牆上還鑲了一塊石敢當，用來鎮煞。"},{"who":"R","text":"前有古井、上有八卦、後有石敢當，防護罩開好開滿！"},{"who":"A","text":"請你在屋外仔細看水車堵的交趾陶，找出那本寫著「戊辰重修」的小書卷！"}],"clues":["我的交趾陶書卷上寫著「中華民國歲次戊辰重修」","我屋後牆面鑲著石敢當，中脊有太極八卦彩繪","我是泗湖的二落大厝，門前有聚落最古老的龍水井"],"quiz":[{"q":"薛清江宅前埕的水井叫什麼名字？","options":["金水井","虎泉井","大潭井","龍水井"],"answer":3,"explain":"前埕水井為泗湖聚落最古老井「龍水井」。"},{"q":"屋後牆面鑲嵌的石敢當有什麼作用？","options":["鎮煞","排水","記錄年份","標示地界"],"answer":0,"explain":"建築後側牆面鑲有石敢當鎮煞。"}],"images":[]},{"id":"jincheng-huangrujifanzaicuo","name":"黃汝楫番仔厝","short":"黃汝楫番仔厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41135,"lng":118.2976,"address":"金門縣金城鎮前水頭74號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000048","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/bd49e24e-07f2-4b98-a869-e59e07852749/黃汝楫番仔厝01.png","year":1935,"yearText":"1935至1937年（民國24至26年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"曾作村里辦公室的大九架番仔厝","intro":"黃汝楫番仔厝位於金城鎮水頭聚落，黃汝楫在印尼峇厘吧板經商致富後，於1935至1937年返鄉興建。完工不久即遇日軍占領金門，黃家前往印尼居住；據耆老口述，1960年代末印尼排華時，家族輾轉遷居香港。戰地政務時期，這裡曾作為水頭村的村里辦公室，現仍有後人居住。建築為大九架番仔厝，前有牆規樓圍出前埕；正面山頭中央為半圓形裝飾，下方是「紫雲衍派」堂號，左右柱頭有天使泥塑，山頭下方吐水作剪黏雙龍，榻受立柱以磨石子飾面，柱身有五個圓框花草裝飾。","highlights":["山頭下方剪黏雙龍造型的吐水","榻受立柱上五個圓框的花草裝飾","側面窗楣的人物與走獸泥塑"],"funFact":"完工不久就遇上日軍占領金門，屋主一家前往印尼；戰地政務時期這裡還當過村辦公室。","photoSpot":"在牆規樓外拍半圓形山頭與天使柱頭","visitMin":15,"openNote":"位於金城鎮水頭聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這棟番仔厝屋頂下的排水口，怎麼是兩條龍？"},{"who":"A","text":"那叫吐水，用剪黏做成雙龍，下雨時就像雙龍吐水，很有氣勢吧！"},{"who":"R","text":"好酷！那這棟番仔厝是誰蓋的呢？"},{"who":"A","text":"黃汝楫在印尼峇厘吧板經商致富，1935年開始回鄉興建，大約兩年才完成。"},{"who":"R","text":"房子蓋好後，他就在這裡住下來了嗎？"},{"who":"A","text":"可惜完工不久，日軍就占領金門，黃家只好前往印尼。據耆老口述，後來家族又輾轉遷居香港。"},{"who":"R","text":"房子好不容易蓋好，主人卻要離開，好讓人心疼。"},{"who":"A","text":"正面山頭也很講究，中央是半圓形裝飾，左右柱頭各站著一尊天使泥塑。"},{"who":"A","text":"是啊。戰地政務時期這裡當過村辦公室，現在仍有後人居住。請在屋外找找側面窗楣，泥塑裡藏了哪些人物和走獸！"}],"clues":["我完工不久就遇上日軍占領，主人一家前往印尼","戰地政務時期我曾是水頭村的村里辦公室","我是水頭的大九架番仔厝，吐水是剪黏雙龍"],"quiz":[{"q":"戰地政務時期這棟番仔厝曾作什麼用途？","options":["軍醫院","小學教室","村里辦公室","郵政代辦所"],"answer":2,"explain":"戰地政務時期，此宅曾為水頭村之村里辦公室。"},{"q":"山頭下方的吐水是什麼造型？","options":["剪黏雙龍","鯉魚","獅頭","鳳凰"],"answer":0,"explain":"山頭下方吐水作剪黏雙龍造型。"}],"images":[]},{"id":"jinsha-zhangwendiyanglou","name":"張文帝洋樓","short":"張文帝洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.49096,"lng":118.41375,"address":"金門縣金沙鎮沙美200號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000019","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-08-16/6ad48f3e-9a99-417d-a7ec-f196ef8077f5/張文帝洋_代表圖像.jpg","year":1935,"yearText":"1935年（民國24年）","era":"japan","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"動物排水孔可愛、見證戰火的沙美洋樓","intro":"張文帝洋樓位於金沙鎮沙美聚落。創建人張文帝（1897–1987）隨父親到馬來西亞創立商號「瑞祥」致富，民國22年（1933）返鄉親自監工，為父母興建洋樓，民國24年（1935）落成，橫樑還刻著「1935」。因時局動盪，父母與他本人都沒有回來住。民國26年（1937）日軍占領金門，看上這處制高點設指揮所；戰後國軍進駐，曾設鼠疫防治處，民國47至78年為沙美憲兵隊駐地。民國105年（2016）捐贈縣府，民國111年（2022）修復完成。山頭有鏤空仙桃與老鷹泥塑，排水孔做成兔子、鯉魚、蟾蜍、烏龜。","highlights":["兔子、鯉魚、蟾蜍、烏龜造型的泥塑排水孔","山頭鏤空仙桃、展翅老鷹與鴿子泥塑","二樓後房外突的角樓與槍孔"],"funFact":"二樓祖廳上方做了「暗厝」，在屋頂下再做一面屋坡，形成屋中屋的特殊空間。","photoSpot":"在前埕拍出龜外廊與山頭全景","visitMin":30,"openNote":"位於金沙鎮沙美聚落，已由縣府修復開放。官方資料：每日上午9時至下午5時（除夕休館），夜間照明至晚上9時；圖書館週一休館。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"R","text":"Allan，這棟洋樓的排水孔居然是小動物！有兔子、有鯉魚，還有烏龜！"},{"who":"A","text":"還有一隻蟾蜍喔！雨一下，牠們就一起吐水，像在表演噴水秀。"},{"who":"R","text":"是誰這麼有童心，把排水孔做成動物園？"},{"who":"A","text":"屋主張文帝在馬來西亞經商，民國22年回來親自監工，民國24年蓋好，要給爸媽養老。"},{"who":"R","text":"好孝順！那爸媽住進來以後，一定很開心吧？"},{"who":"A","text":"可惜時局動盪，他們都沒能回來住。民國26年日軍占領金門，看上這裡是制高點，在這裡設了指揮所。"},{"who":"R","text":"一棟孝心滿滿的房子，卻先被拿去當軍事據點，好讓人感慨。"},{"who":"A","text":"戰後國軍也進駐過，當過憲兵隊駐地，2022年才由縣府修復完成。現在白天開放，可以入內參觀。"},{"who":"R","text":"那我先在門口，把四種動物排水孔都找齊拍下來！"}],"clues":["我的橫樑上刻著「1935」","我的排水孔有兔子、鯉魚、蟾蜍和烏龜","沙美的出龜洋樓，主人在馬來西亞經商"],"quiz":[{"q":"洋樓落成後，最早進駐設指揮所的是？","options":["國軍憲兵隊","日軍","民防自衛隊","蛙人部隊"],"answer":1,"explain":"民國26年日軍占領金門，進駐洋樓設置指揮所。"},{"q":"下面哪一種不是洋樓排水孔的動物造型？","options":["兔子","蟾蜍","烏龜","老虎"],"answer":3,"explain":"排水孔有兔子、鯉魚、蟾蜍及烏龜造型。"}],"images":[]},{"id":"jinsha-likangtayanglou","name":"李康塔洋樓","short":"李康塔洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.51909,"lng":118.41316,"address":"金門縣金沙鎮官澳段1082地號","announced":"2006-11-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20061109000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-23/4fa7a497-97f3-46fe-925e-0604f8ade07a/李康塔洋樓.jpg","year":1935,"yearText":"年代不詳","era":"unknown","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":true,"summary":"壽屏留著主人奮鬥自序的官澳洋樓","intro":"李康塔洋樓位於金沙鎮官澳聚落。李康塔十餘歲就和弟弟李建修到新加坡打拚，從打零工做起，升任南北貨批發公司掌櫃，後來在老闆支持下自立「恆通」公司。他委託弟弟帶數千白銀返鄉興建此樓，並在二樓正廳壽屏寫下自序，回顧遠渡重洋、傭工覓食的艱辛，勉勵後輩創業維艱，但他本人從未住過。民國36至47年曾作為陸軍營部指揮中心與官眷住所，入口仍留「中山室」字樣；八二三砲戰時，附近30多位居民在此避難。洋樓為五腳基洋樓帶前落與後裙房，前落飾馬約利卡磁磚。官方未載明興建年代。","highlights":["二樓壽屏上李康塔的奮鬥自序","入口門額上隱約可見的「中山室」字樣","象、龜、魚、葫蘆造型的落水口"],"funFact":"民國100到101年官澳龍鳳宮整修時，這棟洋樓曾作為龍鳳宮的臨時場所，供信徒參拜。","photoSpot":"在前埕外拍前落馬約利卡磁磚立面","visitMin":15,"openNote":"位於金沙鎮官澳聚落，鄰近官澳龍鳳宮。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，聽說這棟洋樓的主人寫了一篇作文，放在家裡？"},{"who":"A","text":"那是自序啦！李康塔十幾歲就到新加坡打零工，後來當上掌櫃，再自己開了恆通公司。"},{"who":"R","text":"從打工仔變老闆，根本是勵志電影！"},{"who":"A","text":"他請弟弟帶著數千白銀回官澳蓋樓，還在二樓壽屏寫下自己的奮鬥過程，要後輩記得創業不容易。"},{"who":"R","text":"蓋了這麼漂亮的樓，那他住在這裡一定很開心吧？"},{"who":"A","text":"說來可惜，他本人從沒住過。後來國軍進駐，這裡當過營部指揮中心，入口還留著中山室三個字。"},{"who":"R","text":"那八二三砲戰的時候，這裡發生了什麼事？"},{"who":"A","text":"洋樓蓋得比一般民宅堅固，砲戰時附近30多位居民躲在這裡避難。這是私人住宅，請在外面參觀。"},{"who":"R","text":"好暖心的房子。那我繞到側面，找找落水口有沒有大象或烏龜的造型！"}],"clues":["我的主人在新加坡從打零工做到開公司","我的二樓壽屏上寫著主人的奮鬥自序","官澳聚落裡，主人從沒住過的五腳基洋樓"],"quiz":[{"q":"李康塔在新加坡創立的公司叫什麼？","options":["恆通","瑞祥","復興","義發"],"answer":0,"explain":"李康塔在老闆支持下開設「恆通」公司。"},{"q":"八二三砲戰時，這棟洋樓曾作為什麼用途？","options":["鼠疫防治處","小學教室","雜貨店","居民臨時避難所"],"answer":3,"explain":"洋樓較堅固，砲戰時附近居民約30餘人在此避難。"}],"images":[]},{"id":"jincheng-shuitoudihaoyang2","name":"水頭57 地號洋樓（僑鄉文化展示）","short":"水頭57地號洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.409663,"lng":118.29891,"address":"金門縣金城鎮前水頭39號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000051","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-08-28/d03c6796-8d23-4585-a4f2-f44d49f5fd59/DSC_6732-1.jpg","year":1936,"yearText":"1936年（民國25年）改建左護龍洋樓","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"古厝加洋樓的組合，現為僑鄉文化展示館","intro":"水頭57地號洋樓位於金城鎮水頭聚落，為黃俊所建，門額堂號「紫雲衍派」。它原屬黃氏酉堂祖產，後來子孫黃仲衷染上吸食鴉片惡習，以一萬三千元典賣，買主是黃廷瓢。建築為一落二櫸頭加左護龍，左護龍原是傳統閩南式，倒塌後於1936年改建為洋樓疊樓。1990年代遭火災，木結構幾乎全毀，2001年由金門國家公園管理處整體修建，現為「僑鄉文化展示館」，介紹金門人僑居南洋的建築與生活文化。疊樓山頭的石獅與洗牡蠣殼灰牆面是視覺焦點。","highlights":["疊樓山頭望柱上的一對石獅與鳥禽花卉泥塑","洗牡蠣殼灰的二樓外牆與華麗窗楣","屋頂吐水口的鰲魚、豬造型"],"funFact":"左櫸頭牆上用藍色筆意寫著「精誠」二字，推測是戰地政務時期留下的精神標語。","photoSpot":"在前埕拍閩南古厝與左側洋樓同框","visitMin":30,"openNote":"位於金城鎮水頭聚落，由金門國家公園管理處作為開放展示館，官方資料記載每日08:30至17:00開放，每日固定解說6場次。可搭金門縣公車到水頭，或從水頭碼頭步行前往。","dialogue":[{"who":"A","text":"來到水頭57地號洋樓，這裡現在是僑鄉文化展示館，想認識落番故事來這裡就對了。"},{"who":"R","text":"落番？是指不小心掉進番茄醬裡嗎？"},{"who":"A","text":"哈，是閩南話說出洋到南洋打拚啦。這棟原本是黃氏酉堂的祖產，背後還有一段家族故事。"},{"who":"R","text":"什麼故事？聽起來有點八點檔的味道。"},{"who":"A","text":"子孫黃仲衷染上吸鴉片的惡習，以一萬三千元把祖產典賣，買下的人是黃廷瓢。"},{"who":"R","text":"唉，壞習慣真的會把家產吃掉，比你吃燒餅還快。"},{"who":"A","text":"左護龍倒塌後，1936年改建成洋樓，後來又遭火災，2001年由金門國家公園管理處修好。"},{"who":"R","text":"所以它是古厝和洋樓的合體，像機器人一樣可以組合！"},{"who":"A","text":"沒錯。進去前先抬頭看洋樓山頭，數數看上面蹲著幾隻石獅，再去聽一場解說吧！"}],"clues":["我原屬一座知名書院別業的祖產，後來被典賣","我的左護龍在1936年改建成洋樓疊樓","我在水頭，現在是僑鄉文化展示館"],"quiz":[{"q":"這棟洋樓現在作為什麼用途？","options":["貢糖展售中心","戰史館","遊客住宿","僑鄉文化展示館"],"answer":3,"explain":"由金管處作為僑鄉文化展示館開放。"},{"q":"這棟建築的左護龍在哪一年改建為洋樓？","options":["1916年","1936年","1958年","2001年"],"answer":1,"explain":"左護龍倒塌後於1936年改建為洋樓。"}],"images":[]},{"id":"jincheng-zhengwenzhoufanzai","name":"鄭文周番仔厝","short":"鄭文周番仔厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41237,"lng":118.29656,"address":"金門縣金城鎮水頭143號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000049","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-10-24/93cf1eab-b576-4d09-b112-6319fa93d93b/鄭文周番仔厝_封面.png","year":1936,"yearText":"1936年（民國25年）改建","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"四櫸頭老厝翻建成番仔厝，山頭有三對雙獅","intro":"鄭文周番仔厝位於金城鎮水頭聚落，原為一落四櫸頭格局，1936年由鄭家購得。鄭家兄弟水湘、再法、水泮在印尼泗水經營土產與海運，發跡後匯錢返鄉，由父親鄭文周購買並將主屋翻建為番仔厝，形成大九架番仔厝加前四櫸頭及牆規的格局。洋樓正面山頭以半圓收頭，共有三對雙獅戲球，望柱上有獎盃泥塑；榻受附壁柱書有「福如東海」「壽比南山」，門額為鄭氏堂號「滎陽衍派」。側面山牆圓形氣窗內嵌五角星。完成此屋的匠師，隨後被請到後豐港建造洪克保番仔厝。","highlights":["半圓山頭上的三對雙獅戲球泥塑","附壁柱上的「福如東海」「壽比南山」","側面山牆內嵌五角星的圓形氣窗"],"funFact":"完成這棟的匠師隨後被請到後豐港，蓋出形制相同的洪克保番仔厝。","photoSpot":"在牆規樓外拍山頭三對雙獅","visitMin":10,"openNote":"位於金城鎮水頭聚落，私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可搭金門縣公車到水頭。","dialogue":[{"who":"A","text":"阿拉蕾，考考你，一個山頭上可以放幾隻獅子？"},{"who":"R","text":"兩隻吧？一左一右守門，再多就要吵架了。"},{"who":"A","text":"這棟鄭文周番仔厝的山頭，一口氣放了三對雙獅戲球，整整六隻，熱鬧得像舞獅大會。"},{"who":"R","text":"六隻獅子！屋主是不是很喜歡獅子？"},{"who":"A","text":"這倒沒有紀錄。我們知道的是，鄭家兄弟在印尼泗水做土產和海運，1936年匯錢回來，由爸爸鄭文周買下老厝翻建。"},{"who":"R","text":"所以原本是傳統古厝，後來才變身成番仔厝。"},{"who":"A","text":"對，前面保留四櫸頭，主屋改成大九架番仔厝。蓋完這棟，同一批匠師又被請去後豐港蓋另一棟。"},{"who":"R","text":"這批師傅好搶手，簡直是當年的建築明星團隊！"},{"who":"A","text":"吃完燒餅再上路吧。請你在屋外抬頭，親自數一數山頭上是不是真的有六隻獅子！"}],"clues":["我的半圓山頭上有三對雙獅戲球","我原是一落四櫸頭，1936年主屋翻建成番仔厝","我在水頭，門額寫著「滎陽衍派」，由泗水兄弟匯錢翻建"],"quiz":[{"q":"鄭家兄弟在哪裡經營土產與海運？","options":["新加坡","菲律賓","印尼泗水","緬甸仰光"],"answer":2,"explain":"兄弟水湘、再法、水泮在印尼泗水經商。"},{"q":"鄭文周番仔厝的正面山頭共有幾對雙獅戲球？","options":["三對","一對","兩對","四對"],"answer":0,"explain":"山頭上共有三對雙獅戲球。"}],"images":[]},{"id":"jinning-wengdeyansangai","name":"翁德晏三蓋廊厝","short":"翁德晏三蓋廊","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.44765,"lng":118.33989,"address":"金門縣金寧鄉盤山村頂堡40號","announced":"2007-10-09","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071009000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-10-13/d6ab0591-cc9c-4176-b5e9-cbd58fe97b12/01.jpg","year":1936,"yearText":"1936年（民國25年）","era":"japan","themes":["閩南古厝","僑鄉洋樓"],"yearUnknown":false,"summary":"勿里洞僑商的三蓋廊厝，彩磁上有南洋人像","intro":"翁德晏三蓋廊厝位於金寧鄉盤山村頂堡。翁德晏（1897～1959）清宣統2年（1910）13歲時下南洋到印尼勿里洞，從打漁、賣魚做起，後來創立協德號，販售糖、米、花生等生活用品與土產，也代理茶葉。1934年他返鄉，以龍銀二百大員向堂兄購得建地，1936年完成這座大厝，也出資讓後厝支派歷代先祖在翁氏大宗祠晉主。建築為三蓋廊形式，以牆規樓圍出前院，院內有古井；前落在磚坪上再疊雙坡屋面，作法特殊。立面大量使用彩磁，其中有南洋人像圖樣。日軍占領期間古厝曾被占用，燕尾遭當作單槓使用而斷裂，2021年申請獎助進行整體修復。","highlights":["立面彩磁中少見的南洋人像圖樣","前落在磚坪上再疊雙坡屋面的特殊屋頂","門額「六桂傳芳」與院內古井"],"funFact":"日軍占領金門期間，士兵曾拿古厝的燕尾吊單槓，結果把燕尾弄斷了。","photoSpot":"在牆規樓外拍花瓶欄杆與彩磁立面","visitMin":15,"openNote":"位於金寧鄉盤山村頂堡。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這棟古厝的磁磚上好像有人臉耶！是在看我們嗎？"},{"who":"A","text":"眼力真好，那是南洋人像圖樣的彩磁，在金門很少見。主人翁德晏13歲就到印尼勿里洞打拚。"},{"who":"R","text":"13歲就出國工作？我13歲還在煩惱午餐要吃什麼。"},{"who":"A","text":"他從打漁賣魚開始，後來開了協德號，賣糖、米、花生，還當茶葉公司的代理商。"},{"who":"R","text":"從賣魚變老闆，這是金門版的白手起家！"},{"who":"A","text":"1934年他回鄉，用龍銀二百大員向堂兄買地，1936年完成這座三蓋廊厝。"},{"who":"R","text":"咦，那屋頂的燕尾怎麼看起來好像修過？"},{"who":"A","text":"日軍占領期間，古厝被占用，士兵還拿燕尾吊單槓，把燕尾弄斷了。燕尾可不是健身器材啊。"},{"who":"A","text":"請你在立面找一找，那位南洋人像在哪一塊彩磁上？順便看看門額寫的是哪四個字。"}],"clues":["我的主人13歲到印尼勿里洞，從賣魚做到開商號","我的燕尾曾被拿來吊單槓而斷裂","我在盤山頂堡，是三蓋廊形式，彩磁上有南洋人像"],"quiz":[{"q":"翁德晏13歲時到哪裡發展？","options":["印尼勿里洞","新加坡","菲律賓衣里岸","馬來西亞彭亨"],"answer":0,"explain":"清宣統2年翁德晏13歲時下南洋到印尼勿里洞。"},{"q":"這座古厝的立面彩磁有什麼特別圖樣？","options":["西洋帆船","南洋人像","鳳凰牡丹","八仙過海"],"answer":1,"explain":"頂堵、身堵與對看堵的彩磁中有南洋人像圖樣，十分特殊。"}],"images":[]},{"id":"jincheng-hongkebaofanzaicuo","name":"洪克保番仔厝","short":"洪克保番仔厝","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.41819,"lng":118.30124,"address":"金門縣金城鎮后豐港7 號","announced":"2003-12-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031222000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-05-22/8926eb0d-38df-4b9e-b729-34a2a2aadf95/01封面.jpg","year":1938,"yearText":"1938年（民國27年）","era":"japan","themes":["僑鄉洋樓","閩南古厝"],"yearUnknown":false,"summary":"後豐港唯一番仔厝，以水頭為師的華洋民宅","intro":"洪克保番仔厝位於金城鎮後豐港聚落，1938年由洪克保之子在新加坡經商後僑匯返鄉興建，是聚落裡唯一受近代外洋影響的民宅，俗稱「番仔厝」。它是在傳統承重牆上採「大九架」形制的單層華洋混合建築。因聚落裡沒有前例可參考，便以正值洋樓興建潮的水頭為師，甚至請來剛完成水頭鄭文周番仔厝的同一批匠師，因此兩者形制相同。1949至1950年間曾作村辦公室，也經營過海產餐廳，2012年依縣府私有歷史建築修復獎助辦法整體修復。","highlights":["曲線山頭的雙獅、獎盃柱頭與「燉煌衍派」堂號","山頭兩側相伴的天使泥塑","火焰型窗楣邊緣的靛藍色點綴"],"funFact":"它和水頭鄭文周番仔厝出自同一批匠師之手，可說是相隔不遠的「建築雙胞胎」。","photoSpot":"正面拍曲線山頭與兩側天使泥塑","visitMin":15,"openNote":"位於金城鎮後豐港聚落，目前作住宿使用，官方資料記載「無房客時開放」；其餘時間請在外觀參觀，勿擅入、勿打擾住客。可騎機車或開車前往，鄰近水頭。","dialogue":[{"who":"R","text":"Allan，番仔厝是什麼？聽起來有點像外國人住的房子。"},{"who":"A","text":"差不多，就是受到南洋和西洋影響的華洋混合民宅。這棟是後豐港唯一的一棟。"},{"who":"R","text":"唯一？那當年蓋的時候不就沒有範本可以抄？"},{"who":"A","text":"所以他們乾脆去隔壁的水頭取經，連匠師都請同一批，剛蓋完鄭文周番仔厝就被請來這裡。"},{"who":"R","text":"哇，這是建築界的跟團旅行，連導遊都一樣！"},{"who":"A","text":"1938年洪克保的兒子從新加坡匯錢回來興建，戰後還當過村辦公室，也開過海產餐廳。"},{"who":"R","text":"海產餐廳？那你一定很想念這裡的石蚵吧。"},{"who":"A","text":"被你看穿了。不過重點是正面山頭，有雙獅、獎盃，還有兩個小天使守著堂號，天使配獅子，中西合璧。"},{"who":"A","text":"請在屋外找找山頭下方的靛藍色字堂號，唸唸看寫的是什麼！"}],"clues":["我請來剛完工水頭某棟番仔厝的同一批匠師","我曾當過村辦公室，也經營過海產餐廳","我是後豐港唯一的華洋混合民宅，1938年興建"],"quiz":[{"q":"洪克保番仔厝的匠師之前剛完成哪一棟建築？","options":["得月樓","陳景蘭洋樓","莒光樓","鄭文周番仔厝"],"answer":3,"explain":"匠師完成水頭鄭文周番仔厝後被請來後豐港。"},{"q":"1949至1950年間這棟番仔厝曾作什麼使用？","options":["小學教室","郵局","軍醫院","村辦公室"],"answer":3,"explain":"官方資料記載曾作為村辦公室。"}],"images":[]},{"id":"jincheng-dongguangdeyanglou","name":"董光得洋樓","short":"董光得洋樓","category":"歷史建築","level":"","town":"金城鎮","types":["宅第"],"lat":24.4004,"lng":118.31379,"address":"金門縣金城鎮大古崗94號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000024","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-26/cb78ed20-d582-49cd-ad70-fc3a19ab286c/01封面.jpg","year":1938,"yearText":"1938年（民國27年）","era":"japan","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"會計一生積蓄蓋的洋樓，山頭寫著主人名字","intro":"董光得洋樓位於金城鎮大古崗聚落，創建於1938年，由曾任董允耀公司會計的董光得，將一生積蓄僑匯返鄉興建。平面為五腳基洋樓加後落，前廊與屋頂都有花瓶欄杆女兒牆。二樓外廊中間四柱為圓柱，柱身有花藤紋飾；大門上方有董氏堂號「玉箏流芳」匾額，山頭飾有董光得姓名的羅馬拼音、立體花卉泥塑與黨徽泥塑。屋內不同於一般五腳基的木質單梯，而是左右對稱的雙梯，相當氣派。後落山牆脊墜以雙旗與盾形勳章泥塑裝飾。可惜目前屋頂與二樓樓板崩塌，亟待修復。","highlights":["山頭上主人姓名的羅馬拼音與立體花卉泥塑","二樓外廊中央四根帶花藤紋飾的圓柱","側面山牆脊墜的老鷹泥塑"],"funFact":"一般五腳基洋樓用木質單梯，這棟卻是左右對稱的雙梯，到半途才合成一道木梯上二樓。","photoSpot":"在屋前安全距離外拍山頭與二樓圓柱","visitMin":10,"openNote":"位於金城鎮大古崗聚落，私人產業，請在外觀參觀，勿擅入；建築屋頂與樓板崩塌，請保持安全距離。可騎機車或開車前往。","dialogue":[{"who":"A","text":"阿拉蕾，如果你蓋一棟洋樓，會把自己的名字刻在哪裡？"},{"who":"R","text":"當然是最高的地方，讓全村都看到是我蓋的！"},{"who":"A","text":"董光得就是這麼做的。洋樓山頭上用羅馬拼音寫著他的名字，旁邊還有立體花卉泥塑。"},{"who":"R","text":"好有個性！他是很有錢的大老闆嗎？"},{"who":"A","text":"其實他是董允耀公司的會計，1938年把一生的積蓄寄回大古崗蓋了這棟洋樓。"},{"who":"R","text":"會計存錢最厲害了，難怪算得這麼精準，連樓梯都要左右對稱。"},{"who":"A","text":"沒錯，屋裡是罕見的對稱雙梯。可惜現在屋頂崩塌，我們只能在外面欣賞，千萬別進去。"},{"who":"R","text":"希望它早日修好，不然好浪費會計先生的一片心血。"},{"who":"A","text":"請你在安全距離外拍下山頭，數數看主人的名字用了幾個羅馬字母！"}],"clues":["我屋裡是罕見的左右對稱雙梯","我的山頭上用羅馬拼音寫著主人的名字","我在大古崗，是一位公司會計用一生積蓄蓋的洋樓"],"quiz":[{"q":"董光得在南洋的工作是什麼？","options":["碾米廠老闆","船頭行掌櫃","公司會計","橡膠園主"],"answer":2,"explain":"他曾擔任董允耀公司會計，以積蓄僑匯建樓。"},{"q":"董光得洋樓的室內樓梯有什麼特色？","options":["旋轉鐵梯","對稱雙梯","石砌樓梯","沒有樓梯"],"answer":1,"explain":"上樓處為對稱雙梯，再合併為木質單梯。"}],"images":[]},{"id":"jinning-huxiasanjianlouzai","name":"湖下三間樓仔","short":"湖下三間樓仔","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.45629,"lng":118.30454,"address":"金門縣金寧鄉湖浦村湖下44、44-1、45、46、46-8號","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000014","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-25/60193e31-6a44-45ac-91b7-3abfbe9d66e4/01封面.jpg","year":1946,"yearText":"約1946～1949年（民國35～38年）","era":"postwar","themes":["僑鄉洋樓","市場商業"],"yearUnknown":false,"summary":"三位合夥人一人一間的連棟五腳基洋樓","intro":"湖下三間樓仔位於金寧鄉湖浦村湖下聚落，是連成一排的三棟五腳基洋樓。1945年湖下的金和發公司經營油坊與商船運輸，由楊鴻禮、楊清淹與楊英舉三人合夥，往來福建漳州、石碼載運貨物，再從大陸運竹器與木頭回金門販售，致富後合建這排洋樓，三人各分一間。木材與石材都購自大陸，工人工資是每月領米12斤，總花費約500銀元，歷時三年多。1949年接近完工時青年軍進駐，八二三砲戰時中間那棟遭砲擊，樓梯與窗戶都曾修建；1970年代又在主屋後各增建一落。洋樓前有磚砌抹灰拱廊，其中兩棟拱廊上方分別寫著「清白世冑」與「宏農衍派」。","highlights":["三棟並排、磚砌抹灰的五腳基拱廊","拱廊上方「清白世冑」與「宏農衍派」字樣","二樓山牆的圓洞氣窗"],"funFact":"蓋這排洋樓時，工人的工資不是發錢，而是每個月領12斤米。","photoSpot":"退到路對面，把三棟拱廊一次入鏡","visitMin":10,"openNote":"位於金寧鄉湖浦村湖下聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，這三棟洋樓黏在一起，好像三個手牽手的好朋友！"},{"who":"A","text":"還真的是好朋友蓋的。楊鴻禮、楊清淹、楊英舉三人合夥開金和發公司，賺了錢一人分一間。"},{"who":"R","text":"合夥做生意還能不吵架，真不簡單！他們是做什麼的？"},{"who":"A","text":"經營油坊和商船，往來福建漳州、石碼之間，再把竹器和木頭運回金門賣。"},{"who":"R","text":"那時候蓋房子的工人，薪水很高嗎？"},{"who":"A","text":"當時工人每個月領的是12斤米，不是錢。要是用貢糖發薪水，我一定第一個報名。"},{"who":"R","text":"你這樣會被老闆吃垮啦！那房子後來還好嗎？"},{"who":"A","text":"1949年快完工時青年軍進駐，八二三砲戰時中間那棟被砲擊，樓梯和窗戶都修過。"},{"who":"A","text":"請你看拱廊上方，找出寫著「清白世冑」和「宏農衍派」的是哪兩棟？"}],"clues":["起造我們的三位合夥人經營油坊與商船運輸","蓋我們的工人每月領12斤米當工資","我們是湖下連在一起的三棟五腳基洋樓"],"quiz":[{"q":"興建三間樓仔的三位合夥人經營的是哪家公司？","options":["聯芳公司","協德號","和源號","金和發公司"],"answer":3,"explain":"三人共同經營金和發公司，從事油坊與商船運輸。"},{"q":"蓋三間樓仔時，工人的工資是用什麼支付？","options":["每月領米12斤","每天一塊銀元","每月一擔地瓜","每週兩斤花生"],"answer":0,"explain":"工人當時工資為月領米12斤。"}],"images":[{"file":"湖下三間樓仔.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/%E6%B9%96%E4%B8%8B%E4%B8%89%E9%96%93%E6%A8%93%E4%BB%94.jpg/960px-%E6%B9%96%E4%B8%8B%E4%B8%89%E9%96%93%E6%A8%93%E4%BB%94.jpg","page":"https://commons.wikimedia.org/wiki/File:%E6%B9%96%E4%B8%8B%E4%B8%89%E9%96%93%E6%A8%93%E4%BB%94.jpg","artist":"jeff~","license":"CC BY 2.0","licenseUrl":"https://creativecommons.org/licenses/by/2.0","local":"img/jinning-huxiasanjianlouzai-0.webp","small":"img/jinning-huxiasanjianlouzai-0-s.webp"}]},{"id":"jinsha-chenjingchengyang","name":"陳景成洋樓","short":"陳景成洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.47349,"lng":118.40448,"address":"金門縣金沙鎮何斗里斗門2號","announced":"2007-12-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20071213000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-29/ee60a527-4ca3-41b2-9cb9-affac5281e74/01封面.jpg","year":1946,"yearText":"1946年（民國35年）落成","era":"postwar","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"牆門把竣工年「1946」直接寫上的斗門洋樓","intro":"陳景成洋樓位於金沙鎮何斗里斗門聚落。創建人陳景成（1913–2002）年輕時到菲律賓馬尼拉賓南杜發展，在同鄉朋友提攜下累積資本，創立「金瑞成」公司，經營傘業加工、電焊加工與金紙製售。約民國32年（1943）他匯款返鄉，請兄長陳清錶代為籌劃，聘請呂厝土水匠師林清安興建，民國35年（1946）落成。陳景成大部分時間仍在菲律賓生活，便把宅邸交給兄長使用管理。建築為五腳基洋樓加二櫸頭與牆規樓，牆規呈蔥頭形，下方寫著「穎川衍派」與竣工年份1946。民國105年（2016）依縣府獎助辦法完成整體修復。","highlights":["蔥頭形牆規與「穎川衍派」、1946字樣","望柱聯對「群才成大廈，列宿照文星」","一樓四柱三開間、二樓六柱五開間拱圈"],"funFact":"這棟洋樓的主人在菲律賓做雨傘、電焊和金紙生意，橫跨日常、工業和信仰三種需求。","photoSpot":"在前埕外正面拍蔥頭形牆規","visitMin":15,"openNote":"位於金沙鎮何斗里斗門聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這座門的屋頂尖尖圓圓的，好像一顆洋蔥！"},{"who":"A","text":"沒錯，這叫蔥頭形牆規，下面還寫著「穎川衍派」，旁邊直接標了竣工年份1946。"},{"who":"R","text":"把年份寫在門上，好像房子自己的出生證明喔！"},{"who":"A","text":"說得好。主人陳景成年輕時到菲律賓馬尼拉打拚，開了一家「金瑞成」公司。"},{"who":"R","text":"金瑞成？那他們公司是賣什麼的？"},{"who":"A","text":"做雨傘加工、電焊加工，還有金紙。下雨、修鐵門、拜拜都找得到他，超全方位。"},{"who":"R","text":"生意做這麼大，那他蓋好房子以後，有回來斗門住嗎？"},{"who":"A","text":"他大部分時間還在菲律賓，就把房子交給哥哥管理。匠師是呂厝的林清安，民國105年還完成了整體修復。"},{"who":"R","text":"那我要去門口兩根柱子上，讀讀看那副對聯寫了什麼！"}],"clues":["我的牆門把竣工年份用數字直接寫在上面","我的主人在馬尼拉做雨傘、電焊和金紙生意","斗門一棟有蔥頭形牆規的五腳基洋樓"],"quiz":[{"q":"陳景成在菲律賓創立的公司叫什麼？","options":["金和美","金瑞成","和通","金福和"],"answer":1,"explain":"陳景成在馬尼拉創設「金瑞成」公司。"},{"q":"洋樓正面牆規是什麼造型？","options":["三葉形","火焰形","鑰匙孔形","蔥頭形"],"answer":3,"explain":"正面牆規為「蔥頭型」，兩側望柱有聯對。"}],"images":[]},{"id":"jinsha-chenshiyiluosiju2","name":"陳氏一落四櫸頭(碧山6號)","short":"碧山6號古厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.4866,"lng":118.44302,"address":"金門縣金沙鎮碧山6號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-06-23/c8f4cdd6-0560-4a23-a4bf-16395afe458c/01封面.jpg","year":1946,"yearText":"約1940年代（民國30年代）","era":"postwar","themes":["閩南古厝"],"yearUnknown":false,"summary":"曾作軍官宿舍而保存較好的僑匯古厝","intro":"陳氏一落四櫸頭（碧山6號）位於金沙鎮碧山聚落，創建者約在民國30年代（1940年代）從新加坡返鄉興建。格局為一落四櫸頭，外側櫸頭之間以牆規樓（牆門）相接，前埕兩側為後期加建的矮牆。正身為雙坡翹脊，櫸頭為圓脊，正身大規壁脊墜有蝙蝠、如意捲紋泥塑，櫸頭脊墜則是蝴蝶與如意捲紋，水車堵飾以彩磁。大廳兩側馬鼻窗以煙炙磚砌框，額堵畫有雙螭龍彩繪，正廳保留木製壽屏與半廳紅牆。民國38年國軍進駐，這間當作軍官住所，因此保存較為完善；民國86年（1997）翻修，把櫸頭磚坪改為斜屋頂。","highlights":["正身脊墜蝙蝠與櫸頭脊墜蝴蝶泥塑","額堵上的雙螭龍彩繪","連接外側櫸頭的牆規樓"],"funFact":"國軍駐紮時這間給軍官住，官方說正因如此保存得比較完善，算是被好好愛惜過的房子。","photoSpot":"在牆規樓外拍門樓與兩側櫸頭","visitMin":10,"openNote":"位於金沙鎮碧山聚落。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間古厝看起來比旁邊的整齊很多，是最近才蓋的嗎？"},{"who":"A","text":"不算新，大約民國30年代由新加坡返鄉的主人蓋的。它保存得好，還有一個特別原因。"},{"who":"R","text":"什麼原因？請了很厲害的保全嗎？"},{"who":"A","text":"差不多！民國38年國軍進駐，這間被安排給軍官住，官方說因此保存得比較完善。"},{"who":"R","text":"原來是軍官宿舍，住的人比較愛乾淨吧！"},{"who":"A","text":"也許喔。民國86年翻修時，兩邊櫸頭的平頂磚坪改成斜屋頂，算是它的造型升級。"},{"who":"R","text":"那屋頂兩邊山牆上的小動物是什麼？"},{"who":"A","text":"這就是今天的考題。正身脊墜是蝙蝠，櫸頭脊墜是蝴蝶，兩種都長翅膀，很容易搞混。"},{"who":"R","text":"挑戰接受！我要在外面分辨哪一隻是蝙蝠、哪一隻是蝴蝶！"}],"clues":["國軍駐紮時，我被安排給軍官住，所以保存得比較好","我的山牆脊墜上，一邊是蝙蝠，一邊是蝴蝶","碧山一座約民國30年代由新加坡返鄉者興建的一落四櫸頭"],"quiz":[{"q":"官方說這座古厝保存較完善的原因是什麼？","options":["屋主從未離開","被列為國軍軍官住所","一直無人進入","曾作為廟宇使用"],"answer":1,"explain":"民國38年國軍佔用時，此房為軍官使用，保存較完善。"},{"q":"民國86年翻修時做了什麼改變？","options":["加蓋二樓洋樓","拆除照壁","櫸頭磚坪改為斜屋頂","大門改成鐵捲門"],"answer":2,"explain":"民國86年翻修，將兩邊櫸頭磚坪改為斜屋頂。"}],"images":[]},{"id":"jinsha-hesuquehesupoyang","name":"何肅闕、何肅坡洋樓","short":"肅闕肅坡洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.480208,"lng":118.3894,"address":"金門縣金沙鎮沙0084 房屋稅籍牌（現無地址）","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000014","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-27/b50f5e4c-8552-41e4-b1fe-1ea9d6b76d0f/何肅闕、何肅坡洋樓-封面.png","year":1947,"yearText":"1947年（民國36年）始建","era":"postwar","themes":["僑鄉洋樓","教育書院","戰地史蹟"],"yearUnknown":false,"summary":"住過蛙人隊、當過小學校舍的洋樓","intro":"何肅闕、何肅坡洋樓位於金沙鎮浦邊聚落，目前沒有門牌地址。何肅闕、何肅坡年輕時下南洋，在印尼勿里洞、新加坡經商致富，以僑匯返鄉興建，建材購自大陸。洋樓民國36年（1947）動工，隔年落成，屋主只短暫居住便返回僑居地。民國38年國軍進駐，民國40年代由成功特種蛙人隊駐紮；民國48年（1959）何浦國校將校本部與中高年級教室遷入，直到民國54年新校舍落成。正面為六柱五開間拱圈，山頭立天使塑像並有「照亮海山」字樣，大象造型吐水口相當少見。目前屋頂與樓板已坍塌。","highlights":["山頭上的天使塑像與「照亮海山」泥塑字","少見的大象造型泥塑吐水口","窗楣、柱頭的祥獅、天馬、石榴等中西合璧泥塑"],"funFact":"這棟洋樓當過蛙人隊營區，也當過小學教室，民國48年到54年間，浦邊孩子就在這裡上課。","photoSpot":"在外圍遠拍山頭天使像，勿靠近危牆","visitMin":10,"openNote":"位於金沙鎮浦邊聚落，屋頂與樓板已坍塌，結構危險，請勿靠近或進入。私人住宅，請在外觀參觀，勿擅入、勿打擾住戶。可開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，快看！這棟洋樓屋頂上站著一個小天使耶！"},{"who":"A","text":"眼睛真利。天使旁邊還塑著照亮海山四個字，這是何肅闕、何肅坡從南洋寄錢回來蓋的。"},{"who":"R","text":"南洋那麼大，是哪裡呀？新加坡嗎？"},{"who":"A","text":"印尼勿里洞和新加坡。民國36年動工、隔年落成，可是屋主只住了一下，就回南洋拚事業了。"},{"who":"R","text":"屋主走了，那房子空著豈不是很可惜？"},{"who":"A","text":"它一點都沒閒著！先是國軍進駐，民國40年代還住過成功特種蛙人隊，後來又變成何浦國校的教室。"},{"who":"R","text":"蛙人和小學生住過同一棟樓？這履歷比我的還精彩！"},{"who":"A","text":"民國48年到54年，浦邊孩子就在這裡上課。現在屋頂樓板都塌了，只能在外面遠遠看，千萬別靠近。"},{"who":"R","text":"好，那我站遠一點，找找排水口是哪一種動物的造型！"}],"clues":["我當過蛙人隊營區，也當過小學教室","我的山頭上站著天使，寫著「照亮海山」","浦邊聚落裡，由印尼、新加坡僑匯蓋成的戰後洋樓"],"quiz":[{"q":"洋樓山頭上立著什麼塑像？","options":["麒麟","天使","關公","仙鶴"],"answer":1,"explain":"山頭上立一天使塑像，中央有「照亮海山」字樣。"},{"q":"民國48年起，這棟洋樓曾作為什麼用途？","options":["衛生所","雜貨店","郵局","小學校舍"],"answer":3,"explain":"何浦國校將校本部與中高年級教室遷入洋樓。"}],"images":[]},{"id":"jinsha-shameijiduzhanglao","name":"沙美基督長老教會教堂","short":"沙美長老教會","category":"歷史建築","level":"","town":"金沙鎮","types":["教堂"],"lat":24.49169,"lng":118.41191,"address":"金門縣金沙鎮沙美122號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000018","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-12-23/b8090b6d-79c0-4167-a5c2-7e7381e9b8af/511595.jpg","year":1947,"yearText":"1947年（民國36年）","era":"postwar","themes":["宗教信仰","公共建築"],"yearUnknown":false,"summary":"南洋募款重建的金門磚造禮拜堂","intro":"沙美基督長老教會教堂位於金沙鎮沙美聚落。清光緒22年（1896）英國倫敦傳道會到金門傳教，在沙美、西園、後浦設立會所。抗戰時期日軍占領金門，沙美會堂遭毀，戰後只剩後浦有禮拜堂。民國35年（1946）一位來自新加坡的牧師為恢復金門東半島的教會，到南洋各地募款，籌得叻幣7,198元，隔年教堂完工。教堂為一層長形禮拜空間，以煙炙磚丁砌外牆，用疊澀技法砌出略帶西洋式樣的門窗框，屋頂卻是傳統瓦作；正門上方有「中華基督教會」字樣與十字架，右下方石碑題「浯島之光」。","highlights":["正門上方「中華基督教會」泥塑字樣與十字架","中華基督教會全國總會長題「浯島之光」的石碑","煙炙磚疊澀砌出的西洋式門窗框"],"funFact":"原登錄名稱含牧師樓，因牧師樓已拆除重建，民國115年（2026）2月更名為現名。","photoSpot":"在正門前拍「中華基督教會」字樣","visitMin":15,"openNote":"位於金沙鎮沙美聚落，目前仍是基督宗教聚會場所；官方資料未載明開放時間，參觀請尊重聚會活動，以外觀參觀為主。可搭金門縣公車至沙美車站，再步行前往。","dialogue":[{"who":"R","text":"Allan，這間教堂看起來好特別，牆是紅磚，屋頂卻是傳統瓦片！"},{"who":"A","text":"這就是它的混搭風。外牆用煙炙磚丁砌，門窗框砌出一點西洋味，屋頂卻是閩南瓦作。"},{"who":"R","text":"中西合璧的教堂，好有金門味！它是什麼時候蓋的？"},{"who":"A","text":"早在清光緒22年，英國倫敦傳道會就來金門傳教。不過抗戰時期日軍占領金門，原本的會堂被毀了。"},{"who":"R","text":"會堂被毀了，那後來是誰把它蓋回來的？"},{"who":"A","text":"戰後一位從新加坡來的牧師跑遍南洋各地募款，募到7198元叻幣，民國36年教堂完工。"},{"who":"R","text":"又是南洋華僑出手相助，金門跟南洋真的好親！"},{"who":"A","text":"到現在這裡還是教會聚會的地方，參觀時要安靜、尊重。到正門前抬頭看看，十字架旁邊寫著哪幾個字？"}],"clues":["我是靠南洋募款重建起來的禮拜堂","我的門額上有十字架和「中華基督教會」字樣","沙美聚落裡，煙炙磚砌牆、屋頂卻是傳統瓦作的教堂"],"quiz":[{"q":"教堂正面花崗石碑上題的是哪四個字？","options":["福音廣傳","浯島之光","主恩浩大","以馬內利"],"answer":1,"explain":"中華基督教會全國總會長陳秋卿建碑，題字「浯島之光」。"},{"q":"戰後重建教堂的經費主要來自哪裡？","options":["縣政府補助","英國教會撥款","國軍協助","南洋各地募款"],"answer":3,"explain":"牧師赴南洋各地籌款，募得叻幣7,198元。"}],"images":[]},{"id":"jinsha-caiyongyaoerluoda","name":"蔡永耀二落大厝","short":"蔡永耀二落大厝","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48071,"lng":118.38982,"address":"金門縣金沙鎮浦邊98號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000009","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/8fce908f-438a-4b0b-8c9b-99b08fb96675/蔡永耀二落大厝_封面.jpg","year":1947,"yearText":"1947年（民國36年）竣工","era":"postwar","themes":["閩南古厝"],"yearUnknown":false,"summary":"門額題「瓊林世澤」、當過村公所的大厝","intro":"蔡永耀二落大厝位於金沙鎮浦邊聚落。蔡永耀的先祖出自瓊林，後來遷居浦邊，相傳是父親或祖父入贅浦邊趙氏。他早年到新加坡經商，民國34至36年（1945–1947）返鄉同時興建這座大厝和前方的洋樓，外圍以圍牆環繞。大厝門額書「瓊林世澤」，右題「民國三十六年」，說明家族的血緣來處。竣工後國軍隨即進駐，國軍撤離後成為浦邊的村公所，直到民國69年（1980）村公所遷出。建築是傳統二落大厝，雙坡翹脊紅瓦屋頂，大規壁脊墜有人物與走獸泥塑，正廳保留木製壽屏與格扇，整體風格簡樸。","highlights":["門額「瓊林世澤」與「民國三十六年」題字","大規壁脊墜的人物、走獸泥塑","正立面水車堵的各式彩磁"],"funFact":"這座大厝蓋好後主人沒住多久，先是國軍進駐，後來又當了浦邊的村公所，一用就到民國69年。","photoSpot":"在前埕外拍門額「瓊林世澤」","visitMin":10,"openNote":"位於金沙鎮浦邊聚落，與蔡永耀洋樓相鄰。私人產權，由代管人管理，請在外觀參觀，勿擅入、勿打擾。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這間大厝的門上寫「瓊林世澤」，可是這裡不是浦邊嗎？"},{"who":"A","text":"問到重點了！主人蔡永耀的祖先來自瓊林蔡氏，後來搬到浦邊，這四個字就是在說「我從哪裡來」。"},{"who":"R","text":"原來門額就是家族的身分證！那這間是什麼時候蓋的？"},{"who":"A","text":"旁邊題著「民國三十六年」，蔡永耀在新加坡經商有成，回來同時蓋了這座大厝和前面的洋樓。"},{"who":"R","text":"一次蓋兩棟，好大的手筆！那他住哪一棟？"},{"who":"A","text":"他住洋樓。大厝一蓋好就有國軍進駐，後來還變成浦邊的村公所，一直用到民國69年。"},{"who":"R","text":"所以以前村民辦事情都要來這裡？簡直是古厝版的區公所！"},{"who":"A","text":"沒錯，金門很多古厝都有這種身兼多職的經歷。等一下找找看，大規壁上的泥塑是人物還是動物？"}],"clues":["我的門額寫著另一個村子的名字，說明主人的祖先從哪來","我蓋好不久就當過浦邊的村公所","浦邊一座民國36年竣工、與洋樓相伴的二落大厝"],"quiz":[{"q":"大厝門額的「瓊林世澤」說明了什麼？","options":["主人在瓊林做官","主人祖先出自瓊林","大厝由瓊林匠師建造","建材來自瓊林"],"answer":1,"explain":"蔡永耀先祖系出瓊林，門額說明其血緣淵源。"},{"q":"國軍撤離後，這座大厝曾作為什麼用途？","options":["小學教室","郵政代辦所","浦邊村公所","電影院"],"answer":2,"explain":"國軍撤離後成為浦邊村公所，民國69年才遷出。"}],"images":[]},{"id":"jinsha-caiyongyaoyanglou","name":"蔡永耀洋樓","short":"蔡永耀洋樓","category":"歷史建築","level":"","town":"金沙鎮","types":["宅第"],"lat":24.48085,"lng":118.38977,"address":"金門縣金沙鎮浦邊99號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000010","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/2fb9ca3c-23aa-4ae2-841c-5e7d21450979/蔡永耀洋樓_封面.jpg","year":1947,"yearText":"1947年（民國36年）竣工","era":"postwar","themes":["僑鄉洋樓"],"yearUnknown":false,"summary":"二樓圓拱廊配花瓶欄杆的戰後僑匯洋樓","intro":"蔡永耀洋樓位於金沙鎮浦邊聚落，左側就是同一位主人興建的蔡永耀二落大厝。蔡永耀先祖出自瓊林，早年到新加坡經商，民國34至36年（1945–1947）返鄉同時興建大厝與洋樓。竣工後大厝由國軍進駐，洋樓則由蔡永耀夫婦自用；民國42年（1953）起租給吳姓人家居住，直到民國62年搬離。洋樓左側的附屬建物在駐軍時期當過器械室與村民避難所，後來還做過何浦國小的臨時廚房。建築為二層洋樓，二樓退縮成三開間圓拱廊，拱廊作多層線腳，中央立柱有泥塑聯對，柱間以花瓶欄杆相接，外觀簡潔平整。","highlights":["二樓三開間圓拱廊與多層線腳","中央立柱上的泥塑聯對","一樓四柱三開間圓柱前廊"],"funFact":"洋樓旁的小附屬屋一屋多用，當過駐軍器械室、村民避難所，還做過何浦國小的臨時廚房。","photoSpot":"在圍牆外拍二樓圓拱廊與花瓶欄杆","visitMin":10,"openNote":"位於金沙鎮浦邊聚落，與蔡永耀二落大厝相鄰。私人產權，由親族代管，請在外觀參觀，勿擅入、勿打擾。可開車或騎機車前往。","dialogue":[{"who":"A","text":"剛看完隔壁的大厝，現在換主人自己住的這棟洋樓。阿拉蕾，先看二樓。"},{"who":"R","text":"二樓往裡面縮進去，排了三個圓圓的拱門，好像三個大大的笑臉！"},{"who":"A","text":"很可愛的比喻！那叫圓拱廊，柱子之間用花瓶欄杆連起來，中間柱子上還有泥塑對聯。"},{"who":"R","text":"蔡永耀先生同時蓋大厝跟洋樓，為什麼自己選洋樓住？"},{"who":"A","text":"大厝一蓋好就給國軍進駐了。他們夫婦住過洋樓，後來長年旅居新加坡，就把洋樓租給吳家住了二十年。"},{"who":"R","text":"那旁邊那間小屋子又是做什麼的？"},{"who":"A","text":"它最多才多藝，當過器械室、村民避難所，還當過何浦國小的臨時廚房。"},{"who":"R","text":"從放器械到煮營養午餐，這小屋的履歷比我還精彩！"},{"who":"A","text":"哈哈，那你在外面數數看，二樓圓拱廊一共有幾個拱圈？"}],"clues":["我身邊的小附屬屋當過避難所，也當過小學臨時廚房","我曾經出租給吳姓人家住了二十年","浦邊一棟二樓有三開間圓拱廊、民國36年竣工的洋樓"],"quiz":[{"q":"洋樓二樓立面是什麼樣的造型？","options":["五腳基方柱廊","出龜式門廊","鑄鐵陽台","三開間圓拱廊"],"answer":3,"explain":"二樓退縮成三開間的圓拱廊，柱間有花瓶欄杆。"},{"q":"洋樓左側附屬建物曾經做過什麼？","options":["何浦國小臨時廚房","郵局","雜貨店","理髮店"],"answer":0,"explain":"曾作器械室、村民避難所，後作何浦國小臨時廚房。"}],"images":[]},{"id":"jinning-beishanlishixiong","name":"北山李氏兄弟洋樓","short":"李氏兄弟洋樓","category":"歷史建築","level":"","town":"金寧鄉","types":["宅第"],"lat":24.47841,"lng":118.31147,"address":"金門縣金寧鄉北山23-3號","announced":"2015-02-26","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20150226000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-05-15/d8d4f290-73a4-495c-9f04-1be7610e487e/北山李氏兄弟洋樓-代表圖像.jpg","year":1948,"yearText":"1948年（民國37年）起建","era":"postwar","themes":["僑鄉洋樓","戰地史蹟"],"yearUnknown":false,"summary":"因古寧頭戰役停工的五腳基洋樓","intro":"北山李氏兄弟洋樓位於金寧鄉古寧村北山聚落，由李增田、李明堂、李增料三兄弟在馬來西亞經商致富後，匯款返鄉興建。洋樓1948年動工，隔年因古寧頭戰役停工，結構大致成形卻未完工，屋主攜家人避往南洋，交由親戚代管。戰後由國軍醫療單位使用，直到八二三砲戰後才撤離，砲戰期間也是重要的避難所。建築歷經戰火損壞，閒置數十年，2008年交由金門國家公園管理處修繕，之後招標再利用。洋樓為典型五腳基洋樓併後落，正面以紅磚柱分成四柱三開間，二樓外廊與女兒牆用水泥花瓶欄杆，牆面為蠣殼洗石子，山牆規帶做成三拱線板並開圓窗。","highlights":["四柱三開間的紅磚柱立面","二樓外廊與屋頂女兒牆的水泥花瓶欄杆","山牆三拱線板與中央圓窗"],"funFact":"這棟洋樓蓋到一半遇上古寧頭戰役而停工，戰後還當過國軍醫療單位的空間。","photoSpot":"在洋樓正面拍紅磚柱與花瓶欄杆","visitMin":15,"openNote":"位於金寧鄉古寧村北山聚落，由金門國家公園管理處管理，修復後招標再利用，部分古厝修復後作為民宿使用；非住宿旅客請在外觀參觀，勿擅入、勿打擾住宿旅客。可從金城車站搭公車或騎機車前往古寧頭。","dialogue":[{"who":"A","text":"阿拉蕾，北山這棟紅磚柱洋樓，是一棟「蓋到一半就被迫暫停」的房子。"},{"who":"R","text":"暫停？是工人師傅去吃點心，結果忘記回來嗎？"},{"who":"A","text":"不是啦。李家三兄弟在馬來西亞做生意，1948年匯錢回來蓋，隔年古寧頭戰役爆發就停工了。"},{"who":"R","text":"那屋主一家人後來怎麼辦呢？好擔心他們。"},{"who":"A","text":"他們帶著家人避往南洋，房子交給親戚李增添代管。戰後國軍醫療單位進駐，砲戰時這裡也是避難所。"},{"who":"R","text":"原來它也曾經保護過大家，好像一位默默站崗的大哥。"},{"who":"A","text":"形容得好。2008年金門國家公園修繕後，它才重新站穩腳步，比我減肥還有毅力。"},{"who":"R","text":"那這棟洋樓的外觀有什麼看點呢？"},{"who":"A","text":"它是典型的五腳基洋樓。請你數一數正面有幾根紅磚柱，二樓欄杆是不是像一排小花瓶？"}],"clues":["起造我的三兄弟在馬來西亞經商","我在1948年動工，隔年因戰事停工未完工","我在古寧頭北山，是紅磚柱的五腳基洋樓"],"quiz":[{"q":"李氏兄弟洋樓為什麼在1949年停工？","options":["建材運不到","屋主生意失敗","颱風摧毀工地","古寧頭戰役爆發"],"answer":3,"explain":"1949年古寧頭戰役爆發，洋樓工程因而停止。"},{"q":"古寧頭戰役後，哪個單位曾使用這棟洋樓？","options":["國軍醫療單位","古寧村公所","國民學校","郵政代辦所"],"answer":0,"explain":"戰役後由國軍醫單位佔用，直到八二三砲戰後才撤離。"}],"images":[]},{"id":"lieyu-yongshibao","name":"勇士堡","short":"勇士堡","category":"歷史建築","level":"","town":"烈嶼鄉","types":["其他設施"],"lat":24.44792,"lng":118.25151,"address":"金門縣烈嶼鄉黃埔村黃厝海岸","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000017","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/b235f722-1911-4dcb-813b-0735b2f15279/01-封面.jpg","year":1949,"yearText":"1949年（民國38年）初建，1971年（民國60年）整建","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"地下坑道串連鐵漢堡的四八高地海防碉堡","intro":"勇士堡位於烈嶼鄉黃埔村黃厝海岸，民國38年（1949）國軍初建時規模較小；民國60年（1971）因軍事需要，由當時的金門防衛部司令官指示重新整建四八高地，歷時五個多月，增挖戰車濠溝與火點防禦工事，目標是小而堅、能獨立固守。碉堡分上下兩層，上層為砲堡、中山室與寢室，地下有八座機槍堡、四間彈藥庫、消防水池與一座戰車堡，綿延數百公尺的地下交通坑道與鐵漢堡相連。民國86年（1997）精實案裁軍後廢棄，後移交烈嶼鄉公所整建，民國99年（2010）開放參觀，民國103年（2014）連通道整建為地雷展示館。","highlights":["入口小橋、城堡造型哨所與深壕溝斜坡","地下八座機槍堡與一座戰車堡","連接鐵漢堡的地雷展示館坑道"],"funFact":"勇士堡和鐵漢堡靠地下坑道相連，參觀動線地上地下交錯，可以一次走完兩座碉堡。","photoSpot":"在圓拱入口「勇士堡」字樣前留影","visitMin":45,"openNote":"位於烈嶼鄉黃埔村黃厝海岸，依官方資料每日08:00–17:00開放，可經地下坑道連通鐵漢堡；坑道內光線較暗，請注意腳步。可經金門大橋開車或騎車前往。","dialogue":[{"who":"A","text":"阿拉蕾，前面這座小橋和兩個城堡造型的哨所，就是勇士堡的入口，要沿著斜坡走下去喔。"},{"who":"R","text":"好像要進城堡探險！Allan，這裡以前是做什麼的？"},{"who":"A","text":"是小金門東北角的海防碉堡，民國38年初建，民國60年花了五個多月大整建，要做到小而堅。"},{"who":"R","text":"小而堅，聽起來跟Allan的光頭一樣。"},{"who":"A","text":"我的頭是亮而堅，謝謝。碉堡分兩層，地下有八座機槍堡、四間彈藥庫，還有一座戰車堡。"},{"who":"R","text":"地下藏了這麼多東西！走得完嗎？"},{"who":"A","text":"數百公尺的坑道一路連到鐵漢堡，中間的連通道現在整建成地雷展示館。"},{"who":"R","text":"地雷展示館？聽起來有點可怕耶。"},{"who":"A","text":"那是讓我們認識戰地歷史的展示，參觀時心存敬意就好。進圓拱入口前，先找找門上的「勇士堡」三個字。"}],"clues":["我的入口有小橋和一對城堡造型哨所","我的地下藏著八座機槍堡和一座戰車堡","我和鐵漢堡用坑道相連，中間有地雷展示館"],"quiz":[{"q":"勇士堡的地下坑道和哪裡相連？","options":["將軍堡","鐵漢堡","九宮坑道","擎天廳"],"answer":1,"explain":"數百公尺的地下坑道與鐵漢堡相連。"},{"q":"民國60年整建勇士堡的目標是？","options":["擴建成觀光樂園","改建為野戰醫院","作為彈藥工廠","小而堅、能獨立固守"],"answer":3,"explain":"整建目標是小而堅、能獨立固守。"}],"images":[]},{"id":"jincheng-zhongxuezhongzheng","name":"金門中學中正堂","short":"金中中正堂","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.43509,"lng":118.31397,"address":"金門縣金城鎮光前路94號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000022","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-29/e284c2e0-17a2-4b4f-b402-51d07cabc836/01封面.jpg","year":1951,"yearText":"1951年（民國40年）啟用","era":"postwar","themes":["公共建築","戰地史蹟","教育書院"],"yearUnknown":false,"summary":"克難運動中約四個月完工的集會堂","intro":"金門中學中正堂位於金城鎮光前路金門高中校園內，1950年10月由陸軍第十二兵團司令官胡璉下令興建，工兵部隊施工，在「克難運動」背景下動員軍民，約四個月完工，1951年3月啟用，是當時金門最大的室內集會場所，舉辦過典禮、晚會、電影、考試與集團結婚。1952年曾作南日島戰役的臨時戰俘看守所，1955至1960年三樓設為觀測哨。1960年改為金門第一所室內電影院「金門戲院」，1963年停業後撥交金門中學作禮堂，2010年修復完成。","highlights":["三樓中央金漆的「中正堂」楷書大字與圓形校徽","四柱三開間正立面，層層降低略呈山形","禮堂大跨距拱形屋頂與刻意粗糙的吸音天花板"],"funFact":"禮堂天花板刻意用水泥砂漿做出粗糙表面，為的是吸音、降低室內回音。","photoSpot":"前廣場拍白色山形立面與金字招牌","visitMin":20,"openNote":"位於金城鎮光前路金門高中校園內，官方資料記載每日8:00至17:00；仍為學校禮堂，請遵守校園規定、勿干擾上課。可搭金門縣公車到金城車站後步行前往。","dialogue":[{"who":"A","text":"今天帶你逛校園，這棟白色大樓叫中正堂，1951年啟用，是當年全金門最大的室內集會場所。"},{"who":"R","text":"全金門最大？那時候大家都來這裡開會嗎？"},{"who":"A","text":"不只開會，晚會、電影、考試，還有集團結婚，熱鬧得像金門的多功能巨蛋。"},{"who":"R","text":"集團結婚！一次辦很多對，喜餅一定吃不完吧？"},{"who":"A","text":"你很會抓重點耶。它在克難運動中由工兵施工，大約四個月就蓋好了。"},{"who":"R","text":"才四個月！那後來它還當過什麼角色？"},{"who":"A","text":"1952年當過臨時戰俘看守所，砲戰期間三樓設觀測哨，1960年又變成金門第一家室內電影院。"},{"who":"R","text":"一棟房子換了好多身分，比演員還會變裝。"},{"who":"A","text":"1963年起它成為金門中學禮堂。到現場請抬頭，找找屋頂中央那枚圓形的金色校徽！"}],"clues":["我當過戰俘看守所、觀測哨，也當過電影院","我在克難運動中由工兵約四個月蓋好，1951年啟用","我在金門高中校園裡，現在是學校的禮堂"],"quiz":[{"q":"中正堂1960年曾改作什麼用途？","options":["公有市場","軍醫院","圖書館","金門戲院"],"answer":3,"explain":"1960年改為公營電影院金門戲院，是金門第一所室內電影院。"},{"q":"禮堂天花板做成粗糙表面的目的是？","options":["防止屋頂滲水","吸音並降低回音","讓室內更明亮","防止砲彈破片"],"answer":1,"explain":"以水泥砂漿製造粗糙表面，用來吸音、降低回音。"}],"images":[]},{"id":"jincheng-xiongshibao","name":"雄獅堡","short":"雄獅堡","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.43135,"lng":118.31007,"address":"金門縣金城鎮民權路34-1號","announced":"2003-03-31","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20030331000073","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-29/5bd6eb6e-ae68-4d71-a0e8-6a1aca1bfd75/01封面.jpg","year":1955,"yearText":"約1950年代以後（推估）","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"曾管制蚵民下海的海防「蚵管哨」","intro":"雄獅堡位於金城鎮後浦民權路旁，是一處海防據點，創建年代無資料可考，推估在1950年代以後。戰地政務解除以前屬金西師轄區，負責海岸管理，漁民要經崗哨查驗蚵民證才能下海，因此俗稱「蚵管哨」。此地原為後浦大媽祖廟舊址，國軍進駐後土地被徵用，建成設有政戰點、機槍堡、彈藥室的軍事碉堡。數座碉堡依地形興建，外觀漆成迷彩，周邊保留瓊麻等阻絕性植物，地下有坑道與射口。駐軍撤離後交由地方團體使用，加建了鐵門與涼亭。","highlights":["迷彩外觀、依地形隱身的多座碉堡","周邊保留的瓊麻等阻絕性植物","地下的坑道與射口"],"funFact":"漁民要先在崗哨查驗蚵民證才能下海採蚵，所以這裡被叫作「蚵管哨」。","photoSpot":"拍迷彩碉堡與前方的瓊麻","visitMin":20,"openNote":"位於金城鎮後浦民權路旁，官方資料記載每日6:00至17:30開放，現由地方團體使用；坑道內潮濕，請注意腳步安全。可從金城市區步行或騎機車前往。","dialogue":[{"who":"A","text":"阿拉蕾，你知道以前在金門採蚵，也要先看證件嗎？"},{"who":"R","text":"採蚵要證件？難道蚵仔會查身分證？"},{"who":"A","text":"不是蚵仔查你，是哨兵查。戰地政務時期，漁民要在崗哨出示蚵民證才能下海，所以這裡叫蚵管哨。"},{"who":"R","text":"原來雄獅堡是管海岸的碉堡！它什麼時候蓋的？"},{"who":"A","text":"確切年代查不到，推估是1950年代以後。有趣的是，這裡原本是後浦大媽祖廟的舊址。"},{"who":"R","text":"從媽祖廟變成碉堡，變化也太大了！"},{"who":"A","text":"國軍進駐後徵用土地，蓋了政戰點、機槍堡和彈藥室，外面漆迷彩，還種瓊麻阻擋接近。"},{"who":"R","text":"瓊麻葉子尖尖的，我才不要靠近！"},{"who":"A","text":"這正是它的用意。今天能吃到石蚵，也要記得當年漁民進出海邊的不便。到現場數數看，你能找到幾座迷彩碉堡？"}],"clues":["我原本是一座媽祖廟的舊址，後來被徵用建成碉堡","漁民要在我這裡查驗證件才能下海採蚵","我在後浦民權路旁，外觀迷彩，俗稱蚵管哨"],"quiz":[{"q":"這處碉堡為何俗稱「蚵管哨」？","options":["漁民要在此查驗蚵民證才能下海","這裡專門養殖石蚵","碉堡外形很像蚵殼","哨兵負責收購蚵仔"],"answer":0,"explain":"漁民須接受崗哨查驗蚵民證方可下海，因此稱蚵管哨。"},{"q":"雄獅堡所在地原本是什麼地方？","options":["金門城城門","清代總兵署","後浦大媽祖廟舊址","後浦魚市場"],"answer":2,"explain":"雄獅堡原為後浦大媽祖廟舊址，後因國軍進駐被徵用。"}],"images":[]},{"id":"jinning-panshanzhongyongbu","name":"盤山忠勇部隊伏地堡","short":"忠勇部隊伏地堡","category":"歷史建築","level":"","town":"金寧鄉","types":["其他設施"],"lat":24.44093,"lng":118.33732,"address":"金門縣金寧鄉中三劃測段488、517地號","announced":"2020-10-29","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20201129000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-21/99ef1888-7123-4252-a256-05a46e844069/盤山忠勇部隊伏地堡_代表圖像.jpg","year":1955,"yearText":"約1950年代（民國40年代，確切年代不詳）","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"小小碉堡裡塞滿泥塑標語的防砲據點","intro":"盤山忠勇部隊伏地堡位於金寧鄉盤山村一帶。空軍高射砲兵36師於1953至1955年間逐年接收美援裝備，部隊別稱「忠勇部隊」，伏地堡入口的泥塑「忠勇」二字，顯示它是該部隊駐紮金門時所建。這座伏地堡負責警戒、保護兩側陣地，監控營區道路出入，後期也保護北側的軍用加油站「盤果加油站」。2019年國防部在附近清理環境時發現它，2020年登錄為歷史建築。碉堡以石塊與鋼筋混凝土構築，深入地表、射口略高於地面，內部空間雖小，卻布滿梅花立體泥塑、黨徽、五大信念與各式作戰口訣標語，密度在金門相當罕見。","highlights":["入口泥塑「忠勇」二字，標示部隊別稱","天花板的梅花立體泥塑與五大信念標語","「瞄不準不打、距離遠不打」等防砲作戰口訣"],"funFact":"這座伏地堡直到2019年環境清理時才被發現，隔年就登錄為歷史建築。","photoSpot":"在入口外拍「忠勇」泥塑字樣","visitMin":15,"openNote":"位於金寧鄉盤山村一帶的國有土地。官方資料未載明開放時間，目前請在外觀參觀，勿擅自進入碉堡內部。可騎機車或開車前往。","dialogue":[{"who":"R","text":"Allan，地上這個矮矮的水泥塊是什麼？差點以為是一個超大的便當盒。"},{"who":"A","text":"這是伏地堡，故意蓋得很低，射口剛好高出地面，是防空砲兵部隊用來警戒陣地的碉堡。"},{"who":"R","text":"門口寫著「忠勇」兩個字，是它的名字嗎？"},{"who":"A","text":"那是空軍高射砲兵36師的別稱「忠勇部隊」，代表這座碉堡是他們駐紮金門時蓋的。"},{"who":"R","text":"那它為什麼最近才變成文化資產？"},{"who":"A","text":"因為它一直藏在草叢裡，2019年國防部清理環境時才被發現，隔年登錄為歷史建築。"},{"who":"R","text":"原來是捉迷藏冠軍！那裡面有什麼？"},{"who":"A","text":"裡面空間很小，卻布滿泥塑標語，有五大信念，也有「瞄不準不打」這類防砲口訣，是當時鼓舞士氣的時代印記。"},{"who":"A","text":"請你看看官方照片，找找天花板上那朵立體梅花泥塑在哪裡？"}],"clues":["我一直藏在草叢裡，2019年環境清理時才被發現","我身體很矮，裡面卻塞滿泥塑標語和防砲口訣","我在盤山，入口寫著高射砲兵部隊的別稱"],"quiz":[{"q":"伏地堡入口的「忠勇」二字代表什麼？","options":["守軍的姓名","附近村莊名稱","高射砲兵部隊的別稱","碉堡的編號"],"answer":2,"explain":"「忠勇」是空軍高射砲兵36師的別稱，顯示碉堡為該部隊所建。"},{"q":"這座伏地堡是在什麼情況下被發現的？","options":["颱風吹倒樹木","國防部清理環境","學生校外教學","道路拓寬施工"],"answer":1,"explain":"2019年國防部軍備局進行環境清理工程時發現此堡。"}],"images":[]},{"id":"lieyu-jiangjunbao","name":"將軍堡","short":"將軍堡","category":"歷史建築","level":"","town":"烈嶼鄉","types":["其他設施"],"lat":24.44092,"lng":118.26646,"address":"金門縣烈嶼鄉黃埔村后頭海岸","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000016","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-20/92c95176-46a6-442a-a659-1131c3faa5df/1.jpg","year":1958,"yearText":"1958年（民國47年）已為守備據點，1980年（民國69年）整修定名","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"扼守金烈水道、八二三砲戰時的前線據點","intro":"將軍堡位於烈嶼鄉黃埔村后頭海岸，扼守大小金門之間的金烈水道。民國47年（1958）八二三砲戰期間，九宮碼頭遭火砲封鎖、交通中斷，國軍運補困難，改在后頭附近據點搶灘運補，這裡成為烈嶼重要的守備據點，主要任務是監控金烈水道。同年10月21日，蔣經國偕王昇、柯遠芬兩位將軍自水頭乘艇抵烈嶼慰問守軍，並在砲聲中與第九師師長郝柏村於此會談，因此被稱為前線戰地的精神碉堡。民國69年（1980）金防部指示整修，正式定名為將軍堡；民國92年（2003）由國家公園管理處接管整修後開放參觀。","highlights":["入口上方的「將軍堡」門額","監控金烈水道的海岸據點位置","園區景觀步道上的崗哨與雲牆"],"funFact":"八二三砲戰時九宮碼頭被封鎖，補給船改在后頭一帶搶灘，將軍堡就守在這條運補線旁。","photoSpot":"在「將軍堡」門額前，背對水道留影","visitMin":30,"openNote":"位於烈嶼鄉黃埔村后頭海岸，依官方資料每日08:00–17:00開放。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，這裡的海好窄，對岸看起來好近喔！"},{"who":"A","text":"這片海就是金烈水道，隔開大金門和小金門。我們腳下的將軍堡，以前專門負責監控這條水道。"},{"who":"R","text":"那為什麼叫將軍堡？裡面住滿了將軍嗎？"},{"who":"A","text":"不是啦。民國47年八二三砲戰期間，10月21日蔣經國先生來烈嶼慰問守軍，在砲聲中和師長郝柏村在這裡會談。"},{"who":"R","text":"在砲聲中開會，當時一定非常緊張。"},{"who":"A","text":"是的，那時九宮碼頭被火砲封鎖，補給船只能改到后頭一帶搶灘，前線官兵和居民都非常辛苦。"},{"who":"R","text":"那將軍堡這個名字是什麼時候取的？"},{"who":"A","text":"民國69年金防部整修時才正式定名，民國92年起由國家公園管理處接手開放參觀。"},{"who":"A","text":"站在據點邊望向水道，想像一下當年冒著危險搶灘運補的船隻，再拍一張平靜的海面吧。"}],"clues":["我守在金烈水道邊，監控大小金門之間的海面","八二三砲戰時，曾有人在砲聲中於我這裡會談","我在小金門后頭海岸，民國69年才正式定名"],"quiz":[{"q":"將軍堡主要負責監控哪裡？","options":["金烈水道","料羅灣","廈門港","大膽島"],"answer":0,"explain":"將軍堡扼守並監控大小金門之間的金烈水道。"},{"q":"將軍堡在哪一年正式定名？","options":["民國47年","民國60年","民國69年","民國92年"],"answer":2,"explain":"民國69年金防部指示整修，正式定名為將軍堡。"}],"images":[]},{"id":"jinhu-nanxiongbaersanpao","name":"南雄八二三砲戰勝利紀念碑","short":"南雄八二三紀念碑","category":"歷史建築","level":"","town":"金湖鎮","types":["碑碣"],"lat":24.44687,"lng":118.42313,"address":"金門縣金湖鎮南雄段350-12地號","announced":"2014-04-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20140401000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-18/6f57cb0d-9811-43a1-9559-807a2c4089b3/南雄八二三砲戰勝利紀念碑封面.jpg","year":1959,"yearText":"1959年（民國48年）","era":"postwar","themes":["戰地史蹟"],"yearUnknown":false,"summary":"八二三砲戰後的第一座紀念碑，碑身是一顆砲彈","intro":"南雄八二三砲戰勝利紀念碑位於金湖鎮下莊聚落外圍，原屬金防部總預備隊南雄師的營區（該師2006年裁撤）。紀念碑於1959年11月建成，是1958年8月23日八二三砲戰後設立的第一座紀念碑，碑名與題字反映當時軍方鼓舞士氣的用意。碑體仿砲彈造型，高5.43公尺，立在高2.65公尺的方形基座上，碑身下方一圈斜紋代表砲管膛線的刻痕。碑座四面有「威鎮臺海」、國防部長俞大維題「我武維揚」、當時的「領袖訓示」及「確保金門十大勝利保證」。2013年縣府調處土地糾紛時，決議保留碑體周邊土地以保存紀念碑。","highlights":["仿砲彈造型的碑身與代表膛線刻痕的斜紋","碑座上俞大維題寫的「我武維揚」","記錄當時軍中標語的「確保金門十大勝利保證」"],"funFact":"營區土地申請購回時，各方協調同意以碑座外緣往東、西、南各延伸10公尺保留，讓紀念碑留在原地。","photoSpot":"在碑前仰角拍砲彈造型碑身","visitMin":10,"openNote":"位於金湖鎮下莊聚落外圍的戶外紀念碑，官方資料未載開放時間。周邊多為私人土地，請在碑體周邊參觀，勿攀爬碑體。","dialogue":[{"who":"R","text":"Allan，那邊立著一顆超巨大的砲彈！是不是要發射了？"},{"who":"A","text":"別緊張，那是紀念碑，做成砲彈的樣子。它是1958年八二三砲戰之後，金門蓋的第一座紀念碑，1959年11月完成。"},{"who":"R","text":"八二三砲戰是一場什麼樣的戰役呢？"},{"who":"A","text":"砲戰從1958年8月23日開始，金門承受了大量砲擊，軍民都有傷亡，這段歷史值得我們安靜地記住。"},{"who":"R","text":"嗯，那碑座上寫的那些字是什麼意思？"},{"who":"A","text":"碑名和四面的題字，像「威鎮臺海」「我武維揚」，都是當時軍方鼓舞士氣的用語，讓我們看見那個年代的氛圍。"},{"who":"R","text":"砲彈下面那一圈斜斜的紋路是裝飾嗎？"},{"who":"A","text":"那代表砲彈發射時被砲管膛線刻出的痕跡。請你繞碑一圈，找找俞大維題字的那一面在哪個方向。"}],"clues":["我原本在一個已裁撤師級部隊的營區裡","我的身上有一圈斜紋，代表膛線刻痕","我是1959年建成、外形像砲彈的砲戰紀念碑"],"quiz":[{"q":"這座紀念碑的碑體做成什麼造型？","options":["砲彈","坦克","燈塔","寶劍"],"answer":0,"explain":"碑體為仿砲彈形式，直徑1.73公尺、高5.43公尺。"},{"q":"碑身下方一圈斜紋代表什麼？","options":["海浪波紋","稻穗圖案","砲管膛線刻痕","防滑設計"],"answer":2,"explain":"斜紋代表砲彈射擊後被砲管膛線刻劃的鑿痕。"}],"images":[]},{"id":"jinsha-jindongdianying","name":"金東電影院","short":"金東電影院","category":"歷史建築","level":"","town":"金沙鎮","types":["其他設施"],"lat":24.47861,"lng":118.42724,"address":"金門縣金沙鎮陽翟96-6號","announced":"2003-12-01","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20031201000023","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-06-18/e9e32c89-fe8c-41e2-9038-39c6706e676c/金東電影院_封面.jpg","year":1960,"yearText":"1960年（民國49年）","era":"postwar","themes":["戰地史蹟","公共建築"],"yearUnknown":false,"summary":"勞軍捐款興建、于右任題字的前線戲院","intro":"金東電影院位於金沙鎮陽翟，民國49年（1960）臺北市議會議長張祥傳率團到金門勞軍，捐助12萬元興建，作為前線官兵休憩的場所。正面山頭有書法家于右任題寫的「金東電影院」五個紅色大字，大門左側留有電影院記誌。當年場場座無虛席，旁邊的陽翟街區也隨之發展成有理髮廳、撞球室、澡堂的熱鬧商店街。停映後仍由軍方使用，民國107年撥用給金門縣文化局，民國108年（2019）修復完成，保留仿舊座椅、綠色地磚、二樓放映室以及早期軍人塗鴉，現由金沙鎮公所管理，作為金東地區藝文與集會場所。","highlights":["山頭于右任題「金東電影院」紅色大字","入口保留的水泥排隊欄杆與售票口","修復時特意保留的早期軍人塗鴉"],"funFact":"電影院帶旺了旁邊的陽翟街，理髮廳、撞球室、澡堂一應俱全，阿兵哥看完電影還能順便打理門面。","photoSpot":"在正面廣場拍山頭紅字與雨庇挑檐","visitMin":30,"openNote":"位於金沙鎮陽翟，鄰近陽翟老街。官方資料開放時間為週二至週日08:30–12:00、13:00–17:00，週一休息；有活動時依金沙鎮公所公告。可開車或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這棟房子上面寫著五個紅色大字，是電影院耶！金門以前也有這種地方？"},{"who":"A","text":"有喔！民國49年臺北市議會議長張祥傳來勞軍，捐了12萬元，蓋給前線的官兵看電影放鬆。"},{"who":"R","text":"那招牌上的字是誰寫的？看起來好有氣勢。"},{"who":"A","text":"是大書法家于右任。當年這裡場場爆滿，旁邊的陽翟街也跟著熱鬧，開了理髮廳、撞球室和澡堂。"},{"who":"R","text":"看電影、剪頭髮、打撞球，根本是阿兵哥的休假一條龍！"},{"who":"A","text":"形容得很傳神。後來停止放映，民國108年修復完成，保留了舊座椅風格、綠色地磚，還有當年的塗鴉。"},{"who":"R","text":"連塗鴉都留下來？不怕被說亂畫嗎？"},{"who":"A","text":"那可是時代的簽名，修復團隊特地保留。進去以後找找看，牆上哪一塊是早期留下的塗鴉！"}],"clues":["我的建造經費來自一位臺北市議會議長的勞軍捐款","我門口還留著水泥排隊欄杆和售票口","陽翟老街旁、山頭有于右任紅色題字的戲院"],"quiz":[{"q":"電影院山頭的五個大字是誰題寫的？","options":["蔣經國","王玉白","于右任","胡璉"],"answer":2,"explain":"正面山頭的「金東電影院」由書法家于右任題寫。"},{"q":"金東電影院最初興建的目的是什麼？","options":["推廣國片外銷","慰勞前線官兵","舉辦選舉造勢","作為防空避難所"],"answer":1,"explain":"張祥傳率團勞軍捐款興建，提供軍人休憩場所。"}],"images":[]},{"id":"jinsha-xiyuan","name":"金沙戲院","short":"金沙戲院","category":"歷史建築","level":"","town":"金沙鎮","types":["戲劇院"],"lat":24.488898,"lng":118.413132,"address":"金門縣金沙鎮復興街與中興街交會","announced":"2020-03-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20200409000003","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2026-10-28/e21a295a-f454-462b-963a-ef8f84e5d0a7/00.封面.jpg","year":1964,"yearText":"1964年（民國53年）落成","era":"postwar","themes":["公共建築","市場商業","戰地史蹟"],"yearUnknown":false,"summary":"金門第一座公私合股的電影院","intro":"金沙戲院位於金沙鎮沙美復興街底，民國52年（1963）11月動工，由陸軍部隊協建，民國53年3月20日落成，是可容納六百多席的鋼筋混凝土電影院。籌建時由金沙鎮公所與地方仕紳組成社教推行委員會，向同期興建的新街屋屋主籌資，形成官方16股、民間64股，是金門首間公私合股的電影院。招牌「金沙戲院」由時任縣長王玉白題寫，民國60年代增建中央尖拱、兩側彎弧的山牆。戲院坐落沙美商圈中軸線上，營運至民國78年（1989）停業；二樓放映室還留有兩台少見的碳精棒放映機。縣府完成緊急修繕後，於2026年1月10日重新啟用。","highlights":["中央尖拱、兩側彎弧的山牆與黨徽裝飾","縣長王玉白題寫的「金沙戲院」招牌","二樓放映室兩台碳精棒放映機"],"funFact":"戲院經費來自同期新街屋的屋主入股，官方16股、民間64股，民間出的力氣是官方的4倍。","photoSpot":"站在復興街中央，拍街屋盡頭的戲院山牆","visitMin":20,"openNote":"位於金沙鎮沙美復興街底，2026年1月10日重新啟用；開放時間與活動請以金門縣政府公告為準。鄰近沙美車站，可搭金門縣公車前往後步行。","dialogue":[{"who":"A","text":"阿拉蕾，站在復興街正中間往前看，街道盡頭那座有紅色山牆的建築，就是金沙戲院。"},{"who":"R","text":"它剛好擋在路的尾巴，好像整條街的終點站！"},{"who":"A","text":"就是故意的！民國53年它和兩旁的新街屋一起規劃，蓋在商圈中軸線上，當年是沙美最潮的地標。"},{"who":"R","text":"蓋電影院應該很貴吧，錢從哪裡來？"},{"who":"A","text":"金沙鎮公所找新街屋的屋主一起入股，官方16股、民間64股，是金門第一間公私合股的電影院。"},{"who":"R","text":"原來大家都是股東！那看電影時是不是可以喊這是我家的戲院？"},{"who":"A","text":"哈哈，股東也要買票啦。這裡一直營運到民國78年才停業，二樓還留著兩台老式碳精棒放映機。"},{"who":"R","text":"好想看看那種老機器喔！現在可以進去嗎？"},{"who":"A","text":"整修後在2026年初重新啟用了，開放請看縣府公告。先數數看，招牌上面那面山牆有幾道彎弧吧！"}],"clues":["我是金門第一座由官方和民間合股興建的電影院","我站在一條新街的盡頭，二樓藏著碳精棒放映機","沙美商圈中軸線上、招牌由縣長王玉白題字的戲院"],"quiz":[{"q":"金沙戲院在金門電影院史上有什麼「第一」？","options":["第一座放彩色片","第一座冷氣戲院","第一座軍方獨資","第一座公私合股"],"answer":3,"explain":"官方16股、民間64股，為金門首間公私合股電影院。"},{"q":"二樓放映室保存了哪一種少見的設備？","options":["碳精棒放映機","黑膠唱機","幻燈片投影機","手搖發電機"],"answer":0,"explain":"放映室保有兩台日本品牌的碳精棒放映機。"}],"images":[]},{"id":"lieyu-tiehanbao","name":"鐵漢堡","short":"鐵漢堡","category":"歷史建築","level":"","town":"烈嶼鄉","types":["其他設施"],"lat":24.44691,"lng":118.25519,"address":"金門縣烈嶼鄉黃埔村黃厝海岸","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20041216000018","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-27/820f9933-172a-4a40-beb1-0aecdce67ea2/鐵漢堡封面.jpg","year":1971,"yearText":"1971年（民國60年）","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"花崗石城牆造型入口的小金門海防碉堡","intro":"鐵漢堡位於烈嶼鄉黃埔村黃厝海岸，創建於民國60年（1971），內有門砲三座，與鄰近的將軍堡、勇士堡及雷霆堡連成一氣，共同防衛烈嶼東北角的金烈水道。入口以花崗石砌成城牆造型，正面掛有「鐵漢堡」匾額。碉堡分上下兩層，地上層有砲堡、中山室與彈藥庫，地下層有5座機槍堡、2間寢室、2間彈藥庫、1座五七戰防砲與消防水池，坑道縱橫串連各海防據點，並與勇士堡相連。民國86年（1997）駐軍撤離，移交烈嶼鄉公所整建後，民國99年（2010）與勇士堡一同開放參觀，連通坑道內設有地雷主題展示。","highlights":["花崗石城牆造型入口與「鐵漢堡」匾額","地下層的五七戰防砲與機槍堡","與勇士堡相連、縱橫交錯的地下坑道"],"funFact":"鐵漢堡、勇士堡、將軍堡和雷霆堡當年連成一氣，一起守護小金門東北角的金烈水道。","photoSpot":"在花崗石城牆入口正面取景","visitMin":40,"openNote":"位於烈嶼鄉黃埔村黃厝海岸，依官方資料每日08:00–17:00開放，與勇士堡以坑道相連，可安排一起參觀；坑道內光線較暗，請注意腳步。可經金門大橋開車或騎車前往。","dialogue":[{"who":"R","text":"Allan，鐵漢堡！聽到名字我肚子就餓了，裡面有賣漢堡嗎？"},{"who":"A","text":"沒有漢堡，只有碉堡！不過參觀完，我們可以去吃一碗金門炒泡麵。"},{"who":"R","text":"好吧，那這座碉堡有什麼厲害的地方？"},{"who":"A","text":"它在民國60年建成，入口是花崗石砌的城牆造型，裡面有三座門砲，守著小金門東北角。"},{"who":"R","text":"看起來好像古代城堡喔，只有它自己守嗎？"},{"who":"A","text":"不只，它和將軍堡、勇士堡、雷霆堡連成一氣，一起看守金烈水道。"},{"who":"R","text":"那碉堡的地下也有很多小房間嗎？"},{"who":"A","text":"地下層有5座機槍堡、2間寢室、2間彈藥庫，還有一座五七戰防砲，坑道一路通到勇士堡。"},{"who":"A","text":"當年官兵就在這裡長期戍守。進坑道前，先在城牆入口看看匾額上的鐵字，和課本的寫法一樣嗎？"}],"clues":["我的入口用花崗石砌成城牆的模樣","我的地下層藏著一座五七戰防砲","我的名字聽起來像速食，其實是小金門的碉堡"],"quiz":[{"q":"鐵漢堡創建於哪一年？","options":["民國38年","民國60年","民國47年","民國69年"],"answer":1,"explain":"鐵漢堡創建於民國60年，即1971年。"},{"q":"鐵漢堡地下層設有哪一種火砲？","options":["一五五榴砲","八吋榴砲","高射機砲","五七戰防砲"],"answer":3,"explain":"地下層有5座機槍堡與1座五七戰防砲。"}],"images":[]},{"id":"lieyu-zhonghuaminguowan","name":"烈嶼中華民國萬歲碑","short":"中華民國萬歲碑","category":"歷史建築","level":"","town":"烈嶼鄉","types":["碑碣"],"lat":24.427471,"lng":118.261345,"address":"金門縣烈嶼鄉九宮測段660、725-1地號","announced":"2014-11-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20141128000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-05-19/bbcc917e-0afb-4252-99b3-bd1cb0fa581d/烈嶼中華民國萬歲碑封面.jpg","year":1973,"yearText":"1973年（民國62年）","era":"postwar","themes":["戰地史蹟","牌坊碑碣"],"yearUnknown":false,"summary":"九宮碼頭高地上的戰地政務時期地標","intro":"烈嶼中華民國萬歲碑位於烈嶼鄉九宮碼頭附近的高地，由誠實部隊於民國62年（1973）7月7日興建，是戰地政務時期的軍事紀念碑。碑文原題「蔣總統萬歲」，後改為「中華民國萬歲」。由於地處九宮碼頭上岸後的重要通衢，過去搭船往來烈嶼的人幾乎都會經過，成為出入烈嶼的精神地標，也承載許多軍民的共同記憶。它是當時的宣傳設施，也是認識戰地政務時期的具體見證，2014年登錄為歷史建築。","highlights":["碑文由「蔣總統萬歲」改為「中華民國萬歲」","位於九宮碼頭上岸通衢的地標位置","戰地政務時期軍事紀念碑的樣貌"],"funFact":"這座碑的碑文原本寫的是「蔣總統萬歲」，後來才改成今天看到的「中華民國萬歲」。","photoSpot":"退後幾步，從下方仰拍碑體與天空","visitMin":10,"openNote":"位於烈嶼鄉九宮碼頭附近高地，戶外空間。可經金門大橋開車或騎車前往。","dialogue":[{"who":"A","text":"阿拉蕾，以前從大金門搭船到小金門，在九宮碼頭一上岸，常常第一眼就看到這座碑。"},{"who":"R","text":"好高好顯眼！上面寫著「中華民國萬歲」，是誰蓋的呀？"},{"who":"A","text":"是當時駐守的誠實部隊，在民國62年7月7日興建，是戰地政務時期的軍事紀念碑。"},{"who":"R","text":"碑上的字是一開始就這樣寫的嗎？"},{"who":"A","text":"問得好，冷知識來了！碑文一開始寫的是「蔣總統萬歲」，後來才改成現在這幾個字。"},{"who":"R","text":"換過字！那它算是有改名經驗的地標了。"},{"who":"A","text":"可以這麼說。它是當時的宣傳設施，也是很多官兵和居民往來烈嶼時的共同記憶。"},{"who":"R","text":"現在有金門大橋，開車過來也很方便呢。"},{"who":"A","text":"沒錯。到現場請退後幾步，把整座碑和天空一起拍下來，數數碑上一共有幾個字。"}],"clues":["我的碑文曾經換過內容","我在民國62年7月7日由誠實部隊興建","我站在小金門九宮碼頭附近的高地上"],"quiz":[{"q":"這座碑的碑文原本題的是什麼？","options":["蔣總統萬歲","毋忘在莒","還我河山","反共抗俄"],"answer":0,"explain":"碑文原題「蔣總統萬歲」，後改為「中華民國萬歲」。"},{"q":"這座碑位在哪個碼頭附近？","options":["水頭碼頭","料羅碼頭","九宮碼頭","羅厝漁港"],"answer":2,"explain":"碑體矗立在九宮碼頭附近高地，是出入烈嶼的地標。"}],"images":[]},{"id":"jinsha-haiyinsidaxiongbao","name":"海印寺大雄寶殿","short":"海印寺大雄寶殿","category":"歷史建築","level":"","town":"金沙鎮","types":["寺廟"],"lat":24.46252,"lng":118.41855,"address":"金門縣金沙鎮金沙鎮大山段403、404地號","announced":"2009-06-03","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20090603000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-07-18/4c0dbbad-4f98-4c8b-8bb3-09a742c3f575/01封面.jpg","year":1975,"yearText":"約1970年代（民國60年代）興建，2013年（民國102年）改建","era":"postwar","themes":["宗教信仰"],"yearUnknown":false,"summary":"太武山海印寺後殿，殿下藏著心形安心石","intro":"海印寺大雄寶殿是金沙鎮太武山海印寺的後殿，約民國60年代新建，因供奉佛陀而稱為大雄寶殿，主祀毗盧遮那佛、釋迦佛、盧舍那佛三寶佛。現在看到的是民國102年（2013）改建後的全新樣式，以鋼筋混凝土和木構混合建造，三重簷歇山式筒瓦屋頂，正面立有四根龍柱，木構件大量使用金漆。殿分上下兩層：上層是主殿，下層有「安心石」與「安心石室」。安心石原是建廟前就在廟地的花崗岩巨石，形似心臟；石室則展示歷次整建的建材、明代留下的花崗岩與佛教書畫。它與古蹟海印寺關係密切，因此登錄為歷史建築，維護寺院整體性。","highlights":["殿下形似心臟的花崗岩「安心石」","正面四根龍石柱與三重簷歇山屋頂","安心石室展示的明代花崗岩與整建建材"],"funFact":"安心石是建廟前就躺在廟地裡的天然巨石，相傳摸一摸就能獲得能量，後來乾脆把大殿蓋在它上面。","photoSpot":"在前庭拍三重簷屋頂與四根龍柱","visitMin":30,"openNote":"位於金沙鎮太武山海印寺內，官方資料開放時間為08:00至17:30。需沿太武山步道步行上山，請量力而為並留意現場公告；參拜請保持安靜、尊重寺方規範。","dialogue":[{"who":"A","text":"爬了一段太武山，喘口氣吧！阿拉蕾，我們現在站在海印寺的後殿，大雄寶殿前面。"},{"who":"R","text":"哇，屋頂好幾層，金光閃閃的！Allan，這是很古老的建築嗎？"},{"who":"A","text":"大殿約民國60年代才新建，現在這個樣子是2013年改建的，用了大量金漆，所以特別亮眼。"},{"who":"R","text":"這麼新的建築，為什麼能登錄成歷史建築呢？"},{"who":"A","text":"因為它是古蹟海印寺的一部分，為了保護整座寺院的完整性，就一起登錄了。"},{"who":"R","text":"原來是團體報名！那裡面供奉哪幾位？"},{"who":"A","text":"三寶佛，毗盧遮那佛、釋迦佛和盧舍那佛。殿下面還有一顆像心臟的大石頭，叫安心石。"},{"who":"R","text":"安心石？摸了是不是考試就不會緊張了？"},{"who":"A","text":"傳說是這樣，但讀書還是要靠自己。下樓去找安心石，看看它到底像不像一顆心！"}],"clues":["我的地下室藏著一顆形似心臟的巨石","我在2013年改建成金光閃閃的三重簷大殿","太武山古寺的後殿，供奉三寶佛"],"quiz":[{"q":"大雄寶殿下層那顆巨石叫什麼名字？","options":["安心石","定海石","望夫石","聽濤石"],"answer":0,"explain":"大殿下方的花崗岩巨石稱為安心石，形似心臟。"},{"q":"現在看到的大雄寶殿是哪一年改建完成的樣式？","options":["1949年","1971年","2013年","1992年"],"answer":2,"explain":"目前建築為民國102年（2013）改建後的全新樣式。"}],"images":[]},{"id":"jincheng-chengqudixiakeng","name":"金城城區地下坑道","short":"金城坑道","category":"歷史建築","level":"","town":"金城鎮","types":["其他設施"],"lat":24.433798,"lng":118.319934,"address":"金門縣金城鎮民生路7號2樓坑道分佈從金門高中、國民黨黨部（金門育樂中心）、政府、土地銀行、北嶽廟至金城車站","announced":"2005-12-19","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/historicalBuilding/20051219000006","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-05-07/cf576723-dd54-436c-b416-118a15e723c3/代表圖片-金城城區地下坑道.jpg","year":1978,"yearText":"1978年（民國67年）開工，1979年竣工","era":"postwar","themes":["坑道碉堡","戰地史蹟"],"yearUnknown":false,"summary":"串起後浦市區機關的戰鬥村地下坑道","intro":"金城城區地下坑道位於金城鎮後浦市區，是戰地政務時期「戰鬥村」政策的產物。1968年金門將全縣自然村併編為73個戰鬥村，1976年起選定金城等12個聚落，以既有坑道、碉堡為基礎增建地下坑道，目標是「保存戰力於地下，發揮火力於地上」。金城坑道由陸軍292師、127師協助，1978年3月開工、1979年6月竣工，全長2315公尺，以金門縣政府、金門高中、金城車站三處為據點，串連黨部、司法、金融等機關。2005至2007年修復後，2008年起開放參觀。","highlights":["金城車站二樓入口的坑道主題展示館","寬120公分的鋼筋混凝土主坑道與砲擊音效體驗","金門高中運動場後側的出口休息區與書室"],"funFact":"全長2315公尺中，土質支坑道多已坍塌，2006年修復時回填，現在走的是主坑道。","photoSpot":"主坑道內的模擬構工壁畫前","visitMin":40,"openNote":"位於金城鎮後浦市區，入口在金城車站二樓。官方資料記載每日9:00至22:00，入坑採梯次制，每梯次50人以下，由解說員免費帶領，梯次時間以現場公告為準。可搭金門縣公車到金城車站。","dialogue":[{"who":"A","text":"阿拉蕾，今天我們不逛街，改逛街的地下室，金城鬧區底下藏著一條坑道喔！"},{"who":"R","text":"地下室？Allan你是不是又想躲太陽，找藉口鑽洞？"},{"who":"A","text":"冤枉啊！這是1978年開工、1979年完工的戰鬥村坑道，目標是「保存戰力於地下，發揮火力於地上」。"},{"who":"R","text":"原來是戰地政務時期的防禦工事，它有多長啊？"},{"who":"A","text":"全長2315公尺，串起金門縣政府、金門高中和金城車站三個據點，連黨部、銀行都接得上。"},{"who":"R","text":"哇，在地底下走一圈，不就等於逛完半個金城？"},{"who":"A","text":"差不多！入口在金城車站二樓，有解說員免費帶隊，裡面還有砲擊音效和閃光，模擬夜間砲擊的情境。"},{"who":"R","text":"聽起來有點緊張，不過能體會當年居民躲砲擊的心情。"},{"who":"A","text":"沒錯，出來我再請你喝碗廣東粥壓壓驚。下坑後請找找模擬構工的壁畫，看看當年怎麼挖坑道！"}],"clues":["我在戰地政務時期由陸軍兩個師協助挖成，1979年竣工","我全長2315公尺，串起縣政府、高中與車站三個據點","我的入口在金城車站二樓，有解說員帶你下坑"],"quiz":[{"q":"這條坑道以哪三處為主要據點？","options":["縣政府、金門高中、金城車站","縣政府、莒光樓、金城車站","金門高中、模範街、總兵署","金城車站、水頭碼頭、縣政府"],"answer":0,"explain":"以縣政府、金門高中、金城車站為據點，主坑道貫通三處。"},{"q":"戰鬥村增建地下坑道的目標是？","options":["處處皆戰場，人人皆戰士","軍民一家，共守家園","保存戰力於地下，發揮火力於地上","以地道代替道路通行"],"answer":2,"explain":"戰鬥村坑道的目標是保存戰力於地下，發揮火力於地上。"}],"images":[]},{"id":"jincheng-houpushangxuetang","name":"後浦上學堂陳氏祖塋","short":"上學陳氏祖塋","category":"紀念建築","level":"","town":"金城鎮","types":["墓葬"],"lat":24.43665,"lng":118.32252,"address":"金門縣金城鎮旗牌段251、251-1、251-2地號","announced":"2019-01-14","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20190409000002","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-30/b7a3f643-2633-4492-b775-896c8714cca4/01封面.jpg","year":1370,"yearText":"約元末明初（14世紀，確切年代不詳）","era":"dutch","themes":["墓葬"],"yearUnknown":false,"summary":"後浦上學堂陳氏開基祖墓，牽動「後浦」地名由來","intro":"後浦上學堂陳氏祖塋位於金城鎮旗牌段一帶，是今住埔後的上學堂陳氏開基祖墓。依《上學陳氏世系譜》，始祖陳興仁世襲爵位，元末為避禍棄官遷居金門，初居水浦之濱，堂號「上學」，後族人遷到今後浦一帶。陳氏認為祠堂坐南朝北、浦在堂後，「以浦居後，故名後浦」；不過宋末丘葵詩中已有「後浦莊」，明末許氏族譜也有不同說法，地名由來仍待考證。墓園形制簡樸，由墓碑、墓桌與牛軛形墓岸組成，碑刻「上學陳氏祖塋」六字，2019年登錄為紀念建築。","highlights":["墓碑正面「上學陳氏祖塋」六字","牛軛形墓岸與明顯墓龜的簡樸形制","除碑與墓桌外以灰砂三合土構築"],"funFact":"後浦地名有三種說法：陳氏的「以浦居後」、宋末丘葵詩，以及明末許氏族譜，至今仍待考證。","photoSpot":"在墓前保持距離，拍墓碑與牛軛形墓岸","visitMin":10,"openNote":"位於金城鎮旗牌段一帶，屬宗族祖墓。官方資料未載明開放時間，請在外圍參觀，保持肅靜、尊重祭祀，勿踩踏墓體。","dialogue":[{"who":"A","text":"今天帶你來看一座很低調的墓園，它跟金城舊稱「後浦」的地名，有一段說不完的故事。"},{"who":"R","text":"一座墓跟地名有關？Allan，你是要講鬼故事嗎？我先把耳機音量調小。"},{"who":"A","text":"放心，是歷史故事。陳氏始祖陳興仁在元末為了避禍，棄官搬到金門，堂號叫「上學」。"},{"who":"R","text":"可是這跟後浦這個地名有什麼關係？"},{"who":"A","text":"陳氏說祠堂坐南朝北，水浦在祠堂後面，所以叫後浦。不過宋末詩人丘葵的詩裡就有「後浦莊」了。"},{"who":"R","text":"所以到底是誰說的對？我好想當裁判！"},{"who":"A","text":"官方資料也說還待考證，我們就不亂吹哨了。能確定的是，陳氏開基祖和後浦開發關係很密切。"},{"who":"R","text":"那這座墓長什麼樣子？應該很氣派吧？"},{"who":"A","text":"剛好相反，它很樸素。到現場請安靜地數一數，墓碑上「上學陳氏祖塋」是不是六個字？"}],"clues":["我的主人在元末棄官避禍，遷到金門","族人說「以浦居後」，金城舊名可能跟我們有關","我的碑上刻著六個字，是上學堂陳氏的開基祖墓"],"quiz":[{"q":"上學堂陳氏始祖為什麼遷居金門？","options":["元末為避禍棄官","明初奉命屯田","清初遷界移民","經商落腳定居"],"answer":0,"explain":"族譜記載始祖陳興仁在元末為避禍而棄官遷居金門。"},{"q":"關於「後浦」地名由來，官方說明的態度是？","options":["確定由陳氏而來","確定由許氏而來","確定出自丘葵詩","仍待進一步考證"],"answer":3,"explain":"陳氏說法之外另有丘葵詩與許氏族譜，仍待考證。"}],"images":[]},{"id":"lieyu-donglinfozumiao","name":"烈嶼東林佛祖廟","short":"東林佛祖廟","category":"紀念建築","level":"","town":"烈嶼鄉","types":["寺廟"],"lat":24.42628,"lng":118.25047,"address":"金門縣烈嶼鄉公園測段1160地號","announced":"2019-08-22","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/commemorativeBuilding/20191013000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-30/ad8dcd43-cc5c-4ffc-b14f-a2c1625de543/01封面.jpg","year":1968,"yearText":"1968年（民國57年）重建，前身為民國20年代的水尾宮","era":"postwar","themes":["宗教信仰"],"yearUnknown":false,"summary":"百人移廟保住林天助連環壁畫的小廟","intro":"烈嶼東林佛祖廟位於烈嶼鄉東林聚落，前身是民國20年代（1930年代）所建的東林水尾宮。據田野訪談，村民在東崗海域礁石縫中發現神像，後建小廟奉祀「南海佛祖」。民國38年廟宇被拆作防禦工事，民國57年（1968）村民重建，改名玄女廟，民國86年（1997）正名為佛祖廟。正廳兩側「女兒牆」留有林天助以孫臏鬥龐涓為題的墨繪連環式壁畫，是他現存最早的灰壁連環壁畫作品。為保存壁畫，廟方將建築捐贈縣府，民國106年（2017）11月18日進行金門首宗廟宇遷移，透過百人移廟活動遷到鄰近公有土地，2019年登錄為紀念建築。","highlights":["孫臏鬥龐涓墨繪連環壁畫，依S形逐層閱讀","子午窗上的哼哈二將水墨圖","以蚵殼灰、紅土與紙巾纖維搥打而成的「紙巾壁」"],"funFact":"2017年為了保住壁畫，村民舉辦百人移廟，把整座廟遷到鄰近空地，是金門首宗廟宇遷移。","photoSpot":"在拜亭前拍燕尾脊與八字規山牆","visitMin":20,"openNote":"位於烈嶼鄉東林聚落，依官方資料全天開放；參觀請尊重祭祀，壁畫請勿觸摸或使用閃光燈。可經金門大橋開車或騎車前往。鄰近東林宋代東井。","dialogue":[{"who":"A","text":"阿拉蕾，你搬過家嗎？今天要介紹的這間廟，可是整座搬過家喔。"},{"who":"R","text":"廟也能搬家？是把神像請走，再蓋一間新的吧？"},{"who":"A","text":"不，是連建築一起搬！民國106年11月18日，東林村民發起百人移廟，把整座廟移到旁邊的公有地。"},{"who":"R","text":"一百個人一起出力，好熱血！為什麼要這麼辛苦？"},{"who":"A","text":"因為牆上有林天助畫的墨繪連環壁畫，是他現存最早的灰壁連環畫，拆掉就再也沒有了。"},{"who":"R","text":"那這些壁畫畫的是哪一個故事呀？"},{"who":"A","text":"孫臏鬥龐涓！從龍邊靠子午窗那一格開始看，每層九格，像蛇一樣來回彎著往上讀。"},{"who":"R","text":"好像在玩大富翁，一格一格往前走。那牆壁是用什麼做的？"},{"who":"A","text":"蚵殼灰、紅土加紙巾纖維搥打成的紙巾壁。進廟後試著從第一格開始，跟著來回彎的順序讀完第一層。"}],"clues":["我曾經在百人協力下整座遷到新地點","我的牆上有孫臏鬥龐涓的墨繪連環壁畫","我是小金門東林聚落奉祀南海佛祖的小廟"],"quiz":[{"q":"東林佛祖廟連環壁畫的故事主題是？","options":["薛仁貴東征","孫臏鬥龐涓","楊家將","封神榜"],"answer":1,"explain":"女兒牆墨繪連環壁畫以孫臏鬥龐涓為藍本。"},{"q":"民國106年11月18日，佛祖廟發生什麼事？","options":["改名為玄女廟","重建水尾宮","被拆作防禦工事","百人移廟遷移保存"],"answer":3,"explain":"金門首宗廟宇遷移，以百人移廟保住壁畫。"}],"images":[]},{"id":"jinhu-zhenqionglinjuluo","name":"金湖鎮瓊林聚落建築群","short":"瓊林聚落","category":"聚落建築群","level":"聚落建築群","town":"金湖鎮","types":["其他"],"lat":24.453831,"lng":118.375413,"address":"金門縣金湖鎮瓊林自然村","announced":"2004-12-16","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20121225000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-30/b5c25fbe-51a7-418d-9acf-26321900f9ff/01封面.jpg","year":1200,"yearText":"南宋時期（蔡氏始祖入居平林）","era":"dutch","themes":["聚落地景","宗祠家廟","坑道碉堡"],"yearUnknown":false,"summary":"御賜里名的蔡氏單姓聚落與戰鬥村","intro":"瓊林聚落位於金湖鎮中央蜂腰部北側，舊稱「平林」，因從青山坪（今雙乳山）望去林木森然如蓋而得名。南宋時蔡十七郎入贅平林陳家，成為瓊林蔡氏始祖，聚落逐漸成為蔡氏單姓村。明清兩代出了六進士、六武將、七舉人，明熹宗時因蔡獻臣而御賜里名「瓊林」，但金門人至今仍習慣叫平林。聚落以祠堂群為核心，各房民宅依宗祠同向密集排列，可設隘門防盜，保存約332棟傳統閩南建築。民國65年（1976）完成瓊林戰鬥坑道，有「最堅強戰鬥村」之稱。","highlights":["以宗祠群為核心、同向排列的工整巷弄","連接村中各要處的瓊林戰鬥坑道","聚落中的兩尊風獅爺與保護廟"],"funFact":"皇帝雖然御賜「瓊林」里名，但幾百年來金門民間依然口稱這裡為「平林」。","photoSpot":"在宗祠外埕拍成排燕尾屋脊","visitMin":90,"openNote":"位於金湖鎮瓊林里，聚落巷弄完全開放，可自由步行參觀；多數古厝仍有人居住，請勿擅入、勿打擾住戶，宗祠與坑道開放情形依現場公告。可搭金門縣公車或開車、騎機車前往。","dialogue":[{"who":"R","text":"Allan，這裡巷子好整齊，房子都朝同一個方向，好像排隊升旗的小學生！"},{"who":"A","text":"形容得好。瓊林是蔡氏單姓聚落，各房以祠堂為中心依序蓋房子，所以排得這麼工整。"},{"who":"R","text":"那瓊林這個名字好優雅，是誰取的？"},{"who":"A","text":"這裡原本叫平林，明代出了好多進士、舉人，明熹宗時因為蔡獻臣的緣故，御賜里名瓊林。"},{"who":"R","text":"皇帝取名耶！那大家現在都叫瓊林了吧？"},{"who":"A","text":"妙就妙在金門人幾百年來還是習慣叫平林，就像你改了暱稱，阿嬤還是叫你小名。"},{"who":"R","text":"好有畫面！那房子排這麼密，有什麼用意嗎？"},{"who":"A","text":"冬天能擋東北季風，巷口還能設隘門防海盜。民國65年又完成戰鬥坑道，被稱為最堅強戰鬥村。"},{"who":"R","text":"地上防海盜、地下有坑道！大家走巷子時數數看，能找到幾座燕尾翹起的祠堂？"}],"clues":["皇帝替我改了名字，但大家還是叫我的舊名","我是單姓村，明清兩代出了六進士、六武將、七舉人","我是金門中部的蔡氏聚落，舊名平林"],"quiz":[{"q":"瓊林聚落的舊名是？","options":["青山","平林","陽翟","許坑"],"answer":1,"explain":"瓊林舊稱平林，明熹宗時御賜里名瓊林。"},{"q":"瓊林戰鬥坑道在哪一年完成？","options":["1949年","1958年","1992年","1976年"],"answer":3,"explain":"民國65年（1976）完成瓊林戰鬥坑道。"}],"images":[{"file":"金門金湖鎮瓊林聚落建築群.jpg","thumb":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/%E9%87%91%E9%96%80%E9%87%91%E6%B9%96%E9%8E%AE%E7%93%8A%E6%9E%97%E8%81%9A%E8%90%BD%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg/960px-%E9%87%91%E9%96%80%E9%87%91%E6%B9%96%E9%8E%AE%E7%93%8A%E6%9E%97%E8%81%9A%E8%90%BD%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg","page":"https://commons.wikimedia.org/wiki/File:%E9%87%91%E9%96%80%E9%87%91%E6%B9%96%E9%8E%AE%E7%93%8A%E6%9E%97%E8%81%9A%E8%90%BD%E5%BB%BA%E7%AF%89%E7%BE%A4.jpg","artist":"張雅倫","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0","local":"img/jinhu-zhenqionglinjuluo-0.webp","small":"img/jinhu-zhenqionglinjuluo-0-s.webp"}]},{"id":"jinhu-jinfangbuganxunban","name":"原金防部幹訓班暨士校營區","short":"幹訓班士校營區","category":"聚落建築群","level":"聚落建築群","town":"金湖鎮","types":["其他"],"lat":24.44864,"lng":118.43082,"address":"金門縣金湖鎮士校段407、408、714、715、716、717、717-1、717-2、717-13、718、719、720、721、722、723、724、734、735、740、745、745-1、745-2、745-3、745-4地號（共24筆地號）","announced":"2024-10-18","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/groupsOfBuildings/20250311000004","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2025-08-24/454a92e3-129e-4eb5-8d5a-12f247bb57fb/文康中心.jpg","year":1952,"yearText":"1950年代初期（民國40年代初）","era":"postwar","themes":["戰地史蹟"],"yearUnknown":false,"summary":"金門首批現代化營房，至今仍是訓練基地","intro":"原金防部幹訓班暨士校營區位於金湖鎮太武山南麓、下莊與西洪之間的水源匯集處，又稱太湖一營區。1950年代初期國軍在此興建6幢長條型兵舍，是金門首批現代化軍事營房，落成之初為金南守備部隊示範營區，之後曾由幹訓班、士官學校、精忠衛隊、民防自衛隊、木蘭隊、救國團等使用。民國54年（1965）後擴建陸軍第三士官學校校區，增建現代主義風格的校舍、文康中心與介壽堂。九三砲戰後金門軍事設施多轉入地下，此處因北倚太武山，保留大面積地上營舍，相當少見。","highlights":["1950年代初期興建的6幢長條型兵舍","1965年後現代主義風格的士官學校校舍","門樓、碉堡、指揮所與紀念碑等附屬設施"],"funFact":"營區周邊聚落曾因駐軍眾多，發展出服務軍人的商家而熱鬧一時，後來隨駐軍減少而沒落。","photoSpot":"請勿對營區拍攝，可改到鄰近榕園取景","visitMin":10,"openNote":"位於金湖鎮太武山南麓，營區由陸軍金門防衛司令部管理，仍供常駐部隊與新兵訓練使用，屬軍事管制區，一般民眾無法進入，請勿靠近或拍攝營區。鄰近榕園與八二三戰役紀念園區，可開車或騎機車前往周邊參觀。","dialogue":[{"who":"A","text":"這一站比較特別，我們只能在外圍聊。營區到現在還是部隊訓練新兵的地方，一般民眾不能進去。"},{"who":"R","text":"原來是還在上班的文化資產！Allan，它是什麼時候蓋的？"},{"who":"A","text":"1950年代初期，國軍在太武山南麓蓋了6幢長條型兵舍，是金門第一批現代化軍事營房。"},{"who":"R","text":"第一批耶！那之後住過哪些單位？"},{"who":"A","text":"幹訓班、士官學校、精忠衛隊、民防自衛隊、木蘭隊、救國團都待過，民國54年後還擴建成陸軍第三士官學校。"},{"who":"R","text":"名單好長，這裡根本是金門軍事教育的大學城嘛。"},{"who":"A","text":"很貼切。九三砲戰後金門工事多半轉入地下，這裡靠太武山擋在北邊，才留下大片地上營舍，相當少見。"},{"who":"R","text":"所以它是少數還站在地面上的老營區。那我們要怎麼認識它？"},{"who":"A","text":"請不要對營區拍照。可以到隔壁榕園走走，也可以在網站上看看官方照片，數數有幾幢長條型兵舍。"}],"clues":["我到現在還在訓練新兵，一般人進不來","我曾是陸軍第三士官學校，也住過木蘭隊與救國團","我在太武山南麓，有金門首批現代化軍事營房"],"quiz":[{"q":"這處營區為什麼能保留大面積地上營舍？","options":["地下全是堅硬岩盤","北邊有太武山屏障","位在國家公園核心","從未有部隊進駐"],"answer":1,"explain":"營區北倚太武山為屏障，得以構築地上型營舍群。"},{"q":"民國54年後，營區擴建成什麼學校？","options":["金門高級中學","海軍官校分校","國防醫學院分部","陸軍第三士官學校"],"answer":3,"explain":"1965年後擴建陸軍第三士官學校校區。"}],"images":[]},{"id":"jincheng-yannanshuyuanjitai","name":"燕南書院暨太文巖寺舊址","short":"燕南書院","category":"文化景觀","level":"文化景觀","town":"金城鎮","types":["神話傳說之場域"],"lat":24.406685,"lng":118.31373,"address":"金門縣金城鎮古區268號","announced":"2006-06-13","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20060613000005","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-08-31/5f51f52b-fa0f-4407-a190-9ccd7417cf29/01封面.jpg","year":1150,"yearText":"宋代（相傳朱熹所建，確切年代不詳）","era":"dutch","themes":["教育書院","宗教信仰"],"yearUnknown":false,"summary":"相傳朱熹所建的書院舊址，戰後拆除又重建","intro":"燕南書院暨太文巖寺舊址位於金城鎮古區，在金門千戶所城北門外的太文山，也就是燕南山。清林焜熿《金門志》轉引《滄海瑣錄》記載「燕南書院在浯洲，宋時建」，相傳為朱熹所建，元末明初圮廢。之後在此興建太文巖寺，明末鄉賢盧若騰的詩文曾提及，清同治年間已廢，清光緒5年（1879）重建，俗稱燕南宮，1927年也曾重修。國軍駐金期間寺廟遭拆除，材料移建中山臺，原址改為雷達站。2008至2011年金門縣文化局於原址重建，中殿太文巖寺主祀黑面清水祖師，後殿朱子殿奉祀朱文公、文昌帝君與魁星爺。","highlights":["三進格局：前殿三川門、中殿太文巖寺、後殿朱子殿","中殿主祀黑面清水祖師，後殿奉祀朱文公","屋面雙坡紅瓦翹脊，外牆斗仔砌搭配石砌"],"funFact":"原寺廟在國軍駐金期間被拆，拆下的材料拿去蓋中山臺，原址還一度變成雷達站。","photoSpot":"在前埕拍三川門與紅瓦翹脊屋頂","visitMin":25,"openNote":"位於金城鎮古區、金門城北門外的燕南山。官方資料未載明開放時間，參拜與參觀請以現場公告為準。可搭公車到金門城一帶或騎機車前往。","dialogue":[{"who":"R","text":"Allan，這裡說是朱熹蓋的書院耶！朱熹不是課本裡那位超級大儒嗎？"},{"who":"A","text":"沒錯，不過要加兩個字：「相傳」。清代的金門志引用古書，說燕南書院在浯洲，宋代就建了。"},{"who":"R","text":"那書院現在還在嗎？我想去朱熹的教室坐坐看。"},{"who":"A","text":"書院在元末明初就廢了，後來在這座燕南山蓋了太文巖寺，清光緒5年，也就是1879年還重建過。"},{"who":"R","text":"那為什麼看起來這麼新？是剛刷過油漆嗎？"},{"who":"A","text":"因為國軍駐金期間寺廟被拆，材料拿去蓋中山臺，原址還變成雷達站，原本的構件都不在了。"},{"who":"R","text":"從書院變寺廟又變雷達站，這裡的履歷比我的作業還複雜！"},{"who":"A","text":"所以2008到2011年文化局在原址重建。到後殿朱子殿，請找找除了朱文公，還供奉了哪兩位？"}],"clues":["清代志書說我「宋時建，今莫詳其蹟」","我所在的山後來蓋了寺廟，戰後一度變成雷達站","我在金門城北門外，相傳由朱熹創建"],"quiz":[{"q":"重建後中殿太文巖寺主祀哪一位神明？","options":["關聖帝君","黑面清水祖師","保生大帝","觀世音菩薩"],"answer":1,"explain":"重建後中殿主祀黑面清水祖師，後殿為朱子殿。"},{"q":"太文巖寺原有建築被拆後，原址一度改為什麼？","options":["軍營操場","海防砲臺","雷達站","國民學校"],"answer":2,"explain":"國軍駐金期間寺廟遭拆除，原址改建為雷達站。"}],"images":[]},{"id":"jinsha-taiwushanwenhua","name":"太武山文化景觀","short":"太武山文化景觀","category":"文化景觀","level":"文化景觀","town":"金沙鎮","types":["宗教景觀","軍事設施","歷史文化路徑"],"lat":24.462666,"lng":118.418393,"address":"金門縣金沙鎮大山段370-4（部分）、391、391-1、391-2（部分）、391-4（部分）、392、393、394、394-1 、395、395-1、395-2、396、396-1、396-4（部分）、397、397-1、397-2、397-5、397-6（部分）、397-7、397-8、397-9、397-10、397-12、398、399、400、400-1、401、402、403、404 、404-1、404-2、404-5、404-6地號（共37筆地號）","announced":"2024-01-17","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20240204000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2024-01-25/4c2aacbe-a40e-4f6f-9d26-175cc946d283/太武山文化景觀-以金門海印寺為中心.jpg","year":1600,"yearText":"年代不詳","era":"unknown","themes":["宗教信仰","戰地史蹟","聚落地景"],"yearUnknown":true,"summary":"航海地標、仙山詩意與戰地陣地交織的金門最高峰","intro":"太武山是金門島上的最高峰，2024年登錄為文化景觀，登錄範圍位於金沙鎮大山段。金門位居閩南海域門戶，太武山在大航海時代是船隻進出漳州灣、廈門島的指引地標，是羅盤針經季風貿易年代海洋文化的重要見證。明代後期形成的「太武山十二奇」，是明清文人對山中自然景觀的文學書寫，寄託了仙山想像。山中的石門關與海印寺建築群依山而建，雖歷經改建，仍配置龍樓、鳳閣、蘸月池、拜亭、觀音殿、大雄寶殿與古石室。戰地時期，太武山成為核心陣地，地上與地下的軍事設施融入山勢；岩壁上鑿刻的碑碣精神地標，也成為戰地金門的代表性景觀。","highlights":["石門關一路到海印寺的龍樓、鳳閣與蘸月池","明清文人筆下「太武山十二奇」的奇石山景","融入山勢的戰地設施與岩壁碑碣精神地標"],"funFact":"在靠羅盤針經航海的年代，太武山是船隻進出漳州灣、廈門島時遠遠就能望見的指引地標。","photoSpot":"在石門關前取景，帶入巨石與山勢","visitMin":120,"openNote":"位於金門島中央，登錄範圍在金沙鎮大山段，可循登山步道前往石門關與海印寺。山區仍有軍事設施，請依現場告示行進、勿進入或拍攝管制區域。可開車或騎機車到登山口。","dialogue":[{"who":"R","text":"Allan，你怎麼爬得氣喘吁吁的，我們到底要爬去哪裡？"},{"who":"A","text":"金門的最高峰太武山！以前在海上航行的船，看到這座山，就知道漳州灣和廈門快到了。"},{"who":"R","text":"所以太武山就是古代船員的衛星導航？"},{"who":"A","text":"沒錯，而且是不用充電的那種！明代後期，文人還把山上的奇景寫成「太武山十二奇」。"},{"who":"R","text":"十二奇？聽起來好像武俠小說裡的十二大高手。"},{"who":"A","text":"他們比的是誰更有仙氣啦。往上走會經過石門關，再到海印寺，有龍樓、鳳閣，還有蘸月池。"},{"who":"R","text":"蘸月池，這名字好浪漫！那山裡為什麼也有很多軍事設施？"},{"who":"A","text":"戰地時期太武山是核心陣地，很多工事藏在山裡、和山勢融為一體。爬完山，我請你吃貢糖補體力。"},{"who":"A","text":"邊走邊找，看看哪一塊大石頭最像文人筆下的仙境，拍下來當作你心目中的第十三奇吧！"}],"clues":["明清文人把我山中的奇景寫成「十二奇」","船隻曾靠我辨認漳州灣與廈門島的方向","我是金門島上最高的山，山中有石門關與海印寺"],"quiz":[{"q":"在大航海時代，太武山扮演什麼角色？","options":["海關收稅站","漁獲集散地","航海指引地標","造船工廠"],"answer":2,"explain":"太武山是船隻進出漳州灣、廈門島的指引地標。"},{"q":"明代後期文人描寫太武山奇景的說法是？","options":["太武山八景","太武山十二奇","太武山九曲","太武山十景"],"answer":1,"explain":"明代後期形成「太武山十二奇」的文學書寫。"}],"images":[]},{"id":"lieyu-dadanerdanzhandi","name":"大膽二膽（大擔小擔）戰地文化景觀","short":"大膽二膽","category":"文化景觀","level":"文化景觀","town":"烈嶼鄉","types":["軍事設施"],"lat":24.38946,"lng":118.16331,"address":"金門縣烈嶼鄉大膽段1～59等59筆地號、二擔段1～29等29筆地號","announced":"2013-11-28","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/culturalLandscape/20131128000001","officialImg":"https://data.boch.gov.tw/upload/representImageFile/2022-09-22/cbd36476-9a8d-4413-8b0a-6c65d617879e/01封面.jpg","year":1949,"yearText":"1949年（民國38年）起成為前線島嶼","era":"postwar","themes":["戰地史蹟","心戰設施","坑道碉堡"],"yearUnknown":false,"summary":"扼守金廈海域、坑道與心戰牆遍布的前線島嶼","intro":"大膽、二膽原名「大擔」「小擔」，位於烈嶼西南方海上，大膽面積約0.79平方公里，二膽約0.28平方公里。清代這裡是扼控廈門港航道的海疆要塞，也留下清初的明威將軍墓與北山碑碣群。民國38年（1949）後成為兩岸對峙的前線，民國39年7月26日發生大二膽戰役，298名守軍依託防禦工事擋下登陸進攻；其後歷經九三、八二三、六一七等砲戰，島上承受數以萬計的落彈。島上遍布海岸據點、全島相通的地下坑道、層層阻絕設施，以及播音站、播音牆、心戰牆、空飄站與精神標語等當時的宣傳設施，2013年登錄為文化景觀。","highlights":["面向廈門的大型心戰牆，屬當時的宣傳設施","全島相通的地下坑道與海岸據點","清初明威將軍墓與北山碑碣群"],"funFact":"大膽島的形狀像一隻游水的鵝，北山是鵝頭，中央狹長低窪的沙汕就是鵝的脖子。","photoSpot":"在心戰牆前取景，帶入遼闊海面","visitMin":150,"openNote":"位於烈嶼鄉西南海域，須事先向金門縣政府預約申請，從烈嶼九宮碼頭搭船登島，團進團出；島上部分區域仍屬軍事管制，申請規定以縣府公告為準。可經金門大橋開車或騎車到九宮碼頭。","dialogue":[{"who":"R","text":"Allan，前面那座島就是大膽島嗎？名字聽起來好勇敢！"},{"who":"A","text":"對，它原本叫大擔，旁邊的二膽原名小擔。要事先預約，從九宮碼頭搭船、團進團出才能登島。"},{"who":"R","text":"島的形狀好特別，像一隻在游泳的鵝！"},{"who":"A","text":"眼睛真利！北山是鵝頭，中間狹長的沙汕是脖子。清代這裡就是扼守廈門港航道的要塞。"},{"who":"R","text":"那它後來為什麼被叫做前線中的前線？"},{"who":"A","text":"民國39年7月26日發生大二膽戰役，298名守軍擋下登陸進攻，之後又經歷多次砲戰，承受數以萬計的落彈。"},{"who":"R","text":"在這麼小的島上，那段日子一定很艱難。"},{"who":"A","text":"是的，我們要以莊重的心看待。島上還留著坑道、播音站和面向廈門的心戰牆，都是那段歷史的見證。"},{"who":"A","text":"登島後請跟著導覽、遵守管制規定，到心戰牆前數數看，牆上一共有幾個大字。"}],"clues":["我原名大擔，形狀像一隻游水的鵝","民國39年7月，我的島上發生過一場登陸戰役","我和二膽位在小金門西南，島上有面向廈門的心戰牆"],"quiz":[{"q":"大膽島原本的名稱是什麼？","options":["大擔","大嶝","大金","大坵"],"answer":0,"explain":"大膽、二膽原名「大擔」與「小擔」。"},{"q":"大二膽戰役發生在什麼時候？","options":["民國38年10月","民國43年9月","民國47年8月","民國39年7月"],"answer":3,"explain":"大二膽戰役發生於民國39年7月26日。"}],"images":[]}],"eras":[{"id":"dutch","name":"唐宋到明代","range":"唐代–1645","cityName":"浯洲（浯島）、金門守禦千戶所","title":"從牧馬的浯洲到金門城","summary":"金門古稱浯洲、浯島。據《金門志》記載，唐德宗貞元19年（803年）福建觀察使柳冕奏置萬安牧馬監，牧馬監陳淵率蔡、許、翁、李等十二姓來島上牧馬開墾，後人尊為「開浯恩主」，豐蓮山牧馬侯祠供奉至今。五代已有鹽埕，元代設浯洲鹽場司。相傳南宋朱熹任同安縣主簿時曾到金門講學，創設燕南書院。明洪武20年（1387年）江夏侯周德興在南磐山設金門守禦千戶所、築金門城，取「固若金湯，雄鎮海門」之意，這就是「金門」名稱的由來；次年又築三座石塔指引航行，文臺寶塔是唯一保有明代原貌的一座。嘉靖年間倭寇侵擾，俞大猷守金門時題下「虛江嘯臥」。1633年10月，鄭芝龍在料羅灣擊敗來犯的荷蘭東印度公司艦隊與海盜劉香聯軍。","population":"","events":[{"year":"803","text":"唐貞元19年奏置萬安牧馬監，陳淵率十二姓到浯洲牧馬開墾"},{"year":"元代","text":"設浯洲鹽場司，金沙灣一帶有多處鹽埕"},{"year":"1387","text":"明洪武20年周德興設金門守禦千戶所、築金門城，「金門」得名"},{"year":"1388","text":"築文臺寶塔等三座石塔，作為航行指引"},{"year":"1535–1539","text":"俞大猷守禦金門，在南磐山題「虛江嘯臥」"},{"year":"1560","text":"嘉靖39年倭寇自料羅登岸劫掠，攻陷官澳巡檢司城"},{"year":"1633","text":"10月料羅灣海戰，鄭芝龍擊敗來犯的荷蘭東印度公司艦隊與劉香聯軍"}],"landmarks":[{"name":"豐蓮山牧馬侯祠","lat":24.42061,"lng":118.32238,"note":"金城鎮庵前，供奉唐代牧馬監陳淵，金門最早的恩主公信仰中心","approx":false},{"name":"元太武山築寨砌路摩崖石刻","lat":24.465725,"lng":118.418288,"note":"金沙鎮太武山，元代石刻，見證元代浯洲鹽場","approx":false},{"name":"燕南書院暨太文巖寺舊址","lat":24.40668,"lng":118.31373,"note":"金城鎮金門城北門外太文山，相傳為朱熹所創的書院舊址","approx":false},{"name":"文臺寶塔","lat":24.39877,"lng":118.30601,"note":"金城鎮古城里南磐山，1388年建，臺澎金馬僅存的明代石塔","approx":false},{"name":"虛江嘯臥石刻群","lat":24.39842,"lng":118.30568,"note":"南磐山，俞大猷1535至1539年間駐守金門時所題","approx":false},{"name":"金門城北門外明遺古街","lat":24.40368,"lng":118.3089,"note":"金城鎮古城里，明代中葉金門千戶所城外的商業市街","approx":false},{"name":"官澳（明代官澳巡檢司一帶）","lat":24.51828,"lng":118.41267,"note":"金沙鎮官澳，1560年倭寇攻陷巡檢司城，標示點為官澳龍鳳宮","approx":true},{"name":"料羅灣","lat":24.41268,"lng":118.3835,"note":"金湖鎮南方海灣，1633年料羅灣海戰的海域，標示點為海灣中央","approx":true}],"view":{"lat":24.45,"lng":118.36,"zoom":11},"dialogue":[{"who":"R","text":"Allan，這張古紙地圖上的金門像一個蝴蝶結，一千多年前它叫什麼名字？"},{"who":"A","text":"那時候叫浯洲，也叫浯島。照「金門志」的記載，唐代這裡是朝廷的牧馬場。"},{"who":"R","text":"牧馬？所以金門最早的居民是一群放馬的牛仔嗎？應該叫馬仔吧！"},{"who":"A","text":"803年朝廷設萬安牧馬監，陳淵帶著十二姓來島上牧馬開墾，後人尊稱他「開浯恩主」。"},{"who":"R","text":"那「金門」這個名字是誰取的？聽起來金光閃閃，好像很有錢。"},{"who":"A","text":"1387年江夏侯周德興在這裡設守禦千戶所、築金門城，取「固若金湯，雄鎮海門」的意思。"},{"who":"R","text":"原來不是金子做的門，是防守得很穩的海上大門！"},{"who":"A","text":"答對了。隔年他還蓋了三座石塔當航海指標，文臺寶塔是唯一保有明代原貌的一座。"},{"who":"R","text":"那倭寇來搶劫的時候，是誰在守金門？"},{"who":"A","text":"俞大猷守過這裡，還在南磐山題了「虛江嘯臥」。小任務：到文臺寶塔旁邊，找出這四個大字。"}],"quiz":[{"q":"「金門」這個名稱最早是怎麼來的？","options":["島上曾經盛產黃金","清代設立金門縣時命名","明代設千戶所、築金門城","唐代牧馬場的官方名稱"],"answer":2,"explain":"1387年周德興築城，取「固若金湯，雄鎮海門」之意。"},{"q":"唐代率十二姓到浯洲牧馬開墾、被尊為「開浯恩主」的是誰？","options":["俞大猷","陳淵","周德興","鄭芝龍"],"answer":1,"explain":"牧馬監陳淵，今豐蓮山牧馬侯祠仍供奉他。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"崇禎明荷海戰（料羅灣海戰，中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/崇禎明荷海戰"},{"title":"文臺寶塔（國家文化資產網）","url":"https://nchdb.boch.gov.tw/assets/advanceSearch/monument/19850819000093"},{"title":"豐蓮山牧馬侯祠、虛江嘯臥石刻群、燕南書院暨太文巖寺舊址（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"zheng","name":"明鄭時期","range":"1646–1683","cityName":"金門（浯洲），鄭氏抗清基地","title":"料羅灣揚帆的年代","summary":"1646年鄭成功在烈嶼吳山會集文武群臣，1650年驅逐鄭聯、鄭彩兄弟，以金門、廈門為根據地。1651年魯王朱以海自舟山南下，鄭成功安排他住在金門，古崗東紅山的「漢影雲根」石刻就是魯王所題；1662年12月魯王病逝於金門，今天的魯王墓是1959年發現後重修的。1661年4月22日（農曆三月二十三日），鄭成功率軍在料羅灣集結出發，經澎湖，4月30日進入鹿耳門，展開攻臺之役。1663年11月清軍攻取金門、廈門，次年實施遷界，金門城墮城毀舍、居民遷往內地，所城從此人煙稀少。1674年至1679年鄭氏一度復佔金門，1680年清軍再度攻取，此後金門歸清朝管轄。","population":"","events":[{"year":"1646","text":"鄭成功在烈嶼吳山會集文武群臣"},{"year":"1650","text":"鄭成功驅逐鄭聯、鄭彩兄弟，以金門、廈門為根據地"},{"year":"1651","text":"魯王朱以海南下，鄭成功安排他居住金門"},{"year":"1661","text":"4月22日鄭成功率軍在料羅灣集結，出發攻臺"},{"year":"1662","text":"12月魯王病逝於金門"},{"year":"1663–1664","text":"清軍攻取金門、廈門，隨後實施遷界，金門城墮城遷民"},{"year":"1674–1680","text":"鄭氏一度復佔金門，1680年清軍再度攻取"}],"landmarks":[{"name":"料羅灣","lat":24.41268,"lng":118.3835,"note":"1661年鄭成功率軍在此集結出發攻臺，標示點為海灣中央","approx":true},{"name":"漢影雲根摩崖石刻群","lat":24.39385,"lng":118.31265,"note":"金城鎮古崗東紅山麓，「漢影雲根」四字為魯王所題","approx":false},{"name":"明董颺先墓及周邊摩崖石刻群","lat":24.39245,"lng":118.31315,"note":"金城鎮古崗東紅山，鄭成功夫人董氏之父董颺先流寓金門後葬於此","approx":false},{"name":"金門城北門外明遺古街","lat":24.40368,"lng":118.3089,"note":"清初遷界墮城毀舍，所城人煙稀少，古街隨之沒落","approx":false},{"name":"建功嶼","lat":24.42736,"lng":118.29998,"note":"金城鎮外海小島，今島上立有鄭成功像","approx":false},{"name":"烈嶼（小金門）","lat":24.433,"lng":118.24,"note":"1646年鄭成功在烈嶼吳山會集文武群臣，標示點為烈嶼中部","approx":true}],"view":{"lat":24.42,"lng":118.32,"zoom":12},"dialogue":[{"who":"R","text":"Allan，鄭成功不是在臺南很有名嗎？怎麼金門也到處是他的故事？"},{"who":"A","text":"因為在攻臺以前，鄭成功就是以金門、廈門當根據地，1650年起這兩座島都是他的大本營。"},{"who":"R","text":"那他出發去打臺灣，也是從金門開船的嗎？"},{"who":"A","text":"沒錯。1661年4月22日，大軍在料羅灣集結，第二天到澎湖，4月30日進入鹿耳門。"},{"who":"R","text":"哇，料羅灣根本是那個年代的國際航空站，只是飛機換成帆船！"},{"who":"A","text":"比喻滿分。還有一位貴客住在金門：魯王朱以海，1651年由鄭成功安排來這裡居住。"},{"who":"R","text":"那魯王在金門有留下什麼紀念嗎？"},{"who":"A","text":"古崗東紅山的「漢影雲根」四個字就是他題的。他1662年在金門病逝，墓在1959年才被發現。"},{"who":"R","text":"那鄭成功走了以後，金門的居民過得好嗎？"},{"who":"A","text":"很辛苦。清軍攻取金廈後實施遷界，金門城被拆、居民內遷。小任務：到古崗東紅山找「漢影雲根」石刻。"}],"quiz":[{"q":"1661年鄭成功率軍攻臺，是在金門哪裡集結出發？","options":["古寧頭","料羅灣","水頭","烈嶼九宮"],"answer":1,"explain":"1661年4月22日在料羅灣集結，4月30日進入鹿耳門。"},{"q":"古崗東紅山的「漢影雲根」石刻是誰題的？","options":["俞大猷","鄭成功","董颺先","魯王朱以海"],"answer":3,"explain":"魯王1651年起寄居金門，題下這四個字。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"鄭成功攻臺之役（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/鄭成功攻臺之役"},{"title":"朱以海（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/朱以海"},{"title":"漢影雲根摩崖石刻群、明董颺先墓（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"qing","name":"清代","range":"1683–1911","cityName":"金門（同安縣轄，金門鎮駐地後浦）","title":"總兵署移到後浦","summary":"清初遷界後，金門城人煙稀少、港口也漸漸淤淺。1680年清廷把金門鎮總兵署從金門城移到後浦，總兵陳龍以明代會元許獬的故宅「叢青軒」改建衙署，後浦從此成為金門的政治中心，四月十二迎城隍的習俗也由此而來。1780年（清乾隆45年）縣丞署改建為浯江書院，後設朱子祠。後浦人邱良功1809年與王得祿合力擊敗海上勢力蔡牽，官至浙江水師提督、封三等男；1812年（清嘉慶17年）朝廷為他守節撫孤的母親許氏建「邱良功母節孝坊」。1868年總兵署改為協鎮署。清末不少金門人前往南洋謀生，金門話叫「落番」，事業有成後匯錢回鄉蓋大厝，例如金門城南門陳氏三兄弟在光緒年間興建的三幢宅第，是後來洋樓時代的序曲。","population":"","events":[{"year":"1680","text":"金門鎮總兵署由金門城移駐後浦"},{"year":"1765","text":"水頭黃氏酉堂別業建成"},{"year":"1780","text":"清乾隆45年縣丞署改建為浯江書院"},{"year":"1809","text":"邱良功與王得祿合力擊敗海上勢力蔡牽"},{"year":"1812","text":"清嘉慶17年建邱良功母節孝坊"},{"year":"1840","text":"瓊林蔡氏祠堂創建"},{"year":"1868","text":"清同治7年總兵署改為協鎮署"},{"year":"清光緒年間","text":"落番南洋的陳氏三兄弟匯款回鄉，興建金門城南門宅第"}],"landmarks":[{"name":"清金門鎮總兵署","lat":24.43225,"lng":118.31836,"note":"金城鎮後浦浯江街，1680年移駐，以許獬故宅叢青軒改建","approx":false},{"name":"邱良功母節孝坊","lat":24.43139,"lng":118.31854,"note":"金城鎮後浦東門，1812年建，國定古蹟","approx":false},{"name":"浯江書院（金門朱子祠）","lat":24.4345,"lng":118.31738,"note":"金城鎮北門里，1780年改建為書院，後設朱子祠","approx":false},{"name":"水頭黃氏酉堂別業","lat":24.41064,"lng":118.29814,"note":"金城鎮金水里前水頭，1765年建，國定古蹟","approx":false},{"name":"瓊林蔡氏祠堂","lat":24.45411,"lng":118.37331,"note":"金湖鎮瓊林村，1840年創建，國定古蹟","approx":false},{"name":"邱良功墓園","lat":24.44983,"lng":118.38607,"note":"金湖鎮，清代名將邱良功的墓園","approx":false},{"name":"金門城南門傳統建築群","lat":24.40038,"lng":118.30577,"note":"金城鎮古城里，陳氏三兄弟落番印尼後於光緒年間僑匯興建","approx":false}],"view":{"lat":24.43,"lng":118.34,"zoom":12},"dialogue":[{"who":"R","text":"Allan，明代的熱鬧在金門城，為什麼清代的主角變成後浦？"},{"who":"A","text":"金門城在遷界時被拆，港口又漸漸淤淺。1680年金門鎮總兵署就搬到後浦，也就是今天的金城鎮中心。"},{"who":"R","text":"連衙門都搬家，那城隍爺有沒有一起搬？"},{"who":"A","text":"有喔，城隍爺分火到後浦奉祀，這就是後浦四月十二迎城隍的由來，到現在還很熱鬧。"},{"who":"R","text":"後浦這個地方，還出過什麼大人物嗎？"},{"who":"A","text":"邱良功！1809年他和王得祿合力擊敗海上勢力蔡牽，後來官至浙江水師提督。"},{"who":"R","text":"那他媽媽的節孝坊，是不是就在總兵署附近？"},{"who":"A","text":"就在後浦東門，1812年建。邱媽媽守節撫孤二十八年，這座牌坊是給她的榮譽獎狀。"},{"who":"R","text":"清末好多金門人去南洋打拼，聽說叫「落番」？"},{"who":"A","text":"對，賺了錢就匯回來蓋大厝。小任務：到節孝坊下，數數坊上有幾隻石獅子。"}],"quiz":[{"q":"清代金門鎮總兵署在1680年從金門城移到哪裡？","options":["後浦","沙美","古寧頭","烈嶼"],"answer":0,"explain":"總兵署移駐後浦，後浦成為金門的政治中心。"},{"q":"清末金門人到南洋謀生，金門話稱為什麼？","options":["過臺","走砲","落番","出洋館"],"answer":2,"explain":"落番的僑民常匯錢回鄉興建大厝和洋樓。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"邱良功（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/邱良功"},{"title":"浯江書院（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/浯江書院"},{"title":"清金門鎮總兵署、邱良功母節孝坊、金門城南門傳統建築群（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"japan","name":"民國初年與日軍占領","range":"1912–1945","cityName":"思明縣→金門縣","title":"僑匯蓋起洋樓","summary":"1912年金門與廈門自同安縣分出，成立思明縣；1914年7月金門自思明縣分出設縣，1915年4月正式成立縣治。這段時間落番南洋的金門人匯回大量僑匯，家鄉興起蓋洋樓、辦學校的風潮：陳景蘭從新加坡帶回藍圖，1921年在陳坑完成金門規模最大的洋樓；1924年商會會長傅錫琪等人集資興建紅磚拱廊的模範街；水頭黃輝煌洋樓1931年落成，1932年僑辦的金水國小完工；1933年水頭發生「黑面宙事件」，富商紛紛加建防禦設施，得月樓槍樓因此而生。1937年10月26日日軍登陸，占領金門將近八年，許多僑眷避居南洋，洋樓被徵用為指揮所、醫院。1945年抗戰勝利，金門由中華民國收復。","population":"","events":[{"year":"1912","text":"金門與廈門自同安縣分出，成立思明縣"},{"year":"1914–1915","text":"1914年7月自思明縣分出設金門縣，1915年4月成立縣治"},{"year":"1921","text":"陳坑陳景蘭洋樓完工，為金門規模最大的洋樓"},{"year":"1924","text":"南洋集資興建紅磚拱廊的模範街"},{"year":"1931–1933","text":"水頭黃輝煌洋樓落成，黑面宙事件後加建得月樓"},{"year":"1937","text":"10月26日日軍登陸，金門進入日軍占領時期"},{"year":"1944","text":"盟軍轟炸後浦東門，節孝坊雀替、石獅震落"},{"year":"1945","text":"抗戰勝利，中華民國收復金門"}],"landmarks":[{"name":"模範街","lat":24.43193,"lng":118.31924,"note":"金城鎮後浦，1924年興建，紅磚拱廊「五腳基」店屋","approx":false},{"name":"前水頭得月樓及黃輝煌洋樓","lat":24.40975,"lng":118.29851,"note":"金城鎮水頭聚落，洋樓1931年落成，得月樓為防盜槍樓","approx":false},{"name":"金水國小","lat":24.40929,"lng":118.29796,"note":"水頭聚落，1932年由旅印尼鄉僑集資興建的僑辦小學","approx":false},{"name":"陳景蘭洋樓","lat":24.437288,"lng":118.390161,"note":"金湖鎮成功村（陳坑），1921年完工，日軍占領時期曾被徵用","approx":false},{"name":"後浦頭黃卓彬洋樓","lat":24.4863,"lng":118.41488,"note":"金沙鎮後浦頭，1923年竣工的五腳基洋樓","approx":false},{"name":"古寧頭北山古洋樓","lat":24.47911,"lng":118.31263,"note":"金寧鄉北山，1932至1933年興建，落番菲律賓的李氏兄弟出資","approx":false},{"name":"清金門鎮總兵署（金門縣公署）","lat":24.43225,"lng":118.31836,"note":"1915年設縣後，次年改為金門縣公署","approx":false}],"view":{"lat":24.45,"lng":118.35,"zoom":12},"dialogue":[{"who":"R","text":"Allan，金門那些有拱廊、有天使雕像的洋樓，是什麼時候蓋的？"},{"who":"A","text":"大多是民國初年。落番南洋的金門人賺了錢，把僑匯寄回家鄉，蓋洋樓、蓋學校。"},{"who":"R","text":"所以那時候的金門，是靠南洋寄回來的錢撐起來的囉？"},{"who":"A","text":"可以這麼說。陳景蘭從新加坡帶回藍圖，1921年在陳坑蓋好金門規模最大的洋樓。"},{"who":"R","text":"那模範街呢？紅磚拱廊好像南洋的街道！"},{"who":"A","text":"1924年由商會集資興建，拱廊騎樓叫「五腳基」，下雨天逛街都不用撐傘。"},{"who":"R","text":"水頭的得月樓為什麼長得像一座高高的槍樓？"},{"who":"A","text":"因為1933年水頭發生綁架勒贖的「黑面宙事件」，富商就加蓋防禦設施，自己的家自己顧。"},{"who":"R","text":"後來日軍占領金門，這些洋樓怎麼了？"},{"who":"A","text":"1937年10月日軍登陸，不少洋樓被徵用，僑眷四散。小任務：到陳景蘭洋樓找找門楣上的題字。"}],"quiz":[{"q":"金門在哪一年由日軍登陸占領？","options":["1924年","1931年","1937年","1944年"],"answer":2,"explain":"1937年10月26日日軍登陸，占領到1945年。"},{"q":"水頭得月樓為什麼要蓋成高聳的槍樓？","options":["防範盜匪綁架","觀看潮水","當作燈塔","存放稻穀"],"answer":0,"explain":"1933年黑面宙事件後，富商紛紛加建防禦設施。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"陳景蘭洋樓、模範街、前水頭得月樓及黃輝煌洋樓（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"},{"title":"金水國小、古寧頭北山古洋樓、清金門鎮總兵署（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"early-roc","name":"戰地前線","range":"1945–1958","cityName":"金門縣（1949年起實施軍管）","title":"海峽前線的島嶼","summary":"1949年10月25日凌晨，解放軍在古寧頭一帶登陸，雙方激戰三晝夜，國軍守住金門，雙方傷亡慘重，北山古洋樓牆上至今留有彈痕。戰後金門縣政府建制撤銷，改行軍管，1953年恢復縣政府。1950年7月26日發生大二膽戰役。1952年太武山上刻下「毋忘在莒」，1953年秋莒光樓完工。1954年9月3日九三砲戰爆發，水頭碼頭一帶遭受砲擊；據統計1954年至1957年間的砲戰中，金門居民有63人死亡。此後國軍把陣地逐步地下化，開鑿雙乳山等坑道。1958年8月23日八二三砲戰爆發，第一天就有數萬發砲彈落在金門，軍民傷亡慘重；同年10月起約6,500名居民疏遷臺灣，金門人稱為「走砲」。","population":"1950年約3.8萬人","events":[{"year":"1949","text":"10月25日古寧頭戰役，激戰三晝夜，雙方傷亡慘重"},{"year":"1950","text":"7月26日大二膽戰役"},{"year":"1952","text":"太武山刻「毋忘在莒」"},{"year":"1953","text":"秋季莒光樓完工；縣政府恢復建制"},{"year":"1954","text":"9月3日九三砲戰，此後金門陣地逐步地下化"},{"year":"1958","text":"8月23日八二三砲戰爆發"},{"year":"1958","text":"10月起約6,500名居民疏遷臺灣，稱為「走砲」"}],"landmarks":[{"name":"古寧頭北山古洋樓","lat":24.47911,"lng":118.31263,"note":"金寧鄉北山，古寧頭戰役交戰的重點建築，牆上留有彈痕","approx":false},{"name":"古寧頭戰史館","lat":24.48089,"lng":118.31681,"note":"金寧鄉，展示古寧頭戰役史料","approx":false},{"name":"莒光樓","lat":24.42478,"lng":118.31872,"note":"金城鎮，1953年秋完工，仿宮廷城樓形式","approx":false},{"name":"太武山（毋忘在莒刻石）","lat":24.46267,"lng":118.41839,"note":"1952年刻「毋忘在莒」，標示點為太武山文化景觀代表點","approx":true},{"name":"水頭碼頭","lat":24.41574,"lng":118.28707,"note":"金城鎮，1954年九三砲戰砲擊目標之一","approx":false},{"name":"金門雙乳山坑道","lat":24.446958,"lng":118.357772,"note":"金寧鄉，九三砲戰後陣地地下化興建的坑道","approx":false},{"name":"八二三戰史館","lat":24.44318,"lng":118.43243,"note":"金湖鎮，紀念八二三砲戰","approx":false},{"name":"大膽島","lat":24.38946,"lng":118.16331,"note":"烈嶼鄉，1950年大二膽戰役發生地","approx":false}],"view":{"lat":24.44,"lng":118.3,"zoom":11},"dialogue":[{"who":"R","text":"Allan，這段時期的地圖上，金門到處都標著戰役和坑道，氣氛變得好緊張。"},{"who":"A","text":"是啊，1949年以後金門成了海峽兩岸對峙的最前線，島上的生活完全改變了。"},{"who":"R","text":"課本常提到的古寧頭戰役，是什麼時候發生的？"},{"who":"A","text":"1949年10月25日凌晨，解放軍在古寧頭一帶登陸，雙方激戰三晝夜，傷亡都非常慘重。"},{"who":"R","text":"北山古洋樓牆上的那些洞，就是當年留下的彈痕嗎？"},{"who":"A","text":"對。今天去看，請放輕腳步，那是許多人的生命留下的痕跡。"},{"who":"R","text":"後來還有九三砲戰和八二三砲戰，居民怎麼生活？"},{"who":"A","text":"1954年到1957年的砲戰中，有63位居民罹難。1958年八二三砲戰後，約6500位居民疏遷臺灣。"},{"who":"R","text":"金門人把這段疏遷叫做「走砲」，聽了好心酸。"},{"who":"A","text":"所以後來才挖了這麼多坑道。小任務：到北山古洋樓前，靜靜看一分鐘牆上的彈痕。"}],"quiz":[{"q":"古寧頭戰役發生在哪一年？","options":["1945年","1949年","1954年","1958年"],"answer":1,"explain":"1949年10月25日凌晨開始，激戰三晝夜。"},{"q":"1958年八二三砲戰後，金門居民疏遷臺灣被稱為什麼？","options":["落番","過番","走砲","出外"],"answer":2,"explain":"1958年10月起約6,500名居民疏遷臺灣。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"古寧頭戰役（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/古寧頭戰役"},{"title":"九三砲戰（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/九三砲戰"},{"title":"八二三砲戰（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/八二三砲戰"},{"title":"莒光樓、金門雙乳山坑道、古寧頭北山古洋樓（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"roc60","name":"戰地政務","range":"1956–1992","cityName":"金門縣（戰地政務實驗區）","title":"單打雙不打的日子","summary":"1956年行政院頒布「金門、馬祖地區戰地政務實驗辦法」，金門劃為戰地政務實驗區，由金門防衛司令部設置戰地政務委員會，軍政一體管理。居民的日常生活受到許多管制，包括宵禁、燈火管制、出入境管制與電器用品等限制，國軍也進入各聚落訓練民防自衛隊。1958年10月以後，對岸改採「單打雙不打」，逢單日砲擊、雙日不砲擊，最後一次正式砲擊在1978年12月15日，1979年1月1日宣布停止砲擊。1968年全縣155個自然村併編為73個戰鬥村，1978年至1979年興建金城城區地下坑道。馬山觀測所距對岸約2,300公尺，是心戰喊話據點。模範街一度改稱自強街。1992年11月7日，金門正式結束戰地政務並解除戒嚴。","population":"","events":[{"year":"1956","text":"頒布戰地政務實驗辦法，金門成為戰地政務實驗區"},{"year":"1958","text":"10月起改為「單打雙不打」"},{"year":"1968","text":"全縣155個自然村併編為73個戰鬥村"},{"year":"1971","text":"烈嶼鐵漢堡興建，勇士堡重新整建"},{"year":"1978","text":"12月15日最後一次正式砲擊；金城城區地下坑道動工"},{"year":"1979","text":"1月1日對岸宣布停止砲擊，砲擊歷時21年"},{"year":"1992","text":"11月7日結束戰地政務並解除戒嚴"}],"landmarks":[{"name":"金城城區地下坑道","lat":24.433798,"lng":118.319934,"note":"金城鎮，1978至1979年興建，連接機關與學校的地下系統","approx":false},{"name":"馬山觀測所","lat":24.52789,"lng":118.40842,"note":"金沙鎮官澳，距對岸約2,300公尺的心戰喊話據點","approx":false},{"name":"北山播音牆","lat":24.48892,"lng":118.31311,"note":"金寧鄉古寧頭，對岸喊話用的播音設施","approx":false},{"name":"金湖鎮瓊林聚落（戰鬥村坑道）","lat":24.45383,"lng":118.37541,"note":"1976年起選為戰鬥村之一，地下坑道保存較完整","approx":false},{"name":"陳景蘭洋樓（官兵休假中心）","lat":24.437288,"lng":118.390161,"note":"1959至1990年由金防部作為官兵休假中心","approx":false},{"name":"模範街（曾稱自強街）","lat":24.43193,"lng":118.31924,"note":"戰地政務時期一度改稱自強街","approx":false},{"name":"鐵漢堡","lat":24.44691,"lng":118.25519,"note":"烈嶼鄉黃厝，1971年興建，防衛金烈水道","approx":false}],"view":{"lat":24.46,"lng":118.33,"zoom":11},"dialogue":[{"who":"R","text":"Allan，聽說以前金門晚上要關燈，還不能隨便出門，是真的嗎？"},{"who":"A","text":"真的。1956年起金門實施戰地政務，有宵禁、燈火管制，連出入金門都要申請。"},{"who":"R","text":"那家裡想買收音機或照相機，也要管嗎？"},{"who":"A","text":"要喔，電器用品也在管制清單上。各聚落的居民還要參加民防自衛隊的訓練。"},{"who":"R","text":"「單打雙不打」又是什麼意思？聽起來像打羽毛球的規則。"},{"who":"A","text":"是砲擊的規則：單日砲擊、雙日不打。這樣的日子從1958年一直持續到1978年底。"},{"who":"R","text":"二十年都要看日曆過日子，好難想像！"},{"who":"A","text":"所以戰鬥村都挖了地下坑道，金城城區地下坑道就是1978年到1979年完成的。"},{"who":"R","text":"那這些管制，到什麼時候才結束？"},{"who":"A","text":"1992年11月7日解除戰地政務。小任務：走一段金城地下坑道，數數你經過幾個出入口。"}],"quiz":[{"q":"「單打雙不打」是指什麼？","options":["單日上課雙日放假","單日砲擊、雙日不砲擊","單號車輛限行","單日宵禁、雙日解禁"],"answer":1,"explain":"1958年10月以後改採的砲擊方式，持續到1978年底。"},{"q":"金門在哪一天結束戰地政務？","options":["1979年1月1日","1987年7月15日","1992年11月7日","1995年10月18日"],"answer":2,"explain":"1992年11月7日結束戰地政務並解除戒嚴。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"戰地政務（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/戰地政務"},{"title":"八二三砲戰：單打雙不打（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/八二三砲戰"},{"title":"金門國家公園（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/金門國家公園"},{"title":"金城城區地下坑道、鐵漢堡、陳景蘭洋樓（文化部文化資產局開放資料）","url":"https://nchdb.boch.gov.tw/"}]},{"id":"now","name":"解除戰地政務以後","range":"1992–今","cityName":"金門縣","title":"從戰地到文化島","summary":"1992年11月解除戰地政務後，金門在1993年開放觀光。1995年10月18日金門國家公園管理處成立，是首座位於離島、以歷史文化與戰役紀念為主軸的國家公園，範圍包括太武山、古寧頭、古崗、馬山與烈嶼五區。2001年1月2日小三通啟動，第一班客輪從金門開往廈門，今天的固定航線由水頭碼頭出發。許多軍營、坑道與碉堡陸續轉型：清金門鎮總兵署2004年成為史料館，陳景蘭洋樓2008年修復，烈嶼鐵漢堡、勇士堡2010年對外開放，大膽二膽登錄為文化景觀，大膽島2019年3月1日開放登島。2022年10月30日，全長約5.4公里的金門大橋通車，從金寧鄉開車、騎機車或騎單車就能到烈嶼。","population":"約13.9萬人（2025年戶籍人口）","events":[{"year":"1993","text":"金門開放觀光"},{"year":"1995","text":"10月18日金門國家公園管理處成立"},{"year":"2001","text":"1月2日小三通啟動，第一班客輪從金門開往廈門"},{"year":"2004","text":"清金門鎮總兵署以史料館對外開放"},{"year":"2010","text":"烈嶼鐵漢堡、勇士堡整建後對外開放"},{"year":"2019","text":"3月1日大膽島開放登島觀光"},{"year":"2022","text":"10月30日金門大橋通車，連接金門本島與烈嶼"}],"landmarks":[{"name":"金門國家公園管理處","lat":24.44334,"lng":118.35148,"note":"金寧鄉，1995年成立","approx":false},{"name":"水頭碼頭","lat":24.41574,"lng":118.28707,"note":"金城鎮，小三通往廈門的口岸，也有往烈嶼的交通船","approx":false},{"name":"金門大橋","lat":24.4485,"lng":118.2675,"note":"2022年10月30日通車，全長約5.4公里，標示點為橋身中段","approx":true},{"name":"清金門鎮總兵署","lat":24.43225,"lng":118.31836,"note":"2004年起以史料館開放參觀","approx":false},{"name":"鐵漢堡、勇士堡","lat":24.44691,"lng":118.25519,"note":"烈嶼鄉黃厝，2010年起開放參觀","approx":false},{"name":"大膽島","lat":24.38946,"lng":118.16331,"note":"2019年3月1日開放登島，需事先申請，從烈嶼九宮碼頭搭船","approx":false},{"name":"九宮碼頭","lat":24.42679,"lng":118.26524,"note":"烈嶼鄉，前往大膽島的船從這裡出發","approx":false},{"name":"金門尚義機場","lat":24.42845,"lng":118.3594,"note":"金湖鎮，連接臺灣本島的空中門戶","approx":false}],"view":{"lat":24.43,"lng":118.3,"zoom":11},"dialogue":[{"who":"R","text":"Allan，戰地政務結束以後，金門是不是一下子就變成觀光島了？"},{"who":"A","text":"差不多。1993年開放觀光，1995年金門國家公園成立，守護古厝聚落，也保存戰役史蹟。"},{"who":"R","text":"以前不能靠近的坑道和碉堡，現在都可以進去參觀了嗎？"},{"who":"A","text":"很多都開放了，例如烈嶼的鐵漢堡和勇士堡，2010年整建後就對外開放。"},{"who":"R","text":"那大膽島呢？以前可是前線中的前線耶！"},{"who":"A","text":"2019年3月1日開放登島，要事先向縣政府申請，從烈嶼九宮碼頭搭船，團進團出。"},{"who":"R","text":"還有那座很長的金門大橋，是什麼時候通車的？"},{"who":"A","text":"2022年10月30日，全長約5點4公里，現在騎單車就能到烈嶼，不用再看船班臉色。"},{"who":"R","text":"從砲彈落下的島，變成大家來散步的島，真的很不一樣。"},{"who":"A","text":"沒錯，記得把歷史放在心上。小任務：騎上金門大橋，回頭拍一張金門本島的照片。"}],"quiz":[{"q":"金門國家公園是哪一年成立的？","options":["1992年","1995年","2001年","2019年"],"answer":1,"explain":"1995年10月18日成立管理處，是首座離島國家公園。"},{"q":"金門大橋連接金門本島和哪裡？","options":["大膽島","廈門","烈嶼","烏坵"],"answer":2,"explain":"2022年10月30日通車，全長約5.4公里。"}],"sources":[{"title":"金門縣（中文維基百科，歷史章節）","url":"https://zh.wikipedia.org/zh-tw/金門縣"},{"title":"金門國家公園（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/金門國家公園"},{"title":"小三通（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/小三通"},{"title":"大膽島（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/大膽島"},{"title":"金門大橋（金門縣）（中文維基百科）","url":"https://zh.wikipedia.org/zh-tw/金門大橋_(金門縣)"},{"title":"金門國家公園管理處","url":"https://www.kmnp.gov.tw/"}]}],"qingCity":null,"ich":{"items":[{"id":"ich-f-fengshiye","name":"金門風獅爺","type":"民俗","holder":"金門各聚落居民（官方資料未列保存團體）","registered":"2011-12-15","summary":"鎮風制煞、守護聚落的石獅爺信仰","intro":"金門風獅爺，民間多稱「石獅爺」「石獅公」或「石獅將軍」。官方普查推測，明代中葉以後金門因煮鹽與海盜之患，樹木大量減少，秋冬風沙肆虐，居民便在迎風處與路口設置石獅鎮風制煞，相沿成俗。風獅爺可分兩類：「村落型」立在聚落外圍的迎風路口或寺廟周圍，守護整個聚落，也能制水煞、路箭；「牆垣屋脊型」安在屋脊、牆頭或嵌在壁上，化解巷沖、壁刀等形煞。各地風獅爺有素身也有彩繪，有直立也有蹲踞，大到數公尺、小到雙手可握。俗諺「風頭石獅公，水流水尾塔」，正是先民在強風島嶼上的信仰。金門縣於2011年登錄為民俗。","whereToSee":"金門各鄉鎮聚落都看得到，多立在村落外圍迎風的路口、寺廟旁，或安在屋脊、牆頭上，全年可見。部分風獅爺有居民祭拜、披掛披風，觀賞時請勿攀爬、觸摸或移動供品；位於私人住宅屋頂、牆上的，請在屋外欣賞，勿進入民宅。祭拜日期各聚落不同，請以當地廟方或村里公告為準。","venueId":"","dialogue":[{"who":"R","text":"Allan，金門路口怎麼常站著一尊石頭獅子，還披著紅披風？"},{"who":"A","text":"那是風獅爺！金門人也叫石獅爺、石獅公，專門鎮風制煞，守護整個聚落。"},{"who":"R","text":"鎮風？風又看不見，真的會被石頭獅子嚇跑喔？"},{"who":"A","text":"官方普查推測，明代中葉以後島上樹木大量減少，秋冬風沙很兇，先民就在迎風路口立石獅擋煞。"},{"who":"R","text":"那屋頂上那隻小小的，也是風獅爺嗎？"},{"who":"A","text":"對，那是牆垣屋脊型，專門化解巷子直沖、牆角對著的形煞，路口那種守護整個聚落的叫村落型。"},{"who":"R","text":"有的好威猛，有的好像在傻笑，跟你拍照的表情一模一樣。"},{"who":"A","text":"被你發現了，我們都是鎮店之寶。小任務：找一尊風獅爺，看看牠是站著還是蹲著，面朝哪個方向。"}],"quiz":[{"q":"金門風獅爺依設置位置，可分成哪兩類？","options":["海岸型與山頂型","廟宇型與學校型","村落型與牆垣屋脊型","大型與迷你型"],"answer":2,"explain":"村落型立在聚落外圍迎風路口或寺廟周圍；牆垣屋脊型安在屋脊、牆頭或壁上，化解形煞。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20111215000001"},{"id":"ich-f-pududeng","name":"普渡燈","type":"民俗","holder":"金門各聚落居民（官方資料未列保存團體）","registered":"2011-12-15","summary":"農曆七月家家門口點亮的引路燈","intro":"金門每年農曆七月初一起，家家戶戶在門口懸掛一盞「普渡燈」，為來到陽間的孤魂照明引路，讓祂們順利趕路回家、不在戶外逗留，這項習俗在臺灣本島已很少見。早年燈具內放一個瓷質小圓盤，盛燈油、置燈芯，晚上點燃；近年常見的是綠色鐵框、三面裝玻璃，玻璃畫著花草，寫有「中元普渡」「七月流火」「陰光普照」等字。「七月流火」出自《詩經》，原指夏曆七月黃昏大火星西沉、天氣轉涼，寫在燈上又暗合點火照明，一語雙關。七月間民眾也在家門口、村落要地、山邊與海岸祭拜，十五日舉行中元普渡。金門縣於2011年登錄。","whereToSee":"金門各鄉鎮聚落，每年農曆七月初一至月底，傍晚以後可在住家門口看到點亮的普渡燈。多數位於私人住宅，請在路旁欣賞，勿進入民宅、勿觸碰燈具與供品；拍照時請避開正在祭拜的民眾。","venueId":"","dialogue":[{"who":"R","text":"Allan，農曆七月的金門晚上，怎麼家家門口都掛一盞小燈？"},{"who":"A","text":"這叫普渡燈，金門人從農曆七月初一一路掛到月底，替來到人間的好兄弟照亮回家的路。"},{"who":"R","text":"照路？難道好兄弟們也會在金門的巷子裡迷路？"},{"who":"A","text":"相傳是讓祂們暢行無阻、早點趕路回家，不要在外面逗留，對看不見的朋友也很貼心。"},{"who":"R","text":"燈上寫著「七月流火」，是說七月很熱嗎？"},{"who":"A","text":"剛好相反！這句出自詩經，指大火星往西沉、天氣要轉涼，寫在燈上又剛好是點火照明。"},{"who":"R","text":"原來古人也很會玩雙關，功力跟你差不多，只是比你有學問一點。"},{"who":"A","text":"我的梗比較冷，剛好消暑。小任務：七月夜裡找一盞普渡燈，看看玻璃上寫了哪幾個字。"}],"quiz":[{"q":"金門普渡燈上常寫的「七月流火」，出自哪一部古籍？","options":["論語","詩經","山海經","三字經"],"answer":1,"explain":"「七月流火，九月授衣」出自《詩經‧豳風》，指夏曆七月大火星西沉、天氣轉涼。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20111215000002"},{"id":"ich-f-bobing","name":"中秋搏餅","type":"民俗","holder":"金門各聚落居民（官方資料未列保存團體）","registered":"2011-12-15","summary":"中秋擲骰奪狀元的閩南節慶遊戲","intro":"中秋搏餅是閩南地區特有的中秋民俗，流行於廈門、泉州、漳州與金門一帶。玩法是輪流把6顆骰子擲進大碗，依點數組合得到不同等級的「會餅」。一會月餅仿照科舉頭銜，設狀元1個、對堂2個、三紅4個、四進8個、二舉16個、一秀32個，共63塊。廈門一帶流傳的說法，認為搏餅源於鄭成功部將洪旭為安慰中秋思鄉的士兵而設計；清代詩文已有「拈骰奪取狀元籌」的描寫。這是帶有運氣成分的節慶遊戲，傳統獎品是大小不同的月餅，民間相信搏到好彩頭能預兆來年好運。金門每逢中秋，各聚落與家戶熱鬧舉行，重在親友同樂。金門縣於2011年登錄。","whereToSee":"金門各鄉鎮，每年農曆八月十五日中秋節前後，家戶、社區與團體常自辦搏餅同樂，時間地點每年不同，請留意金門縣政府、各鄉鎮公所與社區公告。搏餅以月餅等獎品同樂，請以娛樂為主、遵守相關法規，不以金錢下注。","venueId":"","dialogue":[{"who":"R","text":"Allan，中秋節金門人圍著大碗叮叮噹噹，在丟什麼呀？"},{"who":"A","text":"這是中秋搏餅！6顆骰子往碗裡一擲，看點數組合換月餅。"},{"who":"R","text":"換月餅？那最大獎是什麼，可以把整盒抱回家嗎？"},{"who":"A","text":"叫狀元。一會月餅有狀元、對堂、三紅、四進、二舉、一秀，共63塊，全照科舉頭銜命名。"},{"who":"R","text":"原來是考科舉的遊戲版！這個玩法是怎麼來的？"},{"who":"A","text":"廈門一帶流傳，是鄭成功部將洪旭為了安慰中秋想家的士兵設計的，清代詩文裡也寫過。"},{"who":"R","text":"那我一定要搏個狀元，保佑我來年考試通通滿分！"},{"who":"A","text":"骰子只看運氣，考試還是要靠自己用功，搏餅重點是全家鄰居熱鬧同樂。小任務：數數看一會月餅裡，哪一種餅最多。"}],"quiz":[{"q":"傳統一會搏餅的月餅，總共有幾塊？","options":["36塊","72塊","81塊","63塊"],"answer":3,"explain":"一會月餅有狀元1、對堂2、三紅4、四進8、二舉16、一秀32，合計63塊。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20111215000003"},{"id":"ich-f-qionglin-jizu","name":"瓊林蔡氏家廟祭祖儀典","type":"民俗","holder":"財團法人金門縣瓊林蔡氏十七郎公裔孫基金會","registered":"2011-12-15","summary":"瓊林蔡氏春秋二祭的大三獻古禮","intro":"金湖鎮瓊林是以蔡氏為主的單姓聚落，蔡氏家廟每年舉行春秋二祭，日期是農曆二月初七與十月初六，分別為五世祖靜山公與祖妣的忌辰，是金門規模最大的家廟祭祖儀典。祭典行大三獻禮，分「頭程」與「二程」：頭程祭始祖十七郎公暨祖妣陳氏，二程祭靜山公與祖妣顏氏。儀式中「奉祖出龕」，把神主請出祖龕依昭穆就位，頭家依輩分服侍。前桌設爵、頭家龜、丁龜，十字形供桌排列五牲與十六小碟。祭畢晚上「食頭」，族人分食祭品，傳統五樣菜寓意「五世其昌」。各項籌備由輪值頭家負責，傳承古禮。金門縣於2011年登錄。","whereToSee":"金湖鎮瓊林村蔡氏家廟，每年農曆二月初七春祭、十月初六秋祭。祭祖是宗族的莊嚴儀典，非族人請在外圍安靜觀禮，勿進入祭祀區、勿干擾通生宣唱與行禮，拍照前請先徵得族人同意；「食頭」是族人宴席，不對外開放。平日家廟開放參觀，時間以現場與宗族公告為準。","venueId":"venue-f-qionglin-citang","dialogue":[{"who":"R","text":"Allan，瓊林蔡氏家廟今天好莊嚴，長輩們都穿長袍耶！"},{"who":"A","text":"今天是春秋二祭之一，農曆二月初七和十月初六，是五世祖靜山公和祖妣的忌辰。"},{"who":"R","text":"他們把祖先牌位一個一個請出來排好，那是在做什麼？"},{"who":"A","text":"這叫奉祖出龕，神主依昭穆就位，頭家按輩分服侍，分頭程、二程兩回行大三獻禮。"},{"who":"R","text":"供桌上一碟一碟好整齊，有柑橘、甘蔗還有蜜餞。"},{"who":"A","text":"那是十六小碟。祭完晚上還有食頭，族人分食祭品，傳統五樣菜代表五世其昌。"},{"who":"R","text":"五世其昌，聽起來比你家的五菜一湯厲害多了，好有學問。"},{"who":"A","text":"我家是五菜一湯我一個人吃光。小任務：平日來參觀時，找找家廟大門上的門神，那可是登錄古物。"}],"quiz":[{"q":"瓊林蔡氏家廟的春秋二祭，在農曆哪兩天舉行？","options":["二月初七與十月初六","正月初一與七月十五","三月二十三與九月初九","四月十二與八月十五"],"answer":0,"explain":"二月初七是五世祖靜山公忌辰，十月初六是靜山祖妣忌辰，春秋二祭都行大三獻禮。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20111215000004"},{"id":"ich-f-houhu-haijiao","name":"后湖卯年海醮","type":"民俗","holder":"社團法人金門縣金寧鄉后湖社區發展協會","registered":"2011-12-15","summary":"每逢卯年舉行、超渡海上孤魂的海醮","intro":"后湖是金寧鄉以許姓為主的血緣聚落，信仰中心昭應廟主祀六姓府王爺、池府王爺與朱府王爺。依官方紀錄，1914年（民國3年）農曆十二月，后湖村民出海捕魚遇上狂風巨浪，有人不幸溺斃；其後昭應廟神明降乩指示，與水府議定孤魂與水族不得侵擾后湖海域的漁民，並約定每逢卯年（兔年）舉行海醮，也就是12年一科，答謝神明護佑並普渡海上孤魂與水族。海醮兼有道教醮儀、普渡與佛教超薦法會，並迎請後浦浯島城隍、靈濟古寺觀世音菩薩與庵前孚濟廟聖侯恩主前來主壇鑑醮，最後焚化大量庫錢，將庫灰裝箱投入海中。金門縣於2011年登錄。","whereToSee":"金寧鄉后湖聚落昭應廟與周邊海岸。每逢卯年（兔年）舉行，12年一科，官方紀錄的醮期約在農曆十月二十二日至二十五日；依此推算，下一個卯年是2035年，實際日期與科儀請以昭應廟及后湖社區公告為準。醮典期間請尊重科儀，勿進入壇場、勿觸碰祭品與紙糊作品，海邊儀式請聽從工作人員引導。","venueId":"venue-f-houhu-zhaoying","dialogue":[{"who":"R","text":"Allan，后湖的海醮要12年才一次？比奧運還難等！"},{"who":"A","text":"沒錯，每逢卯年也就是兔年才舉行，是金門規模最大的海醮。"},{"who":"R","text":"為什麼偏偏是兔年？兔子又不會游泳。"},{"who":"A","text":"官方紀錄說，1914年后湖漁民出海遇上狂風巨浪，有人不幸罹難，後來神明指示每逢卯年做海醮。"},{"who":"R","text":"原來是為了安慰海上的亡魂，也保佑漁民平安。"},{"who":"A","text":"對，有道士醮儀，也有佛教超薦，還迎請城隍爺、觀音菩薩來主壇鑑醮，最後把庫灰裝箱送入海中。"},{"who":"R","text":"好隆重，那下一次海醮是哪一年，我想先記在行事曆上。"},{"who":"A","text":"照12年一科推算是2035年，記得看廟方公告。小任務：到昭應廟前，找找看主祀的是哪幾位王爺。"}],"quiz":[{"q":"后湖海醮多久舉行一次？","options":["每年一次","每3年一次","每逢卯年，12年一科","每60年一次"],"answer":2,"explain":"依官方紀錄，昭應廟神明約定每逢卯年（兔年）舉行海醮，也就是12年一科。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20111215000005"},{"id":"ich-f-yingchenghuang","name":"金門迎城隍","type":"民俗","holder":"金門浯島城隍廟管理委員會","registered":"2011-12-15","summary":"農曆四月十二全島最盛大的城隍遶境","intro":"金門迎城隍源自清康熙19年（1680年）金門鎮總兵署由金門城移駐後浦，城隍爺也從金門城分靈到後浦奉祀，相傳農曆四月十二日就是這個「遷治」紀念日，後浦浯島城隍廟從此每年此日遶境。城隍爵號「顯佑伯」。慶典前有收契子錢、四月初一掛水牌與送佛帖、初九請佛、初九到十一晚上打鑼鼓等程序；十二日正日由後浦東、西、南、北四門境輪值，報馬仔、范謝將軍、神尊蜈蚣座、人力蜈蚣座、粉閣、公揹婆等陣頭出巡，四輦逢廟大力搖擺。金門縣於2011年以「四月十二日迎城隍」登錄，2013年文化部指定為重要民俗。","whereToSee":"金城鎮後浦浯島城隍廟（光前路40號）與後浦城區四境。每年農曆四月十二日遶境，四月初一起陸續有掛水牌、送佛帖等程序，十四日護送各路神明回宮。路線與交通管制每年不同，請以城隍廟及金門縣政府公告為準。依官方紀錄的禁忌，守孝者、進入月內房者與見過入殮遺體者避免參加；遶境時勿穿越神轎與陣頭。附近的清金門鎮總兵署與這段遷治故事相關，可順道參觀。","venueId":"venue-f-wudao-chenghuang","dialogue":[{"who":"R","text":"Allan，後浦街上人山人海，蜈蚣陣一節一節好長喔！"},{"who":"A","text":"今天農曆四月十二，金門迎城隍！這是全島最熱鬧的廟會，2013年文化部指定為重要民俗。"},{"who":"R","text":"為什麼是四月十二？是城隍爺生日嗎？"},{"who":"A","text":"相傳是遷治紀念日。清康熙19年總兵署移到後浦，城隍爺也從金門城分靈過來。"},{"who":"R","text":"原來城隍爺也跟著搬家！那蜈蚣座上坐的是化妝的小朋友嗎？"},{"who":"A","text":"西門境的人力蜈蚣座坐的是裝扮好的孩童，城隍廟的神尊蜈蚣座則坐著各地來的城隍爺。"},{"who":"R","text":"還有四頂輦轎一直狂搖，扛的人跟坐的神明不會暈嗎？"},{"who":"A","text":"那是金門扛輦的特色，我搖兩下就要扶牆了。小任務：遶境時數數看，粉閣的三輪車一共串了幾臺。"}],"quiz":[{"q":"金門迎城隍的遶境正日，是在農曆哪一天？","options":["正月十五","四月十二","三月二十三","七月十五"],"answer":1,"explain":"相傳農曆四月十二日是城隍爺由金門城分靈到後浦的遷治紀念日，每年此日遶境。"},{"q":"金門迎城隍隊伍中，乘坐各地城隍爺神尊的是哪一種陣頭？","options":["布馬陣","粉閣","公揹婆","神尊蜈蚣座"],"answer":3,"explain":"浯島城隍廟的神尊蜈蚣座一節可坐2尊神，以人力肩扛，安奉來參加遶境的各地城隍爺。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20131004000005"},{"id":"ich-f-fengshang-jifeng","name":"峰上天后宮祭蜂鄉俗","type":"民俗","holder":"金門縣金湖鎮峰上天后宮管理委員會","registered":"2018-01-04","summary":"媽祖聖誕時搶紅鴨蛋的祭蜂儀式","intro":"金湖鎮峰上相傳位在「蜂穴」上，村裡多蜂，鄉民認為要祭祀蜂穴之蜂，才能安頓靈穴、安居樂業。每年農曆三月二十三日天上聖母聖誕，峰上天后宮設醮慶祝，全村恭迎媽祖等諸神遶境、食三牲粿後，在廟埕舉行「祭蜂」。供桌旁置兩頂神輦，分別奉蘇府王爺與廣澤尊王，桌上有三牲、紅鴨蛋、紅龜、兵飯與糖粿仔，桌下放臭酸水。鄉老把紅鴨蛋、紅龜與糖粿仔拋進大幅搖擺的神輦之間，另一手潑灑臭酸水，鄉眾冒著被神輦夾擊的危險搶撿紅鴨蛋，象徵蜂群飛舞迎擊。鄉民相信吃到紅鴨蛋有福氣，散落的供品還拿去餵牲畜。金門縣於2018年登錄。","whereToSee":"金湖鎮峰上天后宮廟埕，每年農曆三月二十三日天上聖母聖誕時舉行，時間與流程以廟方公告為準。儀式中神輦大幅擺動、供品與臭酸水四處飛灑，旁觀者請站在安全距離外，勿擋住扛輦鄉眾；搶紅鴨蛋是村民的祈福儀式，請尊重在地習俗。","venueId":"venue-f-fengshang-tianhou","dialogue":[{"who":"R","text":"Allan，峰上天后宮前面，怎麼有人在神輦中間搶蛋？"},{"who":"A","text":"這是祭蜂！峰上相傳位在蜂穴上，媽祖聖誕農曆三月二十三日，全村要祭蜂安頓靈穴。"},{"who":"R","text":"祭蜂跟搶蛋有什麼關係啊？蜜蜂又不會下蛋。"},{"who":"A","text":"鄉老把紅鴨蛋、紅龜、糖粿仔拋進搖擺的神輦之間，還潑臭酸水，大家冒險撿蛋，象徵蜂群迎擊。"},{"who":"R","text":"臭酸水！聽起來好有味道，被潑到怎麼辦？"},{"who":"A","text":"鄉民相信吃到紅鴨蛋有福氣，就算被潑到也一點都不怕。我只怕蛋被搶光，沒得配稀飯。"},{"who":"R","text":"你果然三句不離吃。那掉在地上的紅龜和糖粿仔，就浪費了嗎？"},{"who":"A","text":"撿回去餵牲畜，祈求六畜興旺。小任務：站在安全距離外，看看兩頂神輦各奉的是哪位神明。"}],"quiz":[{"q":"峰上祭蜂儀式中，鄉眾冒險搶撿、相信吃了有福氣的是什麼？","options":["粽子","紅鴨蛋","橘子","月餅"],"answer":1,"explain":"鄉老把紅鴨蛋等供品拋進搖擺的神輦間，鄉眾奮力撿拾，相信吃到紅鴨蛋能帶來福氣與好運。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20180214000001"},{"id":"ich-f-lianan-jinfu","name":"蓮庵金府王爺聖誕建醮遶境","type":"民俗","holder":"護安宮、妙香寺、滄龍宮、保蓮殿、保安殿管理委員會","registered":"2018-01-04","summary":"五呂聚落輪值的金府王爺聯境慶典","intro":"金湖鎮蓮庵里一帶的西村、東村、土樓、庵邊、西埔五個呂氏聚落，合稱「五呂」，各有主祀王爺：西村林府、東村森府、土樓池府、庵邊許府、西埔蘇府王爺。抗戰勝利後，由呂邦楨倡議五呂聯境合祀、聯絡宗誼，以當時香火鼎盛的庵邊金府王爺為共同信仰，成立「五鄉慶神會」，另塑一尊金府王爺金身由五呂輪祀。慶神會訂有「有演戲，才有過鬮」的輪值原則，曾因戰亂與戡亂時期禁演戲劇而中斷，1970年建醮獲准、請到戲班後才恢復年年舉行。現今每年農曆十月十七、十八日金府王爺聖誕，由值年聚落建醮遶境，一年一替、五年一輪。金門縣於2018年登錄。","whereToSee":"金湖鎮蓮庵里五呂聚落（西村、東村、土樓、庵邊、西埔），每年農曆十月十七、十八日舉行，由值年聚落輪流主辦，五年一輪；當年地點與流程請以各宮廟管理委員會公告為準。建醮期間請尊重壇場禁忌，遶境時勿穿越神轎。","venueId":"","dialogue":[{"who":"R","text":"Allan，五呂是指五個姓呂的人嗎？"},{"who":"A","text":"不是喔，是五個呂氏聚落！金湖鎮的西村、東村、土樓、庵邊、西埔，合稱五呂。"},{"who":"R","text":"五個村子各拜各的，還是一起拜同一位神明？"},{"who":"A","text":"各村有自己的王爺，但共同奉祀金府王爺，每年農曆十月十七、十八日聖誕時建醮遶境。"},{"who":"R","text":"五個村子輪流主辦，難道不會為了誰先誰後吵起來嗎？"},{"who":"A","text":"一年一替、五年一輪，規矩很清楚。慶神會還有一句話：有演戲，才有過鬮。"},{"who":"R","text":"沒演戲就不能交接，原來神明跟我一樣愛看戲，還很重視儀式感！"},{"who":"A","text":"曾因戡亂時期禁演戲劇而停辦，直到1970年才恢復年年舉行。小任務：到值年聚落找戲臺，看看今年演哪一齣。"}],"quiz":[{"q":"五呂「五鄉慶神會」的輪值原則是哪一句話？","options":["先到先拜","擲筊決定","抽籤輪值","有演戲，才有過鬮"],"answer":3,"explain":"慶神會明訂「有演戲，才有過鬮」，戡亂時期禁演戲劇時曾因此延宕，1970年後恢復年年舉行。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20180214000002"},{"id":"ich-f-huang-ziyun","name":"金門黃氏恭迎紫雲始祖守恭公巡安","type":"民俗","holder":"社團法人金門縣黃氏宗親會","registered":"2018-01-04","summary":"正月初三黃氏各股恭迎始祖巡安全島","intro":"金門紫雲黃氏宗親每年農曆正月初三恭迎「紫雲始祖守恭公」鑾駕巡安，據官方紀錄始於清宣統元年（1909年），傳承已逾百年。當天上午約9時，宗親在前一年值年村落集合、吃過鹹粥後起駕，巡行各黃氏聚落與街區，最後在當年值年村落的宗祠，由各村宗長焚香安座；農曆二月十八日再於值年宗祠舉行祭祖。金門黃氏原分五股，21世紀初分出第六股，現由西園、汶水（後水頭）、金水（前水頭）、汶浦（後浦頭）四大股，以及英坑、東店、官澳與尚義、后壟兩個合股輪流值年。透過共同始祖的輪祀與巡安，凝聚同姓宗親情誼。金門縣於2018年登錄。","whereToSee":"每年農曆正月初三，巡安隊伍走訪金沙鎮、金湖鎮、金城鎮等地的黃氏聚落與街區，如后水頭、后浦頭、西園、官澳、前水頭等，路線與值年宗祠每年不同，請以社團法人金門縣黃氏宗親會公告為準。巡安與安座屬宗族祭祀，觀禮請保持距離，勿穿越鑾駕隊伍。","venueId":"","dialogue":[{"who":"R","text":"Allan，大年初三一大早，怎麼有一隊人馬在金門到處巡？"},{"who":"A","text":"這是金門黃氏恭迎紫雲始祖守恭公巡安，從清宣統元年，也就是1909年傳到現在。"},{"who":"R","text":"一百多年！那麼大的隊伍，出發前要做什麼準備？"},{"who":"A","text":"宗親在前一年值年的村落集合，先吃一碗鹹粥暖胃，再起駕出發。"},{"who":"R","text":"吃鹹粥再出發，這個我喜歡！最後走到哪裡？"},{"who":"A","text":"一路走遍金沙、金湖、金城的黃氏聚落和街區，最後到今年值年村落的宗祠，由各村宗長焚香安座。"},{"who":"R","text":"感覺像全島的黃家人，一起陪著始祖在金門走春過年。"},{"who":"A","text":"說得好，可惜我不姓黃，只能蹭鹹粥的香味。小任務：到金沙鎮后埔頭黃氏家廟，找找前埕的紫雲屏照壁。"}],"quiz":[{"q":"金門黃氏恭迎紫雲始祖守恭公巡安，在農曆哪一天舉行？","options":["正月初三","正月十五","二月初二","四月十二"],"answer":0,"explain":"每年農曆正月初三上午起駕巡安，農曆二月十八日再於值年宗祠祭祖。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/folklore/20180214000003"},{"id":"ich-a-kuileixi","name":"金門傳統傀儡戲","type":"傳統表演藝術","holder":"金門傀儡戲劇團","registered":"2018-01-04","summary":"泉州系統的懸絲傀儡，兼具酬神與制煞","intro":"傀儡戲是由藝師操弄懸絲戲偶演出的戲劇，閩南語稱「嘉禮戲」，也叫「線戲」。臺灣傀儡戲分南北兩派，北派屬漳州系統、以宜蘭為中心，南派屬泉州系統、以高雄為中心。金門舊屬泉州同安縣，據邱坤良考證，金門傀儡戲與臺灣南派同屬泉州系統，傳入時間可上推至清中葉。演出口白至今仍用泉州古語，音樂屬南管系統，戲偶造型渾圓、偶頭雕工精細。金門傀儡戲分文戲與武戲：文戲用於敬天公與婚俗，戲碼由主人擲筊確認；武戲在宮廟、宗祠奠安時演出，以制煞為主。兼具宗教、娛樂與藝術價值，金門縣於2018年登錄為傳統表演藝術。","whereToSee":"金門傳統傀儡戲多在宮廟、宗祠奠安，或敬天公、婚俗等場合應邀演出，沒有固定的公開演出場所與時間，可留意金門縣文化局與各廟宇活動公告。觀看武戲制煞等儀式性演出時，請遵守廟方與劇團指示，勿任意靠近戲臺或碰觸戲偶。","venueId":"","dialogue":[{"who":"R","text":"Allan，那些戲偶身上綁著好多線，是在演布袋戲嗎？"},{"who":"A","text":"這是傀儡戲，閩南語叫嘉禮戲，藝師站在上方提線操弄，戲偶就會走路、作揖、轉身。"},{"who":"R","text":"好厲害！那金門的傀儡戲，跟臺灣的是同一派嗎？"},{"who":"A","text":"金門舊屬泉州同安，傀儡戲是泉州系統，跟臺灣南派同源，口白還用泉州古語，音樂屬南管。"},{"who":"R","text":"那什麼時候才看得到傀儡戲呢？逢年過節就有嗎？"},{"who":"A","text":"文戲用在敬天公和婚俗，戲碼由主人擲筊確認，武戲在宮廟宗祠奠安時演出，負責制煞。"},{"who":"R","text":"戲偶不只要演戲，還要上班制煞，好辛苦喔。"},{"who":"A","text":"比我辛苦多了，我每天只要專心對付便當。小任務：看演出時數數看，一尊戲偶身上綁了幾條線。"}],"quiz":[{"q":"依官方資料，金門傳統傀儡戲屬於哪一個系統？","options":["漳州系統","泉州系統","潮州系統","福州系統"],"answer":1,"explain":"金門舊屬泉州同安縣，傀儡戲與臺灣南派同屬泉州系統，口白用泉州古語，音樂屬南管系統。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalPerformingart/20191012000001"},{"id":"ich-a-huzhi","name":"金門傳統糊紙","type":"傳統工藝","holder":"翁文標","registered":"2018-01-04","summary":"多用布料、保留古樸手法的金門糊紙","intro":"糊紙是以竹為骨、再糊上紙或布，製作祭儀用品的傳統工藝。官方資料指出，金門糊紙發展始於清代，當時京戲盛行，有人在金門訂製「尪仔齣」作賀禮，例如新官上任送「馬上封侯」、新婚送「狀元夫人」、祝壽送「財子壽」。金門藝師擅長紙偶細工，靈厝裡加上尪仔窗、加官進祿組等戲齣，相當精緻；又因與臺灣本島隔離，臺灣多用紙糊，金門多用布做，保留古樸風味。保存者翁文標9歲隨父親翁享杭學藝，因兩岸隔絕、材料須自製，也練就捏塑尪仔頭土模的功夫，尤擅王船以及醮儀、奠安、喪禮所用的糊紙。金門縣於2018年登錄。","whereToSee":"糊紙作品多為醮典、奠安、喪禮等儀式訂製，儀式後通常焚化，沒有固定展示地點；可在金門各地建醮、王醮、海醮等廟會中看到王船與紙糊作品。觀看時請勿觸碰作品，遇到喪禮儀式請勿圍觀拍攝，尊重家屬與儀式禁忌。","venueId":"","dialogue":[{"who":"R","text":"Allan，醮場旁邊那艘王船好精緻，是紙做的嗎？"},{"who":"A","text":"這是金門傳統糊紙！用竹子紮骨架再糊上去，金門師傅還很愛用布來做。"},{"who":"R","text":"用布？糊紙糊紙，臺灣不是都用紙一層一層來糊嗎？"},{"who":"A","text":"官方資料說臺灣多用紙糊、金門多用布做，因為隔著海，手法反而保留得更古樸。"},{"who":"R","text":"船上的小人偶表情有哭有笑，還有歪嘴斜眼的，好生動耶！"},{"who":"A","text":"保存者翁文標師傅9歲跟父親學藝，當年材料要自己做，連尪仔頭的土模都自己捏。"},{"who":"R","text":"9歲就上工，還要自己捏土模，比我寫功課認真太多了。"},{"who":"A","text":"我9歲只會捏飯糰，而且還捏得歪七扭八的。小任務：在醮場找一件紙糊作品，看看上面有沒有戲曲人物。"}],"quiz":[{"q":"依官方資料，金門糊紙和臺灣本島相比，在材料上有什麼特色？","options":["全部用塑膠","只用木頭雕刻","多用布來做","全部用金屬"],"answer":2,"explain":"官方資料指出臺灣普遍用紙糊，金門多用布做，手法精緻並保留古樸的傳統味道。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/traditionalCraft/20180226000002"},{"id":"ich-a-washi","name":"土水修造技術瓦作（莊西勢）","type":"保存技術","holder":"莊西勢","registered":"2016-04-01","summary":"金門紅瓦屋脊與燕尾的瓦作修造技術","intro":"土水修造技術是古蹟、歷史建築與聚落修復不可缺少的技術，包含整地、砌牆、鋪瓦、抹灰、作脊與灰泥裝飾等。其中瓦作要依建築類型選擇瓦材與鋪法，屋脊曲線與燕尾起翹的比例更是功夫所在。文化部於2016年登錄金門的莊西勢為重要保存技術土水修造技術瓦作的保存者。他師承張振華、王振用等匠師，是小徑工匠群第三代傳承人，精通泥水作，熟悉金門傳統民居與洋樓的寸白規劃與禁忌，講究灰料調配、灰縫細緻。他尤擅作脊鋪瓦，以金門紅土為材，依傳統工法建造屋脊，燕尾曲線與脊頭圓弧比例勻稱，官方資料形容他鋪設的屋頂「保證40年不漏水」。","whereToSee":"保存技術沒有固定展示地點。走訪金門各聚落開放參觀的閩南古厝與宗祠時，可抬頭欣賞紅瓦屋面、燕尾脊與脊頭裝飾，體會瓦作工夫；傳習或觀摩活動請留意文化部文化資產局與金門縣文化局公告。私人古厝請在屋外欣賞。","venueId":"","dialogue":[{"who":"R","text":"Allan，金門古厝的屋脊尾巴翹得好高，像燕子的尾巴！"},{"who":"A","text":"那叫燕尾脊！要翹得漂亮又不漏水，全靠土水修造技術裡的瓦作工夫。"},{"who":"R","text":"鋪瓦片不是一片一片排得整整齊齊就好了嗎？"},{"who":"A","text":"學問可大了，屋脊曲線、分瓦路、出檐都要精算，還要懂傳統尺寸和禁忌。"},{"who":"R","text":"金門有誰是作脊鋪瓦的高手，被國家登錄的嗎？"},{"who":"A","text":"保存者莊西勢師傅，是小徑工匠群第三代，用金門紅土作屋脊，官方說他鋪的屋頂保證40年不漏水。"},{"who":"R","text":"40年不漏水！比你那個天天漏水的保溫杯可靠太多了吧。"},{"who":"A","text":"那是我的保溫杯在練習鎮風制煞。小任務：到古厝聚落抬頭找一座燕尾脊，比比看左右兩端翹得一樣高嗎。"}],"quiz":[{"q":"金門的莊西勢師傅，是哪一項重要保存技術的保存者？","options":["土水修造技術瓦作","大木作技術","剪黏技術","彩繪技術"],"answer":0,"explain":"文化部於2016年登錄莊西勢為土水修造技術瓦作保存者，他尤擅作脊鋪瓦。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ptp/20160808000002"},{"id":"ich-a-damuzuo","name":"大木作技術（翁水千）","type":"保存技術","holder":"翁水千","registered":"2016-04-01","summary":"盤山翁氏派下的金門傳統大木作","intro":"大木作是撐起屋頂的柱樑構造技術。傳統漢式大木作有疊斗式與穿鬥式構架，構件以榫卯接合，從格局規劃、算料、落篙到放樣環環相扣，還要顧及營建禁忌。文化部於2016年登錄金門的翁水千為大木作技術保存者。他師承父親翁金玉，屬盤山翁氏第一代大木匠師翁德定派下，主司大木，兼擅小木門窗與細木家具，熟悉金門傳統建築的大木落篙、尺白寸白吉凶與圖面繪製。民國50到70年代，他主要興建金門傳統民居；70年代後因材料與技術變遷，改以鋼筋混凝土建造宗祠、宮廟；兩岸小三通後傳統材料較易取得，他又以大木匠藝投入金門傳統建築的營造與修復。","whereToSee":"保存技術沒有固定展示地點。參觀金門開放的宗祠、廟宇時，可抬頭看正廳的木構架、斗座與吊筒，認識大木作的結構之美；傳習或展示活動請留意文化部文化資產局與金門縣文化局公告。","venueId":"","dialogue":[{"who":"R","text":"Allan，宗祠的屋頂木頭一層疊一層，沒有釘子也不會垮嗎？"},{"who":"A","text":"這就是大木作！柱和樑用榫卯接合，靠匠師精準計算，穩穩撐起整個屋頂。"},{"who":"R","text":"不用一根釘子，好像在玩超大型的積木，好神奇。"},{"who":"A","text":"積木可沒有禁忌，大木匠師還要懂尺白寸白吉凶，先在丈篙上落篙放樣。"},{"who":"R","text":"那金門有哪位大木師傅，被登錄為保存者呢？"},{"who":"A","text":"翁水千師傅，跟著父親翁金玉學藝，屬盤山翁氏大木匠師派下，連門窗和細木家具都會做。"},{"who":"R","text":"從蓋傳統民居、建宗祠宮廟，一路做到修古蹟，真是全能型師傅。"},{"who":"A","text":"我也很全能，吃飯、睡覺、講冷笑話樣樣拿手。小任務：走進開放的宗祠，抬頭找一找垂在簷下的吊筒。"}],"quiz":[{"q":"傳統漢式大木作的柱樑構件，主要用什麼方式接合？","options":["鐵釘","膠水","螺絲","榫卯"],"answer":3,"explain":"傳統漢式大木作的柱樑構架木料構件，皆以榫卯方式交接，並以丈篙比對尺寸。"}],"url":"https://nchdb.boch.gov.tw/assets/advanceSearch/ptp/20171031000001"}],"venues":[{"id":"venue-f-wudao-chenghuang","name":"金門浯島城隍廟","address":"金門縣金城鎮光前路40號","lat":24.4325803,"lng":118.3161057,"relatedSiteId":"","ichIds":["ich-f-yingchenghuang"],"antiquities":[]},{"id":"venue-f-qionglin-citang","name":"瓊林蔡氏祠堂（蔡氏家廟）","address":"金門縣金湖鎮瓊林村","lat":24.454113984888885,"lng":118.37331306803428,"relatedSiteId":"jinhu-qionglincaishici","ichIds":["ich-f-qionglin-jizu"],"antiquities":[{"name":"蔡氏家廟門神","level":"一般古物","registered":"2018-07-09","note":"蔡氏家廟的清末神荼、鬱壘門神，用鉛丹、砷銅綠等古老顏料，畫風近明清版印年畫"},{"name":"新倉上二房十一世宗祠門神","level":"一般古物","registered":"2018-07-09","note":"在同屬祠堂群的新倉上二房十一世宗祠，有新舊兩層彩繪，戰時塗黑遮蔽反而保住舊彩繪"}]},{"id":"venue-f-houhu-zhaoying","name":"后湖昭應廟","address":"金門縣金寧鄉榜林村后湖聚落","lat":null,"lng":null,"relatedSiteId":"","ichIds":["ich-f-houhu-haijiao"],"antiquities":[]},{"id":"venue-f-fengshang-tianhou","name":"峰上天后宮","address":"金門縣金湖鎮蓮庵里峰上聚落","lat":24.4310629,"lng":118.4613116,"relatedSiteId":"","ichIds":["ich-f-fengshang-jifeng"],"antiquities":[]}]},"ubike":{"meta":{},"stations":[]},"extra":{"intro":[{"who":"A","text":"嗨，我是 Allan Lo！這一站我們飛過臺灣海峽，來到離廈門比離臺灣還近的金門，古時候叫做浯洲。"},{"who":"R","text":"我是阿拉蕾！金門不就是貢糖、麵線、風獅爺，還有好多好多的坑道嗎？"},{"who":"A","text":"沒錯，金門的文化資產超級多，一共251處，國定古蹟就有10處，比很多臺灣本島的縣市還多。"},{"who":"R","text":"哇，那最多的是哪一種？"},{"who":"A","text":"是宅第，有153處！燕尾翹起來的閩南古厝，還有華僑到南洋打拚、寄錢回鄉蓋的洋樓。"},{"who":"R","text":"不過很多古厝現在還有人住，對吧？"},{"who":"A","text":"對，所以要在外面欣賞就好，不要走進去，也不要打擾住戶。"},{"who":"R","text":"金門也有很多戰地史蹟，像古寧頭戰役、八二三砲戰留下的坑道和碉堡。"},{"who":"A","text":"那段歷史有很多人犧牲，參觀時我們放輕腳步，好好聽它的故事。"},{"who":"R","text":"現在還有金門大橋可以開車去小金門！準備好了嗎？從金城出發，我們逛浯島囉！"}],"timeIntro":[{"who":"R","text":"Allan，金門的時光地圖也跟臺灣一樣，有日本統治的時期嗎？"},{"who":"A","text":"沒有喔，金門沒有被日本統治過，倒是1937年到1945年被日軍占領，所以分期跟臺灣不一樣。"},{"who":"A","text":"我們從唐宋、明代的牧馬侯和金門千戶所開始，經過明鄭、清代的落番，再到戰地前線和戰地政務。"},{"who":"R","text":"中研院的老地圖沒有畫到金門，所以前面幾個時期是古紙底圖，最後一個時期可以疊上今天的空照圖！"},{"who":"A","text":"沒錯，點地圖上的星星看當時的地標，再去找找哪些古蹟那時候已經蓋好了。"}],"planIntro":[{"who":"A","text":"金門沒有火車也沒有 YouBike，最方便的是租機車或開車，聚落之間大多十幾分鐘就到。"},{"who":"R","text":"還可以開上金門大橋去烈嶼，也就是小金門！"},{"who":"A","text":"大膽島要先預約、從九宮碼頭搭船；東椗、北椗和烏坵的燈塔一般人不能登島，我會在行程上特別標出來。"},{"who":"R","text":"中午記得留肚子給廣東粥和蚵仔麵線！"}],"gameIntro":[{"who":"R","text":"浯島遊戲場開張！問答王、時光排序、猜猜我是誰、翻翻樂，還有浯島擲骰大冒險！"},{"who":"A","text":"題目從文臺寶塔、邱良功母節孝坊，一路考到水頭的洋樓和太武山，看你能不能全部答對。"},{"who":"R","text":"Allan，這次擲骰子我一定贏你！"},{"who":"A","text":"哈哈，那就從金城車站出發，比比看吧！"}],"reactions":[{"who":"R","text":"答對了！你根本就是浯島文資通！"},{"who":"A","text":"正確答案！給你一個大大的讚。"},{"who":"R","text":"哎呀，答錯了，沒關係，看看解說再挑戰！"},{"who":"A","text":"可惜！差一點點，下次一定行。"},{"who":"R","text":"換我擲骰子囉！看我的！"},{"who":"A","text":"恭喜你贏了！今天的廣東粥算我的！"},{"who":"R","text":"耶！這一局是我贏了，要不要再來一局？"},{"who":"A","text":"平手！你們兩個都是文資高手。"},{"who":"R","text":"時光排序完成！你從明代的文臺寶塔一路排到今天的金門，好厲害！"},{"who":"A","text":"恭喜集到新的護照印章！"},{"who":"R","text":"全部配對成功，記憶力滿分！"},{"who":"A","text":"嗯，這一題我們一起看看解說。"}],"starts":[{"id":"jincheng","name":"金城車站（金城市區）","lat":24.43311,"lng":118.32008},{"id":"airport","name":"金門尚義機場","lat":24.42845,"lng":118.3594},{"id":"shuitou","name":"水頭碼頭","lat":24.41706,"lng":118.28817},{"id":"shanwai","name":"山外車站（金湖鎮）","lat":24.44229,"lng":118.41407},{"id":"jiugong","name":"烈嶼九宮碼頭","lat":24.42679,"lng":118.26524},{"id":"gps","name":"我的目前位置","lat":null,"lng":null},{"id":"pick","name":"在地圖上點選出發點","lat":null,"lng":null}],"plans":{"1":{"name":"一日：金城後浦老街、金門城與水頭聚落","days":[["jincheng-chengqudixiakeng","jincheng-zhuzici","jincheng-houpuwumiao","jincheng-qingjinmenzhenzong","jincheng-mofanjie","jincheng-qiulianggongmujie","jincheng-kuixinglou","jincheng-juguanglou","jincheng-wentaibaota","jincheng-xujiangxiaowoshike","jincheng-qianshuitoudeyue","jincheng-shuitouhuangshiyou"]]},"2":{"name":"二日：金城與水頭 ＋ 古寧頭、瓊林聚落、金沙碧山與山后","days":[["jincheng-chengqudixiakeng","jincheng-zhuzici","jincheng-houpuwumiao","jincheng-qingjinmenzhenzong","jincheng-mofanjie","jincheng-qiulianggongmujie","jincheng-kuixinglou","jincheng-juguanglou","jincheng-wentaibaota","jincheng-xujiangxiaowoshike","jincheng-qianshuitoudeyue","jincheng-shuitouhuangshiyou"],["jinning-guningtoubeishangu","jinning-gulongtoushuiweita","jinning-liguangxiangujuji","jinning-shuangrushankeng","jinhu-qionglinyimensan","jinhu-qionglincaishici","jinhu-zhenqionglinjuluo","jinhu-chenjinglanyanglou","jinsha-ruiyouxuexiao","jinsha-shanhouzhongbao"]]},"3":{"name":"三日：再加上開車過金門大橋，逛烈嶼的碉堡與古厝","days":[["jincheng-chengqudixiakeng","jincheng-zhuzici","jincheng-houpuwumiao","jincheng-qingjinmenzhenzong","jincheng-mofanjie","jincheng-qiulianggongmujie","jincheng-kuixinglou","jincheng-juguanglou","jincheng-wentaibaota","jincheng-xujiangxiaowoshike","jincheng-qianshuitoudeyue","jincheng-shuitouhuangshiyou"],["jinning-guningtoubeishangu","jinning-gulongtoushuiweita","jinning-liguangxiangujuji","jinning-shuangrushankeng","jinhu-qionglinyimensan","jinhu-qionglincaishici","jinhu-zhenqionglinjuluo","jinhu-chenjinglanyanglou","jinsha-ruiyouxuexiao","jinsha-shanhouzhongbao"],["jinning-huxiayangyunpaoji","lieyu-jiangjunbao","lieyu-tiehanbao","lieyu-yongshibao","lieyu-donglinfozumiao","lieyu-donglinsongdaidong","lieyu-qianpubaozhanggong","lieyu-wuxiucaicuo","lieyu-zhonghuaminguowan"]]},"dadan":{"label":"離島：大膽島","name":"離島半日：烈嶼九宮碼頭搭船登大膽島（須事先預約）","days":[["lieyu-zhonghuaminguowan","lieyu-dadanerdanzhandi"]]}},"food":[]}};
